    \caption{\small Joint posterior distributions of the hilltop quintessence parameters \( w_0 \), \( \Omega_{\phi0} \), and the Hubble constant \( H_0 \), with the value of the parameter \( K \) kept fixed. The contours correspond to the 68.27\% (1$\sigma$), 95.45\% (2$\sigma$), and 99.73\% (3$\sigma$) confidence levels for the two-dimensional marginalized posteriors.}
    \label{fig:HilltopCornerFixedK}
\end{figure}

