\section{Theory of Oracle Border Basis Algorithm}\label{sec:theoretical-guarantees-appendix}
In this section we provide proofs to lemmas and theorem in \cref{sec:obba}. We begin by providing the full algorithm. 

\begin{algorithm}[ht]
    \caption{Border Bases Algorithm (\colorbox{peach}{BBA} and \colorbox{skyblue}{OBBA}, simplified)}
    \label{alg:border-basis-full}
    \SetKwInOut{Input}{Input}
    \Input{Polynomial system $F = \{f_1,\ldots,f_r\} \subset \ring$}
    $d \gets \max\{\deg(f_i) \mid 1 \leq i \leq r\}$; $\mathcal{L}_0 \gets \ideal{\mathcal{T}_n^{\leq d}}_k$; $\mathcal{V}_0 \gets \text{VectorSpaceBasis}(\ideal{F}_k)$;

    \While{true}{

        \colorbox{peach}{$\mathcal{C}_i \gets \mathcal{V}_i^+$}\\
        \colorbox{skyblue}{$\mathcal{C}_i \gets \mathrm{Oracle}(\mathcal{L}_i, \mathcal{V}_i)$}\\
        $\mathcal{V}_{i+1} \gets \text{BasisExtension}(\mathcal{V}_i, \mathcal{C}_i, \mathcal{L}_i)$\\
        \If{$\mathcal{V}_{i+1} \neq \mathcal{V}_i$}{
            $\mathcal{V}_i \gets \mathcal{V}_{i+1}$\;
            \textbf{continue}}
        \If{\textbf{not} $\mathrm{BorderBasisCheck}(\mathcal{L}_i, \mathcal{V}_i)$}{
            $d \gets d + 1$\;
            $\mathcal{L}_{i+1} \gets \ideal{\mathcal{T}_n^{\leq d}}_k$ \tcp*{Update universe}
            \textbf{continue}
        }
        \Else{
            $\mathcal{L}_{i+1} \gets \mathcal{L}_i$
        }
        \textbf{break}}
    \KwRet{$\mathrm{FinalReduction}(\mathcal{V}_i, \mathcal{L}_i)$}
    \end{algorithm}

The oracle is restricted to $k$ consecutive non-full expansions, after which we fall back to one final full expansion to ensure correctness. We continue by stating the correctness theorem of the oracle-guided border basis algorithm.\\\\
$\mathrm{BorderBasisCheck}$ corresponds to the check if the border of the tentative order ideal $\mathcal{L}\setminus \lt{\mathcal{V}}$ is already in $\mathcal{L}$.
$\mathrm{FinalReduction}$ refers to the algorithm with the same name introduced by \cite{kehrein2005characterizations}. 

\begin{theorem}\label{thm:obba-correctness}
  The oracle-guided border basis algorithm terminates and the output is a border basis.
\end{theorem}
\begin{proof}
    There are two techniques to ensure the correctness of the oracle-guided border basis algorithm, one of which will be stated here.
    After the oracle has been invoked $k$ times, we make one more full expansion. If $\mathrm{BasisExtension}$ yields additional generators, we fall back to the standard border basis algorithm. This ensures that the output is a border basis, as we could have started with the current iterate $\mathcal{V}$ and applied the standard border basis algorithm. For this we know correctness, so we are done. 
\end{proof}
\subsection{Alternative termination criteria }
To avoid computing a full expansion all the time, we may rely on the \emph{Buchberger Criterion for Border Basis} from \cite{kehrein2006computing}. This criteria is often a lightweight alternative to the full expansion. We can directly apply it to the result of the \cref{alg:border-basis-full}. If it yields that we have a border basis, we are done. If it fails, we go back to the last iterate $\mathbb{V}_i$ and obtain termination by the standard BBA. In practice, we may combine this approach with a learned heuristic, that decides based on the size of the tentative order ideal, whether a full expansion is necessary or we can directly proceed to check for the Buchberger Criterion. 



\begin{lemma}\label{lem:final-stage}
  Assume $\mathcal{L}$ needs no further expansion and let $\mathcal{O}$ be the order ideal of the border basis ultimately produced by \gls{bba} in \cref{alg:border-basis}.  
  If $\lvert\mathcal{L}\rvert - \lvert\mathcal{V}\rvert = \lvert\mathcal{O}\rvert$, then no additional expansions are necessary.
\end{lemma}
\begin{proof}
    Assume towards a contradiction, a further expansion of $\mathcal{V}$ is required for termination. Thus, in particular it holds we can add at least one element to $\mathcal{V}$, increasing its cardinality by $1$. But this contradicts the assumption that $\lvert\mathcal{L}\rvert - \lvert\mathcal{V}\rvert = \lvert\mathcal{O}\rvert$. 
\end{proof}

\paragraph{Setup.}
Throughout this section we analyse the \emph{final stage} of computation, where the
computational universe $\mathcal{L}$ is fixed.  
Let $\mathcal{V}_0$ be the first generator set in this stage and assume the vanilla
BBA terminates after \(T\) full expansions, yielding $\mathcal{V}_T$.

\begin{definition}[Border distance]
  The \emph{border distance} between $\mathcal{L}$ and a generator set
  $\mathcal{V}$ is
  \[
     d(\mathcal{L},\mathcal{V}) \;=\;
     \text{``\# of full BBA expansions still required for }\mathcal{V}\text{''}.
  \]
  Hence $d(\mathcal{L},\mathcal{V}_0)=T$ and $d(\mathcal{L},\mathcal{V}_T)=0$.
\end{definition}

\paragraph{Why conditional error?}
A $k$-order oracle may cut the border distance by any amount $s\le\min\{k,d(\mathcal{L},\mathcal{V}_t)\}$.
If $s<\min\{k,d(\mathcal{L},\mathcal{V}_t)\}$ the oracle has missed \emph{necessary} expansions; if $s=0$ it has made
no progress at all.  To separate progress from waste we introduce a conditional
error measure.

\begin{definition}[Conditional prediction error]
  Invoke a $k$-order oracle at iteration~$t \in \{0, \ldots, T\}$.  
  After its $k$ calls let the border distance have dropped by $s$ and
  denote by $Q$ the \emph{minimal} number of expansions that suffice for an $s$ order oracle to make progress $s$.  The \emph{$s$-progress prediction error} is
  \[
     e(s)\;=\;\sum_{i=0}^{k-1}\bigl|\;\mathrm{Oracle}(\mathcal{L}, \mathcal{V}_{t+i})\bigr|
              \;-\; Q.
  \]
  An oracle is ideal if $s=k$ and $e(s)=0$.
\end{definition}

\paragraph{Benchmark: the optimal expansion sequence.}
Let $\mathrm{OPT}$ be the cost (number of polynomial reductions)
of an \emph{omniscient} algorithm that, starting from
$\mathcal{V}_t$, chooses the minimal set of expansions for $s$ subsequent expansions, decreasing the border distance by $s$.

\begin{theorem}[Cost gap to optimal]\label{thm:obba-runtime}
  Consider a final-stage instance with universe $\mathcal{L}$, order ideal
  $\mathcal{O}$, and invoke a $k$-order oracle at iteration~$t$.
  If it achieves progress $s$ with conditional error $e(s)$, then
  \[
     \mathrm{cost}\bigl(\mathrm{OBBA}\bigr)\;-\;\mathrm{OPT}
     \;\;\le\;\;
     e(s)\;+\;n\,\max\{T-t-s,\,0\}\,\bigl(|\mathcal{L}|-|\mathcal{O}|\bigr).
  \]
\end{theorem}

\begin{proof}
    We analyse the overhead by distinguishing two components: The first component is directly given by the prediction error as it determines how many more expansions were done than necessary. By definition, the prediction error is $e(s) = \sum_{i=0}^{k-1} |\mathrm{Oracle}(\mathcal{L}, \mathcal{V}_{t+i})| - Q$ and $Q$ is the cost of the optimal expansion sequence. This covers cost difference for the first $s$ iterations.
    Suppose now, that $T-t-s = 0$. Then, the algorithm terminates and no further error is incurred. Otherwise, we might incur an additional cost for having expanded the generator set $\mathcal{V}$ too much without reducing the border distance beyond $s$. The size of constructed generator set is at most $|\mathcal{L}|-|\mathcal{O}|$. We know that from the optimal $s$ expansions, after $k-s$ expansions, the set $\mathcal{V}$ has at least the size of the generator set that was predicted by the oracle. Therefore, there are at most $T-t-s$ remaining iterations that incur the higher cost which are upper bounded by $n(|\mathcal{L}|-|\mathcal{O}|)$ times per expansion. 
\end{proof}


\noindent
The overhead therefore consists of two terms: the first grows linearly with the prediction error, while the second reflects a hidden cost for making only progress $s$. Specifically, if the oracle expands the generator set $\mathcal{V}$ too much without reducing the border distance beyond $s$, we incur additional cost in the following $T-t-s$ iterations. This theorem is practically relevant, as it further justifies the use of the $k$-order oracle in the final stage of computation. Being conservative with the use of the oracle (i.e. such that $T$ is smaller than $k$), avoids the worst case additional cost. 

\section{Border basis sampling}\label{sec:border-basis-sampling-app}

\subsection{Order ideal sampling}\label{sec:order-ideal-sampling}
We introduced the overview of order ideal sampling in \cref{sec:border-basis-sampling}. 
This section presents the formal algorithm of the order ideal sampling given . The extension to general $n$-dimensional case is based on the same idea, but it requires a more careful formalization than one may expect. 

Recall our idea. A finite set of terms $\cO$ is called an order ideal if for any $t\in\cO$, its divisors are also all included in $\cO$. Importantly, for any terms $t_1, t_2 \in \cT_n$, the term set $\cO_{t_i} := \{\text{all the divisors of }t_i\}$ is an order ideal for each $i$, and their union $\cO_{t_1, t_2} = \cO_{t_1}\cup\cO_{t_2}$ is also an order ideal. We sample order ideals based on this observation. During the iterative process, we maintain a list $Q$ of \textit{cells}. At each iteration, we pop out a cell $C$ from $Q$, and split it to generate new cells. The cells with sufficient size are appended to $Q$, and this process iterates until $Q$ becomes empty. 

We now formalize this idea. From now on, we work on the exponent vectors of terms. We denote a vector $\bm{v}\in\bN^n$ with a replacement of the $i$-th entry with a scalar $p\in\bN$ by $\bm{v}^{[i\leftarrow p]}$.  A cell is a tuple of $n$ segments and an intersecting point $p\in\bN^n$.
\begin{definition}
    Let $\bm{a}, \bm{b} \in \bN^n$. The following set is called the \emph{segment} of them.
    \begin{align}
    \Delta(\bm{a}, \bm{b}) &= \qty{ \bm{r} := (r_1, \ldots, r_n)^{\top} \in \bN^n \mid \min(a_i, b_i) \le r_i \le \max(a_i, b_i),\ i = 1,\ldots, n }.
    \end{align}
    The maximum point of the segment is defined by $\overline{\Delta(\bm{a}, \bm{b})} := \qty(\max(a_1, b_1), \ldots, \max(a_n, b_n))^{\top}$, and the minimum point $\underline{\Delta(\bm{a}, \bm{b})}$ is defined similarly.
\end{definition}

\begin{definition}
    Let $\Delta_1, \ldots, \Delta_n$ be some segments such that $\underline{\Delta_1}=\cdots = \underline{\Delta_n} = \bm{l}$. 
    The \emph{cell} is a tuple $C = (\{\Delta_i\}_{i=1}^n, \bm{l})$, and $\bm{l}$ is called the \emph{intersecting point}. Further,  the \emph{maximum point} of the cell is $\bm{u} = (u_1,\ldots, u_n)^{\top} \in \bN^n$, where $u_i = \min(\overline{\Delta_1}_i, \ldots, \overline{\Delta_{i-1}}_i, \overline{\Delta_{i+1}}_i, \ldots \overline{\Delta_n}_i
)$ for $i=1,\ldots, n$. The cell is called \emph{valid} if $\bm{l}$ and $\bm{u}$ has at least two different entries, and $\max_{i\in \{1,\ldots, n\}} u_i - l_i \ge 2$.
\end{definition}

Let $\bm{d} = (d_1,\ldots, d_n)^{\top} \in \bN^n$ be the vector of the maximum degree of variables. The initial cell is defined by $C_0 = (\{\Delta(\bm{0}, d_i\bm{e}_i)\}_{i=1}^n, \bm{0})$, and let $Q = [C_0], R = [\ ]$ be lists. Then, we repeat the following until $Q$ becomes empty or the number of iterations reaches the predesignated limit (if any). 
\begin{enumerate}
    \item Select a cell $C = \qty(\{\Delta_i\}_{i=1}^n, \bm{l}) \in Q$ and remove it from the list.
    \item Sample a vector $\bm{p} = (p_1,\ldots,p_n)^{\top} \in \bN^n$ with $p_i \in [l_i, u_i]$ for $i=1,\ldots, n$.
    \item Append a tuple $(\bm{l}, \bm{p})$ to $R$.
    \item For $i=1,\ldots, n$, obtain a new cell 
    $C_i^{\mathrm{new}} = \qty(\qty{\Delta_{j}^{\text{new}}}_{j=1}^n, \bm{l}^{[i \leftarrow p_i ]})$, where $\Delta_{j}^{\text{new}} = \Delta\qty(\underline{\Delta}_j^{[j\leftarrow p_j]}, \overline{\Delta}_j)$ for $j\ne i$ and otherwise $\Delta_{j}^{\text{new}} = \Delta\qty(\bm{l}, \bm{p})$. Append $C_i^{\mathrm{new}}$ to $Q$ if it is a valid cell. 
\end{enumerate}
    We then have an order ideal
    \begin{align}\label{eq:order-ideal-retrieval-final-step}
        \cO = \qty{ x^{\bm{a}} \mid \bm{a} \in \bigcup_{(\bm{l}, \bm{p}) \in R}\bigtimes_{i=1}^n [l_i, p_i]}.
    \end{align}

\begin{theorem}
    The order ideal sampling algorithm terminates within a finite number of steps.
\end{theorem}
\begin{proof}\textbf{Termination.}
We prove that the order ideal sampling algorithm terminates after a finite number of iterations. 

Let $C = (\{\Delta_i\}_{i=1}^n, \bm{l})$ be a cell, and denote its maximum point as $\bm{u} = (u_1, \ldots, u_n)$. In each iteration, the algorithm pops one such cell from the queue $Q$, samples a point $\bm{p} \in \bigtimes_{i=1}^n [l_i, u_i]$, and generates at most $n$ new valid cells $C_1^{\mathrm{new}}, \ldots, C_n^{\mathrm{new}}$. 

\textbf{Case 1:} $\bm{p} \neq \bm{l}$. For any $i$, the new cell $C_{i}^{\text{new}}$ contains at least one segment that is strictly smaller than the corresponding one in $C$. In particular, its $i$-th segment is $\Delta_i^{\text{new}} = \Delta(\bm{l}, \bm{p})$, which has length zero in coordinate $j$ if $p_j = l_j$, and is strictly shorter otherwise. Therefore, the total number of exponent vectors in $C_i^{\text{new}}$ is strictly less than that in $C$.

\textbf{Case 2:} $\bm{p} = \bm{l}$. For any $i$, the new cell $C_{i}^{\text{new}}$ becomes invalid. Indeed, let $\bm{u}' = (u'_{1}, \ldots, u'_n)$ be its maximum point. Since $\bar{\Delta_i^{\text{new}}} = \bm{l}$ by construction, and for all $k \ne i$ the $k$-th segment has lower and upper bounds both equal to $l_k$, we have $u'_{k} = l'_{k}$ for all $k$. This violates the validity condition, which requires that $\bm{l} \ne \bm{u}$ and $\max_i (u_i - l_i) \ge 2$.

Therefore, in either case, the number of valid cells does not increase: Case 1 generates strictly smaller valid cells, and Case 2 generates no valid cells. Moreover, since the exponent space $[0, d_1] \times \cdots \times [0, d_n]$ is finite, and each valid cell corresponds to a distinct subregion defined by its segments, the total number of distinct valid cells is finite.

Hence, the queue $Q$ becomes empty after finitely many iterations, and the algorithm terminates.


\end{proof}












