\subsection{Border basis construction from order ideals: Proof of Theorem~\ref{thm:border-basis-sampling}}\label{sec:border-basis-construction-proof}

\begin{definition}
Given a set of points $P = \{\bm{p}_1,\ldots,\bm{p}_{\nu}\} \subset K^n$, with gentle abuse of notation, the \emph{evaluation vector} of a polynomial $h\in\ring $ is defined by
\begin{align*}
h(X) & =\mqty(h(\bm{p}_{1}) & \cdots & h(\bm{p}_{\nu}))^{\top}\in K^{\nu}.
\end{align*}
For a set of polynomials $\cH=\qty{ h_{1},\ldots,h_{\mu}} \subset\ring$, 
the \emph{evaluation matrix} is defined as 
\begin{align*}
	\cH(P) & = \mqty(h_{1}(P) & \cdots & h_{\mu}(P))\in K^{\nu\times \mu}. 
\end{align*}
\end{definition}

The proof of Theorem~\ref{thm:border-basis-sampling} immediately follows from the following lemma. 
\begin{lemma}\label{lemma:vanishing-ideal-border-basis}
    Let $\cO = \{\os\} \subset \cT_n$ and $G \subset \ring $ be an order ideal and its $\cO$-border prebasis, respectively. Let $P \subset K^n$ be a set of $s$ points. If the following holds, 
    \begin{enumerate}
        \item $\ideal{o_1(P), \ldots, o_\nu(P)}_k = K^\nu$. 
        \item $G \subset \cI(P)$.
    \end{enumerate}
    then, $G$ is the $\cO$-border basis of the vanishing ideal $\cI(P)$.
\end{lemma}
\begin{proof}
    We first show that $G$ is the $\cO$-border basis of $\ideal{G}$. The set $G$ is a border prebasis and (obviously) generates $\ideal{G}$, so we only need to show that $\ring = \ideal{G} \oplus \ideal{\cO}_k$ holds. The border basis division algorithm~\cite{kehrein2005characterizations} allows us to represent any polynomial $f \in \ring$ as $f = g + h$ with some $g \in \ideal{G}$ and $h \in \ideal{\cO}_k$, which implies $\ring = \ideal{G} \cup \ideal{\cO}$. Note that this algorithm only requires $G$ to be a border prebasis (not necessarily a border basis).
    From the first assumption, $o_1(P), \ldots, o_\nu(P)$ form a basis of $K^\nu$, and thus, $h \in \ideal{\cO}_k$ has $h(P) = \bm{0}$ only when $h = 0$. Noting that $\forall g \in \ideal{G}, g(P) = \bm{0}$ from the second assumption, we have $\ideal{G} \cap \ideal{\cO}_k = \{0\}$. Thus, we have $\ring = \ideal{G} \oplus \ideal{\cO}$, and $G$ is the $\cO$-border basis of $\ideal{G}$. Furthermore, the fact that $\cI(P) \cap \ideal{\cO}_k = \{0\}$ implies $\cI(P) \subset \ideal{G}$. With the second assumption, we have $\cI(P) = \ideal{G}$, and thus, $G$ is the $\cO$-boder basis of $\cI(P)$.
\end{proof}

