\subsection{Proof of Theorem.~\ref{thm:backward-transform}}
\BackwardTransform*
\begin{proof}
    We write an outline of the proof (see below for details). When $r<n$, the codimension of $\langle AG\rangle$ is less than $n$ and thus $\langle F\rangle\neq \langle G\rangle$ holds for any $A\in \ring^{r \times s}$. When $r\ge n$, $\langle F\rangle=\langle G\rangle\cap J$ for some ideal $J$. If $r=n$, $J\neq \ring$ for a generic matrix $A\in \ring^{r \times s}$ and thus $\ideal{F}\neq \ideal{G}$. If $r\ge n$, $J=\ring$ for a generic matrix $A\in \ring^{r \times s}$ and thus $\ideal{F}=\ideal{G}$. 
\end{proof}


To prove $\langle AG\rangle=\langle G\rangle$ for a generic matrix $A\in \ring^{r\times s}$, we consider a parametric matrix $\overline{A}$. Fix a positive integer $d\ge 1$. 
Let $h_{ij}=\sum_{|\alpha|\le d}a_{\alpha, ij}X^\alpha$ be a parametric polynomial of total degree $d$ with parameters $a_{\alpha, ij}$ and $\overline{A}=(h_{ij})$ an $r\times s$ matrix with $h_{ij}$ as $(i,j)$ entry. Let $\mathcal{A}=\{a_{\alpha, ij}\}$ be the set of all parameters of $\overline{A}$ and $D$ the cardinality of $\mathcal{A}$. For a generating set $G=\{g_1,\ldots,g_s\}$ of a zero-dimensional ideal $\mathcal{\cI}$, let $f_i=\sum_{j=1}^s h_{ij}g_i$, that is, $\overline{A}G=\{f_1,\ldots,f_r\}$. For a subset $S$ in $\ring$, we also write $\langle S\rangle_{\ring}$ when we emphasize that $\langle S\rangle$ is an ideal of $\ring$. Obviously, $\langle \overline{A}G\rangle_{K[\mathcal{A},X]}\subset \langle G\rangle_{K[\mathcal{A},X]}$. For a point $q\in K^D$, we denote by $\sigma_q$ the substitution map from $K[\mathcal{A},X]\to \ring$, where $\sigma_q(f(\mathcal{A},X))=f(q,X)$. Then, $A:=\sigma_q(\overline{A}):=(\sigma_q(h_{ij}))\in \ring^{r\times s}$ is a generic matrix for a generic $q\in K^D$. Thus, it is enough to show that there exists a dense set $C$ of $K^D$ such that $\langle \sigma_q(\overline{A})G\rangle=\langle G\rangle$ for any $q\in C$. As $\langle\sigma_q(\overline{A})G\rangle\subset \langle G\rangle$ always holds, the inverse inclusion implies the equality. First, we recall some fundamental notions of Commutative Algebra as follows. 

\begin{definition}[Primary Decomposition]
    Let $\cI$ be an ideal. A finite set of primary ideals $\{Q_1,\ldots,Q_l\}$ is a primary decomposition of $\cI$ if $\cI=Q_1\cap \cdots \cap Q_l$. For a minimal primary decomposition, i.e., the length $l$ is minimal among all primary decompositions of $\cI$, each element $Q_i$ is called an isolated primary component of $\cI$ if $\sqrt{Q_i}\not \subset \sqrt{Q_j}$ for any $j\neq i$, where $\sqrt{Q_i}$ is the radical ideal of $Q_i$.   %
\end{definition}

\begin{remark}[\cite{atiyah1994introduction}, Corollary 4.11]\label{rem:isolated}
    The isolated primary components of $\cI$ are uniquely determined from $\cI$. In other words, they are independent of a particular primary decomposition of $\cI$. 
\end{remark}

Independent sets are a useful tool to compute the dimension of a polynomial ideal. 

\begin{definition}[Independent Set]
    Let $U$ be a subset of $\mathcal{A}\cup X$. For an ideal $\cI$ of $K[\mathcal{A},X]$, $U$ is called an independent set mod $\cI$ if $\cI\cap K[U]=\{0\}$. 
\end{definition}

\begin{remark}[\cite{singular}, Theorem 3.5.1 (6)] \label{rem:mis}
    The cardinality of an independent set mod $\cI$ is less than or equal to the dimension of $\cI$. In other words, if $|U|>\dim (\cI)$ then $U$ is not an independent set mod $\cI$. 
\end{remark}




Let $\iota$ be the inclusion map $\iota:K[\mathcal{A},X]\to K(X)[\mathcal{A}]$ such that $\iota(f)=f$. For a prime ideal $\cI$ of $K(X)[\mathcal{A}]$, the inverse image $\iota^{-1}(\cI)=\cI\cap K[\mathcal{A},X]$ is also prime as follows.

\begin{lemma}[\cite{becker1993groebner}, Lemma~1.122 and Lemma~1.123] \label{lem:contraction}
    Let $\cI$ be a prime ideal of $K(X)[\mathcal{A}]$. Then, $\cI\cap K[\mathcal{A},X]$ is a prime ideal of $K[\mathcal{A},X]$.
\end{lemma}

The following lemma is a simple method for determining \gb bases under a certain condition.

\begin{lemma}[\cite{becker1993groebner}, Lemma~5.66 and Theorem 5.68] \label{lem:disjoint}
    Let $\succ$ be a term ordering and 
    $G=\{f_1,\ldots,f_r\}$. If $\lm{f_i}$ and $\lm{f_j}$ are disjoint for any $i\neq j\in \{1,\ldots,r\}$, then $G$ is a \gb basis of $\langle G\rangle$ with respect to $\succ$. 
\end{lemma}

Recall that $\cI:h=\{f\in K[\mathcal{A},X]\mid fh\in \cI\}$ is the ideal quotient of an ideal $\cI$ with respect to a polynomial $h$. The ideal quotient can be used to break the ideal $\cI$ into two ideals as follows. 

\begin{lemma}[\cite{singular}, Lemma~3.3.6 (Splitting tool)] \label{lem:split}
    Let $\cI$ be an ideal of $K[\mathcal{A},X]$ and $h$ a polynomial of $K[\mathcal{A},X]$. If $\cI:h=\cI:h^2$, then $\cI=(\cI:h)\cap (\cI+\langle h\rangle)$.
\end{lemma}

Let $\mathcal{PT}_D$ be the set of all terms of $K[\mathcal{A}]$. Then, $\mathcal{PT}_D\times \mathcal{T}_n:=\{\mathcal{A}^\alpha X^\beta\mid \mathcal{A}^\alpha\in \mathcal{PT}_D,X^\beta\in \mathcal{T}_n\}$ is the set of all terms of $K[\mathcal{A},X]$. For a term ordering $\succ_X$ on $\mathcal{T}_n$ and $\succ_\mathcal{A}$ on $\mathcal{PT}_D$, the product ordering $\succ_{X\times \mathcal{A}}$ is the ordering such that $\mathcal{A}^{\alpha_1} X^{\beta_1}\succ_{X\times \mathcal{A}}\mathcal{A}^{\alpha_2} X^{\beta_2}$ if $X^{\beta_1}\succ_X X^{\beta_2}$ or "$X^{\beta_1}=X^{\beta_2}$ and $\mathcal{A}^{\alpha_1}\succ_\mathcal{A} \mathcal{A}^{\alpha_2}$". In contrast, the product ordering $\succ_{\mathcal{A} \times X}$ is the ordering such that $\mathcal{A}^{\alpha_1} X^{\beta_1}\succ_{\mathcal{A}\times X}\mathcal{A}^{\alpha_2} X^{\beta_2}$ if $\mathcal{A}^{\alpha_1}\succ_{\mathcal{A}} \mathcal{A}^{\alpha_2}$ or "$\mathcal{A}^{\alpha_1}= \mathcal{A}^{\alpha_2}$ and $X^{\beta_1}\succ_X X^{\beta_2}$". For a product ordering $\succ_{Y_1\times Y_2}$, we denote by $\lcp_{Y_2}(f)\in K[Y_2]$ the leading coefficient of $f$ in $K(Y_2)[Y_1]$ with respect to $\succ_{Y_1}$ for $f\in K[Y_1,Y_2]$. We also say that $\succ_{Y_1\times Y_2}$ is a block ordering with $Y_1\succ\succ Y_2$. 

\begin{lemma}[\cite{suzuki-sato}, Lemma 2.2] \label{lem:CGS}
Let $G$ be a Gr\"obner basis of an ideal $\langle F\rangle$ in $K[\mathcal{A},X]$ with respect to a product ordering $\succ_{X\times \mathcal{A}}$. If $\sigma_q(\lcp_{\mathcal{A}}(g)) \neq 0$ for each $g \in G\setminus K[\mathcal{A}]$, then for any $q\in V(\langle G\cap K[\mathcal{A}]\rangle)\subset K^D$, $\sigma_q(G)$ is a Gr\"obner basis of $\langle \sigma_q(F)\rangle$ in $K[X]$ with respect to $\succ_X$.
\end{lemma}

We recall that the codimension of an ideal $\cI$ of $K[Y]$, denoted by $\codim{\cI}$, is equal to $|Y|-\dim(\cI)$. The parametric ideal $\langle \overline{A}G\rangle=\langle f_1,\ldots,f_r\rangle$ satisfies the following properties. 

\begin{proposition}\label{prop:AG}

Let $\langle \overline{A}G\rangle^e=\langle \overline{A}G\rangle_{K(X)[\mathcal{A}]}$ and $\langle \overline{A}G\rangle^{ec}=\langle \overline{A}G\rangle^e\cap K[\mathcal{A},X]$. Then, 
    \begin{enumerate}
        \item $\langle \overline{A}G\rangle^{ec}$ is a prime ideal of $K[\mathcal{A},X]$,
        \item $\overline{A}G$ is a \gb basis of $\langle \overline{A}G\rangle^e$ with respect to an arbitrary term ordering on $K(X)[\mathcal{A}]$,
        \item Fix a term ordering $\succ$ on $K(X)[\mathcal{A}]$. For $h=\lcm{\lcp_\succ(f_1),\ldots,\lcp_\succ(f_r)}\in K[X]$, 
    \[
   \langle \overline{A}G\rangle^{ec}=\langle \overline{A}G\rangle :h=\langle \overline{A}G\rangle :h^2,
    \]
        \item $\codim{\langle \overline{A}G\rangle}\le n$ and $\codim{\langle \overline{A}G\rangle^{ec}}=r$. If $r\ge n$, then $\langle \overline{A}G\rangle^{ec}\not \subset \sqrt{\langle G\rangle}$. 
    \end{enumerate}
\end{proposition}
\begin{proof} 
    \begin{enumerate}
        \item Since $\overline{A}G$ is a set of linear polynomials over $K(X)$, $\langle \overline{A}G\rangle^e$ is a prime ideal of $K(X)[\mathcal{A}]$. By Lemma~\ref{lem:contraction}, $\langle \overline{A}G\rangle^{e}\cap K[\mathcal{A},X]$ is a prime ideal of $K[\mathcal{A},X]$.
        \item Since $f_i$ and $f_j$ do not have common variables except $X$, $\lm{f_i}$ and $\lm{f_j}$ are disjoint for any $i\neq j\in \{1,\ldots,r\}$ with respect to any term ordering on $K(X)[\mathcal{A}]$. Thus, by Lemma~\ref{lem:disjoint}, $\overline{A}G$ is a \gb basis of $\langle \overline{A}G\rangle^e$ with respect to an arbitrary term ordering on $K(X)[\mathcal{A}]$
        \item First, we show that $\langle \overline{A}G\rangle :h^2\subset \langle \overline{A}G\rangle^{ec}$. For $g\in \langle \overline{A}G\rangle :h^2$, it follows that $gh^2\in \langle \overline{A}G\rangle$ and thus $g\in \langle \overline{A}G\rangle^{ec}$ since $h^2\in K[X]$ has the inverse $h^{-2}$ in $K(X)[\mathcal{A}]$. Second, prove that $\langle \overline{A}G\rangle^{ec}\subset \langle \overline{A}G\rangle :h$. Let $g\in \langle \overline{A}G\rangle^{ec}$ and fix a term ordering $\succ$ on $K(X)[\mathcal{A}]$. From (2), $g$ can be divided by the Gr\"obner basis $\overline{A}G$ of $\langle \overline{A}G\rangle^e$ with respect to  $\succ$ according to the division algorithm as
        \[
        g=c_1f_1+\cdots +c_rf_r
        \]
        where $c_1,\ldots,c_r\in K(X)$. Since $f_1,\ldots,f_r$ are linear on $\mathcal{A}$, the number of times to divide by $f_1,\ldots,f_r$ is only once each. Thus, $\lcp_\succ(f_i)c_i\in K[\mathcal{A},X]$ and $hc_i\in K[\mathcal{A},X]$ for each $i$, then
        \[
        hg=hc_1f_1+\cdots +hc_rf_r\in \langle \overline{A}G\rangle.  
        \]
        Therefore, $g\in \langle \overline{A}G\rangle:h$ and $\langle \overline{A}G\rangle^{ec}\subset \langle \overline{A}G\rangle :h$. As $gh\in \langle \overline{A}G\rangle$ implies $gh^2\in \langle \overline{A}G\rangle$, it follows that $\langle \overline{A}G\rangle :h\subset \langle \overline{A}G\rangle :h^2$. Finally, from $\langle \overline{A}G\rangle:h^2\subset \langle \overline{A}G\rangle^{ec}\subset \langle \overline{A}G\rangle:h\subset \langle \overline{A}G\rangle:h^2$, we obtain the equations. 
        \item Since $\langle G\rangle$ is a zero-dimensional ideal of $K[X]$, $\codim{\langle G\rangle_{K[\mathcal{A},X]}}=\codim{\langle G\rangle}=n$. As $\langle \overline{A}G\rangle\subset\langle G\rangle$, $\codim{\langle \overline{A}G\rangle}\le \codim{\langle G\rangle}=n$. Since $\codim{\langle \overline{A}G\rangle^{ec}}=\codim{\langle \overline{A}G\rangle^e}$ and $\overline{A}G$ consists of independent $r$-linear polynomials over $K(X)[\mathcal{A}]$, $\codim{\langle \overline{A}G\rangle^{ec}}=\codim{\langle \overline{A}G\rangle^e}=r$. Assume $r\ge n$. Then $\codim{\langle \overline{A}G\rangle^{ec}}\ge \codim{\langle G\rangle}$. If $\langle \overline{A}G\rangle^{ec}\subset \sqrt{\langle G\rangle}$ then $\langle \overline{A}G\rangle^{ec}=\sqrt{\langle G\rangle}$ since $\langle \overline{A}G\rangle^{ec}$ is a prime ideal by $(1)$. However, this implies $\langle \overline{A}G\rangle^e$ contains a unit $g_1\in G$ in $K(X)$ and thus $\langle \overline{A}G\rangle^e=K(\mathcal{A})[X]$, which contradicts $(1)$. Therefore, $\langle \overline{A}G\rangle^{ec}\not \subset \sqrt{\langle G\rangle}$. 
    \end{enumerate}
\end{proof}

The parametric ideal $\langle \overline{A}G\rangle$ can be decomposed into two ideals as follows. 

\begin{proposition}\label{prop:primdec}
    If $r\ge n$, then there exists an ideal $J$ of $K[\mathcal{A},X]$ such that
    \[
    \langle \overline{A}G\rangle=\langle G\rangle\cap J
    \]
    and $\codim{J}\ge \min(r,n+1)$. 
    Moreover, if $r>n$, then $J\cap K[\mathcal{A}]\neq \{0\}$. 
\end{proposition} 
\begin{proof}
    Let $\mathcal{P}=\langle \overline{A}G\rangle^{ec}=\langle \overline{A}G\rangle_{K(X)[\mathcal{A}]}\cap K[\mathcal{A},X]$. Consider the parameter $a_{0,ij}$ with respect to $\alpha=0$ of $a_{\alpha,ij}X^\alpha$ in $h_{ij}$. For each $i$, fix a block ordering $\{a_{0,i1},a_{0,i2},\ldots,a_{0,is}\}\succ\succ \mathcal{A}\setminus \{a_{0,i1},a_{0,i2},\ldots,a_{0,is}\}$. Since $g_ia_{0,ij}$ is the only term of $f_{i}$ that includes $a_{0,ij}$, the leading term of $f_i=\sum_{j=1}^t h_{ij}g_i$ is $g_ia_{0,ij}$. Thus, $\lcp_\succ(f_j)=g_i$ with respect to $\succ$ for each $j$ and $\lcm{\lcp_\succ(f_1),\ldots,\lcp_\succ(f_r)}=\lcm{g_i,\ldots,g_i}=g_i$. By Proposition~\ref{prop:AG} and Lemma \ref{lem:split}, $\mathcal{P}$ is a prime ideal of $K[\mathcal{A},X]$ and, for each $i$
    \[
    \mathcal{P}=\langle \overline{A}G\rangle:g_i \text{ and } \langle \overline{A}G\rangle=\mathcal{P}\cap (\langle \overline{A}G\rangle+\langle g_i\rangle).
    \]
    Here, $\mathcal{P}\neq \sqrt{(\langle \overline{A}G\rangle\rangle)}$ since otherwise $\mathcal{P}=\sqrt{\langle \overline{A}G\rangle}\subset \sqrt{\langle G\rangle}$, which contradicts Proposition~\ref{prop:AG} (4). Thus, $(\langle \overline{A}G\rangle+\langle g_i\rangle)$ contains at least one isolated component of $\langle \overline{A}G\rangle$. Let $\langle \overline{A}G\rangle+\langle g_1\rangle=Q_1\cap \cdots \cap Q_l$ be a minimal primary decomposition of $\langle \overline{A}G\rangle+\langle g_1\rangle$. Without loss of generality, we may assume that $Q_1,\ldots,Q_k$ are isolated primary components of $\langle \overline{A}G\rangle$ and $Q_{k+1},\ldots,Q_{r}$ are not for some $k\ge 1$. Since isolated primary components are uniquely determined by Remark~\ref{rem:isolated}, $Q_1,\ldots,Q_k$ are also isolated primary components of $(\langle \overline{A}G\rangle+\langle g_2\rangle),\ldots,(\langle \overline{A}G\rangle+\langle g_s\rangle)$. As $Q_1\cap \cdots\cap Q_k\supset \langle \overline{A}G\rangle+\langle g_i\rangle$ for each $i$, $Q_1\cap \cdots\cap Q_k\supset \langle G\rangle$. Then, $(Q_1\cap \cdots\cap Q_k)\cap \langle G\rangle=\langle G\rangle$. Since $\langle \overline{A}G\rangle\subset \langle G\rangle$, 
    \begin{align*}
        \langle \overline{A}G\rangle&=\langle \overline{A}G\rangle\cap \langle G\rangle=(\mathcal{P}\cap (\langle \overline{A}G\rangle+\langle h\rangle))\cap \langle G\rangle =(\mathcal{P}\cap Q_1\cap \cdots \cap Q_l)\cap \langle G\rangle\\
        &=(Q_1\cap \cdots\cap Q_k\cap \langle G\rangle)\cap (\mathcal{P}\cap Q_{k+1}\cap \cdots\cap Q_l) 
        =\langle G\rangle\cap (\mathcal{P}\cap Q_{k+1}\cap \cdots\cap Q_l).
    \end{align*}

    Let $J=\mathcal{P}\cap Q_{k+1}\cap \cdots\cap Q_l$. By Proposition~\ref{prop:AG} (4), $\codim{\mathcal{P}}=r\ge n$. Since $Q_{k+1},\ldots,Q_l$ are not isolated primary components of $\langle \overline{A}G\rangle$, $\codim{Q_{k+1}},\ldots,\codim{Q_{r}}\ge n+1$. Therefore, the codimension of $J$ is $\min(\codim{\mathcal{P}},\codim{Q_{k+1}},\ldots,\codim{Q_l})\ge \min(r,n+1)$.

    If $r>n$, then $\min(r,n+1)=n+1$ and $\dim (J)<(D+n)-(n+1)=D-1$. Thus, $\mathcal{A}$ is not an independent set of $J$ since $|\mathcal{A}|=D>D-1=\dim (J)$, that is, $K[\mathcal{A}]\cap J\neq \{0\}$ by Remark~\ref{rem:mis}. 
\end{proof}

Let $V(J)=\{q\in K^D\mid f(q)=0,\forall f\in J\}$ be the variety of an ideal $J$ of $K[\mathcal{A}]$. If $J$ is a nonzero ideal, $V(J)$ is a variety of dimension $D-1$ at most and thus $K^D\setminus V(J)$ is a dense set of $K^D$. Finally, we obtain the proof of Theorem\ref{thm:backward-transform} as follows. 

\begin{proof}[proof of Theorem\ref{thm:backward-transform}]
    In case $r<n$, $\langle AG\rangle \neq  \langle G\rangle$ since $\codim{\langle AG\rangle}=r<n=\codim{\langle G\rangle}$ for any $A\in \ring^{r\times s}$. Thus, we assume that $r\ge n$. By Proposition~\ref{prop:primdec}, there exists an ideal $J$ of $K[\mathcal{A},X]$ such that
    \[
    \langle \overline{A}G\rangle=\langle G\rangle\cap J. 
    \]
    \begin{enumerate}
        \item Assume that $r=n$ and $G$ is a border basis. Fix a term ordering $\succ_X$ on $X$. Then, for each $i\in \{1,\ldots,n\}$, there exists $f_{k_i}\in G$ such that $\lcp_{\succ_X}(g_{k_i})=x_i^{d_i}$ for some positive integer $d_i$. For simplicity, we may assume that $k_1=1,\ldots,k_n=n$. Consider the parameter $a_{x_{i},ii}$ with respect to $X^\alpha=x_i$ in $h_{ii}$ for each $i$. Fix a term ordering $\succ_\mathcal{A}$ such that $\{a_{x_{1},11},\ldots,a_{x_{n},nn}\}\succ \succ \mathcal{A}\setminus \{a_{x_{1},11},\ldots,a_{x_{n},nn}\}$. Let $\succ$ be the product ordering $\succ_{\mathcal{A}\times X}$. Then, $\ltp_\succ(h_{ii})=\ltp_\succ(a_{x_i,ii}x_ig_i)=a_{x_{i},ii}x_i^{d_i+1}$ for each $i\in \{1,\ldots,n\}$. Since $\ltp_\succ(h_{11}),\ldots,\ltp_\succ (h_{nn})$ are disjoint, $\overline{A}G$ is a \gb basis of $\langle \overline{A}G\rangle$ with respect to $\succ$ by Lemma~\ref{lem:disjoint}. For any non-zero polynomial $w(\mathcal{A})\in K[\mathcal{A}]$, $w(\mathcal{A})g_1\not \in \langle \overline{A}G\rangle$ as $\ltp_{\succ}(w(\mathcal{A})g_1)=\ltp_\succ(w(\mathcal{A}))\ltp_\succ(g_1)=\ltp_\succ(w(\mathcal{A}))x_1^{d_1}$ is not divided by any $\lt{h_{11}},\ldots,\lt{h_{nn}}$. Thus, $\mathcal{P}\cap K[\mathcal{A}]=(\langle \overline{A}G\rangle:g_1)\cap K[\mathcal{A}]=\{0\}$. Let $G^\prime=\{g_1^\prime,\ldots,g_l^\prime\}$ be the reduced \gb basis of $\mathcal{P}$ with respect to a block ordering $X\succ^\prime\succ^\prime \mathcal{A}$. 
        Obviously, $G^\prime\cap K[\mathcal{A}]=\{0\}$. Then, letting $H=\lcm{\lcp_{\mathcal{A}}(g_1)\cdots \lcp_{\mathcal{A}}(g_l)}\neq 0$, $\sigma_q(G^\prime)$ is a \gb basis of $\sigma_q(\mathcal{P})$ for any $q\in V(G^\prime\cap \mathcal{A})\setminus V(H)=K^D\setminus V(H)$ by Lemma~\ref{lem:CGS}. Fix $q\in K^D\setminus V(H)$. Since $\langle \overline{A}G\rangle\subset \mathcal{P}$, 
        \[
        \langle \sigma_q(\overline{A})G\rangle\subset \sigma_q(\mathcal{P})\neq K[X]. 
        \]
         As $\mathcal{P}\not \supset\langle G\rangle_{K[X]}$, there exists $g\in \langle G\rangle_{K[X]}\setminus \mathcal{P}$ such that $\ltp_{\succ^\prime}(g)\not \in  \ltp_{\succ^\prime}(\langle G^\prime\rangle)$. This implies $\ltp_{\succ^\prime}(g)=\ltp_{\succ^\prime}(\sigma_q(g))\not \in  \ltp_{\succ^\prime}(\langle\sigma_q(G^\prime)\rangle)=\ltp_{\succ^\prime}(\sigma_q(\mathcal{P}))$ since $g=\sigma_q(g)$ and $\sigma_q(G^\prime)$ is a
        \gb basis of $\sigma_q(\mathcal{P})$ with respect to $\succ^\prime$. Thus, $g\in \langle G\rangle\setminus \sigma_q(\mathcal{P})$ and  $\langle G\rangle\not \subset \sigma_q(\mathcal{P})$. As $\langle \sigma_q(\overline{A})G\rangle\subset \sigma_q(\mathcal{P})$, 
        we obtain $\langle \sigma_q(\overline{A})G\rangle\neq \langle G\rangle$. With $H\neq 0$, $K^D\setminus V(H)$ is a dense set of $K^D$.

    \item Assume that  $r>n$. Then $J\cap K[\mathcal{A}]\neq \{0\}$ by Proposition~\ref{prop:primdec}. Fix $q\in K^D\setminus V(J\cap K[\mathcal{A}])$. Then, for $0\neq f(\mathcal{A})\in J\cap K[\mathcal{A}]$, it follows that $0\neq f(q)\in \sigma_q(J)$, that is, $\sigma_q(J)=K[X]$. Since $\langle G\rangle\cdot J\subset \langle \overline{A}G\rangle$ and $\sigma_q(\langle G\rangle)=\langle G\rangle$, 
    \[
   \langle \sigma_q(\overline{A})G\rangle=\sigma_q(\langle \overline{A})G\rangle)\supset  \sigma_q (\langle G\rangle\cdot J)=\sigma_q (\langle G\rangle)\cdot \sigma_q (J)=\langle G\rangle.
    \]
    Since $\langle \sigma_q(\overline{A})G\rangle\subset \langle G\rangle$ always holds, we obtain $\langle \sigma_q(\overline{A})G\rangle=\langle G\rangle$. As $J\cap K[\mathcal{A}]\neq 0$, $K^D\setminus V(J\cap K[\mathcal{A}])$ is a dense set of $K^D$.
     \end{enumerate}
\end{proof}

\begin{corollary}\label{cor:backward-transform}
    Let $K=\mathbb{F}_p$ be a finite field of order $p$ for a prime number $p$ and $\mathcal{G}=\{A\in \ring_{\le d}^{r\times s}\mid \ideal{AG}=\ideal{G}\}$. Then the probability of $A$ satisfies $\ideal{AG}=\ideal{G}$, i.e., $Pr(p)=|\mathcal{G}|/|\ring_{\le d}^{r\times s}|$, is almost $1$ for a sufficiently large $p$. 
\end{corollary}

\begin{proof}[proof of Corollary~\ref{cor:backward-transform}]
    Without loss of generality, we may assume that $g_1,\ldots,g_s\in \mathbb{Z}[X]$ and $f_1,\ldots,f_r\in \mathbb{Z}[\mathcal{A},X]$. Fix a block ordering $X\succ\succ\mathcal{A}$. For each $i\in \{1,\ldots,s\}$ and a new variable $y$, let $S_i=\{yf_1,\ldots,yf_r,(1-y)g_i\}$ and $G_{i}$ a \gb basis of $\langle S_i\rangle$ in $K[y,\mathcal{A},X]$ with respect to an extended block ordering $y\succ\succ X\succ\succ\mathcal{A}$. It is known that $G_{i}\cap K[\mathcal{A},X]$ is a \gb basis of $\langle\overline{A}G\rangle: g_i$ (see Lemma~1.8.12 in \cite{singular}). By Proposition~\ref{prop:primdec}, $\langle\overline{A}G\rangle:g_1=\cdots =\langle\overline{A}G\rangle:g_s=\mathcal{P}$.  Let $G_i(p)$ be the \gb basis of $\langle S_i\rangle_{\mathbb{F}_p[X]}$ with respect to $\succ$ and $\maxdeg{G_{i}(p)}=\max(\deg(g)\mid g\in G_{i}(p))$. Since an upper bound of degrees of \gb bases can be decided from degrees of the generator and independently from the coefficient field, there exists $d_{max}$ such that $d_{max}>\maxdeg{G_i(p)}$ for any $i$ and $p$. Let $0\neq f\in G_i\cap K[\mathcal{A}]\subset \mathcal{P}\cap  K[\mathcal{A}]$ and then $\deg(f)\le d_{max}$. For $q\in \mathbb{F}_p^D$ with $f(q)\neq 0$, $\sigma_q(\overline{A}G):g_i\supset \sigma_q(\overline{A}G:g_i)=\sigma_q(\mathcal{P})=\mathbb{F}_p[X]$ for each $i$. Hence, $g_i\in \sigma_q(\overline{A}G)$ for each $i$ and thus $\sigma_q(\overline{A}G)\supset \langle G\rangle$ for such $q$. As the inverse inclusion is obvious, we obtain $\sigma_q(\overline{A}G)=\langle G\rangle$ for any $q\in \mathbb{F}_p^D\setminus V(f)$. Since $f$ has at most $d_{max}p^{D-1}$ solutions in $\mathbb{F}_p^D$ (see Theorem~6.13 in \cite{Lidl_Niederreiter_1996}), $Pr(p)\ge \frac{|\mathbb{F}_p^D\setminus V(f)|}{|\mathbb{F}_p^D|}\ge \frac{p^D-d_{max}p^{D-1}}{p^D}=1-\frac{d_{max}}{p}$ and this goes $1$ for a sufficiently large $p$. 
\end{proof}

