\end{notation}
	Once we have characterized $\mathcal{PS}(M)$, it is immediate to characterize those elements of $\mathcal{PS}(M)$ which correspond to $\mathbf{A}_k(M)$, recalling Notation~\ref{the_lattice notation}.

	\begin{proposition}\label{char_point_stab_singletons} For $0 < k < \omega$, we let
	$\mathcal{PS}_k(M)$ to be the set of  $H \in \mathcal{PS}(M)$ such that $H \neq G$ and any chain of elements of $\mathcal{PS}(M)$ starting at $H$ and arriving at $G$ has length $\leq k$. Also, by convention, we let $\mathcal{PS}_\omega(M) = \mathcal{PS}(M)$. Then, recalling the notation introduced in \ref{the_lattice notation} (so $\mathbf{A}_\omega(M) = \mathbf{A}(M)$), we have the following:
	$$\mathcal{PS}_k(M) = \{G_{(K)} : K \in \mathbf{A}_k(M) \}.$$
\end{proposition}

	\begin{proof} This is obvious, recalling \ref{char_point_stab}.
\end{proof}


\begin{proposition}\label{char_Lpoint_stab} Let $L$ be a group and $H \in \mathcal{PS}(M)$. The following conditions are equivalent:
	\begin{enumerate}[(1)]
	\item $H = G_{(K)} \in \mathcal{PS}(M)$ and $\mrm{Aut}_M(K) \cong L$;
	\item there is $H' \in \mathcal{GS}(M)$ such that $H \trianglelefteq H'$, $H'$ is maximal under this condition and $H'/H \cong L$.
\end{enumerate}
\end{proposition}

	\begin{proof} Concerning the implication ``(1) implies (2)'', let $H' = G_{\{ K \}}$, then, by Proposition \ref{normality_prop} and equation (\ref{equation_label}) in the proof of Lemma \ref{baguettelemma}, we have that $H'$ is as wanted. Concerning the implication ``(2) implies (1)'', if $H$ and $H'$ are as in (2), then, by Proposition \ref{normality_prop} and equation (\ref{equation_label}) in the proof of Lemma \ref{baguettelemma}, it must be the case that $H' = G_{\{ K \}}$ and $H = G_{(K)}$ for some $K \in \mathbf{A}(M)$ s.t. $\mrm{Aut}_M(K) \cong L$.
\end{proof}


	The following proposition is not needed for the proof of Theorem~\ref{main_theorem}, but we believe it to be of independent interest. In fact, it gives us a characterization of the $G_\delta$ subgroups in this framework.

\begin{proposition}
Every $G_\delta$ subgroup of $G$ is of the form $G_{(K,L)}$  with $K$ an algebraically closed subset of $M$ and $L$ a subgroup of $Aut_M(K)$. 
\end{proposition}

\begin{remark}
    We have not defined $G_{(K,L)}$ and $\mrm{Aut}_M(K)$ for algebraically closed sets, but they are the natural generalization of Definitions \ref{algclosednotation} and \ref{GS_def}.
\end{remark}

\begin{proof}
Let $G_{(K,L)}$ for a certain $K$ and $L$ as above. If we show that $G_\delta$ are closed for overextension, we have done since $G_{(K)}=G_{(K,\{ \mrm{id}_k\})} \leq G_{(K,L)}$ and $G_{(K)}=\bigcap_{a \in K} G_{(a)}$ is $G_\delta$. 
\noindent
Suppose $H_1\leq H_2$ and $H_1$ is $G_\delta$, then $H_2$ is $G_\delta$. Since $H_1\leq H_2$, $H_2=\bigcup_{a \in H_2} aH_1$, a countable union of cosets of $H_1$. The left action $\lambda_a$ is a homeomorphism and sends $G_\delta$ in $G_\delta$. Therefore, every coset of $H_1$ is $G_\delta$ and, since $\Sigma_2^0$ is closed for countable union, $H_2$ is $G_\delta$.
\smallskip

\noindent
Conversely, let $H$ a $G_\delta$ subgroup. Then $H=\bigcap_{n \in \omega} A_n$ with $A_n$ open subgroups. By \ref{hyp}(\ref{hyp_2}) and Lemma \ref{baguettelemma}, $A_n=G_{(K_n,L_n)}$ with $K_n \in \mathbf{A}(M)$ and $L \in \mathrm{Aut}_M(K_n)$ for every $n \in \omega$. 

\noindent Let the algebraically closed $K=\bigcap_n K_n$ and $L=\{f \restriction K : f \in G, f(K_n)=K_n \text{ and } f\restriction K_n \in L_n\}$. We show that $H=G_{(K,L)}$. Let $f \in H$. Since $f \in G_{(K_n,L_n)}$, $f(K_n)=K_n$, $f\restriction K_n \in L_n$ and $f(K)=f(\bigcap_n K_n)=\bigcap_n f(K_n)=\bigcap_n K_n=K$, that is $f \in G_{(K,L)}$. For the other way, suppose not and let $f \in G_{(K,L)} \setminus H$. Then $f \notin G_{(K_n,L_n)}$ for a certain $n$. So $f(K_n)\neq K_n$ or $f\restriction K_n \notin L_n$, that is $f \notin L$, a contradiction.
\end{proof}

This proposition explains, in some sense, the characterization of $\mathcal{OL}(M)$. A generic intersection of open sets is not necessarily in  $\mathcal{GS}(M)$, so we have that $\Sigma^0_1 \subseteq \mathcal{GS}(M) \subseteq \Sigma^0_2$. In $\omega$-categorical case, $\Sigma^0_1=\mathcal{GS}(M)$ (see \cite{Paolini_BLMS}), but in general the inclusions are strict. For this reason, we need $\mathcal{OL}(M)$, a definable fragment of $\mathcal{GS}(M)$, where we consider the intersection of a certain chain of open subgroups. 
