\section{Reconstructing isomorphisms}\label{sec_reconstruction}

In this section, we show that, with the necessary adjustments, the reconstruction theorem from \cite{Paolini_BLMS} remains valid in our context. This, in turn, allows us to apply it in Section \ref{sec_applications} to structures that are not $\omega$-categorical.

\begin{notation}\label{kM_notation} Given $M$ as in \ref{hyp} we define $k_M$ as the following cardinal:
	$$k_M = \mrm{sup} \{k < \omega : \exists a_1, ..., a_k \in M \text{ s.t. } \mrm{acl}^{\mrm{g}}_M(a_1) \subsetneq \cdots \subsetneq \mrm{acl}^{\mrm{g}}_M(a_k)\}.$$
\end{notation}

We now introduce a first-order structure which we refer to as the {\em expanded structure of $M$ of depth $\leq k$} (for $k \leq \omega$), where $k$ has to be thought in the context of Notation~\ref{the_lattice notation}. Morally, it is the orbital structure on the set of Galois algebraically closed sets of $M$ which are at distance $\leq k$ from the bottom of the poset $(\mathbf{A}(M), \subseteq)$.

\begin{definition}\label{def_expanded_1}  Let $0 < k \leq \omega$ and recall the notations from \ref{the_lattice notation}.
\begin{enumerate}[(1)]
	%\item On the set $M$ consider the equivalence relation $a \sim b$ iff $\mrm{acl}^{\mrm{g}}_M(a) = \mrm{acl}^{\mrm{g}}_M(b)$, then the set of equivalence classes of $\sim$ is exactly the set:
	%$$\{ \mrm{acl}^{\mrm{g}}_M(a) : a \notin \mrm{acl}(\emptyset)\}.$$
	\item We let $M^{\mrm{ex}}_k$ be $\{(K, p, K') : K, K' \in \mathbf{A}_k(M) \text{ and } p: K \cong K' \text{ such that exists } f \in G, f\restriction K=p \text{ and } f(K)=K' \}.$
	\item\label{the_identification} We identify $\mathbf{A}_k(M)$ with the set of triples $(K, \mrm{id}_K, K)$.
\end{enumerate}
\end{definition}

	\begin{definition}\label{def_expanded_12} Let $0 < k \leq \omega$. We define a first-\mbox{order structure $\mathcal{E}^{\mrm{ex}}_M(k)$ as follows:}% (so $\sim^{n}_{\mathcal{E}^{\sim}_M}$ is a $2n$-ary predicate):
	\begin{enumerate}[(1)]
	\item $\mathcal{E}^{\mrm{ex}}_M(k)$ has as domain $M^{\mrm{ex}}_k$;
	\item\label{def_expanded_12_unary} we define a unary predicate which holds of $\mathbf{A}_k(M)$, recalling \ref{def_expanded_1}(\ref{the_identification}); 
	\item\label{def_expanded_12_binary} for $1 < n< \omega$, we define an $n$-ary predicate $E_n$ as follows:
	$$((A_1, p_1, B_1), ..., (A_n, p_n, B_n)) \in E^{\mathcal{E}^{\mrm{ex}(k)}_M}_n$$
	$$\Updownarrow$$
	$$\exists g \in \mrm{Aut}(M) \text{ s.t. for all } i \in [1, n], \,  g(A_i) = B_i \text{ and } g \restriction A_i = p_i;$$
	\item\label{dom} we define a binary predicate $\mrm{Dom}$ (which stands for ``domain'')~such~that \newline $(A, p, B) \in \mathcal{E}^{\mrm{ex}}_M(k)$ is in relation with $C \in \mathbf{A}_k(M)$ if and only if $A = C$;
	\item\label{cod} we define a binary predicate $\mrm{Cod}$ (which stands for ``codomain'') such that $(A, p, B) \in \mathcal{E}^{\mrm{ex}}_M(k)$ is in relation with $C \in \mathbf{A}_k(M)$ if and only if $B = C$.
	\item\label{theP_n_predicates} for $1 \leq n < \omega$, we define an $n+1$-ary predicate $P_n$ on $\mathbf{A}_k(M)$ as follows:
	$$(A, B_1, ..., B_n) \in P^{\mathcal{E}^{\mrm{ex}}_M(k)}_n \; \Leftrightarrow \; A \subseteq \mrm{acl}^{\mrm{g}}_M(B_1 \cup \cdots \cup B_n).$$
	%\item a binary predicate which holds of $A, B \in \mathbf{A}_k(M)$exactly when $A \subseteq B$;
        \item\label{def_expanded_12+_item5} a ternary predicate which holds exactly when the following happens:
	$$K_1 \xrightarrow{p_1} K_2 \xrightarrow{p_2} K_3 = K_1 \xrightarrow{p_2 \circ p_1} K_3.$$
        \item a binary predicate which holds exactly when the following happens:
	$$K_1 \xrightarrow{p_1} K_2 \xrightarrow{p_2} K_1 = K_1 \xrightarrow{\mrm{id}_{K_1}} K_1.$$
        %\item for every group $L$ such that $L \cong \mrm{Aut}_M(K)$ for some $K \in \mathbf{A}_k(M)$, we add a unary predicate $P_L$ which holds of $B \in \mathbf{A}_k(M)$ if and only if $\mrm{Aut}_M(B) \cong L$.
\end{enumerate}
%When $k = \infty$ we sometimes simply write $\mathcal{E}^{\mrm{ex}}_M$ instead of $\mathcal{E}^{\mrm{ex}}_M(\infty)$.
When we write $\mathcal{E}^{\mrm{ex}}_M$ (so without the $k$) we mean $\mathcal{E}^{\mrm{ex}}_M(\omega)$.
\end{definition}
%\begin{remark} If $k = \omega$, then clearly we could replace the predicates $P_n$ above with a single binary predicate which holds of $A, B \in \mathbf{A}(M)$ if and only if $A \subseteq B$.
%\end{remark}
	The next theorem shows that as soon as $k \geq \mrm{max}\{k_M, k_N\}$ the problem of determination of $\mrm{Aut}(M) \cong_{\mrm{top}} \mrm{Aut}(N)$ reduces completely to the problem of determination of $\mathcal{E}^{\mrm{ex}}_M(k) \cong \mathcal{E}^{\mrm{ex}}_N(k)$. This theorem is the core of the paper.

	\begin{theorem}\label{main_theorem} Let $M, N$ be as in \ref{hyp}. Then we have the following:
	\begin{enumerate}[(1)]
	\item $\mrm{Aut}(M) \cong_{\mrm{top}} \mrm{Aut}(N)$ implies $\mathcal{E}^{\mrm{ex}}_M(k) \cong \mathcal{E}^{\mrm{ex}}_N(k)$, for all $0 < k \leq \omega$.
	\item If $\mrm{max}\{k_M, k_N\} \leq k$, then $\mathcal{E}^{\mrm{ex}}_M(k) \cong \mathcal{E}^{\mrm{ex}}_N(k)$ implies $\mrm{Aut}(M) \cong_{\mrm{top}} \mrm{Aut}(N)$.
        \item Let $k_M \leq k \leq \omega$. Then every topological automorphism $\alpha$ of $\mrm{Aut}(M)$ induces an automorphism $f_{\alpha}$ of $\mathcal{E}^{\mrm{ex}}_M(k)$, and the assignment $\alpha \mapsto f_{\alpha}$ is a group isomorphism from the group of topological automorphisms of $\mrm{Aut}(M)$ onto the automorphism group of the first-order structure $\mathcal{E}^{\mrm{ex}}_M(k)$.
%	\item If $\mrm{max}\{k_M, k_N\} \leq k$, then every $\alpha: \mrm{Aut}(M) \cong_{\mrm{top}} \mrm{Aut}(N)$ induces an isomorphism $f_{\alpha}$ from $\mathcal{E}^{\mrm{ex}}_M(k)$ onto $\mathcal{E}^{\mrm{ex}}_M(k)$ and the assignment $\alpha \mapsto f_{\alpha}$ is bijective.
%	\item If $M = N$ and $k \geq k_M$, then $\alpha \mapsto f_{\alpha}$ is a group isomorphism from the group of topological automorphisms of $\mrm{Aut}(M)$ onto the automorphism group of $\mathcal{E}^{\mrm{ex}}_M(k)$.
	\end{enumerate}
%$$\mrm{Aut}(M) \cong_{\mrm{top}} \mrm{Aut}(N) \;\; \Leftrightarrow \;\; \mathcal{E}^{\mrm{ex}}_M(k) \cong \mathcal{E}^{\mrm{ex}}_N(k), \text{ for all } k \leq \mrm{max}(k_M, k_n).$$
\end{theorem}
\begin{remark}\label{remark_mainth} To prove item (2), it is sufficient to have the isomorphism $\mathcal{E}^{\mrm{ex}}_M(k) \cong \mathcal{E}^{\mrm{ex}}_N(k)$ on the restricted language \ref{def_expanded_12}(1)-(5). Also, to prove item (3), we do not need all the expressive power of  $\mathcal{E}^{\mrm{ex}}_M(k)$.
\end{remark}

\begin{proof} Concerning (1), let $\alpha : \mrm{Aut}(M) \cong_{\mrm{top}} \mrm{Aut}(N)$. By \ref{char_point_stab_singletons}, $\alpha$ induces a bijection of  $\mathcal{PS}_k(M)$ onto $\mathcal{PS}_k(N)$. Let $f$ be the corresponding bijection of $\mathbf{A}_k(M)$ onto $\mathbf{A}_k(N)$. Let also $G = \mrm{Aut}(M)$ and $H = \mrm{Aut}(N)$. Then, \mbox{for $K \in \mathbf{A}_k(M)$ and $g \in  G$:}
$$\alpha(gG_{(K)}) = \alpha(g)\alpha(G_{(K)}) = \alpha(g) H_{(f(K))}.$$
Hence, $\alpha$ also induces a bijection of $\{gG_{(K)} : K \in \mathbf{A}_k(M)\}$ onto $\{hH_{(K)} : K \in \mathbf{A}_k(N)\}$. Thus, given $(K, p, K') \in M^{\mrm{ex}}_k$ we have that for any extension $\hat{p}$ of $p$ to an automorphism of $M$ we have that $\alpha(\hat{p} G_{(K)}) = \alpha(\hat{p}) H_{(f(K))}$ and also that:
$$\alpha(\hat{p}) H_{(f(K))} \alpha(\hat{p})^{-1} = H_{f(K')},$$
and so it makes sense to define $f_\alpha(K, p, K') = f(K, p, K')$ as $(f(K), \alpha(\hat{p}) \restriction f(K), f(K'))$ (it is easy to see that this does not depend on the choice of $\hat{p}$, recalling the identification of $gG_{(K)}$ with the triple $(K, g \restriction K, g(K))$). Notice that $f(K, \mrm{id}_K, K)$ is $(f(K), \mrm{id}_{f(K)}, f(K))$, as $\hat{\mrm{id}}_K G_{(K)} = G_{(K)}$ and so $\alpha(\hat{\mrm{id}}_K) H_{(f(K))} = H_{(f(K))}$, hence our definition of $f$ is notational consistent with the identification made in \ref{def_expanded_1}(\ref{the_identification}). Thus, the map $f = f_{\alpha}$ that we just defined is a bijection between $M^{\mrm{ex}}_k$ and $N^{\mrm{ex}}_k$ which sends $\mathbf{A}_k(M)$ onto $\mathbf{A}_k(N)$ (and so it preserves the unary predicate from \ref{def_expanded_12}(\ref{def_expanded_12_unary})). 
%We now move to the predicates $P_n$ and $R_n$. Firstly, it is immediate to see that the relations $P_n$, for $1 \leq n < \omega$, from \ref{def_expanded_12}(\ref{theP_n_predicates}) are preserved by $f \restriction \mathbf{A}_k(M)$, in fact:
%	\[ \begin{array}{rcl}	
%(A, B_1, ..., B_n) \in P^{\mathcal{E}^{\mrm{ex}}_M(k)}_n
%& \Leftrightarrow &  A \subseteq \mrm{acl}^{\mrm{g}}_M(B_1 \cup \cdots B_n) \\
