$$\alpha(g) H_{(f(A_1))}\alpha(g)^{-1} = H_{(f(B_1))}, \,  ... , \, \alpha(g) H_{(f(A_n))}\alpha(g)^{-1} = H_{(f(B_n))}$$
$$\Updownarrow$$
$$f(A_1, p_1, B_1), \, ..., \, f(A_n, p_n, B_n) \in E^{\mathcal{E}^{\mrm{ex}}_N(k)}_n.$$
%Finally, reversing the role of $\alpha$ and $\alpha^{-1}$ it is easy to see that we also have:
%$$(f(A_1), f(p_1), f(B_1)), \, ..., \, (f(A_n), f(p_n), f(B_n)) \in E^{\mathcal{E}^{\mrm{ex}}_N(k)}_n.$$
