\smallskip \noindent Concerning the ternary predicate from \ref{def_expanded_12}(7), suppose that:
	$$K_1 \xrightarrow{p_1} K_2 \xrightarrow{p_2} K_3 = K_1 \xrightarrow{p_2 \circ p_1} K_3.$$
Let $p = p_2 \circ p_1$, then this means that:
$$K_1 \xrightarrow{\mrm{id_{K_1}}} K_1 \xrightarrow{p_1} K_2 \xrightarrow{\mrm{id_{K_2}}} K_2 \xrightarrow{p_2} K_3 = K_1 \xrightarrow{p} K_3.$$
Hence, letting $\hat{p}_1, \hat{p}_2, \hat{p}$ be extensions $p_1, p_2, p$ to automorphisms of $M$, we have:
$$\hat{p}_2 G_{(K_2)}\hat{p}_1 G_{(K_1)} = \hat{p}G_{(K_1)}.$$
Thus, applying $\alpha$ we get that:
$$\alpha(\hat{p}_2) H_{(f(K_2))} \alpha(\hat{p}_1) H_{(f(K_1))} = \alpha(\hat{p}) H_{(f(K_1))},$$
which, translating back to the structures and letting $f(p_i) = \alpha(\hat{p}_i) \restriction f(K_i)$, means:
$$f(K_1) \xrightarrow{\mrm{id_{f(K_1)}}} f(K_1) \xrightarrow{f(p_1)} f(K_2) \xrightarrow{\mrm{id_{f(K_2)}}} f(K_2) \xrightarrow{f(p_2)} f(K_3) = f(K_1) \xrightarrow{f(p)} f(K_3),$$
and so we are done. Finally, the proof that \ref{def_expanded_12}(8) is preserved is similar. %concerning the preservation of \ref{def_expanded_12}(9), this is immediate by \ref{char_Lpoint_stab}. 
Thus, we finished proving that $f_\alpha: \mathcal{E}^{\hat{\mrm{ex}}}_M(k) \cong \mathcal{E}^{\hat{\mrm{ex}}}_N(k)$ and so we finished proving item (1). So we proved~(1).

\medskip
\noindent
Concerning item (2), let $\mrm{max}\{k_M, k_N\} \leq k$ and $f: \mathcal{E}^{\mrm{ex}}_M(k) \cong \mathcal{E}^{\mrm{ex}}_N(k)$. Recalling \ref{kM_notation}, observe that under this assumption we crucially have that the following holds:
\begin{equation}\tag{$\star_8$}
\bigcup \{ K : K \in \mathbf{A}_k(M) \} = M \text{ and } \bigcup \{ K : K \in \mathbf{A}_k(N) \} = N.
\end{equation}
Now, given $g \in G$ we have to define $\alpha_f(g) = \alpha(g) \in H$ in such a way that the resulting map $\alpha_f: \mrm{Aut}(M) \cong_{\mrm{top}} \mrm{Aut}(N)$. To this extent, first of all enumerate $\mathbf{A}_k(M)$ as $(K_i : i < \omega)$ and let $g \in G$. For every $i < \omega$, let:
$$(K_i, g \restriction K_i, g(K_i)) =: (A_i, p_i, B_i).$$
Then, clearly, for every $n < \omega$, we have that:
$$((A_1, p_1, B_1), ..., (A_n, p_n, B_n)) \in E^{\mathcal{E}^{\mrm{ex}}_M(k)}_n,$$
and so, being $f: \mathcal{E}^{\mrm{ex}}_M(k) \cong \mathcal{E}^{\mrm{ex}}_N(k)$, we infer that:
$$f(A_1, p_1, B_1), \, ..., \, f(A_n, p_n, B_n) \in E^{\mathcal{E}^{\mrm{ex}}_N(k)}_n.$$
Now, for every $i < \omega$, let $h_i$ be the second component of the triple $f(A_1, p_1, B_1)$. Then, recalling how the predicates $E^{\mathcal{E}^{\mrm{ex}}_N(k)}_n$ were defined, for every $n < \omega$ there is $\hat{h}_n \in H$ such that $h_i \subseteq \hat{h}_n$, for every $i \leq n$. Now, by $(\star_8)$ we have that $\bigcup \{ K : K \in \mathbf{A}_k(N) \} = N$ and so for every $a \in N$ we have that the value $(\hat{h}_n(a) : n < \omega)$ is eventually constant. Thus, we can define:
$$\alpha_f(g) = \alpha(g) = \mrm{lim}(\hat{h}_n : n < \omega).$$
Clearly $\alpha(g)$ is a one-to-one function from $N$ into $N$. The only non-trivial thing is to verify that $\alpha(g)$ is surjective, as it will then immediately follow that it is an automorphism of $N$, because of how it was defined. To this extent, notice that $f \restriction \mathbf{A}_k(M)$ induces a bijection of $\mathbf{A}_k(M)$ onto $\mathbf{A}_k(N)$ and, as before, by $(\star_8)$ we have that $\bigcup \{ K : K \in \mathbf{A}_k(N) \} = N$, using this it is easy to see that $\alpha(g)$ is surjective (recalling the predicates $\mrm{Dom}$ and $\mrm{Cod}$ from \ref{def_expanded_12}(\ref{dom})(\ref{cod})). Furthermore, by how it was defined, it is immediate to verify that this correspondence $g \mapsto \alpha(g) = \alpha_f(g)$ is a topological isomorphism from $\mrm{Aut}(M)$ onto $\mrm{Aut}(N)$. This concludes the proof. 
%Finally, items (3) and (4) are easy to see observing that the maps $\alpha \mapsto f_{\alpha}$ and $f \mapsto \alpha_f$ that we just defined are inverses of each others, for $k \geq \mrm{max}\{k_M, k_N\}$.
\medskip

\noindent
We prove (3). To this extent, we show that the assignment $\alpha \mapsto f_{\alpha}$ is a group isomorphism (recall that in (3) we are assuming that $M = N$). Now, the fact that the assignment $\alpha \mapsto f_{\alpha}$ is bijective is easy to see using the assignment $f \mapsto \alpha_f$ from the proof of the item above and observing that the two maps are one the inverse of the other. We are thus left to show that for $\alpha$ and $\beta$ topological automorphisms of $\mrm{Aut}(M)$ we have that $f_{\beta} \circ f_{\alpha} = f_{\beta \circ \alpha}$, but this is obvious; in fact, writing $\alpha(\hat{p}) \restriction f_\alpha(K)$ the object from the proof above simply as $f_\alpha(p)$ (and similarly for $\beta$) we have that following:
$$(K, p, K') \xrightarrow{f_{\alpha}} (f_{\alpha}(K), f_{\alpha}(p), f_{\alpha}(K')) \xrightarrow{f_{\beta}} (f_\beta(f_{\alpha}(K)), f_\beta(f_{\alpha}(p)), f_\beta(f_{\alpha}(K'))),$$
and this is the same as:
$$(K, p, K') \xrightarrow{f_{\beta} \circ f_{\alpha}}(f_\beta \circ f_{\alpha}(K), f_\beta \circ f_{\alpha}(p), f_\beta \circ f_{\alpha}(K')),$$
essentially because for any $g \in G$ we obviously have that $\beta \circ \alpha(g) = \beta(\alpha(g))$.
\end{proof}

\begin{theorem1.2} Let $M, N$ be with the Lascar \mbox{property (cf. \ref{hyp_intro}) and $G = \mrm{Aut}(M)$.}
	\begin{enumerate}[(1)]
	\item Pointwise stabilizers of finitely generated algebraically closed subsets of $M$ can be characterized, and this determines a definable Galois correspondence between such $G_\delta$-subgroups of $G$ and finitely generated algebraically closed subsets of $M$;
	\item We can associate to $M$ a canonical first-order structure $\mathcal{E}^{\mrm{ex}}_M$, essentially made of finitely generated algebraically closed subsets of $M$ with partial isomorphisms of $M$ between such sets, so that we have: $\mrm{Aut}(M) \cong_{\mrm{top}} \mrm{Aut}(N) \; \Leftrightarrow \; \mathcal{E}^{\mrm{ex}}_M \cong \mathcal{E}^{\mrm{ex}}_N$.
	\item In case $M = N$ we have that $\mrm{Aut}_{\mrm{top}}(G)$ is naturally isomorphic to $\mrm{Aut}(\mathcal{E}^{\mrm{ex}}_M)$.
	\end{enumerate}
	\end{theorem1.2}

\begin{proof}
We prove item (1). By Proposition \ref{char_point_stab}, we have characterized $\mathcal{PS}(M)$. In this way, $\mathcal{PS}(M)$ are definable as subsets of $G$ and $\mathbf{A}(M)$ are definable as subsets of $M$. We define the following maps:
\begin{align*}
    \mrm{Fix}_M:\mathbf{A}(M) &\rightarrow \mathcal{PS}(M) \quad\quad&
    \mrm{Fix}_G:\mathcal{PS}(M)&\rightarrow \mathbf{A}(M)
\end{align*}
where $\mrm{Fix}_M(K)=\{g \in G: \forall m \in K (g(m)=m)\}$ for all $K \in \mathbf{A}(M)$ and 
$\mrm{Fix}_G(H)=\{m \in M: \forall h \in H (h(m)=m)\}$ for all $H \in \mathcal{PS}(M)$.


\noindent The map $\mrm{Fix}_M$ is well defined and $\mrm{Fix}_M(K)=G_{(K)}$ by the definition of pointwise stabilizer.

\noindent We prove that the map $\mrm{Fix}_G$ is well defined and $\mrm{Fix}_G(G_{(K)})=K$. Clearly, $\mrm{Fix}_G(G_{(K)})\supseteq K$. Conversely, let $m \in \mrm{Fix}_G(G_{(K)})$, then $\mathcal{O}(m/K)=\{m\}$, thus finite. Since $K$ is algebraically closed, $m \in K$. Therefore,  $\mrm{Fix}_G(G_{(K)})\subseteq K$. 
Since $$\mrm{Fix}_M(\mrm{Fix}_G(G_{(K)}))=G_{(K)}\text{ and } \mrm{Fix}_G(\mrm{Fix}_M(K))=K,$$ we have a definable Galois correspondence between $\mathcal{PS}(M)$ and $\mathbf{A}(M)$.
\medskip

\noindent
Concerning item (2), it is a consequence of items (1) and (2) of Theorem \ref{main_theorem} with $k=\omega$.
The last item, (3), is nothing other than item (3) of Theorem \ref{main_theorem} for $k=\omega$.
\end{proof}


