\section{When are our assumptions satisfied?}\label{section4}

In this section, we identify sufficient conditions under which the assumptions in~\ref{hyp_intro} are satisfied.
Throughout this section, we write $AB$ to denote  $A \cup B$. 

\begin{definition} Let $M$ be a structure.
	\begin{enumerate}[(1)]
	\item $a \in M$ is algebraic  over $A \subseteq M$ if $M\models \phi(a)\land \exists^{=k} x \phi(x)$ holds for a formula $\phi(x) \in L(A)$ (the language of $A$) and some positive integer $k$. 
	\item The algebraic closure of $A \subseteq M$, denoted by $\mrm{acl}_M(A)$, is the set of elements of $M$ which are algebraic over $A$.
\end{enumerate}
\end{definition}

\begin{hypothesis}\label{hyp_sec4} Throughout this section, let $M$ to be a countable structure in a countable language such that, for every $A\subseteq_\omega M$, $\mrm{acl}_M(A)=\mrm{acl}^\mrm{g}_M(A)$. Also, let $G = \mrm{Aut}(A)$.
 \end{hypothesis}

\begin{notation}
    We denote the algebraically closed set for $\mrm{acl}_M$ as  $\mrm{acl}_M$-closed set.
    Since we suppose that \ref{hyp_sec4} holds, it is harmless to identify the set of finitely generated  $\mrm{acl}_M$-closed sets with $\mathbf{A}(M)$.
\end{notation}


\begin{definition} \label{rkdef}
    Let $\mrm{rk}$ be an integer-valued function  defined on $\mathcal{P}(M)$. %We can extend it to any $A\subseteq M$ as $\mrm{rk}(A)=\mrm{max}\{\mrm{rk}(B): B\subseteq_\omega A\}$.  
    We say that $\mrm{rk}$ is a dimension function on $M$ if, for all $A,B \in \mathbf{A}(M)$ and $C\subseteq M$ we have:
    \begin{enumerate}[(1)]
        \item $\mrm{rk}(g(C))=\mrm{rk}(C)$ for all $g \in G$;
        \item $0\leq \mrm{rk}(A) \leq \mrm{rk}(AB)\leq \mrm{rk}(A) + \mrm{rk}(B)- \mrm{rk}(A\cap B)$;
        \item If $A \subseteq B$ and $\mrm{rk}(A)=\mrm{rk}(B)$, then $A=B$;
        \item $\mrm{rk}(A)<\omega$.
    \end{enumerate} 
    If $A,B \subseteq M$, then we define $\mrm{rk}(A/B)=\mrm{rk}(AB)-\mrm{rk}(B)$. 
\end{definition}

We will need the notion of stationary independence relation from \cite{stationary_indep}.

\begin{definition}\label{stationary}
We say that the ternary relation $\ind$ on $\mathcal{P}(M)$ is a stationary independence relation compatible with $\mrm{acl}_M$ if for every $A,B,C,D \in \mathbf{A}(M)$, $\mrm{acl}_M$-closed set $E$ and finite tuples $a,b \in M^{< \omega}$ the following conditions are met:
    \begin{enumerate}[(1)]
        \item (Compatibility) We have $a\ind_b C \Leftrightarrow a\ind_{\mrm{acl}_M(b)} C$ and $$a\ind_B C \Leftrightarrow e \ind_B C  \text{ for all } e \in \mrm{acl}_M(a,B)\Leftrightarrow \mrm{acl}_M(a,B)\ind_B C.$$
        \item (Invariance) If $g \in G$ and $A\ind_B C $, then $g(A)\ind_{g(B)} g(C)$.
        \item (Monotonicity) If $A\ind_B CD$, then $A\ind_B C$ and $A\ind_{BC} D$ and if $A\ind_B CE$, then $A\ind_B C$.
        \item (Transitivity) If $A\ind_B C$ and $A\ind_{BC} D$, then $A \ind_B CD$.
        \item (Symmetry) If $A\ind_B C$, then $C \ind_B A$.
        \item (Existence) There is $g \in G_{(B)}$ with $g(A) \ind_B C$.
        \item (Stationary) Suppose $B\subseteq A,D$, $A\ind_B C$ and $D\ind_B C$. If $h:A\rightarrow D$ is the identity of $B$ and extends to an automorphism of $M$, then there is some $k \in \mrm{Aut}(M)$ such that $k\supseteq h \cup \mrm{id}_C$.
    \end{enumerate}
\end{definition}

    \begin{definition} We define $A \rkindep[B] C \Leftrightarrow \mrm{rk}(A/BC)=\mrm{rk}(A/B)$.
\end{definition}

    \begin{convention} Below when we write ``Suppose that $\rkindep$ is a stationary independence relation'' we mean ``$\rkindep$ is a stationary independence relation compatible with $\mrm{acl}_M$''.
\end{convention}


\begin{proposition}\label{prop_TPP}
    Suppose that $\rkindep$ is a stationary independence relation. Then $M$ satisfies \ref{hyp_intro}(\ref{hyp_1b}).
\end{proposition}
\begin{proof}
    Let $A,B\in \mathbf{A}(M) $ such that $A\nsubseteq B$. By Existence there is $g \in G_{(B)}$ such that $g(A) \ind_{B} A$. By Existence there is $h \in G_{(A\cup B)}$ such that $h(g(A)) \ind_{AB} g(A)$. By Symmetry, we have $g(A) \ind_{AB} h(g(A))$. We prove that $g$ and $h$ witness \ref{hyp_intro}(1). In fact, $g \in G_{(B)}$ and $h \in G_{(A\cup B)}\subseteq G_{(A)}$ and $g^{-1}hg(A)\neq A$ as we can prove by contradiction. Suppose $g^{-1}hg(A)= A$, therefore we have: 
    \begin{align*}
        0&=\mrm{rk}(g(A)/h(g(A))AB))=\mrm{rk}(g(A)/AB)\\&=\mrm{rk}(g(A)/B)=\mrm{rk}(g(A)B)-\mrm{rk}(B)=\mrm{rk}(AB)-\mrm{rk}(B).
    \end{align*}
Then by \ref{rkdef}(3), we have that $A\cup B=B$, i.e., $A=B$, a contradiction.     

\end{proof}

\begin{definition}\label{def_WCB}
    Let $A, B \in \mathbf{A}(M)$, we say that $C$ is the weak canonical base for the pair $(A, B)$ if it is the smallest set in $\mathbf{A}(M)$ such that $A\ind_C B$ and we denote it by $\mrm{cb}(A/B)$ (so in particular when we write this we implicitly assume that such a $C$ exists). We say that $M$ has weak canonical bases (for $\ind$) if every pair $(A,B)$, where $A \in \mathbf{A}(M)$ and $B$ is an $\mrm{acl}_M$-closed set, admits a weak canonical base.
\end{definition}



\begin{theorem}\label{lascar_ind_th} Suppose $\rkindep$ is a stationary independence relation.
    \begin{enumerate}[(1)]
        \item For every $A, B \in \mathbf{A}(M)$, if $A \rkindep_{A \cap B} B$, then $G_{(A\cap B)}=\langle G_{(A)} \cup G_{(B)} \rangle$.

        \item Suppose (in addition) that $M$ has weak canonical bases. Then, for every $A, B \in \mathbf{A}(M)$, $G_{(A\cap B)}=\langle G_{(A)} \cup G_{(B)} \rangle$.
    \end{enumerate}
\end{theorem}
\begin{proof} 
        We prove item (1). We show the containment from left to right, since the other one is immediate. Let $g \in G_{(A\cap B)}$. By Existence, there is $ h\in 
        G_{(A \cap B)}$ s.t.:
        \begin{equation*}\tag{$\star_9$}\label{equation_label1}
            h(A)\textstyle\rkindep_{A\cap B} ABg(A). 
        \end{equation*}
        The automorphism $h: A \mapsto h(A)$ fixes $A\cap B$, $A \rkindep_{A \cap B} B$ by hypothesis and $h(A) \rkindep_{A \cap B} B$ by (\ref{equation_label1}) and Monotonicity. So, by Stationarity, there is $k \supseteq h \cup \mrm{id}_B$, i.e., $k \in G_{(B)}$ and $k(A)=h(A)$. The subgroup $G_{(K)} \leq \langle G_{(A)} \cup G_{(B)} \rangle$ where $K=k(A)$. Indeed, every $f \in G_{(K)}$, can be written as:
        \begin{equation*}
            f= \underbrace{k}_{\in G_{(B)}} \underbrace{k^{-1} f k}_{\in G_{(A)}} \underbrace{k^{-1}}_{\in G_{(B)}}.
        \end{equation*}
        The automorphism $g: A \mapsto g(A)$ fixes $A\cap B$, and the following two independence relations $A \rkindep_{A \cap B} k(A)$ and $g(A) \rkindep_{A \cap B} k(A)$ are guaranteed by (\ref{equation_label1}), $h(A)=k(A)$, Symmetry, and Monotonicity. 
        So, by Stationarity, there is $t \supseteq g \cup \mrm{id}_K$, i.e., $t \in G_{(K)}$ and $t(A)=g(A)$. The automorphism $t^{-1}g \in G_{(A)}$, therefore $g \in \langle G_{(A)} \cup G_{(B)} \rangle$.


    \medskip \noindent
        Concerning item (2), this is by induction on $n=\mrm{rk}(A/A\cap B) - r(A/B)$. The base    case $n=0$ implies $A \rkindep_{A \cap B} B$, so it holds by (1). 
        Let $H=\langle G_{(A)} \cup G_{(B)} \rangle$. Suppose $A \nrkindep_{A \cap B} B$ and let $C=\mrm{cb}(A/B)$. By Existence, $A \rkindep_B B$, so, by definition $C\subseteq B$ and $A\rkindep_C B$. By Existence, there is $g \in G_{(B)}$ such that $g(A) \rkindep_B AB$. Let $A'=g(A)$ and note that $A\cap B=A' \cap B$. By Invariance, $g(A) \rkindep_{g(C)} g(B)$, i.e., $A'\rkindep_C B$ and, by Transitivity, $A'\rkindep_C B$ and $A'\rkindep_{BC} AB$ imply $A'\rkindep_C AB$. 


        \noindent Note that we have $A\cap B\subseteq A \cap A'$. Let $D=\mrm{cb}(A/A'\cap A)$ that, as above, $D \subseteq A$. From $g(A) \rkindep_B AB$ , by Monotonicity, $A\rkindep_B A'\cap B$. So $D\subseteq B$, in particular, $D\subseteq A\cap B$. Using $A\cap B\subseteq A\cap A' $ and Monotonicity, $A\rkindep_C A'\cap A$ implies $A\rkindep_{A\cap B} A'\cap A$. In terms of rank, this implies $\mrm{rk}(A\cap A')=\mrm{rk}(A\cap B)$. By \ref{rkdef}(3) we have $A\cap B = A \cap A'$.


        \noindent Suppose $A'\rkindep_A B$. By Transitivity, $A'\rkindep_A AB$ and hence we have that $C':=\mrm{cb}(A'/\mrm{acl}_M(AB)) \subseteq A$. But also for $C'\subseteq C \subseteq B$. So $C'\subseteq A\cap B=A'\cap B$ and by Monotonicity, $A' \rkindep_{A'\cap B} B$. By Invariance, we have $A\rkindep_{A\cap B} B$, which contradicts what we are assuming.


        \noindent So we know that $A'\nrkindep_A B$ and, by Symmetry, $B\nrkindep_A A'$. In terms of the rank, this implies
        $$\mrm{rk}(B/AA')<\mrm{rk}(B/A)$$ so by definition $$\mrm{rk}(AA'B)-\mrm{rk}(AA') < \mrm{rk}(AB)-\mrm{rk}(A).$$ Using $\mrm{rk}(A)=\mrm{rk}(A')$ we have
        $$\mrm{rk}(A)+\mrm{rk}(A')-\mrm{rk}(AA')< \mrm{rk}(AB)-\mrm{rk}(AA'B)+\mrm{rk}(A).$$
        The right hand side is $$-\mrm{rk}(A'/AB) +\mrm{rk}(A)= \mrm{rk}(A) - \mrm{rk}(A'/B)=\mrm{rk}(A)-\mrm{rk}(A/B)$$ using the fact that $A'\rkindep _B A$ and $\mrm{rk}(AB)=\mrm{rk}(A'B)$. So putting this together and using $A\cap B = A \cap A'$:
        $$\mrm{rk}(A)+\mrm{rk}(A')-\mrm{rk}(A\cap A') -\mrm{rk}(AA') < \mrm{rk}(A/A\cap B)-\mrm{rk}(A/B) =n. $$ Thus $\mrm{rk}(A/A\cap A') - \mrm{rk}(A/A') <n$. As $G_{(A)}$,$G_{(A')}\leq H$ and $A\cap A'=A\cap B$, we can conclude by induction that $H=G_{(A\cap B)}$.
\end{proof}

\begin{theorem}\label{th_Lascar_baguette}
    Let $M$ be a countable structure satisfying the following conditions:
    \begin{enumerate}[(1)]
        \item there is no strictly decreasing sequence $A_0 \supsetneq A_1 \supsetneq \dots \supsetneq A_n \supsetneq \dots$ where each $A_n \in \mathbf{A}(M)$.
        \item for every $A, B \in \mathbf{A}(M)$, $G_{(A\cap B)}=\langle G_{(A)} \cup G_{(B)} \rangle$.
\end{enumerate}
Then $M$ satisfies \ref{hyp_intro}(\ref{hyp_2b}).
\end{theorem}

\begin{remark}
    If $M$ is as \ref{hyp_sec4} and $\rkindep$ is a stationary independence relation, the hypotheses of the Theorem hold. In fact, the first is a consequence of \ref{rkdef}(3)-(4) and the second is the Theorem \ref{lascar_ind_th}.
\end{remark}

\begin{proof}
Let $H \leq G$ be open, then there is a finite $A$ such that $G_{(A)} \leq H$ (see \cite[4.1.5(b)]{hodges}). Hence, $G_{(\mrm{acl^g}_M(A))} \leq G_{(A)} \leq H$, i.e., $H$ contains the pointwise stabilizer of at least one finite dimensional algebraically closed set of $M$. Let $K$ be of smallest dimension with respect to this property, i.e., being contained in $H$. Note that the existence of such a set is guaranteed by the first hypothesis.

\noindent Let $h \in H$ and $K'=h(K)$. Then $G_{(K')} = hG_{(K)}h^{-1} \leq H$ (as $h \in H$ and $G_{(K)} \leq H$). By \ref{rkdef}(1), the ranks of $K$ and $K'$ coincide. Since $G_{(K)} \leq H$ and $G_{(K')} \leq H$, by the second hypothesis, $G_{(K \cap K')} \leq H$. Therefore, $\mrm{rk}(K \cap K')$ has to have dimension $k := \mrm{rk}(K)$, as otherwise, we would contradict the minimality of the dimension of $K$.  
Hence, by \ref{rkdef}(2), we have the following situation:
\begin{equation*}
    \mrm{rk}(KK') \leq \mrm{rk}(K) + \mrm{rk}(K') - \mrm{rk}(K \cap K') = k+k-k = k.
\end{equation*}
Thus $\mrm{rk}(KK') = k$, therefore by \ref{rkdef}(3), we have $K = K'$. So, recalling that $K' = h(K)$, we have $h \in G_{\{K\}}$.
\end{proof}

\section{Applications} \label{sec_applications}

This final section illustrates the breadth of applicability of our framework, we cover $\omega$-categorical theories, strongly minimal theories, and differentially closed fields. As before, below $M$ is always a countable structure in a countable language. The next proposition is essentially \cite[11.4]{zambella}, see also \cite[10.5]{hodges}.

\begin{proposition}\label{acl=aclg}
    Let $M$ be a $\omega$-saturated structure. Then $\mrm{acl}^{\mrm{g}}_M(A)=\mrm{acl}_M(A)$ for every $A\subseteq_\omega M$.
\end{proposition}

\begin{proposition}\label{omega_1.1}
    Let $M$ be an $\omega$-categorical structure. Then $M$ satisfies \ref{hyp_intro}(\ref{hyp_1b}).
\end{proposition}
\begin{proof}
    Every $M$ $\omega$-categorical is saturated (see \cite[4.3.4]{tentziegler}), so  Proposition \ref{acl=aclg} holds.
    Let $K,S \in \mathbf{A}(M)$ such that $S\nsubseteq K$, i.e., there exists $c \in S\setminus K$. By locally Galois finiteness, $K$ and $S$ are finite. By saturation, the orbit $\mathcal{O}(c/K)$ is equivalent to the type $\mrm{tp}(c/K)$. Since $c \notin K$, the orbit is infinite, so there exists $d \in M\setminus \mrm{acl}^{\mrm{g}}_M(K \cup S)$ such that $\mrm{tp}(c/K)=\mrm{tp}(d/K)$. By strongly homogeneity and $\mrm{tp}(c/K)=\mrm{tp}(d/K)$, there exists $g \in G_{(K)}$ such that $g(c)=d$.
    The element $d \notin S$, therefore there exists $e \in M$ such that $e\neq d,g^{-1}(c)$ and $\mrm{tp}(e/S)=\mrm{tp}(d/S)$.
    For the same reasons, since $\mrm{tp}(e/S)=\mrm{tp}(d/S)$, there exists $h \in G_{(S)}$ such that $h(d)=e$.
    Then, $g$ and $ h$ witness \ref{hyp_intro}(1), since $g^{-1}hg(c)\neq c$, i.e., $g^{-1}hg \notin G_{\{S\}}$.
\end{proof}
Thus, by \ref{omega_1.1}, every $\omega$-categorical structure with weak elimination of imaginaries has the Lascar Property, since the property of weak elimination of imaginaries  is equivalent to \ref{hyp_intro}(\ref{hyp_2b}) in the $\omega$-categorical framework (see e.g. \cite{Paolini_BLMS} and references therein). Thus, our framework generalizes the framework of \cite{Paolini_BLMS}.

\medskip \noindent Let us now move on to the strongly minimal case, one of the main motivations of this paper. 

\begin{definition}
    We say that $(X,\mrm{cl})$ is a pregeometry if $X$ is a set and $\mrm{cl}: \mathcal{P}(X) \rightarrow \mathcal{P}(X)$ is a function satisfying the following five properties for every subsets $A,B$ of $X$ and $a,b \in X$:
    \begin{enumerate}[(1)]
        \item (Reflexivity) $A\subseteq \mrm{cl}(A)$;
        \item (Monotonicity) if $A\subseteq B$ we have $\mrm{cl}(A)\subseteq \mrm{cl}(b)$;
        \item (Finite Character) If $a \in \mrm{cl}(A)$ then there is $A'\subseteq_\omega A$, such that $a \in \mrm{cl}(A')$;
        \item (Idempotency) $\mrm{cl}(\mrm{cl}(A)=\mrm{cl}(A)$;
        \item (Exchange Property) if $a \in \mrm{cl}(A \cup \{b\})$ but $a \notin \mrm{cl}(A)$, then $b \in \mrm{cl}(A \cup \{a\})$.
    \end{enumerate}
    Furthermore, $(X,\mrm{cl})$ is a geometry if, for every $a \in X$, we have: 
    \begin{enumerate}[(6)]
        \item $\mrm{cl}(\{a\})=\{a\}$.
    \end{enumerate}
\end{definition}
\begin{definition}
    An automorphism of the pregeometry (or a geometry)  $(X,\mrm{cl})$ is a bijection $f:X\rightarrow X$ such that $f(\mrm{cl}(A))=\mrm{cl}(f(A))$  for any $A\subseteq X$.
\end{definition}


It is well known that, if $M$ is a strongly minimal structure, then $(M, \mrm{acl}_M)$ is a pregeometry (see e.g. \cite[5.7.5]{tentziegler}) and so, by \ref{acl=aclg}, if $M$ is a countable saturated strongly minimal structure, then also $(M, \mrm{acl}^{\mrm{g}}_M)$ is a pregeometry. 
Letting Morley be our dimension function and non-forking as our $\rkindep$ relation, the hypotheses from Section~\ref{section4} hold in a countable saturated strongly minimal structure with weak elimination of imaginaries (see Chapter 6 and 8 of \cite{marker2}). In particular, they hold for countable saturated algebraically closed fields and countably infinite dimensional $\mathbb{K}$-vector spaces, for $\mathbb{K}$ a countable field. In fact, they both have weak elimination of imaginaries, see e.g. \cite[16.21]{poizat} for algebraically closed fields and \cite[4.4.7]{hodges} for vector spaces.


We will also consider an example outside of the strongly minimal context, namely: the differentially closed fields. As usual, we denote by $\mrm{DCF}_0$ the theory of differentially closed fields of characteristic $0$.

\begin{fact}
    If $M\models\mrm{DCF}_0$, then $\mrm{acl}_M$  is a pregeometry (see \cite[pag.~2]{konnerth}), recalling that $\mrm{DCF}_0$ has elimination of quantifiers (see \cite[2.4]{marker}). Since the theory $\mrm{DCF}_0$ is $\omega$-stable  (see \cite[Lemma 2.8]{marker}), there exists a countable saturated model of $\mrm{DCF}_0$ (see \cite[Lemma 5.2.9]{tentziegler}).
\end{fact}


\begin{proposition}
    Let $M\models \mrm{DCF}_0 $ be a countable and saturated model. Then $M$ has the Lascar Property (cf. \ref{hyp_intro}).
\end{proposition}

\begin{proof}
    Since $M$ is assumed to be saturated, then, by \ref{acl=aclg}, $\mrm{acl^g}_M = \mrm{acl}_M$. Furthermore, since $(M,\mrm{acl^g}_M)$ is a pregeometry and $M$ is saturated, then the dimension function associated to $(M, \mrm{acl}_M)$ is infinite (see \cite[12.1 Remark(2)]{rothmaler}).  

    \smallskip \noindent We first show \ref{hyp_intro}(1). To this extent, let $K,S \in \mathbf{A}(M)$ be such that $S\nsubseteq K$, i.e., there exists $c \in S\setminus K$. Since the dimension is infinite, there exists $d \in M\setminus (K \cup S)$. We can construct an isomorphism $g$ of $M$ such that $K$ is fixed pointwise and $g(c)=d$ (as in \cite[Lemma 2.3]{marker}). We can also construct an automorphism $h$ of $M$ such that $S$ is fixed pointwise and $h(d) \notin \{d,  g^{-1}(c)\}$, this exists by the assumption of infinite dimensionality. So, $g$ and $h$ witness \ref{hyp_intro}(1), because $g \in G_{(K)}$, $h \in G_{(S)}$ and  $g^{-1}hg(c)\neq c$, i.e., $g^{-1}hg \notin G_{\{S\}}$. Thus, \ref{hyp_intro}(1) holds indeed.

    \noindent Finally, concerning \ref{hyp_intro}(2), this follows from Theorem~\ref{th_Lascar_baguette}. In fact, $M$ satisfies the first hypothesis of \ref{th_Lascar_baguette} because $\mrm{acl^g}_M$ is a pregeometry (and so each $A_0 \in \mathbf{A}(M)$ has finite dimension), and the second hypothesis is Lemma 2.24 of \cite{konnerth}.
\end{proof}

\begin{remark}\label{kmpregeometriequal1}
     If $(M,\mrm{acl}^{\mrm{g}}_M)$ is a pregeometry then $k_M=1$ (cf. \ref{kM_notation}). In fact, suppose there exists $a,b \in M$ such that $\mrm{acl}^{\mrm{g}}_M(\emptyset)\subsetneq \mrm{acl}^{\mrm{g}}_M(a)\subseteq \mrm{acl}^{\mrm{g}}_M(b)$. Since $a \in \mrm{acl}^{\mrm{g}}_M(b)\setminus \mrm{acl}^{\mrm{g}}_M(\emptyset)$, by the Exchange Property, $b \in \mrm{acl}^{\mrm{g}}_M(a)$. Therefore $\mrm{acl}^{\mrm{g}}_M(b)\subseteq \mrm{acl}^{\mrm{g}}_M(\mrm{acl}^{\mrm{g}}_M(a))=\mrm{acl}^{\mrm{g}}_M(a)$ by Idempotency. 
\end{remark}

The canonical geometry of $(M,\mrm{acl}^{\mrm{g}}_M )$ is $(\mathbb{G}_M,\mrm{cl}_{\mathbb{G}_M})$ where $\mathbb{G}_M=\{\mrm{acl}^{\mrm{g}}_M(a): a\in M\setminus \mrm{acl}^{\mrm{g}}_M(\emptyset) \}$ and $\mrm{cl}_{\mathbb{G}_M}(X)=\{K \in \mathbb{G}_M: K\subseteq \mrm{acl}^{\mrm{g}}_M(\bigcup X)\}$ for every $X\subseteq \mathbb{G}_M$.

\begin{lemma}\label{canonicalmaplemma}
  Let $M$ be a countable structure with the Lascar Property and such that $\mathbb{G}_M = (M,\mrm{acl}^\mrm{g}_M)$ is a pregeometry. Then there exists a canonical map $\pi$ from $\mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))$ into $\mrm{Aut}(\mathbb{G}_M)$.
\end{lemma}

\begin{proof}
    By Remark \ref{kmpregeometriequal1} and Theorem \ref{main_theorem}(3), there is a well defined  group isomorphism $\psi$ from $\mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))$ into $\mrm{Aut}(\mathcal{E}^{{\mrm{ex}}}_M(1))$.

    \smallskip
    \noindent Let $\alpha \in \mrm{Aut}(\mathcal{E}^{{\mrm{ex}}}_M(1))$. Recalling Proposition \ref{char_point_stab_singletons} and Theorem \ref{main_theorem}, we can  define a map $\xi_\alpha$ from $\mathbb{G}_M$ onto itself by: for every $K \in \mathbb{G}_M$ $\xi_\alpha(K)=K'$ where $\alpha(K,\mrm{id}_K,K)=(K',\mrm{id}_{K'},K')$. It is easy to see that $\xi_\alpha \in \mrm{Aut}(\mathbb{G}_M)$ and the map $\xi$ from $\mrm{Aut}(\mathcal{E}^{{\mrm{ex}}}_M(1))$ into $\mrm{Aut}(\mathbb{G}_M)$ defined by $\xi(\alpha)=\xi_\alpha$ is a group homomorphism.\smallskip


    \noindent Then $\pi=\xi\circ\psi$ is the natural group homomorphism from $\mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))$ into $\mrm{Aut}(\mathbb{G}_M)$ we are looking for.
\end{proof}


\begin{theorem1.3} Let $M$ be a countable structure with the Lascar Property (cf \ref{hyp_intro}) and suppose that $\mathbb{G}_M = (M,\mrm{acl}_M^{\mrm{g}})$ is a pregeometry. Then there exists a canonical map $\pi$ from $\mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))$ into $\mrm{Aut}(\mathbb{G}_M)$. Suppose further there is $\mrm{Aut}(M)\leq H \leq \mrm{Sym}(\omega)$ such that for every $g \in \mrm{Aut}(\mathbb{G}_M)$ there exists $\hat{g} \in H$ satisfying:
    \begin{enumerate}[(1)]
    \item for every $A \in \mathbf{A}(M)$ and $h \in H$, $h(A) \in \mathbf{A}(M)$; and the map $A \mapsto h(A)$ induces a homomorphism $\phi_H$  from $H$ onto $\mrm{Aut}(\mathbb{G}_M)$; 
            \item for every $h \in H$, $h(\cdot)h^{-1} \in \mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))$;
    		\item the map $g \mapsto \hat{g}$ is a homomorphism;
        \item $\pi(\hat{g}(\cdot)\hat{g}^{-1})=g$.
    \end{enumerate}
    In fact, more precisely, we have that the following diagram commutes:
    $$\begin{tikzcd}
    H \arrow[r, "\phi_H"] \arrow[d, "\gamma"]
    & \mrm{Aut}(\mathbb{G}_M) \\
    \mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M)) \arrow{ur}{\pi} 
    &
    \end{tikzcd}$$ where $\gamma$ is conjugation; and $\mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))\cong \mrm{ker}(\pi) \rtimes \mrm{Aut}(\mathbb{G}_M)$.
    \end{theorem1.3}

\begin{proof}
    Recall $\pi$, $\psi$ and $\xi$ introduced in the proof of Lemma \ref{canonicalmaplemma}.
    Let then $\gamma: H \rightarrow \mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))$ be the map from item (2), then, easily, the diagram  $$\begin{tikzcd}
    H \arrow[r, "\phi_H"] \arrow[d, "\gamma"]
    & \mrm{Aut}(\mathbb{G}_M) \\
    \mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M)) \arrow{ur}{\pi} \arrow[r,"\psi" ,"\cong"']
    & \mrm{Aut}(\mathcal{E}^{{\mrm{ex}}}_M(1)) \arrow[u, "\xi" ]
    \end{tikzcd}$$ commutes. In fact, let $h \in H$. Then for all $K \in \mathbb{G}_M$ $\xi\psi\gamma(h)(K)$ is the element $K'$ of $\mathbb{G}_M$ such that:
    $$(K',\mrm{id}_{K'},K')=(\psi\gamma(h))(K,\mrm{id}_K,K)=(h(K),\mrm{id}_{h(K)},h(K))$$
    recalling the proof of Theorem \ref{main_theorem}(1). Therefore, $\phi_H(h)(K)=h(K)=(\xi\psi\gamma)(h)(K)$.\smallskip

    \smallskip \noindent  
    Observe now that we have the following exact sequence:
    $$1\rightarrow \mrm{ker}(\pi) \rightarrow \mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M)) \overset{\pi}{\rightarrow} \mrm{Aut}(\mathbb{G}_M). $$ We prove that it is a split exact sequence.
    By items (3) and (4), for every $g \in \mrm{Aut}(\mathbb{G}_M)$, we have that $\pi(\hat{g}(\cdot)\hat{g}^{-1})=g$. Hence, the map $g\mapsto \hat{g}(\cdot)\hat{g}^{-1}$ is a section of $\pi$, so we are done.
\end{proof}


    \begin{notation}\label{notation_phi} Suppose that $M$ is such that $\mathbb{G}_M = (M,\mrm{acl}^\mrm{g}_M)$ is a pregeometry. Let $\alpha \in \mrm{Aut}(M)$. Then $\alpha$ naturally induces a map $\phi_\alpha$ from $\mathbb{G}_M$ onto itself by: $\phi_\alpha(K)=\alpha(K)$, and it is clear that $\phi_\alpha \in \mrm{Aut}(\mathbb{G}_M)$. Moreover, the map $\phi$ from $\mrm{Aut}(M)$ to $\mrm{Aut}(\mathbb{G}_M)$ defined by $\phi(\alpha)=\phi_\alpha$ is a group homomorphism and we call it the natural map from $\mrm{Aut}(M)$ to $\mrm{Aut}(\mathbb{G}_M)$.
\end{notation}

\begin{lemma}\label{phiinjective}
    Let $M$ and $H$ be as in the hypotheses of the Theorem \ref{genevansth}.
    If the map $\phi$ from \ref{notation_phi} is injective, then $\mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))\cong \mrm{Aut}(\mathbb{G}_M)$ (and if $M$ has $\mrm{SIP}$, then ``top'' can be removed).
\end{lemma}

\begin{proof}
    Recalling from Lemma \ref{canonicalmaplemma} that $\pi=\xi\circ\psi$. Since $\psi$ is an isomorphism, $\pi$ is injective if and only if $\xi$ is injective, hence, in order to conclude, it suffices to show that $\xi$ is injective, we do this.\smallskip


    \noindent Let $\alpha \in \mrm{Aut}(\mathcal{E}^{{\mrm{ex}}}_M(1))$, and assume that $\xi_\alpha$ is the identity on $\mathbb{G}_M$ that is we have $\alpha((K,\mrm{id}_K,K))=(K,\mrm{id}_K,K)$. We have to prove that $\alpha$ is the identity on $\mathcal{E}^{{\mrm{ex}}}_M(1)$. Let $(K,p,K') \in \mathcal{E}^{{\mrm{ex}}}_M(1)$. By definition, exists $g \in \mrm{Aut}(M)$ such that $(K,p,K')=(K,g\upharpoonright K,g(K))$. Let $g_\alpha=\psi^{-1}(\alpha)$. Then $\alpha((K,p,K'))=(K,g_\alpha\upharpoonright K, g_\alpha(K))$.By the $\mrm{Cod}$ predicate, we have that $g(K)=g_\alpha(K)$. So $g^{-1}g_\alpha(K)=K$. This means exactly that $\phi(g^{-1}g_\alpha)$ is the identity on $\mathbb{G}_M$. By hypothesis, $\phi$ is injective, so $g^{-1}g_\alpha$ is the identity. Therefore, $\alpha((K,g\upharpoonright K,K'))=(K,g\upharpoonright K, K')$, i.e., $\alpha$ is the identity.\smallskip

    \noindent Hence, $\xi$ is injective, and so $\pi$ is injective as well. By Theorem \ref{genevansth}, $\mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))\cong \mrm{ker}(\pi) \rtimes \mrm{Aut}(\mathbb{G}_M)$, and we are done.
\end{proof}

\begin{corollary1.5}Let $M \models \mrm{DCF}_0$ be countable and saturated, then we have:
$$\mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))\cong \mrm{Aut}(\mathbb{G}_M).$$
\end{corollary1.5}

\begin{proof} We now show that the hypotheses of \ref{genevansth} and \ref{phiinjective} are satisfied.
    We denote by $H = \mrm{Aut}^-(M)$ the pure field automorphisms of $M$ that induce automorphisms on $\mathbb{G}_M$. These are exactly the field automorphisms $g$ such that $x \in  \mrm{acl}_M(\bar{y}) $ if and only if $g(x) \in  \mrm{acl}_M(g(\bar{y}))$. Obviously, the map $A \mapsto h(A)$, for $A \in \mathbf{A}(M)$, induces a homomorphism $\phi_H$  from $H$ into $\mrm{Aut}(\mathbb{G}_M)$, and this map is a homomorphism. Moreover, $\phi_H$ extends the map $\phi$ in \ref{notation_phi}. 
By \cite[4.8]{konnerth}, the map $\phi_H$ is bijective. Therefore, $\phi$ is injective and it satisfies \ref{genevansth}(1).  
\smallskip

    \noindent Call $\gamma$ the homomorphism from $H$ into $\mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))$, defined by:  for $h \in H$ and $g \in \mrm{Aut}(M)$, $\gamma(h)(g) = hgh^{-1}$ (that is, $\gamma(h)$ is conjugation by $h$). This is well defined since $H$ normalizes $\mrm{Aut}(M)$ (see \cite[4.10]{konnerth}). Thus, \ref{genevansth}(2) is satisfied. \smallskip

    \noindent Hence, by Lemma \ref{phiinjective} taking $H=\mrm{Aut}^-(M)$ and $\hat{g}=\bar{\phi}^{-1}(g)$ we have that:
    $$\mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))\cong \mrm{Aut}(\mathbb{G}_M).$$
\end{proof}

\begin{lemma}\label{evcompl}
    Let $M$ be a countable structure with the Lascar Property and suppose that $\mathbb{G}_M =(M,\mrm{acl}_M^g)$ is a pregeometry.
    If the map $\phi$ from \ref{notation_phi} is an isomorphism, then $\mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))\cong \mrm{Aut(\mathbb{G}_M)}$. Moreover, every topological automorphism of $\mrm{Aut}(M)$ is inner (and if in addition $M$ has $\mrm{SIP}$, then ``topological" can be removed in ``topological automorphism" and $\mrm{Aut}(\mrm{Aut}(M))\cong \mrm{Aut(\mathbb{G}_M)}$). 
\end{lemma}

\begin{proof} Obviously, taking $H=\mrm{Aut}(M)$ and $\hat{g}=\phi^{-1}(g)$, we are under the hypotheses of Theorem \ref{genevansth}. Furthermore, clearly, the map $g\mapsto \hat{g}$ is a group homomorphism and $\hat{g}(\cdot)\hat{g}^{-1} \in \mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))$. Recall the following commutative diagram:

$$\begin{tikzcd}
    \mrm{Aut}(M) \arrow[r, "\phi","\cong"'] \arrow[d, "\gamma"]
    & \mrm{Aut}(\mathbb{G}_M) \\
    \mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M)) \arrow{ur}{\pi} \arrow[r,"\psi" ,"\cong"']
    & \mrm{Aut}(\mathcal{E}^{{\mrm{ex}}}_M(1)) \arrow[u, "\xi" ]
    \end{tikzcd}$$\smallskip

     \noindent By the commutativity of the diagram $\pi(\hat{g}(\cdot)\hat{g}^{-1})=g$. By Lemma \ref{phiinjective}, $\xi$ is injective and  $\mrm{Aut}_{\mrm{top}}(\mrm{Aut}(M))\cong \mrm{Aut(\mathbb{G}_M)}$.\smallskip

    \noindent The map $\phi$ is surjective, so $\xi$ is also surjective. Thus $\xi$ is an isomorphism group. The map $\gamma=\psi^{-1}\xi^{-1}\phi$ is surjective, that is, every automorphism is inner.
\end{proof}

 \begin{corollary1.4} Let $M\models \mrm{ACF}_0$ be countable and saturated, then we have:
    $$\mrm{Aut}(\mrm{Aut}(M))\cong \mrm{Aut}(\mathbb{G}_M),$$
and automorphisms of $\mrm{Aut}(M)$ are \mbox{inner (so $\mrm{Aut}(M)$, being centerless, is complete).}
\end{corollary1.4}

\begin{proof}
    First, concerning $\mrm{SIP}$, see \cite[Theorem~2]{Evans_ACF}. Concerning the injectivity of the map $\phi$, this follows from the remark soon after Lemma 2.5 of \cite{evan1995}, while the surjectivity follows from Theorem A of \cite{evan1995}.    
    \noindent By Lemma \ref{evcompl},  we have that $\mrm{Aut}(\mrm{Aut}(M))\cong \mrm{Aut(\mathbb{G}_M)}$ and every automorphism of $\mrm{Aut}(M)$ is inner.

\end{proof}



\begin{remark}
    Let $\mathbb{K}$ be a field and let $V$ be a non-trivial $\mathbb{K}$-vector space. Then the map $\phi$ from \ref{notation_phi} is not injective. In fact, let $\alpha \in \mrm{Aut}(V)$ be such that $v \mapsto kv$ with $k \in \mathbb{K^\times}$ and $v \in V$.
    Then, $\phi_\alpha$ is the identity in $\mathbb{G}_V$.
\end{remark}

\begin{definition}Let $V$ a $\mathbb{K}$-vector space. A semilinear automorphism of $V$ is a bijection $f$ from $V$ into itself for which there exists $\tau \in \mrm{Aut}(\mathbb{K})$ such that, for every $c_1,c_2 \in \mathbb{K}$ and $v_1,v_2 \in V$, 
$f(c_1v_1+c_2v_2)=\tau(c_1)f(v_1)+\tau(c_2)f(v_2)$.
\end{definition}

\begin{corollary1.6} Let $\mathbb{K}$ be a countable field and let $T_\mathbb{K}$ be the theory of infinite $\mathbb{K}$-vector spaces. Let $M \models T_\mathbb{K}$ be countable and saturated, then we have:
	$$\mrm{Aut}(\mrm{Aut}(M)) \cong \mrm{Aut}(\mathbb{K}^\times) \rtimes \mrm{Aut}(\mathbb{G}_M).$$
\end{corollary1.6}

\begin{proof}
    First of all, notice that $V$ has the small index property (see \cite[Fact 4.2.11]{hodges}).
    Let $H = \mrm{Aut}_{\mrm{SL}}(V)$ be the group of all semilinear automorphisms of $V$. By the Fundamental Theorem of Projective Geometry (see \cite[2.26]{artin}) there exists a homomorphism from $\mrm{Aut}(\mathbb{G}_M)$ into $H$, $g \mapsto \hat{g} \in H$, satisfying all the hypotheses of Theorem~\ref{genevansth}. Therefore, we can apply Theorem \ref{genevansth} and so we have: 
    $$\mrm{Aut}(\mrm{Aut}(M))\cong \mrm{ker}(\pi) \rtimes \mrm{Aut}(\mathbb{G}_V).$$
    \smallskip

    \noindent Now we examine the kernel of $\pi$. Since $\psi$ is an isomorphism, $\mrm{ker}(\pi)\cong\mrm{ker}(\xi)$, where $\xi$ is defined as in the proof of \ref{canonicalmaplemma}. We shall show that $\ker(\xi)\cong \mrm{Aut}(\mathbb{K}^\times)$.\smallskip

    \noindent First of all, recall that the domain of $\mathcal{E}^{\mrm{ex}}_V(1)$ is made of triples $(K, p, K')$ where $p: K \cong K'$ and $K$ is a subspace of dimension $0$ or $1$. 
%Let $|F| = p^n$ and given a copy of the field $F$, let $\phi_K$ be the Frobenius automorphism of $K$. 
Enumerate the subspaces of dimension $1$ of $V$ as $(K_i : i < \omega)$ and, for every $i < \omega$, choose an element $e_i \in K_i \setminus \{0_V\}$. Then any subspace of dimension $1$ has the form $\{ae_i : a \in \mathbb{K} \} =: \mathbb{K}e_i$ for some $i < \omega$, and so any triple $(K, p, K')$ with $p: K \cong K'$ has the form $a e_i \mapsto \lambda_p a e_j$ for some $i, j < \omega$, where $\lambda_p \in \mathbb{K}^\times$. Thus, for the rest of the proof we write arbitrary elements of $\mathcal{E}^{\mrm{ex}}_V(1)$ as $(\mathbb{K}e_i, \lambda, \mathbb{K}e_j)$. 
%Now, given an automorphism $g \in \mrm{P}(V)$ we can define an automorphism of $\mathcal{E}^{\mrm{ex}^+}_M(1)$ as follows:
%\begin{enumerate}[(a)]
%	\item $(\{0 \}, \mrm{id}_{\{0\}}, \{0 \}) \mapsto (\{0 \}, \mrm{id}_{\{0\}}, \{0 \})$;
%	\item $(Fe_i, \lambda, Fe_j) \mapsto (g(Fe_i), \lambda, g(Fe_j))$, where $\lambda \in F^\times$.
%\end{enumerate}
\smallskip

\noindent Let $f \in \mrm{ker}(\xi)$, then for every $i < \omega$, $f$ sends each triple of the form $(\mathbb{K}e_i, \lambda, \mathbb{K}e_i)$ into a triple of the form $(\mathbb{K}e_i, \lambda', \mathbb{K}e_i)$; so, letting $\lambda' = f_i(\lambda)$, for each $i < \omega$, we have a permutation $f_i$ of $\mathbb{K}^\times$. We will show that:
	\begin{enumerate}[(i)]
	\item for every $i < \omega$, $f_i \in \mrm{Aut}(\mathbb{K}^\times)$;
	\item for every $i, j < \omega$, $f_i = f_j$.
	\end{enumerate}

\noindent Let $\alpha$ be a map from $\mrm{ker}(\xi)$ into $\mrm{Aut}(\mathbb{K}^\times)$ defined by $\alpha(f)=f_i$ for a certain $i \in \omega$. Using (i), (ii), it is easy to see that the map is well defined and an isomorphism.\smallskip

\noindent Concerning (i), let $i < \omega$ and $\lambda, \mu \in \mathbb{K}^\times$, then: 
$$\mathbb{K}e_i \xrightarrow{\lambda} \mathbb{K}e_i \xrightarrow{\mu} \mathbb{K}e_i = \mathbb{K}e_i \xrightarrow{\mu\lambda} \mathbb{K}e_i$$
is mapped to:
$$\mathbb{K}e_i \xrightarrow{f_i(\lambda)} \mathbb{K}e_i \xrightarrow{f_i(\mu)} \mathbb{K}e_i = \mathbb{K}e_i \xrightarrow{f_i(\mu\lambda)} \mathbb{K}e_i$$
and so, as $f \in \mrm{Aut}(\mathcal{E}^{\mrm{ex}}_V(1))$, we have that:
$$f_i(\mu\lambda) = f_i(\lambda\mu) = f_i(\lambda)f_i(\mu).$$
Similarly, for $i < \omega$ and $\lambda \in \mathbb{K}^\times$ we have
$$\mathbb{K}e_i \xrightarrow{\lambda} \mathbb{K}e_i \xrightarrow{\lambda^{-1}} \mathbb{K}e_i = \mathbb{K} e_i \xrightarrow{1} \mathbb{K} e_i$$
is mapped to:
$$\mathbb{K}e_i \xrightarrow{f_i(\lambda)} \mathbb{K}e_i \xrightarrow{f_i(\lambda^{-1})} \mathbb{K}e_i = \mathbb{K} e_i \xrightarrow{1} \mathbb{K} e_i$$
and so, as $f \in \mrm{Aut}(\mathcal{E}^{\mrm{ex}}_V(1))$, we have that:
$$f_i(\lambda^{-1} \lambda) = 1 = f_i(\lambda \lambda^{-1}).$$
Concerning (ii), notice that for $\lambda \in \mathbb{K}^\times$ we obviously have that the following holds:
$$\mathbb{K}e_i \xrightarrow{\lambda} \mathbb{K}e_i \xrightarrow{1} \mathbb{K}e_j \xrightarrow{\lambda^{-1}} \mathbb{K}e_j \xrightarrow{1} \mathbb{K} e_i = \mathbb{K} e_i \xrightarrow{1} \mathbb{K} e_i,$$
and so:
$$\mathbb{K}e_i \xrightarrow{f_i(\lambda)} \mathbb{K}e_i \xrightarrow{1} \mathbb{K}e_j \xrightarrow{f_j(\lambda)^{-1}} \mathbb{K}e_j \xrightarrow{1} \mathbb{K} e_i = \mathbb{K} e_i \xrightarrow{1} \mathbb{K} e_i,$$
from which it follows that $f_i(\lambda) f_j(\lambda)^{-1} = 1$ and so $f_i(\lambda) = f_j(\lambda)$, as desired. This concludes the proof of (i), (ii), and thus the proof.
\end{proof}

We observe that the three cases discussed above represent three examples exhibiting distinct behaviors.
Firstly, in the case of vector spaces, the map $\phi$ from \ref{notation_phi} is not injective, which implies that $\mathrm{Aut}(\mathrm{Aut}(M))$ splits with a non-trivial kernel.
Secondly, in the case of differentially closed fields of characteristic $0$, the map $\phi$ is injective but not surjective; while the map $\phi_H$ for $H = \mrm{Aut}^-(M)$ is surjective. This implies that the map $\pi$ is injective, also. Therefore, we have that  $\mathrm{Aut_{top}}(\mathrm{Aut}(M)) \cong \mathrm{Aut}(\mathbb{G}_M)$.  In this case, the group $\mrm{Aut}(M)$ is not complete though, since there are outer automorphisms induced by $H$ (which is in general strictly larger than $\mrm{Aut}(M)$).
Finally, in the setting of algebraically closed fields of characteristic $0$, we have that $\phi$ is actually an isomorphism. The surjectivity of the map $\phi$  gives us also  that the map $\gamma$ is surjective, i.e., every automorphism is inner.  Thus, in this case,
$\mathrm{Aut}(\mathrm{Aut}(M)) \cong \mathrm{Aut}(\mathbb{G}_M)$ and $\mathrm{Aut}(M)$ is complete.

