    \caption{FoB and $\chi_\text{red}^2$ for the Gaussian (blue) and diagonal sample covariance (pink) for the full likelihood from Eq. \eqref{eq:liks} (cf. Figure \ref{fig:fitplot_sst}).}
    \label{fig:allfitplot}
