\section{Theory Expressions for Tree-level Tensor Bispectrum}\label{sec:expr}
The tree-level tensor bispectrum contains a deterministic and a stochastic piece. 
The $n$-th order term in Fourier space for the deterministic piece takes the form
\begin{equation}
    S_{ij}^{(n)}(\mathbf{k}) = \int \md^3\bb{p}_1 \dots \md^3\bb{p}_n\, \mathcal{K}_{ij}^{(n)}(\mathbf{p}_1, \dots \mathbf{p}_n) \delta^D(\mathbf{k}-\mathbf{p}_{1,n}) \delta^{(1)}(\mathbf{p}_1) \dots \delta^{(1)}(\mathbf{p}_n)
\end{equation}
where
\begin{equation}
    \mathcal{K}_{ij}^{(n)} = \mathcal{K}_{ij}^{\text{s},(n)}+\mathcal{K}_{ij}^{\text{g},(n)}
\end{equation}
is the decomposition into trace- and trace-free parts and $\delta^{(1)}$ is the linear matter density field. The total deterministic bispectrum at tree-level considered in this work is thus
\begin{equation}\label{bispec}
\begin{aligned}
B_{ijklrs}^{\alpha \beta \gamma, \text{det,tree}}(\mathbf{k}_1,\mathbf{k}_2,\mathbf{k}_3) 
&= 2\,\mathcal{K}_{ij}^{\alpha,(1)}(\mathbf{k}_1)\mathcal{K}_{kl}^{\beta,(1)}(\mathbf{k}_2)\mathcal{K}_{rs}^{\gamma,(2)}(\mathbf{k}_1,\mathbf{k}_2)P_L(k_1)P_L(k_2)+ \text{2 perm.} 
\end{aligned}    
\end{equation}
where $\alpha,\beta,\gamma$ are either $\delta$ or g. Since we only consider the matter density field in the scalar sector, the scalar kernels are trivial. Explicitly, the first order kernels are given by
\begin{equation}
\begin{aligned}
    \mathcal{K}_{ij}^{\delta,(1)}(\mathbf{k}) &= \frac{1}{3}\delta_{ij}; \\
    \mathcal{K}_{ij}^{\text{g},(1)}(\mathbf{k}) &= b_1^\text{g} \big( \frac{\bb{k}_i\bb{k}_j}{k^2}-\frac{1}{3}\delta_{ij}\big) = b_1^\text{g}\mathcal{D}_{ij}(\bb{k});
\end{aligned}
\end{equation}
where in the second line we introduced the trace-free Fourier space operator $\mathcal{D}_{ij}(\bb{k}) = \bb{k}_i\bb{k}_j/k^2-\frac{1}{3}\delta_{ij} $.
The second order kernels are given by
\begin{equation}\label{eq:secker}
    \begin{aligned}
        \mathcal{K}_{ij}^{\delta,(2)}(\mathbf{k}_1,\bb{k}_2) &= \frac{1}{3}\delta_{ij}F_2(\mathbf{k}_1,\bb{k}_2); \\
        \mathcal{K}_{ij}^{\text{g},(2)}(\mathbf{k}_1,\bb{k}_2) &= \text{TF}\bigg[c_{1}^\text{g} \bigg(\frac{\bb{k}_{12,i}\bb{k}_{12,j}}{k_{12}^2}F_2(\mathbf{k}_1,\bb{k}_2)\bigg) + c_{2,1}^\text{g}\bigg(\frac{\bb{k}_{12,i}\bb{k}_{12,j}}{k_{12}^2}F_2(\mathbf{k}_1,\bb{k}_2)-\frac{1}{2}\frac{\bb{k}_1\cdot \bb{k}_2}{k_1^2k_2^2}(\bb{k}_{1,i}\bb{k}_{1,j}+\bb{k}_{2,i}\bb{k}_{2,j})\bigg) \\
        &+ c_{2,2}^\text{g}\bigg(\frac{1}{2}\frac{\bb{k}_1\cdot \bb{k}_2}{k_1^2k_2^2}(\bb{k}_{1,i}\bb{k}_{2,j}+\bb{k}_{2,i}\bb{k}_{1,j})\bigg) + c_{2,3}^\text{g} \bigg( \frac{\bb{k}_{1,i}\bb{k}_{1,j}}{2k_1^2}+\frac{\bb{k}_{2,i}\bb{k}_{2,j}}{2k_2^2}\bigg)\bigg]
        \end{aligned}
\end{equation}
where $\bb{k}_{12} = \bb{k}_1+\bb{k}_2$ and $F_2$ is the usual the second order scalar kernel.

In the notation of \cite{mirbabayi}, the coefficients $c_1^{\text{g}},c_{2,a}^{\text{g}} (a=1,2,3)$ belong to the trace-free parts of the operators
\begin{equation}
    \Pi^{[1]}_{ij}, \Pi^{[2]}_{ij},(\Pi^{[1]})^2_{ij}, \Pi^{[1]}_{ij}\text{Tr}(\Pi^{[1]}_{ij})
\end{equation} 
respectively. 
We work with a redefinition of shape bias coefficients which is given by 
\begin{equation}
\begin{aligned}
    b_1^\text{g} &=c_1^\text{g}; \qquad b_{2,1}^\text{g} = c_{2,1}^\text{g}+c_{2,2}^\text{g}+c_{2,3}^\text{g}; \qquad b_{2,2}^\text{g} = c_{2,3}^\text{g}+\frac{20}{7}c_{2,1}^\text{g}; 
    \qquad b_{2,3}^\text{g}=c_{2,3}^\text{g}. 
\end{aligned}
\end{equation}
The B-mode does not depend on $b_{2,2}^\text{g}$, which automatically implies that bispectra containing any B-mode do not depend on $b_{2,2}^\text{g}$ at tree level (since the B-mode starts at second order). We also use the relation to another basis used consisting of the operators $b_{\delta K}, b_{K^2}$ and $b_t$, which is 
\begin{equation}
    b_{\delta K} = \frac{1}{3}(2b_{2,1}^\text{g}+b_{2,3}^\text{g}), \quad b_{K^2} = b_{2,1}^\text{g} - b_{2,3}^\text{g}, \quad b_t = \frac{7}{8}(b^\text{g}_{2,3}-b^\text{g}_{2,2}).
\end{equation}
We will need the co-evolution relations for the second order parameters in terms of $b_1^\text{s}$ and $b_1^\text{g}$, which are derived under the assumption that the Lagrangian higher order bias parameters are zero. They read 
\begin{equation}
    b_{2,1}^\text{g} = (b_1^\text{s}-1)b_1^\text{g}; \qquad b_{2,2}^\text{g} = (b_1^\text{s}-20/7)b_1^\text{g}; \qquad b_{2,3}^\text{g} = b_1^\text{s}b_1^\text{g}.
\end{equation}
For the stochastic piece, all the relevant correlators were collected in Paper I. The only nonzero stochastic contribution we can form with the stochastic shape contributions 
\begin{equation}
    g_{ij}^{\text{stoch}}(\bb{x}) \qquad \supset \qquad \epsilon_{ij}(\mathbf{x}) \text{ (first order)}; \qquad \epsilon_{ij}^\delta(\bb{x})\delta(\bb{x}),\quad \epsilon^\Pi(\mathbf{x})\text{TF}(\Pi^{[1]})_{ij}(\bb{x}) \text{ (second order) }
\end{equation}
and which occurs in the projected tree-level bispectrum is
\begin{equation}
    \langle \epsilon_{ij}(\mathbf{k}_1)\epsilon_{kl}^\delta(\mathbf{k}_2)\rangle ' = \alpha_{\text{gg}}^{1\delta}\Delta_{ij,kl}^{\text{TF}}  + \mathcal{O}((k/k_{\text{NL}})^2);
\end{equation}
where 
\begin{equation}
    \Delta_{ij,kl}^{\text{TF}} = \delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}-\frac{2}{3}\delta_{ij}\delta_{kl}
\end{equation}
is pair-symmetric and pair-traceless.
This combination occurs in spectra with two or three tensor fields, specifically as 
\begin{equation}
    \begin{aligned}
        B_{ijkl}^{\delta\text{gg}} &\supset \langle \delta(\bb{k}_1)\epsilon_{ij}(\mathbf{k}_2)(\epsilon_{kl}^\delta\delta)(\mathbf{k}_3)\rangle ' =  \alpha_{\text{gg}}^{1\delta} \Delta_{ij,kl}^{\text{TF}}P_L(k_1) + \mathcal{O}((k_i/k_{\text{NL}})^2);\\
    B_{ijklrs}^{\text{ggg}} &\supset \langle (b_1^\text{g}\text{TF}(\Pi^{[1]})_{ij})(\bb{k}_1)(\epsilon_{kl}^\delta\delta)(\mathbf{k}_2)\epsilon_{rs}(\mathbf{k}_3)\rangle ' = b_1^\text{g}\alpha_{\text{gg}}^{1\delta} \mathcal{D}_{ij}(\bb{k}_1) \Delta_{kl,rs}^{\text{TF}}P_L(k_1)+ \mathcal{O}((k_i/k_{\text{NL}})^2). 
    \end{aligned}
\end{equation}
