\begin{lemma}
	For any structure $M$, $(M^{\eq})^{\Sh}$ is a (proper in general) reduct of $(M^{\Sh})^{\eq}$, i.e.~every sort of $(M^{\eq})^{\Sh}$ is also a sort of $(M^{\Sh})^{\eq}$, and every $\emptyset$-definable subset of any product of sorts in $(M^{\eq})^{\Sh}$ is also $\emptyset$-definable in $(M^{\Sh})^{\eq}$.
\end{lemma}
\begin{proof}
It is clear that every sort of $(M^{\eq})^{\Sh}$ is also a sort of $(M^{\Sh})^{\eq}$.

Let $L$ be the language of $M$ and $L^{\Sh}$ the language of $M^{\Sh}$.
Let $N' \succ M^{\eq}$ be a saturated $L^{\eq}$-elementary extension, then $N' = N^{\eq}$ for some saturated $L$-elementary extension $N \succ M$.

Assume that $E_1, \ldots, E_n$ are some $L(\emptyset)$-definable equivalence relations in $T := \Th_L(M)$, let $S_{E_i}$  be the corresponding sorts in $T^{\eq}$, let $Y'$ be an $L^{\eq}(N^{\eq})$-definable subset of $\prod_{i=1}^n S_{E_i}^{N^{\eq}}$. Let $Y := Y' \cap \prod_{i=1}^n S_{E_i}^{M^{\eq}}$.

Say $Y'$ is defined in $N^{\eq}$ by $\varphi(y_1, \ldots, y_n, b_1, \ldots, b_m)$ for some 
$$\varphi(y_1, \ldots, y_n; y_{n+1}, \ldots, y_{n+m}) \in L^{\eq}$$
with the variable $y_i$ of sort $S_{E_i}$ and some $b_i \in S^{N^{\eq}}_{E_{n+i}}$. Let $f_{E_i}$ be the function symbol in $L^{\eq}$ for the quotient by $E_i$. 
By basic properties of $T^{\eq}$, there is some formula $\psi(x_1, \ldots, x_{n+m}) \in L$ with $x_i$ is the home sort so that 
\begin{gather*}
	T^{\eq} \vdash \varphi(f_{E_1}(x_1), \ldots, f_{E_{n+m}}(x_{n+m})) \equiv \psi(x_1, \ldots, x_{n+m}).
\end{gather*}
As $f_{E_i}$ are onto, there are some $a_{n+1}, \ldots, a_{n+m} \in N$  with $f_{E_i}(a_i) = b_i$. Let $X'$ be the subset defined in $N$ by $\psi(x_1, \ldots, x_n; a_{n+1}, \ldots, a_{n+m})$, then $X := X'(M)$ is definable in $M^{\Sh}$ and, using that each $f_{E_i}$ is onto in $M^{\eq}$ (and $M^{\eq}$ is closed under these functions), we get that $Y = f(X)$ for the $L^{\eq}(\emptyset)$-definable map
\begin{gather*}
	(x_1, \ldots, x_{n}) \mapsto (f_{E_1}(x_1), \ldots, f_{E_n}(x_n))
\end{gather*}
in $M^{\eq}$, hence $Y$ is definable (using a quantifier) in $(M^{\Sh})^{\eq}$.
\end{proof}
\begin{remark}
	In particular $((M^{\Sh})^{\eq})^{\Sh}$ is a reduct of $((M^{\Sh})^{\Sh})^{\eq}$, so, if $M$ is NIP, a reduct of $(M^{\Sh})^{\eq}$ already, so $(M^{\Sh})^{\eq}$ is closed under both taking $^{\Sh}$ and $^{\eq}$.
\end{remark}



\subsection{Keisler measures in NIP theories}\label{sec: Keisler measures in NIP theories}
For $r,s \in \mathbb{R}$ and $\varepsilon \in \mathbb{R}_{>0}$, we write $r \approx^{\varepsilon} s$ to denote $|r-s| \leq  \varepsilon$. We denote the collection of Keisler measures (in variable $x$ over $A$) as $\mathfrak{M}_{x}(A)$. Given $\mu \in \mathfrak{M}_{x}(A)$, we let $S(\mu)$ denote the support of $\mu$, i.e.~the (closed) set of all $p \in S_x(A)$ such that $\mu(\varphi(x))>0$ for every $\varphi(x) \in p$. Given a partial type $\pi(x)$ over $A$, we will consider the closed set 
\begin{gather*}
	\mathfrak{M}_\pi(A) := \left\{ \mu \in \mathfrak{M}_{x}(A) : p \in S(\mu) \Rightarrow p(x) \vdash \pi(x) \right\} \\
	= \left\{ \mu \in \mathfrak{M}_{x}(A) : \bigwedge_{\varphi(x) \in \pi} \mu(\varphi(x)) = 1 \right\}
\end{gather*}
of measures supported on $\pi(x)$. We will also write $S_{\pi}(A)$ for $\{p \in S_x(A) : p(x) \vdash \pi(x)\}$.

\begin{fact}\label{fac: types in sup of inv meas are inv NIP}(see e.g.~\cite[Lemma 2.10(3)]{chernikov2022definable}) 
	If $T$ is NIP and $\mu \in \mathfrak{M}_x(\cU)$ is $M$-invariant, then every type $p \in S(\mu)$ is also $M$-invariant.
\end{fact}

\begin{definition}\cite[Definition 2.2]{chernikov2013externally}
	Assume $M \prec \cU$. We say that $\nu \in \mathfrak{M}_x(\cU)$ is an \emph{heir} of $\mu \in \mathfrak{M}_x(M)$ if for any finitely many formulas $\varphi_i(x,a) \in L(\cU)$ (where $a$ is an arbitrary finite tuple in $\cU$) and $r_i \in [0,1)$, $i <n$, if $\bigwedge_{i < n} \nu(\varphi_i(x,a) > r_i)$ holds, then there exists some $b$ in $M$ so that $\bigwedge_{i < n} \mu(\varphi_i(x,b) > r_i)$ holds. 
\end{definition}
\begin{remark}\label{rem: unique def ext of definable measure}
	If the measure $\mu \in \mathfrak{M}_x(\cU)$ is \emph{definable} over $M$ (i.e.~$\mu$ is $M$-invariant, and for every $\varphi(x,y) \in L$ the function $F^{\varphi(x;y)}_{\mu, M}: S_{y}(M) \to [0,1]$, $q(y) \mapsto \mu(\varphi(x,b))$ for some/any $b \models q$, is continuous), then $\mu$ is the unique heir of $\mu|_{M}$ (see \cite[Remark 2.7]{NIP1}; they use a weaker notion of heir of a measure there, but uniqueness of heirs in their sense implies in particular the uniqueness of heirs in our sense).
\end{remark}


\begin{fact}\cite[Theorem 2.5]{chernikov2013externally}\label{fac: inv heir of a measure NIP}
	Assume $T$ is NIP and $M \models T$. Then every $\mu \in \mathfrak{M}_x(M)$ has a global extension $\nu \in \mathfrak{M}_x(\cU)$ which is both invariant over $M$ and an heir of $\mu$.
\end{fact}


We summarize some facts about generically stable measures in NIP theories (see \cite[Theorem 3.2]{NIP3}, \cite[Section 7.5]{simon2015guide}, \cite{zbMATH07456275}):

\begin{fact}\label{fac: NIP gen stab meas equivs}
Let $T$ be NIP and assume that $\mu \in \mathfrak{M}_x(\cU)$ is invariant over a small model $M$.  Then the following are equivalent:
	\begin{enumerate}
		\item $\mu$ is both definable and finitely satisfiable over $M$ (i.e.~for every $\varphi(x) \in L(\cU)$, if $\mu(\varphi(x)) > 0$ then $\models \varphi(a)$ for some $a \in M^x$);
		\item $\mu$ is \emph{fim} over $M$, i.e.~$\mu$ is Borel-definable (over $M$) and for any $\varphi(x,y) \in \mathcal{L}$ there exists a sequence of formulas $(\theta_{n}(x_1,\ldots,x_n))_{1 \leq n < \omega}$ in $\mathcal{L}(M)$ such that: 
	\begin{enumerate}
		\item for any $\varepsilon > 0$, there exists some $n_{\varepsilon} \in \omega$ satisfying: for any $k \geq n_{\varepsilon}$, if $\cU \models \theta_{k}(\abar)$ then 
		\begin{equation*} 
		\sup_{b \in \cU^{y}} |\Av(\abar)(\varphi(x,b)) - \mu(\varphi(x,b))| < \varepsilon;
		\end{equation*} 
		\item $\lim_{n \to \infty} \mu^{\otimes n} \left( \theta_n \left(\bar{x} \right) \right) = 1$.
	\end{enumerate}

		\item \label{item: fam} $\mu$ is \emph{fam} over $M$, that is for any formula $\varphi(x,y) \in L$ and $\varepsilon \in \mathbb{R}_{>0}$ there exist some $n \in \omega$ and $a_0, \ldots, a_{n-1} \in M^x$ so that for every $b \in \cU^y$,
		\begin{gather*}
		 \left \lvert \Av(\abar)(\varphi(x,b))	- \mu \left( \varphi(x,b) \right) \right \rvert \leq \varepsilon.
		\end{gather*}
		\end{enumerate}
If either of these properties holds for some small model $M$, we will say that $\mu$ is \emph{generically stable}. And we say that $\mu$ is \emph{generically stable over $A$}, for $A$ a small set, if $\mu$ is generically stable and $A$-invariant.
\end{fact}
\begin{remark}\label{rem: gs over a set but not fs}
If $\mu \in \mathfrak{M}_x(\cU)$ is generically stable over $A$, then it is definable over $A$ and finitely satisfiable (fim, fam) over any small model $M \supseteq A$ (but not necessarily finitely satisfiable in $A$ itself).
\end{remark}

We also have the following:
\begin{fact}\label{fac: basic props gen stab meas}
\cite[Proposition 3.3]{NIP3} Let $T$ be NIP and assume that $\mu \in \mathfrak{M}_x(\cU)$ is generically stable over $M$. Then  $\mu$ is the unique $M$-invariant extension of $\mu|_M$ (in particular its  unique global coheir; and its unique global heir).
\end{fact}



\begin{definition}\label{def: definable pushforward}
Let $f:\cU^{x} \to \cU^{y}$ be a partial $L(\cU)$-definable map and $\mu \in \mathfrak{M}_{x}(\cU)$.
\begin{enumerate}
	\item We say that \emph{$f$ is defined on $\mu$} if $\mu_x(\exists y \Gamma_{f}(x,y))=1$ (equivalently, if $p(x) \vdash \exists y \Gamma_{f}(x,y)$ for every $p \in S(\mu)$).
	\item If $f$ is defined on $\mu$,  we define the \emph{push-forward measure} $f_{*}(\mu)$ in $\mathfrak{M}_{y}(\cU)$, where for any formula $\varphi(y) \in \mathcal{L}_{y}(\mathcal{U}), f_*(\mu)(\varphi(y)) = \mu_x(\exists u (\Gamma_f(x,u) \land \varphi(u)))$. 

\end{enumerate}
\end{definition} 


\begin{fact}\cite[Proposition 3.26]{chernikov2024definable}
We have $S(f_{\ast}\mu) = \{f_{\ast}p : p \in S(\mu)\}$, and	 if $\mu \in \mathfrak{M}_{x}(\cU)$ is generically stable over $M$ and $f$ is an $M$-definable map, then $f_{\ast}(\mu)$ is also generically stable over $M$.
\end{fact}


The following is a classical result on extending finitely additive measures to larger Boolean algebras:

\begin{fact}(\L o\'s-Marczewski \cite{Los1949})\label{fac: classic measure ext}
	Let $S$ be a set and $\mathcal{B}_0 \leq \mathcal{B}_1 \leq \mathcal{P}(S)$ be Boolean subalgebras, where $\mathcal{P}(S)$ is the power set. Let $\mu$ be a finitely additive probability measure on $\mathcal{B}_0$. Then there is a finitely additive probability measure $\nu$ on $\mathcal{B}_1$ extending $\mu$. Moreover, for any $X \in \mathcal{B}_1$ we can choose $\nu$ with $\nu(X) = r$ for any $r$ satisfying
	$$\sup \left\{ \mu(L) : L \in \mathcal{B}_0, L \subseteq X \right\} \leq r \leq \inf \left\{ \mu(U) : U \in \mathcal{B}_0, X \subseteq U \right\}$$
	(and clearly any $\nu$ extending $\mu$ has to satisfy this for every $X \in \mathcal{B}_1$).
\end{fact}

We will also need the following fact on finding generically stable measures in NIP theories:
\begin{fact}\cite[Proposition 3.3]{zbMATH06025969}\label{fac: symmetrization measure}
	Let $T$ be NIP, $M$ a small model and $\mu \in \mathfrak{M}_x(\cU)$ a global $M$-invariant measure. Then there is $\mu' \in \mathfrak{M}_x(\cU)$ so that:
	\begin{enumerate}
		\item $\mu'|_{M} = \mu|_{M}$;
		\item $\mu'$ is generically stable over some $M' \succ M$;
		\item if $f: \cU^x \to \cU^x$ is an $M$-definable function such that $f_{\ast}(\mu) = \mu$, then also $f_{\ast}(\mu') = \mu'$.
	\end{enumerate}
\end{fact}


\subsection{Keisler measures in type-definable groups and their stabilizers}\label{sec: Keisler measures in definable groups and their stabilizers}

\begin{definition}\label{def: definable conv} Suppose that $G$ is an $M$-type-definable group and $\mu \in \mathfrak{M}_{G}(\cU)$ is Borel-definable. Then for any measure $\nu \in \mathfrak{M}_{G}(\cU)$, the (definable) \emph{convolution of $\mu$ and $\nu$}, denoted $\mu * \nu$, is the unique measure in $\mathfrak{M}_{G}(\cU)$ such that for any formula $\varphi(x) \in \mathcal{L}(\cU)$, 
\begin{equation*} 
(\mu * \nu)(\varphi(x)) = ( \mu \otimes \nu)(\varphi(x \cdot y)). 
\end{equation*} 
We say that $\mu$ is \emph{idempotent} if $\mu * \mu = \mu$. 
\end{definition} 
\begin{remark}
	When $T$ is NIP, it suffices to assume that $\mu$ is invariant (under $\Aut(\mathbb{M}/M)$ for some small model $M$), as then $\mu$ is automatically Borel-definable (\cite{NIP3}). We refer to \cite[Section 3]{chernikov2022definable} for a detailed discussion of when convolution is well-defined, and to \cite{chernikov2022definable, chernikov2023definable2} for a study of the convolution semigroups on measures.
\end{remark} 

\begin{remark}\label{rem: type-def group formula}
		If $G$ is a type-definable (over $M$) group, without loss of generality defined by a partial type $G(x)$ closed under conjunctions, by compactness we may assume that $\cdot$ is an $M$-definable partial function defined, associative and with left and right cancellation on $\varphi_0(\cU)$, and $^{-1}$ is defined on $\varphi_0(\cU)$, for some $\varphi_{0}(x) \in G(x)$ (but $\varphi_0(\cU)$ is not necessarily closed under $\cdot$ or $^{-1}$). 
%		By compactness, there is formula $\varphi_1(x) \in G(x)$ so that $\varphi_1(x) \vdash \varphi_0(x)$ and $\varphi_1(x) \land \varphi_1(y) \vdash \varphi_0(x \cdot y)$.
%		For a formula $\varphi(x,y) \in L$ with $y$ an arbitrary tuple of variables, we let $\widetilde{\varphi}(x; y,x') := \varphi(x' \cdot x, y) \land \varphi_1(x) \land \varphi_1(x')$. Note that the family of instances of $\widetilde{\varphi}$ is closed under left translates by elements of $G$.
\end{remark}

\begin{definition}\label{def: stab of a measure}
For $G$ an $M$-type-definable group, $N \succeq M$, we have an action of $G(N)$ on $\mathfrak{M}_{G}(N)$ via $g \cdot \mu (\varphi(x)) := \mu_x(\varphi(g \cdot x))$ (where $\varphi(g \cdot x)$ is an abbreviation for $\exists u (\Gamma_{\cdot_{G}}(g,x,u) \land \varphi(u))$). For a measure $\mu \in \mathfrak{M}_{G}(\cU)$, we let 
$$\Stab(\mu) := \{g \in G(\cU) : g \cdot \mu = \mu \} $$ 
denote the left stabilizer of $\mu$. Similarly, we let $\Stab^{\leftrightarrow}(\mu) := \{g \in G(\cU) : g \cdot \mu = \mu \cdot g = \mu \}$ denote the two-sided stabilizer of $\mu$.
\end{definition}
\begin{fact}\label{fac: stab of def meas type def}(see \cite[Proposition 5.3]{chernikov2022definable})
	When $G = G(x)$ is an $M$-type-definable group and $\mu \in \mathfrak{M}_{G}(\cU)$ is a measure definable over $M \prec \cU$, then $\Stab_G(\mu)$ is an $M$-type-definable subgroup of $G(\cU)$. 

	More precisely, $\Stab_G(\mu) = G \cap \bigcap_{\varphi(x;y) \in  L,  \varepsilon \in \mathbb{Q}_{>0}} \Stab_{G,\varphi(x;y), \varepsilon}(\mu)$, where each $\Stab_{G,\varphi(x;y), \varepsilon}(\mu) \subseteq \varphi_{0}(\cU)$ (see Remark \ref{rem: type-def group formula})  is an $M$-definable set (not necessarily a subgroup or even a subset of $G$) so that:
	\begin{enumerate}
		\item  for any $b \in \cU^y$ and any $g  \in  \Stab_{G,\varphi(x;y), \varepsilon}(\mu)$, 
	$$\left \lvert  \mu(\varphi(x,b)) - \mu (\varphi(g \cdot x,b) )\right \rvert \leq \varepsilon;$$
	\item given $g$, if for all $b \in \cU^y$ we have $$\left \lvert  \mu(\varphi(x,b)) - \mu (\varphi(g \cdot x,b))\right \rvert \leq \varepsilon,$$
	 then $g \in \Stab_{G,\varphi(x;y), 2 \varepsilon}(\mu)$.
	\end{enumerate}
	And similarly for $\Stab^{\leftrightarrow}(\mu)$.
\end{fact}


\begin{fact}\cite[Proposition 3.37]{chernikov2024definable}\label{fac: pushforward gen stab}
Let $G$ be an $M$-definable group, and $\mu \in \mathfrak{M}_{G}(\cU)$ an idempotent generically stable measure. Then the following are equivalent:
\begin{enumerate}
	\item $\mu \in \mathfrak{M}_{H}(\cU)$, where $H := \Stab_{G}(\mu)$;
	\item $\mu^{(2)} = f_{\ast}\left(\mu^{(2)} \right)$, where $f: \left( \cU^{x} \right)^2 \to \left( \cU^{x} \right)^2$ is the $M$-definable map $f(x_1,x_0) = (x_1 \cdot x_0, x_0)$ (where $\cdot$ is viewed as a globally defined function whose restriction to $G$ defines the group operation).
	\item $\mu \otimes p = f_{\ast}(\mu \otimes p)$ for every $p \in S(\mu)$.
\end{enumerate}
If any of these conditions hold, we say that $\mu$ is \emph{generically transitive}.
\end{fact}

We recall:
\begin{definition}
	A type-definable group $G$ is \emph{definably amenable} (\emph{definably extremely amenable}) if there is a left-$G(\cU)$-invariant measure $\mu \in \mathfrak{M}_{G}(\cU)$ (respectively, a left-$G(\cU)$-invariant type $p \in S_{G}(\cU)$).
\end{definition}

\begin{fact}\cite[Lemma 5.8]{NIP2}\label{fac: def am def measure}
	If $T$ is NIP and $G$ is $M$-type-definable and definably amenable, then there exists a left-$G(\cU)$-invariant measure $\mu \in \mathfrak{M}_{G}(\cU)$ which is definable over some small model $M' \succ M$.
\end{fact}

\begin{remark}
	If $G$ is definable and $H \leq G$ is type-definable by a partial type $\pi(x)$ and definably amenable, then $H$ is already type-definable by some $\pi_0 \subseteq \pi$ with $|\pi_0| \leq |T|$.
\end{remark}
\begin{proof}
	By Fact \ref{fac: def am def measure} there is a left $H(\cU)$-invariant measure $\mu \in \mathfrak{M}_{H}(\cU)$ definable over some small model $M \prec \cU$. But by definition, every definable measure is definable over some set of size $\leq |T|$, hence $\Stab_{G}(\mu) \leq G(\cU)$ is also type-definable by some $\pi_1(x)$ of size $\leq |T|$ by Fact \ref{fac: stab of def meas type def}. Clearly $H(\cU) \subseteq \Stab_{G}(\mu)$. Conversely, $\Stab_{G}(\mu) \leq  H$: otherwise there is some $g \in \Stab_{G}(\mu) \setminus H$, so $g \cdot H \cap H = \emptyset$. By compactness this implies $g \cdot \psi(x) \cap \psi(x) = \emptyset$ for some $\psi \in \pi$, and $\mu(\psi(x) = \mu( g \cdot \psi(x)) = 1$ (as $\mu \in \mathfrak{M}_{H}(\cU)$) --- a contradiction. So $\pi(\cU) = \pi_1(x)$, and by compactness this implies that $\pi(x)$ is equivalent to some $\pi_0 \subseteq \pi$ with $|\pi_0| \leq |T|$.
\end{proof}


\subsection{Type-definable fsg groups}\label{sec: type-def fsg groups}
We summarize some facts on (type-) definable fsg groups, see \cite[Remark 4.4]{NIP3}, and \cite[Remark 3.3]{chernikov2024definable} for the type-definable case.

\begin{definition}\cite[Definition 6.1]{NIP2}
	Let $G$ be a type-definable group. We say that $G$ is \emph{fsg} (\emph{finitely satisfiable generics}) if there  exist some $p \in S_G(\cU)$ and small $M \prec \cU$ such that $G$ is type-definable over $M$ and for every $g \in G(\cU)$, the type $g \cdot p$ is finitely satisfiable in $G(M)$ (we stress that finite satisfiability in $G(M)$ is a stronger requirement than finite satisfiability in $M$ when $G$ is only type-definable rather than definable). In this case we will say that $G$ is fsg \emph{over $M$}.
\end{definition}

\begin{proposition}\label{prop: fsg type-def arb models}
	If $G$ is type-definable over $M$ and fsg, then for any $N \succ M$ which is $|M|^{+}$-saturated, $G$ is fsg over $N$.
\end{proposition}
\begin{proof}
	We adapt the proof from \cite[Remark 4.4]{NIP1} for definable groups. Let $N \succ M$ be any $|M|^{+}$-saturated model.


	By \cite[Lemma 6.2(ii)]{NIP2}, there is a global generic type $p$ of $G$, namely $p \in S_G(\cU)$ so that any $\varphi(x) \in p$ is generic, i.e.~there are $n_{\varphi} \in \omega$ and $g_1, \ldots, g_{n_{\varphi}} \in G(\cU)$ so that $G(\cU) \subseteq  \bigcup_{i \in [n_{\varphi}]} g_i \cdot (\varphi(\cU) \cap G(\cU))$. By \cite[Lemma 6.2(iii)]{NIP2}, there is a small $M_0 \prec \cU$ so that any generic $p \in S_G(\cU)$ is finitely satisfiable in $G(M_0)$, and for any generic $\varphi(x) \in L(\cU)$, the translates $g_1, \ldots, g_{n_{\varphi}}$ witnessing this can be chosen in $G(M_0)$. 


	Now assume that $\psi(x) \in L(\cU)$ is generic, say $\psi(x) = \varphi(x,b)$ for some $\varphi(x,y) \in L, b \in \cU^y$, and  $G(\cU) \subseteq  \bigcup_{i \in [k]} g_i \cdot (\varphi(\cU,b) \cap G(\cU))$ for some $g_1, \ldots, g_{k} \in G(\cU)$. Let $q(y) := \tp(b/M)$. As $G$ is type-definable over $M$, $\varphi(x,b')$ is generic for any $b' \models q$ in $\cU$ (witnessed by any $g'_1, \ldots, g'_k$ so that $(b,g_1, \ldots, g_k) \equiv_M (b',g'_1, \ldots, g'_k)$).
	Then the partial type $q(y) \cup \{ \neg \varphi(d,y) : d \in G(M_0) \}$ is inconsistent, as every generic formula meets $G(M_0)$ by the choice of $M_0$. That is, there exists a finite tuple $\bar{d} = (d_1, \ldots, d_n) \in G(M_0)^n$ so that for every $b' \models q$ in $\cU$ we have $\models \bigvee_{i \in [n]} \varphi(d_i,b')$. As $N$ is $|M|^{+}$-saturated, there is a tuple $\bar{d}'$ in $N$ with $\bar{d}' \equiv_M \bar{d}$. In particular, $\bar{d}' \in G(N)^n$ and we still have that for every $b' \models q$ in $\cU$,  $\models \bigvee_{i \in [n]} \varphi(d'_i,b')$. This shows that $\psi(x)$ meets $G(N)$.

	As every $G(\cU)$-translate of a generic type is generic, this shows that $g \cdot p$ is finitely satisfiable in $G(N)$ for all $g \in G(\cU)$.
	\end{proof}



\begin{proposition}\label{prop: fsg iff inv gen stab meas}
Let $T$ be NIP and $G$ a group  type-definable over $M$. The following are equivalent:
\begin{enumerate}
	\item  $G$ is fsg;
	\item $G$ is fsg over any $|M|^{+}$-saturated $N \succ M$;
	\item there exists a generically stable left-$G(\cU)$-invariant  measure $\mu \in \mathfrak{M}_{G}(\cU)$;

	\item there exists a left-$G(\cU)$-invariant  measure $\mu \in \mathfrak{M}_{G}(\cU)$ generically stable over any $|M|^{+}$-saturated  $N \succ M$.
	\end{enumerate}
\end{proposition}
\begin{proof}
(1) implies (2) by Proposition \ref{prop: fsg type-def arb models}. 

(2) implies (4). Given $p \in S_G(\cU)$ such that $g \cdot p$ is finitely satisfiable in an arbitrary $N \succ M$ for all $g \in G(\cU)$, the standard construction of a left-invariant generically stable over $N$ measure $\mu_p$ in an fsg group goes through in the type-definable case (see \cite[Proposition 6.2]{NIP1} and \cite[Remark 4.4]{NIP3}).

(4) implies (3) is trivial.

(3) implies (1). If (3) holds for $\mu \in \mathfrak{M}_G(\cU)$ generically stable over some $|M|^+$-saturated $N \succ M$, then the proof of \cite[Proposition 3.26]{chernikov2024definable}) shows that $\mu$ is finitely satisfiable in $G(N)$, so any $p \in S(\mu)$ satisfies (1) with respect to $N$.
\end{proof}




In the case of definable fsg groups, we can omit the saturation requirements on the model.
\begin{fact}\cite[Proposition 3.4]{chernikov2014external}\label{fac: heir of a measure remains G-inv}
	If $G$ is an $M$-definable group, $\mu \in \mathfrak{M}_G(M)$ is $G(M)$-invariant and $\nu$ is a global heir of $\mu$, then $\nu \in \mathfrak{M}_{G}(\cU)$ is $G(\cU)$-invariant.
\end{fact}

\begin{fact}\label{fac: fsg groups basic props}
	Assume $G$ is type-definable and fsg, witnessed by some left $G$-invariant generically stable measure $\mu \in \mathfrak{M}_{G}(\cU)$ (using Proposition \ref{prop: fsg iff inv gen stab meas}).
	\begin{enumerate}
		\item $\mu$ is the unique left $G$-invariant, as well as the unique right $G$-invariant measure in $\mathfrak{M}_{G}(\cU)$.
		\item If $T$ is NIP and $G$ is in fact a definable group over $M \prec \cU$, then $\mu$ is generically stable over any small model $M \prec \cU$ so that $G$ is $M$-definable.
	\end{enumerate}
\end{fact}
\begin{proof}
(1)  By \cite[Theorem 4.3]{NIP3} for definable groups.  See \cite[Proposition 3.33]{chernikov2024definable} for type-definable groups, and without assuming NIP.

	(2) By Fact \ref{fac: inv heir of a measure NIP}, let $\mu' \in \mathfrak{M}_{G}(\cU)$ be a global $M$-invariant heir of $\mu|_{M}$. As $G$ is $M$-definable and $\mu|_{M}$ is $G(M)$-invariant, it follows by Fact \ref{fac: heir of a measure remains G-inv} that $\mu'$ is $G(\cU)$-invariant. But then $\mu = \mu'$ by (1). So $\mu$ is generically stable, and invariant over $M$, hence generically stable over $M$.
\end{proof}




	Recall:
	\begin{definition}\cite{PiTa}
A global type $p \in S_x(\cU)$ is \emph{generically stable} if it is $A$-invariant for some small $A \subset \cU$, and for any ordinal $\alpha$ (or just for $\alpha = \omega + \omega$), $(a_i : i \in \alpha)$ a Morley sequence in $p$ over $A$ and formula $\varphi(x) \in \cL(\cU)$, the set $\{i \in \alpha : \models \varphi(a_i) \}$ is either finite or co-finite. 
\end{definition}
\begin{remark}\label{rem: gen stab one Morley seq}
	As $\tp(\bar{a}/A) = \tp(\bar{a}'/A)$ for any two Morley sequences in $p$ over $A$ of the same order type, to check generic stability of $p$ it is enough to find \emph{some}  Morley sequence in it of order type $\alpha := \omega + \omega$ so that the set $\{i \in \alpha : \models \varphi(a_i) \}$ is either finite or co-finite (follows by taking an automorphism of $\cU$ over $A$ sending one Morley sequence to the other and replacing $ \varphi(x)$ by its image under this automorphism).
\end{remark}
\begin{remark}
	We note that in any theory, $p \in S_x(\cU)$ is generically stable over $M$ if and only if it is fim over $M$, viewed as a $\{0,1\}$-valued Keisler measure (see \cite[Proposition 3.2]{conant2020remarks}).
\end{remark}

We will also consider the special case of an fsg group with a $\{0,1\}$-valued measure:
\begin{definition} \cite[Definition 2.1]{PiTa}\label{def: generically stable group}
	A type-definable group $G(x)$ is (connected) \emph{generically stable} if there is a generically stable $p \in S_{G}(\cU)$ which is left $G(\cU)$-invariant, i.e. $g \cdot p = p$ for all $g \in G(\cU)$.
		\end{definition}


\begin{remark}\label{rem: def iso preserves fsg}
	In any theory $T$, assume $G$ and $H$ are groups (type-)definable over $M$ and $f: G \to H$ is an $M$-definable surjective homomorphism. Then if $G$ is definably amenable (fsg, generically stable), then so is $H$.
\end{remark}
\begin{proof}
Assume $\mu \in \mathfrak{M}_{G}(\mathbb{M})$ is left-$G(\cU)$-invariant. Then the push-forward measure $f_{\ast}\mu \in \mathfrak{M}_{H}(\mathbb{M})$ is left-$H(\cU)$-invariant. Indeed, fix any $\varphi(y) \in \cL(\cU)$ and $h \in H(\cU)$, as $f$ is surjective take $g \in G(\cU)$ with $f(g) = h$. Then $f_{\ast}\mu \left( \varphi( h \cdot_H y) \right) = \mu ( \varphi(h \cdot f(x)))$ by definition of push-forward measure, $= \mu (\varphi(f(g) \cdot_H f(x) )) = \mu (\varphi(f(g \cdot_G x) ))$ as $f$ is a homomorphism, $= \mu (\varphi(f(x) ))$ by left-$G(\cU)$-invariance of $\mu$, $= f_{\ast}(\varphi(y))$ by definition of push-forward measure again.

And if $\mu$ is generically stable over $M$, then $f_{\ast} \mu$ is also generically stable over $M$ (e.g.~fim is preserved, see \cite[Proposition 3.26]{chernikov2024definable}).
\end{proof}


\subsection{Properties of definable groups preserved in Shelah expansion}\label{sec: props of grps preserved in Sh exp}

We summarize some known facts about externally definable groups, mostly from \cite{chernikov2013externally}.
\begin{fact}\label{fac: group props preserved in Sh exp}
	Let $T$ be an NIP $L$-theory, $M \models T$, $ G = G(\cU)$ is an $M$-definable group.
	Let $T' := \Th(M^{\Sh})$ in $L'$.
	\begin{enumerate}

		\item $G$ is fsg in $T$ if and only if $G$ is fsg in $T'$.
		\item $G$ is generically stable in $T$ if and only if $G$ is generically stable in $T'$.
		\item $G$ is definably (extremely) amenable in $T$ if and only if $G$ is definably (extremely) amenable in $T'$.
		\item $G^0/G^{00}/G^{\infty}$ calculated in $T$ is equal to $G^0/G^{00}/G^{\infty}$ calculated in $T'$ (that is, in its monster model $M'$).
		\item In particular, if $H \leq G(M)$ is an externally definable subgroup of finite index, then it is already (internally) definable.
	\end{enumerate}
\end{fact}
\begin{proof}
(1) If $G$ is fsg in $T'$, there is some $p' \in S^{L'}_{G}(M')$ such that $g \cdot p'$ is finitely satisfiable in $M$ for all $g \in G(M')$ (e.g.~using Fact \ref{fac: fsg groups basic props}(2), taking any type in the support of such a measure). Let $p := p'\restriction_{L}$, then for all $g \in G(M')$ we have $g \cdot p = (g \cdot p')\restriction_{L}$ is finitely satisfiable in $M$. Alternatively, we can start with a generically stable over $M$ measure $\mu' \in \mathfrak{M}^{L'}_{G}(M')$ which is $G(M')$-invariant (using Fact \ref{fac: fsg groups basic props}(2)), then $\mu := \mu'\restriction_{L} \in \mathfrak{M}^{L}_{G}(M')$ is generically stable in $T$ by Proposition \ref{prop: properties of reducts of measures}(1), hence $G$ is fsg in $T$. The converse is by \cite[Theorem 3.19]{chernikov2014external} (using Fact \ref{fac: fsg groups basic props}(2), we can always find a type that is fsg in $G$ over $M$).

(2) Restricting the argument in (1) to types.

	(3) If $G$ is definably amenable (definably extremely amenable) in $T'$, there is a measure $\mu' \in \mathfrak{M}^{L'}_{G}(M')$ (a type $p' \in S^{L'}_{G}(M')$) which is left $G(M')$-invariant. But then $\mu := \mu'\restriction_{L} \in \mathfrak{M}^{L}_{G}(M')$ ($p := p'\restriction_{L} \in S^{L}_{G}(M')$) is still $G(M')$-invariant, witnessing that $G$ is definably amenable (definably extremely amenable) in $T$. The converse is by \cite[Theorem 3.17]{chernikov2014external}.

	(4),(5) By Theorem 4.5 and Corollaries 4.15 and 4.20 in \cite{chernikov2014external}.
\end{proof}



\section{Externally definable subgroups of definable groups}\label{sec: Externally definable fsg subgroups of definable groups}





\subsection{Transfer of properties of measures between $T$ and $\Th(M^{\Sh})$}
\label{sec: Transfer of properties of measures between T and T sh}




\begin{proposition}\label{prop: properties of reducts of measures}
	Assume $T \subseteq T'$ are complete $L \subseteq L'$-theories and $T'$ is NIP. Let $\mathbb{M}' \models T'$ be a monster model, then $\mathbb{M}' := \mathbb{M}' \restriction L$ is a monster model for $T$. Let $M' \prec \mathbb{M}'$ be a small model of $T'$, and $M := \mathbb{M} \restriction L$.
	\begin{enumerate}
		\item \label{item: gen stab of meas preserved in reduct} If $\mu'(x) \in \mathfrak{M}^{L'}_x\left(  \mathbb{M}' \right)$ is  generically stable  over $M$ in $T'$, then $\mu := \mu\restriction_{L}$ is generically stable over $M$ in $T$.
		\item  Assume $G$ is an $L(M)$-definable group and $\mu \in \mathfrak{M}^{L'}_{G}(\mathbb{M})$ is finitely satisfiable in $M$ and idempotent. Then $\mu$ is also idempotent.
		\item Assume $G$ is an $L(M)$-definable group and $\mu' \in \mathfrak{M}^{L'}_{G}(\mathbb{M}')$ is generically stable over $M$ and generically transitive. Then $\mu$ is also generically transitive (in $T$).
	\end{enumerate}
\end{proposition}
\begin{proof}
	(1) Fam clearly transfers to reducts: by assumption  $\mu'$ satisfies Fact \ref{fac: NIP gen stab meas equivs}\eqref{item: fam} in $T'$; as for any $L$-formula $\varphi(x,y)$ and $b \in \cU^y$ we have $\mu'(\varphi(x,b)) = \mu(\varphi(x,b))$, it follows that $\mu$ also satisfies Fact \ref{fac: NIP gen stab meas equivs}\eqref{item: fam} in $T$ (which is also NIP).

	(2) First note that if $\mu'$ is finitely satisfiable in $M$ (i.e.~for every $\varphi(x) \in L'(M')$, if $\mu'(\varphi(x))>0$ then $\varphi(M) \neq \emptyset$), then $\mu$ is also finitely satisfiable in $M$, hence $\mu$ is $M$-invariant (in $T$), and so it is Borel-definable over $M$ in $T$ as $T$ is NIP. We have:

	\begin{claim}\label{cla: restriction commutes with tensor}
		$\left( \mu' \otimes \nu' \right) \restriction_{L} = \left( \mu' \restriction_{L}  \right) \otimes \left( \nu' \restriction_{L}  \right)$ for an arbitrary $\nu' \in S^{L'}_x(\cU')$.
	\end{claim}
	\begin{proof}
	Indeed, fix an arbitrary formula $\varphi(x,y) \in L(\cU)$, and let $M \preceq N \prec \cU'$ be a small  model so that $\varphi(x,y) \in L(N)$. 
Let $f: S^{L'}_y(N) \to S^{L}_{y}(N)$ be defined via $f(q) := q \restriction_{L}$, then $f$ is a continuous surjection. Let $\tilde{\nu}'$ be the unique regular Borel probability measure on $S^{L'}_y(N)$ extending $\nu'|_{N}$, and let $\tilde{\nu}$ be the unique regular Borel probability measure on $S^{L}_y(N)$ extending $\nu|_{N}$, where $\nu := \nu'\restriction_{L}$. Let $f_{\ast} \tilde{\nu}'$ be the pushforward measure of $\tilde{\nu}'$, we then have $f_{\ast} \tilde{\nu}' = \tilde{\nu}$ (as they clearly agree on the clopens). Note also that for any  $\left( F^{\varphi(x;y)}_{\mu, N} \circ f \right) (q) = F^{\varphi(x;y)}_{\mu', N}(q)$ by $M$-invariance of $\mu$. Then have 
	\begin{gather*}
		\left(\mu \otimes \nu \right) \left( \varphi(x,y) \right) =  \int_{S^L_y(N)} F^{\varphi(x;y)}_{\mu, N} d \tilde{\nu} = \int_{S^{L'}_y(N)} \left( F^{\varphi(x;y)}_{\mu, N} \circ f  \right) d \tilde{\nu}'\\
		 = \int_{S^{L'}_y(N)} F^{\varphi(x;y)}_{\mu', N}  d \tilde{\nu}' = \left(\mu' \otimes \nu' \right) \left( \varphi(x,y) \right),
	\end{gather*}
where the first and last equalities are by definition of $\otimes$, the second equality is by the change of variables formula for push-forward measures (and as usual $F_{\mu,N}^{\varphi(x;y)}: S_{y}(N) \to [0,1]$ is defined by $F_{\mu,N}^{\varphi(x;y)}(q) = \mu(\varphi(x;b))$ for some (equivalently, by invariance of $\mu$, any) $b \models q$ in $\cU$).
	\end{proof}


	It follows that $\mu \ast \mu = \left(\mu' \ast \mu' \right)\restriction_{L} = \mu' \restriction_{L} = \mu$.

	(3) Let $\varphi(x) \in L(\cU)$ be arbitrary, we want to show that $\mu^{\otimes 2}(\varphi(x_1 \cdot x_0, x_0)) = \mu^{\otimes 2} (\varphi(x))$.
	By the above and generic transitivity of $\mu'$ we have
	\begin{gather*}
		\mu^{\otimes 2}(\varphi(x_1 \cdot x_0, x_0)) = (\mu')^{\otimes 2}(\varphi(x_1 \cdot x_0, x_0)) \\
		= (\mu')^{\otimes 2}(\varphi(x_1, x_0)) = (\mu)^{\otimes 2}(\varphi(x_1, x_0)),
	\end{gather*}
 hence $\mu$ is generically transitive.
	\end{proof}

	\begin{remark}
		It was pointed out to me by Kyle Gannon that fim transfers to reducts in arbitrary theories.  Indeed, by \cite[Lemma 3.6]{arXiv:2308.01801}, in any theory $T$, if $\mu$ is a global measure definable over a small model $M$ (so $\mu$ is invariant over $M$, and for every $\varphi(x,y) \in L$, the map $F^{\varphi}_{\mu}: q \in S_y(M) \mapsto \mu(\varphi(x,b)) \in [0,1]$, for some/any $b \models q$, is continuous), then $\mu$ is fim if and only if $\lim_{n \to \infty} \int_{S_{\bar{x}}(M)} \chi^{\varphi}_{\mu,n} d(\mu^{\otimes n})' = 0$, where $\bar{x} = (x_1, \ldots, x_n)$, $\chi^{\varphi}_{\mu,n}: p \in S_{\bar{x}}(M) \mapsto \sup_{b \in \cU^y}|\Av(\bar{a};\varphi(x,b)) - F^{\varphi}_{\mu}(\tp(b/M))| \in [0,1]$ for some $\bar{a} \models p$ (equivalently any $\bar{a} \models p$; and the map $\chi^{\varphi}_{\mu,n}$ is continuous by the assumption on $F^{\varphi}_{\mu}$).  Now if  $\mu'\in \mathfrak{M}^{L'}_x\left(  \mathbb{M}' \right)$ is fim in $T'$, it is in particular fam, hence $\mu := \mu'\restriction_{L}$ is also fam, hence definable, in the reduct $T$ (in fact, by \cite[Theorem 4.8]{conant2020remarks}, dfs is preserved under reducts). Using Claim \ref{cla: restriction commutes with tensor}, as the value $ \chi_{\mu,n}^{\varphi}$ depends only on the reduct of $\mu'$ to the language containing $\varphi$, the aforementioned integral remains $0$ calculated in $T$.
	\end{remark}


