	\begin{claim}
	$p' := \tp^{L'}(\alpha/M')$ is definable over $M$ in $T'$.
\end{claim}
\begin{proof}


We follow the analysis of formulas in $T$ in \cite[Theorem 3.16]{arXiv:2204.13790} (omitted in the final version of the paper \cite{CHERNIKOV_MENNEN_2025}). In $T$, every formula in any number of variables is equivalent to a Boolean combination of formulas $\varphi(x,y,z)$ in (at most) three singleton variables, which by quantifier elimination in $T$ we can assume to be quantifier-free. We also have  $R_{\varphi(\bar{x}) \land \psi(\bar{x})} \leftrightarrow^{T'} R_{\varphi(\bar{x})} \land  R_{\psi(\bar{x})} $ and $R_{\neg \varphi(\bar{x})} \leftrightarrow^{T'} \neg R_{\varphi(\bar{x})} $ for all $\varphi(\bar{x}), \psi( \bar{x}) \in L(N)$; and given a type, a definition with respect to it for a Boolean combination of formulas is given by a Boolean combination of their definitions. And for every  $\varphi(\bar{x}) \in L(M)$, $R_{\varphi(\bar{x})}(M'') = \varphi(M'')$ (evaluated in $N'' \models T$).
So it suffices to show the following for every atomic $\varphi(x,y_1,y_2) \in L$ with $x,y_1,y_2$ singletons:
	\begin{enumerate}
		\item for every fixed $b \in N$, the set $\{a \in M' : N'' \models \varphi(\alpha;a,b)\}$ is of the form $\psi(M')$ for some $\psi(y_1) \in L(N)$ (hence $L'(M)$-definable in $\widetilde{M}'$ via $R_{\psi(y_1)}(y_1)$);
		\item  the set $\{(a_1,a_2) \in (M')^2 : N'' \models  \varphi(\alpha,a_1,a_2)\}$ is of the form $\psi(M')$ for some $\psi(y_1,y_2) \in L(N)$.
	\end{enumerate} 

Up to logical equivalence in $T$,  restricting to formulas involving both $x$ and at least one $y_i$, up to permuting the variables $y_1,y_2$ and replacing by Boolean combinations, we only need to consider the following possibilities for $\varphi(x,y_1,y_2)$: $x = y_1$, $x = x \land y_1$ (i.e.~$x \leq y_1$), $x = y_1 \land y_2$, $x \land y_1 = y_1$ (i.e.~$x \geq y_1$), $x \land y_1 = x \land y_2$, 
$x \land y_1 = x \land y_1 \land y_2$ (i.e.~$(x \land y_1) \leq y_2$), $x \land y_1 \land y_2 = y_1 \land y_2$ (i.e.~$x \geq (y_1 \land y_2)$) (see the proof of \cite[Theorem 3.16]{arXiv:2204.13790}).




We have $N'' \models \alpha <c \land \alpha \not \leq a $ for all $a \in M'$ by the choice of $\alpha$, hence 
\begin{gather}
	\alpha \not \leq a \land b  \textrm{ for any } a \in M', b \in N \label{eq: def type reduct ex 1}
\end{gather}
(as otherwise $\alpha \leq a \land b \leq a \in M'$).




Also, for any $a \in M'$ we have $\alpha = \alpha \land c > a \land c$ (otherwise $\alpha = \alpha  \land c \leq a \land c \leq a$, contradicting \eqref{eq: def type reduct ex 1}). Then
\begin{gather}
	\alpha \land a = (\alpha \land c) \land a = a \land c \textrm{ for all }a \in M' \label{eq: def type reduct ex 2}
\end{gather}



%
%Also, for any $b \in N$ and $a \in M'$, $\alpha \land c > (a \land b) \land c$ (as otherwise  $\alpha = \alpha \land c \leq (a\land b) \land c \leq a \in M'$, contradicting \eqref{eq: def type reduct ex 1}), so 
%\begin{gather}
%	\alpha \land a \land b  = 	\alpha \land a \land b \land c  =  a \land b \land c \textrm{ for all } b \in N, a \in M'. \label{eq: def type reduct ex 3}
%\end{gather}



We consider the non-trivial cases below.

\begin{enumerate}
\item $\varphi(x;y_1,y_2) = x \leq y_1$.

For any $a \in M'$, $\alpha \leq a$ does not hold by \eqref{eq: def type reduct ex 1}.
\item $\varphi(x;y_1,y_2) = (x = y_1 \land y_2)$.

For any $b \in N$ and $a \in M'$, $\alpha = a \land b$ does not hold (by \eqref{eq: def type reduct ex 1}). Similarly, for any $a_1, a_2 \in M'$,  $\alpha = a_1 \land a_2$ does not hold (by \eqref{eq: def type reduct ex 1} again).

\item $\varphi(x;y_1,y_2) = x \geq y_1$.

For any $a \in M'$, by \eqref{eq: def type reduct ex 2} we have $\alpha \geq a \Leftrightarrow \alpha \land a = a \Leftrightarrow a \land c = a \Leftrightarrow a \leq c$.

		\item $\varphi(x,y_1,y_2) = (x \land y_1 = x \land y_2)$.
\begin{enumerate}
		\item  Fix $b \in N$. If $b \land c \geq \alpha$, then $\alpha \land b = \alpha \land a$ does not hold for any $a \in M'$ (as then 
		$\alpha \land b = \alpha \land c \land b = \alpha > a \land c = \alpha \land a$ by \eqref{eq: def type reduct ex 2}). Otherwise $b \land c < \alpha$. Then $\alpha \land b = (\alpha \land c) \land b = b \land c$, so, using \eqref{eq: def type reduct ex 2}, $\alpha \land b = \alpha \land a \Leftrightarrow b \land c = a \land c \Leftrightarrow \widetilde{M}' \models R_{b \land c = y_1 \land c}(a)$.
		\item For any $a_1, a_2 \in M'$, by \eqref{eq: def type reduct ex 2} we have $\alpha \land a_1 = \alpha \land a_2 \Leftrightarrow a_1 \land c = a_2 \land c \Leftrightarrow \widetilde{M}' \models R_{y_1 \land c = y_2 \land c}(a_1,a_2)$.
	\end{enumerate}

	\item $\varphi(x;y_1,y_2) = (x \land y_1) \leq y_2$.
	Fixed $b \in N$. Using \eqref{eq: def type reduct ex 2}, for any $a \in M'$ we have $\alpha \land a \leq b \Leftrightarrow \alpha \land a \land b = \alpha \land b \Leftrightarrow a \land b \land c = a \land c \Leftrightarrow a \land c \leq b$.

	Similarly, for any $a_1,a_2 \in M'$ we get  $\alpha \land a_1 \leq a_2 \Leftrightarrow a_1 \land c \leq a_2 $.


	\item $\varphi(x;y_1,y_2) = (x \geq y_1 \land y_2)$.
	\begin{enumerate}
		\item  Fix $b \in N$. By \eqref{eq: def type reduct ex 2} we have $\widetilde{M}'' \models R_{x \geq y_1 \land b}(\alpha,a) \Leftrightarrow \alpha \geq (a \land b) \Leftrightarrow \alpha \land (a \land b) = a \land b \Leftrightarrow  a\land b \land c = a \land b   \Leftrightarrow c \geq a \land b \Leftrightarrow  \widetilde{M}' \models R_{c \geq (y_1 \land b)}(a)$.
\item For any $a_1, a_2 \in M'$, $a_1 \land a_2 \in M'$, hence $\alpha \geq a_1 \land a_2 \Leftrightarrow (a_1 \land a_2) \leq c \Leftrightarrow \widetilde{M}' \models R_{c \geq (y_1 \land y_2)}(a_1,a_2)$. \qedhere
	\end{enumerate}
\end{enumerate}
\end{proof}

By compactness, we can choose  $a \in M' \setminus M$ so that $X < a < c$, then $a < \alpha$ (by \eqref{eq: def type reduct ex 1}). So $(x > a) \in p'$. But the formula $x > a$ divides over $M$ in $T$, as by density of the tree, quantifier elimination and saturation we can choose $\leq$-incomparable $a_i \in M', i \in \omega$  with $a_i \equiv^L_M a$.
\end{example}
\begin{question}
	Is this possible for an $o$-minimal theory $T$?
\end{question}



\begin{fact}\label{fac: all meas over Sh exp are def}
Assume $T$ is NIP and $M \models T$.
	\begin{enumerate}
		\item  If all types in $S_x(M)$ are definable, then all measures in $\mathfrak{M}_x(M)$ are definable.
		\item All measures in $\mathfrak{M}_x^{L'}(M^{\Sh})$ are definable (in $T' = \Th_{L'}(M^{\Sh})$).
	\end{enumerate}
\end{fact}
\begin{proof}
	(1) By \cite[Theorem 2.7]{chernikov2014external}.

	(2) By (1) for $T'$, as  all types in $S_x^{L'}(M^{\Sh})$ are definable in $T'$ (by definition of Shelah's expansion).
\end{proof}


The following  key lemma in particular generalizes \cite[Lemma 3.18]{chernikov2014external} from types to measures, and from $M$ to arbitrary coherent models:
\begin{lemma}\label{lem: unique extension of def meas to Sh}
	Let $T$ be NIP, $M \models T$ and $T' := \Th_{L'}(M^{\Sh})$ (we are following the notation in Definition \ref{def: Shelah exp context}, in particular $\widetilde{M}'$ is a monster model for $T'$). Let $M_1 \preceq^{L'} \widetilde{M}'$ be  a small coherent model (i.e.~$(N,M) \preceq^{L_P} (N_1,M_1) \prec^{L_P} (N',M')$ for some $N_1$; so e.g.~$M_1 = M$).
	\begin{enumerate}
		\item 	Let $\mu \in \mathfrak{M}_x^{L}(M_1)$ be definable (in $T$). Then there exists a unique measure $\mu' \in \mathfrak{M}_x^{L'}(M_1)$ so that $\mu' \restriction_{L} = \mu$, and $\mu'$ is definable over $M_1$ in $T'$ (moreover, if $\mu$ is definable over $A \subseteq M_1$ in $T$, then $\mu'$ is also definable over $A$ in $T'$). In fact  for every $\psi(x) \in L'(M_1)$ we have:
		\begin{gather*}
			\mu'(\psi(x)) = \sup \left\{ \mu(\varphi(x)) :  \varphi(x) \in L(M_1), \varphi(M_1) \subseteq \psi(M_1) \right\} \\
			= \inf \left\{ \mu(\varphi'(x)) :  \varphi'(x) \in L(M_1), \psi(M_1) \subseteq \varphi'(M_1) \right\}.
		\end{gather*}

		\item If  $\bar{\mu} \in \mathfrak{M}_x^{L}(M')$ is the definable over $M_1$ extension of $\mu \in \mathfrak{M}_x^{L}(M_1)$ (in $T$), then  there exists a unique measure $\bar{\mu}' \in \mathfrak{M}_x^{L'}(M')$ so that $\bar{\mu}' \restriction_{L} = \bar{\mu}$. Moreover, $\bar{\mu}'$ is the $M_1$-definable extension of $\mu'$  in $T'$.
	\end{enumerate}
\end{lemma}
\begin{proof}

(1) Let $\mu \in \mathfrak{M}_x^{L}(M_1)$ be definable, and let $\bar{\mu} \in \mathfrak{M}_x^{L}(M')$ be the (unique, by Remark \ref{rem: unique def ext of definable measure}) global $M_1$-definable extension of $\mu$ (in $T$).
 Let $\bar{\mu}' \in \mathfrak{M}_x^{L'}(M')$ be arbitrary so that $\bar{\mu}' \restriction_{L} = \bar{\mu}$ (note that there exists one by Fact \ref{fac: classic measure ext} applied for the Boolean algebra of $L'(M')$-definable subsets of $M'$), and let $\mu' := \bar{\mu}'|_{M_1}$. Note that $(\bar{\mu}'|_{M}) \restriction_{L} = \mu' \restriction_{L} = \mu$.


Take any $\psi(x,y) \in L'$ and $b \in M_1$, and let $r := \mu'(\psi(x,b))$. We have that $\psi(x,y)$ is equivalent in $T'$ to $R_{\varphi(x,y;e)}(x,y)$ for some $\varphi(x,y;y') \in L$ and $e$ in $N^{y'}$, i.e.~$\psi(M') = \varphi(M';e)$.
By Fact \ref{fac: honest defs} (including the ``moreover'' part) applied to $(N_1,M_1)$ there is some $\theta(x,y;z) \in L$ and some $c \in (M')^z$ so that $\theta(M',c) \subseteq \varphi(M',e) = R_{\varphi(x,y;e)}(M')$ and no type $q \in S_{x,y}^{L}(M')$ invariant over $M_1$ in $T$ is consistent with $\{ \varphi(x,y;e) \setminus \theta(x,y;c)\} \cup \{P(x) \land P(y)\}$ in $\Th_{L_P}(N',M')$ (equivalently, with $R_{\varphi(x,y;e)}(x,y) \setminus \theta(x,y;c)$ in $T'$).





Let $\bar{p}' \in S(\bar{\mu}')$ be arbitrary. Then for $\bar{p}:= \bar{p}' \restriction_{L}$ we have $\bar{p} \in S(\bar{\mu})$ by definition of support. As $\bar{\mu}$ is definable over $M_1$ in $T$, it is in particular invariant over $M_1$ in $T$, hence by NIP every type $\bar{p} \in S(\bar{\mu})$ is also $M_1$-invariant in $T$ (Fact \ref{fac: types in sup of inv meas are inv NIP}). 
Suppose that $\left( R_{\varphi(x,y;e)}(x,b) \setminus \theta(x,b;c) \right) \in  \bar{p}'$, and let $a \models \bar{p}'$ in a bigger monster model $\widetilde{M}''$ (as in Definition \ref{def: Shelah exp context}). Then $(a,b) \models R_{\varphi(x,y;e)}(x,y) \setminus \theta(x,y;c)$ and $\tp^L(a,b/M')$ is invariant over $M_1$ in $T$ (as, working in $T$, $\tp^L(b/M')$ is obviously invariant over $M_1$ as $b \in M_1$ and $\tp^L(a/M'b)$ is invariant over $M_1$ as $a \models \bar{p}$, so we can apply left transitivity of invariance, see e.g.~\cite[Remark 2.20]{chernikov2012forking}). But this contradicts the choice of $\theta(x,y;c)$. As $\bar{p}' \in S(\bar{\mu}')$ was arbitrary, this shows that  $\bar{\mu}' \left( R_{\varphi(x,y;e)}(x,b) \setminus \theta(x,b;c) \right) = 0$, so $\bar{\mu}'(\theta(x,b,c)) = \bar{\mu}(\theta(x,b,c)) = r$. 

As the measure $\bar{\mu}$ is $M_1$-definable in $T$, for every $\varepsilon \in \mathbb{R}_{>0}$ there is some $\chi_{\varepsilon}(y,z) \in L(M_1)$ so that $\chi_{\varepsilon}(y,z) \in \tp^{L}((b,c)/M_1)$ and for every $(b',c') \in (M')^{y,z}$ with $\models \chi_{\varepsilon}(b',c')$ we have $\bar{\mu}(\theta(x,b',c')) \approx^{\varepsilon} \bar{\mu}(\theta(x,b,c))$, in particular $\bar{\mu}(\theta(x,b',c')) \geq r - \varepsilon$. So we have 
\begin{gather*}
	(N',M') \models \chi_{\varepsilon}(b,c) \land \forall x \in P \left( \theta(x,b,c) \rightarrow \varphi(x,b,e) \right).
\end{gather*}
As $(N,M) \preceq (N_1,M_1) \prec (N',M') $, $b \in M_1^y$ and $e \in N^z$,  there is some $c_{\varepsilon} \in M_1^z$ so that 
\begin{gather*}
	(N,M) \models \chi_{\varepsilon}(b,c_{\varepsilon}) \land \forall x \in P \left( \theta(x,b,c_{\varepsilon}) \rightarrow \varphi(x,b,e) \right).
\end{gather*}
That is, for every $\varepsilon >0$ there is some $c_{\varepsilon} \in M_1^{z}$ so that $\theta(M';b,c_{\varepsilon}) \subseteq \varphi(M';b,e)$ and $\mu(\theta(x,b,c_{\varepsilon})) = \bar{\mu}(\theta(x,b,c_{\varepsilon}))  \geq r - \varepsilon$. Applying the same argument with $\neg \varphi(x,y;e)$ instead of $\varphi(x,y;e)$, we find some $\theta'(x,y;z') \in L$ so that 
for every $\varepsilon >0$ there is some $c'_{\varepsilon} \in M_1^{z'}$ with $\varphi(M';b,e) \subseteq \theta'(M';b, c'_{\varepsilon})$ and $\mu(\theta'(x,b,c'_{\varepsilon})) = \bar{\mu}(\theta'(x,b,c'_{\varepsilon})) \leq r + \varepsilon$. But if now $\mu'' \in \mathfrak{M}_x^{L'}(M)$ is an arbitrary measure in $T'$ extending $\mu$, it in particular has to satisfy $\mu(\theta(x,b,c_{\varepsilon})) \leq \mu''(\varphi(x,b,e)) \leq \mu(\theta'(x,b,c'_{\varepsilon}))$	for every $\varepsilon > 0$, hence $\mu''(\psi(x,b)) =  r = \mu'(\psi(x,b))$. As $\psi(x,b) \in L'(M_1)$ was arbitrary, it follows that $\mu'$ is the unique measure  in $\mathfrak{M}_x^{L'}(M)$  extending $\mu$. 


Finally, if $M_1 = M$ then all measures in $\mathfrak{M}^{L'}_x(M)$ are definable in $T'$ by Fact \ref{fac: all meas over Sh exp are def}, but this need not be the case over an arbitrary coherent $M_1$. In that case we let 
$$\chi'_{\varepsilon}(y) := \exists c_{\varepsilon} \left( \chi_{\varepsilon}(y,c_{\varepsilon}) \land  \forall x \left( \theta(x,y,c_{\varepsilon}) \rightarrow R_{\varphi(x,y;e)}(x,y) \rightarrow \theta'(x,y,c'_{\varepsilon})  \right) \right).$$

Then, by the above, $\chi'_{\varepsilon}(y) \in \tp^{L'}(b/M_1)$, and for any $b' \in (M_1)^y$ with $\widetilde{M}' \models \chi'_{\varepsilon}(b')$ we have $\mu'(\psi(x,b')) \approx^{\varepsilon} \mu'(\psi(x,b)) $. This shows that $\mu'$ is definable over $M_1$ in $T'$ (also shows the ``moreover'' part as $\chi'_{\varepsilon}$ only uses the same parameters in $M_1$ as $\chi_{\varepsilon}$).

(2) Applying (1) to $\bar{\mu}$ and $(M'\restriction_{L})^{\Sh}$ (as a structure in a language $L'' \supseteq L'$), we see that $\bar{\mu}$ has a unique extension to a measure in $\mathfrak{M}^{L''}_x((M')^{\Sh})$, hence in particular a unique extension to a measure $\bar{\mu}' \in \mathfrak{M}^{L'}_x(M')$ (note that each of the two different extensions to a subalgebra would extend to the full algebra by Fact \ref{fac: classic measure ext}).

Note that $\mu' \in \mathfrak{M}_x^{L'}(M_1)$ is definable in $T'$ by (1). Let $\bar{\mu}'' \in \mathfrak{M}_x^{L'}(M')$ be the unique $M_1$-definable extension of $\mu'$, in $T'$ (by Remark \ref{rem: unique def ext of definable measure}). We claim that $\bar{\mu}'' \restriction_{L} = \bar{\mu}$, hence  $\bar{\mu}'' = \bar{\mu}'$ as wanted. Assume not, then there is some $\varphi(x,y) \in L$ and $c \in (M')^y$ with $\bar{\mu}(\varphi(x,c)) = r  < s = \bar{\mu}''(\varphi(x,c)) $. Let $\varepsilon := (s-r)/3$. As $\bar{\mu}$ is definable over $M_1$ in $T$, there is some $\chi(y) \in L(M_1)$ so that $M' \models \chi(c)$ and $\bar{\mu}(\varphi(x,c')) \approx^{\varepsilon} \bar{\mu}(\varphi(x,c))$ for all $c' \in (M')^y$ with $M' \models \chi(c')$. Similarly, as $\bar{\mu}''$ is definable over $M_1$ in $T'$, there is some $\chi''(y) \in L'(M_1)$ so that $\widetilde{M}' \models \chi''(c)$ and $\bar{\mu}''(\varphi(x,c')) \approx^{\varepsilon} \bar{\mu}''(\varphi(x,c))$ for all $c' \in (M')^y$ with $\widetilde{M}' \models \chi(c')$.
As $\widetilde{M}' \models \chi(c) \land \chi''(c)$ and $M_1 \prec^{L'} \widetilde{M}'$ (by coherence, see Definition \ref{def: Shelah exp context}), there is some $c' \in M_1^y$ so that $\widetilde{M}' \models \chi(c') \land \chi''(c')$, hence $\bar{\mu}(\varphi(x,c')) \leq r + \varepsilon < s - \varepsilon \leq  \bar{\mu}''(\varphi(x,c')) $.
But $\bar{\mu}'' |_{M_1} = \mu'$, $\bar{\mu} |_{M_1} = \mu$ and $\mu' \restriction_{L} = \mu$, a contradiction.
\end{proof}

Using this, we establish a one-to-one correspondence between global generically stable measures in $T$ and in $\Th(M^{\Sh})$:
\begin{theorem}\label{thm: corresp for gs measures}
	Let $T$ be NIP, $M \models T$, $T' := \Th_{L'}\left(M^{\Sh} \right)$ and $\widetilde{M}'$ is a monster model for $T'$ (we are following the notation in Definition \ref{def: Shelah exp context}). Then the map $\bar{\mu}' \in \mathfrak{M}_x^{L'}(M') \mapsto \bar{\mu} := \bar{\mu}'\restriction_{L}  \in \mathfrak{M}_x^{L}(M')$ defines a bijection between global generically stable measures in $T'$ and global generically stable measures in $T$. Moreover, 
	$\bar{\mu}'$ is the unique measure in $\mathfrak{M}_x^{L'}(M')$ extending $\bar{\mu}$; and for any small set $A \subset M'$: 
	\begin{enumerate}
		\item if $\bar{\mu}'$ is fam over  $A$ in $T'$, then $\bar{\mu}$ is fam over $A$ in $T$;
		\item if $\bar{\mu}$ is generically stable over $A$ in $T$, then $\bar{\mu}'$ is generically stable over $A$ in $T'$ (see Remark \ref{rem: gs over a set but not fs}).
	\end{enumerate}
\end{theorem}
\begin{proof}


If $\bar{\mu}' \in \mathfrak{M}_x^{L'}(M')$ is fam over some small $A \subset M'$ in $T'$, then $\bar{\mu} := \bar{\mu}' \restriction_{L}$ is also fam over $A$ in $T$ by Proposition \ref{prop: properties of reducts of measures}(1). 

Conversely, assume $\bar{\mu} \in \mathfrak{M}_x^{L}(M')$ is generically stable in $T$, over some small set $A \subset M'$. Let $M_1$ with $A \subseteq M_1 \prec^{L'} \widetilde{M}'$ be a small coherent model (exists by Definition \ref{def: Shelah exp context}), in particular $\bar{\mu}$ is definable over $M_1$ in $T$. Then, by Lemma \ref{lem: unique extension of def meas to Sh}, $\bar{\mu}$ extends to a unique measure $\bar{\mu}' \in \mathfrak{M}_x^{L'}(M')$, and $\bar{\mu}'$ is definable over $A$ in $T'$ (by the ``moreover'' part of Lemma \ref{lem: unique extension of def meas to Sh}(1)). 


Let $\mu := \bar{\mu}|_{M_1},  \mu' := \bar{\mu}'|_{M_1}$.
		Let $\bar{\mu}'' \in  \mathfrak{M}_x^{L'}(M')$ be an extension of $\mu'$ finitely satisfiable in $M_1$ (every measure over a model has a global coheir, by Fact \ref{fac: classic measure ext} applied to externally definable subsets of this model). Then $\bar{\mu}'' \restriction_{L}$ is also finitely satisfiable in $M_1$, hence is equal to $\bar{\mu}$ (by generic stability and Fact \ref{fac: basic props gen stab meas}, $\bar{\mu}$ is the unique $M_1$-invariant extension of $\mu$ in $T$). But then $\bar{\mu}'' = \bar{\mu}'$ by uniqueness, hence  $\bar{\mu}'$ is also finitely satisfiable in $M_1$, so generically stable over $M_1$ in $T'$ by NIP (Fact \ref{fac: NIP gen stab meas equivs}).
