\begin{remark}
The proof of Theorem \ref{thm: main for fsg subgroups} goes through with $M_1$ instead of $M$, for an arbitrary coherent model $M_1 \prec^{L'} \widetilde{M}'$ so that $(M,N) \prec^{L_P} (M_1,N_1) \prec^{L_{P}}(M',N')$ for some $N_0 \prec^L N_1 \prec^L N'$.
\end{remark}

\begin{remark}\label{rem: no fsg subgroups applies to reducts}
	We note that Theorem \ref{thm: main for fsg subgroups} also applies to arbitrary reducts of $M^{\Sh}$ expanding $M$. Indeed, assume $M'' = M^{\Sh} \restriction_{L''}$ for some $L \subseteq L'' \subseteq L' = L^{\Sh}$, $G$ an $M$-definable group and $H$ is a subgroup of $G$ definable in $M''$ and fsg in the sense of $\Th_{L''}(M'')$. Then, Fact  \ref{fac: group props preserved in Sh exp}(1), $H$ is also fsg in the sense of $\Th_{(L'')^{\Sh}}((M'')^{\Sh})$, and $(M'')^{\Sh} = (M')^{\Sh}$ (up to a correct identification of the languages), so Theorem \ref{thm: main for fsg subgroups} applies.
	\end{remark}

\begin{corollary}\label{cor: fsg subgroups in RCVF}
Let $\RCVF$ be the theory of real closed valued fields, $M'' \models \RCVF$ arbitrary. If $G$ is definable in the reduct $M$ of $M''$ to $\RCF$, and $H \leq G$ is definable in $M''$ and is fsg, then $H$ is already definable in $M$.
\end{corollary}
\begin{proof}
	Let $L''$ be the language of rings with an additional unary predicate for the valuation ring. Given any $L''$-model $M'' \models \RCVF$, let $M \models \RCF$ be its reduct to the language of rings $L$. As the valuation ring is convex, it is externally definable in $M$, hence $M''$ is a (proper) reduct of $M^{\Sh}$. Using Remark \ref{rem: no fsg subgroups applies to reducts}, Theorem \ref{thm: main for fsg subgroups} applies.
\end{proof}

\subsection{Fsg groups both type-definable and externally definable}
\label{sec: Type-definable and externally definable fsg groups are definable}
We also show that, for a sufficiently saturated $M$, every type-definable  fsg group in $M$ which is externally definable, is already definable.

\begin{theorem}\label{thm: type-def and ext def fsg implies def}
Let $T$ be an NIP $L$-theory, $G$ a type-definable over $M_0 \models T$ group  and $M \succ M_0$ is $|M_0|^{+}$-saturated. Assume $G$ is fsg in $T$ as a type-definable group, and $G(M)$ is definable in $M^{\Sh}$. Then $G$ is already a definable group in $M$ (hence $H=G$ is fsg as a definable group in $T'$).
\end{theorem}
\begin{proof}

	First we generalize Fact \ref{fac: group props preserved in Sh exp}(1) and show that $G$ is still fsg as a type-definable group in $T' := \Th_{L'}(M^{\Sh})$. 	The proof as for definable groups in \cite[Theorem 3.19]{chernikov2014external}  could be adapted, but we give a proof with measures instead.


		As $G$ is type-definable over $M_0$ in $T$ and $M \succ^L M_0$ is $|M_0|^+$-saturated, by Proposition \ref{prop: fsg iff inv gen stab meas} there is a global measure $\bar{\mu} \in \mathfrak{M}_G^L(M')$ which is $G(M')$-left-invariant and generically stable over $M$ in $T$. Let $\mu := \bar{\mu}\restriction_{M}$.


		By Lemma \ref {lem: unique extension of def meas to Sh}, there exists a unique measure $\bar{\mu}' \in \mathfrak{M}_x^{L'}(M')$ with $\bar{\mu}' \restriction_{L} = \bar{\mu}$, clearly $\bar{\mu}' \in \mathfrak{M}_{G}^{L'}(M')$. By Theorem \ref{thm: corresp for gs measures}, $\bar{\mu}'$ is generically stable over $M$ in $T'$.



		By the ``moreover'' part of Lemma \ref{lem: unique extension of def meas to Sh}(2), $\bar{\mu}'$ is definable over $M$ in $T'$. Let $\mu' := \bar{\mu}'|_{M}$.
		Let $\bar{\mu}'' \in  \mathfrak{M}_x^{L'}(M')$ be an extension of $\mu'$ finitely satisfiable in $M$ (every measure over a model has a global coheir, by Fact \ref{fac: classic measure ext} applied to externally definable subsets of this model). Then $\bar{\mu}'' \restriction_{L}$ is also finitely satisfiable in $M$, hence is equal to $\bar{\mu}$ (by Fact \ref{fac: basic props gen stab meas}, $\bar{\mu}$ is the unique $M$-invariant extension of $\mu$ in $T$). But then $\bar{\mu}'' = \bar{\mu}'$ by uniqueness, hence  $\bar{\mu}'$ is also finitely satisfiable in $M$, so generically stable over $M$ in $T'$.
%	We also have that $\bar{\mu}$ is $G(M')$-invariant.  Indeed, assume not, then there is some $g \in G(M')$ and $\varphi(x,y) \in L, b \in (M')^{y}$ so that $\bar{\mu}(\varphi(x,b)) = r < s = \bar{\mu}(\varphi(g \cdot x,b))$.
%	By saturation of $M$, there are some $g', b'$ in $M$ with $(g',b') \equiv_{M_0}^{L} (g,b)$. Then $g' \in G(M)$ and, as $\bar{\mu}$ is $M_0$-invariant in $T$, we have $\mu(\varphi(x,b')) = r <  s = \mu(\varphi(g' \cdot x,b'))$, contradicting $G(M)$-invariance of $\mu$.  
 And $\bar{\mu}'$ is also $G(M')$-invariant: given $g \in G(M')$, $g \cdot \bar{\mu} = \bar{\mu} $ and $(g \cdot \bar{\mu}') \restriction_{L} = g \cdot (\bar{\mu}'\restriction_{L}) = g \cdot \bar{\mu} = \bar{\mu}$, so $g \cdot \bar{\mu}' = \bar{\mu}'$ by uniqueness. By Proposition \ref{prop: fsg iff inv gen stab meas}, $\bar{\mu}'$ witnesses that the type-definable group $G$ is fsg in $T'$.




	Now  $G$ is type-definable over $M_0$ is $T$ by some partial type $\{\psi_{\alpha}(x) : \alpha < |M_0|\}$ with $\psi_{\alpha} \in L(M_0)$, without loss of generality closed under finite conjunctions. And $G(M)$ is also definable in $M^{\Sh}$, that is 	there is some formula 
	$H(x) \in L'(M)$ so that $G(M) = H(M)$.
	For every $\alpha$, as $\psi_{\alpha}(M) \supseteq H(M)$, $H(M') = \theta(M',c)$ for some $\theta(x,y) \in L$ and $c \in N^y$,  and $(N',M') \succ (N,M)$, we still have $\psi_{\alpha}(M') \supseteq H(M')$, hence $G(M') \supseteq H(M')$, but in general this could be a proper containment (e.g.~take $G$ as the type-definable subgroup of infinitesimals on a unit circle group in $T =\RCF$).

	We claim that still $\bar{\mu}'$ is supported on $H(x)$, that is $\bar{\mu}' \in \mathfrak{M}_{H}^{L'}(M')$  in $T'$.
	Indeed,	by Lemma \ref{lem: unique extension of def meas to Sh}(1), 
	$$\mu'(H(x)) = \inf \left\{ \mu(U(x)) :  U(x) \in L(M), H(M) \subseteq U(M) \right\}.$$
	As $\mu \in \mathfrak{M}^{L}_G(M)$, we have $\mu(\psi_{\alpha}(x)) = 1$ for all $\alpha$.
	But if $U(x) \in L(M)$ and $U(M) \supseteq H(M) = G(M)$, then by $|M_0|^+$-saturation of $M$ we have $U(M) \supseteq \psi_{\alpha}(M)$ for some $\alpha$ (using closure under conjunctions), so $\mu(U(x)) = 1$. We conclude $\mu'(H(x)) = 1$.

	So we have $H(M') \leq G(M')$, and we claim $H(M') = G(M')$. Assume not, then $H(M') \cap g \cdot H(M') = \emptyset$ for some $g \in G(M')$. As $\bar{\mu}' \in \mathfrak{M}^{L'}_{H}(M')$, we have $S(\bar{\mu}') \subseteq S^{L'}_{H}(M'), S(g \cdot \bar{\mu}') \subseteq S^{L'}_{g \cdot H}(M')$, so $S(\bar{\mu}') \cap  S(g \cdot \bar{\mu}') = \emptyset$, so $\bar{\mu}' \neq g \cdot \bar{\mu}'$ --- a contradiction as $\bar{\mu}'$ is $G(M')$-invariant.

 Finally, as $H(M') = G(M')$, saturation of the $L_P$-structure $(N', M')$ implies $G(M') = \bigcap_{\alpha \in s}\psi_{\alpha}(M')$ for some finite $s$, so $G$ is $L(M_0)$-definable in $T$.
\end{proof}


The following proposition gives some criteria that could be used to see that certain externally definable groups are not fsg in $\Th(M^{\Sh})$:


\begin{proposition}\label{prop: ext def V def fsg implies definable} ($T$ NIP) Suppose $M_0 \prec M$ and $M$ is $|M_0|^+$-saturated. 
\begin{enumerate}
	\item Suppose $G$ is type-definable over $M_0$ and $G(M) = H(M)$ for $H$ a definable group in $M^{\Sh}$.  If $H$ is fsg as a definable group in $T' = \Th(M^{\Sh})$, then $G$ is fsg as a type-definable group in $T$ (hence again $G$ is already definable).
	\item Similarly, suppose $G$ is $\bigvee$-definable over $M_0$ and $G(M) = H(M)$ for $H$ a definable group in $M^{\Sh}$.  If $H$ is fsg as a definable group in $T'$, then $G$ is definable (and fsg) in $M$.
%	\item Suppose $H$ is a definable fsg group in $M^{\Sh}$. Assume $\mu \in \mathfrak{M}^L_x(M)$ is such that $\mu(\varphi(x)) = \mu(\varphi(h \cdot x))$ and if $\mu(\varphi(x)) > 0$ then $\varphi(x) \land H(x)$ is consistent (in $T'$), for all $\varphi(x) \in L(M)$ and $h \in H(M)$. Then  $\mu$ is finitely satisfiable in some small $M_1 \prec M$.
\end{enumerate}
\end{proposition}
\begin{proof}
	(1) Let $\bar{\mu}' \in \mathfrak{M}_{H}^{L'}(M')$ be a global left-$H(M')$-invariant measure generically stable over $M$ in $T'$ (Fact \ref{fac: fsg groups basic props}(2)). Let $\bar{\mu} := \bar{\mu}' \restriction_{L}$, then $\bar{\mu}$ is generically stable over $M$ in $T$ (Proposition \ref{prop: properties of reducts of measures}), hence generically stable over some $M_1$ with $M_0 \leq M_1 \prec M$ and $|M_1| \leq |T|$. Also $\bar{\mu} \in \mathfrak{M}_{G}^{L}(M')$ (if $G(x) = \bigcap_{i \in I}{\psi_{i}(x)}$ with $\psi_{i}(x) \in L(M_0)$, then $H(M) = G(M)$ implies $H(x) \vdash^{T'} \psi_i(x)$ for all $i \in I$, so $\bar{\mu}(\psi_i(x)) = \bar{\mu}'(\psi_i(x)) \geq \bar{\mu}'(H(x)) = 1$) and $\bar{\mu}$ is left-$H(M')$-invariant. Let $\mu := \bar{\mu}\restriction_{L}$, then $\mu$ is generically stable over a small model $M_1 \prec^L M$, $\mu \in \mathfrak{M}_{G}^L(M)$ and $\mu$ is left-$G(M)$-invariant (as $G(M) = H(M)$) --- witnessing that $G$ is fsg as a type-definable group in $T$.

(2) Similarly, suppose $G$ is $\bigvee$-definable over $M_0$, $M$ is $|M_0|^+$-saturated and $G(M) = H(M)$ for $H$ a definable group in $M^{\Sh}$.  If $H$ is fsg as a definable group in $T'$, then $G$ is definable (and fsg).

Indeed, let again $\bar{\mu}' \in \mathfrak{M}_{H}^{L'}(M')$ be a global left-$H(M')$-invariant measure generically stable over $M$ in $T'$. Say $G(x) = \bigvee_{i \in I}{\psi_{i}(x)}$ with $\psi_{i}(x) \in L(M_0)$, and without loss of generality $\{\psi_{i}(x) : i \in I\}$ is closed under disjunctions. Then $\psi_i(M) \subseteq H(M)$ for all $i \in I$ and $G(M') \leq H(M')$, as $H(M) = G(M)$. 
By Lemma \ref{lem: unique extension of def meas to Sh}(1) we have
	$$1 = \bar{\mu}'(H(x)) = \sup \left\{ \bar{\mu}'(U(x)) :  U(x) \in L(M), U(M) \subseteq H(M) \right\}.$$
If $U(x) \in L(M)$ and $U(M) \subseteq H(M) = G(M)$, then by $|M_0|^+$-saturation of $M$ we have $U(M) \subseteq \psi_{i}(M)$ for some $i \in I$ (using closure under disjunctions), so $\sup \left\{ \bar{\mu}'(\psi_i(x)) :  i \in I \right\} = 1$. Assume $G(M') \lneq H(M')$, then $G(M') \cap h \cdot G(M') = \emptyset$ for some $h \in H(M')$. We have $\bar{\mu}'(\psi_i(x)) > 1/2$ for some $i \in I$, so also $\bar{\mu}'(h \cdot \psi_i(x)) > 1/2$ by $H(M')$-invariance of $\bar{\mu}'$, contradicting these sets being disjoint. So $H(M') = G(M')$, hence $G(M') = \bigcup_{i \in I_0}\psi_{i}(M')$ for some finite $I_0 \subseteq I$ (by saturation of the $L_P$-structure $(N', M')$), so $G$ is $L(M_0)$-definable in $T$.
