\begin{example}\label{ex: infinitesim not fsg}
(1) Let $T = \RCF$, $M \models T$ is $|T|^{+}$-saturated, $G(M) = ([0,1)(M), + \mod 1)$ is the definable (non-standard) unit circle group, and $H(M) \leq G(M)$ is the subgroup of infinitesimals, then $H(M) = G^{00}(M)$ is definable in $M^{\Sh}$ (as it is convex with respect to the circular order) and a type-definable over $M_0 := \mathbb{R}$ subgroup of bounded index of $G$ in $M$, but not definable in $M$ by $o$-minimality. It follows that $H$ is not fsg in $T' := \Th_{L'}(M^{\Sh})$ (and $G^{00}$ is not fsg as a type-definable group in $T$), either by Theorem \ref{thm: main for fsg subgroups} or Proposition \ref{prop: ext def V def fsg implies definable}(1). 


(2)	Let $M = (K, \Gamma, k, v) \models \ACVF$ with valuation ring $\mathcal{O}_v = \{a \in K : v(a) \geq 0\}$, and let $v'$ be a coarsening of $v$, i.e.~a valuation $v'$ on $K$ with $\mathcal{O}_{v'} \supseteq \mathcal{O}_v$. Then there is a convex subgroup $\Gamma' \leq \Gamma$ such that $v'K \cong vK/\Gamma'$. Then $\Gamma'$ is definable in $M^{\Sh}$, and hence $\mathcal{O}_{v'} = \{ a \in K : a \in \mathcal{O}_{v} \lor v(a) \in \Gamma' \}$ is also definable in $M^{\Sh}$ (see e.g.~\cite[Example 2.2]{zbMATH07845700}) and a subgroup of $(K,+)$. It follows that $\mathcal{O}_{v'}$ is not fsg in $M^{\Sh}$, by Theorem \ref{thm: main for fsg subgroups} (or by Proposition \ref{prop: ext def V def fsg implies definable} if $\Gamma'$ is either type-definable or $\bigvee$-definable in $M$). 
\end{example}


\subsection{Generically stable measures as a hyper-definable set}\label{sec: Generically stable measures as a hyper-definable set}
An important point in \cite{hrushovski2016non} and subsequent work is that the set of global generically stable types in NIP theories can be viewed as a pro-definable (i.e.~a type-definable set of length $|T|$ tuples)  set in $\cU^{\eq}$. Here we consider an analogous presentation for the set of global generically stable measures in an NIP theory, but as a \emph{hyper-definable}  set  of  length $|T|$ tuples. In particular this is convenient for carrying out some compactness arguments with generically stable measures (which do not form a closed subset of the space of all global Keisler measures), e.g.~in Section \ref{sec: abelian ext def subgroups}. Recall from Fact \ref{fac: NIP gen stab meas equivs}:
\begin{definition}
	A Keisler measure $\mu \in \mathfrak{M}_x(\cU)$ is \emph{fam} (finitely approximated measure) if for every $\varphi(x,y) \in L$ and $\varepsilon > 0$ there is some $n$ and $\bar{a}^{\mu}_{\varphi, \varepsilon} = (a_1, \ldots, a_n) \in (\cU^x)^n$ so that $\bar{a}^{\mu}_{\varphi, \varepsilon}$ is an \emph{$\varepsilon$-approximation for $\mu$ on $\varphi(x,y)$}, i.e.~for every $b \in \cU^y$ we have 
		\begin{gather*}
		 \left \lvert \Av(\bar{a}^{\mu}_{\varphi, \varepsilon}; \varphi(x,b))	- \mu \left( \varphi(x,b) \right) \right \rvert \leq \varepsilon.
		\end{gather*}
	For $A \subseteq \cU$, we say that $\mu$ is \emph{fam over $A$} if $\bar{a}^{\mu}_{\varphi, \varepsilon}$ can be chosen in $A$ for all $\varphi, \varepsilon$.
\end{definition}

\begin{fact}\label{fac: unif e approx for gs measures in NIP}

	\begin{enumerate}
		\item If $T$ is NIP and $M \prec \cU$, then $\mu \in \mathfrak{M}_x(\cU)$ is generically stable (over $M$) if and only if it is fam (over $M$).
		\item For every NIP formula $\varphi(x,y) \in L$ (in $T$) and $\varepsilon > 0$ there is some $n_{\varphi, \varepsilon} \in \omega$  depending only on $\varphi$ and $\varepsilon$ so that: for any $\mu \in  \mathfrak{M}_x(\cU)$, if $\mu$ is fam over $M$ then there is an $\varepsilon$-approximation $\bar{a}^{\mu}_{\varphi, \varepsilon} = (a_1, \ldots, a_n) \in M^n$ for $\mu$ on $\varphi(x,y)$ with $n \leq n_{\varphi, \varepsilon}$ (see e.g.~\cite[Proposition 2.13]{zbMATH06966829} for an explanation of the uniform bound).
\end{enumerate}
\end{fact}

\begin{remark}\label{rem: eps approx precise size}
	In Fact \ref{fac: unif e approx for gs measures in NIP}(2), taking $n'_{\varphi, \varepsilon} := (n_{\varphi, \varepsilon})! $, we can
choose an $\varepsilon$-approximation of size \emph{exactly} $n'_{\varphi, \varepsilon}$ (indeed, given a tuple $\bar{a}$ of size $n \leq n_{\varphi, \varepsilon}$ which is an $\varepsilon$-approximation, we can take a tuple of length $n'_{\varphi, \varepsilon}$ which is a concatenation of (integer many) copies of $\bar{a}$ --- it still gives an $\varepsilon$-approximation.
\end{remark}

Assume that $T$ is NIP, and let $x$ be a tuple of variables of fixed sort.

\begin{definition}\label{def: a^mu coding measure}
	Given any generically stable measure $\mu \in \mathfrak{M}_x(\cU)$, we associate to it a tuple $\bar{a}^{\mu} = \left(\bar{a}^{\mu}_{\varphi, 1/k} : \varphi(x,y) \in L, k \in \mathbb{N} \right)$ of length $|T|$ so that $\bar{a}^{\mu}_{\varphi, 1/k} \in (\cU^{x})^{n_{\varphi, 1/k}}$ is an $1/k$-approximation for $\mu$ on $\varphi(x,y)$ of length $n_{\varphi, 1/k}$ (exists by Remark \ref{rem: eps approx precise size}).
\end{definition}
 We will establish a bijection between the set of global generically stable measures (in $x$) and a particular hyperdefinable set of such tuples.

\begin{definition}
	We let $X' = X'_x$ be the set of all tuples 
	$$\bar{a} = \left(\bar{a}_{\varphi, 1/k} : \varphi(x,y) \in L, k \in \mathbb{N} \right)$$ 
	in $\cU$ satisfying: 
\begin{gather*}
	\bigwedge_{\varphi(x,y) \in L} \bigwedge_{k_1, k_2 \geq k \in \mathbb{N} } \forall b \left( \left\lvert\Av(\bar{a}_{\varphi, 1/k_1}; \varphi(x,b))  - \Av(\bar{a}_{\varphi, 1/k_2}; \varphi(x,b))  \right \rvert \leq 2/k \right).
\end{gather*}
\end{definition}
Then $X'$ is $\emptyset$-type-definable, and $\bar{a}^{\mu} \in X'$ for any generically stable $\mu  \in \mathfrak{M}_x(\cU)$. By definition, for every $\bar{a} \in X'$, $\varphi(x,y) \in L$ and $b \in \cU^y$, the limit $\lim_{k \to \infty} \Av(\bar{a}_{\varphi, 1/k}; \varphi(x,b))$ exists.

\begin{definition}\label{def: X_x}
	Let $X = X_x$ be the set of tuples $\bar{a} \in X'_x$ satisfying 
\begin{gather*}
	\bigwedge_{\varphi_1(x,y_1), \varphi_2(x,y_2) \in L} \bigwedge_{k \in \mathbb{N}} \forall b_1 \forall b_2 \Big( \neg \exists x( \varphi_1(x,b_1) \land \varphi_2(x,b_2)) \rightarrow \\
	\big  ( \lvert \Av \left( \bar{a}_{\varphi_1 \lor \varphi_2, 1/k}; \varphi_1(x,b_1) \lor \varphi_2(x,b_2)  \right) -\\
\Av(\bar{a}_{\varphi_1,  1/k}; \varphi_1(x,b_1)) + \Av(\bar{a}_{\varphi_2,  1/k}; \varphi_2(x,b_2))  ) \rvert \leq 3/k \big) \Big).
\end{gather*}
Then  $X$ is $\emptyset$-type-definable, and for every $\bar{a} \in X$, defining $\mu_{\bar{a}}$ via 
$$\mu_{\bar{a}}(\varphi(x,b)) := \lim_{k \to \infty} \Av(\bar{a}_{\varphi, 1/k}; \varphi(x,b))$$
 for all $\varphi(x,b) \in L(\cU)$, it satisfies $\mu_{\bar{a}}(\varphi_1(x,b_1) \lor \varphi_2(x,b_2)) = \mu_{\bar{a}}(\varphi_1(x,b_1)) + \mu_{\bar{a}}(\varphi_2(x,b_2))$ for all disjoint $\varphi_i(x,b_i) \in L(\cU)$. Hence $\mu_{\bar{a}}$ is a Keisler measure. 
\end{definition}

\begin{remark}\label{rem: 2/k approx}
	For an arbitrary $\bar{a} \in X$, definition of $X'$ guarantees that $\bar{a}_{\varphi, 1/k}$ is a $2/k$-approximation for $\mu_{\bar{a}}$ on $\varphi(x,y)$ (but not necessarily a $1/k$-approximation).
\end{remark}
Hence $\mu_{\bar{a}}$ is generically stable (by Fact \ref{fac: NIP gen stab meas equivs}(1)). We also have $\bar{a}^{\mu} \in X_x$ for every generically stable measure $\mu_x$, using that $\bar{a}^{\mu}_{\varphi, 1/k}$ is a $1/k$-approximation for $\mu$. 

\begin{definition}
For two tuples $\bar{a}, \bar{a}'$, we define $E = E_x$ to be the set of pairs $(\bar{a},\bar{a}')$ satisfying  
\begin{gather*}
	\bigwedge_{\varphi(x,y) \in L} \bigwedge_{k \in \mathbb{N}} \forall b \left( \left \lvert \Av \left(\bar{a}_{\varphi, 1/k}; \varphi(x,b) \right) - \Av \left(\bar{a}'_{\varphi, 1/k}; \varphi(x,b) \right) \right \rvert \leq 4/k \right).
\end{gather*}
\end{definition}
Then $E$ is an $\emptyset$-type-definable equivalence relation on $X$ (but not an intersection of definable equivalence relations), and  for any $\bar{a},\bar{a}' \in X$, $E(\bar{a}, \bar{a}')$ holds if and only if $\mu_{\bar{a}} = \mu_{\bar{a}'}$. Indeed, if $E(\bar{a}, \bar{a}')$ holds, then for any $\varphi(x,b)$ we have 
\begin{gather*}
\mu_{\bar{a}}(\varphi(x,b)) = \lim_{k \to \infty} \Av(\bar{a}_{\varphi, 1/k}; \varphi(x,b)) \\
= \lim_{k \to \infty} \Av(\bar{a}'_{\varphi, 1/k}; \varphi(x,b)) = \mu_{\bar{a}'}(\varphi(x,b)).	
\end{gather*}
Conversely, if $\mu_{\bar{a}} = \mu_{\bar{a}'}$, then for any $\varphi$ and $k$ we have that $\bar{a}_{\varphi, 1/k}$ is a $2/k$-approximation for $\mu_{\bar{a}}$  and $\bar{a}'_{\varphi, 1/k}$ is a $2/k$-approximation for $\mu_{\bar{a}'}$  on $\varphi(x,y)$ (by Remark \ref{rem: 2/k approx}), hence $E(\bar{a}, \bar{a}')$ holds. 

We have thus established the following:
\begin{proposition}
	Consider the hyperdefinable set $\widetilde{\mathcal{M}}_x := X_x/E_x$. For a generically stable measure $\mu \in \mathfrak{M}_{x}(\cU)$, we consider the hyperimaginary $[\mu] := \bar{a}^{\mu}/E \in \widetilde{\mathcal{M}}_x$. Then the map $\mu \mapsto [\mu]$ is a bijection from the space of global generically stable measures to $\widetilde{\mathcal{M}}_x$ (with the inverse $\bar{a}/E \mapsto \mu_{\bar{a}}$).
\end{proposition}

\begin{remark}
	We can think of $\Cb(\mu) := \dcl^{\heq}([\mu])$ as a canonical base for $\mu$. In particular we have $\sigma(\mu) = \mu$ if and only if $\sigma(\Cb(\mu)) = \Cb(\mu)$ for any automorphism $\sigma$ of $\cU^{\heq}$; and $\Cb(\mu)$ is the smallest $\dcl^{\heq}$-closed set over which $\mu$ is definable.
\end{remark}

 Next we observe that some of the important operations on generically stable measures correspond to type-definable maps on $\widetilde{\mathcal{M}}$.

\begin{fact}\label{fac: approx for product} (see \cite[Proposition 2.13]{zbMATH07456275})
	Let $\mu_x$ and $\nu_y$ be global generically stable measures and $\varphi(x,y;z) \in L$. Assume that $\bar{a} = (a_1, \ldots, a_m)$ is an $\varepsilon$-approximation for $\mu_x$ on $\varphi_1(x;y,z) :=  \varphi(x,y,z)$, and $\bar{b} = (b_1, \ldots, b_n)$ is an $\varepsilon$-approximation for $\nu_y$ on $\varphi_2(y;x,z) := \varphi(x,y,z)$, then $\bar{a} \times \bar{b} := \left( (a_i, b_j) : (i,j) \in [m] \times [n] \right)$ is a $2 \varepsilon$-approximation for $\mu_x \otimes \nu_y$ on $\varphi(x,y;z)$.
\end{fact}

\begin{proposition}\label{prop: tensor is type-def}
	The map $([\mu], [\nu]) \in \widetilde{\mathcal{M}}_x \times \widetilde{\mathcal{M}}_y \mapsto [\mu \otimes \nu] \in  \widetilde{\mathcal{M}}_{xy}$ is $\emptyset$-type-definable.
\end{proposition}
\begin{proof}

Indeed, let $\Gamma$ be the $\emptyset$-type-definable set of triples $(\bar{a}', \bar{a}'', \bar{a}''') \in X_x \times X_{y} \times X_{x,y}$ satisfying
\begin{gather*}
	\bigwedge_{\varphi(x,y;z) \in L} \bigwedge_{k \in \mathbb{N}} \forall b \Big( \Big \lvert \Av \left( \bar{a}'''_{\varphi(x,y;z), 1/k}; \varphi(x,y;b) \right) - \\
	  \Av \left(  \bar{a}'_{\varphi_1(x;y,z), 1/k} \times \bar{a}''_{\varphi_2(y;x,z), 1/k} ; \varphi(x,y;b) \right) \Big \rvert \leq  6/k \Big)
\end{gather*}
(using the notation in Fact \ref{fac: approx for product}).
Then $\models \Gamma(\bar{a}', \bar{a}'', \bar{a}''')$ if and only if $\mu_{\bar{a}'} \otimes \mu_{\bar{a}''} = \mu_{\bar{a}'''}$, using Remark \ref{rem: 2/k approx} and  Fact \ref{fac: approx for product} with $\varepsilon := 2/k$, and $\Gamma$ is $E$-invariant on each of its coordinates.
\end{proof}

Similarly we have:
\begin{proposition}\label{prop: push-forward is type-def}
	Let $f: \cU^x \to \cU^y$ be an $A$-definable function. Then $[\mu] \in \widetilde{\mathcal{M}}_x \mapsto [f_{\ast} \mu] \in \widetilde{\mathcal{M}}_y$ is an $A$-type-definable function.
\end{proposition}
\begin{proof}

Given $\varphi(y;z) \in L$, let $\psi(x;z) := \varphi(f(x);z) \in L(A)$. Recall that $(f_{\ast} \mu)_y$ is the unique measure satisfying $f_{\ast} \mu (\varphi(y;b)) = \mu_x( \psi(x;b) )$ for all $\varphi$ and $b \in \cU$. Then the graph is $A$-type-definable via 
\begin{gather*}
	\bigwedge_{\varphi(y,z) \in L} \bigwedge_{k \in \mathbb{N}} \forall b \Big( \left \lvert \Av \left(\bar{a}'_{\psi(x;z), 1/k} ; \psi(x,b) \right) - \Av \left(\bar{a}''_{\varphi(y;z), 1/k} ; \varphi(y,b) \right) \right \rvert \leq 4/k\Big).
\end{gather*}
\end{proof}

\begin{definition}\label{def: X_G}
	For a partial type $\pi(x)$ over a small set of parameters $A$, we let $\widetilde{\mathcal{M}}_{\pi}$ be the set of all $ [\mu] \in \widetilde{\mathcal{M}}_x$ for $\mu$  a generically stable measure in $\mathfrak{M}_{\pi}(\cU)$ (and similarly $X_{\pi}$ the set of all $\bar{a} \in X_x$ so that $\mu_{\bar{a}} \in \mathfrak{M}_{\pi}(\cU)$), i.e.~$\pi \subseteq p$ for every $p \in S(\mu)$ (equivalently, $\mu(\varphi(x))=1$ for all $\varphi(x) \in \pi$). Then $\widetilde{\mathcal{M}}_{\pi}$ is an $A$-type-definable subset of $\widetilde{\mathcal{M}}_{x}$ (and $X_{\pi}$ is an $A$-type-definable subset of $X_x$), via the ($E$-invariant) set of all $\bar{a} \in  X$ satisfying
	\begin{gather*}
		\bigwedge_{\varphi(x,b) \in \pi} \bigwedge_{k \in \mathbb{N}} \Av\left( \bar{a}_{\varphi, 1/k}; \varphi(x,b) \right) \geq 1 - 2/k.
	\end{gather*}
	In particular, if $G$ is a type-definable group, $\widetilde{\mathcal{M}}_{G}$ represents the set of all generically stable measures supported on $G$.
\end{definition}

\begin{remark}\label{rem: meas code rep inside the partial type}
	For every $[\mu] \in \mathfrak{M}_{\pi}(\cU)$, we have $\mu = \mu_{\bar{a}}$ for some representative $\bar{a} \in X_{\pi} \cap \pi(\cU)^{\bar{y}}$ (by Lemma \ref{lem: generically stable localizing}).
\end{remark}

\begin{proposition}
	Let $G$ be an $A$-type-definable group. Then the set  of all $[\mu] \in \widetilde{\mathcal{M}}_{G}$ with $\mu \in \mathfrak{M}_G(\cU)$ idempotent (generically transitive) is $A$-type-definable.
\end{proposition}
\begin{proof}
	By Propositions \ref{prop: tensor is type-def} and \ref{prop: push-forward is type-def}, as $\mu$ is idempotent if and only if $\mu = f_{\ast}(\mu \otimes \mu)$ for $f(x,y) = x \cdot y$, and $\mu$ is generically transitive if and only if $\mu \otimes \mu = g_{\ast}(\mu \otimes \mu)$ for $g(x,y) = (x, x \cdot y)$.
\end{proof}


\begin{lemma}\label{lem: unif defining stab of mu}
	Let $G = G(x)$ be an $A$-type-definable group. Then there is an $A$-type-definable set $\St_{G} \subseteq G \times \widetilde{M}_G$ so that for any $[\mu] \in \widetilde{M}_G$ we have $\St_{G}(\cU;[\mu]) = \Stab_{G}(\mu)$ (the left stabilizer of $\mu$, Definition \ref{def: stab of a measure}). And similarly we have an $A$-type-definable set  $\St_{G}^{\leftrightarrow}$  for the two-sided stabilizers.
\end{lemma}
\begin{proof}
For $\varphi(x,y) \in L$, let $\varphi'(x;y,x') := \varphi(x' \cdot x; y)$. We consider the definable sets 
\begin{gather*}
\St_{G, \varphi(x,y) , 1/k} := 
	\Big\{(g, \bar{a}_{\varphi', 1/k}) \in \cU^x \times  M^{\bar{y}_{\varphi', 1/k}}  : \\
	\forall b \  \left \lvert \Av\left( \bar{a}_{\varphi', 1/k}; \varphi'(x;b,1_{G})  \right)  -  \Av\left( \bar{a}_{\varphi', 1/k}; \varphi'(x;b,g) \right) \right \rvert \leq 5/k \Big\}
\end{gather*}
and the type-definable set 
\begin{gather*}
	\St_{G} := \left\{ (g, \bar{a}) \in G \times X_G :  \bigwedge_{\varphi \in L, k \in \mathbb{N}} (g, \bar{a}_{\varphi', 1/k}) \in \St_{G, \varphi(x,y) , 1/k} \right\}.
\end{gather*}
Given $\bar{a} \in X_{G}$, if $g  \in  \Stab_{G,\varphi(x;y), 1/k}(\mu_{\bar{a}})$, then (by Fact \ref{fac: stab of def meas type def}(1)) for all $b \in \cU^y$ we have 
	$$\left \lvert  \mu_{\bar{a}}(\varphi(x,b)) - \mu_{\bar{a}} (\varphi(g \cdot x,b) )\right \rvert \leq 1/k,$$
	 hence $(g,\bar{a}) \in \St_{G, \varphi(x,y) , 1/k}$ (using Remark \ref{rem: 2/k approx}).  Conversely, if $(g,\bar{a}) \in \St_{G, \varphi(x,y) , 1/k}$ then 
	 $$\left \lvert  \mu_{\bar{a}}(\varphi(x,b) ) - \mu_{\bar{a}} (\varphi(g \cdot x,b) )\right \rvert \leq 9/k$$
	  for all $b$, hence $g \in \Stab_{G,\varphi(x;y), 18/k}(\mu_{\bar{a}})$ (by Fact \ref{fac: stab of def meas type def}(2)). 
	  Hence 
	  \begin{gather}
	  	\forall \bar{a} \in X_{G}, \  \Stab_{G, \varphi, 1/k}(\mu_{\bar{a}}) \subseteq \St_{G, \varphi, 1/k}(\cU, \bar{a}) \subseteq \Stab_{G,\varphi, 18/k}(\mu_{\bar{a}});
	  \end{gather}
	  and so 
	\begin{gather*}
		\Stab_{G}(\mu_{\bar{a}}) = G \cap \bigcap_{\varphi,k}  \Stab_{G,\varphi(x;y), 1/k}(\mu_{\bar{a}}) \\
		= G \cap \bigcap_{\varphi,k} \St_{G, \varphi(x,y) , 1/k}(\cU, \bar{a}) = \St(\cU, \bar{a}).
	\end{gather*}

	We define $\St_{G}^{\leftrightarrow}$ and $\St^{\leftrightarrow}_{G, \varphi(x,y) , 1/k}$ for the two-sided stabilizers similarly.
\end{proof}

\begin{remark}\label{rem: one stabilizer implies two stabilizers}
	As $|M| \geq 2$  without loss of generality, given any formulas $\varphi_1(x,y_1), \varphi_2(x,y_2) \in L$ we can choose $\varphi(x, y) \in L$, with $y = (y_1, y_2, y', y'')$ and $\varphi(x,y) := (y' = y'' \land \varphi_1(x,y_1)) \lor (y' \neq y'' \land \varphi_2(x,y_2)) $ so that for any $\bar{a} \in X_{G}$ we have $\St_{G,\varphi,k}(x, \bar{a}) \vdash \St_{G,\varphi_i, k}(x,\bar{a})$ for both $i \in \{1,2\}$.
\end{remark}




\subsection{Externally definable, definably amenable subgroups}\label{sec: abelian ext def subgroups}

In this section we consider externally (type-)definable, definably amenable subgroups of definable groups. 


First we note that Lemma \ref{lem: unique extension of def meas to Sh} also provides an alternative proof of Fact \ref{fac: group props preserved in Sh exp}(3) for definable amenability,  generalizing to type-definable groups and arbitrary models of $T'$:
\begin{corollary}\label{cor: def am is preserved in Msh new proof}
	($T$ NIP) Assume $M \models T$, $\widetilde{M}' \succ M^{\Sh}$ is a monster model, and $G$ is a type-definable and definably amenable group (working in a monster model $M' \models T$). Then $G$ remains definably amenable in $T' = \Th(M^{\Sh})$.
\end{corollary}
\begin{proof}
	By Fact \ref{fac: def am def measure} applied in $M' \models T$ (which is a monster model for $T$), there exists a left-$G(M')$-invariant measure $\bar{\mu} \in \mathfrak{M}_{G}^L(M')$ and small $M_1 \prec^{L} M'$ so that both $G$ is type-definable over $M_1$ and $\bar{\mu}$ is 	definable over  $M_1$. Let $M_2 \prec^{L'} \widetilde{M}'$ be a small coherent model containing $M_1$. By Lemma \ref{lem: unique extension of def meas to Sh}, let $\bar{\mu}'$ be the unique extension of $\bar{\mu}$ to a measure in $\mathfrak{M}_x^{L'}(M')$, in particular $\bar{\mu}' \in \mathfrak{M}_G^{L'}(M')$. As in the proof of Theorem \ref{thm: type-def and ext def fsg implies def},  $\bar{\mu}'$ is also $G(M')$-invariant: given $g \in G(M')$, $g \cdot \bar{\mu} = \bar{\mu} $ and $(g \cdot \bar{\mu}') \restriction_{L} = g \cdot (\bar{\mu}'\restriction_{L}) = g \cdot \bar{\mu} = \bar{\mu}$, so $g \cdot \bar{\mu}' = \bar{\mu}'$ by uniqueness. This shows that $G$ is definably amenable in $T'$.
\end{proof}
\begin{remark}
	However this proof does not seem to apply to definable extreme amenability however, since it is not known that if $G$ is definably  extremely amenable (NIP) then there exists a definable $G$-invariant \emph{type}.
\end{remark}


\begin{remark}
	Note that Theorems \ref{thm: main for fsg subgroups} and \ref{thm: type-def and ext def fsg implies def} need not hold if we only assume definable amenability instead of fsg. Indeed, we have the following facts:

	\begin{fact} \cite[Proposition 3.20]{chernikov2022definable}
	If $T$ is NIP and $G$ is a type-definable group that is definably amenable, then $G^{00}$ is also definably amenable (hence definably amenable in $\Th(M^{\Sh})$ by Fact \ref{fac: group props preserved in Sh exp}).
\end{fact}

\begin{fact} \cite[Remark 8.3(i)]{NIP2}\label{fac: G^00 ext def sometimes} Let $T$ be NIP and $M \models T$ saturated. Assume that $G$ is definable in $M$, definably amenable, and $G/G^{00}$ is a compact Lie group (any definably amenable group in an $o$-minimal theory satisfies these requirements). Then $G^{00}$ is definable in $M^{\Sh}$.
	\end{fact}





	As $G^{00}$ is rarely definable in $M$, even for definably compact groups in $o$-minimal theories (Example \ref{ex: infinitesim not fsg}), Theorem \ref{thm: type-def and ext def fsg implies def} implies in particular that  $G^{00}$ is externally definable, type-definable and  definably amenable, but not fsg in such situations.
\end{remark}




\begin{question}
\begin{enumerate}
	\item Is $G^{00}$ externally definable for all groups definable in $o$-minimal theories?
	\item 	We reiterate Problem 4.21 from \cite{chernikov2014external}: if $G$ is definable in an NIP theory $T$ and $\cU \models T$ is saturated, does naming $G^{00}(\cU)$ by a new predicate
preserve NIP? (Note that $G^{00}$ is not always externally definable, even in stable theories --- in $(\mathbb{Z}, +)$, it is an intersection of infinitely many formulas, not definable, so not externally definable. What about external  definability of the local analog $G^{00}_{\varphi}$ (see \cite[Section 7.14]{hrushovski2024approximate})?
\end{enumerate}
\end{question}



What description can one expect for externally definable (amenable) subgroups of definable groups?
\begin{example}\label{ex: ext def ab wo type-def subgrps}

	Let $M_0 = G(M_0) := (\mathbb{Z}, +, <)$ and $M \succ M_0$ a saturated extension.
	Then $H(M) := \mathbb{Z} \leq G(M)$ is externally definable by convexity in the order on $M$, but 
	\begin{enumerate}
		\item $H(M)$ is not type-definable in $M$ and does not contain any type-definable in $M$ subgroups except $\{0\}$;
		\item $H(M)$ is not of the form $K(\cU) \cap M$ for an $\cU$-definable subgroup $K(\cU) \leq G(\cU)$.
	\end{enumerate}
	Considering instead a convex subgroup given by a cut with large cofinality on both sides in a saturated model $M$ of $(\mathbb{R},+,<)$ shows that also 
	\begin{enumerate}
		\item[(3)]	externally definable (abelian) subgroups need not be $\Aut(M/A)$-invariant for any small $A \subset M$ either.
	\end{enumerate}
\end{example}


\noindent At least in this case we have the following approximations for $H$ is $T$:
\begin{definition}
	\begin{enumerate}
	\item  a formula $\varphi(x,y) \in L$ (e.g.~$y_1 < x < y_2$) so that the  family $\mathcal{F} := \{\varphi(M,b) : b \in M^y, \varphi(M,b) \subseteq H(M)\}$  of uniformly $M$-definable subsets of $H(M)$ is \emph{product-directed} (i.e.~for any $n \in \mathbb{N}$ and $X_1, \ldots, X_n \in \mathcal{F}$ there is $X \in \mathcal{F}$ with $(\bigcup_{i \in [n]} X_i)^2 \subseteq X$) and $H(M) = \bigcup \mathcal{F}$. 
	\item a type-definable (over a small set of parameters in $\cU$) subgroup $K(\cU) \leq G(\cU)$ so that $H(M) = K(M)$; moreover, $K$ is uniformly type-definable: there is a formula $\varphi(x,y) \in L$ (again $y_1 < x < y_2$) and a small family $\mathcal{F} = \{\varphi(\cU,b) : b \in \Omega \}$  with $\Omega \subset \cU^y$ of uniformly $\cU$-definable sets so that $\mathcal{F}$ is \emph{downwards directed} (i.e.~for any $n \in \mathbb{N}$ and $X_1, \ldots, X_n \in \mathcal{F}$ there is $X \in \mathcal{F}$ with $X \subseteq \bigcap_{i \in [n]} X_i$) and $\bigcap_{b \in \Omega} \varphi(M,b) = H(M)$.
\end{enumerate}
\end{definition}


Note that conversely by compactness, the union (respectively, the intersection) of $\varphi(M,b)$ for any such family gives an externally definable subgroup of $G(M)$.


\begin{question}
	Is every externally definable (definably amenable/abelian) subgroup of a definable group the union of a definable product-directed family of its subsets? Respectively, the intersection of a downwards product-directed family of uniformly externally definable sets? (See an analogous Question \ref{q: honest defs directed} for externally definable sets.)
 \end{question}


In this section we get a weaker presentation, as  the union of a (uniformly) product-directed \emph{type-definable} family of subsets indexed by a strict externally pro-definable set (Theorem \ref{thm: ext def abelian final approx in M}); as well as the trace on $M$ of a (not necessarily uniformly) $\cU$-type-definable subgroup of $G(\cU)$ (Remark \ref{rem: am subg is trace of type-def}).

We begin with a couple of auxiliary observations. 
\begin{remark}\label{rem: stab contained in a subgroup}
	If $G$ is a type-definable group, $H \leq G$ a type-definable subgroup and $\mu \in \mathfrak{M}_{H}(\cU)$, then $\Stab_{G}(\mu) = \Stab_{H}(\mu) \leq H$ (and similarly for the two-sided stabilizers).

	Indeed, suppose $g \in \Stab_{G}(\mu) \setminus \Stab_{H}(\mu)$, then $g \in \Stab_{G}(\mu) \setminus H$, hence $g \cdot H(\cU) \cap H(\cU) = \emptyset$, so by compactness $g \cdot \varphi(\cU) \cap \varphi(\cU) = \emptyset$ for some formula $\varphi(x)$ in the partial type defining $H$ (without loss of generality closed under conjunctions).  As $\mu \in \mathfrak{M}_{H}(\cU)$ we have $\mu(\varphi(x)) = 1$, and as $g \in \Stab_{G}(\mu)$ also $\mu(g \cdot \varphi(x)) = \mu(\varphi(x)) = 1$, a contradiction.
\end{remark}

\begin{lemma}\label{lem: generically stable localizing}($T$ NIP) 
	Assume $M_0 \preceq M$, $M$ is $|M_0|^{+}$-saturated,  $U$ is a type-definable set over $M_0$, $V$ a type-definable set over an arbitrary small model $M_1 \prec \cU$. If $\mu \in \mathfrak{M}_{U}(\cU)$ is generically stable over $M$ and $U(M) \subseteq V(\cU)$, then $\mu \in \mathfrak{M}_{V}(\cU)$.
\end{lemma}
\begin{proof}

Assume $U$ is defined by a partial type $\{\varphi_i(x) : i \in I\}$ with $\varphi_i(x) \in L(M_0)$ and $V$ is defined by a partial type $\{\psi_j(x, b_j) : j \in J\}$ with $\psi_j(x,y_j) \in L, b_j \in M_1^{y_j}$. We need to show that $\mu(\psi_j(x, b_j)) = 1$ for all $j \in J$. Assume this fails, say $\mu(\neg \psi_j(x, b_j)) = \varepsilon > 0$ for some $j \in J$.


	By Fact \ref{fac: NIP gen stab meas equivs}, $\mu$ is fim over $M$, in particular there exist $n \in \mathbb{N}$ and a formula $\theta(x_1,\ldots,x_n) \in L(M)$ such that: for any $\bar{a}$ in $\cU$ with $\models \theta(\abar)$ we have 
		\begin{equation*} 
		\sup_{b \in \cU^{y_j}} |\Av(\abar; \varphi_j(x,b)) - \mu(\varphi_j(x,b))| < \varepsilon/2,
		\end{equation*} 
and $\mu^{\otimes n} \left( \theta \left(\bar{x} \right) \right) >0$. For every finite $I_0 \subseteq I$ we have $\mu \left(\bigwedge_{i \in I_0} \varphi_i(x) \right) =1$ (as $\mu \in \mathfrak{M}_{U}(\cU)$), hence $\mu^{\otimes n} \left(\bigwedge_{i \in I_0, t \in [n]} \varphi_i(x_t) \right) = 1$, and so 
$$\mu^{\otimes n} \left(\bigwedge_{i \in I_0, t \in [n]} \varphi_i(x_t) \land \theta(x_1, \ldots, x_n) \right) > 0,$$
in particular this formula is consistent. Then, by $|M_0|^{+}$-saturation of $M$, we can find $\bar{a} = (a_1, \ldots, a_n)$ with each $a_i \in U(M)$ and $\models \theta(\bar{a})$. Then, by construction, for some $i \in [n]$ we have $a_i \in U(M) \setminus \psi_j(M,b_j)$, hence $a_i \in U(M) \setminus V(\cU)$, contradicting the assumption.
\end{proof}

We generalize \cite[Proposition 6.3]{hils2021definable} from definable abelian groups to type-definable, definably amenable groups:
\begin{theorem}\label{thm: approx def am by stab gs}
	Let $T$ be NIP, and $G$ type-definable over $M_0 \models T$ and  definably amenable. Then there are $M_0$-type-definable sets $\St_G \subseteq G(\cU) \times \cU^{\bar{y}}, X_{G} \subseteq \cU^{\bar{y}}$ with $|\bar{y}| = |T|$ so that:
	\begin{enumerate}
		\item for every $\bar{a} \in X_{G}$, $\St_G(\cU; \bar{a}) = \Stab_{G}(\mu_{\bar{a}}) \leq G(\cU)$ for a measure $\mu_{\bar{a}} \in \mathfrak{M}_{G}(\cU)$ generically stable over $\bar{a}$;
		\item $G(\cU) = \bigcup_{\bar{a} \in X_{G}} \St_{G}(\cU, \bar{a})$;
		\item the family $\{\St_{G}(\cU, \bar{a}) : \bar{a} \in X_{G}\}$ is directed, i.e.~for any small $I \subseteq X_{G}$ there is some $\bar{a}_{I} \in X_{G}$ so that $\St_{G}(\cU, \bar{a}) \subseteq \St_{G}(\cU, \bar{a}_{I}) $ for all $\bar{a} \in I$.
	\end{enumerate}
\end{theorem}

\begin{proof}

We will use some material from Section \ref{sec: hyperdef sets from measures}. Namely, we consider the $M_0$-type-definable set $X_{G}$ (Definition \ref{def: X_G}): generically stable measures in $\mathfrak{M}_G(\cU)$ are precisely the measures of the form $\mu_{\bar{a}}$ (Definition \ref{def: X_x}) for $\bar{a} \in X_G$ (but possibly $\mu_{\bar{a}} = \mu_{\bar{a}'}$ for $\bar{a} \neq \bar{a}' \in X_{G}$), and $\mu_{\bar{a}}$ is generically stable over $\bar{a}$. By Remark \ref{rem: meas code rep inside the partial type} we may assume that every element of every tuple in $X_G$ is in $G(\cU)$.   By Lemma \ref{lem: unif defining stab of mu} we have an $M_0$-type-definable set $\St_{G}(x,\bar{y})$ so that $\left( \Stab_{G}(\mu_{\bar{a}}) \right)(\cU) = \St(\cU, \bar{a})$ for all $\bar{a} \in X_G$. 

\begin{claim}\label{cla: ab of gs stabilizers}
	For every small model $M \succ M_0$ there is a measure $\mu_{M} \in \mathfrak{M}_{G}(\cU)$ and a small model $M' \succ M$ so that $\mu_{M}$ is generically stable over $M'$ and $G(M) \subseteq \Stab_{G}(\mu_{M})$.
\end{claim}
\begin{proof}
	 As $G$ is definably amenable and NIP, by Fact \ref{fac: def am def measure} there is a measure $\mu \in \mathfrak{M}_{G}(\cU)$  which is left-$G(\cU)$-invariant, and definable over some small model $M_1 \prec \cU$, without loss of generality $M \prec M_1$.
  Then, using Fact \ref{fac: symmetrization measure}, $\mu|_{M_1}$ can be extended to a measure $\mu_{M} \in \mathfrak{M}_{G}(\cU)$ which is generically stable over some small $M_1 \prec M' \prec \cU$ and left $G(M)$-invariant (see also \cite[Section 7]{NIP2}).
\end{proof}


In particular, for every small model $M$, $G(M) \subseteq \Stab_{G}(\mu)$ and $\mu = \mu_{\bar{a}}$ for some $\bar{a} \in X_{G}$, hence $G(M) \subseteq \Stab_{G}(\mu_{\bar{a}}) = \St_G(\cU; \bar{a})$. This shows that $G(\cU) =  \bigcup_{\bar{a} \in X_{G}} \St_{G}(\cU, \bar{a})$.

Now let $(\bar{a}_i : i \in I)$ be a small tuple of elements of $X_{G}$. Let $M$ be a small $(|M_0|+|T|)^{+}$-saturated model containing $M_0$ and all of $\bar{a}_i$, then $\mu_{\bar{a}_i} \in \mathfrak{M}_{G}(\cU)$ is generically stable over $M$ for all $i \in I$. Let $\mu_{M} \in \mathfrak{M}_{G}(\cU)$ be given  by Claim \ref{cla: ab of gs stabilizers}, then $\mu_{M}$ is generically stable over some small $M' \succ M$ and $\Stab_{G}(\mu_{M})$ is type-definable over $M'$. As  $G(M) \subseteq \Stab_{G}(\mu_{M})$, we have $\mu_{\bar{a}_i} \in \mathfrak{M}_{\Stab_{G}(\mu_{M})}(\cU)$ by Lemma \ref{lem: generically stable localizing}. Hence  $\Stab_{G}(\mu_{\bar{a}_i}) \leq \Stab_{G}(\mu_{M})$ for all $i \in I$, by Remark \ref{rem: stab contained in a subgroup}. As $\mu_{M} = \mu_{\bar{a}}$ for some $\bar{a} \in X_{G}$, we have $\St_{G}(\cU; \bar{a}_i) \subseteq \St_{G}(\cU; \bar{a})$ for all $i \in I$.
\end{proof}

This immediately implies a generalization of \cite[Corollary 6.4]{hils2021definable} from abelian to definably amenable groups:
\begin{corollary}
	($T$ NIP) If $G$ is definably amenable with no indiscernible linearly ordered (by inclusion) family of type-definable subgroups, then $G$ is fsg.
\end{corollary}
\begin{proof}
	Since the family $\{\St_{G}(\cU; \bar{a} : \bar{a} \in X_{G} \}$ is directed and its union is $G(\cU)$, it follows from the assumption that $G(\cU) = \St_{G}(\cU; \bar{a})$ for some $\bar{a} \in X_{G}$, hence $G(\cU) = \Stab_{G}(\mu_{\bar{a}})$ for a generically stable measure $\mu_{\bar{a}} \in \mathfrak{M}_{G}(\cU)$, witnessing that $G$ is fsg.
\end{proof}

\begin{remark}
Theorem \ref{thm: approx def am by stab gs} also holds with two-sided stabilizers of generically stable measures instead of just left stabilizers.
\end{remark}
\begin{proof}
	As $G$ is definably amenable and NIP, by \cite[Lemma 6.2]{chernikov2018definably} there is a measure $\mu \in \mathfrak{M}_{G}(\cU)$  which is both left and right $G(\cU)$-invariant, and definable over some small model. Then Claim \ref{cla: ab of gs stabilizers} holds with  $G(M) \subseteq \Stab^{\leftrightarrow}_{G}(\mu_{M})$ (the two-sided stabilizer of $\mu_{M}$, Definition \ref{def: stab of a measure}), applying Fact \ref{fac: def am def measure} to each of left and right multiplications by elements of $G(M)$. The proof of Theorem \ref{thm: approx def am by stab gs} then goes through working with the type-definable set $\St_G^{\leftrightarrow}$ (Lemma \ref{lem: unif defining stab of mu}) defining two-sided stabilizers instead of $\St_{G}$.
\end{proof}

The following example, checked in discussion with Kyle Gannon, demonstrates that we cannot assume the groups $\St_{G}(\cU;\bar{a}) \leq G$ in Theorem \ref{thm: approx def am by stab gs} to be fsg (equivalently, we cannot assume that the measures $\mu_{\bar{a}}$ are supported on their stabilizers $\Stab_{G}(\mu_{\bar{a}})$):
\begin{example}\label{ex: no fsg subroups in R+}
	Let $M_0 = (R,+, <, \ldots)$ be an $o$-minimal (expansion of an) ordered (abelian) group, $G(M_0) = (R,+)$, $\cU \succ M_0$ a monster model.  There are no non-trivial type-definable fsg subgroups of $G(\cU)$.

	Indeed, first note that there are no non-trivial definable subgroups of $G(\cU)$ (by $o$-minimality any such group would be a finite union of intervals with end-points in $\cU$, but taking $a$ close enough to the right end-point of the right-most interval $I$, $a+a \notin I$). Next, we have:
	\begin{claim}
		If $\mu \in \mathfrak{M}_{G}(\cU)$ is any measure, then the subgroup $\Stab_{G}(\mu) \leq G(\cU)$ is convex.
	\end{claim}
	\begin{proof}
		Assume $0 < c < b $ in $\cU$ and $b \in \Stab_{G}(\mu)$. Suppose $c \notin \Stab_{G}(\mu)$, i.e.~$\mu(X) \neq \mu(c+ X)$ for some $\cU$-definable set $X$. Then, by $o$-minimality, we have $\mu(I) \neq \mu(c+ I)$ for some non-empty $\cU$-definable interval $I$.
		\begin{enumerate}
			\item $I = (-\infty, d)$ for some $d \in \cU$.
			 Then  $I \subseteq c+I \subseteq b+ I$ and necessarily $\mu(c+ I) > \mu(I)$, contradicting $\mu(I) = \mu(b+ I)$.

			\item $I = (d, + \infty)$ for some $d \in \cU$.
			 Then $b+ I \subseteq c+ I \subseteq I$ and necessarily $\mu(c+ I) < \mu(I)$, contradicting $\mu(I) = \mu(b+ I)$.
			 \item $I = (a,d)$ for some $a<b \in \cU$. 

			 \noindent Suppose $\mu(c+I) > \mu(I)$. Then $
			 \mu((-\infty, d)) = \mu( (-\infty, a]) + \mu( I) < \mu( (-\infty, a]) + \mu( c+ I) = \mu( (-\infty, a] \sqcup (c+I)) \leq \mu(b + (-\infty, d))$, thus $b \notin \Stab_{G}(\mu)$. 

			\noindent  If $\mu(c+I) < \mu(I)$, we have $0 < \mu(I \setminus c+ I) \leq \mu((a,a+c))$, so $\mu((a, + \infty)) > \mu(b+ (a, + \infty))$, thus $b \notin \Stab_{G}(\mu)$.
			\item And similarly for closed intervals. \qedhere
		\end{enumerate}
	\end{proof}
 Every type-definable fsg group $H(\cU) \leq G(\cU)$ is of the form $\Stab_{G}(\mu)$ for a generically stable measure $\mu$ supported on it, hence definable in $\cU^{\Sh}$ by the claim,  so it has to be definable in $\cU$ by Theorem \ref{thm: type-def and ext def fsg implies def}.
\end{example}

\begin{remark}
	By \cite[Theorem 1.5]{chernikov2024definable}, Example \ref{ex: no fsg subroups in R+} also shows that there are no  idempotent generically stable measures in  $(R,+, <, \ldots)$ (except for $\tp(1/\cU)$), which is a $dp$-minimal ordered abelian group. Contrast this with the case of abelian groups in ACVF \cite[Lemma 5.1]{hrushovski2019valued}.
\end{remark} 


Next we strengthen ``directed'' in Theorem \ref{thm: approx def am by stab gs} to ``uniformly directed'' (similar to Definition \ref{def: unif dir}):
\begin{proposition}\label{prop: getting unif directed}
 In Theorem \ref{thm: approx def am by stab gs}(3), the family $\{\St_{G}(\cU, \bar{a}) : \bar{a} \in X_{G}\}$ is moreover \emph{uniformly directed}, i.e.~for any  $\varphi(x,y) \in L, k \in \mathbb{N}$ there are $\varphi'(x,y') \in L, k' \in \mathbb{N}$ so that: for any small $I \subseteq X_{G}$ there is some $\bar{a}_{I} \in X_{G}$ so that $\St_{G,\varphi',1/k'}(x,\bar{a}) \vdash \St_{G,\varphi,1/k}(x,\bar{a}_{I})$ for all $\bar{a} \in I$ simultaneously.
\end{proposition}
\begin{proof}


First we refine Remark \ref{rem: stab contained in a subgroup} in the case when $H = \Stab_{G}(\nu)$ for some generically stable measure $\nu \in \mathfrak{M}_{G}(\cU)$ (possibly different from $\mu$):
\begin{claim}\label{cla: more precise directedness for stabilizers}
	For every $\varphi(x,y) \in L, k \in \mathbb{N}$ there exist $\xi(x,y') \in L, k' \in \mathbb{N}$ satisfying the following: if $\bar{a}_1, \bar{a}_2 \in X_{G}$ and $\mu_{\bar{a}_1} \in \mathfrak{M}_{\Stab_{G}(\mu_{\bar{a}_2})}(\cU)$, then $ \St_{G, \xi , 1/(k')}(x, \bar{a}_1) \vdash \St_{G, \varphi, 1/k}(x, \bar{a}_2)$.
\end{claim}
\begin{proof}
For every $\varphi(x,y) \in L, k \in \mathbb{N}$, $\St_{G, \varphi, 1/k}(\cU, \bar{a})$ is defined by $\psi_{\varphi, 1/k}(x;\bar{a})$ for some $\psi_{\varphi, 1/k}(x;y') \in L$ depending only on $\varphi, \varepsilon$ (but not on $\bar{a}$). Then  ``$\mu_{\bar{a}_1} \in \mathfrak{M}_{\Stab_{G}(\mu_{\bar{a}_2})}(\cU)$'' is a type-definable condition on $(\bar{a}_1, \bar{a}_2) \in X_G \times X_G$ via  a partial type $\pi(\bar{y}_1, \bar{y}_2)$ given by 
$$\bigwedge_{\varphi \in L, \  k, \ell \in \mathbb{N}}  \Av\left( (\bar{a}_1)_{\psi_{\varphi, 1/k}, 1/\ell}; \psi_{\varphi, 1/k}(x;(\bar{a}_2)_{\varphi', 1/k}) \right) \geq 1 - 2/\ell
$$
(see Lemma \ref{lem: unif defining stab of mu}).

Now suppose claim fails for $\varphi(x,y)$ and $k$. Then, using Remark \ref{rem: one stabilizer implies two stabilizers}, for any $n \in \mathbb{N}$ and $\varphi_i(x,y_i)  \in L, k_i \in \mathbb{N}$ for $i \in [n]$ there are some $b, \bar{a}_1, \bar{a}_2$ in $\cU$ with 
$$ \models X_{G}(\bar{a}_1) \land X_{G}(\bar{a}_2) \land \pi(\bar{a}_1, \bar{a}_2) \land   \bigwedge_{i \in [n]} \St_{G, \varphi_i, 1/(k_i)}(b, \bar{a}_1) \land \neg \St_{G, \varphi, 1/k}(b, \bar{a}_2).$$
By compactness we thus find some  $b, \bar{a}$ in $\cU$ so that
$$\models X_{G}(\bar{a}_1) \land X_{G}(\bar{a}_2) \land  \pi(\bar{a}_1, \bar{a}_2)  \land  \St_{G}(b, \bar{a}_1) \land \neg \St_{G, \varphi, 1/k}(b, \bar{a}_2).$$
But this contradicts Remark \ref{rem: stab contained in a subgroup}, with  $\mu := \mu_{\bar{a}_1}, \nu :=  \mu_{\bar{a}_2}, H := \Stab_G(\mu_{\bar{a}_2})$.
\end{proof}

Now in the proof of directedness in Theorem \ref{thm: approx def am by stab gs}, given any small tuple $(\bar{a}_i : i \in I)$  of elements of $X_{G}$,
we found a generically stable measure  $\mu_{M} \in \mathfrak{M}_{G}(\cU)$, say $\mu_{M} = \mu_{\bar{a}}$ for $\bar{a} \in X_{G}$, so that  $\mu_{\bar{a}_i} \in \mathfrak{M}_{\Stab_{G}(\mu_{M})}(\cU)$ for all $i \in I$. By Claim \ref{cla: more precise directedness for stabilizers} we have $\xi$ and $k'$ so that 
$$ \models \forall x \left( \St_{G, \xi , 1/k'}(x, \bar{a}_i) \rightarrow \St_{G, \varphi , 1/k}(x, \bar{a}) \right)$$
for all $i \in I$, as wanted.
\end{proof}



We give a more explicit proof of Proposition \ref{prop: getting unif directed} in the case of an abelian group $G$. For (automorphism-) invariant measures $\mu$,$\nu$ in an NIP group, we have that $\Stab_{G}(\mu) \subseteq \Stab_{G}(\mu \ast \nu)$ and $\Stab_{G}(\nu) \subseteq \Stab_{G}^{\leftarrow}(\mu \ast \nu)$ (the right stabilizer). This point was used e.g.~in \cite[Lemma 6.2]{chernikov2018definably} to show that every definably amenable NIP group admits a bi-invariant measure (see also \cite[Proposition 3.23]{chernikov2022definable}). The following is a  refinement of \cite[Section 6, (A)]{hils2021definable}: 
\begin{lemma}\label{lem: convolution stab uniformly}
	Let $G = G(x)$ be a type-definable abelian group, $n \in \omega$ and $\mu_i \in \mathfrak{M}_{G}(\cU)$ for $i \in [n]$ generically stable. Let $\mu :=  \bigast_{i \in [n]} \mu_i$. For $\varphi(x,y)$, let $\varphi'(x; y, x') := \varphi(x \cdot x', y)$. Then for any $i \in [n]$ and $\varepsilon > 0$, 
	$$ \Stab_{G, \varphi', \varepsilon} (\mu_i) \subseteq \Stab_{G, \varphi, 2 \varepsilon} (\mu)$$
	 (in the notation of Fact \ref{fac: stab of def meas type def}); in particular, $\Stab_{G}(\mu_i) \subseteq \Stab_{G}(\mu)$.
\end{lemma}
\begin{proof}
For $I \subseteq [n]$, let $\mu_{I} :=  \bigast_{i \in I} \mu_i$. As $\mu_i$ are $\otimes$-commuting by generic stability and $G$ is abelian, the order in the product does not matter, and $\mu_{I}$ is generically stable  (see \cite[Proposition 3.15]{chernikov2022definable}). In particular $\mu = \mu_i \ast \mu_{[n] \setminus \{i\}}$ for all $i \in [n]$.

Assume $g \in \Stab_{G, \varphi', \varepsilon} (\mu_i)$. Then, by Fact \ref{fac: stab of def meas type def}(1), for all $(b,g') \in \cU^{y}\times \cU^x$ we have  
\begin{gather}
	\left \lvert \mu ( \varphi'(x; b,g'))  -  \mu ( \varphi'(g \cdot x; b, g')) \right \rvert \leq \varepsilon. \label{eq: close for all params phi'}
\end{gather}


	Given an arbitrary $b \in \cU^y$, let $M \prec \cU$ be a small model so that all of $\mu_i$ are definable over $M$, $G$ is type-definable over $M$, $g \in G(M)$ and $b \in M^y$. We have
	\begin{gather*}
		\left \lvert \mu (\varphi(x;b) ) -  \mu (\varphi(g \cdot x;b)) \right \rvert \\
		= 		\left \lvert \mu_i \ast \mu_{[n] \setminus \{i\}} (\varphi(x;b) )  - \mu_i \ast \mu_{[n] \setminus \{i\}} (\varphi(g \cdot x;b) )\right \rvert \\
		= \int_{q \in S_y(M)} \left \lvert \mu ( \varphi(x \cdot g'; b))  -  \mu ( \varphi(g \cdot x \cdot g'; b)) \right \rvert d \mu'_{[n] \setminus \{i\}}(q) 
		\overset{\eqref{eq: close for all params phi'}}{\leq } \varepsilon,
	\end{gather*}
where $\mu'_{[n] \setminus \{i\}}$ is the regular Borel probability measure on $S_y(M)$ extending $\mu_{[n] \setminus \{i\}}$, and $g' \models q$ arbitrary in $\cU$. As $b$ was arbitrary, this implies $g \in \Stab_{G, \varphi, 2 \varepsilon} (\mu)$ by Fact \ref{fac: stab of def meas type def}(2).
\end{proof}


\begin{proof}[A more explicit proof of Proposition \ref{prop: getting unif directed} for  abelian $G$.]
	Let $I \subseteq X_G$ be small. For any finite $J \subseteq I$, let $\mu_{J} :=  \bigast_{\bar{a} \in J} \mu_{\bar{a}}$. As $\mu_{J} \in \mathfrak{M}_{G}(\cU)$ is generically stable, we have $\mu_{J} = \mu_{\bar{a}_{J}}$ for some $\bar{a}_{J} \in X_{G}$.  By Lemma \ref{lem: convolution stab uniformly}, for each $\bar{a} \in J$ we have $\Stab_{G, \varphi', \varepsilon} (\mu_{\bar{a}}) \subseteq \Stab_{G, \varphi, 2 \varepsilon} (\mu_{\bar{a}_{J}})$, hence, using the notation from the proof of Lemma \ref{lem: unif defining stab of mu},
$$ \models \forall x \left( \St_{G, \varphi'(x,y) , 1/(32 k)}(x, \bar{a}) \rightarrow \St_{G, \varphi(x,y) , 1/k}(x, \bar{a}_{J}) \right).$$
 As $I$ is small, by compactness there exists $\bar{a}' \in X_{G}$ so that 
 $$ \models \bigwedge_{\varphi(x,y) \in L, k \in \mathbb{N}}  \forall x \left( \St_{G, \varphi'(x,y) , 1/(32 k)}(x, \bar{a}) \rightarrow \St_{G, \varphi(x,y) , 1/k}(x, \bar{a}') \right)$$
 for all $\bar{a} \in I$ simultaneously. Hence the formula $\St_{G, \varphi'(x,y) , 1/(32 k)}(x, \bar{y}) \in \St_{G}(x;\bar{y})$ satisfies the requirement. 
\end{proof}

We also include a proof of Claim \ref{cla: more precise directedness for stabilizers} without using compactness theorem, in the hope for future applications:





\begin{proof}[A proof of Claim \ref{cla: more precise directedness for stabilizers} without using compactness.]




	For $\varphi(x,y) \in L$, where $y$ is any tuple of variables, let $\varphi'(x; y, y') := \varphi(y' \cdot x; y)$. The following are easy to verify from Fact \ref{fac: stab of def meas type def} (for any definable measure $\mu$), using that for all $b$ and $g$ we have $\varphi(g \cdot x;b) = \varphi'(x; b,g)$:
 \begin{gather}
 	\Stab_{G,\varphi', \varepsilon}(\mu) \subseteq \Stab_{G,\varphi, 2 \varepsilon}(\mu), \ 
 	\left( \Stab_{G,\varphi', \varepsilon}(\mu) \right)^{-1} \subseteq \Stab_{G,\varphi, 2 \varepsilon}(\mu), \label{eq: epsilon stabilizers 1}\\
 	\left( \Stab_{G, (\varphi')', \varepsilon}(\mu) \right) \cdot  \left( \Stab_{G, (\varphi')', \varepsilon}(\mu) \right)  \subseteq \Stab_{G, \varphi,  4 \varepsilon}(\mu)\label{eq: epsilon stabilizers 2}
 \end{gather}
(note that $\cdot$ and  $^{-1}$ are defined as $\Stab_{G, \varphi, \varepsilon}(\mu)  \subseteq \varphi_0(\cU)$ from Remark \ref{rem: type-def group formula} always).
% 
%Then$\Stab_{G, \varphi', \varepsilon}(\mu) \cdot \Stab_{G, \varphi', \varepsilon}(\mu) \subseteq \Stab_{G, \varphi,  4 \varepsilon}(\mu)$ (note that $\cdot$ is defined on $\Stab_{G, \varphi', \varepsilon}(\mu)$ as $\Stab_{G, \varphi', \varepsilon}(\mu) \subseteq \varphi_G$). Indeed, assume $g_1, g_2 \in \Stab_{G, \varphi', \varepsilon}(\mu)$. Then  for any $b \in \cU^y$ we have $|\mu(\varphi'(x;b, 1_{G}, 1_{G}) - \mu(\varphi'( g_1 \cdot x;b, 1_{G}, 1_{G})| \leq \varepsilon$ and $|\mu(\varphi'(x;b, 1_{G}, 1_{G}) - \mu(\varphi'( g_1 \cdot x;b, 1_{G}, 1_{G})| \leq \varepsilon$

 Without loss of generality $T$ contains a constant symbol. Then for any $\varphi_1(x,y_1), \varphi_2(x,y_2) \in L$ we can choose $\xi(x, \bar{y}) \in L$, with $\bar{y} = (y_1, y_2, y')$ so that $\Stab_{G,\xi, \varepsilon}(\mu)\subseteq \Stab_{G,\varphi_i, 2\varepsilon}(\mu)$ for both $i \in \{1,2\}$.

Also, given any formula $\varphi(x,y) \in L, k \in \mathbb{N}$, by Lemma \ref{lem: unif defining stab of mu} for any $\bar{a} \in X_{G}$ we have
\begin{gather}
	\forall \bar{a} \in X_{G}, \  \Stab_{G, \varphi, 1/k}(\mu_{\bar{a}}) \subseteq \St_{G, \varphi, 1/k}(\cU, \bar{a}) \subseteq \Stab_{G,\varphi, 18/k}(\mu_{\bar{a}}),\label{eq: epsilon stabilizers 3}
\end{gather} 
 and $\St_{G, \varphi, 1/k}(\cU, \bar{a})$ is defined by $\psi(x;\bar{a}_{\varphi, 1/k}, \bar{a}_{\varphi', 1/k})$ for some $\psi(x;y_{\psi}) \in L$ depending only on $\varphi, \varepsilon$ (but not on $\bar{a}$).

 Let us choose such $\xi(x, y_{\xi})$ for $\varphi_1 (x, y_1) := ((\varphi(x,y)')')'$ and $\varphi_2(x,y_2) := \psi(x,y_{\psi})$ where $\psi(x,\bar{a})$ is the formula as above defining  $\St_{G,\varphi_1, 1/(8k)}(\mu_{\bar{a}})$. And let $k' := 1/(18 \cdot 8 \cdot k)$ (in particular $1/k' < 1/2$).


Now suppose towards contradiction that $g \in \Stab_{G,\xi, 1/k'}(\mu) \setminus \Stab_{G,\varphi,1/k}(\nu)$ for $\nu \in \mathfrak{M}_{G}(\cU)$ a generically stable measure, hence $\nu = \mu_{\bar{a}}$ for some $\bar{a} \in X_G$. 




Then $g \cdot \Stab_{G,\varphi_1, 1/(8k)}(\nu) \cap \Stab_{G,\varphi_1, 1/(8k)}(\nu) = \emptyset$ (otherwise there are some $h_1,h_2 \in \Stab_{G,((\varphi')')', 1/(8k)}(\nu)$ so that $g \cdot h_1 = h_2$, hence, using \eqref{eq: epsilon stabilizers 1} and \eqref{eq: epsilon stabilizers 2}, $g = h_2 \cdot h_1^{-1} \in \Stab_{G, \varphi, 1/k}(\nu)$ --- a contradiction).
Using \eqref{eq: epsilon stabilizers 3} and the choice of $k'$, we have $\St_{G, \varphi_1, 1/k'}(\cU, \bar{a}) \subseteq \Stab_{G,\varphi_1, 1/(8k)}(\nu)$, hence also $g \cdot \St_{G, \varphi_1, 1/k'}(\cU, \bar{a}) \cap \St_{G, \varphi_1, 1/k'}(\cU, \bar{a}) = \emptyset$. 
As $\mu \in \mathfrak{M}_{\Stab_{G}(\nu)}(\cU)$,  we have $\mu (\St_{G, \varphi_1, 1/k'}(x, \bar{a})) = 1$. And as $g \in \Stab_{G,\xi, 1/k'}(\mu)$ and $1/k' < 1/2$, by the choice of $\xi$ we have $\mu (g \cdot \St_{G, \varphi_1, 1/k'}(x, \bar{a})) > 1/2$ --- a contradiction since the total measure is $1$.
\end{proof}







Using Theorem \ref{thm: approx def am by stab gs} and earlier results, we get a description for externally type-definable, definably amenable subgroups of definable groups when \emph{working in a monster model of $M^{\Sh}$}, as a directed union of a family of type-definable \emph{in $T$} subroups:
\begin{proposition}\label{prop: ext def am descr in M'}
		Let $T$ be NIP,  $M \models T$, $\widetilde{M}' \succ M^{\Sh}$ a monster model for $T'$, $G$ a definable group in $M$ and $H(M') \leq G(M')$ a subgroup which is $L'(M)$-type-definable and definably amenable in $T' = \Th(M^{\Sh})$. 
	 Then there exist an $L(M)$-type-definable set $\St_G(x,\bar{y})$ and $L'(M)$-type-definable set $Y \subseteq (M')^{\bar{y}}$, with $|\bar{y}| = |T|$, so that:
	\begin{enumerate}
		\item for every $\bar{a} \in Y(M')$, $\St_G(M'; \bar{a})$  is a type-definable in $M' \models T$ subgroup of $H(M')$ of the form $\Stab_{G}(\mu_{\bar{a}}) \leq H(M')$ for a measure $\mu_{\bar{a}} \in \mathfrak{M}^{L}_{G}(M')$ generically stable over $\bar{a}$ in $T$;
		\item $H(M') = \bigcup_{\bar{a} \in Y} \St_{G}(M', \bar{a})$;
		\item the family $\{\St_{G}(M', \bar{a}) : \bar{a} \in Y\}$ is directed;
		\item $H(M) = \St_G(M; \bar{a})$ for all $\bar{a} \in Y$.
	\end{enumerate}
\end{proposition}
\begin{proof}
	Let $\St'_{H}(x,\bar{y}')$ and $X'_{H}(\bar{y}')$ be $L'(M)$-type-definable as given by  Lemma \ref{lem: unif defining stab of mu}  applied to $H $ in $T'$, and $L(M)$-type-definable $\St_{G}(x,\bar{y}), X_{G}(\bar{y})$ given by Lemma \ref{lem: unif defining stab of mu} for $G$ in $T$. Here $\bar{y}' = \left(y_{\varphi, 1/k} : \varphi(x,y) \in L', k \in \mathbb{N} \right)$ is a tuple of length $|T'|$, and $\bar{y} = \bar{y}'\restriction_{L} := \left(y_{\varphi, 1/k} : \varphi(x,y) \in L, k \in \mathbb{N} \right)$ is a subtuple of length $|T|$.




	So generically stable measures in $\mathfrak{M}^{L'}_{H}(\cU)$ are precisely the measures of the form $\bar{\mu}_{\bar{a}'}$ with $\bar{a}' \in X'_{H}(M')$, and  $\St'_{H}(M',\bar{a}') = \Stab_{H}(\mu_{\bar{a}'})$. Given $\bar{a}' \in X'_H$, let $\bar{a} := \bar{a}'\restriction_{L}$, then $\bar{a} \in X_{G}$,  $(\mu_{\bar{a}'})\restriction_{L} = \mu_{\bar{a}}$ (where the former is given by Definition \ref{def: X_x} in $T'$, and the latter in $T$), $\mu_{\bar{a}}$ is generically stable (in $T$) and $\mu_{\bar{a}'}$ is the unique measure extending it; and every $\bar{a} \in X_{G}$ extends (non-uniquely) to $\bar{a}' \in X'_{G}$  (both by Theorem \ref{thm: corresp for gs measures}).


	By Remark \ref{rem: stab contained in a subgroup} in $T'$, for any generically stable $\bar{\mu}' \in \mathfrak{M}^{L'}_{H}(M')$ we have $\Stab_{G}(\bar{\mu}') = \Stab_{H}(\bar{\mu}') \leq H(M')$; and, as the proof of Theorem \ref{thm: main for fsg subgroups} shows, $\Stab_{G}(\bar{\mu}') = \Stab_{G}(\bar{\mu}' \restriction_{L})$, so 
	\begin{gather}
		\St_{G}(M', \bar{a}) = \St'_{G}(M',\bar{a}') = \St'_{H}(M', \bar{a}') \leq H(M') \textrm{ for all } \bar{a}' \in X'_{H}. \label{eq: internal stab subrp of H}
	\end{gather}


	By Theorem \ref{thm: approx def am by stab gs} applied to $H$ in $T'$, the family $\{\St'_{H}(M',\bar{a}') : \bar{a}' \in X'_{H} \}$ is directed and its union is $H(M')$. 
Let 
$$Y := \{\bar{a} \in X_{G} : \exists \bar{a}' \in X'_{H}  \left( \bar{a}' \restriction_{L} = \bar{a} \ \land H(M) \  \subseteq  \St'_{G}(M', \bar{a}') \right)\}.$$
 By $L'(M)$-type-definability of $X'_{H}$ and compactness in $\widetilde{M}'$, $Y$ is also $L'(M)$-type-definable. And $Y$ and $\St_{G}$ satisfy the requirement.
\end{proof}

\begin{remark}\label{rem: am subg is trace of type-def}
	In particular, if $G$ is definable and $H \leq G(M)$ is externally (type-)definable and definably amenable in $T'$, then $H(M) = K(M)$ for some $K(M') \leq H(M')$ a type-definable in $M'$ subgroup of $H(M')$. Can we additionally assume that $K(M')$ is definably amenable in $T$?
\end{remark}

Next we would like to extract from Proposition \ref{prop: ext def am descr in M'} a description of $H(M)$ \emph{entirely in $M$}. As Example \ref{ex: ext def ab wo type-def subgrps} shows, in general there might be no $M$-type-definable subgroups of $H(M)$. We are going to present $H(M)$ as a union of a (uniformly, product-) directed family of type-definable subsets of the form $\St_{G}(M, \bar{a})$ with $\bar{a}$  in $M$ but \emph{not necessarily in $X_{G}$} (as $X_{G} \cap M$ can be empty). Such a set corresponds to the intersection of approximate stabilizers of a (possibly infinite) sequence of finitely supported in $M$ measures (as opposed to a single, not necessarily finitely supported, generically stable measure when $\bar{a} \in X_{G}$), hence no longer gives a subgroup of $G(M)$ --- but the directedness of the family will be preserved.


\begin{theorem}\label{thm: ext def abelian final approx in M}
	Let $T$ be NIP,  $M \models T$, $G$ a definable group in $M$ and $H(M) \leq G(M)$ a subgroup that is $L'(M)$-definable and definably amenable  in $T'$.
	 Then there is an $M$-type-definable in $T$ set $\Gamma(x, \bar{y})$ and a strict $L'(M)$-pro-definable set $Z \subseteq \cU^{\bar{y}}$ with $|\bar{y}| = |T|$ so that:


	\begin{enumerate}

		\item $H(M) = \bigcup_{\bar{a} \in Z} \Gamma(M, \bar{a})$;
		\item  the family $\{\Gamma(M, \bar{a}) : \bar{a} \in Z\}$ is uniformly product directed.
	\end{enumerate}

	\end{theorem}
\begin{proof} 


We continue in the setting and notation of (the proof of) Proposition \ref{prop: ext def am descr in M'}. So $H(M') \leq G(M')$ is $L'(M)$-definable in $T'$. And, from 
Proposition \ref{prop: ext def am descr in M'}\eqref{eq: internal stab subrp of H}, we have $H(M') = \bigcup_{\bar{a}' \in X'_{H}} \St'_{H}(M', \bar{a}')$ and $H(M) = \St_{G}(M, \bar{a})$ for all $\bar{a} \in  Y$. 
Here $\bar{a}' = \left(\bar{a}_{\varphi, 1/k} : \varphi(x,y) \in L', k \in \mathbb{N} \right)$ is a tuple of length $|T'|$, and $\bar{a} = \bar{a}'\restriction_{L} := \left(\bar{a}_{\varphi, 1/k} : \varphi(x,y) \in L, k \in \mathbb{N} \right)$ is a subtuple of length $|T|$ (and similarly for $\bar{y}'$ and $\bar{y} := \bar{y}' \restriction L$).
The following claims refine/uniformize the steps in the proof of Proposition \ref{prop: ext def am descr in M'}.

\begin{claim}\label{cla: uniform directedness in H}
	For every $\varphi(x,y) \in L', k \in \mathbb{N}$ there are some $\varphi'(x,y') \in L', k' \in \mathbb{N}$ so that: for every $n \in \mathbb{N}$ and $\bar{a}'_1, \ldots, \bar{a}'_n \in X'_{H}$ there is some $\bar{a}' \in X'_{H}$ so that $\St'_{H, \varphi', 1/k'} \left(x,(\bar{a}'_i)_{\varphi', 1/k'} \right) \vdash^{T'} \St'_{H, \varphi, 1/k}\left(x,\bar{a}'_{\varphi, 1/k} \right)$ for all $i \in [n]$.
\end{claim}
\begin{proof}
	By Proposition \ref{prop: getting unif directed} applied to $H$ in $T'$.
\end{proof}



\begin{claim}\label{cla: approx stabs imply H}
	There are some $\varphi(x,y) \in L, k \in \mathbb{N}$ so that: for every $\bar{a}' \in X'_{H}$,  $\St_{G, \varphi, 1/k} \left(x, \bar{a}_{\varphi, 1/k} \right) \vdash^{T'} \psi(x)$.
\end{claim}
\begin{proof}
Suppose not. Hence, using Remark \ref{rem: one stabilizer implies two stabilizers}, for any $n \in \mathbb{N}$ and $\varphi_i(x,y_i)  \in L, k_i \in \mathbb{N}$ for $i \in [n]$ there are some $b, \bar{a}'$ in $M'$ with 
$$\widetilde{M}' \models \neg H(b) \land X'_{H}(\bar{a}') \land  \bigwedge_{i \in [n]} \St_{G, \varphi_i, 1/(k_i)}(b, \bar{a}).$$
By saturation of $\widetilde{M}'$ we thus find some  $b, \bar{a}'$ in $M'$ so that

$$\widetilde{M}' \models \neg H(b) \land X'_{H}(\bar{a}') \land  \St_{G}(b, \bar{a}),$$
contradicting \eqref{eq: internal stab subrp of H}.
\end{proof}




\begin{claim} \label{cla: approx stab in T imply T'}
	For every $\varphi(x,y) \in L', k \in \mathbb{N}$ there is $\varphi'(x,y') \in L, k' \in \mathbb{N}$ so that: for every $\bar{a}' \in X'_{H}$	 we have $\St_{G, \varphi', 1/k'}\left(x,\bar{a}_{\varphi', 1/k'} \right) \vdash^{T'} \St'_{H, \varphi, 1/k} \left(x,\bar{a}'_{\varphi, 1/k} \right) $.
\end{claim}
\begin{proof}
Similarly, follows by compactness in $T'$ as $\St_{G}(M', \bar{a}) = \St'_{H}(M', \bar{a}') \leq H(M')$ for all $\bar{a}' \in X'_{H}$ by \eqref{eq: internal stab subrp of H}.
\end{proof}


Uniform (product-) directedness holds for arbitrary tuples  in $H(M')$  as opposed to just $\bar{a}' \in X'_{H}$:
\begin{claim}\label{cla: putting things together}
	For any $\varphi(x,y) \in L'$ and $ k\in \mathbb{N}$ there are $\varphi'(x,y') \in L, k' \in \mathbb{N}$ so that:  for any $n \in \mathbb{N}$ and finite tuples $\bar{a}^{\ast}_1, \ldots, \bar{a}^{\ast}_n $ in $H(M')$ of length corresponding to $\bar{y}_{\varphi', 1/k'}$, there is a tuple $\bar{a}^{\ast}$ in $H(M')$ of length corresponding to $\bar{y}_{\varphi, 1/k}$ so that $\left( \bigcup_{i \in [n]}\St_{G, \varphi', 1/k'}\left(M',\bar{a}^{\ast}_i \right) \right)^2 \subseteq \St'_{H, \varphi, 1/k}\left(M',\bar{a}^{\ast} \right)$.
\end{claim}
\begin{proof}



Given $\varphi(x,y) \in L'$ and $k \in \mathbb{N}$, by \eqref{eq: epsilon stabilizers 2} there exist $\varphi_1(x,y_1)$ and $k_1 \in \mathbb{N}$ so that $(\St_{G, \varphi_1, 1/k_1}(M';\bar{a}'))^2 \subseteq \St_{G, \varphi, 1/k}(M';\bar{a}')$ for any $\bar{a}' \in X'_{H}(M')$. 

Applying Claims \ref{cla: uniform directedness in H} and \ref{cla: approx stab in T imply T'} to $\varphi_1, k_1$ we find $\varphi'(x,y') \in L, k' \in \mathbb{N}$ so that for any $n$ and $\bar{a}'_1, \ldots, \bar{a}'_n \in X'_{H}$ there is $\bar{a}' \in X'_{H}$ so that 
$$\left( \bigcup_{i \in [n]}\St_{G, \varphi', 1/k'}\left(M',(\bar{a}_i)_{\varphi', 1/k'} \right) \right)^2 \subseteq \St'_{H, \varphi, 1/k}\left(M',\bar{a}'_{\varphi, 1/k} \right).$$





Now let $\bar{a}^{\ast}_1, \ldots, \bar{a}^{\ast}_n $ be arbitrary tuples in $H(M')$ of length corresponding to $\bar{y}_{\varphi', 1/k'}$. Then there exist $\bar{a}'_1, \ldots, \bar{a}'_n \in X'_{H}$ so that $(\bar{a}'_i)_{\varphi', 1/k'} = a^{\ast}_i$ for all $i \in [n]$. Namely, $\Av^{L'}(\bar{a}_i^{\ast})$ (calculated in $T'$) is a (finitely supported) generically stable measure in $\mathfrak{M}_{H}^{L'}(M')$, so we can choose $\bar{a}'_i \in X'_{H}$ so that $\mu_{\bar{a}'_i} = \Av^{L'}(\bar{a}_i^{\ast})$ and $(\bar{a}'_i)_{\varphi', 1/k'} = a^{\ast}_i$). Then there is some $\bar{a}' \in X'_{H}$ so that 
$$\left( \bigcup_{i \in [n]}\St_{G, \varphi', 1/k'}\left(M',\bar{a}^{\ast}_i \right) \right)^2 \subseteq \St'_{H, \varphi, 1/k}\left(M',\bar{a}'_{\varphi, 1/k} \right).$$
And, by Remark \ref{rem: meas code rep inside the partial type} we can choose $\bar{a}'$ contained in $H(M')$, so in particular $\bar{a}^{\ast} := \bar{a}'_{\varphi,1/k}$ is contained in $H(M')$.
\end{proof}


	Now we let $\Gamma(x,\bar{y}) := \St_{G}(x,\bar{y})$ and take the strict $L'(M)$-pro-definable set 
	$$Z := \left\{\bar{a} \in (M')^{\bar{y}}: \bigwedge_{\varphi \in L, k \in \mathbb{N}} \bar{a}_{\varphi, 1/k} \subseteq H(M') \right\}.$$

	By Claim \ref{cla: putting things together} and using $M^{\Sh} \prec^{L'} \widetilde{M}'$ repeatedly it follows that the family $\{\St_{G}(M, \bar{a}) : \bar{a} \in Z(M) \}$ is uniformly product-directed. 
	Using Claim \ref{cla: approx stabs imply H} we have $\Gamma(M,\bar{a}) \subseteq H(M)$ for every $\bar{a} \in Z(M)$. And as $H(M) = \St'_{H}(M, \bar{a}')$ for some $\bar{a}' \in X'_{H}$, given any finite $A \subseteq H(M)$ and using $M^{\Sh} \prec^{L'} \widetilde{M}'$ repeatedly we can choose $\bar{a} \in Z(M)$ with $A \subseteq \St_{G}(M, \bar{a})$.
