\begin{remark}
	By Proposition \ref{prop: ext def subgroups approx V-def}, we can also write $H(M)$ as a union of a uniformly $L(M)$-$\bigvee$-definable directed family of its subgroups.
\end{remark}


Finally, we discuss the relation to some results in the literature on definable envelopes of subgroups of NIP groups preserving certain properties:
\begin{fact}
	Let $M \models T$ be NIP, $\cU \succ M$ a monster model and $G$ an $M$-definable group. Let $H$ be a (not necessarily definable) subgroup of $G(M)$.
	\begin{enumerate}
		\item \cite{zbMATH05662715} If $H$ is abelian, there exists a $\cU$-definable abelian subgroup $K \leq G(\cU)$ with $H \subseteq K(M)$.
		\item \cite{zbMATH06177016} If $H$ is nilpotent, there exists a $\cU$-definable subgroup $K \leq G(\cU)$ of the same nilpotency class as $H$ with $H \subseteq K(M)$.
		\item \cite{zbMATH06177016} If $H$ a normal subgroup of $G(M)$ and solvable, there exists a $\cU$-definable subgroup $K \leq G(\cU)$ of the same derived length  as $H$ with $H \subseteq K(M)$.
		\item \cite{zbMATH06578125} If $H$ is solvable, there exists a type-definable in $\cU$ subgroup $K \leq G(\cU)$ given by a downwards directed family of  uniformly $\cU$-definable sets with $H \subseteq K(M)$.
	\end{enumerate}
\end{fact}
\begin{question}
Is the analogous statement true for $H$ an amenable subgroup of $G(M)$?	
\end{question}

In particular, every externally definable subgroup of $G(M)$ with a corresponding property is contained in the trace on $M$ of an $\cU$-definable subgroup $K(\cU)$ of $G(\cU)$ with this property.  We can actually choose $K$ to be $M$-definable in this case, e.g.:

\begin{proposition}\label{prop: ext def ab in def ab}
	Let $M \models T$ be NIP, $G$ a  definable group in $M$, and $H \leq G(M)$ an externally definable abelian subgroup. Then there exists an $M$-definable abelian subgroup $K(M) \leq G(M)$ so that $H(M) \leq  K(M)$.
\end{proposition}
\begin{proof}
	Let $\theta(x) \in L(M')$ be an honest definition for $\neg H(x)$, i.e.~$\theta(x) \vdash^{T'} \neg H(x)$ and $\neg H(M) = \theta(M)$. Then $H(M) =\neg \theta(M)$ and $H(x) \vdash^{T'} \neg \theta(x)$.

	Let $K(M') := C_{G}(C_{G}(\neg \theta(M')))$ (where $C_{G}(A)$ denotes the centralizer of $A$ in $G(M')$). As  $\widetilde{M}' \succ^{L'} M^{\Sh}$, we have that $H(M')$ is an abelian subgroup of $G(M')$, hence $K(M')$ is an abelian $L(M')$-definable subgroup of $G(M')$ and $H(M') \subseteq  K(M')$.  Say $K(M')$ is defined by $\psi(x,b)$ for $\psi(x,y) \in L$ and $b \in (M')^y$. Using $\widetilde{M}' \succ^{L'} M^{\Sh}$ again, there is some $b' \in M^y$ so that still $H(M) \subseteq \psi(M,b')$ and $\psi(M,b')$ is an abelian subgroup of $G(M)$.
\end{proof}








\section{Hyperdefinable group chunk for partial type-definable types}
\label{sec: Hyperdefinable group chunk for partial type-definable types}

\subsection{Preliminaries on hyperdefinability}\label{sec: Basics on hyperdefinability}
We refer to e.g.~\cite[Chapter 3]{wagner2000simple}, \cite[Chapter 15]{casanovas2011simple} for basics on hyperdefinability. We set up some notation in a way convenient for the discussion of large partial types and their type-definability (which agrees with the usual treatment of hyperimaginaries, see e.g.~``uniform definitions'' in \cite[Section 1]{fanlo2023piecewise}).

A hyperdefinable set is a quotient $P = X/E$  with $X$ non-empty ($\emptyset$-)type-definable set and $E$ a type-definable equivalence relation. Given $a \in X$, $a_E$ denotes $a/E \in P$, and given $a \in P$, $a^* \in a$ denotes a representative of $a$; we let $\quot_E: X \to P, \quot_E(a) := a_E$ denote the quotient map. The elements of a hyperdefinable set are called \emph{hyperimaginaries}. We let $\cU^{\heq}$ denote $\cU$ together with the collection of all hyperimaginaries modulo $(\emptyset)$-type-definable equivalence relations.

Let $E_i$ be type-definable equivalence relations on $\cU^{x_i}$. A partial type $\pi((x_i)_{i \in I})$ over $\cU$ is \emph{$E_i$-invariant on $x_i$} if $\pi((x_i)_{i \in I}) \land E_i(x_i, x'_i) \vdash \pi(\bar{x}')$ where $\bar{x}'$ is obtained from $(x_i)_{i \in I}$ replacing $x_i$ by $x'_i$. For a formula $\varphi((x_i)_{i \in I_0}) \in L(\emptyset)$, consider the partial type  
$$\Delta_{\varphi}((x_i)_{i \in I_0}) := \exists (x'_i)_{i \in I_0} \left( \bigwedge E_i(x_i,x'_i) \land \varphi((x'_i)_{i \in I_0}) \right)$$
$E_i$-invariant on $x_i$ for all $i \in I_0$.
\begin{lemma}\label{lem: hyperdef part types formulas}
	If $\pi((x_i)_{i \in I})$ is closed under conjunctions, it is $E_i$-invariant on $x_i$ for all $i \in I$ if and only if $\pi(x) \equiv \bigcup_{\varphi \in \pi} \Delta_{\varphi}((x_i)_{i \in I_0})$.
\end{lemma}
\begin{proof}
	Right to left is clear.  Conversely, assume  $\varphi((x_i)_{i \in I_0}) \in \pi$. Clearly, $\varphi((x_i)_{i \in I_0}) \vdash \Delta_{\varphi}((x_i)_{i \in I_0})$. On the other hand, as $\pi((x'_i)_{i \in I}) \land \bigwedge_{i \in I} E_i(x,x') \vdash \pi((x'_i)_{i \in I})$, by compactness and closure of $\pi$ under conjunctions there is some $\psi((x_i)_{i \in I_0}) \in \pi$ so that $\psi((x'_i)_{i \in I_0}) \land \bigwedge_{i \in I_0}E(x_i,x'_i) \vdash \varphi((x_i)_{i \in I_0})$, hence $\Delta_{\psi}((x_i)_{i \in I_0}) \vdash \varphi((x_i)_{i \in I_0})$. 
\end{proof}



Let $P = X/E$ and $Q_i = Y_i/F_i$ be hyper-definable. 
By a \emph{partial type $\pi(x)$ on $P$ over a (possibly large) set of hyperimaginaries} $B = \{ b_{F_i} \in Q_i : i \in I\}$ we mean a partial type of the form $\pi^*(x, (b_i)_{i \in I})$ over a set of real elements $\{b_i : i \in I\}$ so that $\pi^*(x; (y_i)_{i \in I})$ is a partial type over $\emptyset$ which is $E$-invariant on $x$ and $F_i$-invariant on $y_i$  and $\pi^*(x, (b_i)_{i \in I}) \vdash X(x) \cup \{Y_i (y_i)\}_{i \in I}$. Up to logical equivalence of partial types, this does not depend on the choice of the representatives $b_i, i \in I$.
	We say that $a_E \models \pi(x)$ if $a \models \pi^*(x; (b_i)_{i \in I})$. Again, this does not depend on the choice of representatives. For $\pi(x), \rho(x)$ partial types on $P$, we write $\pi(x) \vdash \rho(x)$ if $\pi^*(x, (b_i)_{i \in I}) \vdash \rho^*(x, (c_j)_{j \in J})$. We say that $\pi(x)$ (over $\cU^{\heq}$) is \emph{closed under implication} if for every small partial type $\rho(x)$ on $P$ (over hyperimaginary parameters) with  $\pi(x) \vdash \rho(x)$ we have $\rho^*(x, (c_j)_{j \in J}) \subseteq \pi^*(x; (b_i)_{i \in I})$. In particular if $\pi, \rho$ are closed under implication and $\pi \vdash \rho, \rho \vdash \pi$, then $\pi^*(x, (b_i)_{i \in I}) = \rho^*(x, (c_j)_{j \in J})$.

For a small set $B \subseteq \cU^{\heq}$, a set $V \subseteq P$ is $B$-type-definable if $V = \{b \in P : \models \pi(b) \}$ for $\pi$ a partial type on $P$ over $B$ (then $\quot^{-1}_{E}(V)$ is a $B^*$-type-definable subset of $X$ for any set $B^*$ of representatives of $B$).
Given hyperdefinable sets $P = X/E$ and $Q = Y/F$, the cartesian product $P \times Q$ is canonically identified with the hyperdefinable set $(X \times Y) / (E \land F)$, where $(x,y) (E\land F) (x',y')$ if $x E x'$ and $y F y'$. This allows to talk about hyperdefinable relations and (partial) functions. In particular, if $f$ is a $B$-type definable function from $P$ to $Q$, then for any $B$-type-definable sets $V \subseteq P, W \subseteq Q$, both $f(V) \subseteq Q$ and $f^{-1}(W) \subseteq P$ are $B$-type-definable. If $\rho(x,y)$ is a partial type on $P \times Q$ over $c \subseteq \cU^{\heq}$, witnessed by $\rho^*(x,y;c^*)$ and $b \in Q$, then $\rho(x;b)$ is a partial type on $P$ witnessed by $\rho^*(x;b^*,c^*)$.


