\begin{definition}\label{def: def type hyperim}
	We say that a partial type $\pi(x)$ (over $\cU^{\heq}$) on $P$ is \emph{type-definable over $A \subseteq \cU^{\heq}$} if for every sort $Q$ in $\cU^{\heq}$ and small partial type  $\gamma(x,y)$ on $P \times Q$ over $\emptyset$,  the set $\{b \in Q : \pi(x) \vdash \gamma(x,b)\}$ is type-definable over $A$ by some partial type $\rho(y) =: (d_{\pi}x) \gamma(x,y)$ on $Q$.
\end{definition}
\begin{remark}\label{rem: around typ-def types def}
	By Lemma \ref{lem: hyperdef part types formulas}, it suffices to require this for $\gamma(x,y) := \Delta_{\varphi} (x,y)$, $\varphi(x,y) \in L$; equivalently, we can let $\gamma(x,y)$ be an arbitrary small type over $A$, as then we can take $(d_\pi x) \gamma(x,y) := (d_\pi x) \gamma'(x,y, \bar{a})$, where $\bar{a}$ is a tuple enumerating $A$ and $\gamma'(x,y,z)$ is a partial type on $P \times Q \times R$ such that $\gamma(x,y) = \gamma'(x,y,\bar{a})$.
\end{remark}
%\begin{remark}
%	A partial type $\pi$ on $P$ is type-definable over $A$ if and only if for every $\varphi(x,y) \in L$, the requirement in Definition \ref{def: def type hyperim} holds for $\gamma(x,y) := \Delta_{\varphi(x,y)}^{(E \land =)} (x,y)$ (applying Lemma \ref{lem: hyperdef part types formulas} to an $(E \land =)$-invariant $\gamma(x,y)$). We will write $(d_{\pi}x) \varphi(x,y)$ as an abbreviation for the partial type $(d_{\pi}x) \Delta_{\varphi(x,y)}^{(E \land =)} (x,y)$.
%	\end{remark}

\begin{definition}
		If $C \subseteq \mathbb{M}^{\heq}$ is a set of parameters, we define $\pi|_{C} := \bigcup \{\gamma(x,m) : \mathbb{M} \models (d_{\pi}x) \gamma(x,m), m \in C, \gamma(x,y)\textrm{ small partial type over }\emptyset\}$. If $C$ is an $|A|^+$-saturated model, then $\pi|_C$ determines $\pi$.
\end{definition}

\begin{remark}\label{rem: realize over dcl heq}
	If $C \subseteq \mathbb{M}^{\heq}$ is a small set of parameters, $b \in \cU^{\heq}, a \models \pi|_{C b}$ and $d \in \dcl^{\heq}(C, b)$, then $a \models \pi|_{C d}$.

	Indeed, as $d \in \dcl^{\heq}(C, b)$, there is a partial $C$-type-definable function $f: Y/F \to Z/G$ so that $f(b) = d$. Let $\Gamma_f(y,z)$ be the partial type over $C$ defining the graph of $f$, then $\Gamma_f(b, d)$.
	Now assume that $\gamma(x,z)$ is a partial type on $X/E \times Y/F$ over $C$ such that $\pi(x) \vdash \gamma(x,d)$. Then $\pi(x) \vdash \exists z \left( \Gamma_f(b,z) \land \gamma(x,z) \right)$, with a small partial type on $X/E \times Z/G$ over $C, b$ on the right. Hence $ \models \exists z \left( \Gamma_f(b,z) \land \gamma(a,z) \right)$ by assumption, so $ \models \gamma(a,d)$ as $d$ is the unique realization of $\Gamma_f(b,z)$.
\end{remark}


\begin{definition}\label{def: pushforward of types}
	Let $A \subseteq \cU^{\heq}$, $\pi(x)$ a partial type over $\cU^{\heq}$ on $P$, $Q$ a sort in $\cU^{\heq}$ and $f: P \to Q$ an $A$-type-definable partial function \emph{defined on $\pi$} (i.e.~$\pi(x) \vdash \exists y \Gamma_{f}(x,y) $), in which case already $\pi(x)|_{A} \vdash \exists y \Gamma_f(x,y) $). We define the \emph{pushforward} 
	\begin{gather*}
		(f_{\ast} \pi)(y) := \bigcup\Big\{\gamma(y) : \pi(x) \vdash \exists u (\Gamma_f(x,u) \land \gamma(u)), \\
		\gamma(y) \textrm{ is  a small partial type on } Q\Big\}.
	\end{gather*}
	Then $f_{\ast}\pi$ is a partial type on $Q$. (This corresponds to the pushforward of the corresponding filter of type-definable subsets of $P$.)
\end{definition}



\begin{remark}\label{rem: pushfoward preserves type-def}
	If $\pi, f$ are type-definable over $A$, then $f_{\ast}\pi$ is also type-definable over $A$: for every small partial type $\gamma(y,z)$ on $Q$ over $\emptyset$, we have 
	$$(d_{(f_{\ast} \pi)} y) \gamma(y,z) = d_{\pi}x (\exists u (\Gamma_f(x,u) \land \gamma(u,z))).$$
\end{remark}

\begin{remark}\label{rem: pushforward sets of realiz}
	In the same situation as above, if $\pi$ is a partial type closed under implication, then for any $B \supseteq A$ we have $f( \pi|_{B}( \cU)) = (f_{\ast} \pi)|_{B}(\cU)$.

	Indeed, we clearly have $f(\pi|_{B}(\cU)) \subseteq (f_{\ast} \pi)|_{B}(\cU)$ from the definition. Then $\pi|_{B}(\cU) \subseteq f^{-1}(f(\pi|_{B}(\cU))) \subseteq f^{-1}((f_{\ast} \pi)|_{B}(\cU))$, hence $\pi|_{B}(\cU) = f^{-1}((f_{\ast} \pi)|_{B}(\cU))$ using $B$-type-definability of these sets and closure of $\pi$ under implication.
\end{remark}

\begin{definition}
	Let $\pi(x), \rho(y)$ be $A$-type-definable partial types over $\cU^{\heq}$ on sorts $P,Q$ respectively. We define a partial type $(\pi \otimes \rho)(x,y)$ on $P \times Q$  by taking
	$$(d_{\pi \otimes \rho} x y)\gamma(x,y;z) := (d_{\pi} x) \left( (d_{\rho} y) \gamma(x,y,z) \right)$$
	for every small partial type $\gamma(x,y;z)$ over $\emptyset$ on $P \times Q \times R$. (This is well-defined by Remark \ref{rem: around typ-def types def} as $(d_{\rho} y) \gamma(x,y,z)$ is a small partial type on $P \times R$ over $A$.) 
\end{definition}

\begin{remark}\label{rem: prod of partial types realiz}
	It follows from the definition that for any $B \supseteq A$, $(a, b) \models (\pi \otimes \rho)|_{B}$ if and only if $a \models \pi|_{B}$ and $b \models \rho|_{B,a} $.
\end{remark}


\begin{definition}\label{def: germs}
	Let $\pi(x)$ be a partial $C$-type-definable type over $\cU^{\heq}$. Two type-definable functions $f(x,b)$ and $g(x,c)$, for $b,c$ hyperimaginaries, defined on $\pi$, are said to have the same \emph{$\pi$-germ}, written $f(x,b) \sim_{\pi} g(x,c)$, if $f(a,b) = g(a,c)$ \emph{for all} $a \models \pi|_{C, b,c}$. Equivalently, if $\pi(x) \vdash \exists z \left( \Gamma_f(x,b,z) \land \Gamma_g(x,c,z)\right)$; if and only if $ \models (d_{\pi}x) \exists z  \left(\Gamma_f(x,b,z) \land \Gamma_g(x,c,z) \right)$ --- a type-definable condition on $(b,c)$. Then $\sim_{\pi}$ is an equivalence relation on all type-definable partial functions defined on $\pi$, and we let $[f(x,b)]_{\pi}$ denote the $\pi$-germ of $f(x,b)$.
	\end{definition}

	\begin{remark}\label{rem: push forward germs}
		In fact, push-forwards of $\pi$ are well-defined for $\pi$-germs of type-definable partial functions defined on $\pi$: if  $f(x) \sim_{\pi} g(x)$, then $f_{\ast} \pi = g_{\ast} \pi$. Indeed, if $\gamma(u)$ is  a small partial type,  $\pi(x) \vdash \exists u (\Gamma_f(x,u) \land \gamma(u))$ if and only if $\pi(x) \vdash \exists u (\Gamma_g(x,u) \land \gamma(u))$.
\end{remark}

		\begin{remark}\label{rem: real partial type in heq}
		If $\pi$ is a partial type over $\cU$ closed under implication, then  $\pi$ viewed as a partial type on the home sort over $\cU^{\heq}$ is also closed under implication.  And if $\pi$ was $A$-type-definable, $A \subseteq \cU$, then $\pi$ remains an $A$-type-definable partial type in $\cU^{\heq}$.
	\end{remark}
\subsection{Hyperdefinable group chunk}\label{sec: Hyperdefinable group chunk proof}

 We will need a hyper-definable generalization of the group chunk theorem from \cite[Section 3.4]{hrushovski2019valued} to \emph{type-definable} partial types (as opposed to definable partial types; see also \cite[Section 3]{rideau2021short}; and \cite[Section 4.7]{wagner2000simple} for a different hyper-definable group chuck theorem in simple theories).  We refer to e.g.~\cite[Section 4.3]{wagner2000simple} or \cite{fanlo2023piecewise} for the basics on hyper-definable groups. A hyper-definable group is given by a hyper-definable set $G$ and a type-definable binary function $\cdot: G^{2} \to G$ such that $(G, \cdot)$ forms a group.

\begin{remark}\label{rem: translates of partial types}
	If $(G, \cdot_{G})$ is a hyper-definable group, $\pi(x)$ a partial type on $G$ (over $\cU^{\heq}$) and $g \in G(\cU)$, we let $g \cdot \pi := (t_g)_{\ast} \pi$ where $t_g: G \to G$ is the type-definable map $h \in G \mapsto g \cdot h$. Then $g \cdot \pi$ is a partial type on $G$, and if $\pi$ was $C$-type-definable, then $\pi$ is $C \cup \{g \}$-type-definable. Note that if $g \cdot \pi = \pi$, then also $g^{-1} \cdot \pi = \pi$.
\end{remark}



 \begin{definition}\label{defn: group chunk}
 	Let $P = X/E$ with $X,E$ type-definable over $C \subseteq \cU^{\heq}$. A \emph{group chunk} over a small set of parameters $C$ on $P$ is  a $C$-type-definable partial type $\pi(x)$ on $P$ in $T^{\heq}$ closed under implication and $C$-type-definable partial functions $F,H: P^2 \to P$ defined on $\pi^{\otimes 2}$ (and hence on $\pi^{\otimes 2}|_{C}$) and $K: P^2 \to P$, so that:
 	\begin{enumerate}
 		\item for all $a \models \pi|_{C}$, $(F_a)_{\ast} \pi = \pi$, where $F_a(x) := F(a,x)$;
 		\item if $(a,b) \models \pi^{\otimes 2}|_{C}$, then $H(a,F(a,b)) = b$ and  $ K(b, F(a,b)) = a$ (in particular the partial function $K$ is  defined).
 		\item if $(a,b,c) \models \pi^{\otimes 3}|_{C}$, then $F(a,F(b,c)) = F(F(a,b), c)$.  	\end{enumerate}
 \end{definition}

 \begin{remark}
 \begin{enumerate}

 	\item Note that by Definition \ref{defn: group chunk}(1), if $(a,b) \models \pi^{\otimes 2}|_{C}$, then $(a, F(a,b)) \models \pi^{\otimes 2}|_{C}$, hence $H(a,F(a,b))$ in Definition \ref{defn: group chunk}(2) is defined. However, the requirement that $ K(y, F(x,y))$ is defined on $g_{\ast}(\pi^{\otimes 2})$ for  $g(x,y) := (y, F(x,y))$ needs to be made separately (follows from (1) if $\pi$ $\otimes$-commutes with itself).
 	\item The composition of partial functions in Definition \ref{defn: group chunk}(3) is well-defined. Indeed, assume $(a,b,c) \models \pi^{\otimes 3}|C$. Then $(b,c) \models \pi^{\otimes 2}|_{C,a}$, so $F(b,c) \models \pi^{\otimes 2}|_{C,a, b}$ by Definition \ref{defn: group chunk}(1), so $(a, F(b,c)) \models \pi^{\otimes 2}|_{C}$. Also $c \models \pi|_{C,a,b}$, hence $c \models \pi|_{C, F(a,b)}$ (by Remark \ref{rem: realize over dcl heq}).

 	\item In \cite[Section 3.4]{hrushovski2019valued}, in Definition \ref{defn: group chunk}(2) one simply requires $a \in \dcl(C, b, F(a,b))$, $b \in \dcl(C, a, F(a,b))$, which by compactness allows to find definable partial functions $H,K$. Since  $\dcl^{\heq}$ is only given by partial types rather than formulas, we cannot apply the same compactness argument here, and require the existence of type-definable partial functions $H,K$ explicitly.
 \end{enumerate}
 \end{remark}


 Of course, every type-definable translation invariant partial type on a hyper-definable group gives rise to a group chunk:
\begin{remark}\label{rem: group chunk from a group}
	Assume $G$ is a hyper-definable over $C \subseteq \cU^{\heq}$ group and $\pi(x)$ is a partial left-$G$-invariant type on $G$ (over $\cU^{\heq}$), type-definable over $C$. Let $\Gamma(x,y,z)$ be the $C$-type-definable graph of multiplication in $G$, without loss of generality $\Gamma(x,y,z)$ defines a graph of partial function from any two of its coordinates to the third one (intersecting with the partial type defining $G$ on every coordinate, if necessary). Consider the partial type-definable functions  $F(x,y)$ with $\Gamma_{F}(x,y,z) := \Gamma(x,y,z)$, $H$ with $\Gamma_{H}(x,y,z) := \Gamma(x,z,y)$ and $K$ with $\Gamma_{K}(x,y,z) := \Gamma(z,x,y)$. Then $(\pi, F,H,K)$ is a group chunk satisfying Definition \ref{defn: group chunk}.
\end{remark}

Conversely,

\begin{theorem}\label{thm: hyperdef group chunk gives group}
	Let $(\pi,F,H,K)$ be a group chunk over $C$ on $P$. Then there exists a $C$-hyper-definable group $G = (Y/F', \cdot_G)$ and a $C$-type-definable partial function $f: \pi \to G$ defined and injective on $\pi$, so that for any $(a,b) \models \pi^{\otimes 2}|_{C}$ we have $f(F(a,b)) = f(a) \cdot_{G} f(b)$ and the global partial type $f_{\ast} \pi$ concentrates on $G$ and is left-$G$-invariant.
\end{theorem}
\begin{proof}
	We follow closely the proof of \cite[Proposition 3.15]{hrushovski2019valued}, but provide some details.

	We let $\mathfrak{F}(\pi)$ be the semigroup under composition of all $\cU^{\heq}$-type-definable functions $h$ such that $h_{\ast} \pi = \pi$. This semigroup has a quotient consisting of the $\pi$-germs of elements in $\mathfrak{F}(\pi)$. Inside of which the invertible $\pi$-germs form a group, denoted $\mathfrak{G}(\pi)$.

		Let $P' := \{ a \in P : a \models \pi|_{C}(x) \}$. 

	For every $a \in P'$, the $\pi$-germ $[F_a] := [F(a,x)]_{\pi}$ is invertible, in fact $[H_a] := [H(a,x)]_{\pi}$ is the two-sided inverse of $[F_a]$. Indeed, for any $a \models \pi|_{C}$ and $a_0 \models \pi|_{C,a}$, let $b := F(a,a_0)$, $b \models \pi|_{C,a}$ by by Definition \ref{defn: group chunk}(1). Then $a_0 = H(a, F(a,a_0))$ by Definition \ref{defn: group chunk}(2). So $ [H_a] \circ [F_a](a_0) = a_0$. Conversely, for any $a \models \pi|_{C}$, $B \supseteq C$ and $b \models \pi|_{B,a}$, there is some $a_0 \models \pi|_{B,a}$ with $b = F(a,a_0)$ (by Remark \ref{rem: pushforward sets of realiz}, as $(F_{a})_{\ast} \pi = \pi$). Again, $a_0 = H(a, F(a,a_0))$ (as $B \supseteq C$ was arbitrary, this shows in particular that $(H_a)_{\ast} \pi = \pi$), hence $[F_a] \circ [H_a] (b) = b$.

	Let $\mathfrak{G}_F(\pi)$ be the subgroup of $\mathfrak{G}(\pi)$ generated by the elements $\{[F_a] : a \in P'\}$ and their inverses. 

	The map $a \in P' \mapsto [F_a] \in \mathfrak{G}_{F}(\pi)$ is injective. Indeed, let $a,a' \in P'$ be such that $[F_a] = [F_{a'}]$. Let $b \models \pi|_{C, a, a'}$. Then by Definition \ref{defn: group chunk}(2), $a = K(b, F(a,b)) = K(b, F(a',b))  = a'$ (note that we are testing injectivity on a single realization of $\pi$).


\begin{claim*}
	Every element of $\mathfrak{G}_{F}(\pi)$ is of the form $[F_a] \circ [F_b]^{-1}$ for some $a,b \in P'$.
\end{claim*}
\begin{proof}
To see this, first we make the following two observations.
	\begin{enumerate}
	\item For any $a \models \pi|_{C}$, $D \supseteq C$ and $c \models \pi|_{D,a}$, there is some $b \models \pi|_{D,a}$ so that $[F_b] = [F_a] \circ [F_c]$.

		\item For any $a \models \pi|_{C}$, $D \supseteq C$ and $b \models \pi|_{D,a}$, there is some $c \models \pi|_{D,a}$ such that $[F_{a}]^{-1} \cdot [F_{b}] = [F_c]$.
		\end{enumerate}

For (1), let $b := F(a,c)$, $b \models \pi|_{D,a}$ by Definition \ref{defn: group chunk}(1). Let $e \models \pi|_{D, a,b,c}$ be arbitrary, then $(a,c,e) \models \pi^{\otimes 3}|_{C}$, and by Definition \ref{defn: group chunk}(3) we have $[F_{b}](e) = F(b,e) = F(F(a,c),e) = F(a, F(c,e)) = [F_a] \circ [F_c] (e)$, so $[F_b] = [F_a] \circ [F_c]$.

For (2), we have $F(a,b) \models \pi|_{D,a}$ (by Definition \ref{defn: group chunk}(1)). And there is $c \models \pi|_{D,a}$ such that $F(a,c) = b$ (by Definition \ref{defn: group chunk}(1) and Remark \ref{rem: pushforward sets of realiz}). Let $e \models \pi|_{D, a,b,c}$ be arbitrary. As $(a,c,e) \models \pi^{\otimes 3}|_{C}$, by Definition \ref{defn: group chunk}(3) we have $[F_b](e) = F(F(a,c), e) = F(a, F(c,e)) = [F_a] \circ [F_c] (e)$. Hence $[F_b] = [F_a] \circ [F_c]$, so $[F_{a}]^{-1} \cdot [F_{b}] = [F_c]$.


To prove the claim, first note that $[F_a]$ is of the required form for every $a \in P'$: by (1) there exist $b,c \models \pi|_{C}$ with $[F_b] = [F_a] \circ [F_c]$, hence $[F_a] = [F_b] \circ [F_c]^{-1}$. Then it suffices to show that $[F_a] \circ [F_b]^{-1} \circ [F_c] \circ [F_{d}]^{-1}$ has the required form for all $a,b,c,d \in P'$. Let $e_0 \models \pi|_{C,a,b,c,d}$. By (2) there is $e_1 \models \pi|_{C,a,b,c,d}$ with $[F_d]^{-1} \circ [F_{e_0}] = [F_{e_1}]$. By (1) there is $e_2 \models \pi|_{C,a,b,c,d}$ with $[F_c] \circ [F_{e_1}] = [F_{e_2}]$. By (2) there is $e_3 \models \pi|_{C,a,b,c,d}$ with $[F_{b}]^{-1} \circ [F_{e_2}] = [F_{e_3}]$, and by (1) there is $e_4 \models \pi|_{C,a,b,c,d}$ with $[F_a] \circ [F_{e_3}] = [F_{e_4}]$. It follows that $[F_a] \circ [F_b]^{-1} \circ [F_c] \circ [F_d]^{-1} \circ [F_{e_0}] = [F_{e_4}]$, hence $[F_a] \circ [F_b]^{-1} \circ [F_c] \circ [F_d]^{-1}  = [F_{e_4}] \circ [F_{e_0}]^{-1}$, as wanted.
\end{proof}






%	
%	. Indeed, given $a \models \pi|_{C}$, let $a_2 \models \pi|_{C, a}$ be arbitrary. Let $a_1 := F(a,a_2)$, then $a_1 \models \pi|_{C,a}$ by Definition \ref{defn: group chunk}(1). Let $b \models \pi|_{C, a, a_1, a_2}$ be arbitrary. Then by Definition \ref{defn: group chunk}(3) we have $[F_{a_1}](b) = F(a_1,b) = F( F(a, a_2), b) = F(a, F(a_2,b)) = [F_a] \circ [F_{a_2}] (b)$. This shows $[F_{a_1}] = [F_a] \circ [F_{a_2}]$, hence $[F_a] = [F_{a_1}] \circ [F_{a_2}]^{-1}$ as wanted.




	Using the claim, we can identify $\mathfrak{G}_{F}(\pi)$ with a hyperdefinable group. Let $Y := P' \times P'$, $F' := \{((a,b), (a',b')) \in Y^2 : [F_a] \circ [F_b]^{-1} = [F_{a'}] \circ [F_{b'}]^{-1}\}$. By $C$-type-definability of $\pi$, $F'$ is a $C$-type-definable equivalence relation on $Y$ (see Definition \ref{def: germs}) by 
	\begin{gather*}
		F((a,b), (a',b')) \iff
		 (d_{\pi} y) \Big( \exists u \exists v \exists u' \exists v' \\
		 \left(\Gamma_{H}(b,y,u) \land 
