	Note that the graph of $f$ is a $C$-type-definable subset of $ P \times G$ using type-definability of $\pi$ as above.

	For any $(a,b) \models \pi^{\otimes 2}|_{C}$, we have $c := F(a,b) \models \pi|_{C,a}$. For any $e \models \pi|_{C, a,b}$,  $[F_c](e) = F(F(a,b), e) = F(a,F(b,e)) = [F_a] \circ [F_b] (e)$, so $[F_c] = [F_a] \circ [F_b]$. This shows that $f(F(a,b)) = f(a) \cdot_{G} f(b)$.




Finally, given an arbitrary $D \supseteq C$, assume $g \models (f_{\ast} \pi)|_{C}$ and 	$h \models (f_{\ast} \pi)|_{D,g}$. By Remark \ref{rem: pushforward sets of realiz} there  exist $a \models \pi|_{C}$ with $f(a) = g$ and  $b \models \pi|_{D,g}$ with $f(b) = h$. As $f$ is injective on $\pi|_{C}$, $a \in \dcl^{\heq}(C, g)$, so $b \models \pi|_{D,a}$ (by Remark \ref{rem: realize over dcl heq}). Then $F(a,b) \models \pi|_{D,a}$ and $g \cdot h = f(a) \cdot f(b) = f(F(a,b))$, hence $g \cdot h \models (f_{\ast}\pi)|_{D,a}$, so $g \cdot h \models (f_{\ast}\pi)|_{D,g}$ (by Remark \ref{rem: realize over dcl heq} again). This implies that $g \cdot (f_{\ast}\pi) = f_{\ast}\pi$. And for an arbitrary $g \in G$ we have $g = g_1 \cdot g_2^{-1}$ for $g_1, g_2 \models (f_{\ast} \pi)|_{C}$. By Remark \ref{rem: translates of partial types} it follows that $g \cdot (f_{\ast}\pi) = f_{\ast}\pi$, as wanted.
\end{proof}

\begin{theorem}\label{thm: equiv of cats groups vs chunks}
	Let $G = (P, \cdot_G)$ and $H = (Q, \cdot_H)$ with $P = X/E, Q = Y/F$ be groups hyperdefinable over $C$. Let $\pi$ be a left-$G$-invariant partial type concentrating on $G$ and type-definable over $C$. Let $f: P \to Q$ be a $C$-type-definable partial function defined on $\pi|_{C}$ and such that for all $a \models \pi|_{C}, b \models \pi|_{C, a}$ we have $f(a \cdot_G b) = f(a) \cdot_H f(b)$. Then there exists a unique type-definable over $C$ group homomorphism $f': G \to H$ that agrees with $f$ on realizations of $\pi|_{C}$. Moreover, if $f$ is injective on $\pi|_{C}(\cU)$, then $f'$ is also injective.
\end{theorem}
\begin{proof}
	We follow closely the proof of \cite[Proposition 3.16]{hrushovski2019valued}, but provide some details.

	First note that $\pi|_{C}(\cU)$ generates $G(\cU)$, which clearly implies that there can only exist a unique group homomorphism extending $f$. Indeed, given $g \in G(\cU)$, let $e \models \pi|_{C,g}$ in $G(\cU)$. Then $g \cdot e \models \pi|_{C,g}$ by $G$-invariance of $\pi$. And $g = (g \cdot e) \cdot e^{-1}$. (Note that we do not claim that $a^{-1} \models \pi|_C$ --- this would follow if we assumed additionally that $\pi$ $\otimes$-commutes with itself.) 



		To show existence, for any $g \in G(\cU)$ we define $f'(g) := f(a) \cdot f(b)^{-1}$ for some $a,b \models \pi|_{C}$ with $g = a \cdot b^{-1}$. To show that $f'$ is well-defined, it suffices to show that for all $a,b,c,d \models \pi|_{C}$ with $a \cdot b^{-1} = c \cdot d^{-1}$ we have $f(a) \cdot f(b)^{-1} = f(c) \cdot f(d)^{-1}$. As $H$ is a group, it suffices to show that for any $e \models \pi|_{C, a,b,c,d}$ we have $f(a) \cdot f(b)^{-1} \cdot f(e) = f(c) \cdot f(d)^{-1} \cdot f(e)$. 
	In particular $e \models \pi|_{C,a,b,b^{-1}}$ (by Remark \ref{rem: realize over dcl heq}), hence $b^{-1} \cdot e \models \pi|_{C,a,b}$ by invariance of $\pi$. Then, by assumption on $f$, we have $f(e) = f( (b \cdot b^{-1}) \cdot e) = f( b \cdot (b^{-1} \cdot e)) = f(b) \cdot f(b^{-1} \cdot e)$, hence $f(b)^{-1} \cdot f(e) = f(b^{-1} \cdot e)$; and $f(a) \cdot f(b^{-1} \cdot e) = f(a \cdot b^{-1} \cdot e)$. So $f(a) \cdot f(b)^{-1} \cdot f(e) = f(a \cdot b^{-1} \cdot e)$.
	 Similarly, $f(d)^{-1} \cdot f(e) = f(d^{-1} \cdot e)$ and $f(c) \cdot f(d^{-1} \cdot e) = f(c \cdot d^{-1} \cdot e)$, so $f(c) \cdot f(d)^{-1} \cdot f(e) = f(c \cdot d^{-1} \cdot e)$. As $a \cdot b^{-1} \cdot e = c \cdot d^{-1} \cdot e$ by assumption, the required equality holds.

	 We show that $f'$ is a homomorphism. First, for any $g,h \in G(\cU)$ we have $f'(g \cdot h^{-1}) = f'(g) \cdot (f'(h))^{-1}$. Indeed, let $e \models \pi|_{C, g, h}$. Then, using definition of $f'$ and that $g\cdot e, h \cdot e \models \pi|_{C}$ by $G$-invariance of $\pi$, we have $f'(g) = f(g \cdot e) \cdot f(e)^{-1}$, $f'(h) = f(h \cdot e) \cdot f(e)^{-1}$ and $f'(g \cdot h^{-1}) = f'(g \cdot (e \cdot e^{-1}) \cdot h^{-1}) = f'((g \cdot e) \cdot (h \cdot e)^{-1}) = f( g\cdot e) \cdot f(h \cdot e)^{-1}$. Combining $f'(g) \cdot f'(h)^{-1} = f(g \cdot e) \cdot f(e)^{-1} \cdot f(e) \cdot f(h \cdot e)^{-1} = f'(g) \cdot f'(h)$. Second, we have $f'(g^{-1}) = f'(g)^{-1}$ for any $g \in G(\cU)$. Indeed, if $g = a \cdot b^{-1}$ for some $a,b \models \pi|_{C}$, then by definition of $f'$ we have $f'(g^{-1}) = f'( (a \cdot b^{-1})^{-1}) = f'(b \cdot a^{-1}) = f(b) \cdot f(a)^{-1} = \left(f(a) \cdot f(b)^{-1} \right)^{-1} = f'(a \cdot b^{-1})^{-1} = f'(g)^{-1}$. Finally, for any $g,h \in G(\cU)$ using these two remarks we have $f'(g \cdot h) = f'(g \cdot (h^{-1})^{-1}) = f'(g) \cdot f'(h^{-1})^{-1} = f'(g) \cdot (f'(h)^{-1})^{-1} = f'(g) \cdot f'(h)$.



	 Assume that $f$ is injective on $\pi|_{C}(\cU)$, and let $f'(a) = f'(b)$ for some $a,b \in G$. Let $e \models \pi|_{C, a, b}$, then $a = (a \cdot e) \cdot e^{-1}, b = (b \cdot e) \cdot e^{-1}$ and $f'(a) = f(a \cdot e) \cdot f(e)^{-1}, f'(b) = f
	 (b \cdot e) \cdot f(e)^{-1}$. Then $f(a \cdot e) = f(b \cdot e)$, so $a \cdot e = b \cdot e$ by injectivity of $f$, hence $a = b$. Hence $f'$ is injective as well.


	 Now for $C$-type-definability of $f'$. Given any $a \in G, b \in H$, let $e \models \pi|_{C,a,b}$ be arbitrary. Then $a = ( a \cdot e) \cdot e^{-1}$ and, 	 by definition of $f'$, $f'(a) = f(a \cdot e) \cdot f(e)^{-1}$. That is, $f'(a) = b$ if and only if $f(a \cdot_{G} e) = b \cdot_{H} f(e)$. In other words, if and only if
	  \begin{gather}
	 	\pi(x) \vdash \label{eq: explicit formula for group iso}\\ 
	 	\exists u, u', v, v' \Big( \Gamma_{\cdot_G}(a,x,u) \land \Gamma_f(u,u') \land \Gamma_f(x,v) \land \Gamma_{\cdot_H}(b, v, v') \land F(u',v') \Big) \nonumber,
	 \end{gather}
	where on the right we have a small partial type over $C$ (invariant with respect to $E,F$ in the relevant coordinates). By type-definability of $\pi$ over $C$, the set of pairs $(a,b) \in P \times Q$ for which this holds is type-definable over $C$.
\end{proof}

In particular this implies that the group $G$ in Theorem \ref{thm: hyperdef group chunk gives group} is unique, up to a type-definable isomorphism:
\begin{corollary}\label{cor: unique group from group chunk}
	Let $(\pi,F,H,K)$ be a group chunk over $C$ on $P$, and for $i \in \{1,2\}$ let $G_i$ be $C$-hyper-definable groups and $C$-type-definable partial functions $f_i: \pi \to G_i$ defined and injective on $\pi$, so that for any $(a,b) \models \pi^{\otimes 2}|_{C}$ we have $f_i(F(a,b)) = f_i(a) \cdot_{G} f_i(b)$ and the global partial type $(f_i)_{\ast} \pi$ concentrates on $G_i$ and is left-$G_i$-invariant. Then there is  $C$-type-definable group isomorphism $\iota: G_1 \to G_2$.
\end{corollary}
\begin{proof}



	By assumption $(f_i)_{\ast}\pi$ concentrates on $G_i$ and is left-$G_i$-invariant, and $C$-type-definable (Remark \ref{rem: pushfoward preserves type-def}). 
	By Remark \ref{rem: pushforward sets of realiz} and injectivity of $f_i$ on $\pi$, 	$g_1 := f_2 \circ f_1^{-1} : (f_1)_{\ast}\pi \to (f_2)_{\ast}\pi$ and $g_2 := f_1 \circ f_2^{-1} : (f_2)_{\ast}\pi \to (f_1)_{\ast}\pi$ are  $C$-type-definable injections with $g_1 \circ g_2 = \id_{(f_2)_{\ast}\pi}, g_2 \circ g_1 = \id_{(f_1)_{\ast}\pi}$; and for any $(a,b) \models ((f_i)_{\ast}\pi)^{\otimes 2}|_{C}$, $g_i(a \cdot_{G_i} b) = g_i(a) \cdot_{G_{3-i}} g_i(b)$. By Theorem \ref{thm: equiv of cats groups vs chunks}, there exist unique $C$-type-definable injective group homomorphisms $h_i: G_i \to G_{3-i}$ with $h_i \restriction_{(f_i)_{\ast}\pi } = g_i$. As (by Theorem \ref{thm: equiv of cats groups vs chunks}) $h_i \circ h_{3-i}$ is the unique  isomorphism of $G_i$ extending $g_i \circ g_{3-i}$, $h_i \circ h_{3-i} = \id_{G_{3-i}}$, hence $h_i: G_i \to G_{3-i}$ is a group isomorphism.
\end{proof}




\section{Externally definable fsg groups}\label{sec: Externally definable fsg groups}


\subsection{Type-definable filters associated to definable measures}\label{sec: Type-definable filters associated to definable measures}


\begin{definition}\label{def: pi mu}
	Assume that $\mu \in \mathfrak{M}_x(\cU)$ is a global Keisler measure. We define the partial type $\pi_{\mu} := \{ \varphi(x) \in \mathcal{L}_x(\cU) : \mu(\varphi(x)) = 1 \} = \{ \neg \varphi(x) \in \mathcal{L}_x(\cU) : \mu(\varphi(x)) = 0 \}$ (note that $\pi_\mu$ is closed under conjunction and implication). \end{definition}

\begin{remark}\label{rem: pi mu defines support}
	We have $S(\mu) = \{ p \in S_x(\cU) : \pi_{\mu} \subseteq p \}$ and for any $C \subseteq \cU$, $a \models \pi_{\mu}|_{C} \iff \tp(a/C) \in S(\mu|_{C})$.
\end{remark}

The following are straightforward adaptations of the usual notions from complete to partial types.
\begin{definition}\label{def: props of partial types}
Given $A \subseteq \cU$, a partial type $\pi(x)$ over $\cU$ is
\begin{enumerate}
\item \emph{invariant over $A$} if for every formula $\varphi(x,y)$ and $b \in \cU^y$, we have $\varphi(x,b) \in \pi \iff \varphi(x, \sigma(b)) \in \pi$.
	\item \emph{(type-)definable over $A$} if  for every formula $\varphi(x;y) \in L(\emptyset)$, the set $\{ b \in \cU^y : \varphi(x,b) \in \pi \}$ is (type-)definable over $A$.
	\item \emph{finitely satisfiable in $A$} if every formula $\varphi(x) \in \pi$ has a realization in $A$. And $\pi(x)$ is \emph{strongly finitely satisfiable in $A$} if for every $\varphi(x) \in L(\cU)$ such that $\varphi(A) = \emptyset$, $\neg \varphi(x) \in \pi$.
\end{enumerate}

\end{definition}

\begin{remark}
	Note that if $\pi(x)$ is a partial type over $\cU$ type-definable over $A$ and closed under implication, then viewed as a partial type on the home sort over $\cU^{\heq}$ (Remark \ref{rem: real partial type in heq}), it remains type-definable over $A$ in the sense of Definition \ref{def: def type hyperim}.
\end{remark}

\begin{remark}\label{rem: pi mu type-def for mu def}
If $\mu$ is invariant (definable, finitely satisfiable) over $A$, then  $\pi_\mu$ is invariant (type-definable, strongly finitely satisfiable) over $A$.  Indeed, if the measure  $\mu$ is definable over $A$, then for every formula $\varphi(x,y) \in L$, the set $\{b \in \cU^{y} : \mu( \varphi(x,b))=1\}$ is type-definable over $A$.
\end{remark}

\begin{lemma}\label{lem: props of pi mu}

	\begin{enumerate}
	\item If $\mu_x, \nu_y \in \mathfrak{M}(\cU)$ are definable measures, then $\pi_{\mu} \otimes \pi_{\nu} = \pi_{\mu \otimes \nu}$. In particular, if $\mu$ is generically stable then  $\pi_{\mu}$ commutes with itself.
	\item For $\mu \in \mathfrak{M}_x(\cU)$  and $f$ a definable map, we have $f_{\ast} \pi_{\mu} = \pi_{f_{\ast} \mu}$.
		\item If $G$ is a type-definable group and $\mu \in \mathfrak{M}_{G}(\cU)$, then $\pi_{\mu}(x) \vdash G(x)$. And if  $\mu$ is $G$-invariant, then $\pi_{\mu}$ is also $G$-invariant.
	\end{enumerate}

\end{lemma}
\begin{proof}
(1) Given a formula  $\varphi(x,y) \in L(\cU)$, let $M$ be a small model such that $\mu_x,\nu_y, \varphi(x,y)$ are $M$-definable. 
  By definition of $\otimes$, we have 
	$\varphi(x,y) \in \pi_{\left(\mu \otimes \nu \right)} \iff \mu \otimes \nu \left( \varphi(x,y) \right) = 1 \iff \int_{S(\mu|_{M})} F^{\varphi(x,y)}_{\nu, M} (p)  d \mu_{M} = 1$, where $\mu|_{M} \in \mathfrak{M}_x(M)$ is the restriction of $\mu$ to $M$, $S(\mu|_{M})$ is its support,  $\mu_M$ is the unique regular Borel probability measure extending $\mu$ on $S_x(M)$. As the function $F^{\varphi(x,y)}_{\nu, M}: p \in S_x(M) \mapsto \nu(\varphi(a,y)) \in [0,1]$ for some/any $a \models p$ is continuous by definability of $\nu$, this integral is $=1$ if and only if $F^{\varphi(x,y)}_{\nu, M}(p) = 1$ for all $p \in S(\mu|_M)$. That is, if and only if for every $a \models \pi|_{M} $ and $b \models \pi|_{M,a}$ we have $\models \varphi(a,b)$ (by Remark \ref{rem: pi mu defines support}); if and only if $\varphi(x,y) \in \pi_{\mu} \otimes \pi_{\nu}$ (by  Remark \ref{rem: prod of partial types realiz}).

	(2) Given $\varphi(x) \in L(\cU)$ and a definable map $f$, by Definition \ref{def: pushforward of types}, we have $\varphi(x) \in f_{\ast} \pi_{\mu} \iff \varphi(f(x)) \in \pi_{\mu} \iff \mu(\varphi(f(x))) = 1$, by Definition \ref{def: definable pushforward} $\iff f_{\ast} \mu(\varphi(x)) = 1 \iff \varphi(x) \in \pi_{(f_{\ast \mu})}$.

	(3) If $\mathfrak{M}_{G}(\cU)$, then by definition $\pi_{\mu}(x) \vdash G(x)$.  And assuming $\mu$ is $G$-invariant, for every $g \in G(\cU)$ we have (see Definition \ref{rem: translates of partial types}): 
	$g \cdot \pi_{\mu} = (t_g)_{\ast} \pi_{\mu} = \pi_{(t_g)_{\ast} \mu} = \pi_{g \cdot \mu} = \pi_{\mu}$ by (2), where $t_g: G \to G$ is the definable map $h \in G \mapsto g \cdot h$.
	\end{proof}

\begin{remark}
	In the context of Lemma \ref{lem: props of pi mu}(1), we have $S(\mu) \otimes S(\nu)$ is a dense subset of $S(\mu \otimes \nu)$ (similarly to \cite[Proposition 4.3]{chernikov2022definable}), and $\pi_{\mu}\otimes \pi_{\nu}$ is a partial type, hence corresponds to a closed set of types.
\end{remark}

\begin{remark}
In relation to Lemma \ref{lem: props of pi mu}(3), note that if $G$ is a (type-)definable group and $\mu \in \mathfrak{M}_{G}$ is a definable measure, then its (left) stabilizer $\Stab_{G}(\mu) = \{ g \in G(\cU) : g \cdot \mu = \mu \}$ (Definition \ref{def: stab of a measure}) is a type-definable subgroup of $G$ (Fact \ref{fac: stab of def meas type def}). Similarly, for a partial type $\pi(x) \vdash G(x)$, we can consider its (left) stabilizer $\Stab_{G}(\pi) = \{ g \in G(\cU) : g \cdot \pi = \pi \}$. Then, using Remark \ref{rem: pi mu defines support}, $\Stab_{G}(\mu) \subseteq \Stab_{G}(\pi_{\mu}) = \{g \in G(\cU) : g \cdot S(\mu) = S(\mu) \}$ is a subgroup of $G$ and $\pi_{\mu}$ is type-definable (Remark \ref{rem: pi mu type-def for mu def}), however $ \Stab_{G}(\pi_{\mu})$ need not be type-definable. 

Indeed, let $M$ be a countable strongly minimal expansion of a (necessarily abelian) group $G(M)$, $\cU \succ M$ a monster model. Consider the Keisler measure $\mu := \sum_{q \in M} \alpha_q \cdot \delta_{q}$ for some \emph{pairwise-distinct} $\alpha_q \in (0,1), \sum_{q \in M} \alpha_q = 1$, then $\mu \in \mathfrak{M}_{G}(\cU)$ is smooth (over $M$). Note that $S(\mu) = \{\tp(q/\cU) : q \in M\} \cup \{p\}$, where $p \in S_{G}(\cU)$ is the unique (by strong minimality) non-algebraic type. Note that $\Stab_{G}(\mu) = \{ 0 \}$: given any $g \in G(\cU) \setminus \{0\}$, take any $q \in M$, then  $0 < (g \cdot \mu)(x = q) = \mu(x = g^{-1} \cdot  q )$,  and as $g^{-1} \cdot q \neq q$ we conclude $(g \cdot \mu)(x = q) \neq \mu(x = q)$ using that $\alpha_q$ are pairwise distinct.  And $\pi_{\mu} = \{ \varphi(x) \in L(\cU) : \models \bigwedge_{q \in M} \varphi(q) \}$, hence  $M \subseteq \Stab_G (\pi_{\mu}) $ as $M$ is a subgroup. In fact,  $M = \Stab_G (\pi_{\mu}) $: given any $g \in G(\cU) \setminus M$ and $q \in M$, $g \cdot q \notin M$, hence  $\mu(x \neq g \cdot q) = 1$. But $g \cdot \mu( x \neq g \cdot q) = \mu( g \cdot x \neq g \cdot q) = \mu(x \neq q) \leq 1 - \alpha_q < 1$. In particular $\Stab_G (\pi_{\mu})$ is not type-definable, as a countable subset of $\cU$.
\end{remark}




\begin{corollary}\label{cor: measure theoretic group chunk}
Let $T$ be NIP, $G$ an $M$-type-definable group, and $\mu \in \mathfrak{M}_{G}(\cU)$ an $M$-definable left-invariant measure (such $M$ and $\mu$ exist  whenever $G$ is a definably amenable NIP group, Fact \ref{fac: def am def measure}). Then $G$ can be recovered, up to an $M$-type-definable isomorphism of $M$-hyperdefinable groups in $\cU^{\heq}$, from its $M$-type-definable group chunk $(\pi_{\mu}, F,H,K)$ (Remark \ref{rem: group chunk from a group}).
\end{corollary}
\begin{proof}
	The partial type $\pi_{\mu}$ concentrates on $G$, is type-definable over $M$ (Remark \ref{rem: pi mu type-def for mu def}) and is left $G$-invariant (Lemma \ref{lem: props of pi mu}). Then Theorems \ref{thm: hyperdef group chunk gives group} and Corollary \ref{cor: unique group from group chunk} apply.
\end{proof}


\begin{proposition}\label{prop: fsg iff invariant filter str fin sat}
	($T$ NIP) Assume $G(x)$ is a type-definable group over $M$ and $\pi(x)$ is a filter over $\cU$ so that $\pi(x) \vdash G(x)$, $\pi$ is left-$G(\cU)$-invariant and strongly finitely satisfiable in $G(M)$. Then $G$ is fsg and $\pi = \pi_\mu$ for the unique left-invariant measure $\mu \in \mathfrak{M}_G(\cU)$. 
\end{proposition}
\begin{proof}
	Let $p \in S_{G}(\cU)$ be a complete type extending $\pi$, by $G(\cU)$-invariance of $\pi$ we have $g \cdot p \supseteq \pi$ for every $g \in G(\cU)$. By strong finite satisfiability of $\pi$ in $G(M)$ every type extending $\pi$ is finitely satisfiable in $G(M)$, hence $p$ witnesses that $G$ is fsg (over $M$). 
		In particular $p$ is generic. Let $\mu$ be the unique left and right-invariant measure on $G$ (Fact \ref{fac: fsg groups basic props}). As $S(\mu) = \overline{G \cdot p}$ (by \cite[Theorem 3.36, Remark 3.37, Proposition 3.31]{chernikov2018definably}), we get $p'(x) \vdash \pi(x)$ for every $p' \in S(\mu)$. Hence $\pi \subseteq \pi'_{\mu}$. 
		Conversely, assume $\varphi(x) \in \pi_{\mu}$. Then $\mu(\neg \varphi(x)) = 0$, so $\neg \varphi(x)$ is not right generic (by right-invariance of $\mu$). Hence $\neg \varphi(g \cdot x) \cap G(M) = \emptyset$ for some $g \in G(\cU)$. (Indeed, assume $X$ is (relatively) definable and $g \cdot X \cap G(M) \neq \emptyset$ for all $g \in G(\cU)$. It follows by compactness that there are $n \in \omega$ and $h_i \in G(M), i \in [n]$ so that for every $g \in G(\cU)$, $h_i \in g \cdot X$ for some $i \in [n]$. Then, given any $g \in G(\cU)$, $h_i \in g^{-1} \cdot X$ for some $i \in [n]$, hence $g \in  X \cdot h_i^{-1}$. This shows that $X$ is right generic.)
		Hence $\varphi(g \cdot x) \in \pi$ by strong finite satisfiability of $\pi$, hence $\varphi(x) \in \pi$ by left-$G(\cU)$-invariance of $\pi$.

	Conversely, if $G$ is fsg over $M$ witnessed by $\mu$, then $\pi_{\mu}$ is strongly finitely satisfiable ($\varphi(M) = \emptyset$ implies $\mu(\varphi(x)) = 0$, so $\mu(\neg \varphi(x)) = 1$) and $G(\cU)$-invariant.
\end{proof}



\subsection{An eliminable hyperdefinable group in a reduct}\label{sec: eliminable hyper-def group}

We show that if a hyperdefinable group is type-definably isomorphic to a definable group in some expansion of the theory, it is already definable in $\cU^{\eq}$:

\begin{proposition}\label{prop: elim hyperdef group}
	Let $T \subseteq T'$ be complete theories and $\cU \models T'$ a monster model. Let $H = (X,\gamma(x,y,z))$ be a definable group in $T'$, $G = (Y/F, \Gamma(x,y,z))$ a hyperdefinable group in $T$ (with $Y$ a partial type in finitely many variables), and assume $\iota(x,y)$ is a type-definable in $T'$ isomorphism between $H(\cU)$ and $G(\cU)$, all over a small set of real parameters $C \subseteq \cU$. Then there is a group $G_0$ definable over $C$ in $T^{\eq}$ and a $C$-definable in $T'$ isomorphism $\iota'$ between $H$ and $G_0$.  
\end{proposition}

\begin{proof}
	Without loss of generality $F(x,y)$ is a $C$-type-definable in $T$ equivalence relation on the whole universe $\cU^x$, $\Gamma(x,y,z) \vdash Y(x) \land Y(y) \land Y(z)$ is $C$-type-definable in $T$ and $F$-invariant in every coordinate, i.e.
	$$\Gamma(x,y,z) \land F(x,x') \land F(y,y') \land F(z,z') \vdash \Gamma(x',y',z'),$$
	and $\iota(x,y) \vdash X(x) \land Y (y)$ is $C$-type-definable in $T'$ and $F$-invariant on $y$, i.e.~$\iota(x,y) \land F(y,y') \vdash \iota(x,y')$.

	As $\iota$ in particular defines an injection from $X$ to $Y/F$, $\iota(x,y) \land \iota(x',y) \vdash x = x'$, then by compactness there is finite $\iota_0 \subseteq \iota$ so that  
	\begin{gather}
		\iota_0(x,y) \vdash X(x) \textrm{ and } \iota_0(x,y) \land \iota_0(x',y) \vdash x = x'.\label{eq: elim hyperdef 1}
	\end{gather}
	As $\iota$ in particular defines a surjection from $X$ onto $Y/F$, we have 
 	\begin{gather}
		Y(y') \vdash \exists x \  \iota (x,y'). \label{eq: elim hyperdef 2}
	\end{gather}

	We claim that the equivalence
	\begin{gather}
		\left( \iota_0(x,y) \land Y(y) \right) \leftrightarrow \iota(x,y)\label{eq: elim hyperdef 3}
	\end{gather}
	of partial types holds. 
	Right to left is by the choice of $\iota$ and $\iota_0$. Conversely, assume  that $\iota_0(x,y) \land Y(y) $ holds. By \eqref{eq: elim hyperdef 2}, $Y(y) \vdash \exists x' \iota(x',y)$. And by  \eqref{eq: elim hyperdef 1}, $\iota_0(x,y) \land \iota(x',y) \vdash x = x'$, so combining we get that $\iota(x,y)$ holds.

	Again, as $\iota$ is $F$-invariant on $y$ and defines a bijection between $X$ and $Y/F$, we have (using \eqref{eq: elim hyperdef 3} for the second part):
	\begin{gather*}
		Y(y_1) \land Y(y_2)  \land F(y_1,y_2) \vdash \exists x \left( \iota(x,y_1) \land \iota(x,y_2) \right) \vdash \exists x( \iota_0(x,y_1) \land \iota_0(x,y_2)),\\
	\textrm{ and }	Y(y_1) \land Y(y_2)  \land \exists x( \iota_0(x,y_1) \land \iota_0(x,y_2)) \vdash \\ \vdash 	Y(y_1) \land Y(y_2)  \land (\exists x \left( \iota(x,y_1) \land \iota(x,y_2) \right) \vdash F(y_1,y_2).
	\end{gather*}
	By compactness this implies that there is some finite $F_0 \subseteq F$ so that 
	\begin{gather}
		Y(y_1) \land Y(y_2) \vdash F(y_1, y_2) \leftrightarrow F_0(y_1,y_2). \label{eq: elim hyperdef 4}
	\end{gather}


	Similarly, using that $\iota$ defines a group isomorphism and assumption on $\Gamma$, the following partial types are equivalent:
	\begin{gather*}
		 \Gamma(y_1,y_2, y_3) \leftrightarrow \Big( Y(y_1) \land Y(y_2) \land Y(y_3) \land \\
		 \exists x_1, x_2, x_3 \  \left( \iota(x_1, y_1) \land \iota(x_2, y_2) \land \iota (x_3, y_3) \land \gamma(x_1,x_2,x_3) \right) \Big).
		\end{gather*}
	By \eqref{eq: elim hyperdef 3} we then have 
	\begin{gather*}
		 \Gamma(y_1,y_2, y_3) \leftrightarrow \Big( Y(y_1) \land Y(y_2) \land Y(y_3) \land \\
		 \exists x_1, x_2, x_3 \  \left( \iota_0(x_1, y_1) \land \iota_0(x_2, y_2) \land \iota_0 (x_3, y_3) \land \gamma(x_1,x_2,x_3) \right) \Big).
		\end{gather*}

	By compactness this implies that there is some finite $\Gamma_0 \subseteq \Gamma$ so that 
	\begin{gather}
		Y(y_1) \land Y(y_2) \land Y(y_3) \vdash \Gamma(y_1, y_2, y_3) \leftrightarrow \Gamma_0(y_1,y_2, y_3). \label{eq: elim hyperdef 5}
	\end{gather}


	By assumption on $F$ and $\Gamma$, \eqref{eq: elim hyperdef 4}
 and \eqref{eq: elim hyperdef 5} we have
	\begin{gather*}
		Y(y_1) \land Y(y_2) \land Y(y_3) \vdash \Big( F_0(y_1,y_1) \land \left( F_0(y_1, y_2) \rightarrow F_0(y_2,y_1) \right) \land  \\
		\left( F_0(y_1, y_2) \land F_0(y_2, y_3) \rightarrow F_0(y_1, y_3) \right) \land \left( \exists x \  \iota_0(x,y_1) \right) \land \\
		\left( \forall x  \ (\iota_0(x,y_1) \land \iota_0(x,y_2) \rightarrow F_0(y_1, y_2)) \right) \land\\
		 \big( \Gamma_0(y_1, y_2, y_3) \leftrightarrow \\
		 \exists x_1, x_2, x_3 \left( \iota_0(x_1, y_1) \land \iota_0(x_2,y_2) \land \iota_0(x_3, y_3) \land \gamma(x_1,x_2,x_3) \right) \big)\Big).
	\end{gather*}

	By compactness there is some finite $Y_0 \subseteq Y$ so that $F_0$ defines an equivalence relation on $Y_0(\cU)$, $\iota_0(x,y)$ (also using \eqref{eq: elim hyperdef 1}) defines a bijection between $X$ and $Y_0/F_0$, and for any $x_i \in X$ and $y_i \in Y_0$ with $\models \iota_0(x_i,y_i)$  we have $\gamma(x_1,x_2,x_3) \leftrightarrow \Gamma_0(y_1, y_2, y_3)$. Hence $G_0 := (Y_0/F_0, \Gamma_0)$ is a $C$-definable group in $T^{\eq}$ and $\iota_0$ is a $C$-definable in $T'$ isomorphism between the groups $H$ and $G_0$.
\end{proof}

\subsection{Externally definable fsg groups are isomorphic to definable ones}
\label{sec: Externally definable fsg groups are isomorphic to definable ones}
First we give an example of an externally definable fsg (and even generically stable group) in an NIP theory that is not definable.

\begin{example}\label{ex: ext def fsg not def}
	Let $\cU = (K,\Gamma,k)$ be a monster model of the theory of algebraically closed fields.


	Let $G := (K,+)$ be the additive group of the field. For $a \in K$, $\alpha \in \Gamma$ and $\square \in \{\geq, >\}$, let $B_{\square \alpha}(a) := \{ x \in K : v(x-a) \square \alpha \}$ be the closed (respectively, open) valuational ball of radius $\beta$ with center $b$. Given a ball $B_{\square \alpha}(a)$, by quantifier elimination in $\ACVF$, density of $\Gamma$ and the fact that for any two balls, either one is contained in the other or they are disjoint, the set of formulas 
	\begin{gather*}
		\{ x \in B_{\square \alpha}(a)\} \cup \{ x \notin B_{\square \beta}(b) : b \in K, \beta \in \Gamma, B_{\square \beta}(b) \subsetneq B_{\square \alpha}(a) \}
	\end{gather*}
	determines a complete type $p_{\square \alpha, a}(x) \in S_G(\cU)$, called the generic type of $B_{\square \alpha}(a)$. 

	Fix some $\alpha \in \Gamma$ and let $B := B_{\geq \alpha}(0)$ and $p := p_{\geq \alpha, 0}$. For any $a,b \in K$ we have $a + B_{\square \beta}(b) = B_{\square \beta}(a+b)$, hence for any $b \in B$ we have $b + B = B$, and if $B' \subsetneq B$ then $b + B' \subsetneq B$ for any ball $B'$. It follows that $B$ is a subgroup of $G(\cU)$ and $p \in S_B(\cU)$ is left-$B(\cU)$-invariant. Moreover, $p$ is generically stable over any $a \in K$ with $v(a) = \alpha$ (as it is internal to the residue field; or can see directly that $p$ commutes with itself), hence $B$ is a generically stable group.


	 Choose a small model $M \prec \cU$ with $\Gamma^M \cong (\mathbb{Q}, +, <)$ and $\alpha := 1 \in \Gamma^M$. Then $B(M)$ is an infinite (by density of $\Gamma^M$) group definable in $M$ and $p$ is generically stable over $M$, hence $B(M)$ is also a generically stable group in $\Th(M^{\Sh})$ (by Fact \ref{fac: group props preserved in Sh exp}). Then $X := B_{> \sqrt 2}(0) \cap M$ is an externally definable subset of $M$, $X \subsetneq B(M)$, but it is not definable in $M$ (as by quantifier elimination, every definable subset of $M$ is a Boolean combination of balls with parameters in $M$).
	Let $Y \subseteq (K^M)^2$ be  the $M^{\Sh}$-definable set
	 \begin{gather*}
	 	Y := \{ (0,x) :  x \in X \} \cup \{ (1,x) :  x \in B(M) \setminus X \}.
	 \end{gather*}
	 We equip it with an $M^{\Sh}$-definable group operation by copying it from $B$: for $(t_1,a_1), (t_2,a_2), (t_3,a_3) \in Y$, we define $(t_1,a_1) +_Y (t_2,a_2) = (t_3,a_3)$ if 
	 \begin{gather*}
	 	\left(\bigwedge_{i=1}^3 (t_i = 0 \land a_i \in X) \lor (t_i =1 \land a_i \in B(M) \setminus X) \right) \land (a_1 + a_2 = a_3).
	 \end{gather*}

	Then $(Y, +_Y)$ is $M^{\Sh}$-definably isomorphic to $(B(M), +)$ via an isomorphism $f$ defined by
	\begin{gather*}
		f((t,a)) = b :\iff a = b \land \left( ( a \in X \land t = 0) \lor (a \in B(M) \setminus X \land t = 1) \right).
	\end{gather*}

	But $Y$ is not definable in $M$ as then $X$ would be definable in $M$ via $X = \{ a \in K^M : (0,a) \in Y\}$.
	 \end{example}

\begin{remark}
	Similarly, we can find an externally definable fsg group in an $o$-minimal structure which is not definable --- take the circle group, and split it into two externally definable, non-definable intervals.
\end{remark}

We show that this is the only obstruction:

\begin{theorem}\label{thm: ext def fsg groups is to definable}
		Let $T$ be NIP and $M \models T$. Then a group definable in $M^{\Sh}$ is fsg (in the sense of $\Th(M^{\Sh})$) if and only if it is definably (in $M^{\Sh}$) isomorphic to a group definable in $M^{\eq}$ and fsg in $T$.
\end{theorem}

\begin{proof}
One direction is by Fact \ref{fac: group props preserved in Sh exp},  Remark \ref{rem: def iso preserves fsg} and the fact that every subset of the main sort definable in $(M')^{\eq}$ is already definable in $M'$. We prove the other direction.

We are following the notation in Definition \ref{def: Shelah exp context}, in particular we have $(N,M) \prec^{L_P} (N',M') \prec^{L_P} (N'', M'')$ with each pair saturated over the previous one, and $\widetilde{M}'$ is a monster model for $T' = \Th_{L'}(M^{\Sh})$.

Let $G' = G(M')$ be an $M$-definable fsg group, both in the sense of the $L'$-theory $T' := \Th \left(M^{\Sh} \right)$. Let $\cdot_{G'}$ be given by the partial $L'(M)$-definable function $F'(x,y)$ restricted to $G'(M')$, let $\Gamma_{F'}(x,y,z) \in L'(M)$ denote the graph of $F'$. We may assume that $\Gamma_{F'}(x,y,z)$ defines the graph of a partial function from any two of its coordinates to the third one.

By Proposition \ref{prop: fsg iff inv gen stab meas} and Fact \ref{fac: fsg groups basic props} (as $T'$ is NIP by Fact \ref{fac: Sh exp qe}), there is $\bar{\mu}' \in \mathfrak{M}^{L'}_{G'}(M')$ generically stable over $M$ (in $T'$) and such that $g \cdot \bar{\mu}' = \bar{\mu}'$ for all $g \in G'(\cU')$. 
Let $\bar{\nu}'(x,y,z) := h_{\ast} \left( (\bar{\mu}')^{\otimes 2} \right) \in \mathfrak{M}^{L'}_{(G')^{3}}(M')$ for the $L'(M)$-definable (partial) map $h: (x,y) \mapsto (x,y,x \cdot_{G'} y)$. Note that $\bar{\nu}'$ is generically stable over $M$ in $T'$ (by Fact \ref{fac: pushforward gen stab}).

Let $\bar{\mu} := \bar{\mu}'|_{L} \in \mathfrak{M}_{x}^L(M')$. By Proposition \ref{prop: properties of reducts of measures}, $\bar{\mu}$ is generically stable over $M$ (in $T$); and by Lemma \ref{lem: unique extension of def meas to Sh}, $\bar{\mu}'$ is the unique extension of $\bar{\mu}$ to a measure in $\mathfrak{M}_{x}^{L'}(M')$. Let $\bar{\nu} := \bar{\nu}'|_{L} \in \mathfrak{M}_{x,y,z}^L(M')$. Similarly, $\bar{\nu}$ is generically stable over $M$ in $T$, and $\bar{\nu}'$ is its unique extension to a measure in $\mathfrak{M}_{x,y,z}^{L'}(M')$.


Let $M_0 := M$, $N_0 := N$. Applying Fact \ref{fac: honest defs} repeatedly, we can choose $(N_i,M_i)$ by induction on $i \in \omega$ so that: 
\begin{itemize}
	\item $(N_i,M_i) \preceq^{L_P} (N_{i+1},M_{i+1}) \preceq^{L_P} (N',M')$,
	\item  $|M_{i+1}| + |N_{i+1}| \leq |N_i|+|L|$,
	\item for every $\varphi(x,y) \in L$ and $c \in N^y_{i}$ there is $\theta(x,z) \in L$ and $d \in M^{z}_{i+1}$ so that 
\begin{itemize}
\item $\theta(x,d) \land P(x) \vdash \varphi(x,c)$, and
\item no $p \in S^L_x(M')$ invariant over $M_i$ (in $T$) is consistent with $(\varphi(x,c) \setminus \theta(x,d)) \land P(x)$ (in $(N',M')$).
\end{itemize}
\end{itemize}

We let $M_{\omega} := \bigcup_{i \in \omega} M_i$, $N_{\omega} := \bigcup_{i \in \omega} N_i$. By construction it follows:
\begin{itemize}
	\item $(N,M) \preceq^{L_P} (N_{\omega}, M_{\omega}) \preceq^{L_P} (N',M')$ (in particular $M \prec^{L'}  M_{\omega} \prec^{L'} M'$),
	\item $|N_{\omega}|+|M_{\omega}| \leq |N|$ (in particular  $\widetilde{M}'$ is still $|M_{\omega}|^{+}$-saturated),
	\item for every $\varphi(x,y) \in L$ and $c \in N^y_{\omega}$ there is $\theta(x,z) \in L$ and $d \in M^{z}_{\omega}$ so that 
\begin{itemize}
\item $\theta(x,d) \land P(x) \vdash \varphi(x,c)$, and
\item no $p \in S^L_x(M')$ invariant over $M$ (in $T$) is consistent with $(\varphi(x,c) \setminus \theta(x,d)) \land P(x)$ (in $(N',M')$).
\end{itemize}

\end{itemize}

We let $\pi_{\bar{\mu}'}$ and $\pi_{\bar{\nu}'}$ be the partial types over $M'$ in $T'$ (as in Definition \ref{def: pi mu}), they are type-definable over $M$ (in $T'$; Definition \ref{def: props of partial types}), using definability of $\bar{\mu}', \bar{\nu}'$ (Remark \ref{rem: pi mu type-def for mu def}); and $\pi_{\bar{\mu}'}|_{M}(x) \vdash G'(x)$. Similarly, $\pi_{\bar{\mu}}$ and $\pi_{\bar{\nu}}$ are partial types over $M'$, type-definable over $M$ in $T$, and $\pi_{\bar{\mu}} = \pi_{\bar{\mu}'} \restriction_{L}$ and $\pi_{\bar{\nu}} = \pi_{\bar{\nu}'}\restriction_{L}$. Conversely, we have:

\begin{claim}\label{cla: pi mu implies pi mu'}
 $\pi_{\bar{\mu}}|_{M_{\omega}}(x) \vdash \pi_{\bar{\mu}'}|_{M_{\omega}} (x) $, $\pi_{\bar{\nu}}|_{M_{\omega}}(x,y,z) \vdash \pi_{\bar{\nu}'}|_{M_{\omega}} (x,y,z) $ and $\pi_{\bar{\mu}^{\otimes n}}|_{M_{\omega}}(x) \vdash \pi_{(\bar{\mu}')^{\otimes n}}|_{M_{\omega}}(x)$ for all $n \in \omega$ (in $T'$).
\end{claim}
\begin{proof}
Assume $\varphi(x) \in L'(M_{\omega})$ is such that $\varphi(x) \in \pi_{\bar{\mu}'}|_{M_{\omega}}$. We have $\varphi(x) \leftrightarrow^{T'} R_{\psi(x,y_1;d_2)}(x,d_1)$ for some $\psi(x,y_1,y_2) \in L, d_2 \in N, d_1 \in M_{\omega}$ (Remark \ref{rem: Shelah QE formulas}). And, by definition of $\widetilde{M}'$, $(N',M') \models R_{\psi(x,y_1;d_2)}(x,y_1) \leftrightarrow (P(x) \land P(y_1) \land \psi(x,y_1;d_2))$. 
By the choice of $M_{\omega}$ there is some $\theta(x; z) \in L$ and $e \in M_{\omega}^{z}$ so that $(N',M') \models (\theta(x,e) \land P(x)) \rightarrow \psi(x, d_1, d_2)$ and no $p \in S^L_x(M')$ invariant over $M$ (in $T$) is consistent with $(\psi(x,d_1,d_2) \setminus \theta(x,e)) \land P(x)$. So $\theta(x,e) \vdash \varphi(x)$  and no $p \in S^L_x(M')$ invariant over $M$ (in $T$) is consistent with $\varphi(x) \setminus \theta(x,e)$, both in $T'$.


Let $\bar{p}' \in S(\bar{\mu}')$ be arbitrary. Then $\bar{p}:= \bar{p}'\restriction_{L} \in S(\bar{\mu})$. The measure $\bar{\mu}$ is $M$-invariant in $T$ (by generic stability over $M$), hence $\bar{p} \in S(\bar{\mu})$ is also $M$-invariant in $T$ (by Fact \ref{fac: types in sup of inv meas are inv NIP}). It follows that  $(\varphi(x) \setminus \theta(x,e)) \notin p'$. Hence $\bar{\mu}' \left( \varphi(x) \setminus \theta(x,e) \right) = 0$, so $\bar{\mu}'(\theta(x,e)) = \bar{\mu}(\theta(x,e)) = 1$, so $\theta(x,e) \in \pi_{\bar{\mu}}|_{M_{\omega}}$.

Note that the argument applies to any measure in $T'$ generically stable over $M$, in particular to $(\bar{\mu}')^{\otimes n}, n \in \omega$ and $\bar{\nu}'$.
\end{proof}

Note that $\Gamma_{F'}(x,y,z) \in \pi_{\bar{\nu}'}|_{M_{\omega}}$. Indeed, by definition of pushforward  measure $\bar{\nu}'(\Gamma_{F'}(x,y,z)) =  (\bar{\mu}')^{\otimes 2}  (\Gamma_{F'}(h(x,y))) = (\bar{\mu}')^{\otimes 2}  (\Gamma_{F'}(x,y, x \cdot_{G'} y)) \geq (\bar{\mu}')^{\otimes 2}(H(x) \land H(y)) = 1$.
Then, by Claim \ref{cla: pi mu implies pi mu'}, there is some $L(M_{\omega})$-formula $\Gamma(x,y,z) \in \pi_{\bar{\nu}}|_{M_{\omega}}$ so that $\Gamma(x,y,z) \vdash \Gamma_{F'}(x,y,z)$ (in $T'$). From this and assumption on $\Gamma_{F'}$, we still have that $\Gamma(x,y,z)$ defines (in $T$) the graph of a partial function from any two of its coordinates to the third one. We consider the partial $L(M)$-definable (in $T$) functions $F$ with graph defined by $\Gamma_{F}(x,y,z) := \Gamma(x,y,z)$, $H$ with $\Gamma_{H}(x,y,z) := \Gamma(x,z,y)$ and $K$ with $\Gamma_{K}(x,y,z) := \Gamma(z,x,y)$.

