\begin{claim}\label{cla: proof of group chunk in the reduct}
We claim that $\left( \pi_{\bar{\mu}}(x), F, H,K \right)$ 	is a group chunk over $M_{\omega}$ in $T$, in the sense of Definition \ref{defn: group chunk} (on the home sort).
\end{claim}
\begin{proof}
We already know that $\pi_{\bar{\mu}}(x)$ is a partial type over $M'$ closed under implication and type-definable over $M_{\omega}$, all in $T$.


By Lemma \ref{lem: props of pi mu} we have $(\pi_{\bar{\mu}})^{\otimes 2} = \pi_{({\bar{\mu}}^{\otimes 2})}$ and $(\pi_{\bar{\mu}'})^{\otimes 2} = \pi_{((\bar{\mu}')^{\otimes 2})}$. By Claim \ref{cla: restriction commutes with tensor} we have $(\bar{\mu}')^{\otimes 2} \restriction_{L} = (\bar{\mu}' \restriction_{L})^{\otimes 2}  = \bar{\mu}^{\otimes 2}$.
So, using Claim  \ref{cla: pi mu implies pi mu'},
$$\pi_{\bar{\mu}}^{\otimes 2}|_{M_{\omega}} = \pi_{({\bar{\mu}}^{\otimes 2})} |_{M_{\omega}}  \vdash \pi_{((\bar{\mu}')^{\otimes 2})}|_{M_{\omega}} = \pi_{\bar{\mu}'}^{\otimes 2}|_{M_{\omega}}.$$

Now if $(a,b) \models \pi_{\bar{\mu}}^{\otimes 2}|_{M_{\omega}}$, then $(a,b) \models \pi_{((\bar{\mu}')^{\otimes 2})} |_{M_{\omega}} = \pi_{\bar{\mu}'}^{\otimes 2}|_{M_{\omega}}$, in particular $a, b \in G'(M')$. By Lemma \ref{lem: props of pi mu},  $h_{\ast}\left( \pi_{(\bar{\mu}')^{\otimes 2}} \right) =  \pi_{h_{\ast}((\bar{\mu}')^{\otimes 2})} = \pi_{\bar{\nu}'}$, it follows (Remark \ref{rem: pushforward sets of realiz}) that $h(a,b) = (a,b, a \cdot_{G'} b) \models \pi_{\bar{\nu}'}|_{M_{\omega}}$. As $\Gamma(x,y,z) \in \pi_{\bar{\nu}}|_{M_{\omega}} \subseteq \pi_{\bar{\nu}'}|_{M_{\omega}}$, in particular $\models \Gamma(a,b, a \cdot_{G'} b)$. This shows that the partial function
\begin{gather}
	F \textrm{ is defined on } \pi_{\bar{\mu}}^{\otimes 2}|_{M_{\omega}} \textrm{ and agrees with  } \cdot_{G'} \textrm{ on it.}\label{eq: main thm proof 1}
\end{gather}

As $\models \Gamma(a,b, a \cdot_{G'} b)$, by definition of $H$ we have $\models \Gamma_H(a, a \cdot_{G'} b, b)$ and $F(a,b) = a \cdot_{G'} b$, so $H$ is defined on $(a, F(a,b))$ and $H(a,F(a,b)) = b$.
Similarly, by definition of $K$ we have $\models \Gamma_K(b, a \cdot_{G'} b, a)$, so $K$ is defined on  $(b, F(a,b))$ and $K(b, F(a,b)) = a$.

Given any $a \models \pi_{\bar{\mu}}|_{M_{\omega}}$, by the above  the partial map $F_a: b \mapsto F(a,b)$ is defined on $\pi_{\bar{\mu}}|_{M_{\omega},a}$, and for any $b \models \pi_{\bar{\mu}}|_{M_{\omega},a}$, $F_a(b) = a \cdot_{G'} b$. We have $(F_{a})_{\ast} \pi_{\bar{\mu}'} = \pi_{\bar{\mu}'}$. Indeed, take any $D \supseteq M \cup \{a\}$, let $b \models \pi_{\bar{\mu}'}|_{D}$. Then $(F_{a})(b) = F(a,b) = a \cdot_{G'}b \models \pi_{\bar{\mu}'}|_{D}$ by $G'$-invariance of $\pi_{\bar{\mu}'}$.
%
%
%Then both partial maps $F_a$ and $t_a: b \mapsto a \cdot_{G'} b$ are defined on $\bar{\mu}'$ and have the same germ on $\bar{\mu}'$ (as $\pi_{\bar{\mu}}|_{M_{\omega},a}(x) \vdash \exists u \Gamma_{F}(a,x,u) \land \Gamma_{F'}(a,x,u)$, so $\bar{\mu}'(\exists u \Gamma_{F}(a,x,u) \land \Gamma_{F'}(a,x,u)) = 1$), hence $(F_a)_{\ast} \bar{\mu}' = (t_a)_{\ast} \bar{\mu}' = a \cdot \bar{\mu}' = \bar{\mu}'$ (by $G'$-invariance of $\bar{\mu}'$ and Remark \ref{rem: measure push-forward for germs}). Hence $(F_a)_{\ast} \bar{\mu} = (F_a)_{\ast} (\bar{\mu}' \restriction_{L}) = ((F_a)_{\ast} \bar{\mu}') \restriction_{L}) =   \bar{\mu}' \restriction_{L}) = \bar{\mu}$, so  $(F_a)_{\ast} \pi_{\bar{\mu}} = \pi_{(F_a)_{\ast} \bar{\mu}} = \pi_{\bar{\mu}}$.
Hence we have $(F_a)_{\ast} \pi_{\bar{\mu}} = (F_a)_{\ast} (\pi_{\bar{\mu}'}\restriction_{L}) =  ((F_a)_{\ast} \pi_{\bar{\mu}'})\restriction_{L} = (\pi_{\bar{\mu}'})\restriction_{L} = \pi_{\bar{\mu}}$.

Finally, assume $(a,b,c) \models \pi_{\bar{\mu}}^{\otimes 3}|_{M_{\omega}} \vdash \pi_{\bar{\mu}'}^{\otimes 3}|_{M_{\omega}}$ (by Claim \ref{cla: pi mu implies pi mu'}). In particular, $a,b,c \in G'(M')$. First, $(b,c) \models \pi_{\bar{\mu}'}^{\otimes 2}|_{M_{\omega}, a}$, so $F(b,c) = b \cdot_{G'} c \models \pi_{\bar{\mu}'}|_{M_{\omega},a,b}$ by $G'$-invariance of $\pi_{\bar{\mu}'}$. Hence $F(a,F(b,c)) = F(a, b \cdot_{G'} c) = a \cdot_{G'} b \cdot_{G'} c$. Similarly, as $(a,b) \models \pi_{\bar{\mu}'}^{\otimes 2}|_{M_{\omega}}$, $F(a,b) = a \cdot_{G'} b$. And as $c \models \pi_{\bar{\mu}'}|_{M_{\omega}, a, b}$, we have $c \models \pi_{\bar{\mu}'}|_{M_{\omega}, a \cdot_{G'} b}$ (Remark \ref{rem: realize over dcl heq}), so $F(F(a,b),c) = F(a \cdot_{G'} b, c) = a \cdot_{G'} b \cdot_{G'} c$.
\end{proof}

Using Claim \ref{cla: proof of group chunk in the reduct} and applying Theorem \ref{thm: hyperdef group chunk gives group} in $T$, we find an $M_{\omega}$-hyper-definable in $T$ group $G^{\ast} = (X/E, \cdot_{G^{\ast}})$ and an $L(M_{\omega})$-type-definable partial function $\iota: \pi_{\bar{\mu}} \to G^{\ast}$ defined and injective on $\pi_{\bar{\mu}}$, so that for any $(a,b) \models \pi_{\bar{\mu}}^{\otimes 2}|_{M_{\omega}}$ we have $\iota(F(a,b)) = \iota(a) \cdot_{G^{\ast}} \iota(b)$ and the global partial type $f_{\ast} \pi$ concentrates on $G^{\ast}$ and is left-$G^{\ast}(M')$-invariant.


Now we work in $T'$. We know that $\pi_{\bar{\mu}'}$ is type-definable over $M_{\omega}$, concentrates on $G'$ and is $L'(M_{\omega})$-type-definable.
 As $\pi_{\bar{\mu}}|_{M_{\omega}}(x) \subseteq \pi_{\bar{\mu}'}|_{M_{\omega}}(x)$ (Claim \ref{cla: pi mu implies pi mu'}),  $\iota$ is of course still defined on $\pi_{\bar{\mu}'}|_{M_{\omega}}$ and is injective on it. And by  \eqref{eq: main thm proof 1} we have that for any $(a,b) \models \pi_{\bar{\mu}'}^{\otimes 2}|_{M_{\omega}}$, $\iota( a \cdot_{G'} b) = \iota(F(a,b))$. 
Applying Corollary \ref{cor: unique group from group chunk} in $T'$ (for $\pi_{\bar{\mu}'}$, $F$ and $f_1 = \iota: \pi_{\bar{\mu}'}|_{M_{\omega}} \to G^{\ast}$ and $f_2 = \id: \pi_{\bar{\mu}'}|_{M_{\omega}} \to G'$, we find an $L'(M_{\omega})$-type-definable group isomorphism $\iota': G' \to G^{\ast}$.

Applying Proposition \ref{prop: elim hyperdef group},  we find a group $G_0$ which is $L(M_{\omega})$-definable  in $T^{\eq}$ and an $L'(M_{\omega})$-definable isomorphism $\iota_0: G'(M') \to G_0(M')$.


Finally, say $G'(M') = \varphi(M')$ for some formula $\varphi(x) \in L'(M)$, $\Gamma_{F'}(x,y,z) \in L'(M)$ is the formula defining its graph of multiplication.  Say $G_0 = (X_0/E_0, \cdot_{G_0})$ for $X_0$ defined by $\psi(y, b)$,  the equivalence relation $E_0$ defined by $\xi(y_1,y_2,b)$, $\Gamma_{\cdot_{G_0}}$ defined by $\chi(y_1,y_2,y_3; b)$, and $\Gamma_{\iota_0}$ defined by $\rho(x,y; b)$ for some  $L(\emptyset)$-formulas $\psi(y,z), \xi(y_1,y_2,z), \chi(y_1,y_2,y_3; b), \rho(x,y; z)$ and a tuple $b$ in $M_{\omega}$. 




As $(N',M') \succ^{L_P} (N,M)$, there exist some tuple $b'$ in $M$ so that $ \xi(y_1,y_2,b')$ defines an equivalence relation $E'$ in $M$,
 $G := \left( \psi(M, b')/E_0, \chi(y_1,y_2,y_3; b')  \right)$ is a group definable in $M^{\eq}$ and $\rho(x,y;b')$ defines a group isomorphism $G'(M) \to G(M)$, as wanted.
\end{proof}

