\begin{remark}\label{rem: ext def fsg iso def applies to reducts}
	Theorem \ref{thm: ext def fsg groups is to definable} also applies to arbitrary reducts of $M^{\Sh}$ expanding $M$ (with the new point being the definability of the isomorphism $\iota$ in such a reduct). 
	\end{remark}
	\begin{proof}
		This follows by inspection of the proof of Theorem \ref{thm: ext def fsg groups is to definable}. Indeed, assume $M'' = M^{\Sh} \restriction_{L''}$ for some $L \subseteq L'' \subseteq L' = L^{\Sh}$ and $G'$ is group definable  in $M''$  and fsg in the sense of $\Th_{L''}(M'')$. Then $G'$ is definable in $M^{\Sh}$ and fsg in $T' = \Th_{L'}(M^{\Sh})$, by Fact \ref{fac: group props preserved in Sh exp}. 

		Following the proof of Theorem \ref{thm: ext def fsg groups is to definable}, we let $\bar{\mu}' \in \mathfrak{M}_{G'}^{L'}(M')$ be an invariant generically stable over $M$ measure in $T'$, and let $\bar{\mu}'' := \bar{\mu} \restriction_{L''}$. Then $\bar{\mu}'' \in \mathfrak{M}^{L''}_x(M')$ is generically stable over $M$ in $T''$ (Proposition \ref{prop: properties of reducts of measures}), so   $\pi_{\bar{\mu}''}$ is a partial type over $M'$ type-definable over $M$ in $T''$. And $ \pi_{\bar{\mu}''} = \pi_{\bar{\mu}'} \restriction_{L''}, \pi_{\bar{\mu}} = \pi_{\bar{\mu}''} \restriction_{L}$.


		Following the proof of Theorem \ref{thm: ext def fsg groups is to definable}, we find a hyper-definable over $M_{\omega}$ group $G^{\ast}$ in $T$ (given by $L(M_{\omega})$-type-definable $X$,$E$, $\Gamma_{\cdot_{G^{\ast}}}$) and an  $L(M_{\omega})$-type-definable partial map $\iota : \pi_{\bar{\mu}'} \to G^{\ast}$.
			As $G', \iota, G^{\ast}$ are all $L''(M_{\omega})$-type-definable, we get that then the group isomorphism $\iota': G' \to G^{\ast}$ is also $L''(M_{\omega})$-type-definable (indeed, from the proof of Theorem \ref{thm: equiv of cats groups vs chunks} we have that $\Gamma_{\iota'}(y,z)$ is type-defined by $(d_{\pi_{\bar{\mu}'}}x) \rho(x,y,z)$ for $\rho$ a small partial type defined in \eqref{eq: explicit formula for group iso}, which in our case only contains $L''(M_{\omega})$-formulas, hence $(d_{\pi_{\bar{\mu}'}}x) \rho(x,y,z) \equiv^{T'} (d_{\pi_{\bar{\mu}''}}x) \rho(x,y,z)$, and the latter is defined by a partial $L''(M_{\omega})$-type using type-definability of $\pi_{\bar{\mu}''}$ in $T''$). 


			  Then Proposition \ref{prop: elim hyperdef group}, applied for $T''$ and $T$, gives a group $G_0$ definable over $M_{\omega}$ in $T^{\eq}$ and an isomorphism $\iota_0:  G'(M') \to G_0(M')$  definable over $M_{\omega}$ in $(T'')^{\eq}$, and we reduce to definability over $M$ instead of $M_{\omega}$ in the same way.
	\end{proof}



\begin{corollary}\label{cor: ext def fsg groups in RCVF}
\begin{enumerate}
	\item If $T$ is $o$-minimal and $M \models T$, then every group definable and fsg in $M^{\Sh}$ is definably  isomorphic to a group definable in $M$.
	\item  Let $M'' \models \RCVF$ be arbitrary. If $G$ is definable in $M''$ fsg group, then $G$ is definably isomorphic to a group definable in the reduct $M \models \RCF$.
\end{enumerate}

\end{corollary}
\begin{proof}
(1) By Theorem \ref{thm: ext def fsg groups is to definable}, as every group definable in $M^{\eq}$ is definably isomorphic to a group definable in $M$ by \cite{eleftheriou2014interpretable}.

(2) By Remark \ref{rem: ext def fsg iso def applies to reducts} and (1), as $M''$ is a reduct of $M^{\Sh}$ (see the proof of Corollary \ref{cor: fsg subgroups in RCVF}).
\end{proof}

\begin{remark}
	In Theorem \ref{thm: ext def fsg groups is to definable}, if $G'$ is  not just fsg but moreover generically stable (i.e.~admits a left-invariant generically stable type $\bar{p}' \in S_{G'}^{L'}(M')$), we can avoid increasing the parameter set from $M$ to $M_{\omega}$ (as we already have $(\bar{p}' \restriction_{L})|_{M} \vdash \bar{p}' |_{M}$, by Lemma \ref{lem: unique extension of def meas to Sh} for types) and the passage through hyperdefinable groups in the proof, and apply a special case of the group chunk from \cite[Section 3.4]{hrushovski2019valued} for complete definable types to directly construct a group type-definable over $M$ in $T^{\eq}$ definably isomorphic to $G'$, which is then immediately definable over $M$ in $T^{\eq}$ by compactness.
\end{remark}

\begin{remark}\label{rem: type-def fsg in MSh recognize as hyper-definable}
The first part of the proof of Theorem \ref{thm: ext def fsg groups is to definable} goes through unchanged only assuming that $G'$ was a group type-definable over $M^{\Sh}$ and fsg in $T' = \Th(M^{\Sh})$, demonstrating that there is a small model $M_{\omega} \succ M$ and an  $M_{\omega}$-hyper-definable in $T$ group $G^{\ast} = (X/E, \cdot_{G^{\ast}})$ and an $L'(M_{\omega})$-type-definable isomorphism $\iota': G' \to G^{\ast}$.
\end{remark}

\begin{remark}\label{rem: ext interpretable groups}
	The situation is more complicated for fsg groups \emph{interpretable} in $M^{\Sh}$. Walsberg \cite{walsberg2019nip} (see also \cite[Section 5.1]{arXiv:2504.05566}) gives an example (related to Fact \ref{fac: G^00 ext def sometimes}) of a weakly $o$-minimal $\aleph_1$-saturated structure $\mathcal{H}$  so that $\mathcal{H}$ does not interpret an infinite groups, but $\mathcal{H}^{\Sh}$ interprets $(\mathbb{R},+,\times)$ (hence, e.g.~considering the associated circle group in it, interprets an infinite fsg group). 

	We note that this copy of $\mathbb{R}$ is given by a $\bigvee$-definable set in $\mathcal{H}$ quotiented by a $\bigwedge$-definable in $\mathcal{H}$ equivalence relation. The related fsg groups interpretable in  $\mathcal{H}^{\Sh}$, are  in fact hyper-definable in $\mathcal{H}$ (as we can replace the  $\bigvee$-definable set by a bounded definable set; for definably amenable, e.g. $(\mathbb{R},+)$ --- seem to get only $\bigvee/\bigwedge$-definability in $\mathcal{H}$). This motivates the following question that will be considered in future work:
\end{remark}

\begin{question}\label{que: ext interp fsg}
	Assume $M$ is a sufficiently saturated NIP structure, and $G(M)$ is definable in $(M^{\Sh})^{\eq}$ (which is not a saturated structure) and fsg (in $\Th((M^{\Sh})^{\eq})$). Then $G(M)$ is isomorphic to a group hyper-definable in $M$ (over a small set of parameters; globally in $\widetilde{M}'$ we can only expect a type-definable embedding). 
\end{question}


\section{Some further results}\label{sec: discussion}


\subsection{On the algebraic closure in Shelah expansion}\label{sec: acl in MSh}

The following basic question remains open:
\begin{question}
	Assume that $M$ is NIP and there is an infinite definable group in $\Th(M^{\Sh})$. Does it imply that there is an infinite definable (or at least type-definable) group in $\Th(M^{\eq})$?
\end{question}
\begin{remark}
	Note that this is not true if we only have an interpretable group in $\Th(M^{\Sh})$, by the example in Remark \ref{rem: ext interpretable groups} we would need to at least consider hyper-definable groups.
\end{remark}

\begin{prop}\label{prop: disint acl implies no groups}
	In any theory $T$, if the algebraic closure is \emph{disintegrated}, i.e. $\acl(a,b) = \acl(a) \cup \acl(b)$ for all finite sets $a,b$, then there are no infinite type-definable groups.
\end{prop}
\begin{proof}
	Let $\mathbb{M} \models T$ be a monster model and $(G, \cdot)$ an infinite group type-definable over a small set $A \subset \mathbb{M}$, i.e.~we have  $A$-definable functions $\cdot : (\mathbb{M}^x)^2 \to \mathbb{M}^x, ^{-1}: \mathbb{M}^x \to \mathbb{M}^x$ so that their restrictions to the partial type $G(x)$ defining $G$ are the group operations on $G$. As $G$ is infinite, by Ramsey and compactness we can find sequences $(a_i : i \in \mathbb{Q}), (b_i : i \in \mathbb{Q})$ of pairwise distinct elements of $G$ that are mutually indiscernible over $A$ (e.g. they can be two parts of the same $A$-indiscernible sequence of order type $\omega + \omega$).

	Let $c := a_0 \cdot b_0$, then $c \in \dcl(a_0, b_0, A)$.
	If  $c \in \acl(a_0, A)$, then $b_0 = a^{-1}_0 \cdot (a_0 \cdot b_0) = a^{-1}_0 \cdot c \in \acl(a_0, A)$ --- contradicting that the sequence $(b_i : i \in \mathbb{Q})$ is infinite and indiscernible over $a_0, A$ (in general, if a sequence is indiscernible over a set, then it is indiscernible over its algebraic closure). If  $c \in \acl(b_0, A)$, then $a_0 = (a_0 \cdot b_0) \cdot b^{-1}_0 = c \cdot b^{-1}_0 \in \acl(b_0,A)$ --- contradicting that the sequence $(a_i : i \in \mathbb{Q})$ is infinite and indiscernible over $b_0, A$.
\end{proof}

%\begin{remark}\label{rem: disint induct}
%	Note that if $T$ has disintegrated $\acl$, then by induction we have $\acl(a_1, \ldots, a_n) = \bigcup_{i \in [n]} \acl(a_i)$ for all $n \in \omega$ and finite sets $a_i$.
%\end{remark}
The following is standard:
\begin{remark}\label{rem: choosing alg formula}
		In any $L$-theory, if $a \in \acl(b)$, then there is some $k \in \omega$ and formula $\varphi(x,y) \in L$ so that $\models \varphi(a,b)$ and for every $b' \in \mathbb{M}^y$, $|\varphi(\mathbb{M},b')| \leq k$.

Indeed, given any $\psi(x,y) \in L$ so that $\psi(\mathbb{M},b')$ is finite, let $k:= |\psi(\mathbb{M},b')|$ and let $\varphi(x,y)$ be the formula 
\begin{gather*}
	\psi(x,y) \land \left( \exists x_1 \ldots \exists x_k  \left( \bigwedge_{i=1}^k \psi(x_i,y) \land  \forall x' \left(  \psi(x',y) \rightarrow \bigvee_{i=1}^k x' = x_i \right) \right) \right).
\end{gather*}
\end{remark}


We are following the notation from Definition \ref{def: Shelah exp context}.
Let us say that a binary relation $R \subseteq X \times Y$ is \emph{$k$-fiber-algebraic}, $k \in \omega$, if for every $x \in X$ there are at most $k$ elements $y\in Y$ so that $(x,y) \in R$. The following is a slight generalization of \cite[Corollary 1.5]{chernikov2013externally}:

\begin{cor}
Let $R \subseteq M^x \times M^y$ be an externally definable binary relation that is $k$-fiber-algebraic. Then there exists an $\mathbb{M}$-definable $k$-fiber-algebraic relation $R' \subseteq \mathbb{M}^x \times \mathbb{M}^y$ so that $R = R' \cap \left( M^x \times M^y \right)$. 

In particular, if $R$ is the graph of a function, then $R'$ is the graph of a partial function.
\end{cor}
\begin{proof}
	Say $R$ is the trace on $M$ of some $L(c)$-formula $\varphi(x,y; c)$ with $c \in N \succeq M$. By Fact \ref{fac: honest defs} we find $(N',M') \succ (N,M)$ and $\theta(x,y) \in L(M')$ so that $\theta(M) = \varphi(M,c)$ and $\theta(M') \subseteq \varphi(M';c)$. As the extension of pairs is elementary, we still have that $\varphi(M';c)$ is $k$-fiber-algebraic, then $\theta(M') \subseteq \varphi(M';c)$ implies that $\theta(M')$ is $k$-fiber-algebraic.
\end{proof}






 We let $\acl$ denote the algebraic closure in $T$, and $\acl^{\Sh}$ denote the algebraic closure in $\Th(M^{\Sh})$.


\begin{proposition}\label{prop: disint acl in Shelah exp}
If $T$ is NIP and has disintegrated $\acl$, then $\acl^{\Sh}(A) = \acl(A) \cup M$ for any $A \subseteq M'$ (in particular, $\acl^{\Sh}$ is also disintegrated).
\end{proposition}
\begin{proof}


	Clearly $\acl(A,M) \subseteq \acl^{\Sh}(A)$ for every $A \subseteq M'$ (note that $M \subseteq \dcl^{\Sh}(\emptyset)$ since every singleton subset of $M$  gets named by a relation symbol in $M^{\Sh}$). Assume we have tuples $a, c\in M'$ with $c \in \acl^{\Sh}(a) \setminus M$. 


	As $c \in \acl^{\Sh}(a)$, let  $k \in \omega$ and $\varphi(x;y)$ be an $L^{\Sh}$-formula given by Remark \ref{rem: choosing alg formula} applied in $\Th(M^{\Sh})$. By quantifier elimination in $\Th(M^{\Sh})$, $\varphi(M') = \varphi'(M',d)$ for some $\varphi'(x,y;u) \in L$ and some $d \in N$. That is, there exist some $d \in N$, $k \in \omega$ and $\varphi'(x, y; u) \in L$ so that 
	 \begin{gather}
	 	(N', M') \models \varphi'(c, a; d) \land  \forall y \in P\,  \exists^{\leq k} x \in P \, \varphi'(x, y; d) \label{eq: disint acl in Sh 1}
	 \end{gather}
	 (but $\varphi'(x, a; d)$ might have infinitely many realizations in $N$).


	By Fact \ref{fac: honest defs}, let $\theta(x,y;v) \in L$ and $e \in M'$ be such that
	\begin{gather}
		\theta(M;e) = \varphi'(M; d) \textrm{ and }\theta(M';e) \subseteq  \varphi'(M'; d).\label{eq: disint acl in Sh 3}
	\end{gather}

 Consider the partial $L$-types 
	\begin{gather*}
		A(x,y) := \left\{ \neg \alpha(x;y) \in L : \exists k' \in \omega \, \forall a' \in (M')^y \,  |\alpha(M', a')| \leq k' \right\},\\
%			B(x,z) := \left\{ \neg \beta(x;z) \in L : \exists k' \in \omega \, \forall b' \in (M')^z \,  |\beta(M', b')| \leq k' \right\},\\
			\Gamma(x; v) := \left\{ \neg \gamma(x;v) \in L : \exists k' \in \omega \, \forall e' \in (M')^v \,  |\gamma(M', e')| \leq k' \right\}.
	\end{gather*}
	Let $A_0 \subseteq A, \Gamma_0 \subseteq \Gamma$ be arbitrary finite subsets. By definition of $\Gamma$, the formula $\neg \bigwedge\Gamma_0(x, e)$ has only finitely many realizations in $M'$, let $c_1, \ldots, c_n$, $n \in \omega$, enumerate all of its realizations in $M$.

As $c \notin M$ by assumption, we have 
\begin{gather*}
	(N', M') \models \varphi'(c, a; d) \land A_0(c,a) \land \bigwedge_{i=1}^{n} c \neq c_i.
\end{gather*}
As $ (N, M) \prec (N', M')$, there exist some $c', a'$ in $M$ so that 
\begin{gather*}
	(N, M) \models \varphi'(c', a'; d) \land A_0(c',a') \land \bigwedge_{i=1}^{n} c'\neq c_i.
\end{gather*}
By the choice of $c_i$ and \eqref{eq: disint acl in Sh 3} we thus have 
\begin{gather*}
	(N', M') \models \theta(c', a'; e) \land A_0(c',a') \land \Gamma_0(c',e).
\end{gather*}


	 By saturation of the pair $(N', M')$ we can thus find $a^\ast, c^\ast$  in $M'$ so that 
\begin{gather*}
	(N', M') \models \theta(c^\ast, a^\ast; e) \land A(c^\ast,a^\ast) \land \Gamma(c^\ast,e).
\end{gather*}
Since all of these are $L$-formulas and all parameters are in $M'$ (and $(N', M')$ is an elementary pair), we have 
\begin{gather*}
	M' \models \theta(c^\ast, a^\ast; e) \land A(c^\ast,a^\ast) \land \Gamma(c^\ast,e).
\end{gather*}

As $\theta(M',e) \subseteq \varphi'(M',d)$ by \eqref{eq: disint acl in Sh 3}, using  \eqref{eq: disint acl in Sh 1} we get that $\theta(x, a^\ast; e)$ has at most $k$ realizations in $M'$. It follows by the choice of $A,\Gamma$ and Remark \ref{rem: choosing alg formula} (applied in $M' \models T$) that
\begin{gather*}
	c^\ast \in \acl(a^\ast,e) \setminus \left( \acl(a^\ast)  \cup \acl(e) \right).
\end{gather*}

	This contradicts the disintegration of the  algebraic closure in $T$.
\end{proof}

\begin{corollary}\label{cor: disint acl no groups in MSh}
	If $T$ is NIP, has disintegrated $\acl$ and $M \models T$, then there are no infinite type-definable groups in $\Th(M^{\Sh})$.
\end{corollary}
\begin{proof}
By Propositions \ref{prop: disint acl in Shelah exp} and \ref{prop: disint acl implies no groups}.
\end{proof}

\begin{remark}
	It follows from Corollary \ref{cor: disint acl no groups in MSh} that there are no infinite type-definable groups in $\mathcal{H}^{\Sh}$ from Example \ref{rem: ext interpretable groups}. 
\end{remark}

\subsection{Uniform type-definability for some sets related to generically stable measures}\label{sec: hyperdef sets from measures}


We are interested when the type-definable equivalence relations arising in the proof of Theorem \ref{thm: ext def fsg groups is to definable} (i.e.~the equality of germs in a definable family of partial functions on a generically stable measure) are uniformly type-definable or externally definable. We have:
\begin{lemma}
	For every $\varphi(x,y)$ and $r \in [0,1]$ there is an $\emptyset$-type definable set $D_r \subseteq \cU^y \times X_x$ so that: for any generically stable measure $\mu \in \mathfrak{M}_x(\cU)$ and any $b \in \cU^y$, $\mu(\varphi(x,b)) = r$ if and only if $(b, \bar{a}^{\mu}) \in D_r$ (where $\bar{a}^{\mu}$ is as in Definition \ref{def: a^mu coding measure}).
\end{lemma}
\begin{proof}
	We let  $D_r$ be the set of pairs $(b, \bar{a}) \in \cU^y \times X_x$ satisfying
	\begin{gather*}
\bigwedge_{k \in \mathbb{N} } \left( \left\lvert\Av(\bar{a}_{\varphi, 1/k}; \varphi(x,b))  - r)  \right \rvert \leq 1/k \right).
	\end{gather*}
As $\bar{a}^{\mu}_{\varphi, 1/k}$ is a $1/k$ approximation for $\mu$ on $\varphi(x,y)$ for any generically stable measure $\mu$, we have $(b, \bar{a}^{\mu}) \in D_r$ if and only if $\mu(\varphi(x,b))=r$.
\end{proof}

Note that $D_r$ is defined by a conjunction of instances of infinitely many distinct formulas (the condition ``$\left\lvert\Av(\bar{a}_{\varphi, 1/k}; \varphi(x,b))  - r)  \right \rvert \leq 1/k $'' is expressed by a disjunction of size growing with $k$ of conjunctions of instances of the form $\varphi(a,y)$). We consider a stronger notion:

\begin{definition}\label{def: unif type-def}
A set $X \subseteq \cU^x$ is \emph{uniformly} type-definable over $A \prec \cU$ if it is type-definable over $A$ by a partial type of the form $\pi(x) = \{ \varphi(x,a) : a \in A\}$ consisting of instances of a single formula $\varphi(x,y) \in L$.
\end{definition}


 \begin{proposition}\label{prop: unif def meas}
 	\begin{enumerate}
 		\item Let $T$ be arbitrary. Then for every stable formula $\varphi(x,y) \in L$ there is some $\theta(y,z) \in L$ so that: for every measure $\mu \in \mathfrak{M}_x(\cU)$, the set $\{b \in \cU^y : \mu(\varphi(x,b)) = 1 \}$ is uniformly type-definable over $M$ by instances of $\theta$.
 		Moreover, if $\mu$ is invariant over $M \prec \cU$, then we only need instances of $\theta$ with parameters in $M$.
 		\item Let $T$ be distal. Then for every $\varphi(x,y) \in L$ there is some $\theta(y,z) \in L$ so that: for every $r \in [0,1]$ and every measure $\mu \in \mathfrak{M}_x(\cU)$ generically stable over $M$ (hence smooth over $M$), the set  $\{b \in \cU^y : \mu(\varphi(x,b)) = r \}$ is uniformly type-definable over $M$ by instances of $\theta$.
 		\item If $T$ is NIP, $G$ is $M$-definable and $\mu \in \mathfrak{M}_{G}(\cU)$ witnesses that $G$ is fsg over $M$, then  for every $\varphi(x,y) \in L$, the set $\{b \in \cU^y : \mu(\varphi(x,b)) = 1 \}$ is externally definable.
 	\end{enumerate}
 \end{proposition}
 \begin{proof}
 	(1) Let $\varphi(x,y) \in L$ be a stable formula. By uniform definability of types with respect to a stable formula, there is some $\theta(y,z) \in L$ (given by a Boolean combination of instances of $\varphi^*(y,x)$) so that: for every type $p \in S_x(\cU)$ there is some $c_p \in \cU^z$ so that for every $b \in \cU^y$ we have $\varphi(x,b) \in p \iff \models \theta(b,c_p)$.
 	By Keisler's theorem, for every stable formula $\varphi(x,y) \in L$ and every Keisler measure $\mu \in \mathfrak{M}_x(\cU)$, there are some types $p_i \in S(\mu), i \in \omega$ and $r_i \in (0,1]$ with $\sum_{i \in \omega} r_i = 1$ so that for every $b \in \cU^y$ we have $\mu( \varphi(x,b)) = \left( \sum_{i \in \omega} r_i \cdot p_i \right)(\varphi(x,b))$. By the above, let $c_{p_i} \in \cU^z$ be so that  $\theta(y, c_{p_i})$ is a definition for $p_i$. Let $\Theta_{\mu}(y) := \{ \theta(y, c_{p_i}) : i \in \omega \}$. Now given $b \in \cU^y$, if $\mu(\varphi(x,b)) = 1$ then $\varphi(x,b) \in p_i$ for all $i \in \omega$ as $p_i \in S(\mu)$, so $\models \Theta(b)$. And conversely, if $\models \Theta(b)$ then $\mu(\varphi(x,b)) = \sum_{i \in \omega} r_i = 1$.

 	And if $\mu$ was $M$-invariant, every $p \in S(\mu)$ is non-forking over $M$, hence $p\restriction_{\varphi} \in S_{\varphi}(M)$ is definable over $M$ by basic local stability, so $c_{p_i}$ above can be chosen in $M$. 

 	(2) By uniform strong honest definitions in distal theories (\cite[Section 1.3]{chernikov2015externally}), given $\varphi(x,y)$ there is some $\theta(x_1, \ldots, x_k;y) \in L$ so that: for every finite $A \subseteq \cU^x$, $|A| \geq 2$ and $b \in \cU^y$, there are some $a_1, \ldots, a_k \in A$ so that $\models \theta(a_1, \ldots, a_k; b)$ and $\theta(a_1, \ldots, a_k; y) \vdash \tp_{\varphi}(b/A)$. In particular, we have distal cell decompositions: for every finite $A \subseteq \cU^x$ there are some $\bar{a}_1, \ldots, \bar{a}_N \in A^n$ so that $\cU^y \subseteq \bigcup_{1 \leq i \leq N} \theta(\bar{a}_i, \cU)$ (not necessarily a disjoint union) and for any $i \in [N]$ and $b,b' \models \theta(\bar{a}_i, y)$, $\tp_{\varphi}(b/A) = \tp_{\varphi}(b'/A)$.

 	Now let $\mu \in \mathfrak{M}_x(\cU)$ be an arbitrary measure generically stable over $M$ and $r \in [0,1]$. Fix $\varepsilon > 0$, by generic stability there are some $n_{\varepsilon} \in \omega$ and $(a^{\varepsilon}_1, \ldots, a^{\varepsilon}_{n_{\varepsilon}}) \in (M^x)^{n_{\varepsilon}}$ so that for every $b \in \cU^y$, $\mu(\varphi(x,b)) \approx^{\varepsilon} \Av(a^{\varepsilon}_1, \ldots, a^{\varepsilon}_{n_{\varepsilon}}; \varphi(x,b))$. Let $A^{\varepsilon} := \{a^{\varepsilon}_i : i \in [n_{\varepsilon}]  \}$. Let $B^\varepsilon := \{ \bar{a}^{\varepsilon}_i \in (A^{\varepsilon})^k: i \in [N_{\varepsilon}]\}$ be as given by the distal cell decomposition. That is, $\cU^y = \bigcup_{i \in [N_{\varepsilon}]} \theta(\bar{a}^{\varepsilon}_i; \cU)$ and for any $i \in [N_{\varepsilon}]$ and $b,b' \models \theta(\bar{a}^{\varepsilon}_i, y)$, $\tp_{\varphi}(b/A^{\varepsilon}) = \tp_{\varphi}(b'/A^{\varepsilon})$; in particular, $\Av(a^{\varepsilon}_1, \ldots, a^{\varepsilon}_{n_{\varepsilon}}; \varphi(x,b)) = \Av(a^{\varepsilon}_1, \ldots, a^{\varepsilon}_{n_{\varepsilon}}; \varphi(x,b'))$. Let $C^{\varepsilon}$ be the set of $ i \in [N_{\varepsilon}]$ so that for some (equivalently, any) $b \models \theta(\bar{a}^{\varepsilon}_i, y)$, $|\Av(a^{\varepsilon}_1, \ldots, a^{\varepsilon}_{n_{\varepsilon}}; \varphi(x,b)) - r| > \varepsilon$.
Finally, consider the partial type 
$$\Theta (y) := \left\{ \neg \theta \left(\bar{a}^{1/m}_{i}, y \right) : m \in \omega, i \in C^{1/m}\right\}$$
of size $|T|$ over $M$. 	Let $b \in \cU^y$ be arbitrary. 


  Assume $\mu(\varphi(x,b)) = r$. For any  $m \in \omega$ and $i \in C^{1/m}$, we cannot have $\models \theta(\bar{a}^{1/m}_{i};b)$ because by the choice of $C^{1/m}$ we would then have 
  $$|\Av(a^{\varepsilon}_1, \ldots, a^{\varepsilon}_{n_{\varepsilon}}; \varphi(x,b)) - r| > 1/m,$$
   but by the choice of $A^{\varepsilon}$ we have 
  $$|\Av(a^{\varepsilon}_1, \ldots, a^{\varepsilon}_{n_{\varepsilon}}; \varphi(x,b)) - r| = | \Av(a^{\varepsilon}_1, \ldots, a^{\varepsilon}_{n_{\varepsilon}}; \varphi(x,b)) - \mu(\varphi(x,b))| \leq 1/m,$$
  so $\models \Theta(b)$.

 	Conversely, assume $\models \Theta(b)$. For each $m \in \omega$, by the choice of $B^{1/m}$ we must have $\models \theta(\bar{a}^{\varepsilon}_i; b)$ for at least one $i \in [N_{\varepsilon}]$, and necessarily $i \notin C^{\varepsilon}$ since $\models \Theta(b)$, so $\mu(\varphi(x,b)) \approx^{1/m} \Av(a^{\varepsilon}_1, \ldots, a^{\varepsilon}_{n_{\varepsilon}}; \varphi(x,b)) \approx^{1/m} r$, hence $\mu(\varphi(x,b)) \approx^{2/m} r$. As this holds for all $m \in \omega$, we must have $\mu(\varphi(x,b)) = r$.

 	(3) Let $\mu \in \mathfrak{M}^L_G(\cU)$ be the unique left-$G(\cU)$-invariant measure and let $p \in S_{G}^L(\cU)$ be a generic type, then $S(\mu) = \overline{G \cdot p}$ (see the proof of Proposition \ref{prop: fsg iff invariant filter str fin sat}). Then $\mu(\varphi(x,b)) =1 \iff \varphi(x,b) \in q$ for all $q \in S(\mu)$, $\iff \varphi(x,b) \in g \cdot p$ for all $g \in G(\cU)$, $\iff \varphi(g \cdot x,b) \in p$ for all  $g \in G(\cU)$. Let $\psi(x;y,z) := \varphi(y \cdot x,z)$, then $(d_p x) \psi(x;y,z)$ is definable in $\cU^{\Sh}$, hence $\forall y \in G ((d_p x) \psi(x;y,z))$ is also definable in $\cU^{\Sh}$.
 \end{proof}

 \begin{question}
 	\begin{enumerate}
 		\item In Proposition \ref{prop: unif def meas}(1), can we replace $1$ by an arbitrary $r \in [0,1]$?
 		\item Does Proposition \ref{prop: unif def meas}(1) hold for arbitrary generically stable measures in NIP theories?
 	\end{enumerate}
 \end{question}

 \begin{remark}
	Let $M \models T$ be the theory of equality and a tuple of variables $x$ be arbitrary. Let  $A \subseteq M^x$ be an arbitrary countable set, say $A = \{a_i : i \in \omega \}$.  Choose arbitrary $r_i \in (0,1]$ so that $\sum_{i \in \omega} r_i = 1$. Let $\mu := \sum_{i \in \omega} r_i \cdot \tp(a_i/\cU)$, then $\mu$ is smooth over $M$. Then for any $b \in \cU^y$, $\mu( x \neq b)=1 \iff b \notin A$. So in general the set $\{b \in M^y: \mu(\varphi(x,b))=1\}$ is not externally definable even for smooth measures.
\end{remark}



\subsection{Externally type-definable and $\bigvee$-definable sets}\label{sec: ext type-def sets}
In this section we give an internal description of externally type-definable and $\bigvee$-definable sets in NIP theories, and a soft description of externally $\bigvee$-definable subgroups of definable groups.

\begin{definition}
	Let $M \models T$ and $\kappa$ a cardinal. A set $X \subseteq M^x$ is \emph{externally $\kappa$-type-definable} (\emph{externally $\kappa$-$\bigvee$-definable}) if there is a partial type $\Gamma(x;\bar{y})$ over $\emptyset$ of size $\leq \kappa$ (respectively, a disjunction $\Sigma(x;\bar{y})$  of $\leq \kappa$ formulas over $\emptyset$), where $\bar{y}$ possibly infinite of length at most $\kappa$, and a  tuple $\bar{b} \in \cU^{\bar{y}}$ so that $X = \Gamma(M; \bar{b})$, where $\Gamma(M; \bar{b})$ is the set of realizations of $\Gamma(x,\bar{b})$ in $M$ (respectively, $X = \Sigma(M, \bar{a})$).
\end{definition}

We consider several notions of directedness for type-definable and $\bigvee$-definable families working in a possibly non-saturated model:
\begin{definition}\label{def: unif dir}
	Let $\Gamma(x;\bar{y})$ be a conjunction (or a disjunction) of a tuple of formulas  $(\varphi_t(x, y_t) :  t < \kappa )$ where $\varphi_t(x,y_t) \in L(\emptyset)$, $y_t$ is a finite tuple of variables and $\bar{y} = (y_t : t < \kappa)$ is a tuple of variables of length at most $\kappa$,  and $\Omega \subseteq M^{\bar{y}}$ an arbitrary set.
	We say that the family of subsets $\left\{ \Gamma(M;\bar{b}) : \bar{b} \in \Omega \right\}$ of $M^x$  is
	\begin{enumerate}
	\item \emph{$\lambda$-directed}, for a cardinal $\lambda$, if for every $\Omega_0  \subseteq \Omega$ with $|\Omega_0| < \lambda$ there is some $\bar{b} \in \Omega$  so that $  \bigcup_{i \in \Omega_0} \Gamma(M, \bar{b}_{i}) \subseteq  \Gamma(M, \bar{b})$. We say \emph{directed} for $\aleph_0$-directed.

		\item \emph{downwards $\lambda$-directed} if for every $\Omega_0  \subseteq \Omega$ with $|\Omega_0| < \lambda$ there is some $\bar{b} \in \Omega$  so that $\Gamma(M, \bar{b}) \subseteq \bigcap_{i \in \Omega_0} \Gamma(M, \bar{b}_{i})$; 

		\item \emph{uniformly directed} if there is some $f: \kappa \to \kappa$ so that for every $n \in \omega$, finite $I \subseteq \kappa$ and $\bar{b}_1, \ldots, \bar{b}_n \in \Omega$ there is some $\bar{b} \in \Omega$  so that: 
		\begin{itemize}
			\item if $\Gamma(x,\bar{y})$ is a disjunction, $\bigvee_{i=1}^{n}  \varphi_t(x, \bar{b}_i) \vdash \varphi_{f(t)}(x, \bar{b})$ for all $t \in I$;
			\item if $\Gamma(x,\bar{y})$ is a conjunction, $\bigvee_{i=1}^{n}  \varphi_{f(t)}(x, \bar{b}_i) \vdash \varphi_{t}(x, \bar{b})$ for all $t \in I$.
			\end{itemize}
	\item \emph{uniformly downwards directed} if $\Gamma(x,\bar{y})$ is a conjunction, and there is $f: \kappa \to \kappa$ so that for all $n \in \omega$, $t < \kappa$ and $\bar{b}_1, \ldots, \bar{b}_n \in \Omega$ there is $\bar{b} \in \Omega$  so that $ \varphi_{f(t)}(x, \bar{b}) \vdash \bigwedge_{i=1}^{n}  \varphi_{t}(x, \bar{b}_i)$ for all $t \in I$.
	\end{enumerate}
	(If $\left\{ \Gamma(M;\bar{b}) : \bar{b} \in \Omega \right\}$ is uniformly directed, then it is also directed; and if $\Gamma(x,\bar{y})$ consists of a single formula, the two notions are equivalent)
\end{definition}

We recall from \cite{hrushovski2016non}, here $M$ is not necessarily saturated:
\begin{definition}
	A set of tuples $\Omega \subseteq M^{\bar{y}}$, with $\bar{y} = (y_t: t<\kappa)$ and each $y_t$ a finite tuple of variables, is \emph{strict pro-definable} if $\Omega = \Psi(M)$ for a partial type $\Psi(\bar{y})$ over $M$ and,  letting $\pi_{I}: M^{\bar{y}} \to \prod_{t \in I}  M^{y_{t}}$ be the projection map, $\pi_I(\Omega) = \psi_I(M)$ for some $\psi_{I}((y_t)_{t \in I}) \in L(M)$ (hence without loss of generality in $\psi_I \in \Psi$).
\end{definition}
\begin{remark}\label{rem: strict pro lifts}
If $N \succ M$ is $(|M|+\kappa)^{+}$-saturated, then $\Psi(N)$ is still strict pro-definable. Indeed, for every finite $I, J \subseteq \kappa$	 and $\Psi_0 ((y_t)_{t \in I \cup J}) \subseteq \Psi$, $M \models \forall (y_t)_{t \in I} ( \psi_I((y_t)_{t \in I}) \rightarrow \exists (y_t)_{t \in J} \Psi_0 ((y_t)_{t \in I \cup J}))$. Hence the same holds in $N$ by elementarity, so by saturation  $\pi_{I}(\Psi(N)) = \psi_{I}(N)$.
\end{remark}



\begin{remark}\label{rem: unif direct and strict pro-def}

(1) Directed does not imply uniformly directed, even if $\Omega$ is type-definable in a saturated $M$ (consider $\Sigma(x,\bar{y}) = \bigvee_{t \in \aleph_0}(x = y_t)$ and $\Omega = M^{\aleph_0}$ for $M \models T$ theory of an infinite set; then $\left\{\Sigma(M,\bar{b})\right\}_{\bar{b} \in \Omega}$ is $\aleph_1$-directed, but not uniformly directed).

(2) If $\left\{\Gamma(M,\bar{b})\right\}_{\bar{b} \in \Omega}$ is uniformly directed, $\Omega \subseteq M^{\bar{y}}$ is type-definable and $M$ is saturated, then $\left\{\Gamma(M,\bar{b})\right\}_{\bar{b} \in \Omega}$ is $\lambda$-directed for every small $\lambda$. Indeed, say $ \Omega = \pi(M)$ for a small partial type $\pi(\bar{y})$, and let $\bar{b}_i \in \pi(M)$ for $i < \lambda$ be given. Let $\Theta(\bar{y}) := \pi(\bar{y}) \cup \bigcup_{t < \kappa}\{\forall x (\varphi_{f(t)}(x, \bar{y}) \rightarrow \varphi_t(x, \bar{b}_{i})) : i < \lambda \}$. Every finite subset of $\Theta(\bar{y})$ is consistent by uniform directedness, hence there is $\bar{b} \in \Theta(M)$ by saturation, and it satisfies the requirement. Similarly for $\Sigma$.

(3) Assume that $M \prec N$ and $N$ is saturated, $\Omega \subseteq M^{\bar{y}}$ is strict pro-definable in $M$ via $\Psi(\bar{y})$ and $\{\Gamma(M,\bar{b}) : \bar{b} \in \Omega\}$ (respectively, $\{\Sigma(M,\bar{b}) : \bar{b} \in \Omega\}$) is uniformly directed. Then $\{\Gamma(N,\bar{b}) : \bar{b} \in \Psi(N) \}$ (respectively, $\{\Sigma(N,\bar{b}) : \bar{b} \in \Psi(N) \}$) is also uniformly directed. 

Indeed, by uniform directedness in $M$ and strict pro-definability, given $t < \kappa$, for any fixed $n \in \omega$ and $b_{1,t}, \ldots, b_{n,t} \in \psi_{\{t\}}(M^{y_t})$ there is some $b_{f(t)} \in \psi_{\{f(t)\}}(M^{y_{f(t)}})$ so that 
$M \models \forall x \left( \varphi_{\{f(t)\}}(x, b_{f(t)}) \rightarrow \bigwedge_{i \in [n]} \varphi_{\{t\}}(x, b_{i,t}) \right)$. 
By elementarity the same holds in $N$, so we conclude by Remark \ref{rem: strict pro lifts}. Similarly for $\Sigma$.

\end{remark}

\begin{proposition}\label{prop: unif directed implies ext type def}
	Let $M$ be a small model, $\Omega \subseteq M^{\bar{y}}$ and $\left\{ \Gamma(x;\bar{b}) : \bar{b} \in \Omega \right\}$ (respectively, $\left\{ \Sigma(x;\bar{b}) : \bar{b} \in \Omega \right\}$)  a uniformly directed family. Then there is $\bar{b}^* \in \cU^{\bar{y}}$ with
	$$\bigcap_{\bar{b} \in \Omega}  \Gamma(M, \bar{b}) = \Gamma(M, \bar{b}^*) \textrm{ (respectively, } \bigcup_{\bar{b} \in \Omega}  \Sigma(M, \bar{b}) = \Sigma(M, \bar{b}^*)\textrm{),}$$
	in particular this intersection (respectively, union) is externally $|\Gamma|$-type-definable (respectively, $|\Gamma|$-$\bigvee$-definable).
\end{proposition}
\begin{proof}
	Let $\Gamma(x;\bar{y}) = \{\varphi_t(x, \bar{y}) : t < \kappa \}$ and $f: \kappa \to \kappa$ be given by uniform directedness.
	Let $\pi(\bar{y})$ be the following set of formulas over $M$:
	\begin{gather*}
	 \left\{ \forall x \left( \varphi_{f(t)}(x,\bar{y}) \rightarrow \varphi_t(x, \bar{b}) \right)  : t < \kappa, \bar{b} \in \Omega \right\} \cup \bigcup \left\{ \Gamma(a, \bar{y}) : a \in \bigcap_{\bar{b} \in \Omega} \Gamma(M,\bar{b})  \right\}.
	\end{gather*}

	Then $\pi(\bar{y})$ is consistent. Indeed, given any finitely many $\bar{b}_1, \ldots, \bar{b}_n \in \Omega$, by uniform directedness there is some $\bar{b}' \in \Omega$ so that $\varphi_{f(t)}(x, \bar{b}') \vdash \bigwedge_{i=1}^{n}  \varphi_t(x, \bar{b}_i)$ for all $t < \kappa$. And we still have $a \in \Gamma(M,\bar{b}')$ for every $a$ appearing in the second set of conditions.
	This shows that every finite subtype of $\pi$ is consistent, hence $\pi(\bar{y})$ is consistent. Let $\bar{b}^{\ast} \models \pi(\bar{y})$ in $\cU$, we claim that it satisfies the requirement. Indeed, from the first set of conditions, $\Gamma(x,\bar{b}^{\ast})  \vdash \Gamma(x,\bar{b})$ for every $\bar{b} \in \Omega$, so $\Gamma(M,\bar{b}^{\ast}) \subseteq \bigcap_{\bar{b} \in \Omega}  \Gamma(M, \bar{b})$. Conversely, if $a \in \bigcap_{\bar{b} \in \Omega}  \Gamma(M, \bar{b})$, then also $a \in \Gamma(M,\bar{b}^{\ast})$ by the second set of conditions.
	 Similarly for $\Sigma$, letting $\bar{b}^{\ast} \in \cU^y$ realize the following partial type over $M$:
\begin{gather*}
	\left\{ \forall x \left(  \varphi_t(x, \bar{b})  \rightarrow \varphi_{f(t)}(x,\bar{y})\right)  : t < \kappa, \bar{b} \in \Omega \right\} \cup \\ \bigcup \left\{ \neg \Sigma(a, \bar{y}) : a \in M^x \setminus \bigcup_{\bar{b} \in \Omega} \Sigma(M,\bar{b})  \right\}. \qedhere
\end{gather*}

