We will need a slightly stronger version of honest definitions that work against an additional uniformly definable family $\zeta(x,u)$ of sets from \cite[Proposition 1.11]{chernikov2013externally} (generalizing the usual case $\zeta(x,u) = (x=u)$), which we state here with additional uniformity of the resulting honest definition:
\begin{fact}\label{fac: better uniform honest defs}
	Let $T$ be NIP, $M \models T$. Let $X \subseteq M^{x}$ be externally definable, say $X = \varphi(M,b)$ for some $\varphi(x,y) \in L$ and $b \in \cU^y$. Let $\zeta(x,u) \in L$. Let $\Omega := \{e \in M^u  : \zeta(M,e) \subseteq X\}$, and assume that $X = \bigcup_{e \in \Omega} \zeta(M,e)$. Then there is a formula $\theta(x,z) \in L$ depending only on $\varphi(x,y)$ and $\zeta(x,u)$, and there is $c \in \cU^z$ such that:
	\begin{enumerate}
		\item $\theta(x,c)$ is an honest definition of $X$,
		\item $\cU \models \zeta(x,e) \rightarrow \theta(x,c)$ for every $e \in \Omega$,
		\item for any $n \in \omega$ and $e_1, \ldots, e_n \in \Omega$, there is $c' \in M^z$ so that $\theta(M, c') \subseteq X$ and $\cU \models \zeta(x,e_i) \rightarrow \theta(x,c')$ for all $i = 1, \ldots, n$.
	\end{enumerate}
\end{fact}
\begin{proof}
If $X = \varphi(M,b)$, then by quantifier elimination in Shelah's expansion the set 
$$U := \{ e \in M^u: \forall a \in M^{x}, \zeta(a,e) \rightarrow  \varphi(a,b) \}$$
is externally definable. Moreover, by the existence of uniform honest definitions (\cite[Theorem 11]{chernikov2015externally}), there is a formula $\psi(u, v) \in L$ depending only on $\varphi(x,y), \zeta(x,u)$ so that $U = \psi(M, d)$ for some $d \in \cU^v$ (see the proof of \cite[Proposition 1.9.]{chernikov2013externally}). Let $\alpha(u, z)$ depending only on $\psi(u,v)$ be so that $\alpha(M,f)$, $f \in \cU^z$, is an honest definition for  $\psi(M, d) $.
The proof of \cite[Proposition 1.11]{chernikov2013externally} shows that we can take $\theta(x,z) := \exists u (\alpha(u,z) \land \zeta(x,u))$ (which depends only on $\varphi(x,y)$ and $\zeta(x,u)$).
\end{proof}


\begin{theorem}\label{thm: ext type def presentation}
	Let $M \models T$ be NIP and $\kappa \geq \aleph_0$ a cardinal. A set $X \subseteq M^x$ is externally $\kappa$-type-definable (respectively, externally $\kappa$-$\bigvee$-definable) if and only if  $X = \bigcap_{\bar{b} \in \Omega} \Theta(M;\bar{b})$ (respectively, $X = \bigcup_{\bar{b} \in \Omega} \Theta(M;\bar{b})$) for $\Theta(x;\bar{z})$ a partial type (respectively, a disjunction of formulas) over $\emptyset$ of size $\leq \kappa$, $\Omega \subseteq M^{\bar{z}}$ and $\{\Theta(x;\bar{c}) : \bar{c} \in \Omega \}$ a uniformly directed family. Moreover, if $X = \Gamma(M, \bar{b})$ for some $\bar{b} \in \cU^{\bar{y}}$, then $\Theta(x;\bar{z})$ can be chosen depending only on $\Gamma(x, \bar{y})$; and $\Omega$ can be chosen to be strict pro-definable in $M^{\Sh}$.
\end{theorem}
\begin{proof}
	The right to left implication holds in any theory by Proposition \ref{prop: unif directed implies ext type def}.

	We prove the converse in the type-definable case ($\bigvee$-definable case is similar, applying honest definitions directly to the formula defining $X$ rather than its complement). Assume $X = \Gamma(M, \bar{b})$ with $\Gamma(x,\bar{y}) = \{ \varphi_t(x, y_t) : t < \kappa \}$, $\bar{y}_t$ a finite subtuple of $\bar{y}$, and $b_t$ a subtuple of $\bar{b}$ corresponding to it.

	Fix $t < \kappa$. By induction on $j < \omega$, we choose formulas $\theta_{t,j}(x,z_{t,j})$ in $L$ so that the following hold for every $j < \omega$:
	\begin{enumerate}

		\item  $\varphi_t(M, b_t) = \bigcap \left\{ \theta_{t,j}(M,c) : c \in M^{z_{t,j}}, \varphi_t(M, b_t) \subseteq \theta_{t,j}(M,c)   \right\}$;
		\item for every $n \in \omega$ and $c_1, \ldots, c_n \in M^{z_{t,j}}$ with $ \varphi_t(M, b_t)  \subseteq \theta_{t,j}(M,c)$ there is some $c \in M^{z_{t,j+1}}$ so that $\varphi_t(M, b_t)  \subseteq \theta_{t,j+1}(M,c)$ and
 $\models \theta_{t,j+1}(x,c) \rightarrow \bigwedge_{i=1}^{n} \theta_{t,j}(x,c_i)$.
	\end{enumerate}

	Let $z_{t,0} := x$ and $\theta_{t,0}(x, z_{t,0}) := (\neg x = z_{t,0})$, clearly (1) holds.

	Assume we are given $\theta_{t,j}(x,z_{t,j})$ satisfying (1). Let $y := y_t$ and $\varphi(x,y) := \neg \varphi_t(x,y)$, $u := z_{t,j}$ and $\zeta(x, u) := \neg \theta_{t,j}(x,u)$. As $\theta_{t,j}$ satisfies (1), we have $\varphi(M,b_t) = \bigcup \left\{ \zeta(M, e) : e \in M^{u}, \zeta(M, e) \subseteq \varphi(M,b_t) \right\}$. Let $\theta(x, z)$ be as given for $\varphi(x,y), \zeta(x, u)$ by Fact \ref{fac: better uniform honest defs}. Let $z_{t,j} := z$ and $\theta_{t,j+1}(x,z_{t,j}) := \neg \theta(x, z_{t,j})$. Then $\theta_{t,j+1}(x,z_{t,j})$ satisfies (2), as $\theta(x, z)$ satisfies Fact \ref{fac: better uniform honest defs}(3). Which, combined with $\theta_{t,j}(x,z_{t,j})$ satisfying (1), implies that $\theta_{t,j+1}(x,z_{t,j})$ also satisfies (1).

	Let $\bar{z}$ be the concatenation of $(z_{t,j} : t < \kappa, j < \omega)$ and $\Theta(x,\bar{z}) := \left\{\theta_{t,j}(x,z_{t,j}) : t < \kappa, j < \omega \right\}$, a set of formulas of size $\leq \kappa$. Let 
	$$\Omega := \left\{ \bar{c} = (c_{t,j})_{t < \kappa, j < \omega} \in M^{\bar{z}} :  \bigwedge_{t<\kappa, j < \omega} \ \left( \varphi_t(M,b_t) \subseteq \theta_{t,j}(M,c_{t,j}) \right) \right\},$$
	it is clearly strict pro-definable in $M^{\Sh}$. We then have $\Gamma(M, \bar{b}) = X = \bigcap_{\bar{c} \in \Omega} \Theta(M, \bar{c})$, by definition of $\Omega$ and $\Theta$, using that $\theta_{t,j}$ satisfy (1) for all $t,j$.


	And the family $\{\Theta(M,\bar{c}) : \bar{c} \in \Omega\}$ is uniformly directed. Indeed, let $\bar{c}^{s} = (c^s_{t,j} : t< \kappa, j < \omega) \in \Omega$ for $1 \leq s \leq n $ be given. For any $t < \kappa, j < \omega$, by definition of $\Omega$ we have  $ \varphi_t(M, b_t)  \subseteq \theta_{t,j}(M,c^s_{t,j})$ for every $1 \leq s \leq n $; hence, by (2), there is some $c_{t,j}$ so that $\varphi_t(M, b_t)  \subseteq \theta_{t,j+1}(M,c_{t,j})$ and
 $\models \theta_{t,j+1}(x,c_{t,j}) \rightarrow \bigwedge_{s=1}^{n} \theta_{t,j}(x,c^s_{t,j})$. Let $\bar{c} := (c_{t,j})_{t < \kappa, j < \omega}$, then $\bar{c} \in \Omega$. Hence we can take the function $f:  (t,j) \in \kappa \times \omega \mapsto (t,j+1) \in \kappa \times \omega$ to witness uniform directedness of the family.
\end{proof}

\begin{remark}\label{rem: directed approximation in the monster}
	It follows  that, for $\widetilde{M}' \succ^{L'} M^{\Sh}$ a saturated extension, $X(\widetilde{M}') = \bigcap_{\bar{b} \in \Omega(\widetilde{M}')} \Theta(\widetilde{M}';\bar{b})$ (by (1), definition of $\Theta$ and $\Omega$ in the Proof of Theorem \ref{thm: ext type def presentation} and elementarity), and the pro-definable family of type-definable sets $\left\{\Theta(\widetilde{M}';\bar{b}) : \bar{b} \in \Omega(\widetilde{M}')\right\}$ is $\lambda$-directed for any small $\lambda$ (by Remark \ref{rem: unif direct and strict pro-def} ((3) and (1)). And similarly in the $\bigvee$-definable case.
\end{remark}

\begin{question}
	If $M$ is saturated, can we also assume that $\{\Theta(M,\bar{b}) : \bar{b} \in \Omega\}$ is $\lambda$-directed for any small $\lambda$? (Note that $M^{\Sh}$ is not saturated, so Remark \ref{rem: unif direct and strict pro-def}(2) does not apply).
\end{question}

\begin{question}\label{q: honest defs directed}
	It is open since \cite{chernikov2013externally} if an analogous presentation holds for externally definable sets, i.e.~if Theorem \ref{thm: ext type def presentation} holds for $\kappa=1$ (or finite).
	Also, can one have directedness for small sets of members of the family rather than finite sets?
	\end{question}	

As an application, we have a (soft) description of externally definable subgroups of definable groups, as unions of (uniformly) directed families of their $\bigvee$-definable  subgroups:
\begin{proposition}\label{prop: ext def subgroups approx V-def}
	Let $M \models T$ be NIP, $G$ a definable group in $M$, $H \leq G(M)$ an externally $\kappa$-$\bigvee$-definable subgroup, and $\widetilde{M}' \succ^{L'} M^{\Sh}$ is saturated. Then there is a disjunction $\Sigma(x;\bar{y})$ of $\leq \kappa$ formulas over $\emptyset$ and a strict pro-definable over $M^{\Sh}$ set $\Omega \subseteq (\widetilde{M}')^{\bar{y}}$ so that $\Sigma(\widetilde{M}' ;\bar{b}) \leq H(\widetilde{M}')$ is a $\bigvee$-definable subgroup for each $\bar{b} \in \Omega$, $H(\widetilde{M}') = \bigcup_{\bar{b} \in \Omega} \Sigma(\widetilde{M}' , \bar{b})$ and the family $\left\{\Sigma(\widetilde{M}', \bar{b}) :  \bar{b} \in \Omega\right\}$ is uniformly directed, hence $\lambda$-directed for any small $\lambda$ (with respect to saturation of $\widetilde{M}'$).
\end{proposition}
\begin{proof}
	Let $\Theta(x,\bar{y}) $ be a disjunction of formulas $\{\varphi_t(x,\bar{y}) : t < \kappa\}$ of size $\leq \kappa$ and $\Omega$ be given by Theorem \ref{thm: ext type def presentation} with respect to $H(M)$, and let $\Sigma(x,\bar{y})$ be so that $\Sigma(x,\bar{b})$ defines the subgroup generated by $\Theta(x,\bar{b})$, i.e.~$\Sigma(x,\bar{y})$ is 
	$$\bigvee_{n \in \omega} \bigvee_{\bar{t} = (t_1, \ldots,t_n) \in  \kappa^n} \bigvee_{f: [n] \to \{1,-1\}} \exists (x_i : i \in [n]) \left( \bigvee_{i \in [n]} \varphi_{t_i}(x_i, \bar{y}) \land x = \prod_{i \in [n]} x_i^{f(i)} \right).$$
	Then $\{\Sigma(M, \bar{b}) : \bar{b} \in \Omega\}$ is still uniformly directed, and satisfies the requirement (using Remark \ref{rem: directed approximation in the monster}).
\end{proof}

\begin{remark}
	If $E(x_1,x_2)$ is an externally $\bigvee$-definable equivalence relation, we can similarly approximate it from below by a uniformly directed family of  $\bigvee$-definable equivalence relations. Namely, if $\Theta(x_1,x_2;\bar{y}) $ is a disjunction of formulas $\{\varphi_t(x_1,x_2,\bar{y}) : t < \kappa\}$ of size $\leq \kappa$ and $\Omega$ be given by Theorem \ref{thm: ext type def presentation} with respect to $E(M)$, and let $\Sigma(x,\bar{y})$ be the disjunction defining  the transitive closure of $\Theta'(x_1,x_2; \bar{y}) := \Theta(x_1,x_2;\bar{y}) \lor \Theta(x_2,x_1; \bar{y}) \lor x_1 = x_2$.
\end{remark}


We conclude with an observation about local coheirs.

\begin{definition}
\begin{enumerate}
	\item Let $\Delta(x,y)$ be a finite set of partitioned formulas $\varphi(x,y)$. By a complete $\Delta(x,y)$-type $q(x)$ over a set of parameters $A$  we mean a maximal consistent set of formulas of the form $\varphi(x,a)$ or $\neg \varphi(x,a)$ with $\varphi(x,y) \in \Delta$ and $a$ a tuple of corresponding length from $A$. We let $S_{\Delta(x,y)}(A)$ denote the set of complete $\Delta$-types over $A$.
	\item  If $\Delta$ is a finite set of (non-partitioned) formulas, by a complete $\Delta$-type over $A$ in the free variables $x$ we mean a complete $\Delta^\ast(x,y)$-type over $A$, where $\Delta^\ast(x,y)$ is a finite set of  all partitioned formulas obtained by taking an arbitrary partition of the variables of appropriate lengths  of a formula from $\Delta$. We let $S_{\Delta,x}(A)$ denote the set of complete $\Delta$-types over $A$ in the free variables $x$.
\end{enumerate}
	\end{definition}

\begin{fact}\cite[Claim 4.11]{kaplan2014examples}\label{fac: local coheirs}
	For every $A \subseteq C \subseteq \cU$ and type $q \in S_{\Delta,x}(\cU)$ which is finitely satisfiable in $A$, and any choice of a coheir $q' \in S_x(\cU)$ over $A$ with $q \subseteq q'$ (there is always one) and $n \in \omega$, we have:
	$(a_0, \ldots, a_{n-1}) \models \left( (q')^{(n)}|_{C}  \right) \restriction_{\Delta}$ if and only if $a_i \models q|_{Ca_{<i}}$ for all $i < n$.

	In particular, if $a_i \models q|_{Ca_{<i}}$ for all $i < n$, then $(a_i : i <n)$ is a $\Delta(C)$-indiscernible sequence of length $n$.
\end{fact}

The following is a local refinement of \cite[Proposition 3.9]{chernikov2014external} in the case of coheirs:
\begin{lemma}\label{lem: local honest def}
Assume we are in the context of Definition \ref{def: Shelah exp context}. 	Working in $T'$, let $p(x) \in S^L(M')$ be finitely satisfiable in $M$. For every NIP formula $\varphi(x,y) \in L$ there is some finite set of formulas $\Delta \subseteq L$ so that: for every $b \in N^y$, if $p\restriction_{\Delta}(x) \cup \{ \varphi(x,b) \} \cup \{ P(x) \}$ is consistent, then $p \restriction_{\Delta}(x) \cup \{ P(x) \} \vdash \varphi(x,b)$.
\end{lemma}
\begin{proof}
	As $\varphi(x,y)$ is NIP in $T$, by compactness there exist some finite set of $L$-formulas $\Delta$ and some $n$ so that: if $(a_i)_{i <n}$ is $\Delta$-indiscernible and $b$ is arbitrary (in $\cU \models T$), then we cannot have $\models \varphi(a_i,b) \iff i$ is even.

	Now if for some $b$ in $N$ we had $p\restriction_{\Delta} \cup \{ \varphi(x,b) \} \cup \{ P(x) \}$ is consistent but $p \restriction_{\Delta}(x) \cup \{ P(x) \} \not \vdash \varphi(x,b)$, following the proof of the existence of honest definitions \cite[Proposition 1.1]{chernikov2013externally} we can find 
	$(a_i: i < n)$ in $M' = P(N')$  so that $a_i \models \left( p\restriction_{\Delta} \right)_{Ma_{<i}}$ and $\models \varphi(a_i,b) \iff i$ is even.  By Fact \ref{fac: local coheirs} the sequence $(a_i : i <n)$ is $\Delta$-indiscernible, contradicting the choice of $\Delta$ and $n$.
\end{proof}
\noindent It is not known if analogous statements hold for invariant $\Delta$-types. 


