\section{Proof of Theorem \ref{thm:main} assuming Lemma \ref{lm:twopoint}}
\label{sec:proofthm}

\subsection{Necessity of the condition on \texorpdfstring{$p,q$}{p,q}}
We only need to assume that \eqref{eq:improvedHY} holds in dimension $d=1$, for every function $f$ supported in $\{0,1\}$.

First, by choosing
\[ f(0)=f(1)=1 \]
one obtains
\begin{equation}\label{eq:auxnecess}
\Big( \int_0^1 |1+e^{-2\pi i t}|^q \,\textup{d}t \Big)^{1/q} \leq 2^{1/p}
\end{equation}
whenever $q<\infty$.
The left hand side simplifies as
\[ \Big( \frac{2^{q+1}}{\pi} \int_0^{\pi/2} \cos^q t \,\textup{d}t \Big)^{1/q} \]
and then formula
\[ \int_0^{\pi/2} \cos^q t \,\textup{d}t = \frac{\sqrt{\pi}\,\Gamma((q+1)/2)}{2\,\Gamma(q/2+1)} \]
from \cite[Formula 5.12.2]{NIST} and the gamma-function duplication formula \cite[Formula 5.5.5]{NIST}
\[ \Gamma(q+1) = \frac{2^q}{\sqrt{\pi}} \Gamma\Big(\frac{q+1}{2}\Big) \Gamma\Big(\frac{q}{2}+1\Big) \]
transform \eqref{eq:auxnecess} into
\begin{equation}\label{eq:auxnecess1}
\frac{1}{p} \geq \frac{1}{q}\log_2\frac{\Gamma(q+1)}{\Gamma(q/2+1)^2}.
\end{equation}

The same choice of $f$ works for $q=\infty$ and leads to $2\leq 2^{1/p}$, so
\begin{equation}\label{eq:auxnecess2}
q=\infty \ \implies\ p\leq 1.
\end{equation}

Finally, let us also substitute
\[ f(0)=1, \quad f(1)=\varepsilon, \quad \varepsilon>0 \]
into \eqref{eq:improvedHY} and observe
\[ |1+\varepsilon e^{-2\pi i t}|^q = 1 + q\varepsilon \cos 2\pi t + \frac{q}{2} \varepsilon^2 \big(1+(q-2)\cos^2 2\pi t\big) + o(\varepsilon^2) \]
as $\varepsilon\to0^+$, uniformly in $t\in\R$.
Thus
\[ \Big( \int_0^1 |1+\varepsilon e^{-2\pi i t}|^q \,\textup{d}t \Big)^{1/q} 
= \Big( 1 + \frac{q^2}{4} \varepsilon^2 + o(\varepsilon^2) \Big)^{1/q}
= 1 + \frac{q}{4} \varepsilon^2 + o(\varepsilon^2) \]
for $q<\infty$ and
\[ (1+\varepsilon^p)^{1/p} = 1 + \frac{1}{p} \varepsilon^p + o(\varepsilon^p) \]
for $p<\infty$, both as $\varepsilon\to0^+$.
That way \eqref{eq:improvedHY} implies 
\[ \frac{q}{4} \varepsilon^2 + o(\varepsilon^2) \leq \frac{1}{p} \varepsilon^p + o(\varepsilon^p) \quad\text{as } \varepsilon\to0^+, \]
which is only possible when 
\begin{equation}\label{eq:auxnecess3}
p\leq 2.
\end{equation}

Note that \eqref{eq:auxnecess1}, \eqref{eq:auxnecess2}, and \eqref{eq:auxnecess3} together complete the proof of \eqref{eq:improvedrange} for all $q\in[1,\infty]$.

\subsection{Sufficiency of the condition on \texorpdfstring{$p,q$}{p,q}}
Suppose that the coefficients $p$ and $q$ satisfy \eqref{eq:improvedrange}. We can freely assume that $q\in(2,\infty)$ and $p\in(1,2)$, since for other exponents there is nothing to prove beyond the ordinary Hausdorff--Young inequality.  

Any two complex numbers $a,b$ can be written as
\[ a=\alpha e^{2\pi i \theta}, \quad b=\beta e^{2\pi i \vartheta} \]
for some $\alpha,\beta\in[0,\infty)$ and $\theta,\vartheta\in\R$.
Then 
\[ \int_0^1 |a + b e^{-2\pi i t}|^q \,\textup{d}t 
= \int_0^1 |\alpha e^{2\pi i (t+\theta-\vartheta)} + \beta|^q \,\textup{d}t
= \int_0^1 |\alpha e^{2\pi i t} + \beta|^q \,\textup{d}t, \]
so Lemma \ref{lm:twopoint} gives
\begin{equation}\label{eq:twopointineqcon} 
\Big( \int_0^1 |a + b e^{-2\pi i t}|^q \,\textup{d}t \Big)^{1/q} \leq (|a|^p + |b|^p)^{1/p} \quad \text{for } a,b\in\mathbb{C}.
\end{equation}

We are proving \eqref{eq:improvedHY} by the mathematical induction on the dimension $d\in\N$ and the basis $d=1$ becomes precisely \eqref{eq:twopointineqcon} after the substitution $a=f(0)$, $b=f(1)$.
For the induction step take some integer $d\geq 2$ and a function $f\colon\Z^d\to\mathbb{C}$ supported in $\{0,1\}^d$.
Define $f_0,f_1\colon\Z^{d-1}\to\mathbb{C}$ by
\[ f_0(x) := f(\underbrace{x}_{\in\Z^{d-1}},\underbrace{0}_{\in\Z}), \quad f_1(x) := f(\underbrace{x}_{\in\Z^{d-1}},\underbrace{1}_{\in\Z}) \]
for every $x\in\Z^{d-1}$, so that 
\[ \widehat{f}(\xi,t) = \widehat{f_0}(\xi) + \widehat{f_1}(\xi) e^{-2\pi i t} \]
for $(\xi,t)\in\T^{d-1}\times\T$.
Then \eqref{eq:twopointineqcon} and Minkowski's inequality (thanks to $p<q$) give
\begin{align*}
\|\widehat{f}\|_{\textup{L}^q(\T^d)}
& = \bigg( \int_{\T^{d-1}} \int_{\T} \big| \widehat{f_0}(\xi) + \widehat{f_1}(\xi) e^{-2\pi i t} \big|^q \,\textup{d}t \,\textup{d}\xi \bigg)^{1/q} \\
& \!\!\stackrel{\eqref{eq:twopointineqcon}}{\leq}
\bigg( \int_{\T^{d-1}} \bigg( |\widehat{f_0}(\xi)|^p + |\widehat{f_1}(\xi)|^p \bigg)^{q/p} \,\textup{d}\xi \bigg)^{1/q} \\
& \leq \big( \|\widehat{f_0}\|_{\textup{L}^q(\T^{d-1})}^p + \|\widehat{f_1}\|_{\textup{L}^q(\T^{d-1})}^p \big)^{1/p}.
\end{align*}
Applying the induction hypothesis to $f_0$ and $f_1$,
\[ \|\widehat{f_0}\|_{\textup{L}^q(\T^{d-1})} \leq \|f_0\|_{\ell^p(\{0,1\}^{d-1})}, \quad
\|\widehat{f_1}\|_{\textup{L}^q(\T^{d-1})} \leq \|f_1\|_{\ell^p(\{0,1\}^{d-1})}, \]
we finally deduce 
\[ \|\widehat{f}\|_{\textup{L}^q(\T^d)} 
\leq \big( \|f_0\|_{\ell^p(\{0,1\}^{d-1})}^p + \|f_1\|_{\ell^p(\{0,1\}^{d-1})}^p \big)^{1/p}
= \|f\|_{\ell^p(\{0,1\}^d)} \]
and thus complete the induction. 

