\section{Proof of Lemma \ref{lm:twopoint}}

Take some $q\in(2,\infty)$ and let $p=p(q)\in(1,2)$ be defined as \eqref{eq:pqequality}, so that \eqref{eq:improvedrange} is satisfied with an equality. 
It is sufficient to establish \eqref{eq:twopointineq} only for this value of $p$, since lowering $p$ only increases the right hand side.

Motivated by a computation from the introductory section, we substitute $a=\alpha^p$ and $b=\beta^p$, so that \eqref{eq:twopointineq} becomes
\[ \int_0^1 |a^{1/p} e^{2\pi i t} + b^{1/p}|^q \,\textup{d}t \leq (a + b)^{q/p}. \]
Both sides of the above inequality are homogeneous of degree $q/p$ in $(a,b)$, so we can simply just define $F_q\colon[0,1]\to(0,\infty)$ as
\begin{align}
F_q(x) & := \int_0^1 \big|x^{1/p} e^{2\pi i t} + (1-x)^{1/p}\big|^q \,\textup{d}t \nonumber \\
& \, = \int_{0}^{1} \big( (1-x)^{2/p} + x^{2/p} + 2 (1-x)^{1/p} x^{1/p} \cos 2\pi t \big)^{q/2} \,\textup{d}t \label{eq:fformula1}
\end{align}
and prove
\begin{equation}\label{eq:mainineq}
F_q(x) \leq 1 \quad \text{for every } x\in[0,1];
\end{equation}
see Figure \ref{fig:funct2D} for an illustration of the particular case $q=4$.

\begin{figure}
\includegraphics[width=0.55\linewidth]{dimension_funct2D.eps}
\caption{Graph of $F_4$. The maximum $1$ is attained at $0$, $1/2$, and $1$.}
\label{fig:funct2D}
\end{figure}

The following lemma is a direct generalization of \cite[Lemma 5]{Kov23}, but a different proof is needed, since $F_q$ no longer has an expansion into a finite sum.

\begin{lemma}\label{lm:ode}
The function $F_q$ satisfies the second-order ordinary differential equation
\begin{equation}\label{eq:theODE}
a_q(x) F_q''(x) + b_q(x) F_q'(x) + c_q(x) F_q(x) = 0 \quad \text{for } x\in\Big(0,\frac{1}{2}\Big), 
\end{equation}
where $a_q,b_q,c_q\colon(0,1/2)\to\mathbb{R}$ are defined as
\begin{align*}
a_q(x) & := p^2 (1-x)^2 x^2 \big((1-x)^{2/p}-x^{2/p}\big), \\
b_q(x) & := p (1-x) x \Big((1-x)^{2/p}\big(p (1-2x) + 2 q x\big) + x^{2/p}\big(p (2x-1) + 2q(1-x)\big)\Big), \\
c_q(x) & := q (1-x)^{2/p} x \big(p(1-x) + q x\big) - q  x^{2/p}(1-x) \big(p x + q(1-x)\big).
\end{align*}
\end{lemma}

\begin{proof}
The Legendre function $P_\nu$ of degree $\nu$ has the integral representation
\begin{equation}\label{eq:fformula2}
P_{\nu}(z) = \int_{0}^{1} \big( z + \sqrt{z^2-1} \cos(2\pi t)\big)^{\nu} \,\textup{d} t 
\end{equation}
for $z\in(1,\infty)$; see \cite[Formula 14.12.7]{NIST}.
It also satisfies the differential equation
\begin{equation}\label{eq:LegendreODE}
(1-z^2) P_{\nu}''(z) - 2 z P_{\nu}'(z) + {\nu}({\nu}+1) P_{\nu}(z) = 0 
\end{equation}
for $z>1$; see \cite[Formula 14.2.1]{NIST}.

Denoting
\[ \varphi(x) := \frac{(1-x)^{2/p}+x^{2/p}}{(1-x)^{2/p}-x^{2/p}},  \]
we can compare \eqref{eq:fformula1} and \eqref{eq:fformula2} to derive
\begin{equation}\label{eq:fqexpressed}
F_q(x) = \big((1-x)^{2/p}-x^{2/p}\big)^{q/2} P_{q/2}(\varphi(x)).
\end{equation}
Then we can finish the proof using symbolic computation in Mathematica as follows. First, direct symbolic differentiation expresses
\begin{itemize}
\item $F'_q(x)$ in terms of $P_{q/2}(\varphi(x))$ and $P'_{q/2}(\varphi(x))$, 
\item $F''_q(x)$ in terms of $P_{q/2}(\varphi(x))$, $P'_{q/2}(\varphi(x))$, and $P''_{q/2}(\varphi(x))$.
\end{itemize}
Next, we use the Legendre ODE \eqref{eq:LegendreODE} to write
\begin{itemize}
\item $P''_{q/2}(\varphi(x))$ in terms of $P_{q/2}(\varphi(x))$ and $P'_{q/2}(\varphi(x))$,
\end{itemize}
and plug all these into the left hand side of \eqref{eq:theODE}.
Mathematica command \verb+Simplify+ perfoms algebraic manipulation sufficient to show that this is in fact identically $0$.

Alternatively, we can start with $F_q$ expressed as in \eqref{eq:fqexpressed} and immediately apply Mathematica command \verb+FullSimplify+ to the left hand side of \eqref{eq:theODE}. Once again we end up with $0$, but this fully automated verification does not reveal what properties of the Legendre functions were used during the simplification. It turns out that Mathematica first expresses their derivatives in terms of Legendre functions of varying degrees \cite[Formula 14.10.5]{NIST} and then relates the latter via the recurrent relation \cite[Formula 14.10.3]{NIST}.
\end{proof}

%\begin{lemma}\label{lm:sign}
%The coefficient $a_q$ is strictly positive on $(0,1/2)$.
%The coefficient $c_q$ has a unique zero in $(0,1/2)$ and it changes sign precisely once on $(0,1/2)$.
%\end{lemma}

Before we begin the proof of \eqref{eq:mainineq}, let us observe the behavior of $F_q$ at $x=0,1/2$.

\begin{lemma}\label{lm:perturbative}
We have
\begin{align*}
F_q(0) = 1, & \qquad F_q(\varepsilon) = 1 - \frac{q}{p} \varepsilon + o(\varepsilon) \quad \text{as } \varepsilon\to0^+, \\
F_q\Big(\frac{1}{2}\Big) = 1, & \qquad F_q\Big(\frac{1}{2}-\varepsilon\Big) = 1 - \frac{2q^2}{p(q-1)} \Big(\underbrace{1-\frac{1}{p}-\frac{1}{q}}_{>0}\Big) \varepsilon^2 + o(\varepsilon^2) \quad \text{as } \varepsilon\to0^+.
\end{align*}
\end{lemma}

\begin{proof}
Substitution of $x=\varepsilon$ into the integrand of \eqref{eq:fformula1} gives
\begin{align*}
 \Big( 1 + 2 \varepsilon^{1/p} \cos 2\pi t - \frac{2}{p}\varepsilon + o(\varepsilon) \Big)^{q/2} 
 = 1 + q \varepsilon^{1/p} \cos 2\pi t - \frac{q}{p}\varepsilon + o(\varepsilon) 
\end{align*}
as $\varepsilon\to0^+$, uniformly in $t\in\R$, so integrating over $t\in[0,1]$ we deduce the first asymptotic formula.

Substituting $x=1/2-\varepsilon$ into the same integrand we get
\begin{align*}
& 2^{-q/p} \big( (1+2\varepsilon)^{2/p} + (1-2\varepsilon)^{2/p} + 2 (1-4\varepsilon^2)^{1/p} \cos 2\pi t \big)^{q/2} \\
& = 2^{q/2-q/p} \Big( 1 + \cos 2\pi t + \varepsilon^2 \frac{4}{p^2} (2-p-p\cos 2\pi t) + o(\varepsilon^2) \Big)^{q/2} \\
& = 2^{q/2-q/p} \Big( (1 + \cos 2\pi t)^{q/2} + \varepsilon^2 \frac{2q}{p^2} (1 + \cos 2\pi t)^{q/2-1} (2-p-p\cos 2\pi t) \Big) + o(\varepsilon^2)
\end{align*}
as $\varepsilon\to0^+$, uniformly in $t$ again.
Integrating this over $t\in[0,1]$ and using the same identities as in Section \ref{sec:proofthm}, we end up with
\[ 2^{-q/p} \binom{q}{q/2} - \varepsilon^2 \frac{2q^2}{p(q-1)} \Big(1-\frac{1}{p}-\frac{1}{q}\Big) 2^{-q/p} \binom{q}{q/2}. \]
Finally, the second asymptotic formula follows by recalling \eqref{eq:pqequality} and consequently replacing $\binom{q}{q/2}$ with $2^{q/p}$.

Both computations are trivially also valid for $\varepsilon=0$, revealing the values of $F_q$ at $0$ and $1/2$.
\end{proof}

Now we can finalize the proof of inequality \eqref{eq:mainineq}.
Notice that $F_q$ is symmetric about $1/2$, i.e., $F_q(1-x)=F_q(x)$ for $x\in[0,1]$.
Because of Lemma \ref{lm:perturbative} we know that $F_q$ has strict local maxima at $0$ and $1/2$, the one at $0$ being only one-sided.
Our goal is to show $F_q(x)\leq 1$ whenever $x\in(0,1/2)$. Suppose now, for contradiction, that there exists a point $x_{\max}\in (0,1/2)$ at which $F_q$ attains a local maximum.\footnote{One may further assume $F_q(x_{\max})>1$ in order to achieve the goal, but the argument in fact yields a stronger conclusion: $F_q$ cannot attain a local maximum in $(0,1/2)$ at all.}
Then $F_q$ would also attain local minima at some points $x_{\min,1}\in(0,x_{\max})$ and $x_{\min,2}\in(x_{\max},1/2)$; see Figure \ref{fig:minima}.
Since
\[ F'_q(x_{\min,1}) = F'_q(x_{\max}) = F'_q(x_{\min,2}) = 0 \]
and
\[ F''_q(x_{\min,1}) \geq 0, \quad F''_q(x_{\max}) \leq 0, \quad F''_q(x_{\min,2}) \geq 0, \]
the differential equation from Lemma \ref{lm:ode} and strict positivity of $F_q$ and $a_q$ on $(0,1/2)$ give
\[ c_q(x_{\min,1}) \leq 0, \quad c_q(x_{\max}) \geq 0, \quad c_q(x_{\min,2}) \leq 0. \]
In particular, by the intermediate value theorem, we see that $c_q$ has at least two zeros in the interval $(0,1/2)$.

