\section{Proof of Corollary \ref{cor:restriction}}

\subsection{Necessity of the condition on \texorpdfstring{$p,q$}{p,q}}
Suppose that \eqref{eq:improvedHY3} holds with a constant $C_{p,q}$ independent of the dimension.
Take $r\in\N$ and $g\in\ell^{q'}(\T^d)$ and apply \eqref{eq:improvedHY3} to the $rd$-dimensional function
\[ G(\xi_1,\xi_2,\ldots,\xi_r) := g(\xi_1) g(\xi_2) \cdots g(\xi_r), \quad \xi_1,\xi_2,\ldots,\xi_r \in \T^d, \]
to obtain
\[ \big\|\widehat{g}\big|_{\{0,1\}^d}\big\|_{\ell^{p'}(\{0,1\}^d)}^r \leq C_{p,q} \|g\|_{\textup{L}^{q'}(\T^d)}^r. \]
Taking the $r$-th roots of both sides and letting $r\to\infty$ we recover \eqref{eq:improvedHY2}, i.e., the constant becomes $1$.
Now the implication \eqref{thmit2}$\implies$\eqref{thmit3} from Theorem \ref{thm:main} confirms that the exponents $p,q$ need to belong to the range \eqref{eq:improvedrange}.

\subsection{Sufficiency of the condition on \texorpdfstring{$p,q$}{p,q}}
This follows from the implication \eqref{thmit3}$\implies$\eqref{thmit2} from Theorem \ref{thm:main} and we immediately also obtain the sharp constant $C_{p,q}=1$.

