\section{Proof of Corollary \ref{cor:entropy}}
\label{sec:entropy}

In this section we again assume that $q\in(2,\infty)$ and that $p=p(q)$ is always defined by \eqref{eq:pqequality}.
If we write
\[ q = 2 + \varepsilon, \]
then, using Taylor's expansion of $z\mapsto \log_2 \Gamma(z)$ around $z=2$ and $z=3$ in terms of the digamma function 
\[ \psi(z) := \frac{\textup{d}}{\textup{d}z} \ln \Gamma(z), \]
we obtain
\[ p = \frac{2+\varepsilon}{1+(\psi(3)/\ln 2)\varepsilon-2(\psi(2)/\ln 2)(\varepsilon/2)+o(\varepsilon)} \quad\text{as } \varepsilon\to0^+. \]
Since \cite[Formula 5.5.2]{NIST} specializes to	
\[ \psi(3) - \psi(2) = \frac{1}{2}, \]
we get
\begin{align}
p & = \frac{2 + \varepsilon}{1 + \varepsilon/(2\ln 2) + o(\varepsilon)} \nonumber \\
& = 2 - \Big(\frac{1}{\ln 2} - 1\Big) \varepsilon + o(\varepsilon) \quad\text{as } \varepsilon\to0^+. \label{eq:asymofp}
\end{align}

Take a function $f\colon\Z^d\to\mathbb{C}$ supported in $\{0,1\}^d$ and normalized as in \eqref{eq:normalization}. Denote
\[ S := \{ x\in\Z^d : f(x)\neq 0 \}, \quad T := \{ \xi\in\T^d : \widehat{f}(\xi)\neq 0 \}. \]
Applying \eqref{eq:improvedHY} from Theorem \ref{thm:main} with $p,q$ as above gives
\begin{equation}\label{eq:applofthm}
\Big( \int_T |\widehat{f}(\xi)|^q \,\textup{d}\xi \Big)^{1/q} \leq \Big( \sum_{x\in S} |f(x)|^p \Big)^{1/p}.
\end{equation}
Note that $|\widehat{f}|$ is bounded, so
\[ |\widehat{f}(\xi)|^q = |\widehat{f}(\xi)|^2 + \varepsilon |\widehat{f}(\xi)|^2 \ln |\widehat{f}(\xi)| + o(\varepsilon) \]
as $\varepsilon\to0^+$, uniformly in $\xi\in T$, and then
\[ \Big( \int_T |\widehat{f}(\xi)|^q \,\textup{d}\xi \Big)^{1/q} = 1 + \frac{\varepsilon}{2} \int_T |\widehat{f}(\xi)|^2 \ln |\widehat{f}(\xi)| \,\textup{d}\xi + o(\varepsilon) \quad\text{as }\varepsilon\to0^+, \]
thanks to our normalization
\[ \int_T |\widehat{f}(\xi)|^2 \,\textup{d}\xi = 1. \]
Also,
\[ |f(x)|^p \stackrel{\eqref{eq:asymofp}}{=} |f(x)|^2 - \Big(\frac{1}{\ln 2} - 1\Big) \varepsilon |f(x)|^2 \ln |f(x)| + o(\varepsilon) \quad\text{as }\varepsilon\to0^+, \]
which gives
\[ \Big( \sum_{x\in S} |f(x)|^p \Big)^{1/p} \stackrel{\eqref{eq:normalization}}{=} 1 - \Big(\frac{1}{\ln 2} - 1\Big) \frac{\varepsilon}{2}\sum_{x\in S} |f(x)|^2 \ln |f(x)| + o(\varepsilon) \quad\text{as }\varepsilon\to0^+. \]
Recall inequality \eqref{eq:applofthm}, subtract $1$, divide by $\varepsilon/(4\log_2 e)$, and let $\varepsilon\to0^+$ to obtain
\[ -\textup{H}_{\T^d}(|\widehat{f}|^2) \leq \Big(\frac{1}{\ln 2} - 1\Big) \,\textup{H}_{\Z^d}(|f|^2). \]

The equality will be attained for
\[ f = 2^{-d/2} \mathbbm{1}_{\{0,1\}^d}, \]
when
\[ \textup{H}_{\Z^d}(|f|^2) = - \sum_{x\in\{0,1\}^d} 2^{-d} \log_2 2^{-d} = d \neq 0. \]
Namely,
\[ \widehat{f}(\xi) = 2^{-d/2} \prod_{j=1}^{d} \big(1 + e^{-2\pi i \xi_j}\big) \]
for $\xi=(\xi_1,\xi_2,\ldots,\xi_d)\in\T^d$. Then Fubini's theorem on $\T^d$ and integration by parts enable us to compute
\begin{align*}
-\textup{H}_{\T^d}(|\widehat{f}|^2) & = \int_{\T^d} 2^{d} \Big(\prod_{j=1}^{d} \cos^2 \pi\xi_j\Big) \Big(d + \prod_{j=1}^{d} \log_2 \cos^2 \pi\xi_j\Big) \,\textup{d}\xi \\
& = d + 2d \int_0^1 (\cos^2 \pi t) (\log_2 \cos^2 \pi t) \,\textup{d}t \\
& = d + 2d\Big(\frac{1}{2\ln 2} - 1\Big) = d \Big(\frac{1}{\ln 2} - 1\Big).
\end{align*}
Therefore,
\[ \textup{H}_{\T^d}(|\widehat{f}|^2) + \Big(\frac{1}{\ln 2}-1\Big) \textup{H}_{\Z^d}(|f|^2) = 0, \]
as desired.

