\section{Proof of Theorem~\ref{thm:Young} assuming Lemma~\ref{lm:twopointYoung}}

\subsection{Necessity of the condition on \texorpdfstring{$p,q$}{p,q}}
Suppose that $1\leq p,q<\infty$.
We know that \eqref{eq:improvedYoung} holds for one-dimensional functions $f,g\colon\Z\to\mathbb{C}$ such that $f(0)=f(1)=g(0)=g(1)=1$, which vanish outside of $\{0,1\}$.
Since
\[ (f\ast g)(x) = 
\begin{cases}
2 & \text{if } x=1, \\
1 & \text{if } x=0 \text{ or } x=2, \\
0 & \text{otherwise},
\end{cases} \]
the inequality \eqref{eq:improvedYoung} actually gives
\[ (1^q + 2^q + 1^q)^{1/q} \leq 2^{1/p}2^{1/p}, \]
which transforms into \eqref{eq:rangeYoung2}.

\subsection{Sufficiency of the condition on \texorpdfstring{$p,q$}{p,q}}
Take $p\in(1,2)$ and $q\in(1,\infty)$ that satisfy \eqref{eq:rangeYoung2}, as the cases $q=1,\infty$ are trivial.
Replacing $f$ and $g$ with $|f|$ and $|g|$ we see that it is sufficient to work with nonnegative functions only.
Once again we proceed by the mathematical induction on the dimension $d$.
When $d=1$ estimate \eqref{eq:improvedYoung} is just \eqref{eq:twopointineqYoung} with
\[ \alpha_0 = f(0), \ \alpha_1 = f(1), \ \beta_0 = g(0), \ \beta_1 = g(1), \]
which holds in the range \eqref{eq:rangeYoung2} by Lemma \ref{lm:twopointYoung}.

In the induction step we take $d\geq 2$ and functions $f,g\colon\Z^d\to[0,\infty)$ supported in $\{0,1\}^d$.
Define $f_0,f_1,g_0,g_1,\widetilde{f},\widetilde{g}\colon\Z^{d-1}\to\mathbb{C}$ by
\begin{align*}
& f_0(x):=f(x,0), \quad f_1(x):=f(x,1), \quad g_0(x):=g(x,0), \quad g_1(x):=g(x,1), \\
& \widetilde{f}(x):=\big(f_0(x)^p + f_1(x)^p\big)^{1/p}, \quad \widetilde{g}(x):=\big(g_0(x)^p + g_1(x)^p\big)^{1/p} 
\end{align*}
for every $x\in\Z^{d-1}$.
Then $f\ast g$ is supported on $\{0,1,2\}^d$ and for each $x\in\Z^{d-1}$ we have
\begin{align*}
(f\ast g)(x,0) & = \sum_{y\in\Z^{d-1}} f_0(x-y) g_0(y), \\
(f\ast g)(x,1) & = \sum_{y\in\Z^{d-1}} \big( f_0(x-y) g_1(y) + f_1(x-y) g_0(y) \big), \\
(f\ast g)(x,2) & = \sum_{y\in\Z^{d-1}} f_1(x-y) g_1(y).
\end{align*}
The $\ell^q$-norm of $f\ast g$ will be estimated ``slice-wise,'' so first observe that Minkowski's inequality followed by \eqref{eq:twopointineqYoung} with
\[ \alpha_0 = f_0(x-y), \ \alpha_1 = f_1(x-y), \ \beta_0 = g_0(y), \ \beta_1 = g_1(y) \]
gives
\begin{align*}
& \big( (f\ast g)(x,0)^q + (f\ast g)(x,1)^q + (f\ast g)(x,2)^q \big)^{1/q} \\
& \leq \sum_{y\in\Z^{d-1}} \Big( \big( f_0(x-y) g_0(y) \big)^q + \big( f_0(x-y) g_1(y) + f_1(x-y) g_0(y) \big)^q + \big( f_1(x-y) g_1(y) \big)^q \Big)^{1/q} \\
& \stackrel{\eqref{eq:twopointineqYoung}}{\leq} \sum_{y\in\Z^{d-1}} \widetilde{f}(x-y) \widetilde{g}(y) = \big(\widetilde{f} \ast \widetilde{g}\big)(x).
\end{align*}
Finally, we take the $\ell^q$-norm in $x$ and use the induction hypothesis applied to $\widetilde{f}$ and $\widetilde{g}$:
\[ \|f\ast g\|_{\ell^q(\Z^d)} 
\leq \big\| \widetilde{f} \ast \widetilde{g} \big\|_{\ell^q(\Z^{d-1})} 
\leq \big\| \widetilde{f} \big\|_{\ell^p(\Z^{d-1})} \big\| \widetilde{g} \big\|_{\ell^p(\Z^{d-1})}
= \|f\|_{\ell^p(\Z^d)} \|g\|_{\ell^p(\Z^d)}. \]
This completes the induction step.

