\section{Proof of Lemma~\ref{lm:twopointYoung}}

For any $q\in(1,\infty)$ we consider the endpoint exponent $p=p(q)$ only, given by
\begin{equation}\label{eq:pqeqYoung}
p = \frac{2q}{\log_2(2^q+2)},
\end{equation}
i.e., $(1/p,1/q)$ is from the upper boundary of the region \eqref{eq:rangeYoung2} depicted in the right half of Figure \ref{fig:Young}. Note
\begin{equation}\label{eq:whatarepandq}
1<p<\min\{q,2\}. 
\end{equation}
Substituting
\[ a_j=\alpha_j^p, \quad b_j=\beta_j^p \]
for $j=0,1$, inequality \eqref{eq:twopointineqYoung} turns into
\[ a_0^{q/p} b_0^{q/p} + \big( a_0^{1/p} b_1^{1/p} + a_1^{1/p} b_0^{1/p} \big)^{q} + a_1^{q/p} b_1^{q/p}
\leq (a_0 + a_1)^{q/p} (b_0 + b_1)^{q/p}. \]
Since both sides are homogeneous functions of order $q/p$ in both $(a_0,a_1)$ and $(b_0,b_1)$, it is enough to show that  $G_q\colon[0,1]^2\to(0,\infty)$ defined as
\[ G_q(x,y) := (1-x)^{q/p} (1-y)^{q/p} + \big( (1-x)^{1/p} y^{1/p} + x^{1/p} (1-y)^{1/p} \big)^{q} + x^{q/p} y^{q/p} \]
satisfies
\begin{equation}\label{eq:mainineqYoung}
G_q(x,y) \leq 1 \quad \text{for every } (x,y)\in[0,1]^2;
\end{equation}
see Figure \ref{fig:funct3D} for an illustration of the particular case $q=2$.
Obviously, $G_q(0,0)=G_q(1,0)=G_q(0,1)=G_q(1,1)=1$, while the choice \eqref{eq:pqeqYoung} guarantees $G_q(1/2,1/2)=1$.
Also observe that
\[ G_q(x,y) = G_q(y,x) = G_q(1-y,1-x) \]
for $(x,y)\in[0,1]^2$, i.e., $G_q$ is symmetric about the lines $y=x$ and $y=1-x$. 

\begin{figure}
\includegraphics[width=0.55\linewidth]{dimension_funct3D.eps}
\caption{Graph of $G_2$. The maximum $1$ is attained at $(0,0)$, $(0,1)$, $(1,0)$, $(1,1)$, and $(1/2,1/2)$.}
\label{fig:funct3D}
\end{figure}

Before we begin the proof of \eqref{eq:mainineqYoung} we need to establish two elementary inequalities.

\begin{lemma}\label{lm:cosh}
For exponents $p,q$ as before and for every $t\in\R$ we have
\begin{equation}\label{eq:thetwoineq}
2^{2q/p} \bigg( \Big(\cosh\frac{pt}{2q}\Big)^{2q/p} - 1 \bigg)
\geq 2^q \bigg( \Big(\cosh\frac{t}{q}\Big)^{q} - 1 \bigg)
\end{equation}
and
\begin{equation}\label{eq:thetwoineq2}
\Big(2\cosh\frac{t}{q}\Big)^{q} > \frac{2(2q-p)}{p} \cosh\frac{pt}{q}.
\end{equation}
\end{lemma}

\begin{proof}
Note that \eqref{eq:thetwoineq} becomes an equality for $t=0$, while the hyperbolic cosine is an even function, which enables us to restrict our consideration to $t\in(0,\infty)$.
For the proof of \eqref{eq:thetwoineq} define
\[ \Phi\colon(0,\infty)^2 \to \R, \quad
\Phi(s,t) := 2^s \bigg(\Big(\cosh\frac{t}{s}\Big)^s-1\bigg), \]
so that the estimate can be written simply as
\begin{equation}\label{eq:whatweneed}
\Phi\Big(\frac{2q}{p},t\Big) \geq \Phi(q,t) \quad \text{for } t\in(0,\infty).
\end{equation}
For $s>2$ and $t>0$ differentiation gives 
\[ 2^{-s} \partial_s\Phi(s,t)
= \Big(\cosh\frac{t}{s}\Big)^s \bigg( \ln\Big(2\cosh\frac{t}{s}\Big) - \frac{t}{s} \tanh\frac{t}{s} \bigg) - \ln 2
\geq \varphi\Big(\frac{t}{s}\Big), \]
where $\varphi\colon[0,\infty)\to\R$ is now a concrete one-dimensional function, 
\[ \varphi(u) := (\cosh u)^2 \big( \ln(2\cosh u) - u \tanh u \big) - \ln 2. \]
It is easily seen to be positive on $(0,\infty)$, because
\begin{align*}
& \varphi(0)=0, \quad 
\varphi'(u) = \sinh(2u) \gamma(u), \quad 
\gamma(u) := \ln(2\cosh u)-u\coth(2u), \\ 
& \gamma'(u) = \frac{2u-\sinh(2u)}{(\sinh(2u))^2}<0, \quad 
\lim_{u\to 0^+}\gamma(u)=\ln 2-\frac{1}{2} > 0, \quad 
\lim_{u\to\infty}\gamma(u) =0
\end{align*}
imply $\gamma(u)>0$, $\varphi'(u)>0$, and then also $\varphi(u)>0$ for every $u\in(0,\infty)$.
Thus, $s\mapsto\Phi(s,t)$ is increasing on $[2,\infty)$ for any fixed $t>0$.
Since 
\[ \frac{2q}{p} \stackrel{\eqref{eq:whatarepandq}}{>} \max\{q,2\}, \]
we are done proving \eqref{eq:whatweneed} in the case $q\geq 2$, while in the case $1<q<2$ we still need to show
\[ \Phi(2,t) \geq \Phi(q,t) \quad \text{for } t\in(0,\infty). \]
However,
\[ \Phi(2,t) = 4 \bigg(\Big(\cosh\frac{t}{2}\Big)^2-1\bigg) = 2 (\cosh t - 1) = \Phi(1,t) \]
and it is again natural to substitute $u=t/q$, so it remains to see that 
\[ \eta(q,u) := \Phi(1,qu) - \Phi(q,qu) 
= 2 (\cosh(qu) - 1) - 2^q \big( (\cosh u)^q-1 \big) \]
is always nonnegative when $1<q<2$ and $u>0$. Here we have $\eta(q,0)=0$,
\[ \partial_u \eta(q,u) = 2q\sinh(qu) - 2^q q (\cosh u)^{q-1} \sinh u, \]
and it is sufficient to verify $\partial_u \eta(q,u)\geq 0$ for $u>0$, but this is equivalent to
\begin{equation}\label{eq:thelastphi}
\phi(q,u) := \ln\sinh(qu) - (q-1)\ln(2\cosh u) - \ln\sinh u \geq 0. 
\end{equation}
Finally,
\[ \partial_q^2 \phi(q,u) = - \Big(\frac{u}{\sinh(qu)}\Big)^2 \leq 0, \]
so $q\mapsto\phi(q,u)$ is concave on $[1,2]$ for a fixed $u>0$ and then
\[ \phi(1,u) = 0, \quad \phi(2,u) = \ln\frac{\sinh(2u)}{2\cosh u \sinh u} = 0 \]
imply that \eqref{eq:thelastphi} holds for every $q\in(1,2)$ and $u\in(0,\infty)$, completing the proof of \eqref{eq:thetwoineq}.

For the proof of \eqref{eq:thetwoineq2}, we fix $p,q\in(1,\infty)$ related by \eqref{eq:pqeqYoung}, recalling the right image in Figure \ref{fig:Young}. Note that the assignment $q\mapsto p(q)$ actually makes sense for all $q\in(0,\infty)$ and we can compute
\begin{equation}\label{eq:expprimeeq}
p'(q) = \frac{p}{q} \Big( 1 - \frac{p 2^q}{2(2^q + 2)} \Big), \quad p'(1)=\frac{3}{4}.
\end{equation}
Substitute $u=t/q$, transforming \eqref{eq:thetwoineq2} into
\begin{equation}\label{eq:thetwoineq2b}
\big(2\cosh u\big)^q > \frac{2(2q-p)}{p} \cosh(p u).
\end{equation}
Taking logarithms and defining $\widetilde{\Phi}\colon(0,\infty)\times[0,\infty)\to\R$ as
\[ \widetilde{\Phi}(q,u) := q\ln\cosh u - \ln\cosh(pu) + \ln\frac{p 2^{q-1}}{2q-p}, \]
the desired inequality \eqref{eq:thetwoineq2b} becomes 
$\widetilde{\Phi}(q,u)>0$ for $q>1$ and $u\geq0$.

Let us begin with the case of exponents satisfying $p^2\leq q$.
Observe
\begin{align*} 
\partial_u\widetilde{\Phi}(q,u) & = q \tanh u - p \tanh(pu) \\
& = p (\tanh u) \Big(\frac{q}{p} - \frac{\tanh(pu)}{\tanh u}\Big),
\end{align*}
that $u\mapsto \tanh(pu) / \tanh u$ is strictly decreasing, which follows from
\[ \frac{\textup{d}}{\textup{d}u} \ln\frac{\tanh(pu)}{\tanh u}
= \frac{2p}{\sinh(2pu)} - \frac{2}{\sinh(2u)} < 0, \]
and that
\[ \lim_{u\to0^+}\frac{\tanh(pu)}{\tanh u} = p, \quad \lim_{u\to\infty}\frac{\tanh(pu)}{\tanh u} = 1. \]
Since $q/p\geq p$, we see that $u\mapsto\widetilde{\Phi}(q,u)$ is strictly increasing on $[0,\infty)$, so
\[ \widetilde{\Phi}(q,0) = \ln \frac{2^{q-1}p}{2q-p} \stackrel{\eqref{eq:pqeqYoung}}{=} \ln \frac{2^{q-1}}{\log_2(2^{q-1}+1)} > 0 \]
implies that $\widetilde{\Phi}(q,u)$ is positive for $u>0$ as well, and \eqref{eq:thetwoineq2b} is confirmed.

Now we turn to the case $p^2>q$, which easily implies $q<4$ and this is all that we need in what follows.
Using \eqref{eq:expprimeeq} and differentiating once again we easily estimate\footnote{Reliable optimization of one-dimensional functions (with no other variables or parameters) is never a difficulty for Mathematica \cite{Mathematica}. Also see the very last part of the proof for an example of how (even higher-dimensional) concrete inequalities can be verified $100\%$ rigorously.} 
\begin{equation}\label{eq:expprimeineq}
0 < p'(q) \leq \frac{3p}{4q}, \quad \frac{2p}{5q^2} < -p''(q) < \frac{4p}{5q^2}
\end{equation}
for $1\leq q\leq4$.
Positivity of $\widetilde{\Phi}(q,u)$ for $q>1$ will follow from $\widetilde{\Phi}(1,u)=0$ once we can prove
\begin{equation}\label{eq:weneedPhi}
\partial_q \widetilde{\Phi}(q,u) > 0
\end{equation}
for $q\in(1,4)$ and $u\in[0,\infty)$.
Note that
\[ \partial_q \widetilde{\Phi}(q,u) = \widetilde{\eta}(q,u) + \frac{2}{2q-p}  \Big(p'(q)\frac{q}{p} - 1 \Big) + \ln 2, \]
where
\[ \widetilde{\eta}(q,u) := \ln\cosh u - p'(q) u \tanh (pu). \]
Furthermore,
\[ \partial_q \widetilde{\eta}(q,u) = - p''(q) u \tanh (pu) - p'(q)^2 \frac{u^2}{(\cosh (pu))^2} \stackrel{\eqref{eq:expprimeineq}}{\geq} \frac{1}{q^2}\widetilde{\varphi}(pu), \]
where $\widetilde{\varphi}$ is a concrete one-dimensional function given by
\[ \widetilde{\varphi}(s) := \frac{2}{5}s\tanh s - \frac{s^2}{(\cosh s)^2}. \]
It is easily seen that $\widetilde{\varphi}(s) \geq 0$ for $s\geq3$, which then implies $\partial_q \widetilde{\eta}(q,u)\geq0$ for $1<q<4$ and $u\geq 3$, and thus also
\begin{align*} 
\widetilde{\eta}(q,u) & \geq \widetilde{\eta}(1,u)  
\stackrel{\eqref{eq:expprimeeq}}{=} \ln\cosh u - \frac{3}{4} u \tanh u > 0
\end{align*}
for $q\in(1,4)$ and $u\in[3,\infty)$, by an easy one-dimensional optimization in $u$.
Finally,
\[ \partial_q \widetilde{\Phi}(q,u) \geq - \frac{p 2^q}{(2q-p)(2^q+2)} + \ln 2 \]
and yet another one-dimensional optimization, this time in $1\leq q\leq 4$, shows that this is always strictly positive, confirming \eqref{eq:weneedPhi} for $u\geq3$.

In the last part of the proof we verify \eqref{eq:weneedPhi} when $q\in[1,4]$ and $u\in[0,3]$.
Mathematica can perform numerical optimization of $\partial_q \widetilde{\Phi}(q,u)$ over $(q,u)\in[1,4]\times[0,3]$, computing its minimal value as
\[ 0.0293596409\ldots > \frac{1}{50}, \]
but this might not be completely rigorous. Thus, we rather reduce the desired strict inequality to finitely many single-number inequalities corresponding to nodes of a subdivision of that square.
We compute
\begin{align*}
\partial_q^2 \widetilde{\Phi}(q,u) & = - p''(q) u \tanh(pu) - p'(q)^2 \frac{u^2}{(\cosh(pu))^2} + p''(q) \frac{2q}{p(2q-p)} \\
& \quad - p'(q)^2 \frac{4q(q-p)}{p^2(2q-p)^2} + \frac{4}{(2q-p)^2}\big(1-p'(q)\big), \\
\partial_u \partial_q \widetilde{\Phi}(q,u) & = -p'(q) \tanh(pu) - p'(q) \frac{pu}{(\cosh(pu))^2} + \tanh u.
\end{align*}
Using \eqref{eq:expprimeineq} we easily get
\[ |\partial_q^2 \widetilde{\Phi}(q,u)| \leq 7,
\quad |\partial_u \partial_q \widetilde{\Phi}(q,u)| \leq 3 \]
for $1\leq q\leq 4$ and $0\leq u\leq 3$.
Thus, $(q,u)\mapsto\partial_q \widetilde{\Phi}(q,u)$ is a Lipschitz function on the square $[1,4]\times[0,3]$ with explicit horizontal and vertical Lipschitz constants, so it is sufficient to verify $\partial_q \widetilde{\Phi}(q,u)> 1/50$ on the two-dimensional subdivision
\[ \Big\{ (q,u) = \Big(1+\frac{i}{700},\frac{j}{300}\Big) \,:\, i\in\{0,1,2,\ldots,2100\},\ j\in\{0,1,2,\ldots,900\} \Big\}. \]
This is easily done in Mathematica, using the exact expressions and not just numerical approximations. It completes the proof of \eqref{eq:weneedPhi} and thus also that of \eqref{eq:thetwoineq2b}.
\end{proof}

\begin{lemma}\label{lm:boundary antidiagonal}
It holds that $G_q(x,y)\leq 1$ on the boundary of $[0,1]^2$ and on the anti-diagonal line $y=1-x$. 
\end{lemma}
\begin{proof}
Regarding the boundary, due to the symmetries of $G_q$ it is sufficient to consider the left side of the square. Substituting $x=0$ into $G_q(x,y)$ and using $q/p>1$ we obtain
\[ G_q(0,y) = (1-y)^{q/p} + y^{q/p} \leq (1-y) + y = 1. \]

Regarding the anti-diagonal of $[0,1]^2$, the goal is to establish
\[ G_q(x,1-x) = \big((1-x)^{2/p}+x^{2/p}\big)^q+2(1-x)^{q/p}x^{q/p}\leq 1 \]
for $x\in(0,1)$. 
Substituting 
\[ x = \frac{1}{1 + e^{pt/q}}, \quad t\in\R, \]
this estimate transforms into
\[ \big( e^{pt/q} + 1 \big)^{2q/p} \geq \big( e^{2t/q} + 1 \big)^{q} + 2 e^t \]
and, dividing by $e^t$, into
\[ \big( e^{pt/(2q)} + e^{-pt/(2q)} \big)^{2q/p} \geq \big( e^{t/q} + e^{-t/q} \big)^q + 2, \]
i.e.,
\[ \Big( 2 \cosh \frac{pt}{2q} \Big)^{2q/p} \geq \Big( 2 \cosh \frac{t}{q} \Big)^q + 2. \]
Finally note that \eqref{eq:pqeqYoung} can be rewritten as
$2^{2q/p} - 2^q = 2$,
so the last inequality is precisely the first of the two inequalities from Lemma \ref{lm:cosh}, namely \eqref{eq:thetwoineq}.
\end{proof}

In the rest of the proof, let us consider points $(x,y)$ in the open lower-right triangle with anti-diagonal removed,
\[ \Delta:=\big\{(x,y)\in (0,1)^2: y\leq x,\, y\not = 1-x\big\}, \]
shaded in Figure \ref{fig:two_max}.
Suppose now, for contradiction, that there exists a point $(x_{\max},y_{\max})\in \Delta$ at which $G_q$ attains a local maximum.\footnote{Again, one may further assume $G_q(x_{\max},y_{\max})>1$ in order to achieve the goal, but the argument in fact yields a stronger conclusion: $G_q$ cannot attain a local maximum in $\Delta$ at all.}
We analyze $G_q$ along curves 
\begin{equation}\label{e:dissecting curve}
\Theta_a := \Big\{ (x,y)\in(0,1)^2 \,:\, \frac{y}{1-y}=a\frac{x}{1-x} \Big\}
\end{equation}
for $0<a\leq 1$.
These curves are easily seen to partition the triangle $0<y\leq x<1$.
Remark \ref{rem:thePDE} will motivate this unusual choice of curves, but they also reflect the structure of $G_q$.
Simplifying the formula, we can write the equation of $\Theta_a$ as
\[ y=\theta_a(x):=\frac{ax}{1-x+ax}. \]

Choose $a\in (0,1]$ so that the curve passes through the point $(x_{\max},y_{\max})\in \Delta$. By the symmetry of both $G_q$ and $\Theta_a$, the reflected point $(x_{\max}',y_{\max}')\in \Delta$, obtained by mirroring across the line $y=1-x$, must also be a local maximum of $G_q$. Therefore, the one-dimensional function $G_q\vert_{\Theta_a}$ defined along the curve also has at least two local maxima in $\Theta_a\cap\Delta$. 
Moreover, by direct computation in Mathematica we see that
\[ \lim_{x\to0^+} \frac{\textup{d}}{\textup{d} x}G_q(x,\theta_a(x)) = -\frac{q}{p}(1+a) < 0. \]
Also note that $y=\theta_a(x)$ intersects $y=1-x$ at the point with $x$-coordinate $1/(1+\sqrt{a})$. 
We want to verify
\begin{equation}\label{eq:centralmaxofGq}
\frac{\textup{d}^2}{\textup{d} x^2}\Big\vert_{x=1/(1+\sqrt{a})} G_q(x,\theta_a(x)) < 0
\end{equation}
and Mathematica can easily compute this second derivative as
\[ \frac{2q}{p} a^{(q-p)/(2p)} \big(1+\sqrt{a}\big)^{2(p-q)/p}
\Big( -\big( a^{-1/(2p)} + a^{1/(2p)} \big)^q + \frac{q}{p} \big( a^{-1/2} + a^{1/2} \big) + \frac{2(q-p)}{p} \Big). \]
Then we perform the substitution
\[ a = e^{-2pt/q}, \quad t\in[0,\infty), \]
to see that \eqref{eq:centralmaxofGq} is equivalent with
\[ - \Big(2\cosh\frac{t}{q}\Big)^q + \frac{2q}{p} \cosh\frac{pt}{q} + \frac{2(q-p)}{p} < 0. \]
However, this is an immediate consequence of \eqref{eq:thetwoineq2} from Lemma \ref{lm:cosh} because $\cosh(pt/q)\geq1$.

All this and the symmetry of $G_q$ about $y=1-x$ imply that $G_q\vert_{\Theta_a}$ is decreasing\footnote{Monotonicity is considered with respect to the natural orientation of $\Theta_a$, from $(0,0)$ to $(1,1)$.} near $(0,0)$, increasing near $(1,1)$, and has yet another local maximum at the intersection of $\Theta_a$ with the anti-diagonal; see Figure~\ref{fig:two_max}. Consequently, $G_q\vert_{\Theta_a}$ must also attain at least four local minima, so, altogether, $G_q\vert_{\Theta_a}$ is stationary at at least seven points of $\Theta_a$ depicted in Figure~\ref{fig:two_max}.
In what follows, we show that such behavior is impossible, even under the most intricate scenario. 

We employ a similar argument to the one used in the proof of inequality \eqref{eq:mainineq}, but carried out at a deeper level: we analyze $x\mapsto G_q(x,\theta_a(x))$ by repeatedly differentiating, factoring the expression, and isolating the nontrivial factor.
We repeat this process until the remaining expression becomes sufficiently simple to analyze.

