 \section{Lie skew braces, post-Lie groups, post-Lie algebras and affine actions}\label{secLSB}
\subsection{Lie skew braces}
Let \( (G, \cdot, \circ) \) be a Lie skew brace (LSB), meaning that \( (G, \cdot) \) and \( (G, \circ) \) are real Lie groups sharing the same  smooth manifold structure, and such that the identity  
\begin{equation} \label{eqLSB}
a \circ (b \cdot c) = (a \circ b) \cdot a^{-1} \cdot (a \circ c)
\end{equation}
holds for all \( a, b, c \in G \), where \(a^{-1}\) denotes the inverse of \(a\) in the group \((G, \cdot)\). 
From this it follows that the two groups also share they same identiity element denoted here by $e$.
One can then define the category \( \mathbf{LSB} \), whose \emph{objects} are LSBs, and whose \emph{morphisms} between two LSBs  
\((G_1, \cdot_1, \circ_1)\) and \((G_2, \cdot_2, \circ_2)\) are \emph{LSB homomorphisms}, that is, smooth maps \( \varphi: G_1 \to G_2 \) such that
\[
\varphi(a \cdot_1 b) = \varphi(a) \cdot_2 \varphi(b) \quad \text{and} \quad \varphi(a \circ_1 b) = \varphi(a) \circ_2 \varphi(b)
\]
for all \( a, b \in G_1 \).

The category of  \( \mathbf{LSB} \)  forms a \emph{subcategory} of 
\emph{left skew braces}, as defined in \cite{Guarnieri2017} (in the purely algebraic sense, without requiring a Lie group structure), namely the category consisting of those objects and morphisms where the group operations are considered on underlying sets rather than smooth manifolds.
Indeed, all the results described in this subsection are natural extensions to the smooth case of those established for left skew braces in the algebraic setting, as presented in \cite{Guarnieri2017}.

\begin{example}\label{exLSBtriv} (cf. \cite[Ex. 1.3 ]{Guarnieri2017})
Let \( (G, \cdot) \) be a real Lie group. Define \( a \circ b = a\cdot b \) for all \( a, b \in G \). Then \( (G, \cdot, \circ) \) is a LSBs. Similarly, defining \( a \circ b = b\cdot  a\) also yields a LSB structure on \( G \).
These LSBs are isomorphic if and only if $(G, \cdot)$ is abelian. For our aim these LSBs
are not interesting since in both cases  $(G, \cdot)\cong (G, \circ)$.
\end{example}


\begin{example} \label{exLSBprod}
Let \( (G_1, \cdot_1, \circ_1) \) and \( (G_2, \cdot_2, \circ_2) \) be two LSBs. Then the triple
\[
(G_1 \times G_2, \cdot, \circ)
\]
is also a LSB, where the operations are defined componentwise by
\[
(a_1, b_1) \cdot (a_2, b_2) := (a_1 \cdot_1 a_2,\; b_1 \cdot_2 b_2), \quad
(a_1, b_1) \circ (a_2, b_2) := (a_1 \circ_1 a_2,\; b_1 \circ_2 b_2),
\]
for all \( a_1, a_2 \in G_1 \) and \( b_1, b_2 \in G_2 \).
This LSB is referred to as the \emph{direct product} of the LSBs \( (G_1, \cdot_1, \circ_1) \) and \( (G_2, \cdot_2, \circ_2) \).
\end{example}

\begin{example} \label{exLSBzappa} (cf.\ \cite[Ex.~1.6]{Guarnieri2017}) 
Let \( G \) be a real Lie group admitting a factorization \( G = G_1 G_2 \), where \( G_1 \) and \( G_2 \) are Lie subgroups such that \( G_1 \cap G_2 = \{1\} \). 
 In particular, every element \( a \in G \) can be uniquely written as \( a = a_1\cdot a_2 \) for some \( a_1 \in G_1 \), \( a_2 \in G_2 \).
This factorization allows us to define a new group operation \( \circ \) on the underlying manifold of \( G \), as follows: for any \( a, b \in G \), let \( a = a_1\cdot a_2 \), with \( a_1 \in G_1 \) and  \( a_2 \in G_2 \)  . Then define
\[
a \circ b := a_1 \cdot b \cdot a_2.
\]
With this operation, the triple \( (G, \cdot, \circ) \) becomes a LSB. 
Indeed the map
\[
\Phi: G_1 \times G_2 \longrightarrow G, \quad (a_1,a_2) \mapsto a_1 \cdot a_2^{-1}
\]
is a Lie group isomorphism between $(G, \circ )$ and the direct product $G_1\times G_2$.
\end{example}


\vskip 0.3cm

Let \((G, \cdot) \) be a connected real Lie group. The group of Lie group automorphisms of \( G \), denoted \( \mathrm{Aut}(G, \cdot) \), consists of all Lie group isomorphisms of \( G \), i.e.  smooth group homomorphisms from \( G \) to itself with smooth inverses. When endowed with the subspace topology induced by the inclusion
\[
\mathrm{Aut}(G, \cdot) \subset C^0(G, G),
\]
where \( C^0(G, G) \) is the space of continuous maps from \( G \) to itself equipped with the compact-open topology, the group \( \mathrm{Aut}(G, \cdot) \) becomes a real Lie group of finite dimension. For further details, see \cite{Hochschild1952aut} and \cite{Dani1992}.


\begin{example} \label{exLSBrevzappa}
Let \( G_1 \) and \( G_2 \) be connected real Lie groups, and let 
\[
\alpha : G_2 \to \mathrm{Aut}(G_1)
\]
be a Lie group homomorphism. Then the set \( G_1 \times G_2 \), endowed with the usual componentwise group operation
\[
(a_1, b_1) \cdot (a_2, b_2) := (a_1 \cdot a_2,\, b_1 \cdot b_2),
\]
and with the twisted operation
\[
(a_1, b_1) \circ_{\alpha} (a_2, b_2) := \left( a_1 \cdot \alpha(b_1)(a_2),\; b_1 \cdot b_2 \right),
\]
forms a LSB \( (G_1 \times G_2, \cdot, \circ_{\alpha}) \).
Here, \( (G_1 \times G_2, \circ_{\alpha}) \) is precisely the {\em semidirect product} Lie group \( G_1 \rtimes_{\alpha} G_2 \). 

%When we write \( G = G_1 \rtimes G_2 \), we mean that \( G = G_1 G_2 \), \( G_1 \trianglelefteq G \), and \( G_1 \cap G_2 = \{e\} \), and the map 
%$
%\alpha : G_2 \to \mathrm{Aut}(G_1)
%$
%is not written explicitly, since it is uniquely determined by conjugation in \( G \); that is,
%\[
%\alpha(b)(a) := b a b^{-1}, \quad \text{for all } a \in G_1,\ b \in G_2.
%\]
\end{example}






\vskip 0.3cm

\begin{definition}
The  {\em affine group}\footnote{Some authors, especially in the context of finite groups, but also occasionally in the Lie group setting (see e.g., \cite{Wu1986}),  refer to $\mathrm{Aff}(G)$
as the  \emph{holomorph} of $G$,  and denote it by \( \mathrm{Hol}(G) \) instead of \( \mathrm{Aff}(G) \).}
associated to a connected Lie group  \( (G, \cdot) \) is the Lie group given by the semidirect product
\[
\mathrm{Aff}(G, \cdot) = (G, \cdot) \rtimes \mathrm{Aut}(G, \cdot),
\]
where  \( \mathrm{Aut}(G, \cdot) \)  acts on \( G\) by evaluation; that is, for \( f\in \mathrm{Aut}(G, \cdot) \) and \( a \in G \), the action is given by evaluation.
\end{definition}

The group operation on \( \mathrm{Aff}(G, \cdot) \) is then given by
\[
(a, f) (b, g) = (a \cdot f(b), f  g),
\]
for all \( a, b \in G \), \( f, g \in \mathrm{Aut}(G, \cdot) \).
Any subgroup $H$ of $\mathrm{Aff}(G, \cdot)$ acts smoothly  on $G$:
$$(x, f)a=x\cdot f(a),\  a\in G, (x, f)\in H.$$

In particular $\mathrm{Aff}(G, \cdot)$ acts transitively on $G$ and the stabilizer 
of any $a\in G$ is a Lie subgroup of  $\mathrm{Aff}(G, \cdot)$ isomorphic (as Lie group)
 to $G$.


\begin{definition}\label{regsubgroup}
Let $(G, \cdot)$ be a connected Lie group.
A subgroup \( H \subseteq \mathrm{Aff}(G, \cdot) \) is said to be \emph{regular}
if for each  $a\in G$ there exists a unique $(x, f)\in H$  such that $x\cdot f(a)=1$.
\end{definition}


 Notice that if $H$ is a regular subgroup of  $\mathrm{Aff}(G, \cdot)$ then it is not hard to see that   the projection  \( \pi_1 : \mathrm{Aff}(G) \to G \) on the first factor, when restricted to \( H \), is a bijection (see \cite[Lemma 4.1]{Guarnieri2017}).
It follows that $H$ is a closed subset of 
\( \mathrm{Aff}(G, \cdot) \), and therefore \( H \) is a Lie subgroup of \( \mathrm{Aff}(G, \cdot) \). 
In fact, \( H = ({\pi_1}{|_H})^{-1}(G) \).
Since \( \pi_1 \) is a continuous (even smooth) map and \( G \subseteq \mathrm{Aff}(G, \cdot) \cong G \times \mathrm{Aut}(G, \cdot) \) is a closed submanifold, it follows that \( H \) is closed as the preimage of a closed set under a continuous map.


\vskip 0.3cm

Now, let us fix a LSB \( (G, \cdot, \circ) \). Define the  \emph{lambda-action}
\begin{equation}\label{lambda}
\lambda: (G, \circ) \to \mathrm{Aut}(G, \cdot), \quad a \mapsto \lambda_a,
\end{equation}
where
\begin{equation}\label{lambdaspec}
\lambda_a(b) = a^{-1}\cdot (a \circ b), \quad \forall b \in G.
\end{equation}
It is easily seen (see, e.g.,  \cite[Corollary 1.10]{Guarnieri2017}, that $\lambda$ is a group homomorphism. This action is particularly important, as it expresses the group operations \(\circ\) in terms of \(\cdot\), and viceversa:
$$a \circ b = a\cdot \lambda_a(b), \quad a\cdot b = a \circ \lambda_{\overline{a}}(b), \forall a, b \in G,$$
where \(\overline{a}\) denotes the inverse of \(a\) in the group \((G, \circ)\)

The following lemma shows that $\lambda$  is indeed a Lie group homomorphism. 


\begin{lemma} \label{lambdasmooth}
Let \( (G, \cdot, \circ) \) be a LSB.
Then the map \( \lambda \) is smooth.
\end{lemma}

\begin{proof}
Since both \( (G, \cdot) \) and \( \mathrm{Aut}(G, \cdot) \) are Lie groups, and \( \lambda \) is a group homomorphism, it suffices to prove that \( \lambda \) is continuous.
Observe that, by \eqref{lambdaspec} and the fact that the group operations on \( (G, \cdot) \) and \( \mathrm{Aut}(G, \cdot) \) are continuous (in fact, smooth), the map
\[
\tilde{\lambda} \colon G \times G \to G, \quad (a, b) \mapsto \lambda_a(b)
\]
is continuous.

Now, since any Lie group is a locally compact topological space, it follows from \cite[Theorem 46.11]{Munkres2000topology} that for each \( a \in G \), the map
\[
\lambda \colon G \to  \mathrm{Aut}(G, \cdot)\subset C^0(G, G), \quad a \mapsto \lambda_a
\]
is continuous when \( \mathrm{Aut}(G, \cdot) \) is viewed as a subspace of \( C^0(G, G) \) with the compact-open topology. This completes the proof.
\end{proof}

The connection between LSBs and regular subgroups of the affine group is expressed by the following proposition, which generalizes the classical correspondence for skew left braces (see \cite[Th.~4.2 and Prop.~4.3]{Guarnieri2017}). We sketch the proof in the smooth setting.

\begin{proposition}\label{proplambda}
Let \( (G, \cdot) \) be a connected real Lie group. Then there is a one-to-one correspondence between:
\begin{itemize}
    \item LSBs structures \( (G, \cdot, \circ) \), and
    \item regular Lie subgroups \( H \leq \mathrm{Aff}(G, \cdot) \),
\end{itemize}
such that \( (G, \circ) \simeq H \) as Lie groups. Moreover, two LSB structures on \( G \) are isomorphic if and only if the corresponding regular subgroups are conjugate in \( \mathrm{Aff}(G, \cdot) \) via an element of \( \mathrm{Aut}(G, \cdot) \).
\end{proposition}

\begin{proof}
Suppose \( (G, \cdot, \circ) \) is a LSB. Define the regular Lie subgroup  \( H = \{ (a, \lambda_a) \mid a \in G \} \leq \mathrm{Aff}(G, \cdot) \), where $\lambda_a$ given by \eqref{lambdaspec}.  The map
\[
\Psi \colon G \to H, \quad a \mapsto (a, \lambda_a)
\]
is a group homomorphism from \( (G, \circ) \) to \( H \), since
\[
\Psi(a \circ b) = (a \lambda_a(b), \lambda_{a \circ b}) = (a, \lambda_a)(b, \lambda_b) = \Psi(a)\Psi(b).
\]
Smoothness of \( \lambda \) (cf.\ Lemma~\ref{lambdasmooth}) ensures that \( \Psi \) is a diffeomorphism, and hence \( H \) is a regular Lie subgroup of \( \mathrm{Aff}(G, \cdot) \),  isomorphic to \( (G, \circ) \) as a Lie group.

Conversely, let \( H \subseteq \mathrm{Aff}(G, \cdot) \) be a regular Lie subgroup. Then the projection \( \pi_1|_H \colon H \to G \) is a diffeomorphism. Transporting the group law of \( H \) to \( G \) via this diffeomorphism defines a smooth operation \( \circ \), given by
\[
a \circ b := \pi_1\left( (\pi_1|_H)^{-1}(a) \cdot (\pi_1|_H)^{-1}(b) \right)=a\cdot f(b),
\]
where \( (\pi_1|_H)^{-1}(a) = (a, f) \). It follows that \( (G, \circ) \) is a Lie group and (a direct computation shows that) \( (G, \cdot, \circ) \) is a LSB.

The final assertion concerning the correspondence between isomorphism classes of LSBs and conjugacy classes of regular subgroups is of algebraic nature and can be found in  \cite[Prop.~4.3]{Guarnieri2017}. The proof is omitted.
\end{proof}



\subsection{Post-Lie groups}\label{postandLSB}
We recall the definition of a  post-Lie group given in \cite{Bai2023}. 

\begin{definition}\label{defpostliegroup}
    A post Lie group is a triple $(G,\cdot,\triangleright)$ where $(G,\cdot)$ is a real  Lie group and $\triangleright: G \times G \rightarrow G$ is a smooth map such that: 
    \begin{enumerate}
        \item 
        For every $a \in G$ the map 
        \begin{equation}\label{Ltriangle}
        L^{\triangleright}_{a}:G \rightarrow  G, b \mapsto  L^{\triangleright}_{a}(b):=a \triangleright b
        \end{equation} 
        is an automorphism of $(G, \cdot)$, i.e. $L^{\triangleright}_{a}(b\cdot c)=(a \triangleright b)\cdot (a \triangleright c)$, for all $a,b,c \in G$;
        \item For all $a,b,c \in G$,
        $$(a \cdot (a \triangleright b)) \triangleright c= a \triangleright ( b \triangleright c).$$
    \end{enumerate}
\end{definition}
Given two post Lie groups $(G_1,\cdot_1,\triangleright_1),(G_2,\cdot_2,\triangleright_2)$ a smooth map $\Phi: G_1 \rightarrow G_2$ is said to be an homomorphism between the post Lie groups $(G_1,\cdot_1,\triangleright_1)$ and $(G_2,\cdot_2,\triangleright_2)$, if for every $a,b \in G_1$ we have $\Phi(a \cdot_1 b)=\Phi(a) \cdot_2 \Phi(b)$ and $\Phi(a \triangleright_1 b)=\Phi(a) \triangleright_2 \Phi(b)$.
Therefore we can speak about the category of post-Lie group $\mathbf{PLG}$, 
whose objects are post-Lie groups and whose morphisms are homomorphisms between the post-Lie groups.
\begin{proposition}
The categories $\mathbf{LSB}$ and $\mathbf{PLG}$ are isomorphic.
\end{proposition}

\begin{proof}
As shown in \cite[Prop. 3.22]{Bai2023}, there is a functor
\[
F: \mathbf{PLG} \rightarrow \mathbf{LSB}, \quad (G,\cdot, \triangleright) \mapsto (G,\cdot,\circ)
\]
where for all \(a,b \in G\) the operation \(\circ\) is defined algebraically by
\[
a \circ b := a \cdot (a \triangleright b).
\]

Conversely, by \cite[Thm 3.24]{Bai2023}, one defines a functor
\[
G: \mathbf{LSB} \rightarrow \mathbf{PLG}, \quad (G,\cdot, \circ) \mapsto (G,\cdot,\triangleright)
\]
where, for all \(a,b \in G\), the post-Lie product is given by
\[
a \triangleright b := \lambda_a(b),
\]
with \(\lambda_a(b)\) defined by \eqref{lambdaspec}.
Since, by Lemma \ref{lambdasmooth}, \(\lambda: G  \to \mathrm{Aut}(G, \cdot)\)  is smooth, this construction is well-defined in the category of smooth manifolds. 
Finally, by \cite[Thm 3.25]{Bai2023}, the two functors \(F\) and \(G\) are mutually inverse. Therefore, the categories \(\mathbf{LSB}\) and \(\mathbf{PLG}\) are isomorphic.
\end{proof}

\subsection{Post-Lie algebras}\label{subsecPLA}
Although the correspondence between Lie groups and Lie algebras is classical and well known, we briefly recall it here to fix notation.
Given any Lie group \( (G, \cdot) \), there is an associated Lie algebra \( \mathrm{Lie}(G, \cdot) = (\mathfrak{g}, [\cdot,\cdot]_{\cdot}) \), defined as the tangent space \( T_eG \) at the identity element \( e \), endowed with the Lie bracket induced by the left-invariant vector fields on \( G \).
Conversely, for every finite-dimensional real Lie algebra \( (\mathfrak{g}, [\cdot,\cdot]) \), there exists a real Lie group \( (G, \cdot) \) whose Lie algebra is \( (\mathfrak{g}, [\cdot,\cdot]_{\cdot}) \). In fact, such a group \( G \) can be obtained as a quotient of the unique simply-connected Lie group integrating \( (\mathfrak{g}, [\cdot,\cdot]) \).



\begin{definition} \label{postLieAlgebras}
    A \emph{post-Lie algebra} (PLA) is a  quadruple \( (\mathfrak{g}, [\cdot,\cdot]_{\cdot}, [\cdot,\cdot]_{\circ},  \triangleright )\) such that both \( (\mathfrak{g}, [\cdot,\cdot]_{\cdot}) \) and \( (\mathfrak{g}, [\cdot,\cdot]_{\circ}) \) are real Lie algebras (on the same finite dimensional real vector space $\mathfrak{g}$), and     \[
    \triangleright: \mathfrak{g} \times \mathfrak{g} \rightarrow \mathfrak{g}, \quad (\zeta,\eta) \mapsto \zeta \triangleright \eta,
    \]
    is a   bilinear map, called the {\em post-Lie product}, 
    satisfying the following identities for all \( \zeta, \eta, \gamma \in \mathfrak{g} \):
    \begin{enumerate}
        \item \( [\zeta,\eta]_{\circ} - [\zeta,\eta]_{\cdot} = \zeta \triangleright \eta - \eta \triangleright \zeta \),
        \item \( \zeta \triangleright [\eta,\gamma]_{\cdot} = [\zeta \triangleright \eta,\gamma]_{\cdot} - [\eta, \zeta \triangleright \gamma]_{\cdot} \),
        \item \( [\zeta,\eta]_{\circ} \triangleright \gamma = \zeta \triangleright (\eta \triangleright \gamma) - \eta \triangleright (\zeta \triangleright \gamma) \).
    \end{enumerate}
\end{definition}

\begin{remark}
 Notice that  by (1) in Definition \ref{postLieAlgebras} the Lie algebra structure  $[\cdot,\cdot]_{\circ}$
 is uniquely determined by the pair $([\cdot,\cdot]_{\cdot},  \triangleright)$.
 Hence, one can also define (see, e.g. \cite{Bai2023} and  \cite{Burde2012affineaction}) a PLA as a triple 
 \( (\mathfrak{g}, [\cdot,\cdot]_{\cdot}, \triangleright) \), where \( (\mathfrak{g}, [\cdot,\cdot]_{\cdot}) \) is a real Lie algebra and 
    \[
    \triangleright: \mathfrak{g} \times \mathfrak{g} \to \mathfrak{g}, \quad (\zeta,\eta) \mapsto \zeta \triangleright \eta
    \]
    is a bilinear map satisfying:
    \begin{enumerate}
        \item \( \zeta \triangleright [\eta,\gamma]_{\cdot} = [\zeta \triangleright \eta, \gamma]_{\cdot} - [\eta, \zeta \triangleright \gamma]_{\cdot} \),
        \item \( ([\zeta,\eta]_{\cdot} + \zeta \triangleright \eta - \eta \triangleright \zeta) \triangleright \gamma = \zeta \triangleright (\eta \triangleright \gamma) - \eta \triangleright (\zeta \triangleright \gamma) \).
    \end{enumerate}
    Then one defines the so-called \emph{sub-adjacent Lie algebra} \( (\mathfrak{g}, [\cdot,\cdot]_{\circ}) \) via
    \[
    [\zeta,\eta]_{\circ} := [\zeta,\eta]_{\cdot} + \zeta \triangleright \eta - \eta \triangleright \zeta.
    \]
    Indeed,  is not hard to  verify that the quadruple  
    \( (\mathfrak{g}, [\cdot,\cdot]_{\cdot}, [\cdot,\cdot]_{\circ},  \triangleright )\) is indeed a  PLA. 
   \end{remark}


An important class of examples of post-Lie algebras is given by {\em pre-Lie algebras}
(also known as a {\em left-symmetric algebra}), which arise when the Lie bracket \( [\cdot,\cdot]_{\cdot} \) is trivial. 
In this setting, the post-Lie product defines a compatible Lie algebra structure via antisymmetrization.

\begin{definition}\label{preliealg} \label{preLieAlgebras}
A \emph{pre-Lie algebra} is a triple  \( (\mathfrak{g}, [\cdot,\cdot]_{\circ} ,  \triangleright)\) consisting of a    finite dimensional Lie algebra
    \( (\mathfrak{g}, [\cdot,\cdot]_{\circ} )\)   
    together with a bilinear map 
     \[
    \triangleright : \mathfrak{g} \times \mathfrak{g} \rightarrow \mathfrak{g}, \quad (\zeta, \xi) \mapsto \zeta \triangleright \xi
    \]
 satisfying the identity
    \begin{equation}\label{idpre}
    \zeta \triangleright (\xi \triangleright \gamma) - \xi \triangleright (\zeta \triangleright \gamma)
    = (\zeta \triangleright \xi) \triangleright \gamma - (\xi \triangleright \zeta) \triangleright \gamma
    \quad \text{for all } \zeta, \xi, \gamma \in \mathfrak{g}.
    \end{equation}
   \end{definition}




The \emph{category of post-Lie algebras}, denoted by \( \mathbf{PLA} \), is the category whose objects are PLAs  \( (\mathfrak{g}, [\cdot,\cdot]_{\cdot},  [\cdot,\cdot]_{\circ} )\) and morphisms between two PLAs \( (\mathfrak{g}_1, [\cdot,\cdot]_{\cdot_1}, [\cdot,\cdot]_{\circ_1},  \triangleright_{1} )\) and \ \( (\mathfrak{g}_2, [\cdot,\cdot]_{\cdot_2}, [\cdot,\cdot]_{\circ_2},  \triangleright_{2}) \) are linear maps 
 $\phi: \mathfrak{g}_1 \to \mathfrak{g}_2$ such that for all \( \xi, \eta \in \mathfrak{g}_1 \),
    \[
    \phi([\xi,\eta]_{\cdot_1}) 
    = [\phi(\xi), \phi(\eta)]_{\cdot_2} \quad \text{and} \quad 
     \phi (\xi \triangleright_{1} \eta)= 
     \phi(\xi) \triangleright_{2} \phi(\eta).
    \]
    (note that  also $\phi([\xi,\eta]_{\circ_1}) 
    = [\phi(\xi), \phi(\eta)]_{\circ_2}$ holds true  by (1) in Definition \ref{postLieAlgebras}).




PLAs and pre-Lie algebras have attracted significant attention in recent years since  they  arise in a variety of contexts including affine manifolds, Lie group actions, crystallographic groups, affine representations of Lie algebras, quantum field theory, operad theory, Rota--Baxter operators, and deformation theory. For further details on pre- and post-Lie algebras, we refer the reader to \cite{Burde2012affineaction, Burde2013postliealgebra, Burde2016postliealgebrapair, Burde2018postliealgebranilpotent, Burde2019rotabaxterpostliealgebra}, and the references therein. A comprehensive survey is also provided in \cite{Burde2021crystallographicpostliealgebra}.

\vskip 0.3cm
Given a LSB \( (G, \cdot, \circ) \), one can associate two Lie algebras:
\[
\mathrm{Lie}(G, \cdot) := (\mathfrak{g}, [\cdot,\cdot]_{\cdot}), \qquad 
\mathrm{Lie}(G, \circ) := (\mathfrak{g}, [\cdot,\cdot]_{\circ}),
\]
and define a bilinear map \( \triangleright: \mathfrak{g} \times \mathfrak{g} \to \mathfrak{g} \) by
\begin{equation}\label{trianglelambda}
\xi \triangleright \eta := \lambda_{*e}(\xi)(\eta), \qquad \text{for all } \xi, \eta \in \mathfrak{g},
\end{equation}
where \( \lambda_{*e} \) is the differential at the identity \( e \) of the map
\[
\lambda: (G, \circ) \to \mathrm{Aut}(G, \cdot),
\]
defined by \eqref{lambda}. In particular,
\[
\lambda_{*e}: (\mathfrak{g}, [\cdot,\cdot]_{\circ}) \longrightarrow \mathrm{Der}\left(\mathfrak{g}, [\cdot,\cdot]_{\cdot}\right),
\]
where  \( \mathrm{Der}(\mathfrak{g}, [\cdot,\cdot]_{\cdot}) \) denotes the Lie algebra of derivations of \( (\mathfrak{g}, [\cdot,\cdot]_{\cdot}) \), that is, the Lie algebra of the automorphism group \( \mathrm{Aut}(G, \cdot) \).
As shown in \cite{Bai2023}, the quadruple
$(\mathfrak{g}, [\cdot,\cdot]_{\cdot}, [\cdot,\cdot]_{\circ}, \triangleright)$
forms a PLA. 
This construction defines a functor from the category of Lie skew braces \( \mathbf{LSB} \) to the category of post-Lie algebras \( \mathbf{PLA} \):
\[
D: \mathbf{LSB} \to \mathbf{PLA},
\]
which acts on objects and morphisms as follows:
\[
\begin{aligned}
D(G, \cdot, \circ) &= \bigl(\mathfrak{g}, [\cdot,\cdot]_{\cdot}, [\cdot,\cdot]_{\circ},  \triangleright\bigr), \\
D(\varphi) &= \varphi_{*e},
\end{aligned}
\]
for any homomorphism \( \varphi: (G_1, \cdot_1, \circ_1) \to (G_2, \cdot_2, \circ_2) \) of LSBs,
where the post-Lie product $\triangleright$ is defined in  \eqref{trianglelambda}.



\begin{definition}
A post-Lie algebra \( (\mathfrak{g}, [\cdot,\cdot]_{\cdot}, [\cdot,\cdot]_{\circ},  \triangleright) \) is  \emph{integrable} if there exists a LSB \( (G, \cdot, \circ) \) such that
\[
D(G, \cdot, \circ) = (\mathfrak{g}, [\cdot,\cdot]_{\cdot}, [\cdot,\cdot]_{\circ}, \triangleright).
\]
\end{definition}

As already mentioned in the Introduction, the problem of determining which post-Lie algebras are integrable  is highly nontrivial and remains open, as originally posed in \cite{Bai2023}. A simple example of non integrable PLA is the following. 


\begin{example}\label{exnonint}
Consider the pre-Lie algebra \( \left(\mathbf{M}_n(\mathbb{R}), [\cdot,\cdot]_{\cdot} = 0, [\cdot,\cdot]_{\circ},\ \triangleright \right) \), where \( [X,Y]_{\circ} := XY - YX \) is the usual matrix commutator, and the post-Lie product is defined by
\[
X \triangleright Y := XY,
\]
i.e., matrix multiplication. In this case, the Lie algebra \( (\mathbf{M}_n(\mathbb{R}), [\cdot,\cdot]_{\cdot} = 0) \) is abelian, while \( (\mathbf{M}_n(\mathbb{R}), [\cdot,\cdot]_{\circ}) \) is reductive (since it is isomorphic to \( \mathfrak{gl}_n(\mathbb{R}) \)) and not solvable for \( n \geq 2 \). 
Therefore, this PLA does not satisfy condition \textbf{(S2)} in Theorem~\ref{mainteor},.
Hence, it is not integrable.

Now consider the case \( n = 1 \). In this situation, \( \mathbf{M}_1(\mathbb{R}) \cong \mathbb{R} \), and both Lie brackets vanish:
\[
[x,y]_{\cdot} = 0, \qquad [x,y]_{\circ} = xy - yx = 0,
\]
so the underlying Lie algebras are abelian. The post-Lie product becomes \( x \triangleright y = xy \), the standard multiplication in \( \mathbb{R} \). Suppose, for contradiction, that this structure integrates to a LSB which is necessarily 
 \( (\mathbb{R}, +, +) \).
For such a trivial brace, we have
\[
\lambda_a(b) = -a + (a + b) = b, \qquad \text{for all } a, b \in \mathbb{R},
\]
so the \( \lambda \)-map is the identity on \( \mathbb{R} \), i.e., \( \lambda(\mathbb{R}) = \mathrm{id}_{\mathbb{R}} \in \mathrm{Aut}(\mathbb{R}) \), and hence its differential at the identity is the zero map:
$\lambda_{*1} = 0$. By  \eqref{trianglelambda}, this implies
\[
x \triangleright y = \lambda_{*1}(x)(y) = 0(y) = 0,
\]
which contradicts  \( x \triangleright y = xy \). 
Thus, even in the case \( n = 1 \), the PLA is not integrable.
\end{example}

\noindent
{\bf Convention.}
In what follows, and with a slight abuse of notation, we shall denote a post-Lie algebra simply by the triple
\( (\mathfrak{g}, [\cdot,\cdot]_{\cdot}, [\cdot,\cdot]_{\circ})\)
omitting the post-Lie product~\(\triangleright\), which is understood to be fixed throughout.




\subsection{Affine actions}\label{affineactions}

We begin by recalling the notion of a simply transitive affine action. 
\begin{definition}
Let \( (G, \circ) \) and \( (K, \cdot) \) be two connected real Lie groups. An \emph{affine action} of \( G \) on \( K \) is a Lie group homomorphism
\[
\rho: (G, \circ) \longrightarrow \mathrm{Aff}(K, \cdot) := K \rtimes \mathrm{Aut}(K, \cdot).
\]
We say that the affine  action is \emph{simply transitive} if  for all \( k_1, k_2 \in K \), there exists a unique \( g \in G \) such that \( \rho(g)(k_1) = k_2 \).
\end{definition}

In the 1970s, Milnor  \cite{Milnor1977} posed a fundamental question:
\begin{quote}
\emph{Does every solvable, connected and simply-connected Lie group \((G, \circ)\) of dimension $n$ admit a simply transitive affine action on \((\mathbb{R}^n, +)\)?}
\end{quote}

This question stimulated extensive research and initially led to several attempts to give a positive answer. However, it was eventually shown that the answer is negative. Specifically, Benoist proved in \cite{Benoist1995nil} the existence of an 11-dimensional solvable (even nilpotent), connected and simply connected Lie group \((G, \circ)\) that does \emph{not} admit a simply transitive affine action on \((\mathbb{R}^{11}, +)\).
Later,  Burde and Grunewald \cite{Burde1995} generalize this to a family of examples in dimension $11$ in  and also exhibited a new example in dimension $10$. 
The core of their argument is to exhibit Lie groups $(G,\circ)$
whose Lie algebra $(\mathfrak g,[\cdot,\cdot]_\circ)$ admits \emph{no}
post-Lie product $\triangleright$ capable of endowing $\mathfrak g$ with a
pre-Lie structure $(\mathfrak g,[\cdot,\cdot]_\circ,[\cdot,\cdot]_{\!\cdot}=0)$.


On the other hand, if one does not insist on the affine action being on an abelian Lie group, a positive result can still be obtained:

\begin{theorem}[Dekimpe \cite{Dekimpe1999semisimple}]\label{dekimpesolvable}
Given a connected and simply-connected solvable Lie group \( G \), there exists a nilpotent Lie group \( K \) such that \( G \) acts simply transitively by affine transformations on \( K \).
\end{theorem}


The following proposition illustrates a natural connection between LSB structures on a Lie group and simply transitive affine actions. While this connection is not always stated explicitly, it is implicit in several works (see, e.g. \cite{Burde2009}-\cite{Burde2024postliealgebraperfect}), especially at the level of post-Lie algebras and in the case where $(K, \cdot_K)$ is simply-connected and nilpotent (in this case  one speaks of   {\em simply transitive Nill-affine actions}). This proposition makes the relationship precise for our purposes in the general setting, namely for general connected real Lie groups.

\begin{theorem}\label{propLSBaff}
Let \( (G, \circ_G) \) be a connected real Lie group. The following are equivalent:
\begin{enumerate}
    \item There exists a Lie group structure \( \cdot_G \) on \( G \) such that \( (G, \cdot_G, \circ_G) \) is a LSB;
    \item There exists a connected Lie group \( (K, \cdot_K) \) and a simply transitive affine action
    \[
    \rho: (G, \circ_G) \to \mathrm{Aff}(K, \cdot_K).
    \]
\end{enumerate}
Moreover, whenever one (hence both) of the above conditions holds, there is a \emph{canonical} LSB structure $(K,\cdot_K,\circ_K)$ on $K$ and an isomorphism of LSBs 
\[
\Phi: (G, \cdot_G, \circ_G) \xrightarrow{\;\cong\;} (K, \cdot_K, \circ_K).
\]
As a consequence, the corresponding post-Lie algebras
$\bigl(\mathfrak{g}, [\cdot,\cdot]_{\cdot_G}, [\cdot,\cdot]_{\circ_G} \bigr)$ and 
$\bigl(\mathfrak{k}, [\cdot,\cdot]_{\cdot_K}, [\cdot,\cdot]_{\circ_K} \bigr)$
are isomorphic.
\end{theorem}


\begin{proof}
\noindent
(1) \( \Rightarrow \) (2): Suppose \( (G, \cdot_G, \circ_G) \) is a LSB. Then the map
\[
\rho: (G, \circ_G) \to \mathrm{Aff}(G, \cdot_G), \quad a \mapsto (a, \lambda_a),
\]
is a Lie group homomorphism, where \( \lambda_a \in \mathrm{Aut}(G, \cdot_G) \) is defined as in \eqref{lambdaspec}. The induced action
\[
\rho(a)(b) := a \cdot_G \lambda_a(b)
\]
is simply transitive on \( (G, \cdot_G) \). We can then set \( (K, \cdot_K) := (G, \cdot_G) \), and \( \rho \) defines a simply transitive affine action.

\medskip

\noindent
(2) \( \Rightarrow \) (1): Assume there exists a simply transitive affine action
\[
\rho: (G, \circ_G) \to \mathrm{Aff}(K, \cdot_K).
\]
We first show that \( \rho(G) \subseteq \mathrm{Aff}(K, \cdot_K) \) is a regular subgroup (cf. Definition  \ref{regsubgroup}).  
Since the action of \( G \) on \( K \) via \( \rho \) is simply transitive, for any \( k \in K \), there exists a unique \( g \in G \) such that
\[
\rho(g)(k) = x \cdot f(k) = e_K,
\]
where $\rho (g)=(x, f)$ and $e_K$ denotes the identity element of $(K, \cdot_K)$.
 It follows that  \( \rho(G) \) is a regular subgroup of \( \mathrm{Aff}(K, \cdot_K) \).
Now, by Proposition~\ref{proplambda}, every regular Lie  subgroup of \( \mathrm{Aff}(K, \cdot_K) \) corresponds to a LSB structure \( (K, \cdot_K, \circ_K) \), and the group \( \rho(G) \) is isomorphic to \( (K, \circ_K) \).
Let \( \Psi: \rho(G) \to (K, \circ_K) \) be such an isomorphism. Then the composition
\[
\Phi := \Psi\circ  \rho: (G, \circ_G) \to (K, \circ_K)
\]
is a Lie group isomorphism. We define a new multiplication on \( G \) by
\[
a \cdot_G b := \Phi^{-1}(\Phi(a) \cdot_K \Phi(b)),
\]
which turns \( G \) into a Lie group and makes \( (G, \cdot_G, \circ_G) \) a LSB isomorphic to \( (K, \cdot_K, \circ_K) \). The result follows.
\end{proof}
\medskip
\noindent

Theorem \ref{propLSBaff} shows that studying LSB structures on Lie groups is equivalent to studying simply transitive affine actions. Consequently, the structural properties of LSBs can be translated into geometric properties of affine actions, and viceversa.

The following corollary summarizes several consequences of our results in the setting of affine actions. It provides a reformulation of Theorem~\ref{mainteor} and statement \textbf{(F1)} in Theorem~\ref{mainteor2} from the perspective of affine geometry.



\begin{cor}
Let $\rho: (G,\circ_G) \;\longrightarrow\; \mathrm{Aff}(K,\cdot_K)$
be a simply transitive affine action of a connected Lie group \((G,\circ)\) on a Lie group \((K,\cdot)\). Then:

\begin{itemize}
  \item[\textbf{(S1')}] If \((K,\cdot_K)\) is linear and simply-connected, then \((G,\circ_G)\) is linear.
  \item[\textbf{(S2')}] If \((K,\cdot_K)\) is solvable, then \((G,\circ_G)\) is solvable.
  \item[\textbf{(R1')}] If \((G,\circ_G)\) is nilpotent, then \((K,\cdot_K)\) is solvable.
  \item[\textbf{(R2')}] If \((G,\circ_G)\) is semisimple, then \( \rho \) induces a group isomorphism:
  $(G,\circ_G)\;\cong\;(K,\cdot_K).$


  Moreover, 
  \item[\textbf{(F1')}] For every connected and simply-connected non-linear Lie group \((K,\cdot_K)\), there exists a real connected  linear   \((G,\circ)\) and a  simply transitive affine action
 $\rho: (G,\circ_G) \longrightarrow \mathrm{Aff}(K,\cdot_K)$.
 \end{itemize}
\end{cor}


\medskip

\noindent
Notice that the proof of \textbf{(F2)} in Theorem~\ref{mainteor2} follows by combining Theorem~\ref{propLSBaff} with Dekimpe’s Theorem~\ref{dekimpesolvable}.


Moreover, the result by Benoist mentioned above can be reformulated as the existence of connected and simply connected nilpotent Lie groups of dimension~$11$, denoted by \( (G, \circ) \), such that for any LSB structure \( (G, \cdot, \circ) \), the Lie group \( (G, \cdot) \) is non-abelian.

\begin{remark}\rm
It is also worth noting that a similar phenomenon occurs in the finite setting. Indeed, Bachiller~\cite{Bachiller2018} proved the existence of a finite solvable group \( (G, \circ) \) such that for every left skew brace \( (G, \cdot, \circ) \), the multiplicative group \( (G, \cdot) \) is non-abelian.
\end{remark}

The key idea underlying Benoist's construction relies on the final part of Theorem~\ref{mainteor3}, combined with the observation that certain pairs of Lie algebras, namely \( (\mathbb{R}^{11}, [\cdot,\cdot]_{\circ}) \) and the abelian Lie algebra \( (\mathbb{R}^{11}, [\cdot,\cdot]_{\cdot} = 0) \), cannot be equipped with a bilinear operation \( \triangleright \) satisfying  the pre-Lie identity~\eqref{idpre}. 
\medskip

\noindent
Further results concerning the transition from affine structures to LSB structures will be employed in the proof of Theorem~\ref{mainteor3}.









\section{Proofs of Theorems \ref{mainteor}-\ref{mainteor3} and Corollary \ref{maincor}}\label{proofs}
The following lemmata will be used in the proofs of properties (S1) and (S2) in Theorem~\ref{mainteor}, respectively.
The first lemma establishes a structural property that, although implicitly used in the literature, is often not stated explicitly. For completeness, we include a full proof here.

\begin{lemma} \label{lemmalinear}
Let $(G, \cdot)$ be a linear connected and simply connected real Lie group. 
Then the identity component \( \mathrm{Aff}_{0}(G, \cdot) \) of the group of affine transformations \( \mathrm{Aff}(G, \cdot) \) is also linear.
\end{lemma}

\begin{proof}
By definition, the identity component of the group of affine transformations is given by
\[
\mathrm{Aff}_{0}(G, \cdot) = (G, \cdot) \rtimes \mathrm{Aut}_{0}(G, \cdot),
\]
where \( \mathrm{Aut}_{0}(G, \cdot) \) denotes the connected component of the identity in the group of Lie group automorphisms of \( G \).
Since \( G \) is simply-connected, by \cite[Thm.~3.18.13]{Hall2003lie} it admits a Levi-Malcev decomposition
$(G, \cdot) = R \rtimes S,$
where \( R \) is the radical of \( G \) and \( S \) is a semisimple subgroup. Thus, in the terminology in \cite{Wu1986}, the subgroup \( R \) is a {\em nucleus}, i.e. a closed  connected and simply-connected normal, solvable Lie subgroup of $G$
such that $G/R$ is reductive.
 Since $R$ is   invariant under the action of \( \mathrm{Aut}_{0}(G) \), it follows  by  \cite[Lemma 2]{Wu1986} that 
 there exists a  faithful representation of \( G \)  which can be extended to a (possibly non-faithful) representation of the semidirect product \( (G, \cdot) \rtimes \mathrm{Aut}_{0}(G, \cdot) \).
Now consider the short exact sequence
\[
1 \rightarrow (G, \cdot) \rightarrow (G, \cdot) \rtimes \mathrm{Aut}_{0}(G) \rightarrow \mathrm{Aut}_{0}(G) \rightarrow 1.
\]
Since \( (G, \cdot) \) admits a faithful linear representation that extends to the semidirect product, and \( \mathrm{Aut}_{0}(G, \cdot) \) is linear, being  a Lie subgroup of \( \mathrm{GL}(\mathfrak{g}) \), where \( \mathfrak{g} = \mathrm{Lie}(G, \cdot) \), we may apply \cite[Lemma 1]{Wu1986} to conclude that \( \mathrm{Aff}_{0}(G, \cdot) \) is linear.
\end{proof}

