Our second lemma shows how a LSB structure can be lifted to the universal covering of a connected LSB.

\begin{lemma} \label{Universalcover}
Let $(G, \cdot, \circ)$ be a connected LSB with identity element $e \in G$. Let $\widetilde{G}$ be the universal covering space of $G$, and let $\pi: \widetilde{G} \rightarrow G$ denote the covering map. Then, for any $\tilde{e} \in \pi^{-1}(e)$, there exists a LSB structure $(\widetilde{G}, \tilde{\cdot}, \tilde{\circ})$ with identity $\tilde{e}$ such that $\pi$ is a LSB homomorphism from $(\widetilde{G}, \tilde{\cdot}, \tilde{\circ})$ to $(G, \cdot, \circ)$.
\end{lemma}

\begin{proof}
By standard results in Lie group theory (see, e.g., \cite[Section 3.24]{Warner}), there exist two Lie group structures on $\widetilde{G}$, denoted by $(\widetilde{G}, \cdot)$ and $(\widetilde{G}, \circ )$, both having $\tilde{e}$ as identity element, such that $\pi$ is a Lie group homomorphism from $(\widetilde{G}, \cdot )$ to $(G, \cdot)$ and from $(\widetilde{G}, \circ )$ to $(G, \circ)$ (here with a slight abuse of notation we are denoting the operations on $\widetilde{G}$ with the same symbol $\cdot$ and $\circ$ used for $G$).

To show that $(\tilde G, \cdot , \circ)$ is a LSB and that $\pi$ is a LSB homomorphism, we must verify that the identity
\eqref{eqLSB} is satisfied, namely
\begin{equation}\label{tildeLSB}
[ \tilde{a} \circ (\tilde{b} \cdot \tilde{c}) ] \cdot  [(\tilde{a} \circ \tilde{b}) \cdot  \tilde{a}^{-1}  \cdot  (\tilde{a} \circ  \tilde{c}) ]^{-1}=\tilde e
\end{equation}holds for all $\tilde{a}, \tilde{b}, \tilde{c} \in \widetilde{G}$.

Define the smooth map
\[
\tilde{f} : \widetilde{G} \times \widetilde{G} \times \widetilde{G} \rightarrow \widetilde{G}, \quad
(\tilde{a}, \tilde{b}, \tilde{c}) \mapsto [ \tilde{a} \circ (\tilde{b} \cdot \tilde{c}) ] \cdot  [(\tilde{a} \circ \tilde{b}) \cdot  \tilde{a}^{-1}  \cdot  (\tilde{a} \circ  \tilde{c}) ]^{-1},
\]
and consider the constant map
\[
c_{\tilde{e}} : \widetilde{G} \times \widetilde{G} \times \widetilde{G} \rightarrow \widetilde{G}, \quad
(\tilde{a}, \tilde{b}, \tilde{c}) \mapsto \tilde{e}.
\]

We aim to prove that $\tilde{f} = c_{\tilde{e}}$.
In order to show this,
notice first  that  $\tilde{f}$ and ${c}_{\tilde e}$ are smooth lifts of the constant map 
$$c_e:G\times G\times G\rightarrow G, \ \ (a, b, c)\mapsto c_e(a, b, c)=e,$$
i.e. $\pi\tilde f=\pi c_{\tilde e}=e$.
Indeed, for $c_{\tilde e}$ is obvious while for $\tilde f$:
$$\pi\tilde f(\tilde a, \tilde b, \tilde c)=\pi\left([ \tilde{a} \circ (\tilde{b} \cdot \tilde{c}) ] \cdot  [(\tilde{a} \circ \tilde{b}) \cdot  \tilde{a}^{-1}  \cdot  (\tilde{a} \circ  \tilde{c}) ]^{-1}\right)=[ a \circ (b \cdot c) ] \cdot  [(a \circ b) \cdot  a^{-1}  \cdot  (a \circ  c) ]^{-1}=e,$$
with $a=\pi(\tilde a), b=\pi(\tilde b)$ and $c=\pi(\tilde c)$, where the second equality follows 
by the fact that $\pi$ is an homomorphism
from $(\widetilde{G}, \cdot )$ to $(G, \cdot)$ and from $(\widetilde{G}, \circ )$ to $(G, \circ)$ 
and the third equality follows by the fact that $(G, \cdot, \circ)$ is a LSB and so \eqref{eqLSB} holds true.
Moreover, $\tilde f$ and $c_{\tilde e}$ agree at the point $(\tilde{e}, \tilde{e}, \tilde{e})$, i.e. $c_{\tilde e}(\tilde e, \tilde, e, \tilde e)=\tilde f (\tilde e, \tilde e, \tilde e)=\tilde e$ (the second equality follows by  sobstituting $(\tilde e, \tilde e, \tilde e)$ into \eqref{tildeLSB}).
By uniqueness of  lifts on covering spaces (since the space involved are connected), it follows that $\tilde f = c_{\tilde e}$, and we are done.  
\end{proof}

\begin{remark}\rm
Thanks to the correspondence between LSBs and simply transitive affine actions established in Theorem~\ref{propLSBaff}, Lemma~\ref{Universalcover} admits the following geometric counterpart:
\emph{Let
$\rho : (G,\circ)\;\longrightarrow\;\mathrm{Aff}(K,\cdot)$
be a simply transitive affine action of a connected Lie group $(G,\circ)$ on another connected Lie group $(K,\cdot)$.  
Then the universal coverings $\widetilde{G}$ and $\widetilde{K}$ carry a lifted action
$\widetilde{\rho} : (\widetilde{G},\circ)\;\longrightarrow\;\mathrm{Aff}(\widetilde{K},\cdot),$
which is again simply transitive.}
\end{remark}



\begin{proof}[Proof of Theorem \ref{mainteor}]
\mbox{}

\noindent
\textbf{(S1)} 
Let $(G, \cdot, \circ)$ be a LSB, with $(G, \cdot )$ connected simply-connected and linear. By Proposition~\ref{proplambda}, there exists a regular subgroup \( H \leq \mathrm{Aff}(G, \cdot) \) such that \( H \cong (G, \circ) \).
Since \( G \) is connected, it follows that \( H \leq \mathrm{Aff}_0(G, \cdot) \). 
As \( \mathrm{Aff}_0(G, \cdot) \) is linear (by Lemma~\ref{lemmalinear}),  \( H \) is also linear. Therefore, \( (G, \circ) \) is linear as well.

\vspace{0.5em}
\noindent
\textbf{(S2)} Let \( (G, \cdot, \circ) \) be a connected LSB such that \( (G, \cdot) \) is solvable. We aim to prove that \( (G, \circ) \) is also solvable.
By Lemma~\ref{Universalcover}, we may assume without loss of generality that \( G \) is simply connected. That is, \( (G, \cdot) \) is a connected, simply connected, solvable Lie group.
By standard results, such a Lie group is linear (see \cite[Th. 16.2.7]{Hilgert1952book}) and diffeomorphic to \( \mathbb{R}^n \) (see, e.g., \cite[Th. $2^a$]{Chevalley1951}). Hence, the Lie group \( (G, \circ) \), which is defined on the same underlying manifold \( G \), is also diffeomorphic to \( \mathbb{R}^n \).

By the Levi–Malcev decomposition, we have
$(G, \circ) \simeq R \rtimes S,$
where \( R \) is a connected, simply connected solvable Lie group, and \( S \) is a connected, simply connected semisimple Lie group.

Since \( (G, \circ) \) is diffeomorphic to \( \mathbb{R}^n \), it is in particular contractible. This implies that the semisimple part \( S \) must also be contractible, and hence diffeomorphic to some Euclidean space. One can verify  (see, e.g., \cite[Ch. VI]{Knapp2013lie}) that the \emph{only} connected, simply connected, non-compact, simple real Lie group diffeomorphic to an Euclidean space is the universal covering group \( \widetilde{SL_2(\mathbb{R})} \) of \( SL_2(\mathbb{R}) \) the special linear group of order $2$.
Since any semisimple Lie group is a finite direct product of simple Lie groups, we conclude that
$S \simeq \widetilde{SL_2(\mathbb{R})}^k$
for some \( k \geq 0 \). Therefore, 
$(G, \circ) \simeq R \rtimes \widetilde{SL_2(\mathbb{R})}^k,$
where \( R \) is a connected, simply connected solvable Lie group.
By \textbf{(S1)}, the Lie group \( (G, \circ) \) is linear. However, it is well known that \( \widetilde{SL_2(\mathbb{R})} \) is not linear. This forces \( k = 0 \). Hence,
$(G, \circ) \simeq R,$
and since \( R \) is solvable, we conclude that \( (G, \circ) \) is solvable.

\vspace{0.5em}
\noindent
\textbf{(R1)} 
Let \( (G, \cdot, \circ) \) be a connected LSB such that \( (G, \circ) \) is nilpotent 
and let \( (\mathfrak{g}, [\cdot,\cdot]_{\cdot}, [\cdot,\cdot]_{\circ})\) be the corresponding PLA . Then the Lie algebra \( (\mathfrak{g}, [\cdot, \cdot]_{\circ}) \) is nilpotent as well. By \cite[Prop.~3.2]{Burde2013postliealgebra}, this implies that the Lie algebra \( (\mathfrak{g}, [\cdot, \cdot]_{\cdot}) \) is solvable. Hence, \( (G, \cdot) \) is solvable, as desired.

\vspace{0.5em}
\noindent
\textbf{(R2)} 
Let \( (G, \cdot, \circ) \) be a connected Lie skew brace such that \( (G, \circ) \) is semisimple 
and let \( (\mathfrak{g}, [\cdot,\cdot]_{\cdot}, [\cdot,\cdot]_{\circ})\) be the corresponding PLA. Then the Lie algebra \( (\mathfrak{g}, [\cdot, \cdot]_{\circ}) \) is semisimple as well. By \cite[Th.~3.3]{Burde2022rigiditypostliealgebra}, it follows that \( (\mathfrak{g}, [\cdot, \cdot]_{\cdot}) \) is isomorphic to \( (\mathfrak{g}, [\cdot, \cdot]_{\circ}) \) as Lie algebras. Since \( (G, \cdot) \) and \( (G, \circ) \) are diffeomorphic as manifolds, we conclude that \( (G, \cdot) \cong (G, \circ) \) as Lie groups.
\end{proof}

\begin{remark}\rm\label{rmk1mainteor}
Point \textbf{(S1)} of Theorem~\ref{mainteor} \emph{fails} once the assumption that $G$ is simply connected is dropped. An explicit counterexample can be constructed as follows.
Let \( H = \mathbb{R}^3 \) equipped with the Heisenberg group law:
\begin{equation}\label{heislaw}
(x,y,z)\cdot(x',y',z') =
\bigl(x + x',\, y + y',\, z + z' + xy' \bigr).
\end{equation}

Consider the discrete central subgroup
\[
N = \{(0,0, k): k \in \mathbb{Z} \} \subset Z(H),
\]
and define \( G := H / N \), denoting the group operation on \( G \) by \( \circ \). We represent cosets in \( G \) as \([x, y, \theta]\), with \(\theta \in \mathbb{S}^1\).
As shown in \cite[Section 4.8]{Hall2003lie}, the group \( G \) is not linear. Now consider the following subgroups of \( G \):
\[
G_1 = \bigl\{ [x, 0, \theta] : x \in \mathbb{R},\, \theta \in \mathbb{S}^1 \bigr\}
\cong \mathbb{R} \times \mathbb{S}^1, \quad
G_2 = \bigl\{ [0, y, 0] : y \in \mathbb{R} \bigr\} \cong \mathbb{R}.
\]

It is readily verified that \( G_1 \) is a closed normal subgroup of \( G \), \( G_2 \) is a closed subgroup, and \( G_1 \cap G_2 = \{e\} \). Therefore, \( G \) is the semidirect product \( G = G_1 \rtimes G_2 \). 
Now endow the same underlying set
$G = (\mathbb{R} \times \mathbb{S}^1) \times \mathbb{R}$
with the direct product operation $\cdot$. According to Example~\ref{exLSBrevzappa}, the pair of operations \((\cdot, \circ)\) defines a connected but non-simply-connected LSB, where the group \((G, \cdot)\) is linear, although \((G, \circ )\) is not.
This shows that the assumption of simple-connectedness is crucial for the validity of point \textbf{(S1)}.
\end{remark}

\medskip

\begin{proof}[Proof of Corollary~\ref{maincor}]
Let \(G_{0}\subseteq G\) be the (closed) connected component of the identity.  
Because the map \(\lambda_{a}\) defined in~\eqref{lambdaspec} is continuous, we have
\(\lambda_{a}(G_{0})=G_{0}\) for every \(a\in G\). Moreover,  \(G_{0}\) is a normal
subgroup of both \((G,\cdot)\) and \((G,\circ)\).

Consequently, we obtain two compact LSBs:
\[
  (G_{0},\cdot,\circ)
  \quad\text{and}\quad
  (\overline{G},\cdot,\circ),\qquad
  \overline{G}=G/G_{0},
\]
where the quotient operations are
\[
  (aG_{0})\cdot(bG_{0})=(a\cdot b)G_{0},
  \qquad
  (aG_{0})\circ(bG_{0})=(a\circ b)G_{0}.
\]

Because \(G_{0}\) is connected, condition \textbf{(S2)} of
Theorem~\ref{mainteor} tells us that the  group \((G_{0},\circ)\) is
solvable.
Next, \((G,\cdot)\) is compact and nilpotent, and \(G_{0}\) is an open
subgroup, so \(G_{0}\) has finite index in \((G,\cdot)\).  Therefore
\(|\overline{G}|<\infty\), and \((\overline{G},\cdot,\circ)\) is a finite left
skew brace.  Nilpotency is preserved by quotients, hence
\((\overline{G},\cdot)\) is finite and nilpotent.  By
\cite[Cor.~2.23]{Smoktunowicz2018} the multiplicative group
\((\overline{G},\circ)\) is solvable.
Since the class of solvable groups is closed under extensions, the 
group \((G,\circ)\) is also solvable.  This completes the proof
\footnote{Motivated by the discrete left skew brace setting
(cf.\ \cite{KonSmokVen2021}), one may call a subset
\(I\subseteq(G,\cdot,\circ)\) an \emph{ideal} if it is a closed Lie subgroup
satisfying
\begin{enumerate}\renewcommand{\labelenumi}{(\roman{enumi})}
  \item \(I\trianglelefteq(G,\cdot)\),
  \item \(I\trianglelefteq(G,\circ)\),
  \item \(\lambda_{a}(I)=I\) for every \(a\in G\).
\end{enumerate}
The argument above shows that \(G_{0}\) is indeed such an ideal.  The
closedness of \(I\) is precisely what guarantees that the quotient
\(G/G_{0}\) carries a natural manifold structure.}.
\end{proof}

\begin{remark}\label{rmkconj}
It is worth pointing out that, if Smoktunowicz--Vandramin's conjecture stated in the Introduction is true, the nilpotency assumption in Corollary~\ref{maincor} can be relaxed to mere solvability.
In any case, repeating the argument above and exploiting the fact that, for every \emph{finite} left skew brace \((B,\cdot,\circ)\), the solvability of \((B,\cdot)\) together with \(|B|\) not divisible by~\(3\) forces \((B,\circ)\) to be solvable 
\cite[Cor. 2.3]{Gorshkov2021}, we obtain the following consequence: {\em 
let \((G,\cdot,\circ)\) be a  LSB such that \((G,\cdot)\) is solvable and the quotient \(G/G_0\) is finite of order not divisible by~\(3\).
Then the group \((G,\circ)\) is solvable.}
\end{remark}

\vspace{0.5em}



\begin{proof}[Proof of Theorem \ref{mainteor2}]
\mbox{}

\noindent
\textbf{(F1)} 
Let \( (G, \cdot) \) be a connected, simply connected, non-linear Lie group.  
Our objective is to endow \( G \) with a second Lie group structure \( \circ \) such that \( (G, \cdot, \circ) \) forms a LSB, and the group \( (G, \circ) \) is linear.

To this end, we aim to show that there exist two linear Lie subgroups \( G_1, G_2 \subseteq G \) satisfying
\begin{equation}\label{scomp}
   G = G_1 G_2, \qquad G_1 \cap G_2 = \{e\}.
\end{equation}
Such a factorization allows us, via Example~\ref{exLSBzappa}, to define a second group operation \( \circ \) on \( G \) such that
\[
   (G, \circ) \cong G_1 \times G_2,
\]
where the right-hand side is endowed with the direct product structure, which is linear. 

In order to get \eqref{scomp} we use again the 
 Levi--Malcev decomposition. So let \( R \trianglelefteq G \) be a connected and simply connected solvable Lie subgroup,  and \( S \le G \) be  a connected and simply connected semisimple Lie, such that
\[
G = RS, \qquad R \cap S = \{e\}.
\]
Moreover, by the \emph{Iwasawa decomposition} (see \cite[Th.~6.46]{Knapp2013lie}), we can write
\[
S = KAN,
\]
where \( AN \) is a connected and simply connected solvable Lie subgroup, and \( K = U \times V \), with \( U \cong \mathbb{R}^n \), \( V \) compact, connected, and simply connected. Furthermore, \( K \cap AN = \{e\} \).

Combining these, we obtain:
\[
G = RS = R(KAN) = (RK)(AN) = (RUV)(AN).
\]
Define
\[
G_1 := RUV, \qquad G_2 := AN.
\]
It remains to show that \( G_1 \cap G_2 = \{e\} \), and that \( G_1 \) and \( G_2 \) are linear Lie subgroups of \( G \). Let \( x \in G_1 \cap G_2 \). Then \( x = ruv \) for some \( r \in R \), \( u \in U \), \( v \in V \), and also \( x = an \) for some \( a \in A \), \( n \in N \). Hence,
\[
ruv = an \quad \Rightarrow \quad r = an (uv)^{-1} \in ANK.
\]
Since \(  KAN=S \le G \), we have \( ANK = KAN \), so \( r \in KAN \). But \( R \cap KAN = \{e\} \), thus \( r = e \), implying
$uv = an \in AN$.
However, \( uv \in K \), and \( K \cap AN = \{e\} \), hence \( uv = e \), and so \( x = e \). Therefore, \( G_1 \cap G_2 = \{e\} \). Next, we prove that both \( G_1 \) and \( G_2 \) are linear. Note that
$G_1 = RUV = (RU)V.$
Since \( R \trianglelefteq G \) and \( R \cap U = \{e\} \), we have \( RU \cong R \rtimes U \), which is connected, simply connected, and solvable. Also, \( V \) is compact and therefore real linearly reductive. Since $UV$ normalizes $R$ it follows that,  it follows that \( RU \trianglelefteq G_1 \), and hence
$G_1 = (RU) \rtimes V$.
By \cite[Th.~16.2.7]{Hilgert1952book}, such a group is linear. Moreover, \( G_2 = AN \) is connected, simply connected, and solvable, so it is linear by the same result.

\vspace{0.5em}
\noindent
\textbf{(F2)} 
Let \( (G,\circ) \) be a  connected and simply connected solvable Lie group.  
Combining Theorem  \ref{propLSBaff} with Theorem \ref{dekimpesolvable}, one can construct a LSB \( (G,\cdot,\circ) \) such that the Lie group \( (G,\cdot) \) is nilpotent.

\end{proof}


\begin{proof}[Proof of Theorem \ref{mainteor3}]
To justify each entry of  the table in Theorem \ref{mainteor}, we examine every pair \((G,\cdot)\) and \((G,\circ)\) in turn, constructing explicit non-trivial LSB structures for the boxes marked \(\cmark\) and proving non-existence or  triviality for those marked with a dash ($-$).

\medskip 

\paragraph{\textbf{Step 1. Positive entries (\(\cmark\)).}}
\mbox{}

\medskip



\noindent
{\bf 1. \emph{$(G,\cdot)$ ab, $(G,\circ)$ nil}}

\noindent
In \cite{Scheuneman1974}, using pre-Lie algebra techniques, it was shown that Milnor's question (see Subsection~\ref{affineactions}) has a positive answer for \(3\)-step nilpotent Lie groups.  
Combining this result with Theorem~\ref{propLSBaff}, we deduce that for every connected, simply connected nilpotent Lie group \((G,\circ)\) of step~\(3\), there exists another Lie group law \( \cdot \) on the same underlying manifold \( G \) such that the triple \((G,\cdot,\circ)\) forms an LSB structure, with \((G,\cdot)\) abelian.



\medskip

\noindent  
{\bf  2. \emph{$(G,\cdot)$ ab, $(G,\circ)$ solv}}

\noindent
Consider the affine group \( (G, \circ) = \mathrm{Aff}(\mathbb{R}, +) \), 
that is, the group of automorphisms of the additive group \( (\mathbb{R}, +) \). 
This group can be realized as the semidirect product
$(\mathbb{R}, +) \rtimes_\alpha (\mathbb{R}, +),$
where both factors are copies of the additive group of real numbers, 
and the action \( \alpha \colon (\mathbb{R}, +) \to \mathrm{Aut}(\mathbb{R}, +) \) is given by
$\alpha(a)(b) = e^a b.$
The group operation \( \circ \) on \( G \cong \mathbb{R}^2 \) is then explicitly defined by
\[
(a, b) \circ (a', b') = \left( a + a',\, b + e^a b' \right),
\]
for all \( a, a', b, b' \in \mathbb{R} \). The  group \( (G, \circ) \) is solvable but not nilpotent.
By Example~\ref{exLSBrevzappa}, we deduce that this structure induces a LSB on \( \mathbb{R}^2 \), denoted \( (\mathbb{R}^2, +, \circ) \), where \( + \) is the standard addition on \( \mathbb{R}^2 \) and \( \circ \) is the nontrivial solvable affine product defined above.
Similar examples can be constructed, via pre-Lie algebra techniques, whenever Milnor's question has a positive answer.






\medskip 

\noindent 
{\bf  3. \emph{$(G,\cdot)$ nil, $(G,\circ)$ ab}} 

\noindent
Let \((H_{3}, \cdot)\) be the three–dimensional Heisenberg group with multiplication
\eqref{heislaw}.
It is easily seen that $H_3=\mathbb{R}^2\rtimes_\alpha \mathbb{R}$ 
where 
\[
\alpha \;:\; (\mathbb{R},+) \;\longrightarrow\; \operatorname{Aut}\!\bigl(\mathbb{R}^{2},+\bigr)
          \;=\; \operatorname{GL}_{2}(\mathbb{R}),
\qquad
\alpha(x)\;=\;
\begin{pmatrix}
1 & 0\\[2pt]
x & 1
\end{pmatrix},
\quad x\in\mathbb{R}.
\]
By applying Example \ref{exLSBzappa} we obtain a LSB
$(\mathbb{R}^{3},\,\cdot,\,+),$
in which \((\mathbb{R}^{3},\cdot)\)  is {\em nilpotent} and non-abelian,
whereas \((\mathbb{R}^{3},+)\) is {\em abelian}.

\medskip

\noindent
{\bf  4. \emph{$(G,\cdot)$ nil, $(G,\circ)$ nil}}


\noindent
In \cite{Burde2009}, it is proved that for every \( n \leq 5 \), and for any pair of connected and simply connected nilpotent Lie groups \( (G, \circ_G) \) and \( (K, \cdot_K) \) of dimension \( n \), there exists a simply transitive affine action 
\[
\rho: (G, \circ_G) \rightarrow \mathrm{Aff}(K, \cdot_K).
\]
Therefore, by choosing \( (G, \circ_G) \) and \( (K, \cdot_K) \) to be two non-isomorphic connected and simply connected nilpotent Lie groups of dimension \( n \leq 5 \), and applying Theorem~\ref{propLSBaff}, we obtain a nontrivial LSB structure \( (G, \cdot, \circ) \), where both \( (G, \cdot) \) and \( (G, \circ) \) are connected and simply connected {\em nilpotent} non-abelian Lie groups.


\medskip

\noindent
{\bf  5. \emph{$(G,\cdot)$ nil,  $(G,\circ)$ solv}}

\noindent
Let \( (G, \circ) \) be any connected and simply connected solvable Lie group that is not nilpotent. 
Then, by applying statement \textbf{(F2)} of Theorem~\ref{mainteor2}, one can construct a LSB \( (G, \cdot, \circ) \) such that the group \( (G, \cdot) \) is nilpotent.  
\medskip

\noindent
{\bf  6. \emph{$(G,\cdot)$ solv, $(G,\circ)$ ab}}

\noindent
Consider the affine group \( (G, \cdot) = \mathrm{Aff}(\mathbb{R}, +) \cong (\mathbb{R}, +) \rtimes_\alpha (\mathbb{R}, +) \), 
i.e., the group of automorphisms of the additive group \( (\mathbb{R}, +) \), as in the previous example. 
This time, however, we denote the affine group operation by \( \cdot \) to emphasize its role as the primary group structure. 
By applying Example~\ref{exLSBzappa}, we deduce that this setting induces a LSB  structure on \( \mathbb{R}^2 \), denoted \( (\mathbb{R}^2, \cdot, +) \), 
where \( (\mathbb{R}^2, \cdot) \) is a solvable Lie group and \( (\mathbb{R}^2, +) \) is abelian.



\medskip

\noindent
{\bf 7.  \emph{$(G,\cdot)$ solv, $(G,\circ)$ nil}}

\noindent
Let \(H_{3}\) be the three–dimensional Heisenberg group with multiplication \eqref{heislaw}.

For every \(t\in\mathbb{R}\) the map
\[
\alpha_{t}:(x,y,z)\longmapsto\bigl(e^{t}x,\,e^{t}y,\,e^{2t}z\bigr)
\]
is an automorphism, yielding a one–parameter homomorphism
\(\alpha:\mathbb{R}\to\operatorname{Aut}(H_{3})\).

With this action we set
$(G,\cdot)=\mathbb{R}\rtimes_{\alpha}H_{3},$
a four-dimensional Lie group that is solvable but not nilpotent.
In contrast, the direct product
$(G,\circ)=\mathbb{R}\times H_{3}$
is nilpotent (of step 2) and non-abelian.

By applying Example \ref{exLSBzappa} we obtain a LSB
$(\mathbb{R}^{4},\,\cdot,\,\circ),$
in which \((\mathbb{R}^{4},\cdot)\) is {\em solvable} and non-nilpotent,
whereas \((\mathbb{R}^{4},\circ)\) is {\em nilpotent} and non-abelian.



\medskip

\noindent
{\bf 8. \emph{$(G,\cdot)$ solv,  $(G,\circ)$ solv}}

\noindent
\noindent
Let \(H\) be a connected, solvable, but non-nilpotent Lie group.  
Define the inner automorphism action
\[
\Ad \colon H \longrightarrow\mathrm{Aut}(H), 
\qquad 
\Ad_{a}(b)=a\,b\,a^{-1},
\]
and form the associated semidirect product
$(G,\cdot)\;:=\;H \rtimes_{\Ad} H$.
Equip the same manifold \(H\times H\) with the direct-product structure
$(G,\circ)\;:=\;H\times H$.
Both \((G,\circ)\) and \((G,\cdot)\) are connected and solvable.
The action \(\Ad\) is non-trivial because \(H\) is not abelian and hence
\((G,\circ)\not\cong(G,\cdot)\).
Applying Example~\ref{exLSBzappa}, we obtain a non-trivial LSB
$(G,\cdot,\circ),$
in which \((G,\cdot)\) and \((G,\circ)\) are distinct yet both {\em solvable} Lie groups.








\medskip

\noindent
{\bf 9.  \emph{$(G,\cdot)$ simple,  $(G,\circ)$ solv}} and {\bf \emph{$(G,\cdot)$ ssimple,   $(G,\circ)$ solv}} 

\noindent
Consider the simple Lie group \( \left( \mathrm{SL}_2(\mathbb{R}), \cdot \right) \), where \( \cdot \) denotes the usual matrix multiplication. Its Iwasawa decomposition takes the form
$\mathrm{SL}_2(\mathbb{R}) = KAN,$
where:
\begin{itemize}
  \item \( K = \mathrm{SO}(2) = \left\{ \begin{pmatrix}
      \cos\theta & -\sin\theta \\
      \sin\theta & \cos\theta
    \end{pmatrix} : \theta \in \mathbb{R} \right\} \)
  is a maximal compact subgroup;

  \item \( A = \left\{ \begin{pmatrix}
      a & 0 \\
      0 & a^{-1}
    \end{pmatrix} : a > 0 \right\} \)
  is a one-parameter abelian subgroup consisting of diagonal matrices with positive entries;

  \item \( N = \left\{ \begin{pmatrix}
      1 & x \\
      0 & 1
    \end{pmatrix} : x \in \mathbb{R} \right\} \)
  is  isomorphic to the additive group \( (\mathbb{R}, +) \).
\end{itemize}
The subgroup \( K \cong \mathbb{S}^1 \) is compact, connected, and abelian, and therefore nilpotent. The product \( AN \) forms a connected, simply-connected, solvable Lie subgroup. Moreover, \( K \cap AN = \{ I_2 \} \), where \( I_2 \) denotes the \( 2 \times 2 \) identity matrix.
Hence, Example~\ref{exLSBzappa} applies, yielding a LSB structure
$\left( \mathrm{SL}_2(\mathbb{R}), \cdot, \circ \right),
$
 where
\( \left( \mathrm{SL}_2(\mathbb{R}), \cdot \right) \) is  simple, while
\( \left( \mathrm{SL}_2(\mathbb{R}), \circ \right) \cong K \times AN \) is solvable.
Finally, taking the product of the previous LSB with itself
(cf.\ Example~\ref{exLSBprod}) yields
$\bigl(\mathrm{SL}_{2}(\mathbb{R})\times\mathrm{SL}_{2}(\mathbb{R})
 \,\cdot,\,\circ\bigr),$
where
$\bigl(\mathrm{SL}_{2}(\mathbb{R})\times\mathrm{SL}_{2}(\mathbb{R}),\,\cdot\bigr)$
is semisimple
and 
$(\mathrm{SL}_{2}(\mathbb{R})\times\mathrm{SL}_{2}(\mathbb{R}),\,\circ\bigr)$
is solvable.




\medskip

\noindent
{\bf 10.   \emph{$(G,\cdot)$ simple,  $(G,\circ)$ mixed-type}}  and {\bf \emph{$(G,\cdot)$ ssimple,  $(G,\circ)$ mixed-type}}

\item
Consider the simple Lie group \( \bigl( \mathrm{SL}_3(\mathbb{R}), \cdot \bigr) \),
with the usual matrix multiplication.  
Its Iwasawa decomposition is
$\mathrm{SL}_3(\mathbb{R}) \;=\; K\,A\,N,$
where
\begin{itemize}
  \item \(
        K \;=\; \mathrm{SO}(3)\)
               is a maximal compact subgroup (compact, connected, \emph{semisimple}, non-abelian);

  \item \(
        A
        \;=\;
        \Bigl\{
          \operatorname{diag}(a_1,a_2,a_3)
          \,\bigm|\,
          a_i>0,\;
          a_1a_2a_3=1
        \Bigr\}
        \cong (\mathbb{R}_{>0})^2
        \)
        is a two-parameter abelian subgroup of positive diagonal matrices;

  \item \(
        N
       \)
        is a three-dimensional, step-two nilpotent subgroup
        (isomorphic to the  Heisenberg group \(H_{3}\)).
\end{itemize}

The subgroup \( K\cong \mathrm{SO}(3) \) is compact and semisimple,
while the product \( AN \) is connected, simply connected, and solvable.  
Moreover,
\( K\cap AN = \{I_3\} \), where \( I_3 \) denotes the \(3\times3\) identity.

Hence Example \ref{exLSBzappa} applies and yields a LSB
structure $\bigl(\mathrm{SL}_3(\mathbb{R}),\,\cdot,\,\circ\bigr),$
ssuch that
\( \bigl(\mathrm{SL}_3(\mathbb{R}),\cdot\bigr) \) is simple,
whereas
$\bigl(\mathrm{SL}_3(\mathbb{R}),\circ\bigr)
\;\cong\;
K \times AN$
is of \emph{mixed type}: it contains both a non-abelian semisimple factor
(\(K\)) and a solvable factor (\(AN\)), so it is neither solvable, nor simple,
nor semisimple. Analogously with the previous example by taking 
the product of  $\bigl(\mathrm{SL}_3(\mathbb{R}),\,\cdot,\,\circ\bigr),$
with itself one gets  a LSB such that 
$\bigl(\mathrm{SL}_{3}(\mathbb{R})\times\mathrm{SL}_{3}(\mathbb{R}),\,\cdot\bigr)$
is semisimple
and 
$(\mathrm{SL}_{3}(\mathbb{R})\times\mathrm{SL}_{3}(\mathbb{R}),\,\circ\bigr)$
is of mixed-type.



\medskip 

\noindent
{\bf 11.  \emph{$(G,\cdot)$ mixed-type,  $(G,\circ)$ solv}} 


\smallskip

\noindent
Let \(\bigl(\mathrm{SL}_{2}(\mathbb{R}),\cdot,\circ\bigr)\) be the
LSB constructed in~\textbf{(9)}, for which
\(\bigl(\mathrm{SL}_{2}(\mathbb{R}),\cdot\bigr)\) is \emph{simple}
whereas \(\bigl(\mathrm{SL}_{2}(\mathbb{R}),\circ\bigr)\) is
\emph{solvable}.  
Form the direct product with the abelian LSB
\((\mathbb{R},+,+)\) as in Example~\eqref{exLSBprod}.  
The resulting LSB
$\bigl(\,\mathrm{SL}_{2}(\mathbb{R})\times\mathbb{R},\;
        \cdot,\;\circ\,\bigr)$
 is such that 
$\bigl(\mathrm{SL}_{2}(\mathbb{R})\times\mathbb{R},\cdot\bigr)$
is of {\em mixed-type} and 
$\bigl(\mathrm{SL}_{2}(\mathbb{R})\times\mathbb{R},\circ\bigr)$
 is \emph{solvable}.

\medskip 

\noindent
{\bf 12.  \emph{$(G,\cdot)$ mixed-type,  $(G,\circ)$ mixed-type}}

\noindent
Let $(G,\cdot)=\mathbb{R}^{3}\rtimes_{\operatorname{Ad}}\mathrm{SU}(2)$,
where $\operatorname{Ad}\;:\;\mathrm{SU}(2)\;\longrightarrow\;\operatorname{Aut}(\mathbb{R}^{3})$
is the adjoint representation,
\emph{namely}
\[
\operatorname{Ad}_{u}(v)=u\,v\,u^{-1},
\qquad
u\in\mathrm{SU}(2),\;v\in\mathbb{R}^{3}\cong\mathfrak{su}(2)=\mathrm{Lie}(SU(2)).
\]
By applying Example \ref{exLSBzappa} we obtain a LSB
$(\mathbb{R}^{3}\times\mathrm{SU}(2), \cdot, \circ)$
where  both $(\mathbb{R}^{3}\times\mathrm{SU}(2), \cdot )$
and $(\mathbb{R}^{3}\times\mathrm{SU}(2), \circ )$ are of {\em mixed-type} and not isomorphic.

\medskip

\noindent
\textbf{Step 2. The trivial cases \(({\cong})\).} 
A connected LSB \(\bigl(G,\cdot,\circ\bigr)\) is \emph{trivial} whenever the two
underlying Lie group structures \(\bigl(G,\cdot\bigr)\) and
\(\bigl(G,\circ\bigr)\) are both abelian.  
Indeed, on a connected manifold any two abelian Lie
group laws are isomorphic.
The only other trivial situations are those in which
\(\bigl(G,\cdot\bigr)\) and \(\bigl(G,\circ\bigr)\) are simultaneously
semisimple (or even simple).  
These follow directly from condition~\(\mathbf{(R2)}\) in
Theorem~\ref{mainteor}.

\medskip
\noindent
\textbf{Step 3. The non-existence cases \(({-})\).}  
Every remaining entry marked by a dash \(({-})\) represents a
\emph{non-existence} phenomenon.  
Such combinations are ruled out by
\(\mathbf{(S2)}\) together with \(\mathbf{(R1)}\) of
Theorem~\ref{mainteor}.

\end{proof}




