\subsection{The Asymptotic Character Formulas}
\label{sec:asymptotic_characeter_formula}

In this section, we study how the actions $\alpha^0$ on $T^*M$ and $\rho^h$ on $L^2(M)$ extend to the tangent groupoid, and we obtain the asymptotic character formulas. The main ingredients are the following two extension lemmas. 

\begin{lemma}
    \label{lem:scalar_extension_to_TGM}
    Let $g \colon [0, 1] \times M \to \C$ be a smooth map. Then, $\tilde g(0, v_x) = g(0, x)$ and $\tilde g(h, x, y) = g(h, x)$ defines a smooth map $\tilde g \colon \TGM \to \C$.
\end{lemma}

\begin{proof}
    It is clear that $\tilde g$ is smooth on $(0, 1] \times M \times M \subset \TGM$. Letting $\pi \colon TM \to M$ be the canonical projection and employing the diffeomorphism $\beta$ \eqref{eq:Phi_boundary}, we see that $(\tilde g \circ \beta)(h, v_x) = g(h, x) = g \circ (\id_{[0, 1]} \times\pi)(h, v_x)$, which is smooth on $V_\beta \subset [0, 1] \times TM$.   
\end{proof}

\begin{lemma}  
    \label{lem:diffeo_extension_to_TGM}
    Let $F \colon [0, 1] \times M \to M$ be a smooth map. Then,
    \begin{align*}
        \widetilde F(0, v_x) = \bigl( 0, T_{(0, x)}F(1, v_x) \bigr) \quad \text{and} \quad \widetilde F(h, x, y) = \bigl(h, F(h, x), F(0, y) \bigr) 
    \end{align*}
    with $(1, v_x) \in \R \times T_x M \cong T_{(0, x)} ([0, 1] \times M)$, defines a smooth map $\widetilde F \colon \TGM \to \TGM$.
\end{lemma}

\begin{proof}
    The map
    \begin{align*}
        G \colon V_{\beta} &\to M \times M, \quad (h, v_x) \mapsto \bigl( F(0, x), F(h, \exp_x(-h v_x)) \bigr)
    \end{align*}
    is clearly smooth and maps $\{0\} \times TM$ into the diagonal of $M \times M$. In particular, the preimage of $\expTGM(U_{TM}) \subset M \times M$ under $G$ is a neighborhood of $\{0\} \times TM$ in $V_\beta \subset [0, 1] \times TM$, which we denote by $V$. Noting that $(\expTGM)^{-1} \circ \, G(h, v_x) \in T_{F(x, 0)}M$, independently of $h$, we define $\widetilde G \colon V \to TM$ via
   \begin{align*}
        \widetilde{G}(h,v_x)=\begin{cases}
        \frac1h \Bigl ((\expTGM)^{-1} \circ G (h, v_x) - (\expTGM)^{-1} \circ G(0, v_x) \Bigr) & h \neq 0  \\
        \lim_{h \to 0} \frac1h \Bigl ((\expTGM)^{-1} \circ G (h, v_x) - (\expTGM)^{-1} \circ G (0, v_x) \Bigr) & h=0.\end{cases}
    \end{align*}
    This is well-defined by smoothness of $(\expTGM)^{-1} \circ \, G \colon V \to TM$, and Schwarz's theorem (\cite[8.12.4]{Die60}; symmetry of mixed partial derivatives) implies that it is smooth. Now, $(\expTGM)^{-1} \circ \, G (0, v_x)$ is the zero vector in $T_{F(0, x)} M$, whence
    \begin{align*}
        \widetilde G(0, v_x) = -\lim_{h \to 0} \frac1h \exp_{F(0, x)}^{-1} \circ \, F \bigl(h, \exp_x(-h v_x) \bigr).
    \end{align*}
    This is the derivative of the curve $h \mapsto -\exp_{F(0, x)}^{-1} \circ \, F(h, \exp_x(-h v_x)) $ in $T_{F(0, x)}M$ at $h = 0$, which (by the chain rule) equals
    \begin{align*}
        -\bigl( T_{F(0, x)}\exp_{F(0, x)}^{-1} \circ \, T_{(0, x)}F \bigr)(1, -v_x) = T_{(0, x)}F(-1, v_x),
    \end{align*}
    where we have made the identification $\R \times T_x M \cong T_{(0, x)} ([0, 1] \times M)$. If we now conjugate $(h, v_x) \mapsto (h, \widetilde G(h, v_x))$ by $\beta$, with appropriate restrictions of domains, (using again that $(\expTGM)^{-1} \circ \, G (0, v_x) = 0 \in T_{F(0, x)}M$) we obtain the map
    \begin{align}\label{eq: conv_ext}
        (0, v_x) \mapsto \bigl(0, T_{(0, x)}F(-1, v_x) \bigr) \quad \text{and} \quad (h, x, y) \mapsto \bigl( h, F(0, x), F(h, y) \bigr)
    \end{align}
    restricted to a neighborhood of $\{0\} \times TM$ in $\TGM$. Since $\widetilde G$ is smooth, this map is smooth. Finally, conjugating this map by the smooth inversion $\TGM \to \TGM$ ($(0, v_x) \mapsto (0, -v_x)$ and $(h, x, y) \mapsto (h, y, x)$) yields $\widetilde F$.
\end{proof}

Recall that a \textit{double centralizer} of a C$^*$-algebra $\mathcal A$ is a pair of bounded linear maps $L, R \colon \mathcal A \to \mathcal A$ satisfying $aL(b) = R(a)b$ for all $a, b \in \mathcal A$. The \textit{multiplier algebra} $M(\mathcal A)$ of $\mathcal A$, which, loosely speaking, is the largest non-degenerate unitization of $\mathcal A$, can be identified with the collection of all double centralizers of $\mathcal A$. In particular, $M(\mathcal B_0(L^2(M))) = \mathcal B(L^2(M))$ and $M(C_0(T^*M)) = C_b(T^*M)$ (the continuous and \textit{bounded} functions on $T^*M$). Since $\exp(-2\pi i \mathcal Q^h H_{(X, f)}) = \rho^h_{\exp(h f, h X)}$ by \Cref{prop:derived_rep}, the following result shows that $e^{-2\pi i H_{(X, f)}}$ is the classical limit of $(\exp(-2\pi i \mathcal Q^h H_{(X, f)}))_{h \in (0, 1]}$.

\begin{theorem}
    \label{thm:double_centralizer}
    For every $(X, f) \in \gM$, we obtain a pair of bounded linear maps $L_{(X, f)}, R_{(X, f)} \colon C^*(\TGM) \to C^*(\TGM)$ via
    \begin{align*}
        L_{(X, f)} (a, T_h) &= \bigl( ae^{-2 \pi i H_{(X, f)}}, \rho^h_{\exp(hX, hf)}T_h \bigr) \\ \text{and} \quad
        R_{(X, f)} (a, T_h) &= \bigl( a e^{-2 \pi i H_{(X, f)}}, T_h\rho^h_{\exp(hX, hf)} \bigr).
    \end{align*}
    Moreover, these preserve $C_c^\infty(\TGM)$ and constitute a double centralizer of $C^*(\TGM)$.
\end{theorem}
\begin{remark}\label{rem:left-right}
One can obtain $R_{(X, f)}$ by conjugating $L_{(-X, -f)}$ with the involution on $C^*(\TGM)$. Similarly, the extensions in the earlier Lemmata in this section (i.e. \Cref{lem:scalar_extension_to_TGM},\Cref{lem:diffeo_extension_to_TGM}) admit corresponding versions by conjugating with inversion. We have actually used such a version in \eqref{eq: conv_ext} as it was more convenient for our  proof. 
\end{remark}
\begin{proof}[Proof of \Cref{thm:double_centralizer}]
    In view of \Cref{rem:left-right} it is sufficient to show that $L_{(X, f)} \colon C_c^\infty(\TGM) \to C_c^\infty(\TGM)$ makes sense. From there, it is clear that both mappings (as isometric linear maps) extend to $C^*(\TGM)$ and constitute a double centralizer. 

    Let $(a, T_h) \in C_c^\infty(\TGM)$ and let $K_h$ be the integral kernel of $T_h$. Then, 
    \begin{align*}
        \fiberF \bigl( ae^{-2 \pi i H_{(X, f)}} \bigr)(v_x) &= \int_{T^*M} a(\eta_x) e^{-2 \pi i f(x)} e^{2\pi i \eta_x(v_x - X_x)} \,d\lambda^*_x(\eta_x) \\ &= e^{-2 \pi i f(x)} \fiberF a (v_x - X_x),
    \end{align*}
    while the kernel of $\rho^h_{\exp(hX, hf)} T_h$ is
    \begin{align*}
        e^{-2\pi i f_h(x) } \sqrt{\frac{d \bigl(\Fl_1^{-hX} \bigr)^* \vol }{d\vol}}(x) K_h \bigl(\Fl_1^{-hX}(x), y \bigr), \text{ where } f_h \coloneqq \int_0^1 f \circ \Fl^{-hX}_t \,dt
    \end{align*}
    (cf.\ \Cref{eq:exp_map}).
    Showing that $L_{(X, f)}(a, T_h)$ is an element of $C_c^\infty(\TGM)$ therefore amounts to showing that the function $\TGM \to \C$ defined by
    \begin{equation}
        \label{eq:proof_of_double_centralizer}
        \begin{split}
        (0, v_x) &\mapsto e^{-2\pi i f(x)} \fiberF a(v_x - X_x) \\
        \text{and} \quad (h, x, y) &\mapsto e^{-2\pi i f_h(x) } \sqrt{\frac{d \bigl( \Fl_1^{-hX} \bigr)^* \vol }{d\vol}}(x) h^d K_h \bigl(\Fl_1^{-hX}(x), y \bigr)
        \end{split}
    \end{equation}
    is smooth and compactly supported. Compact support is clear; we will show smoothness.

    We obtain \eqref{eq:proof_of_double_centralizer} from the smooth function $(\fiberF a, h^d K_h)$ by applying the coordinate transformation $\TGM \to \TGM$ given by
    \begin{align}
        \label{eq:proof_of_double_centralizer_2}
        (0, v_x) \mapsto (0, v_x - X_x) \quad \text{and} \quad (h, x, y) \mapsto \bigl(h, \Fl_1^{-hX}(x), y \bigr),
    \end{align}
    and then multiplying with the function $\TGM \to \C$ given by
    \begin{align}
        \label{eq:proof_of_double_centralizer_3}
        (0, v_x) \mapsto e^{-2\pi i f(x)} \quad \text{and} \quad
        (h, x, y) \mapsto e^{-2\pi i f_h(x) } \sqrt{\frac{d \bigl( \Fl_1^{-hX} \bigr)^* \vol }{d\vol}}(x).
    \end{align}
    Defining $F \colon [0, 1] \times M \to M$ by $(h, x) \mapsto \Fl_1^{-hX}(x) = \Fl_h^{-X}(x)$, \eqref{eq:proof_of_double_centralizer_2} is the smooth map $\widetilde F \colon \TGM \to \TGM$ from \Cref{lem:diffeo_extension_to_TGM} (recall that the flow of $X$ is smooth). To see that \eqref{eq:proof_of_double_centralizer_3} is smooth requires a bit more work. 

    For each $t \in [0, 1]$, define $F^t \colon [0, 1] \times M \to M$ by $(h, x) \mapsto \Fl^{-tX}_h(x)$. Then, the smooth maps $\widetilde F^t \colon \TGM \to \TGM$ from \Cref{lem:diffeo_extension_to_TGM} satisfy $\widetilde F^t(0, v_x) = (0, v_x - tX_x)$. Applying \Cref{lem:scalar_extension_to_TGM} to $g(h, x) = f(x)$, we see that the map $G\colon [0,1] \times \TGM \to \C$,
    \begin{align*}
        G \bigl(t,(0, v_x) \bigr) \mapsto f(x) \quad \text{and} \quad G \bigl(t,(h, x, y) \bigr) \mapsto  f \circ \Fl_h^{-tX}(x) = f \circ \Fl_t^{-hX}(x)
    \end{align*}
    is continuous and for each fixed $t \in [0, 1]$ smooth, since $G(t, \cdot) = \tilde g \circ \widetilde F^t (\cdot)$. By smooth parameter dependence of the integral \cite[8.11.12]{Die60}, $(h, \cdot) \mapsto \int_0^1 G (t, (h, \cdot)) \,dt$  is smooth, but this is the map $(0, v_x) \mapsto f(x)$ and $(h, x, y) \mapsto f_h(x)$. Finally, invoking \Cref{lem:scalar_extension_to_TGM} and \Cref{lem:Radon_Nikodym_formula} (along with $\Fl_1^{-hX} = \Fl_h^{-X}$) to deal with the Radon-Nikodym derivative, we conclude that \eqref{eq:proof_of_double_centralizer_3} is smooth. This proves that $L_{(X, f)}$ preserves $C_c^\infty(\TGM)$ and thus concludes the proof.
\end{proof}

We are now prepared to prove the asymptotic character formulas.

\begin{prop}
    \label{prop:easy_trace_formula}
    For any $(a, T_h) \in C_c^\infty(\TGM)$, 
    \begin{align*}
        \lim_{h \to 0} h^d \,\tr(T_h) = \int_{T^*M} a \,dV_L.
    \end{align*}
\end{prop}
\begin{proof}
    By definition of the fiberwise Fourier transform,
    \begin{align*}
        \int_{T^*M} a \,dV_L = \int_M \int_{T_x^*M} a(\eta_x) \,d\lambda^*_x(\eta_x)\,dV_g(x) = \int_M \fiberF a(0_x)\,dV_g(x).
    \end{align*}
    If $K_h$ denotes the integral kernel of $T_h$, then $\tr(T_h) = \int_M K_h(x, x)\,dV_g(x)$ (see e.g.\ \cite{Brislawn91}). The smooth submanifold $[0, 1] \times M \hookrightarrow \TGM$ given by
    \begin{align*}
        (0, x) &\mapsto (0, 0_x) \quad \text{and} \quad (h, x) \mapsto (h, x, x)
    \end{align*}
    is (topologically) closed. Indeed, under the diffeomorphism $\beta \colon V_\beta \to U_\beta \subset \TGM$, it corresponds to $[0, 1] \times 0_{TM} \subset V_\beta$, where $0_{TM}$ denotes the zero-section. 

    The condition $(a, T_h) \in C_c^\infty(\TGM)$ means that
    \begin{align*}
        (0, v_x) \mapsto \fiberF a(v_x) \quad \text{and} \quad (h, x, y) \mapsto h^d K_h(x, y)
    \end{align*}
    is smooth and compactly supported on $\TGM$. Consequently, its restriction to $[0, 1] \times M$,
    \begin{align}
        \label{eq:proof_of_trace_formula}
        (0, x) &\mapsto \fiberF a(0_x) \quad \text{and} \quad (h, x) \mapsto h^d K_h(x, x)
    \end{align}
    is smooth and compactly supported on $[0, 1] \times M$. The result now follows from an application of the dominated convergence theorem \cite[Theorem 22.29]{Sch97}:\ Consider the projection of the support of \eqref{eq:proof_of_trace_formula} to $\{0\} \times M$ (projecting along the unit interval), take the indicator function of the resulting set and multiply by the maximum of \eqref{eq:proof_of_trace_formula}. This compactly supported function dominates the functions $x \mapsto \fiberF a(0_x)$ and $x \mapsto h^d K_h(x, x)$ for $h \in (0 , 1]$, the latter of which converges pointwise to the former as $h \to 0$.
\end{proof}

\begin{remark}
    \label{rem:character_formula}
    We have not been able to find \Cref{prop:easy_trace_formula} in the literature, which seems surprising, given its rather trivial nature. The point of closest approach might be \cite[Remark~5.4.3]{HigsonNigel2019SatT}, where a big point is made of the fact that the traces of $T_h$ diverge as $h \to 0$. This is of course an immediate consequence of \Cref{prop:easy_trace_formula}. Presumably, \Cref{prop:easy_trace_formula} is simply uninteresting from the point of view of index theory, which is the main arena for the tangent groupoid. In the context of quantization, however, trace formulas of this kind are important. Indeed, we have already exposed the connection to character formulas in the context of the orbit method, and a non-asymptotic variant of \Cref{cor:character_formula} is the starting point for the field of quantum harmonic analysis \cite{Werner84}. A non-asymptotic trace formula for Weyl quantization on the tangent groupoid can be found in \cite{CariñenaEtAl}. Similar asymptotic formulas also appear in the context of Toeplitz quantization \cite{Berman06, Schlichenmaier00}.
\end{remark}

\begin{corollary}
    \label{cor:character_formula}
    For any $(a, T_h) \in C_c^\infty(\TGM)$ and $(X, f) \in \gM$,
    \begin{align*}
        \lim_{h \to 0} h^d \, \tr \bigl(\rho^h_{\exp(hX, hf)} T_h \bigr) = \int_{T^*M} a e^{-2\pi i H_{(X, f)}} \,dV_L.
    \end{align*}
\end{corollary}
\begin{proof}
    Combine \Cref{thm:double_centralizer} and \Cref{prop:easy_trace_formula}.
\end{proof}


We can also use \Cref{lem:diffeo_extension_to_TGM} to generalize a result on Weyl quantization due to Landsman \cite[Theorem~5]{Landsman1993}. Recall the action $\alpha^0$ of $\GM$ on $T^*M$ \eqref{eq:alpha_0}. The induced action on $C_0(T^*M)$ is $\alpha^0_{(\phi, f)} a \coloneqq a \circ (\alpha^0_{(\phi, f)})^{-1} = a \circ \alpha^0_{(\phi^{-1}, -f\circ \phi)}$, i.e.\
\begin{align*}
    \alpha^0_{(\phi, f)}a (\eta_x) = a \bigl( \phi^*(\eta_x + df_x) \bigr) \quad \text{for } \eta_x \in T_x^*M.
\end{align*}
Note that $\phi^*(\eta_x + df_x) \in T_{\phi^{-1}(x)}^*M$. For $(\phi, f) \in \GM$, we now define the quantum counterpart, $\alpha^h_{(\phi, f)} \colon \mathcal B(L^2(M)) \to \mathcal B(L^2(M))$, by $\alpha^h_{(\phi, f)} T = \rho^h_{(\phi, f)} T (\rho^h_{(\phi, f)})^*.$

\begin{prop}
    \label{prop:translation_of_ops}
    For any $(\phi, f) \in \GM$, the map
    \begin{align*}
        \alpha_{(\phi, f)} \colon (a, T_h) \mapsto \alpha_{(\phi, f)}(a, T_h) \coloneqq (\alpha^0_{(\phi, f)}a, \alpha_{(\phi, f)}^h T_h)
    \end{align*}
    is a $*$-automorphism of $C^*(\TGM)$ that preserves $C_c^\infty(\TGM)$.
\end{prop}
\begin{proof}
    It suffices to show that $\alpha_{(\phi, f)} \colon C_c^\infty(\TGM) \to C_c^\infty(\TGM)$ makes sense. From there, it is clear that it (as an isometric $*$-automorphism) extends to $C^*(\TGM)$. 

    Let $(a, T_h) \in C_c^\infty(\TGM)$, $q \colon U \to \Rd$ be coordinates on $M$ and $x \in U$. Taking $\widetilde q \coloneqq q \circ \phi$ as coordinates on $\phi^{-1}(U)$, the associated cotangent coordinates $(\widetilde q, \widetilde p)$ are given by $\widetilde p = p \circ (\phi^{-1})^*$. This follows from
    \begin{align*}
        \widetilde p^j ( \phi^* \eta_x) = \eta_x \Bigl( T\phi \tfrac{\partial}{\partial(q \circ \phi)^j}\big|_{\phi^{-1}(x)} \Bigr) = \eta_x \Bigl( \tfrac{\partial}{\partial q^j}\big|_x \Bigr) = p^j(\eta_x).
    \end{align*}
    Thus, with respect to the $p$ and $\widetilde p$ coordinates on $T_xM$ and $T_{\phi^{-1}(x)}M$, $\phi^*$ is the identity. Consequently, by definition of $\lambda^*_x$ and \Cref{lem:Radon_Nikodym_formula},
    \begin{align*}
        \frac{d((\phi^*)^{-1})^*\lambda_x^*}{d\lambda_{\phi^{-1}(x)}^*}(\eta_{\phi^{-1}(x)}) = \Biggl|\frac{\det g_{q \circ \phi}(\phi^{-1}(x))}{ \det g_q(x)} \Biggr|^{\frac12} = \frac{d (\phi^{-1})^* V_g}{dV_g}(x),
    \end{align*}
    which gives
    \begin{align*}
        \fiberF (\alpha^0_{(\phi, f)} a)(v_x) &= e^{-2\pi i v_x(f)}\int_{T^*_xM} a \circ \phi^*(\eta_x) e^{2\pi i \eta_x(v_x)} \,d\lambda^*_x(\eta_x) \\ &= e^{-2\pi i v_x(f)} \frac{d (\phi^{-1})^* V_g}{dV_g}(x) \fiberF a(T\phi^{-1} v_x).
    \end{align*}
    By a change of variables, the integral kernel of $\alpha_{(\phi, f)}^h T_h$ is 
    \begin{align*}
        e^{-2\pi i (f(x) - f(y))/h} \sqrt{\frac{d(\phi^{-1})^*\vol}{dV_g}}(x) \Biggl(\frac{d \phi^*V_g}{d V_g} \bigl(\phi^{-1}(y)\bigr) \Biggr)^{-\frac12}  K_h\bigl( \phi^{-1}(x), \phi^{-1}(y) \bigr).
    \end{align*}
    For $y \in U$, $\widetilde q = q \circ \phi$ are coordinates around $\phi^{-1}(y)$, whence \Cref{lem:Radon_Nikodym_formula} gives
    \begin{align*}
        \frac{d\phi^*V_g}{dV_g} \bigl(\phi^{-1}(y)\bigr) = \Biggl| \frac{\det g_{\widetilde q \circ \phi^{-1}}(y)}{\det g_{\widetilde q}(\phi^{-1}(y))} \Biggr|^{\frac12} = \Biggl(\frac{d (\phi^{-1})^*V_g}{dV_g} (y)\Biggr)^{-1}.
    \end{align*}
    Consequently, in terms of functions on $\TGM$, we obtain $\alpha_{(\phi, f)}(a, T_h)$ from $(a, T_h)$ by applying the coordinate transformation $\TGM \to \TGM$ given by
    \begin{align*}
        (0, v_x) \mapsto (0, T \phi^{-1} v_x) \quad \text{and} \quad (h, x, y) \mapsto \bigl( h, \phi^{-1}(x), \phi^{-1}(y) \bigr),
    \end{align*}
    and then multiplying with the function $\TGM \to \C$ given by
    \begin{align*}
        (0, v_x) &\mapsto e^{-2\pi i v_x(f)} \frac{d (\phi^{-1})^* V_g}{dV_g}(x) \\
        \text{and} \quad (h, x, y) &\mapsto e^{-2\pi i (f(x) - f(y))/h}\sqrt{\frac{d (\phi^{-1})^* V_g}{dV_g}(x) \frac{d (\phi^{-1})^* V_g}{dV_g}(y)}.
    \end{align*}
    Smoothness of the coordinate transformation follows from \Cref{lem:diffeo_extension_to_TGM} applied to $F(h, x) = \phi^{-1}(x)$. Smoothness of the function $\TGM \to \C$ is straightforward to show using \Cref{lem:Radon_Nikodym_formula} and the diffeomorphism $\beta$, as well as the fact that on the tangent groupoid, the difference quotients $(h, x, y) \mapsto (f(x)-f(y))/h$ extend to a smooth map via $(0, v_x) \mapsto v_x(f)$ \cite[Appendix~C.16]{Landsman_Foundations}.
\end{proof}


\appendix

\section{Manifolds of Mappings and Dual Spaces}\label{app:mfd_smooth_maps}

In this section, we recall essentials on spaces of smooth maps from a not necessarily compact manifold $M$ with values in another manifold. Our aim is then to realize the cotangent bundle $T^*M$ as an embedded submanifold of the dual space of an infinite-dimensional Lie algebra constructed from $M$.

\begin{setup}
Let $M$ and $N$ be $\sigma$-compact smooth manifolds without boundary. We write $C^\infty (M,N)$ for the set of all smooth functions from $M$ to $N$. There are two topologies (see e.g.\ \cite{HaS17}) on this set:
\begin{enumerate}
\item The \textit{compact open $C^\infty$-topology} is the initial topology with respect to \[C^\infty (M,N) \rightarrow \prod\nolimits_{k\in \N_0} C_{\mathrm{co}}(T^kM,T^kN), \quad f \mapsto (T^k f)_{k\in \N_0},\]
where the subscript denotes the usual compact open topology.
We write $C^\infty_{\mathrm{co}} (M,N)$ for this topology. It controls a function and its  derivatives on compact sets.
\item The \textit{fine very strong topology}, also called the $\mathcal{FD}$-topology in \cite{Mic80}. It controls functions and derivatives on locally finite families of compact sets.
\end{enumerate}
For non-compact $M$, the first topology does not turn $C^\infty(M,N)$ into a manifold, while the second does.  If $M$ is compact, both topologies coincide, see e.g.\ \cite{HaS17}.
\end{setup}
\begin{setup}\label{setup:indlim}
Let $M$ be a $\sigma$-compact manifold and $E \rightarrow M$ a smooth vector bundle.
We write $\Gamma(E)$ for the \emph{set of smooth sections} of $E$, and let $0 \in \Gamma(E)$ be the \emph{zero-section}.
For a compact subset $K \subseteq M$, consider the subspace of smooth \emph{sections supported in} $K$, i.e.
\begin{equation*}
    \Gamma_{K}(E) \coloneq \{ \sigma \in \Gamma(E) : \sigma|_{X \setminus K} = 0 \}.
\end{equation*}
Topologize $\Gamma_K(E)$ with the subspace topology $\Gamma_K(E) \subseteq C^{\infty}_{\mathrm{co}}(M,E)$.
Note that $\Gamma_K(E) \subseteq \Gamma_L(E)$ if the compact sets satisfy $K\subseteq L$. This inclusion is a topological embedding and the spaces $\Gamma_K(E)$ are Hausdorff locally convex spaces, \cite[Remark F.8]{glo04}.
The \emph{space of compactly supported sections} is defined as
$$\Gamma_c (E) := \bigcup_{K \subseteq M \text{ compact}} \Gamma_K (E).$$
Letting $K$ range over the compact subsets of $M$, using $\Gamma_K(E) \subseteq \Gamma_c(E)$, we topologize 
\begin{align}
    \label{defn:indlim}
    \Gamma_c(E) \coloneq \varinjlim \Gamma_K(E) 
\end{align}
as a locally convex inductive limit. The resulting topology on $\Gamma_c(E)$ is a Hausdorff locally convex vector topology by \cite[Lemma F.19 (c)]{glo04}.
Note that $\X (M) = \Gamma (TM)$. Similarly, we denote by $\X_c(M)$ and $\X_K(M)$ the spaces of vector fields with compact support and support in $K$, respectively.
\end{setup}

For the trivial bundle $M\times \R^n$ ($n \in \N$) over $M$, we have a canonical identification $\Gamma (M\times \R^n) \cong C^\infty (M, \R^n)$. This introduces a topology on the set of smooth, compactly supported functions by declaring $\Gamma_c (M\times \R^n) \cong C^\infty_c (M,\R^n)$ a homeomorphism. Similarly, but restricting to $\Gamma_K (M\times \R^n)$, we obtain the compact open $C^\infty$-topology on the image $C^\infty_K (M,\R^n)$.

Let $\pi \colon E\rightarrow M$ be a finite rank vector bundle. As \cite[Proposition 4.8 and Remark 8.6]{Mic80} show, the subspace topology on $\Gamma_c(E) \subseteq C^\infty (M,E)$ induced by the fine very strong topology coincides with the inductive limit topology \eqref{defn:indlim}. 
\begin{setup}\label{verystrong_convention}
The resulting topology on $C^\infty_c(M,\R^n)$ and $\Gamma_c (E)$ is called the fine very strong topology. We will always endow these spaces with this topology.
\end{setup}

For $\sigma$-compact manifolds, the fine very strong topology turns $C^\infty (M,N)$ into an infinite-dimensional smooth manifold (see e.g.\ \cite{Mic80,GaS22}). The model spaces of this manifold are locally convex spaces of sections $\Gamma_c (f^\ast TN)$ into pullback bundles, which are not Banach spaces. Hence, smoothness has to be interpreted in the sense of Bastiani calculus, cf.\ \cite{Sch23}. This means that a map is smooth if and only if locally in charts all of its (iterated) directional derivatives exist and combine to form continuous mappings. As a consequence:

\begin{lemma}\label{ev_smooth_subm}
Let $M$ and $N$ be finite-dimensional manifolds. For $x \in M$, 
\[\ev_x \colon C^\infty (M,N) \rightarrow N, \quad\ev_x (f)=f(x) \text{ is a smooth submersion.}\]
\end{lemma}

\begin{proof}
Smoothness of $\ev_x$ is established in \cite[Corollary 11.7]{Mic80}. The canonical identification $TC^\infty (M,N) \cong C^\infty (M,TN)$ from \cite{Mic80} yields an identification between $T\ev_x$ and $\widetilde{\ev}_x$, with $\widetilde{\ev}_x \colon C^\infty (M,TN)\rightarrow TN, F \mapsto F(x)$ the evaluation. Since every $T_f\ev_x$ is surjective, $\ev_x$ is a submersion by \cite[Theorem A]{glo15}. 
\end{proof}

\begin{setup}
The diffeomorphism group $$\Diff (M) := \{\phi \in C^\infty (M,M) \colon \phi \text{ is bijective and } \phi^{-1} \in C^\infty (M,M)\}$$ of a $\sigma$-compact manifold $M$ is open in the fine very strong topology \cite[Corollary 5.7]{Mic80}. Its unit component is 
$$\DiffcM=\{\phi \in \Diff(M) \colon \exists K \subseteq M \text{ compact, s.t. } \phi(x)=x,\ \forall x \in M\setminus K\}.$$
This manifold structure turns both groups into Lie groups \cite[Theorem 11.11]{Mic80}.\footnote{The term Lie group here is used for a group which is also a (possibly infinite-dimensional) manifold such that the group operations become smooth maps, see \cite{Neeb06,Sch23}.} The associated Lie algebra is $\mathbf{L}(\Diff(M)) = \X_c(M)$ with the negative of the usual bracket of vector fields.
\end{setup}

By \cite[Theorem 11.4]{Mic80}, the action 
\begin{equation}
  \gamma \colon   \DiffcM \times \CcMR \rightarrow \CcMR, \quad
    \gamma(\phi, f)= f \circ \phi^{-1}
\label{eq:Lgp_act}
\end{equation}
is a Lie group action. The derived action of the Lie algebra associated to $\gamma$ is computed via the formulae \cite[Corollary 11.6 and Proposition 11.13]{Mic80}, yielding
\begin{align}\label{GM:derived_action}
\mathrm{d}\gamma \colon \XcM \times C_c^\infty (M,\R) \rightarrow C_c^\infty (M,\R), \quad\mathrm{d}\gamma (X,f) =-df\circ X.
\end{align}
Hence, as in the finite-dimensional setting, we consider the semidirect product:

\begin{setup}
For a $\sigma$-compact finite-dimensional manifold $M$, we consider the semidirect product of Lie groups (cf.\ \ref{verystrong_convention} for the topology)
$$\GM := \DiffcM \ltimes_\gamma \CcMR$$
with respect to the Lie group action \eqref{eq:Lgp_act}. As in the finite-dimensional case, $\GM$ is a Lie group and its Lie algebra is the semidirect sum
$$\gM := \mathbf{L}(\GM) = \XcM \ltimes_{\mathrm{d}\gamma} \CcMR.$$
The Lie bracket on $\gM$ is
\begin{align}\label{gm:Liebracket}
        \bigl[ (X,f), (Y, g) \bigr] =  \bigl( -[X, Y], - dg\circ X + df \circ Y \bigr)=\bigl( -[X, Y], - Xg + Yf \bigr),
\end{align}
where the bracket in the left component is the commutator of vector fields. The formula \eqref{gm:Liebracket} arises from the definition of a semidirect sum Lie algebra by plugging in the derived action \eqref{GM:derived_action} and observing that the Lie bracket of $C_c^\infty (M,\R)$ vanishes, while the bracket for $\Diff_c (M)$ is the negative of the usual bracket of vector fields (see e.g.\ \cite[Example 3.25]{Sch23} for an argument that generalizes to $\Diff_c(M)$).
\end{setup}

\subsection{An Embedding into the Dual Space}
We continue to work with the semidirect product of the last section and want to show that $T^*M$ embeds into the dual space of its Lie algebra. Recall that a semidirect product of (topological) Lie algebras is, as a locally convex space, the product of the Lie algebra factors from which it was formed. Hence, we have the following:

\begin{lemma}\label{lem:gm_summand}
There exists $m \in \N$ such that $\gM$ is isomorphic to a complemented locally convex subspace of $C^\infty_c (M,\R^{m+1})$.
\end{lemma}

\begin{proof}
Since $M$ is paracompact and $TM$ a finite rank bundle, by \cite[Lemma 5.9 and Exercise 5E]{MaS74}, we can find a vector bundle $E \rightarrow M$ such that the Whitney sum $TM \oplus E$ is isomorphic, as a vector bundle, to a trivial bundle $M \times \R^m$. Hence, \cite[4.7.9]{Mic80} implies that $C^\infty_c (M, \R^m) \cong \Gamma_c (TM \oplus E) \cong \Gamma_c (TM) \times \Gamma_c(E) = \X_c(M) \times \Gamma_c(E)$. We realize $\gM$ as a complemented subspace via the embedding $\gM = \X_c(M) \times C_c^\infty (M,\R) \rightarrow C_c^\infty(M,\R^m)\times C_c^\infty(M,\R) \cong C_c^\infty(M,\R^m\times \R)$.
\end{proof}

As a consequence of \Cref{lem:gm_summand}, the (continuous) dual of $\gM$ can be identified with a summand of the dual of $C_c^\infty (M,\R^{m+1})$:
$$\gM^\ast = \X_c(M)^\ast \times \CcMR^\ast \subseteq C_c^\infty (M,\R^{m+1})^\ast.$$
There is a whole range of natural topologies on the dual $V^*$ of a locally convex space $V$, all of which lie between two extreme topologies (see e.g.\ \cite{Tre06}): 
\begin{itemize} 
\item  the \textit{weak$^*$-topology}, defined by the seminorms $V^* \ni f \mapsto |f(v)|$ for $v \in V$. 
\item  the \textit{strong topology}, defined by the seminorms 
$V^* \ni f \mapsto \sup\nolimits_{v \in B} |f(v)|
$, where $B$ ranges over the bounded subsets of $V$. 
\end{itemize}  
The strong topology is clearly stronger than the weak$^*$-topology.
Our results will hold for all locally convex topologies between (i.e.\ finer than) the weak$^*$-topology and (coarser than) the strong topology on $\gM^*$. Because $\gM$ is a Montel space, these are precisely the locally convex topologies for which $(\gM^*)^* \cong \gM$ via evaluation, cf.\ \cite[Proposition 36.9]{Tre06}. 

Endow $\R^{m+1}$ with the maximum norm $\lVert \cdot \rVert$ and write $\lVert \cdot \rVert_{\mathrm{op}}$ for the (multilinear) operator norms derived from this choice. Recall from \cite[Proposition 1.13 and Appendix C]{HaS17} that the fine very strong topology on $C_c^\infty (M,\R^{m+1})$ is constructed from the following family of seminorms, indexed by $r\in \N_0$ and the compact subsets $K \subseteq M$ such that $K \subseteq U$ for some chart $q \colon U \to \R^d$ on $M$:
\begin{align}\label{seminorm_defn}
 \lVert f \rVert_{(r,K,q)}\coloneq \sup\nolimits_{x\in K} \bigl\{\lVert f(x)\rVert,\lVert d^k(f \circ q^{-1}) (q(x) ; \cdot )\rVert_{\mathrm{op}} : 1\leq k \leq r\bigr\},
\end{align}
where $d^k(f\circ q^{-1})$ denotes the $k$th iterated derivative of a vector valued function. A local base at the origin for the fine very strong topology is obtained by taking intersections $\bigcap_{j \in J} \{ f \in C_c^\infty(M, \R^{m+1}) : \| f \|_{(r_j, K_j, q_j)} < \epsilon_j\}$, where the only restriction is that $(K_j)_{j \in J}$ is locally finite and $\epsilon_j > 0$. In particular, the seminorms \eqref{seminorm_defn} are continuous on $C_c^\infty(M, \R^{m+1})$.

We need the following version of the Arzela-Ascoli theorem. 

\begin{lemma}\label{lem:Arz_Asc}
    Let $M$ be a manifold, $q \colon U \to \Rd$ a chart on $M$, $m\in \N_0$, and suppose that $B \subset C^\infty_c(M, \R^{m+1})$ is bounded. Then, for every compact $K \subseteq U$ and $r \in \N_0$, we have that $\sup_{f \in B}\lVert f\rVert_{(r,K,q)} < \infty$. Furthermore, for every $N \in \N_0$ there is a constant $C(N,K)$ such that, for all $x,y \in q(K)$,
    \begin{align}\label{eq:econt_est}
        \sup\nolimits_{f \in B} \lVert d^N (f\circ q^{-1})(y; \cdot) - d^N (f\circ q^{-1})(x;\cdot) \rVert_\mathrm{op}   &\leq C(N,K) \| y - x \|,
    \end{align}
    where we interpret $\lVert \cdot \rVert_\mathrm{op}$ as $\lVert \cdot \rVert$ when $N = 0$.
\end{lemma}
\begin{proof}
    As the seminorms \eqref{seminorm_defn} are continuous on $C_c^\infty (M,\R^{m+1})$, the first statement is an immediate consequence of boundedness. For the second statement, note that the chart $q \colon U \to \Rd$ induces via restriction to $U$ and composition with $q^{-1}$ a continuous linear map 
    \begin{align*}
        C^\infty_c (M,\R^{m+1}) \xrightarrow{\text{res}} C^\infty (U, \R^{m+1}) \xrightarrow{(q^{-1})^\ast} C^\infty_{\mathrm{co}} \bigl(q(U),\R^{m+1} \bigr), \quad f \mapsto f|_U \circ q^{-1},
    \end{align*}
    where $C^\infty (U, \R^{m+1})$ carries the locally convex topology induced by the seminorms \eqref{seminorm_defn} (which is precisely the compact open $C^\infty$ topology).
    Continuous linear maps preserve bounded sets, so \cite[Example~3.9.3]{Horvath} now implies \eqref{eq:econt_est}.
\end{proof}

Recall the moment map $\mu \colon T^*M \to \gM^*$ from \Cref{prop:moment_map}.

\begin{prop}
    \label{app:topologies}
    The map $\cO \colon T^*M \to \gM^*$ is a smooth embedding for any locally convex topology between the weak$^*$ and the strong topologies on $\gM^*$.
\end{prop}

\begin{proof}
Following \Cref{lem:gm_summand} and the subsequent discussion of the continuous dual, $\gM^\ast$ is a complemented subspace of $C^\infty_c(M,\R^m \times \R)^\ast$ for some $m \in \N$. Hence, we can check that $\cO$ is a smooth immersion and a topological embedding as a mapping into $C^\infty_c(M,\R^m \times \R)^\ast \cong C^\infty_c(M,\R^m)^\ast \times C^\infty_c(M,\R)^\ast$.
Since continuity, smoothness and the immersion property are local, it suffices (for those properties) to work in a chart $q \colon U \to \R^d$ on $M$ around some generic point $x$. For ease of notation, we will then identify $U$ with $q(U)$ and $f$ with $f \circ q^{-1}$. Throughout the proof, $K \subset U$ will be a compact neighborhood of $x$. Moreover, with $E$ as in the proof of \Cref{lem:gm_summand}, we can use the embedding 
$$e \colon T U \rightarrow TM \oplus E \cong M \times \R^m$$
to identify $\eta \in T^\ast_y M\cong (\R^d)^\ast$, for $y \in U$, with $\eta \circ e^{-1} \circ \text{proj}_{e(T_y(M))} \in (\R^{m})^\ast$ (where $\text{proj}_{e(T_y(M))} \colon \{y\} \times  \R^m \rightarrow e(T_yM)$ is the projection onto the subspace). Note that this identification preserves the operator norm of $\eta$ and also convergence in $T^\ast U$. Thus, in the following, we will work with linear forms in $(\R^m)^\ast$. 

\medskip
\noindent \textbf{Step 1: $\cO$ is continuous.} Fix a convergent sequence $(\eta^k)_k \subseteq T^\ast M$ and set $x_k \coloneqq \pi_{T^\ast M}(\eta^k)$ and $\eta \coloneqq \lim \eta^k \in T_x^\ast M$. Then, $x_k = \pi_{T^\ast M}(\eta^k) \rightarrow x = \pi_{T^\ast M} (\eta)$. We establish convergence of $\mu(\eta^k) = (\eta^k, \delta_{x_k})$ to $\mu(\eta) = (\eta, \delta_x)$ in the strong topology on $\gM^\ast$, as this implies convergence in all weaker topologies. Let $B \subseteq \gM\subseteq C^\infty_c(M,\R^m) \times C^\infty (M,\R)$ be bounded. Then, for $(X, f) \in B$ and for $k$ large enough that $x_k \in K$,
\begin{align*}
    &\bigl| \blangle (\eta^k, \delta_{x_k}) - (\eta, \delta_x), (X, f) \brangle \bigr|  
    \leq \lvert \eta^k(X_{x_k}) -  \eta(X_x)\rvert + \lvert f(x_k) - f(x) \rvert\\ &\leq \lvert \eta^k(X_{x_k}) - \eta^k (X_x)\rvert + \lvert \eta^k(X_x)-\eta(X_x)\rvert + \lvert f(x_k) - f(x) \rvert \\
    &\leq \lVert \eta^k\rVert_{\mathrm{op}} \lVert X_{x_k}-X_x\rVert + \lVert \eta^k -\eta\rVert_{\mathrm{op}}\lVert X_x\rVert +  C(0,K)\lVert x_k - x\rVert \\
    &\leq  \bigl(\sup\nolimits_l \lVert \eta^l\rVert_{\mathrm{op}} + 1 \bigr) C(0, K) \|x_k - x\| + \lVert \eta^k -\eta\rVert_{\mathrm{op}}\lVert X_x\rVert 
\end{align*} 
where $C(0,K)$ is the constant from \Cref{lem:Arz_Asc}. Since $\lVert \eta^k-\eta\rVert_{\mathrm{op}}\rightarrow 0$, the last term in the final line converges to $0$ and $\sup\nolimits_l \lVert \eta^l\rVert_{\mathrm{op}} < \infty$. Since $x_k \to x$, we conclude that $\cO$ is continuous.

\medskip
\noindent \textbf{Step 2: $\cO$ is a topological embedding.} By Step 1, we know that $\cO$ is continuous, and it is clearly injective. We will show that it is also open onto its image, hence a topological embedding. It suffices to prove the claim for the weak$^*$-topology on $\gM^*$. Let $\theta \mapsto (\eta^\theta, \delta_{x_\theta})$ be a net in $\cO(T^\ast M) \subset \gM^*$ that converges to $(\eta, \delta_x) \in \cO(T^*M)$. Convergence in the weak$^\ast$-topology means that
\begin{align*}
    \blangle (\eta^\theta, \delta_{x_\theta}), (X, f) \brangle = \eta^\theta (X_{x_\theta}) + f(x_\theta)  \to \blangle (\eta, \delta_x), (X, f) \brangle = \eta(X_x) + f(x) 
\end{align*}
for all $(X, f) \in \gM$. Take $X \equiv 0$ and pick a function $f$ supported in a neighborhood $U$ of $x$ and satisfying $f(x) = 1$. Then, $f(x_\theta) \to 1$, so $x_\theta$ must eventually be contained in $U$. We can repeat this for any $f$ supported in an arbitrarily small neighborhood of $x$, hence $x_k \to x$ in $M$. Take now instead $f \equiv 0$ and $X=\partial_i$ equal to the constant $i$th coordinate vector field on an $x$-neighborhood. As $x_\theta\rightarrow x$, the $i$th component of $\eta^\theta$ converges to the $i$th component of $\eta$. Thus, $\eta^\theta \to \eta$ in $T^*M$.

\medskip
\noindent \textbf{Step 3: $\cO$ is a $C^1$-immersion.} 
We first compute the directional derivatives of $\cO$ in the weak$^\ast$-topology. We then prove that the difference quotients also converge in the strong topology. For the weak$^*$-limits, fix $(X,f) \in \gM \subseteq C^\infty_c (M,\R^m\times \R)$ and $\eta \in T^\ast U \subseteq T^\ast M$. For $\eta=(x,\eta_x) \in U \times (\R^m)^\ast$, $V=(v, S) \in \R^d \times (\R^m)^\ast$ and $t > 0$ small enough that $x+tv \in U$,
\begin{align*}
 \blangle \cO(\eta+tV)-\cO(\eta), (X,f)\brangle &=  (\eta_x +tS)(X_{x+tv})+ f(x+tv)-(\eta_x (X_x)+f(x)) \\
 &= \eta_x (X_{x+tv}-X_x) + t S (X_{x+tv}) + f(x+tv)-f(x).
\end{align*}
Dividing by $t$ and exploiting linearity, the limit becomes
\begin{align}\label{deriv_proxy}
    \blangle d\cO (\eta;V), (X,f) \brangle = \eta_x (dX(x;v))+S (X_x)+df(x;v).
\end{align}
Hence, the limit $d\cO (\eta;V) = \lim_{t \to 0} t^{-1}(\mu(\eta + tV) - \mu(\eta))$ exists in the weak$^*$-topology. To see that it also exists in the strong topology, fix a bounded set $B \subseteq C^\infty_c(M,\R^m\times \R)$. Then, for all $(X,f) \in B$, with the notation as above, and $t > 0$ small enough that $x+stv \in K$ for all $s \in [0, 1]$, 
\begin{align*}
&\bigl| \blangle t^{-1} (\cO(\eta+tV)-\cO(\eta)) - d\cO(\eta;V),(X,f)\brangle \bigr| \\ &\leq \lVert \eta_x\rVert_{\mathrm{op}} \lVert t^{-1}(X_{x+tv}-X_x) - dX(x;v)\rVert + |S(X_{x+tv}-X_x)|  \\ & \quad + \lVert t^{-1}(f(x+tv)-f(x))-df(x;v)\rVert
\\
&\leq \lVert \eta_x\rVert_{\mathrm{op}} \int_0^1 \lVert dX(x+stv;v)-dX(x;v) \rVert \, ds + \lVert S\rVert_{\mathrm{op}}\lVert X_{x+tv}-X_x\rVert  \\
& \quad + \int_0^1\lVert df(x+stv;v)-df(x;v)\rVert \, ds \\
&\leq t\lVert v\rVert \bigl(\lVert \eta_x\rVert_{\mathrm{op}} C(1,K)+\lVert S\rVert_{\mathrm{op}}C(0,K) + C(1, K)\bigr)\rightarrow 0 \quad \text{ as } t\rightarrow 0,
\end{align*}
uniformly in $(X, f) \in B$. Here, we used the mean value theorem in integral form (see e.g.\ \cite[Proposition 1.18]{Sch23}) for the second inequality, and $C(0, K)$ and $C(1,K)$ are as in \Cref{lem:Arz_Asc}. This shows that $\cO$ is differentiable as a map to  $\gM^\ast$ with the strong topology. As in Step 1, continuity of $d\cO$ in the strong topology follows from the estimate
\begin{align*}
    &\bigl|\blangle d\cO(\eta;V)-d\cO(\eta^k;V^k), (X,f) \brangle\bigr| 
    \\ &\leq | (\eta - \eta^k)(dX(x;v)) | + |\eta^k(dX(x; v - v^k))| + |\eta^k(dX(x;v^k) - dX(x_k;v^k))| \\ & \quad + \, |(S-S^k)(X_x)| + |S^k(X_x - X_{x_k})| \\ & \quad + \, |df(x;v-v^k)| + |df(x, v^k) - df(x_k, v^k)|
    \\&\leq \lVert \eta - \eta^k\rVert \lVert dX(x;v)\rVert + \|\eta^k \| \|dX(x,\cdot) \| \| v - v^k \| + \| \eta^k \|  \|v^k \| \| x - x_k \| C(1, K) 
    \\ & \quad + \, \|S - S^k\| \|X_x\| + \|S^k\| \|x-x_k \| C(0, K) \\ & \quad + \, \| df(x;\cdot)\|\|v - v^k\| + \|v^k\| \|x - x_k \| C(1, K)
\end{align*}
(obtained using \eqref{deriv_proxy} and omitting the subscripts on the operator norms and the $\eta$'s), which tends to $0$ uniformly in $(X, f) \in B$ as $k \to \infty$.
Now we are left to prove that $\cO$ is an immersion. Varying $(X,f)$ in \eqref{deriv_proxy}, clearly $d\cO(\eta; \cdot)$ is injective. Since $T^\ast M$ is finite-dimensional, \cite[Theorem H]{glo15} implies that $\cO$ is a $C^1$-immersion.

\medskip
\noindent \textbf{Step 4: $\cO$ is smooth.} We start again with a computation in the weak$^\ast$-topology and argue inductively for $N>1$. 
Taking iterated directional derivatives with respect to the $\eta$-variable, for $V_i = (v_i,S_i) \in \R^d \times (\R^m)^\ast$, we obtain 
\begin{align}
d^N\cO (\eta; V_1,\ldots, V_N)(X,f)\label{higher_deriv} &= \eta_x \left(d^N X(x; v_1,\ldots, v_N)\right) +d^Nf(x; v_1,\ldots,v_N) \notag \\ & \quad + \sum_{i=1}^N S_i \left(d^{N-1}X(x; v_{1}, \ldots, \widehat{v_{k}}, \ldots, v_{N})\right)
\end{align}
where, as usual, $\hat{v}$ indicates the omission of the argument. We conclude that the higher derivatives of $\cO$ as a map into $\gM^\ast$ with the weak$^\ast$-topology exist. %and thus $\cO$ is smooth as a mapping to this space.
Now arguments as in Step 1 and 3, using the higher order estimates from the Arzela-Ascoli theorem (\Cref{lem:Arz_Asc}), applied to \eqref{higher_deriv}, show that $\cO$ is a $C^N$-map into $\gM^\ast$ with the strong topology. We omit the details; the estimates follow exactly the same strategy.
\end{proof}


\section{Additional Proofs}
\label{app:proofs}
In this appendix, we prove various well-known results (used throughout the text) for which we could not find proofs in the literature. 

\subsection{The Derived Action $d\alpha^0$}
\label{app:moment_map}

In this section, we calculate an explicit expression for the derived action $d\alpha^0 \colon \gM \to \Gamma(T^*M)$, where $\Gamma(T^*M)$ denotes the Lie algebra of smooth vector fields on $T^*M$. The action $\alpha^0 \colon \GM \times T^\ast M \rightarrow T^\ast M$ was described in \eqref{eq:alpha_0}. We then obtain \Cref{prop:moment_map} and \Cref{eq:symp_form_in_proof_of_diffeo} as corollaries.

Let $q \colon U \to \Rd$ be coordinates on $M$ and consider the associated cotangent coordinates $(q, p) \colon T^*U \to \R^{2d}$ (\Cref{setup:notation}). These are coordinates on $T^*M$, so we may in turn consider the associated tangent coordinates on $T(T^*M)$. We will only need these coordinates restricted to the tangent space $T_{\eta_x}(T^*M)$, where $\eta_x \in T_x^*M$ is fixed (and $x \in U$). These are given by
\begin{align}\label{eq:coordinates_tangent}
    T_{\eta_x}(T^*M) \ni \sum_{j=1}^d v^j \frac{\partial}{\partial q^j}\Big|_{\eta_x} + \sum_{j=1}^d w_j \frac{\partial}{\partial p_j}\Big|_{\eta_x} \mapsto (v^j, w_j)_{j=1}^d.
\end{align}

\begin{prop}
    \label{prop:derived_rep_app_B}
    Let $(X, f) \in \gM$ and $\eta_x \in T_x^*M$, with $X = \sum_{j=1}^d X^j \frac{\partial}{\partial q^j}$ and $\eta_x = \sum_{j=1}^d \eta_j dq^j_x$. Then, in the coordinates \eqref{eq:coordinates_tangent}, the following identity holds:
    \begin{align*}
        d\alpha^0_{(X, f)}(\eta_x) = \biggl( X^k(x), \sum_{j=1}^d - \eta_j \frac{\partial X^j}{\partial q^k}(x) - \frac{\partial f}{\partial q^k}(x)  \biggr)_{k=1}^d.
    \end{align*}
\end{prop}

\begin{proof}
Since pullbacks commute with the exterior derivative, 
\begin{align*}
    \alpha^0_{(X, f)}(\eta_x) &= (\phi^{-1})^*\eta_x - df_{\phi(x)}
    = \sum_{j=1}^d \biggl( \eta_j d(q^j \circ \phi^{-1})_{\phi(x)} - \frac{\partial f}{\partial q^j} \bigl(\phi(x)\bigr) dq^j_{\phi(x)} \biggr)
    \\ &= \sum_{j=1}^d \biggl( \sum_{k=1}^d \eta_j \frac{\partial (q^j \circ \phi^{-1})}{\partial q^k} - \frac{\partial f}{\partial q^k} \biggr) \bigl(\phi(x)\bigr) dq^k_{\phi(x)}.
\end{align*}
Using the curve $t \mapsto (\Fl^X_t, tf) \in \GM$ to compute the derived action, we find that $d\alpha^0_{(X, f)}(\eta_x)$ has coordinates
\begin{align}
    \label{eq:proof_app_B}
    \ddt \Big|_{t=0} \biggl( q^k, \sum_{j=1}^d \eta_j \frac{\partial (q^j \circ \Fl^{-X}_t)}{\partial q^k} - t \frac{\partial f}{\partial q^k}  \biggr)_{k=1}^d \bigl( \Fl^X_t(x) \bigr).
\end{align}
Clearly, $\ddt \big|_{t=0} q^k(\Fl^X_t(x)) = X_x(q^k)= X^k(x)$ and $\ddt\big|_{t=0} t \frac{\partial f}{\partial q^k} \bigl( \Fl^X_t(x) \bigr) = \frac{\partial f}{\partial q^k}(x)$. As for the remaining terms, we note that $q^j \circ \Fl^{-X}_t$ is a smooth function 
\begin{align*}
    F \colon \R \times M \to M, \quad (t, y) \mapsto \bigl(q^j \circ \Fl^{-X}_t \bigr)(y),
\end{align*}
and hence, $\ddt \big|_{t=0} \frac{\partial (q^j \circ \Fl^{-X}_t)}{\partial q_k} ( \Fl^X_t(x) )$ becomes
\begin{align*}
    \ddt \Big|_{t=0} \frac{\partial F}{\partial q^k} \bigl(t, \Fl^X_t(x) \bigr) = \frac{\partial^2 F}{\partial t \partial q^k}(0, x) + \sum_{l=1}^d X^l(x) \frac{\partial^2 F}{\partial q^l \partial q^k}(0, x).
\end{align*}
But $F(0, y) = q^j(y)$, so that $\frac{\partial^2 F}{\partial q^l \partial q^k}(0, x) = \frac{\partial (\delta^j_k)}{\partial q^l} = 0$, and
\begin{align*}
    \frac{\partial F}{\partial t}(0, y) = \frac{d}{dt}\Big|_{t=0} q^j(\Fl^{-X}_t(y)) = (-X)_y(q^j) = - X^j(y).
\end{align*}
Inserting everything back into \eqref{eq:proof_app_B} yields the desired result.
\end{proof}

\begin{corollary}
    \label{cor:app_comoment_map}
    The map
    \begin{align*}
        H \colon \gM &\to C^\infty(T^*M) \\
        (X, f) &\mapsto H_{(X, f)} \colon \eta_x \mapsto \eta_x(X_x) + f(x)
    \end{align*}
    is a comoment map for $\alpha^0$, i.e.\ $dH_{(X, f)}(\cdot) = \omega'( d\alpha^0_{(X, f)}, \cdot )$ for all $(X, f) \in \gM$, where $\omega'$ denotes the symplectic form on $T^*M$.
\end{corollary}
\begin{proof}
    In cotangent coordinates $(q, p) \colon T^*U \to \R^{2d}$, the symplectic form on $T^*M$ is given by $\sum_{k=1}^d dq^k \wedge dp_k$. Using the identity for $d\alpha^0_{(X, f)}$ from \Cref{prop:derived_rep_app_B}, 
    \begin{align*}
        \omega'_{\eta_x} \bigl( d\alpha^0_{(X, f)}(\eta_x), \cdot \bigr) = \sum_{k=1}^d X^k(x) dp_k +  \sum_{k=1}^d \biggl( \sum_{j=1}^d \eta_j \frac{\partial X^j}{\partial q^k}(x) + \frac{\partial f}{\partial q^k}(x) \biggr) dq^k.
    \end{align*}
    On the other hand, in coordinates, $H_{(X, f)}(q, p) = \sum_{j=1}^d p_j X^j(q) + f(q)$. Calculating $(dH_{(X, f)})_{\eta_x}$, we find that it equals the expression computed above.
\end{proof}

\begin{corollary}
    Equation \eqref{eq:symp_form_in_proof_of_diffeo} holds. That is,
    \begin{align*}
        \omega'_{\eta_x} \bigl( d\alpha^0_{(X, f)}(\eta_x), d\alpha^0_{(Y, g)}(\eta_x) \bigr) = -\eta_x \bigl( [X, Y]_x \bigr) - (Xg - Yf)(x)
    \end{align*}
    for all $x \in M$, $\eta_x \in T_x^*M$ and $(X, f), (Y, g) \in \gM$.
\end{corollary}
\begin{proof}
    Using the expression for $\omega'_{\eta_x}( d\alpha^0_{(X, f)}(\eta_x), \cdot )$ from the proof of the previous corollary, we find that $\omega'_{\eta_x} ( d\alpha^0_{(X, f)}(\eta_x), d\alpha^0_{(Y, g)}(\eta_x) )$ equals
    \begin{align*}
        &\sum_{k=1}^d X^k(x) \biggl(-\sum_{j=1}^n \eta_j \frac{\partial Y^j}{\partial q^k}(x) - \frac{\partial g}{\partial q^k}(x) \biggr) + \sum_{k=1}^d \biggl( \sum_{j=1}^d \eta_j \frac{\partial X^j}{\partial q^k}(x) + \frac{\partial f}{\partial q^k}(x) \biggr) Y^k(x) \\
        &\quad = \sum_{j=1}^d \eta_j \bigl( -X_x(Y^j) + Y_x(X^j) \bigr) + \bigl( - X_x(g) + Y_x(f) \bigr),
    \end{align*}
    which confirms Equation \eqref{eq:symp_form_in_proof_of_diffeo}.
\end{proof}

\subsection{Proof of \Cref{lem:Radon_Nikodym_formula}}\label{app_Radon_Nikodym}

In this section, we prove a slight generalization of \Cref{lem:Radon_Nikodym_formula}

\begin{prop*}
Let $M$ and $N$ be ($\sigma$-compact) Riemannian manifolds with metrics $g_M$ and $g_N$, respectively. Let $\phi \colon M \to N$ be a diffeomorphism and $q \colon U \to \Rd$ be coordinates on $M$. Then,
\begin{align*}
        \frac{d (\phi^* V_{g_N})}{dV_{g_M}}(x) = \Biggl| \frac{\det g_N\bigl(T\phi  \frac{\partial}{\partial q^i}\big|_x, T\phi \frac{\partial}{\partial q^j}\big|_x \bigr)}{\det g_M \bigl(\frac{\partial}{\partial q^i}\big|_x, \frac{\partial}{\partial q^j}\big|_x \bigr)} \Biggr|^{\frac12}
\end{align*}
for all $x \in U$. In particular, this is a smooth function on $M$.
\end{prop*}

\begin{proof}
    Let $\psi \in C_c^\infty(M)$. The change of variables formula gives
    \begin{align*}
        \int_U \psi\, d(\phi^* V_{g_N}) = \int_{\phi(U)} \psi \circ \phi^{-1} \, dV_{g_N}.
    \end{align*}
    Using $q \circ \phi^{-1}$ as coordinates on $\phi(U)$, the right hand side becomes 
    \begin{align}
        \label{eq:Radon_Nikodym_proof}
        \int_{q(U)} (\psi \circ q^{-1})(r) \biggl| \det g_N \biggl( \frac{\partial}{\partial(q \circ \phi^{-1})^i}\Big|_{\phi \circ q^{-1}(r)}, \frac{\partial}{\partial(q \circ \phi^{-1})^j}\Big|_{\phi \circ q^{-1}(r)} \biggr) \biggr|^{\frac12} \,d^dr.
    \end{align}
    Unwinding the definitions, we see that 
    \begin{align*}
        \frac{\partial}{\partial(q \circ \phi^{-1})^i}\Big|_{\phi \circ q^{-1}(r)}  = T \phi \Bigl( \frac{\partial}{\partial q^i} \Big|_{q^{-1}(r)} \Bigr).
    \end{align*}
    Denoting the expression for the Radon-Nikodym derivative by $\mathcal R \colon M \to (0, \infty)$ and expressing $\int_U \psi \mathcal R \, d V_{g_M}$ using $q$-coordinates, one obtains \eqref{eq:Radon_Nikodym_proof}. This implies that $\int_U \psi \, d(\phi^* V_{g_N}) = \int_U \psi \mathcal R \, dV_{g_M}$ for all $\psi \in C_c^\infty(M)$.
\end{proof}

\subsection{Proof of \Cref{prop:derived_rep}}\label{app_derived_rep}
\textbf{Statement of \Cref{prop:derived_rep}} \emph{For $(X, f) \in \gM$ and $\psi \in C_c^\infty(M)$,}
    \begin{align*}
        d\rho^h_{(X, f)}\psi  = -\frac{2\pi i }{h}  f \cdot \psi  - \biggl(X\psi + \frac12 (\divv X) \cdot \psi \biggr) = -\frac{2\pi  i}{h} \mathcal Q^h H_{(X,f)}.
    \end{align*}

\begin{proof}
    Fix $x \in M$ and $\psi \in C_c^\infty(M)$ and let $q \colon U \to \Rd$ be normal coordinates at $x$, \cite[III.8]{KaN63}. Using \eqref{eq:exp_map}, the second component of the Lie group exponential differentiates as follows:
    \begin{align*}
        \ddt \Big|_{t=0} t\int_0^1 f \circ \Fl^{tX}_{-s} \, ds = \int_0^1 f \circ \id_M \,ds + 0 = f.
    \end{align*}
    Writing $g(t)$ for the matrix $g\bigl( T_x \Fl_t^{-X} \tfrac{\partial}{\partial q^i}|_x, T_x \Fl_t^{-X} \tfrac{\partial}{\partial q^j}|_x \bigr)$, \Cref{app_Radon_Nikodym} and the definition of $\rho^h$ \eqref{eq:def_of_rho} now imply that
    \begin{align*}
        \ddt \Big|_{t=0} \Bigl( \rho^h_{\exp(tX, tf)} \psi(x) \Bigr) &= -\frac{2\pi i}{h} f (x) \psi(x) - X_x \psi  + \psi(x)\ddt\Big|_{t=0} \biggl| \frac{\det g(t)}{\det g(0)} \biggr|^{\frac14} \\
        &= -\frac{2\pi i}{h} f (x) \psi(x) - X_x \psi  + \frac14\psi(x)\ddt\Big|_{t=0} \det g(t),
    \end{align*}
    where we have also used that $g(0)$ is the identity, by our choice of normal coordinates. Jacobi's formula gives
    \begin{align*}
        \ddt\Big|_{t=0} \det g(t) = \det g(0)  \cdot \mathrm{tr}\biggl( g^{-1}(0) \frac{dg}{dt}(0) \biggr) = \mathrm{tr}\biggl(\frac{dg}{dt}(0)\biggr).
    \end{align*}
    As the partial derivatives of the metric vanish at $x$, \cite[III. Proposition 8.4]{KaN63},
    \begin{align*}
        \frac{dg}{dt}(0) = g \biggl( \ddt\Big|_{t=0} T_x \Fl_t^{-X} \tfrac{\partial}{\partial q^i}|_x, \tfrac{\partial}{\partial q^j}|_x  \biggr) + g \biggl(  \tfrac{\partial}{\partial q^i}|_x,  \ddt\Big|_{t=0} T_x \Fl_t^{-X} \tfrac{\partial}{\partial q^j}|_x  \biggr).
    \end{align*}
    Using again that the metric at $x$ is the identity, the first term becomes
    \begin{align*}
        \ddt\Big|_{t=0} \bigl( T_x \Fl_t^{-X} \tfrac{\partial}{\partial q^i}|_x \bigr)(q^j) = \ddt\Big|_{t=0} \frac{\partial}{\partial q^i}\Big|_x \bigl(q^j \circ \Fl_t^{-X} \bigr) = - \frac{\partial}{\partial q^i}\Big|_x X(q^j),
    \end{align*}
    and the second term is the same with $i$ and $j$ swapped. Consequently, 
    \begin{align*}
        \ddt\Big|_{t=0} \det g(t) = \mathrm{tr}\biggl(\frac{dg}{dt}(0)\biggr) &= -2 \sum_{j=1}^d \frac{\partial}{\partial q^j}\Big|_x X(q^j)  = -2 \, (\divv X)(x), \\ \text{hence} \quad
        \ddt \Big|_{t=0} \Bigl( \rho^h_{\exp(tX, tf)} \psi(x) \Bigr) &= -\frac{2\pi i}{h} f (x) \psi(x) - X_x \psi - \frac 12\, (\divv X)(x) \psi(x).
    \end{align*}
    This proves pointwise convergence to the desired limit. Since $\rho^h_{\exp(tX, tf)} \psi$ is supported in the compact set $\supp(X) \cap \supp(\psi)$ and bounded there (independently of $t$) for sufficiently small $t$, the dominated convergence theorem \cite[Theorem 22.29]{Sch97} gives $L^2$-convergence. Strong continuity of $t \mapsto \rho^h_{\exp(tX, tf)}$ also follows straightforwardly from compactness of $X$ and the dominated convergence theorem, whence Stone's theorem \cite[Theorem~10.15]{Hall13} gives the result. 
\end{proof}

\subsection{A Haar System on the Tangent Groupoid}
\label{subsec:app_tangent_groupoid}

In this section, we prove that \eqref{eq:Haar_system} defines a Haar system on $\TGM$. Recalling the notation from Examples \ref{ex:pair_groupoid} and \ref{ex:tangent_bundle}, we have:

\begin{prop*}
    A Haar system on $\TGM$ is given by setting $\mu^{(0, x)} = \lambda_x$ and $\mu^{(h, x)} = h^{-d}\vol$.
\end{prop*}
\begin{proof}
    The only condition that requires some work is smoothness of the function
    \begin{align}
        \label{eq:Haar_system_1}
        (0, x) &\mapsto \int_{T_xM} f(0, v_x) \,d\lambda_x(v_x) \quad \text{and} \quad (h, x) \mapsto \int_M f(h, x, y) \,h^{-d} d\vol(y)
    \end{align}
    for $f \in C_c^\infty(\TGM)$ in the limit $h \to 0$. Using a partition of unity, we may assume that $f$ is supported in $U_{\beta} \coloneqq \beta(V_{\beta})$ and furthermore that $f \circ  \beta$ is supported in $[0, 1] \times TU$, where $q \colon U \to \Rd$ are coordinates on $M$. With respect to the associated tangent coordinates $(q, v) \colon TU \to \R^{2d}$, we have, for $h > 0$,
    \begin{align*}
        (\id_{[0, 1]}, q, v) \circ (\beta)^{-1} (h, x, y) = \Bigl(h, q(x), -\frac1h T_xq \bigl(\exp_x^{-1}(y)\bigr) \Bigr).
    \end{align*}
    Introducing the $(h, x)$-dependent coordinates
    \begin{align*}
         y \mapsto v_{(h, x)}(y) \coloneqq -\frac1h T_xq \bigl(\exp_x^{-1}(y) \bigr),
    \end{align*}
    we can rewrite the $h > 0$ part of \eqref{eq:Haar_system_1} as
   \begin{align}
        \label{eq:Haar_system_2}
        (h, x) &\mapsto \int_{\Rd} f \bigl(h, x, v_{(h, x)}^{-1}(r) \bigr) \,h^{-d} \sqrt{\bigl|\det g_{(h, x)}\bigl(v_{(h, x)}^{-1}(r) \bigr) \bigr|} \, d^dr,
    \end{align}
    where $g_{(h, x)}$ is the matrix representation of the metric in the $v_{(h, x)}$-coordinate frame. Now, $g_{(h, x)} = h^2 g_{(1, x)}$, and $v^{-1}_{(h, x)}(r) = \exp_x \circ \,(T_xq)^{-1}(-h r)$, so that
    \begin{align}
        \label{eq:Haar_system_3}
        h^{-d} \sqrt{\bigl|\det g_{(h, x)}\bigl(v_{(h, x)}^{-1}(r) \bigr) \bigr|} = \sqrt{\bigl|\det g_{(1, x)}\bigl( \exp_x \circ \,(T_xq)^{-1}(-h r) \bigr) \bigr|},
    \end{align}
    which is smooth on its domain of definition in $[0, 1] \times U \times \R^d$. Moreover, since
    \begin{align*}
        T_x(v_{(1, x)}^{-1} \circ q) = -T_{0_x} \exp_x \circ \, (T_xq)^{-1} \circ T_x q = -\id_{T_xM},
    \end{align*}
    we find that $g_{(1, x)}(x) = g_q(x)$. Thus, \eqref{eq:Haar_system_3} extends smoothly to $h = 0$, where it takes the value $\sqrt{|\det g_q(x)|}$. Finally, $f \circ \beta$ is smooth on $V_{\beta}\subset [0,1 ] \times TM$, and $(\id_{[0, 1]}, q, v) \circ\beta^{-1}(0, v_x) = ( 0, q(x), T_xq(v_x))$, so \eqref{eq:Haar_system_2} extends smoothly via
    \begin{align*}
        (0, x) &\mapsto \int_{\Rd} f \bigl(0, (T_xq)^{-1}(r)\bigr) \sqrt{|\det g_q(x)|} \, d^dr = \int_{T_xM} f(0, v_x) \,d\lambda_x(v_x). \qedhere
    \end{align*}
\end{proof}

