{} $\true \backslash \{I\} \cap G(0) = G(0)$.

\begin{eqnarray*}
\lefteqn{C \vrad(G(0))}
\\
&=& [
	C(\imin(G(0))) \cap G(0), \ldots, C(\imax(G(0))) \cap G(0),
	\true \backslash G(0)
]
\\
&=& [
	C(1) \cap G(0), \ldots, C(1) \cap G(0),
	\true \backslash G(0)
]
\\
&=& [
	C(1) \cap G(0),
	\true \backslash G(0)
]
\\
&=& [
	\true \backslash \{I\} \cap G(0), 
	\true \backslash G(0)
]
\\
&=& [
	G(0),
	\true \backslash G(0)
]
\end{eqnarray*}

