\subsection{Proofs of Results from Section \ref{subsec:causal-framework}} \label{app:proofs-causal-framework}
%
%

%
The following proposition relates the observed difference of mean outcomes across sub-treatment vectors with adjacent levels of the aggregated treatment to causal quantities. 
\begin{proposition} \label{prop:comparison-of-subtreatments} 
Under Assumption \ref{ass:sutva2}, the difference in mean outcomes between sub-treatment vectors at adjacent levels of the aggregated treatment can be decomposed as
\begin{align*}
    \E[Y|S=s_d] - \E[Y|S=s_{d-1}] &= \mathrm{MATT}(s_d,s_{d-1}) + B(s_d, s_{d-1})
\end{align*}
where
\begin{align*}
    B(s_d,s_{d-1}) &:= \E[Y(s_{d-1})|S=s_d ] - \E[Y(s_{d-1})|S=s_{d-1}] 
\end{align*}
%
%
%
%
which is a selection bias term.  If, in addition, Assumption \ref{ass:unconfoundedness} (or Assumption \ref{ass:local-unconfoundedness}) holds, then $B(s_d,s_{d-1}) = 0$, so that 
\begin{align*}
    \mathrm{MATT}(s_d,s_{d-1}) = \E[Y|S = s_d] - \E[Y|S=s_{d-1}]
\end{align*}
\end{proposition}

The first part of Proposition \ref{prop:comparison-of-subtreatments} shows that the comparison of means between sub-treatment vectors with adjacent levels of the aggregated treatment can be decomposed into a marginal average treatment effect on the treated term and a selection bias term. The second part shows that, under Assumption \ref{ass:unconfoundedness}, the same comparison of means is equal to $\textrm{MATT}(s_d,s_{d-1})$. 
The result in Proposition \ref{prop:comparison-of-subtreatments} holds irrespective of whether $s_d$ and $s_{d-1}$ are congruent sub-treatments. 
%

\begin{proof}[\textbf{Proof of Proposition \ref{prop:comparison-of-subtreatments}}]
    To show the first part, notice that
    \begin{align*}
        \E[Y|S=s_d] - \E[Y|S=s_{d-1}] &= \E[Y(s_d) - Y(s_{d-1}) | S=s_d ] \\ 
        & \hspace{25pt} + \Big( \E[Y(s_{d-1})|S=s_d ] - \E[Y(s_{d-1})|S=s_{d-1}] \Big) \\
        &= \mathrm{MATT}(s_d, s_{d-1}) + B(s_d, s_{d-1})
    \end{align*}
    where the first equality holds by writing observed outcomes in terms of their corresponding potential outcomes, and then by adding and subtracting $\E[Y(s_{d-1}) | S=s_d ]$; and the second equality holds by the definitions of $\textrm{MATT}(s_d,s_{d-1})$ and $B(s_d, s_{d-1})$.

    For the second part, notice that
    \begin{align*}
        \mathrm{MATT}(s_d, s_{d-1}) &= \E[Y(s_d) | S=s_d] - \E[Y(s_{d-1}) | S=s_d] \\
        &= \E[Y(s_d) | S=s_d, D=d~\textrm{or}~D=d-1] \\
        &\hspace{50pt} - \E[Y(s_{d-1}) | S=s_d, D=d~\textrm{or}~D=d-1] \\
        &= \E[Y(s_d) | S=s_d, D=d~\textrm{or}~D=d-1] \\
        &\hspace{50pt} - \E[Y(s_{d-1}) | S=s_{d-1}, D=d~\textrm{or}~D=d-1] \\
        &= \E[Y(s_d) | S=s_d] - \E[Y(s_{d-1}) | S=s_{d-1}] \\
        &= \E[Y|S=s_d] - \E[Y|S=s_{d-1}]
    \end{align*}
    where the first equality hold by the definition of $\textrm{MATT}(s_d,s_{d-1})$; the second equality holds because $D$ is fully determined by $S$ (and $S$ being equal to $s_d$ or $s_{d-1}$ implies that $D$ is either equal to $d$ or $d-1$); the third equality holds by Assumption \ref{ass:unconfoundedness} (or Assumption \ref{ass:local-unconfoundedness}); the fourth equality holds again because $S$ fully determines $D$; and the last equality holds by writing potential outcomes in terms of their observed counterparts.
\end{proof}
%

\bigskip

%
\begin{proposition} \label{prop:comparison-of-neighborly-subtreatments} 
Under Assumption \ref{ass:sutva2}, the difference in mean outcomes between sub-treatment vectors at identical levels of the aggregated treatment can be decomposed as
\begin{align*}
    \E[Y|S=s_d] - \E[Y|S=s_{d}'] &= \mathrm{SATT}(s_d,s_{d}') + SB(s_d, s_{d}')
\end{align*}
where
\begin{align*} 
    SB(s_d,s_{d}') &:= \E[Y(s_d')|S=s_d] - \E[Y(s_d')|S=s_d'] 
\end{align*}
which is a selection bias term.  If, in addition, Assumption \ref{ass:unconfoundedness} (or Assumption \ref{ass:local-unconfoundedness}) holds, then $SB(s_d,s_{d}') = 0$, so that $\mathrm{SATT}$ is identified and is given by
\begin{align*}
    \mathrm{SATT}(s_d,s_{d'}) = \E[Y|S = s_d] - \E[Y|S=s_{d}']
\end{align*}
\end{proposition}
\noindent The proof is provided in the Supplementary Appendix.
