\begin{proposition} \label{prop:marginal-decomposition} For any weighting function $w(s_d,s_{d-1})$ such that
\begin{itemize}
    \item [(i)] $\sum_{s_d \in \mathcal{S}_d} w(s_d,s_{d-1}) = \P(S=s_{d-1}|D=d-1)$
    \item [(ii)] $\sum_{s_{d-1} \in \mathcal{S}_{d-1}} w(s_d,s_{d-1}) = \P(S=s_d|D=d)$
\end{itemize}
\begin{align*}
    \E[Y|D=d] - \E[Y|D=d-1] &= \sum_{(s_{d-1}, s_{d}) \in \mathcal{M}^+(d) } w(s_d,s_{d-1}) \cdot \Big( \E[Y|S=s_d] - \E[Y|S=s_{d-1}]\Big) \\
    &+\sum_{(s_{d-1}, s_{d}) \in \mathcal{M}^-(d) } w(s_d,s_{d-1}) \cdot \Big( \E[Y|S=s_d] - \E[Y|S=s_{d-1}]\Big)
\end{align*}
\end{proposition}

\begin{proof}[\textbf{Proof of Proposition \ref{prop:marginal-decomposition}}] 
Notice that, for any weighting function $w(s_d,s_{d-1})$ that satisfies properties (i) and (ii), 
\begin{align*} 
    &\E[Y|D=d] - \E[Y|D=d-1] \\
    &\hspace{50pt} = \sum_{s_d \in \ST_d} \P(S=s_d|D=d) \cdot \E[Y|S=s_d] - \sum_{s_{d-1} \in \ST_{d-1}} \P(S=s_{d-1}|D=d-1) \cdot \E[Y|S=s_{d-1}] \\
    &\hspace{50pt} = \sum_{s_d \in \ST_d} \sum_{s_{d-1} \in \ST_{d-1}} w(s_d,s_{d-1}) \cdot \E[Y|S=s_d] - \sum_{s_{d-1} \in \mathcal{S}_{d-1}} \sum_{s_d \in \ST_d} w(s_d, s_{d-1}) \cdot \E[Y|S=s_{d-1}] \\
    &\hspace{50pt} = \sum_{s_d \in \ST_d} \sum_{s_{d-1} \in \ST_{d-1}} w(s_d,s_{d-1}) \cdot \Big(\E[Y|S=s_d]-\E[Y|S=s_{d-1}]\Big) \\
    & \hspace{50pt} = \sum_{(s_{d-1}, s_{d}) \in \mathcal{M}^+(d) } w(s_d,s_{d-1}) \cdot \Big( \E[Y|S=s_d] - \E[Y|S=s_{d-1}]\Big) \\
    & \hspace{75pt} +\sum_{(s_{d-1}, s_{d}) \in \mathcal{M}^-(d) } w(s_d,s_{d-1}) \cdot \Big( \E[Y|S=s_d] - \E[Y|S=s_{d-1}]\Big)
\end{align*}
where the first equality holds by applying the law of iterated expectations to each term (and because the aggregated treatment is fully determined by the sub-treatment); the second equality holds from properties (i) and (ii) of the weights, and because the first term does not depend on $s_{d-1}$ and the second term does not depend on $s_d$; the third equality holds by re-arranging the summations and combining terms; and the last equality holds by separating the summation in the previous line among congruent and incongruent comparisons across sub-treatment vectors.
\end{proof}
