\begin{lemma}[Congruent Sub-treatment Existence] \label{lem:congruent-st-existence}
    For every $s_{d-1} \in \ST_{d-1}$ such that $d>0$, there always exists a vector $s_d \in \ST_d$ such that $s_d \cst s_{d-1}$. That is, for non-empty $\ST_{d-1}$ there will exist an $s_d \in \ST_d$ that is congruent with $s_{d-1}$.  
\end{lemma}

\noindent The proof is provided in the Supplementary Appendix.

%

\bigskip

%
\begin{lemma}[Unit Exchange Property] \label{lem:unit-exchange}
    Let $s_d \in S_d \subset S$, which satisfies the $\ell_1$ norm $||s_d||_1=d$ and $S \subseteq \mathbb{Z}^{K}_{\geq 0}$, which is the vector space of non-negative integers with dimension $K$. If $K \geq 2$ and $d>0$, then there exists $s_d' \in S_d$ with coordinates $j$ and $l$ where $j \neq l$ such that 
    \[
    s_d = s_d' + 1_j - 1_l,
    \]
    where $1_j$ and $1_l$ are the unit vectors for coordinates (sub-treatments) $j$ and $l$. 
\end{lemma}

\noindent The proof is provided in the Supplementary Appendix. 
%

\bigskip

%
\begin{lemma}[Productive Chain Progression] \label{lem:productive-progression}    
    Take any $s_{d},s_{d}' \in \ST_{d}$ with $d>0$ such that $||s_{d} - s_{d}'||_1 > 2$,  where at least for some $j^{th}$ and $l^{th}$ coordinates $s_{d,j} < s_{d,j}'$ and $s_{d,l} > s_{d,l}'$. There exists a vector $s_{d}^{\star} \in S_{d}$ such that $s_{d}^{\star} = s_{d} + 1_{j} - 1_{l}$ for some coordinates $j$ and $l$, and $||s_{d} - s_{d}'||_1 > ||s_{d}^{\star} - s_{d}'||_1 \geq 2$. That is, there always exists a vector $s_{d}^{\star}$ which is a unit-exchange towards the terminating vector $s_{d}'$ which strictly decreases in distance $||s_{d}^{\star} - s_{d}'||_1$.
\end{lemma}

\noindent The proof is provided in the Supplementary Appendix. 
%

\bigskip

%
\begin{proposition}[Chain Algorithm] \label{prop:chain-algorithm}
    Let $s_{d}, s_{d}' \in \ST_d \subset \mathbb{Z}_{\geq 0}^{K}$ for $d>0$ and $K \geq 2$. For some $B \in \mathbb{Z}^{+}$, there is a finite sequence of vectors 
    \[
    x^{(0)}=s_d, x^{(1)}, \ldots, x^{(B-1)}, x^{(B)}=s_d'
    \]
    such that each vector in the sequence, indexed by $b$, is a unit exchange 
    \[
    x^{(b+1)} = x^{(b)} + 1_j - 1_l
    \]
    of neighboring vectors which makes strict progress towards $s_d'$, where $1_j$ and $1_l$ are unit vectors for the $j^{th}$ and $l^{th}$ coordinate.
\end{proposition}

\noindent The proof is provided in the Supplementary Appendix. 

%

\bigskip

%
\begin{proof}[\textbf{Proof of Proposition \ref{prop:incongruent-and-substitution-effects}}]
    Given no (local) selection (Assumption \ref{ass:unconfoundedness} or \ref{ass:local-unconfoundedness}), we know by Proposition \ref{prop:comparison-of-subtreatments} that disaggregate comparisons across average outcomes between sub-treatments at adjacent levels of total treatment are $\textrm{MATT}$'s, and by Proposition \ref{prop:comparison-of-neighborly-subtreatments} that disaggregate comparisons across average outcomes between sub-treatments at identical levels of total treatment are $\textrm{SATT}$'s. Under this condition, suppose that $d>0$ and $K\geq2$ so that $S_{d}$ is not empty. Hence, $\mathcal{M}^{+}(d)$ is not empty, but $\mathcal{M}^{-}(d)$ may or may not be empty. If $\mathcal{M}^{-}(d)$ is empty, then the claim holds vacuously. So, we proceed with non-empty $\mathcal{M}^{-}(d)$. 

    Take any pair $(s_d, s_{d-1}) \in \mathcal{M}^{-}(d)$ and, by Lemma \ref{lem:congruent-st-existence}, any congruent $s_{d-1}'$ of $s_d$ in $S_{d-1}$. Denote $m(s) := \E[Y|S=s]$ for any $s \in S$. Then from Proposition \ref{prop:comparison-of-subtreatments} the incongruent $\textrm{MATT}$ can be written as: 
    \begin{align*} 
        \mathrm{MATT}^{-}(s_d,s_{d-1}) &= m(s_d) - m(s_{d-1}) \\
        &= m(s_d) - m(s_{d-1}')  + m(s_{d-1}') - m(s_{d-1})  \\
        &= \mathrm{MATT}^{+}(s_d, s_{d-1}') + \big( m(s_{d-1}') - m(s_{d-1}) \big) 
    \end{align*}
    where the first equality is the definition of $\textrm{MATT}$; the second equality holds by addition and subtraction of $m(s_{d-1}')$; and the third equality holds by the definition of $\textrm{MATT}^{+}$. 

    From here, there are two cases: 
    \begin{enumerate}
        \item $s_{d-1}'$ is a unit exchange of $s_{d-1}$, $s_{d-1}' = s_{d-1} + 1_j - 1_l$, where $1_j$ and $1_l$ are unit vectors for some $j$ and $l$ coordinates;
        \item $s_{d-1}'$ is not a unit exchange of $s_{d-1}$, $s_{d-1}' \neq s_{d-1} + 1_j - 1_l$, for any $j$ and $l$ coordinates.
    \end{enumerate}

    \noindent
    \textit{Case 1:} If $s_{d-1}'$ is a unit exchange of $s_{d-1}$, then by Lemma \ref{lem:unit-exchange}, $s_{d-1}' = s_{d-1} + 1_j - 1_l$. Consequently, $m(s_{d-1}') - m(s_{d-1}) = \textrm{SATT}(s_{d-1}', s_{d-1})$ by the definition of $\textrm{SATT}$. Thus, the claim holds: 
    \begin{align*}
        \mathrm{MATT}^{+}(s_d, s_{d-1}') + m(s_{d-1}') - m(s_{d-1}) &= \mathrm{MATT}^{+}(s_d, s_{d-1}') + \mathrm{SATT}(s_{d-1}', s_{d-1})
    \end{align*}
    by definition of $\textrm{SATT}$ in Proposition \ref{prop:comparison-of-neighborly-subtreatments}, the substitution average treatment effect on the treated. 

    \bigskip
    \noindent
    \textit{Case 2:} Suppose $s_{d-1}'$ is not a unit exchange of $s_{d-1}$. That is, $s_{d-1}' \neq s_{d-1} + 1_j - 1_l$, for any $j$ and $l$ coordinates. 

    Next, our goal is to express the difference $m(s_{d-1}') - m(s_{d-1})$ as unit exchanges between $m(s_{d-1}')$ to $m(s_{d-1})$. To do this, we need a set of vectors, chained by the unit exchange property, that begins at $s_{d-1}'$ and eventually terminates at $s_{d-1}$. We approach this task algorithmically. To build such a chain, we know by Lemma \ref{lem:unit-exchange} that there exists a vector $s_{d-1}^{(1)} \in S_{d-1}$ which is a unit exchange of $s_{d-1}'$ such that $s_{d-1}' = s_{d-1}^{(1)} + 1_{j'} - 1_{l'}$ for some coordinates $j'$ and $l'$.   Next, by Lemma \ref{lem:productive-progression}, there always exists a vector that makes productive progress from $s_{d-1}'$ towards the terminating vector $s_{d-1}$. By Proposition \ref{prop:chain-algorithm}, these conditions guarantee the procedure terminates at $s_{d-1}$ in finitely many steps without any repeating patterns. 

    In the first step of this procedure, we may write: 
    \begin{align*}
        \mathrm{MATT}^{-}(s_d,s_{d-1}) &= \mathrm{MATT}^{+}(s_d, s_{d-1}') + m(s_{d-1}') - m(s_{d-1}) \\ 
        &= \mathrm{MATT}^{+}(s_d, s_{d-1}') + \big( m(s_{d-1}') - m(s_{d-1}^{(1)}) \big) + \big( m(s_{d-1}^{(1)}) - m(s_{d-1}) \big) \\ 
        &= \mathrm{MATT}^{+}(s_d, s_{d-1}') + \mathrm{SATT}(s_{d-1}', s_{d-1}^{(1)}) + \big( m(s_{d-1}^{(1)}) - m(s_{d-1}) \big) 
    \end{align*}
    where the first equality holds from above; the second equality holds by the addition and subtraction of $m(s_{d-1}^{(1)})$; and the third equality holds by the definition of $\textrm{SATT}$ in Proposition \ref{prop:comparison-of-neighborly-subtreatments}. If $s_{d-1}^{(1)}$ is a unit exchange of $s_{d-1}$ also, $s_{d-1}^{(1)} = s_{d-1} + 1_{j''} - 1_{l''}$ for coordinates $j''$ and $l''$, then the original claim holds: 
    \begin{align*}
        \mathrm{MATT}^{-}(s_d,s_{d-1}) &= \mathrm{MATT}^{+}(s_d, s_{d-1}') + \mathrm{SATT}(s_{d-1}',s_{d-1}^{(1)}) + \mathrm{SATT}(s_{d-1}^{(1)},s_{d-1}) 
    \end{align*}
    by the definition of $\textrm{SATT}$ in Proposition \ref{prop:comparison-of-neighborly-subtreatments}.
    Otherwise, we continue this process by iteratively applying the unit exchange property, Lemma \ref{lem:unit-exchange}, that satisfies productive progression towards the terminating vector, Lemma \ref{lem:productive-progression}, at each step $b$ until a chain $\phi := \{ s_{d-1}', s_{d-1}^{(1)}, \ldots, s_{d-1}^{(B-1)}, s_{d-1} \} $ of size $|\phi|=B \in \mathbb{Z}^{+}$ is formed. This implies that we may write the incongruent parameter as a telescoping sum of all $m(s_{d-1}^{(b)})$ in the chain: 
    \begin{align*}
        \mathrm{MATT}^{-}(s_d,s_{d-1}) &= \mathrm{MATT}^{+}(s_d, s_{d-1}') + \sum_{b=0}^{B-1} \mathrm{SATT}(s_{\phi, \; d-1}^{(b)},s_{\phi, \; d-1}^{(b+1)})
    \end{align*}
    where $s_{\phi}^{(b)}$ is linked in the chain $\phi$ to the vector $s_{\phi}^{(b+1)}$ by the unit exchange property in Lemma \ref{lem:unit-exchange}. Hence, the claim holds. Note that Proposition \ref{prop:chain-algorithm} permits a set of possible chains denoted by $\mathcal{C}(s_{d-1}', s_{d-1})$, where $\phi$ is possibly one element of many in this set.%
\end{proof}
%

\bigskip

%
\begin{lemma}[Single Pairwise Congruent Sub-treatment Vector] \label{lem:pairwise-congruent-vectors}
    For any $s_{d-1}, s_{d-1}' \in \ST_{d-1}$ such that $s_{d-1} = s_{d-1}' + 1_j - 1_l$ for some coordinates $j$ and $l$, which is a unit exchange of $s_{d-1}'$, there must exist one $s_{d} \in \ST_{d}$ that is congruent with $s_{d-1}$ and $s_{d-1}'$. %
\end{lemma}

\noindent The proof is provided in the Supplementary Appendix.
%

