\begin{lemma}[Double Binomial Reduction] \label{lem:counting-equality}
    The sum $\sum_{d=1}^{K} \binom{K}{d} \cdot \binom{K}{d-1}$ is equivalent to $\binom{2K}{K-1}$, for all $K \in \mathbb{Z}$.  
\end{lemma}

\noindent The proof is provided in the Supplementary Appendix.
%

\bigskip

%
\begin{proposition}[Number of Congruent and Incongruent Contrasts with Binary Sub-treatments] \label{prop:congruent-incongruent-counts-binary-subtreatments}
    For a given number of binary sub-treatments $K>1$, there are $\sum_{d=1}^K \binom{K}{d} \binom{K}{d-1} = \binom{2K}{K}$ distinct contrasts, and the proportion of incongruent contrasts will increase as $K$ increases - illustrated in Figure \ref{fig:proportion-of-incongruent-subtreatments}. The number of congruent disaggregated contrasts present is $\sum_{d=1}^K K \cdot \binom{K-1}{d-1} = K \cdot 2^{K-1}$, and can be presented as a row-scaled Pascal's (Hui-Khayyam's) Triangle. The number of incongruent disaggregated contrasts present is the difference between total contrasts and congruent contrasts. 
\end{proposition}
%


%
\begin{proof}[\textbf{Proof of Proposition \ref{prop:congruent-incongruent-counts-binary-subtreatments}}]
    Given $K>1$ binary sub-treatments, we show that for all $d \in \D$: (i) the total number of distinct disaggregated contrasts is $\sum_{d=1}^K \binom{K}{d} \binom{K}{d-1} = \binom{2K}{K-1}$; and (ii) the number of congruent disaggregated contrasts is $\sum_{d=1}^K K \cdot \binom{K-1}{d-1}$.

    \begin{enumerate}
        %
        \item \textit{Total distinct contrasts:} 
        First, we show that the number of $K$-tuples that sum to $D=d$ is $\binom{K}{d}$. The size of a tuple is $K$. Since each variable is binary, each element in the $K$-tuple is either zero or one. For each tuple to sum to $D=d$, there must be exactly $d$ ones, and $K-d$ zeros. This amounts to choosing how many ways we can put $d$ ones among $K$ empty positions. Hence, this is a problem of the form ``how to choose $d$ objects from $K$ total objects'', which is known to be determined by the binomial coefficient, $\binom{K}{d}$. This implies, for $K$ binary sub-treatments, that the number of distinct sub-treatment vectors that lie in the aggregate set $\ST_d$ is equal to $\binom{K}{d}$, or $|\ST_d| = \binom{K}{d}$.

        Similarly, if we wanted to know how many $K$-tuples would sum to $D=d-1$, we would write $\binom{K}{d-1}$. Recall that marginal contrasts are made between adjacent aggregate sets, $\ST_d$ and $\ST_{d-1}$. So, for every $d \in \D_{>0}$, there are $|\ST_d| \cdot |\ST_{d-1}| = \binom{K}{d} \cdot \binom{K}{d-1}$ possible comparisons. Hence, the total number of distinct contrasts that can be made is the sum across all $d \in \D$, $\sum_{d=1}^{K} \binom{K}{d} \cdot \binom{K}{d-1}$, as desired. And by Lemma \ref{lem:counting-equality}, this sum $\sum_{d=1}^{K} \binom{K}{d} \cdot \binom{K}{d-1} = \binom{2K}{K-1}$. 

        %
        \item \textit{Congruent distinct contrasts:} 
        Next, we aim to find the number of congruent contrasts out of the total number of contrasts. We demonstrate that the number of congruent contrasts for $K$ binary sub-treatments is $\sum_{d=1}^{K} K \cdot \binom{K-1}{d-1} = K \cdot 2^{K-1}$. 

        Recall that congruent vectors of treatment must satisfy $s' = s + 1_j$, for some $j^{th}$ component. Since the sub-treatments are binary, and thus the elements in each position may not exceed one, this implies that one position must remain fixed while all other positions may vary because all positions for ones must be identical except for one position in the binary case. That is, there are $K-1$ available positions/elements that we are free to vary as long as the tuple sums to $d$. Hence, at each $d$, we are counting the number of ways we can put $d$ ones in $K-1$ positions, $\binom{K-1}{d}$. We can do this for each position in the tuple, which is of length $K$. Therefore, at each $d$, the number of congruent contrasts is $K \cdot \binom{K-1}{d}$. The total number of congruent contrasts can be summed across all $d \in \D$, $\sum_{d=0}^K K \cdot \binom{K-1}{d} = K \cdot \sum_{d=0}^K \binom{K-1}{d}$. 
        Notice that by the binomial theorem, this sum of binomial coefficients can be written as $\sum_{d=0}^K \binom{K-1}{d} = 2^{K-1}$. Hence, the number of congruent contrasts is the product: $K \cdot 2^{K-1}$. \qedhere
    \end{enumerate}
\end{proof}
%

\bigskip

%
\begin{corollary}[Asymptotic Congruity Is Proportionally Zero] \label{cor:asymptotic-congruent-proportion-result}
    As the number of binary sub-treatments increases, the proportion of congruent contrasts in the marginal set approaches zero. That is, 
    \begin{align*}
        \lim_{K \rightarrow \infty} \frac{\big| \mathcal{M}^{+} \big| }{ \big| \mathcal{M} \big|} &= \lim_{K \rightarrow \infty} \frac{\big| \mathcal{M}^{} \big| - \big| \mathcal{M}^{-} \big|}{ \big| \mathcal{M} \big| } = 0 
    \end{align*}
    In other words, as the number of sub-treatments grows, the proportion of incongruity dominates. 
\end{corollary}
%

%
\begin{proof}[\textbf{Proof of Corollary \ref{cor:asymptotic-congruent-proportion-result}}]
    Here we prove that as we let the number of binary sub-treatments grow to infinity, the proportion of congruent contrasts approaches zero. That is, we show that: $\lim_{K \rightarrow \infty} \frac{\big| \mathcal{M}^{+} \big| }{ \big| \mathcal{M} \big|} = 0$.
    If the results in Proposition \ref{prop:congruent-incongruent-counts-binary-subtreatments} holds, the we can write: 
    \begin{align*}
        \lim_{K \rightarrow \infty} \frac{\big| \mathcal{M}^{+} \big| }{ \big| \mathcal{M} \big|} &= \lim_{K \rightarrow \infty} \frac{K \cdot \sum_{d=1}^K \binom{K-1}{d-1}}{\sum_{d=1}^K \binom{K}{d} \binom{K}{d-1}} 
        = \lim_{K \rightarrow \infty} \frac{K \cdot 2^{K-1}}{ \binom{2K}{K-1} } 
    \end{align*}
    which are the results from Proposition \ref{prop:congruent-incongruent-counts-binary-subtreatments}.
    Next, see that the denominator can be rewritten as: 
    \begin{align*}
        \binom{2K}{K-1} &= \frac{(2K)!}{(K-1)! (2K-(K-1))!} = \left( \frac{K}{K+1} \right) \frac{(2K)!}{K! (2K-K)!} = \left( \frac{K}{K+1} \right) \cdot \binom{2K}{K}
    \end{align*}
    This implies that we are trying to find the following limit: 
    \begin{align}
        \lim_{K \rightarrow \infty} & \frac{K \cdot 2^{K-1}}{ \left( \frac{K}{K+1} \right) \cdot \binom{2K}{K} } \label{eq:corA1.limit} 
    \end{align}
    Before taking the limit, notice that we can restate the denominator by Stirling's approximation formula for factorials. First, note that: 
    \begin{align}
    (2K)! &\sim \sqrt{2 \pi (2K)} \cdot \left( \frac{2K}{e} \right)^{2K} 
    = \left( \frac{\sqrt{\pi} \cdot 2^{2K+1} \cdot K^{\frac{4K+1}{2}}}{e^{2K}} \right) \label{eq:corA1.A} 
    \end{align}
    and similarly, 
    \begin{align}
        K! &\sim \sqrt{2 \pi K} \cdot \left( \frac{K}{e} \right)^{K} 
        = \left( \frac{\sqrt{2 \pi} \cdot K^{\frac{2K+1}{2}}}{e^{K}} \right) 
        \label{eq:corA1.B} 
    \end{align}
    where Stirling's formula states, for some $n>0$, that $n! \sim \sqrt{2 \pi n} \cdot \left( \frac{n}{e} \right)^{n}$, and $e$ denotes Euler's constant. Both (\ref{eq:corA1.A}) and (\ref{eq:corA1.B}) imply that the denominator of the limit (\ref{eq:corA1.limit}) can be approximated well by the following expression:
    \begin{align}
        \binom{2K}{K} &= \frac{(2K)!}{K! K!} \sim \frac{ \frac{ \sqrt{\pi} \cdot 2^{2K+1} \cdot K^{(4K+1)/2} }{e^{2K}} }{ \left( \frac{ \sqrt{2 \pi} K^{(2K+1)/2} }{e^K} \right)^2 } = \frac{ \sqrt{\pi} \cdot 2^{2K+1} \cdot K^{(4K+1)/2} }{ 2 \pi \cdot K^{2K+1} } = \pi^{-1/2} \cdot 2^{2K} \cdot K^{-1/2} \label{eq:corA1.C} 
    \end{align}
    Therefore, by (\ref{eq:corA1.C}) above, the limit (\ref{eq:corA1.limit}) becomes: 
    \begin{align*}
        \lim_{K \rightarrow \infty} \frac{K \cdot 2^{K-1}}{ \left( \frac{K}{K+1} \right) \cdot \binom{2K}{K} } &\sim \lim_{K \rightarrow \infty} \frac{ K \cdot 2^{2K-1} }{ \pi^{-1/2} \cdot 2^{2K} \cdot K^{-1/2} } \\
        &= \lim_{K \rightarrow \infty} \sqrt{\pi} \cdot \frac{ K (K+1) }{K^{1/2}} \cdot 2^{(K-1) - 2K} \\ 
        &= \sqrt{\pi} \cdot \lim_{K \rightarrow \infty} \frac{ K^{3/2} + K^{1/2} }{ 2^{K+1} } = 0
    \end{align*}
    where the first line holds by applying Stirling's formula; the second and third lines hold by algebra; and the fourth equality holds since the numerator of the limit grows at the polynomial rate and the denominator grows at the exponential rate. This implies that as the number of binary sub-treatments increases, the proportion of congruent contrasts tends to zero, as claimed. 
\end{proof}
%

\bigskip

%
\begin{proposition}[Number of Congruent and Incongruent Contrasts with Trinary Sub-treatments] \label{prop:congruent-incongruent-counts-trinary-subtreatments}
    For a given number of trinary sub-treatments $K>1$ with common support $\{0,1,2\}$, there are $\sum_{d}^K \binom{K}{d}_2 = \sum_{d=1}^K \sum_{r=0}^{\lfloor d/2 \rfloor} \binom{K}{r} \cdot \binom{K-r}{d-2r}$ distinct contrasts, and the proportion of incongruent contrasts will increase as $K$ increases - illustrated in Figure \ref{fig:sub2}. The number of congruent disaggregated contrasts present is the row-sum of a row-scaled extended trinomial triangle, whose elements are the sum of the top-three adjacent elements. The number of incongruent disaggregated contrasts present is the difference between total contrasts and congruent contrasts.  
\end{proposition}

\noindent The proof is provided in the Supplementary Appendix.
