\begin{proposition}[Homogeneity of Effects] \label{prop:homogeneity-of-effects} 
    Under Assumptions \ref{ass:sutva2}-\ref{ass:homogeniety}, and for any $d \in \D_{>0}$, 
    \begin{align*}
        \E[Y|D=d] - \E[Y|D=d-1] = \beta_d.
    \end{align*} 
\end{proposition}
%

%

%
\begin{proof}[\textbf{Proof of Proposition \ref{prop:homogeneity-of-effects}}]
    Under Assumption \ref{ass:homogeniety}, we have that $\textrm{MATT}^+(s_d, s_{d-1}) = \beta_d$ for all $(s_d, s_{d-1}) \in \mathcal{M}^+(d)$.  Furthermore, by Proposition \ref{prop:substitution-effect-decomp}, for any $(s_d,s_{d-1}) \in \mathcal{M}^{-}(d)$ and any $\phi \in \mathcal{C}(s_d,s_{d-1})$,
    \begin{align*}
        \mathrm{MATT}^{-}(d) &= \mathrm{MATT}^+(s_d,s_{d-1}') + \sum_{ b=0 }^{B-1} \mathrm{MATT}^{+}(s_{\phi, \; d}^{(b)},s_{\phi, \; d-1}^{(b)}) - \sum_{ b=0 }^{B-1} \mathrm{MATT}^{+}(s_{\phi, \; d}^{(b)},s_{\phi, \; d-1}^{(b+1)}) \\ 
        &= \beta_d + |B| \cdot \beta_d - |B| \cdot \beta_d = \beta_d
    \end{align*}
    Hence, all marginal effects are $\beta_d$ at $D=d$. Thus, from Theorem \ref{thm:causal-aggregate-marginal-comparison},  $\E[Y|D=d] - \E[Y|D=d-1] = \beta_d$, as desired.
