\begin{proposition}[No Incongruent Behavior] \label{prop:no-incongruent-behavior}
    Under Assumptions \ref{ass:sutva2}, \ref{ass:unconfoundedness}, \ref{ass:no-sorting-on-D}, and \ref{ass:no-incongruity}, no incongruent comparisons are present in the aggregate contrast, $\E[Y|D=d] - \E[Y|D=d-1]$. 
\end{proposition}
%

%

%
\begin{proof}[\textbf{Proof of Proposition \ref{prop:no-incongruent-behavior}}]
    Under Assumptions \ref{ass:no-sorting-on-D} and \ref{ass:no-incongruity}, there exists a latent treatment joint distribution $F(S(d),S(d-1))$ of the sub-treatments where for all $d \in \D$: 
    \begin{align*}
        \P\big(S(d)=s_d,S(d-1)=s_{d-1} \big| D \in \{d, d-1\}\big) &= 0, ~\textrm{if } (s_{d}, s_{d-1}) \in \mathcal{M}^{-}(d) \\
        \P\big(S(d)=s_d,S(d-1)=s_{d-1} \big| D \in \{d, d-1\}\big) &\geq 0, ~\textrm{if } (s_{d}, s_{d-1}) \in \mathcal{M}^{+}(d)
    \end{align*}
    Under conditions (i) and (ii), $w(s_d, s_{d-1}) = \P(S(d) = s_d, S(d-1)=s_{d-1}|D \in \{d,d-1\})$. 

    Next, we show that the above probabilities satisfy the criteria of Proposition \ref{prop:marginal-decomposition} and put no weight on incongruent comparisons. To show this, first note that the sum: 
    \begin{align*}
        & \sum_{s_{d-1} \in \ST_{d-1}} \P\big(S(d)=s_d,S(d-1)=s_{d-1} \big| D \in \{d, d-1\}\big) \\ 
        & \hspace{10mm} = \P\big(S(d)=s_d \big| D \in \{d, d-1\}\big) = \P\big(S(d)=s_d \big| D=d \big) = \P\big(S=s_d \big| D=d \big),
    \end{align*}
    where the first equality holds by the law of total probability; the second equality holds by Assumption \ref{ass:no-sorting-on-D}; and the last equality holds by writing potential outcomes in terms of their observed counterparts.
    Similarly, we have: 
    \begin{align*}
        & \sum_{s_{d} \in \ST_{d}} \P\big(S(d)=s_d,S(d-1)=s_{d-1} \big| D \in \{d, d-1\}\big) = \P\big(S(d-1)=s_{d-1} \big| D \in \{d, d-1\}\big) \\ 
        & \hspace{10mm} = \P\big(S(d-1)=s_{d-1} \big| D=d-1 \big) = \P\big(S=s_{d-1} \big| D=d-1 \big),
    \end{align*}
    where the first equality holds by the law of total probability; the second equality holds by Assumption \ref{ass:no-sorting-on-D}; and the last equality holds by writing potential outcomes in terms of their observed counterparts. Both results fulfill the requirements of Proposition \ref{prop:marginal-decomposition}.

    Lastly, we demonstrate that the assumptions imply that there are no weights on incongruent comparisons. Denote $m(s_d,s_{d-1}) := \E[Y|S=s_d] - \E[Y|S=s_{d-1}]$. This implies that the marginal contrast decomposition becomes:
    \begin{align*}
        \E[Y|D=d] &- \E[Y|D=d-1] = \sum_{(s_{d-1}, s_{d}) \in \mathcal{M}^+(d) } w(s_d,s_{d-1}) \Big( \E[Y|S=s_d] - \E[Y|S=s_{d-1}]\Big) \\
        & \hspace{40mm} +\sum_{(s_{d-1}, s_{d}) \in \mathcal{M}^-(d) } w(s_d,s_{d-1}) \Big( \E[Y|S=s_d] - \E[Y|S=s_{d-1}]\Big) \\ 
        &= \sum_{(s_{d-1}, s_{d}) \in \mathcal{M}^+(d) } w(s_d,s_{d-1}) \cdot m(s_d, s_{d-1}) + \sum_{(s_{d-1}, s_{d}) \in \mathcal{M}^-(d) } w(s_d,s_{d-1}) \cdot m(s_d, s_{d-1}) \\
        &= \sum_{(s_{d-1}, s_{d}) \in \mathcal{M}^+(d) } \P\big(S(d)=s_d,S(d-1)=s_{d-1} \big| D \in \{d, d-1\}\big) \cdot m(s_d, s_{d-1})
    \end{align*}
    where the first equality holds by Proposition \ref{prop:marginal-decomposition}; the second equality holds by definition of $m(s_d,s_{d-1})$; and the third equality is implied by the condition on $F(S(d),S(d-1))$. Thus, no incongruent comparisons exist in the aggregate marginal contrast as required.
\end{proof}
