%
\begin{proof}[\textbf{Proof of Proposition \ref{prop:decreasing-means-implies-incongruency}}]
    We prove the result by contrapositive. Consequently, this proof shows that sets of weights which are non-zero for only congruent pairs of sub-treatment vectors must imply that for any sub-treatment $k$, and all $d \in \D_{>0}$, $\E[S_k | D=d] \; \geq \; \E[S_k | D=d-1]$.  

    For any sub-treatment indexed by $k \in \{1, \ldots, K\}$, and any $d \in \D$, see that we may write the difference in conditional means of sub-treatment $S_k$ for adjacent values of aggregated treatment $D$ as: 
    \begin{align}
        & \E[S_k | D=d] - \E[S_k | D=d-1] \notag \\ 
        %
        &= \E[ \; \E[S_k |S_d=s_d, D=d] \;| S_d = s_d] - \E[ \; \E[S_k |S_{d-1}=s_{d-1}, D=d-1] \;|S_{d-1}=s_{d-1}] \notag \\
        %
        &= \sum_{s_d \in \ST_d} \P(S=s_d | D=d) \cdot \E[S_k |S_d=s_d, D=d] \notag \\
        & \hspace{10mm} - \sum_{s_{d-1} \in \ST_{d-1}} \P(S=s_{d-1} | D=d-1) \cdot \E[S_k |S_d=s_{d-1}, D=d-1] \notag \\
        %
        &= \sum_{s_d \in \ST_d} \P(S=s_d | D=d) \cdot g_k(s_d) \notag \\
        & \hspace{10mm} - \sum_{s_{d-1} \in \ST_{d-1}} \P(S=s_{d-1} | D=d-1) \cdot g_k(s_{d-1}) \notag \\
        %
        &= \sum_{s_d \in \ST_d} \P(S=s_d | D=d) \cdot \Big( \sum_{s_{d-1} \in \ST_{d-1}} \P(S=s_{d-1}|D=d-1) \Big) \cdot g_k(s_d) \notag \\
        & \hspace{10mm} - \sum_{s_{d-1} \in \ST_{d-1}} \Big( \sum_{s_{d} \in \ST_{d}} \P(S=s_{d}|D=d) \Big) \cdot \P(S=s_{d-1} | D=d-1) \cdot g_k(s_{d-1}) \notag \\ 
        %
        &= \sum_{s_{d} \in \ST_{d}} \sum_{s_{d} \in \ST_{d}} w(s_d,s_{d-1}) \cdot \Big[ g_k(s_d) - g_k(s_{d-1}) \Big] \label{eqn:3.3A} %
        %
    \end{align}
    where the first equality holds by the law of iterated expectations on $S_d$; the second equality holds by the definition of conditional probability; the third equality holds by defining $g_k(s_d) := \E[S_k \big| S_d=s_d, D=d]$ 
    as the value of the $k^{th}$ sub-treatment given the vector of sub-treatment $s_d$ which aggregates to $D=d$; and the fourth equality holds by the second axiom of probability (unity); the fifth equality follows by algebra and by the definition of the class of weighting functions with the properties outlined in Proposition \ref{prop:marginal-decomposition}.

    In Equation \eqref{eqn:3.3A}, we defined $g_k(s_d)$ as the value of the $k^{th}$ sub-treatment when the vector of sub-treatments was $s_d$. Notice that this is a simple constant, the realized value of $S_k$, which lies at the $k^{th}$  component of the vector $s_d$: 
    \begin{align}
        g_k(s_d) &= \E[S_k|S=s_d, D=d] = \E[S_k|S=s_d] = \sum_{s_k \in \ST_k} \P(S_k=s_k | S=s_d) \cdot s_k \notag \\ 
        &= \P(S_k=s_k | S=s_d) \cdot s_k = s_k \label{eqn:3.3B1} %
    \end{align}
    where the first equality holds by definition of $g_k(s_d)$; the second equality holds since $d$ is fully determined by $s_d$; the third equality holds by the definition of expectation; the fourth equality holds because the only realization that $S_k$ can take is the value of $S_k$ from the sub-treatment vector $s_d$ found in the conditioning set; and the fifth equality holds since $\P(S_k=s_k | S=s_d)=1$ due to the previous fact.

    Now, given the result in Equation \eqref{eqn:3.3B1}, see that if a pair of sub-treatment vectors is congruent, $(s_d,s_{d-1}) \in \mathcal{M}^{+}(d)$, then
    \begin{equation}
        g_k(s_d) - g(s_{d-1}) = s_{d,k} - s_{d-1,k} = \begin{cases}
            1, \text {if } s_{d,k} > s_{d-1,k} \\ 
            0, \text{ if } s_{d,k} = s_{d-1,k}
        \end{cases}
        \label{eqn:3.3B2} %
    \end{equation}
    which holds by the definition of congruency. Any two sub-treatment vectors which can be written as $s_d = s_{d-1} + 1_k$, where $1_k$ is a unit vector for the $k^{th}$ sub-treatment, are considered congruent and lie in the set $\mathcal{M}^{+}(d)$ at any $d \in \D$. 

    Since the weights in Equation \eqref{eqn:3.3A} are the same as in Proposition \ref{prop:marginal-decomposition}, then they are positive and sum to one. This, together with Equation \eqref{eqn:3.3B2}, implies that if weights were only non-negative for congruent sub-treatment vectors, then \eqref{eqn:3.3A} would be non-negative. Thus, take any weighting function which satisfies the properties in Proposition \ref{prop:marginal-decomposition} and puts non-negative weight on congruent sub-treatment vectors only, and denote it as $w^{+}(\cdot,\cdot)$. From \eqref{eqn:3.3A}, for any sub-treatment $k$, we have: 
    \begin{align}
        \sum_{s_{d} \in \ST_{d}} \sum_{s_{d} \in \ST_{d}} w(s_d,s_{d-1}) \cdot \Big[ g_k(s_d) - g_k(s_{d-1}) \Big] &= \sum_{s_{d} \in \ST_{d}} \sum_{s_{d} \in \ST_{d}} w^{+}(s_d,s_{d-1}) \cdot \Big[ g_k(s_d) - g_k(s_{d-1}) \Big] \notag \\
        &= \sum_{(s_d,s_{d-1}) \in \mathcal{M}^{+}(d)} w^{+}(s_d,s_{d-1}) \cdot 1\Big\{ g_k(s_d) > g_k(s_{d-1}) \Big\} \notag \\ 
        &\geq 0 \label{eqn:3.3C} %
    \end{align}
    where the first line holds since only positive weights are placed on the congruent comparisons of sub-treatments, denoted by $w^{+}(\cdot,\cdot)$; the second equality holds by the result in \eqref{eqn:3.3B2}, since differences in sub-treatment $k$ must be either one or zero for congruent vectors of sub-treatments; and the inequality in the third line holds because the weights must be non-negative by Proposition \ref{prop:marginal-decomposition}.

    Lastly, the inequality in \eqref{eqn:3.3C} implies that, for any weighting scheme that applies positive weight to only congruent pairs of sub-treatments, the difference in conditional means for any sub-treatment $k$ in \eqref{eqn:3.3A} must satisfy 
    \begin{align*}
        \E[S_k | D=d] - \E[S_k | D=d-1] \geq 0 &\iff \E[S_k | D=d] \geq \E[S_k | D=d-1], 
    \end{align*}
    which states the claim, as desired. As $d$ increases, the means of sub-treatments must not decline in order to rationalize fully congruent weighting schemes. Violations of this inequality signal that weight on incongruent sub-treatments is inevitable. 
\end{proof}
