\begin{proposition} \label{prop:datt-identification} 
Under Assumption \ref{ass:sutva2}, the difference in mean outcomes for the group that experienced sub-treatment $s_d$ relative to the untreated group can be decomposed as 
\begin{align*}
    \E[Y|S=s_d] - \E[Y|S=0_K] &= \mathrm{ATT}(s_d) + UB(s_d)
\end{align*}
where
\begin{align*}
    UB(s_d) &:= \E[Y(0)|S=s_d] - \E[Y(0) | S=0_K]
\end{align*}
which is a selection bias term.  If, in addition, Assumption \ref{ass:unconfoundedness} holds, then $UB(s_d) = 0$, so that
\begin{align*}
    \mathrm{ATT}(s_d) = \E[Y|S = s_d] - \E[Y|S=0_K]
\end{align*}
where $0_K$ denotes the zero vector of length $K$ for the untreated group.
\end{proposition}
Proposition \ref{prop:datt-identification} shows that $\textrm{ATT}(s_d)$ is identified if the sub-treatments are observed and under Assumption \ref{ass:unconfoundedness} (or Assumption \ref{ass:untreated-potential-outcomes}).

%
\begin{proof}[\textbf{Proof of Proposition \ref{prop:datt-identification}}]
    For the first part, notice that
    \begin{align*}
        \E[Y|S=s_d] - \E[Y|S=0_K] &= \E[Y(s_d)|S=s_d] - \E[Y(0)|S=0_K] \\
        &= \E[Y(s_d) - Y(0)|S=s_d] + \E[Y(0)|S=s_d] - \E[Y(0)|S=0_K] \\
        &= \textrm{ATT}(s_d) + UB(s_d)
    \end{align*}
    where the first equality holds by writing observed outcomes as potential outcomes; the second equality holds by adding and subtracting $\E[Y(0)|S=s_d]$; and the last equality holds by the definitions of $\textrm{ATT}(s_d)$ and $UB(s_d)$. For the second part of the result, it follows immediately from Assumption \ref{ass:unconfoundedness} (or Assumption \ref{ass:untreated-potential-outcomes}) that $UB(s_d)=0$, which implies the result. 
\end{proof}
%

\bigskip

%
\begin{proof}[\textbf{Proof of Theorem \ref{thm:att-identification}}]
    We proved the first part of the result as Proposition \ref{prop:datt-identification}.  For the second part, starting from the definition of $\textrm{ATT}(d)$, we have that
    \begin{align*}
        \textrm{AATT}(d) &= \E\big[\textrm{ATT}(S)\big|D=d\big] \\
        &= \sum_{s_d \in \mathcal{S}_d} \textrm{ATT}(s_d) \cdot \P(S=s_d|D=d) \\
        &= \sum_{s_d \in \mathcal{S}_d} \Big(\E[Y|S=s_d] - \E[Y|S=0_K]\Big) \cdot \P(S=s_d|D=d) \\
        &= \E[Y|D=d] - \E[Y|D=0]
    \end{align*}
    where the first equality holds from the definition of $\textrm{AATT}(d)$; the second equality expands the expectation; the third equality holds by Proposition \ref{prop:datt-identification}; and the last equality holds by the law of iterated expectations.
\end{proof}
