\section{The matrix shuffle algebra of quantum toroidal $\fgl_{n|m}$}
\label{sec:shuffle}

In this section we recall the matrix shuffle algebra and its relation with the quantum toroidal $\fgl_n$ algebra \cite{Ng_tale}. We will then explain the generalization to the case of $\fgl_{n|m}$, of which many steps are conjectural (however, we outline the main challenges that need to be solved). After that we will introduce a diagrammatic representation of the elements of the shuffle algebra and the shuffle product which will be used in subsequent sections.


\subsection{The $R$-matrix}\label{sec:R-matrix}
Let $V = \BC^n$ and let $E_{ij}$ denote the $n \times n$ matrix with a single 1 at the intersection of row $i$ and column $j$, and zeroes everywhere else. 
The $R$-matrix $R(z/w) \in \text{End}(V_w \otimes V_z)$ of $\uu$ is given by:
\begin{align}\label{eq:R-matrix}
  R(z) := \sum_{1\leq i,j\leq n}
  \left(\frac{t^{-1/2}-z t^{1/2}}{1-z}\right)^{\delta_{i=j}}E_{ii}\otimes E_{jj}  
  +
  \sum_{1\leq i\neq j\leq n}
  \frac{(t^{-1/2}-t^{1/2})z^{\delta_{i<j}}}{1-z}E_{ij}\otimes E_{ji}  
\end{align}
Let $P \in \text{End}(V \otimes V)$ be the permutation matrix. The matrix $\check R$ is defined by:
\begin{align}\label{eq:R and R-check}
    \check{R}(z) := R(z) P
\end{align}
We define the matrix $\check R_i(z_{i+1}/z_i)\in \text{End}(V_{z_1}\otimes \cdots \otimes V_{z_N})$ by the action of $\check R(z_{i+1}/z_i)$ on $V_{z_i}\otimes V_{z_{i+1}}$ and by the identity on all other tensor factors. Similarly $P_i\in \text{End}(V_{z_1}\otimes \cdots \otimes V_{z_N})$ denotes the action by $P$ on $V_{z_i}\otimes V_{z_{i+1}}$ and by the identity on the other factors. For $1\leq i<j\leq N$ we define $\check R_{i,j}(z)$ as $\check R$ acting in the $i$-th and $j$-th tensor factors. Another important matrix is $\check R^\bullet$ defined by:
\begin{align}
    \label{eq:R-bullet}
    \check{R}^\bullet(z):=(D\otimes \id) \check{R} (z t^{-n}) (\id\otimes D^{-1})
\end{align}
where:
\begin{align}
    \label{eq:D}
    D := \normalfont{\text{diag}}\{1,t^{-1}\ldots t^{-n+1}\}
\end{align}
The matrix $\check R^\bullet_{i,j}\in \text{End}(V_{z_1}\otimes \cdots \otimes V_{z_N})$ is defined in the same way as $\check R_{i,j}$.

The matrix $\check R$ satisfies the Yang--Baxter equation, the unitarity relation and has a simple pole at $z=1$:
\begin{align}
    \label{eq:YB}
    \check R_{i}(z/y)
    \check R_{i+1}(z/x)
    \check R_{i}(y/x)
    &=
    \check R_{i+1}(y/x)
    \check R_{i}(z/x)
    \check R_{i+1}(z/y)
\\
\label{eq:unitarity}
    \check R(x/y)
    \check R(y/x)
    &=f(x/y) \text{id}\otimes \text{id},\\
\label{eq:R residue}
    \underset{x=y}{\text{Res}}\,\check R(x/y) &= (t^{1/2}-t^{-1/2})\id \otimes \id     
\end{align}
where ``Res $f(z)$'' denotes the residue of the 1-form $f(z)\frac {dz}z$, and
\begin{align}
    \label{eq:f}
    f(x)=\frac{(1-t x)(1-t^{-1}x)}{(1-x)^2}
\end{align}
Additionally, the matrices $\check R$ and $\check R^\bullet$ satisfy the {\it crossing unitarity relation}:
\begin{align}
    \label{eq:crossing_unitarity}
\left(\check{R}^\bullet(x) P
    \right)^{T_2}
    \left(P \check{R}(x^{-1})
    \right)^{T_2} =\id\otimes \id
\end{align}
where $T_2$ denotes the transposition in the second tensor factor.


\subsection{Symmetric tensors and wheel conditions}
\label{sub:symmetric tensors}

Consider the vector space:
\begin{equation}
\label{eqn:big space}
\CV = \bigoplus_{k=0}^{\infty} \text{End}_{\BC(q,t)}(V^{\otimes k}) (z_1 \ldots z_k)
\end{equation}
For a fixed  $k\geq 0$ we will sometimes write $(z)$ instead of $(z_1\ldots z_k)$, for simplicity. Similarly, if $\sigma$ is a permutation in the symmetric group $\mathfrak{S}_k$ then we will write $(z_\sigma)=(z_{\sigma(1)} \ldots z_{\sigma(k)})$. Fix $k\geq 0$, a tensor $X=X_{1\dots k}(z_1 \ldots z_k)$ will be called symmetric if for all $\sigma \in \mathfrak{S}_k$ we have:
\begin{equation}
\label{eqn:symmetric tensor}
\check R_\sigma(z) 
X_{1\ldots k}(z) = 
X_{1\ldots k}(z_{\sigma})
\check R_\sigma(z)
\end{equation}
where the matrix $\check R_{\sigma}(z) = \check R_{\sigma} (z_1\ldots z_k)$ is defined recursively by
\begin{align}
\label{eq:Rch-sigma}
&\check R_{\text{id}}(z) = 1,\qquad    
\check R_{\sigma}(z) = \check R_{i}(z_{\sigma'(i+1)}/z_{\sigma'(i)})
   \check R_{\sigma'}(z)
\end{align}
whenever $\sigma=s_i\sigma'$ is a reduced decomposition in $\mathfrak S_k$. We similarly define $\check R^\bullet_{\sigma}$ and $R_\sigma$; in particular, in terms of the latter matrices, formula \eqref{eqn:symmetric tensor} takes the form
$$
R_\sigma (z)
X_{1...k}(z) = 
X_{\sigma(1)\dots\sigma(k)}(z_{\sigma})
R_\sigma(z)
$$
Above and henceforth, we often write $X_{1\dots k}$ to indicate the fact that $X$ is a linear operator on $V^{\otimes k}$, and use the notation $X_{\sigma(1)\dots\sigma(k)}$ to denote the same linear operator conjugated by the permutation of the factors of $V^{\otimes k}$ corresponding to $\sigma \in \mathfrak S_k$. The subspace of symmetric tensors will be denoted by:
\begin{equation}
\label{eqn:symmetric space}
\CV_{\text{sym}} \subset \CV
\end{equation}
Furthermore, we say that a symmetric tensor satisfies the pole conditions if it is of the form:
\begin{equation}
\label{eqn:pole condition}
X_{1\dots k}(z_1\ldots z_k) = \frac {x_{1\dots k}(z_1\ldots z_k)}{\prod_{1\leq i \neq j \leq n} (z_i-z_jq)}
\end{equation}
for some Laurent polynomial:
$$
x_{1\dots k}(z_1 \dots z_k) \in \text{End}_{\BC(q,t)}(V^{\otimes k}) [z_1^{\pm 1} \dots z_k^{\pm 1}]
$$
The subspace of symmetric tensors which satisfy the pole conditions will be denoted by:
\begin{equation}
\label{eqn:pole space}
\CA^+_{\text{big}} \subset \CV_{\text{sym}}
\end{equation}


\begin{defn}
\label{def:wheel}
Consider any composition $\lambda$ of length $u$ and size $\lambda_1+\dots+\lambda_{u}=k$, and let $c_i = \lambda_1+\dots+\lambda_{i-1}+1$ for all $i \in \{1,\dots,u+1\}$. A tensor $X \in \CA^+_{\emph{big}} \cap \normalfont{\text{End}}_{\BC(q,t)}(V^{\otimes k}) (z_1 \ldots z_k)$ is said to satisfy the wheel conditions if, for every composition $\lambda$ as above, the iterated residue of $X$ at:
\begin{equation}
\label{eqn:residue variables}
\Big\{z_{\lambda_1+\dots+\lambda_{s-1}+1} = y_s, z_{\lambda_1+\dots+\lambda_{s-1}+2} = y_s q  \ldots  z_{\lambda_1+\dots+\lambda_{s-1}+\lambda_s} = y_s q^{\lambda_s-1} \Big\}_{1\leq s \leq u}
\end{equation}
is of the form:
\begin{equation}
\label{eqn:residue}
(t^{\frac 12} - t^{-\frac 12})^{k-u} \prod^{\text{unordered pairs } (s,d) \neq (t,e)}_{\text{with } 1 \leq s,t \leq u, 1 \leq d < \lambda_s, 1 \leq e < \lambda_t} f \left( \frac {y_s q^{d}}{y_t q^{e}} \right) \left[ \prod_{u \geq s \geq 1} \prod_{s \leq t \leq u} \prod_{1 \leq e < \lambda_t} R_{c_s,c_t+e} \left( \frac {y_s}{y_t q^{e}}\right) \right]  
\end{equation}
$$
 X^{(\lambda_1\ldots \lambda_u)}_{c_1 \ldots c_u}(y_{1}\ldots y_{u}) \left[ \prod_{1 \leq s \leq u} \prod_{u \geq t > s} \prod_{\lambda_t > e \geq 1} R_{c_t + e, c_s} \left( \frac {y_t q^{e}}{y_s q^{\lambda_s}} \right) \right] \left[ \prod_{s=1}^u P_{c_s} P_{c_s+1} \dots P_{c_{s+1}-2} \right]
$$
for some tensor $X^{(\lambda_1\ldots \lambda_u)} \in \emph{End}(V^{\otimes u})(y_1\ldots y_u)$. We write:
\begin{equation}
\label{eqn:wheel space}
\CA^+ \subset \CA^+_{\emph{big}}
\end{equation}
for the vector subspace of symmetric tensors which satisfy the pole and wheel conditions. 
\end{defn}

We remark that the pole conditions (which require that tensors $X$ have at most simple poles at $z_i = z_j q$) were precisely introduced in order for the residue at \eqref{eqn:residue variables} to be well-behaved. As shown in \cite[Proposition 4.11]{Ng_tale}, for any composition $\lambda=(\lambda_1\ldots \lambda_u)$ with $k = \lambda_1+\dots+\lambda_u$, the tensor $X^{\lambda}(y_{1}\ldots y_{u})$ that features in \eqref{eqn:residue} also satisfies the pole conditions in the variables $y_s$, and is symmetric in the sense of \eqref{eqn:symmetric tensor} with respect to all pairs of variables $y_s$ and $y_t$ for which $\lambda_s = \lambda_t$.

\begin{ex}\label{ex:wheel u=1}
    We consider the particular example of Definition \ref{def:wheel} with $u=1$ and $k=3$. 
    and compute the wheel condition for a tensor $X(z_1,z_2,z_3)\in \CA_{\text{big}}^+ \cap \normalfont{\text{End}}_{\BC(q,t)}(V^{\otimes 3}) (z_1,z_2,z_3)$. 
    We have $\lambda=(\lambda_1)=(3)$ and $(c_1,c_2)=(1,4)$, so the specialization in \eqref{eqn:residue variables} is given by:
    \begin{equation}
    \label{eqn:residue variables example first line}
    \left\{z_1 = y, z_2 =  q y,  z_3 = q^2 y\right\}
    \end{equation}
    where we set $y_1=y$. The first line in \eqref{eqn:residue} is given by
    \begin{equation*}
(t^{\frac 12} - t^{-\frac 12})^{2} \prod_{1 \leq e < d< 3} f \left(q^{d-e} \right) \left[ \prod_{1 \leq e < 3} R_{1,1+e} \left(q^{-e}\right) \right]  =
(t^{\frac 12} - t^{-\frac 12})^{2} 
f \left(q \right)
R_{1,2} \left(q^{-1}\right)
R_{1,3} \left(q^{-2}\right)
\end{equation*}
and the second line in \eqref{eqn:residue} is given by
\begin{equation*}
     X^{(3)}_{1}(y) \left[ \prod_{s=1}^u P_{c_s} P_{c_s+1} \dots P_{c_{s+1}-2} \right]  = X^{(3)}_{1}(y) P_1 P_2
\end{equation*}
Combining these two expressions, we conclude that the wheel condition with $\lambda=(3)$ for a tensor $X(z_1,z_2,z_3)$ requires that its residue be of the form:
\begin{equation}\label{eqn:residue variables example}
\underset{\left\{z_1 = y,z_2 =q y,z_{3} = q^{2} y\right\}}{\normalfont{\text{Res}}}X(z_1,z_2, z_3)=
(t^{\frac 12} - t^{-\frac 12})^{2} 
f \left(q \right)
R_{1,2} \left(q^{-1}\right)
R_{1,3} \left(q^{-2}\right)
 X^{(3)}_{1}(y) P_1 P_2
\end{equation}
for some $X^{(3)}(y) \in \emph{End}(V)(y)$. By commuting the permutation matrices $P_i$ to the left and combining them with the $R$-matrices we can rewrite this using the $\check R$ matrices \eqref{eq:R and R-check}:
\begin{equation}\label{eqn:residue variables example R-check}
\underset{\left\{z_1 = y,z_2 =q y,z_{3} = q^{2} y\right\}}{\normalfont{\text{Res}}}X(z_1,z_2, z_3)
=(t^{\frac 12} - t^{-\frac 12})^{2}
f \left(q \right)
\check R_1 \left(q^{-1}\right)
\check R_2 \left(q^{-2}\right)
 X^{(3)}_{3}(y)
\end{equation}

In a more general case $\lambda=(k)$ we have:
\begin{align}\label{eqn:residue (k)}
\underset{\left\{z_1 = y \ldots  z_{k} = q^{k-1} y\right\}}{\normalfont{\text{Res}}}X(z_1\ldots z_k)= (t^{\frac 12} - t^{-\frac 12})^{k-1} \prod_{j=1}^{k-2} f \left(q^j \right)^{k-1-j}
 \check R_{1} \left(q^{-1}\right) \cdots \check R_{k-1} \left(q^{-k+1}\right) X_k^{(k)}(y)
\end{align}
\end{ex}
\subsection{The shuffle product}
\label{sub:shuffle product}

We can make the vector space $\CV$ of \eqref{eqn:big space} into an associative algebra via the following formula for all $A = A_{1\ldots k}(z_1\ldots z_k)$, $B = B_{1\ldots l}(z_1\ldots z_l)$ in $\CV$:
\begin{equation}
\label{eqn:shuffle product}
A * B = \sum^{a_1<\ldots <a_k, \ b_1<\ldots <b_l}_{\{1\ldots k+l\} = \{a_1\ldots a_k\} \sqcup \{b_1\ldots b_l\}} \left[ \prod_{i=k}^{1} \prod_{j=1}^l \underbrace{R_{a_ib_j} \left( \frac {z_{a_i}}{z_{b_j}} \right)}_{\text{only if }a_i < b_j} \right] 
\end{equation}
$$
A_{a_1\ldots a_k}(z_{a_1}\ldots z_{a_k}) \left[ \prod_{i=1}^k \prod_{j=l}^{1} R_{b_ja_i}  \left( \frac {z_{b_j}}{z_{a_i} q} \right) \right] B_{b_1\ldots b_l}(z_{b_1}\ldots z_{b_l})  \left[  \prod_{i=k}^{1} \prod_{j=1}^l \underbrace{R_{a_ib_j} \left( \frac {z_{a_i}}{z_{b_j}} \right)}_{\text{only if }a_i > b_j} \right] 
$$
The unit of this multiplication is $1 \in \text{End}_{\BC(q,t)}(V^{\otimes 0})$. We will refer to $*$ as the shuffle product.

% \begin{prop}[\cite[Propositions 2.6, 4.6, 4.10]{Ng_tale}]
\begin{prop}[\texorpdfstring{\!\!\cite[Propositions 2.6, 4.6, 4.10]{Ng_tale}}{[Prop. 2.6, 4.6, 4.10]}]
\label{prop:preserve}
The subspaces $\CV_{\emph{sym}}$, $\CA^+_{\emph{big}}$ and $\CA^+$ are preserved by $*$.

\end{prop}

With the Proposition above in mind, we will call $\CA^+$ the shuffle algebra, and it will be the main object of our study. 

The shuffle product $*$ can be written in terms of the matrix $\check{R}$:
\begin{align}
    \label{eq:A*B-Rcheck}
    A*B=\sum_{\sigma\in \mathfrak S_{k+l}/\mathfrak S_l\times \mathfrak S_k}
    \frac{1}{f_\sigma(z)}\check R_\sigma^{-1}(z)
    \Gamma^+_{A,B}(z_\sigma) \check R_\sigma(z)
\end{align}
where $f_\sigma(z)$ is a normalizing factor:
\begin{align}\label{eq:f-sigma}
    f_\sigma(z):= \prod_{\substack{1\leq i< j\leq k+l\\ \sigma(i)>\sigma(j)}} f\left(\frac{z_{\sigma(j)}}{z_{\sigma(i)}}\right)
\end{align}
The tensor $\Gamma^+_{A,B}(z_1\ldots z_{k+l})$ is given by:
\begin{multline}
        \label{eq:Gamma_plus}
    \Gamma^+_{A,B}(z_1\ldots z_{k+l}) :=
    A_{l+1\ldots k+l}(z_{l+1}\ldots z_{k+l})
    \check R_{\omega^{l}}(q z_{l+1}\ldots q z_{l+k},z_{1}\ldots z_{l})\\
    B_{k+1\ldots k+l}(z_1\ldots z_{l}) 
    \check R_{\omega^k}(z_1\ldots z_{k+l})
\end{multline}
where $\omega^{j}\in \mathfrak S_{k+l}$ is the rotation by $j$ units: $\omega^j(12\ldots k+l)=(k+l-j+1\ldots k+l,1\ldots k+l-j)$.  
The version of the shuffle product in \eqref{eq:A*B-Rcheck} contains pairs of $\check R$-matrices which can be removed with the help of the unitarity relation \eqref{eq:unitarity}. When one such pair is removed we need to multiply the expression by a factor $f(z_i/z_j)$ for an appropriate pair of indices $i,j$. When all such pairs of $\check R$-matrices are removed the resulting product of factors $f(z_i/z_j)$ will cancel against $f_\sigma(z)$. 

\subsection{The double shuffle algebra}
\label{sub:double}

One of the deeper results concerning the shuffle algebra $\CA^+$ (which is one of the reasons why the wheel conditions in Definition \ref{def:wheel} are natural to impose) is the following.

\begin{prop}
\label{prop:gen}

(\!\!\cite[Corollary 5.30]{Ng_tale}) As a $\BC(q,t)$ algebra, $\CA^+$ is generated by the elements
\begin{equation}
\label{eqn:generators}
E_{ij} = E_{\bar{i}\bar{j}} z_1^{\left \lfloor\frac {i-1}n \right \rfloor - \left \lfloor\frac {j-1}n \right \rfloor} \in \emph{End}(V)[z_1^{\pm 1}]
\end{equation}
as $(i,j)$ runs over $\BZ^2/(n,n)\BZ$, where $\bar{i}$ denotes the element of $\{1\ldots n\}$ congruent to $i$ modulo $n$. 

\end{prop}

\begin{defn}
\label{def:negative shuffle}

Let $\CA^-$ denote the algebra defined just like $\CA^+$, but with the parameter $q^{-1}t^n$ instead of $q$ in Definition \ref{def:wheel} and \eqref{eqn:pole condition}, and with
$$
D_{b_j} R_{b_ja_i}  \left( \frac {z_{b_j}q}{z_{a_i} t^n} \right) D_{b_j}^{-1} \quad \text{instead of} \quad R_{b_ja_i} \left( \frac {z_{b_j}}{z_{a_i} q} \right)
$$
in \eqref{eqn:shuffle product}, where $D$ was defined in \eqref{eq:D}.

\end{defn}
We will reuse the symbol $*$ for the shuffle product of $\CA^-$. For two tensors $A = A_{1\ldots k}(z_1\ldots z_k)\in \CA^-$ and $B = B_{1\ldots l}(z_1\ldots z_l)\in \CA^-$ we have the following analogue of \eqref{eq:A*B-Rcheck}
\begin{align}
    \label{eq:A*B-Rcheck-dual}
    A*B=\sum_{\sigma\in \mathfrak S_{k+l}/\mathfrak S_l\times \mathfrak S_k}
    \frac{1}{f_\sigma(z)}
    \check R_\sigma^{-1}
    \Gamma^-_{A,B}(z_\sigma) \check R_\sigma
\end{align}
where:
\begin{multline}
        \label{eq:Gamma_minus}
    \Gamma^-_{A,B}(z_1\ldots z_{k+l}) :=
    A_{l+1\ldots k+l}(z_{l+1}\ldots z_{k+l})
    \check R^\bullet_{\omega^{l}}(z_{l+1}\ldots  z_{l+k},q z_{1}\ldots q z_{l})\\
    B_{k+1\ldots k+l}(z_1\ldots z_{l}) 
    \check R_{\omega^k}(z_1\ldots z_{k+l})
\end{multline}
It is easy to see that we have an isomorphism $\CA^+ \xrightarrow{\sim} \CA^-$ given by the assignment
$$
X_{1\dots k}(z_1\ldots z_k) \mapsto D_1 \dots D_k X_{1\dots k}(z_1\ldots z_k)  \Big|_{q \mapsto q^{-1}t^n}
$$
In what follows, we will encounter the quantum group of type $\widehat{A}_{n-1}$
\begin{equation}
\label{eqn:sl}
\su = \BC(t) \Big \langle x_i^+, x_i^-, \psi_i^{\pm 1},c^{\pm 1} \Big \rangle_{i \in \{1\ldots n\}} \Big/ \Big( \text{\text{relations (3.4)-(3.7) of \cite{Ng_tale}}} \Big)
\end{equation}
(note that its Cartan subalgebra has one more dimension than usual for the quantum group, but this is a trivial modification) and the quantum Heisenberg algebra
\begin{equation}
\label{eqn:gl 1}
\uui = \BC(t) \Big \langle p_{\pm k}, c^{\pm 1} \Big \rangle_{k \in \BN} \Big/ 
 \Big( [p_k,p_{-k}] = k \frac {c^k - c^{-k}}{t^k - t^{-k}} \text{ and all other commutators 0} \Big)
\end{equation}
We define the quantum affine group associated to $\fgl_n$ by
\begin{equation}
\label{eqn:gl}
\uu = \su \otimes \uui
\end{equation}

\begin{defn}
\label{def:double shuffle}

(see \cite[Section 6]{Ng_tale} for details) The vector space
\begin{equation}
\label{eqn:double a}
\CA = \CA^+ \otimes \uu \otimes \CA^-
\end{equation}
is made into an algebra by specifying how the three factors commute with each other.

\end{defn}

\subsection{The quantum toroidal algebra}
\label{sub:classic shuffle}

We will consider the quantum toroidal algebra
$$
\UU = \BC(q,t) \Big \langle x_{i,k}^+, x_{i,k}^-, \varphi_{i,k'}^+,  \varphi_{i,k'}^-, \psi_i^{\pm 1}, c^{\pm 1}, \bar{c}^{\pm 1} \Big \rangle_{i \in \{1\ldots n\}}^{k \in \BZ, k' >0 } \Big/ \Big( \text{relations (3.41)--(3.47) of \cite{Ng_tale}} \Big)
$$

\begin{thm}
\label{thm:iso}

(\!\!\cite[Theorem 1.5]{Ng_tale}) There exists an isomorphism 
\begin{equation}
\label{eqn:Phi}
\Phi : \UU \xrightarrow{\sim} \CA
\end{equation}
completely determined by sending 
$$
\varphi_{i,1}^\pm \in \UU \qquad \text{to} \qquad E_{ii} \in \CA^\pm \subset \CA
$$
and 
$$
x_{i,0}^\pm,\psi_i \in \UU \quad \text{to} \quad  x_i^\pm,\psi_i \in \uu \subset \CA
$$
for all $i \in \{1\ldots n\}$.

\end{thm}

The isomorphism $\Phi$ is very non-trivial (it uses an explicit description of both $\UU$ and $\CA$ in terms of slope subalgebras determined in \cite{Ng_pbw}) and this has a lot of potential, in the following sense: formulas that are quite easy on one side of the isomorphism are quite difficult on the other side, and vice versa. An example of this is given by Proposition \ref{prop:comm} in Section \ref{sec:Commutative}. Theorem \ref{thm:iso} was proved in \cite{Ng_tor_sh, Ng_pbw,Ng_tale} by an in-depth study of the algebras involved, in which an important part was played by the classic double shuffle algebra realization of $\UU$, which we now recall.


\begin{defn}
\label{def:classic shuffle}

(\!\!\cite{E}, inspired by \cite{FO}) Consider the vector space
\begin{equation}
\label{eqn:classic shuffle}
\CS^+ \subset \bigoplus_{\bd = (d_i \geq 0)_{i \in \{1,\dots,n\}}} \BC(q,t) (x_{i1},\dots,x_{id_i})_{i \in \{1,\dots,n\}}^{\emph{sym}} 
\end{equation}
consisting of rational functions which are

\begin{itemize}[leftmargin=*]

\item symmetric in $x_{i1}, x_{i2},\dots$ for each $i \in \{1,\dots,n\}$ separately

\item have at most poles of the form $x_{ia}t^{-1/2}-x_{i+1,b}t^{1/2}$ for any $i,a,b$, where we write $x_{n+1,b} =q^{-1} x_{1b}$.

\item their residue the pole above is divisible by $x_{ia}-x_{i+1,b'}$ and by $x_{i+1,b}-x_{ia'}$ for any $a \neq a'$ and $b \neq b'$

\end{itemize}

One makes $\CS^+$ into an algebra with respect to the shuffle multiplication
\begin{multline} 
R * R' = \emph{Sym} \left[R(x_{i1},\dots,x_{id_i})_{i \in \{1,\dots,n\}} R'(x_{i,d_i+1},\dots,x_{i,d_i+d_i'})_{i \in \{1,\dots,n\}} \right. \\ \left. \prod_{i,j \in \{1,\dots,n\}} \prod_{a \leq d_i, b > d_j} \begin{cases} \frac {x_{ia} t^{-1/2} - x_{jb}t^{1/2}}{x_{ia}-x_{jb}} & \text{if } i \equiv j \text{ mod }n \\ \frac {x_{ia}-x_{jb}q^{-\delta_{j1}}}{x_{ia} t^{-1/2} - x_{jb}t^{1/2}q^{-\delta_{j1}}} &\text{if } i+1 \equiv j \text{ mod }n \\ 1 & \text{otherwise} \end{cases}\right]
\end{multline}

\end{defn}



One lets $\CS^- = \CS^{+,\text{op}}$ and defines the double shuffle algebra as
$$
\CS = \CS^+ \otimes \uui^{\otimes n} \otimes \CS^-
$$
by appropriately specifying how the three tensor factors should commute with each other (see \cite{Ng_tor_sh} for details). Then the main result of \cite{Ng_tor_sh} is an isomorphism
\begin{equation}
\label{eqn:Upsilon}
\Upsilon: \UU \xrightarrow{\sim} \CS
\end{equation}
determined by sending $x_{i,k}^\pm$ to the Laurent polynomials $x_{i1}^k \in \CS^\pm$, for all $i \in \{1,\dots,n\}$ and $k \in \BZ$. Composing the isomorphisms \eqref{eqn:Phi} and \eqref{eqn:Upsilon} gives us the isomorphism $\CA \cong \CS$ between the two kinds of double shuffle algebras featured in the present paper.


\subsection{The super case}
\label{sub:super}

There exists an analogue of the discussion above for the Lie superalgebra $\fgl_{n|m}$ instead of $\fgl_n$, although much of it is conjectural (we will outline the complete picture and clearly state the missing parts, but stop short of implementing them). One considers $V = \BC^{n+m}$ and replaces the $R$-matrix \eqref{eq:R-matrix} by
\begin{align}\label{eq:R-matrix super}
  R(z) := \sum_{i,j=1}^{n+m}
  \left(\epsilon_i\frac{t^{-\epsilon_i /2}-z t^{\epsilon_i /2}}{1-z}\right)^{\delta_{i=j}}E_{ii}\otimes E_{jj}  
  +
  \sum_{\substack{i,j=1\\ i\neq j}}^{n+m}
  \frac{(t^{-1/2}-t^{1/2})z^{\delta_{i<j}}}{1-z}E_{ij}\otimes E_{ji}  
\end{align}
where:
\begin{align}\label{eq:gradation}
\epsilon_i = (-1)^{\delta_{i> n}}
\end{align}
is the gradation of the standard basis vectors $\ket{i}\in V$, $i=1\ldots n+m$\footnote{We choose the gradation of vectors to be $\{\overset{n}{\overbrace{1\ldots 1}},\overset{m}{\overbrace{-1\ldots -1}}\}$ for simplicity of presentation. More generally, one may take instead any permutation of $\{1\ldots 1,-1\ldots -1\}$.}.
The supersymmetric version of the matrix $\check R$ is given by:
\begin{align}\label{eq:R-check  super}
  \check R(z) := R(z)P
\end{align}
The $R$-matrix \eqref{eq:R-matrix super} has the same fundamental properties as \eqref{eq:R-matrix}: it satisfies the Yang-Baxter equation with spectral parameter \eqref{eq:YB}, unitarity \eqref{eq:unitarity} and crossing unitarity \eqref{eq:crossing_unitarity} in which the matrix $\check R^{\bullet}$ reads:
\begin{align}
    \label{eq:R-bullet-super}
    \check{R}^\bullet(z):=(D\otimes \id) \check{R} (z t^{m-n}) (\id\otimes D^{-1})
\end{align}
where:
\begin{align}
    \label{eq:D-super}
    D := \normalfont{\text{diag}}\{1,t^{-1}\ldots t^{-n+1},(-1)t^{-n+1},(-t)t^{-n+1}\ldots (-t^{m-1})t^{-n+1}\}
\end{align}
The $R$-matrix \eqref{eq:R-matrix super} has a simple pole at $z = 1$ with the same residue as before. This allows the discussion in Subsections \ref{sub:symmetric tensors}, \ref{sub:shuffle product} and \ref{sub:double} to run through, and determines shuffle algebras $\CA^+$ and $\CA^-$ that one can combine into a Drinfeld double
\begin{equation}
\label{eq:double super}
\CA = \CA^+ \otimes U_t(\dot{\fgl}_{n|m}) \otimes \CA^-
\end{equation}

\begin{conj}
\label{conj:super}

There is an isomorphism 
\begin{equation}
\label{eqn:conj super}
\CA \cong U_{q,t}(\ddot{\fgl}_{n|m})
\end{equation}
with the quantum toroidal superalgebra in the right-hand side defined as in \cite{BM}.


\end{conj}


\begin{rmk}
\label{rmk:conj super}

It may be the case that for \eqref{eqn:conj super} to hold, one needs to impose upon its right-hand side additional higher order relations, on top of the ones considered in \cite{BM}. In \cite{Ng_reduced} (in the particular case of the generalized conifold, which is a singular toric Calabi-Yau threefold) the second-named author introduced such higher order relations, with the express goal of making the quantum toroidal superalgebra isomorphic to the corresponding double shuffle algebra $\CS$. 

\end{rmk}

