\section{An anti-isomorphism of shuffle algebras}\label{sec:Psi}
In this section we introduce an anti-isomorphism $\Psi$ which relates the shuffle algebras $\CA^+$ and an algebra $\CA'$, which is obtained from $\CA^-$ by reversing the order of the tensor product spaces and inverting $q$ and $t$.  This anti-isomorphism can be extended to a map $\widetilde\Psi$ relating shuffle algebras associated to different supersymmetric quantum toroidal algebras. In the next section we will use both $\Psi$ and $\widetilde \Psi$ as tools for producing new commuting elements of matrix shuffle algebras.

\subsection{The shuffle algebra $\CA'$}\label{sec:A-prime}
We start by defining a transform $\Omega$ which acts on tensors in $\CV$ by:
\begin{align}\label{eq:Omega}
    \Omega(X_{1\ldots k}(z_1\ldots z_k)) = X_{k\ldots 1}(z_{k}\ldots z_{1})\Big{|}_{q,t\rightarrow q^{-1},t^{-1}},
    \qquad X(z_1\ldots z_k)\in \CV
\end{align}
It is clear that $\Omega(A * B)=\Omega(A) * \Omega(B)$ and that $\Omega$ is an involution. For any two tensors $A = A_{1\ldots k}(z_1\ldots z_k)$ and $B = B_{1\ldots l}(z_1\ldots z_l)$ in $\CV$ we define: 
\begin{multline}
        \label{eq:Gamma_prime}
    \Gamma'_{A,B}(z_1\ldots z_{k+l}) :=
    A_{1\ldots k}(z_{1}\ldots z_{k})
    \check R^\bullet_{\omega^{k}}(z_{k+1}\ldots  z_{k+l},q z_{1}\ldots q z_{k})\\
    B_{1\ldots l}(z_{k+1}\ldots z_{k+l}) 
    \check R_{\omega^l}(z_1\ldots z_{k+l})
\end{multline}
\begin{lem}
Let $A = A_{1\ldots k}(z_1\ldots z_k)\in\CV$ and $B = B_{1\ldots l}(z_1\ldots z_l)\in\CV$ and $\rho\in \mathfrak S_{k+l}$ be the longest element. 
The transform $\Omega$ satisfies:
\begin{align}\label{eq:Omega_props}
\Omega(\Gamma^-_{A,B}) = \Gamma'_{\Omega(A),\Omega(B)},
\qquad 
\Omega(\check R_{\sigma}) = \check R_{\rho \sigma \rho}
\end{align}
where $\Gamma^-$ is defined in \eqref{eq:Gamma_minus}.
\end{lem}
\begin{proof}
The first identity in \eqref{eq:Omega_props} follows by applying $\Omega$ to the definition of $\Gamma^-$ and using the second identity in \eqref{eq:Omega_props}. For $\sigma$ a simple  transposition the second identity in \eqref{eq:Omega_props} is a property of the $\check R$-matrix which can be verified directly. Using this and \eqref{eq:Rch-sigma} one verifies the second identity for a general $\sigma$.
\end{proof}
\begin{defn}\label{def:A prime}
Let $\CA'$ be the algebra of tensors $\{\Omega(X)\}_{X \in \CA^-}$ with the multiplication $*'$: 
\begin{align}
    \label{eq:A*'B-Rcheck}
    A*'B=\sum_{\sigma\in \mathfrak{S}_{k+l}/\mathfrak{S}_k\times \mathfrak{S}_l}\frac{1}{f_\sigma(z)}
    \check R_\sigma^{-1}
    \Gamma'_{A,B}(z_\sigma) \check R_\sigma
\end{align}
for any $A = A_{1\ldots k}(z_1\ldots z_k)$ and $B = B_{1\ldots l}(z_1\ldots z_l)$ in $\CA'$.
\end{defn}
The shuffle product $*'$ in \eqref{eq:A*'B-Rcheck} is related to the shuffle product $*$ of the algebra $\CA^-$ by the two properties in \eqref{eq:Omega_props}.
