\draw (0,0) -- (0,1);
\node[below] at (0,0) {$\scriptstyle w_1$};
\node[below] at (1,0) {$\scriptstyle w_l$};
\node[below] at (2,0) {$\scriptstyle z_{1}$};
\node[below] at (3,0) {$\scriptstyle z_{k}$};
\node at (0.5,0) {$\scriptstyle \ldots $};
\node at (2.5,0) {$\scriptstyle \ldots $};
\node[above] at (0,3) {$\scriptstyle z_1$};
\node[above] at (1,3) {$\scriptstyle z_k$};
\node[above] at (2,3) {$\scriptstyle w_{1}$};
\node[above] at (3,3) {$\scriptstyle w_{l}$};
\node at (0.5,3) {$\scriptstyle \ldots $};
\node at (2.5,3) {$\scriptstyle \ldots $};
\end{tikzpicture}
\end{align}
Thanks to the Yang--Baxter equation, the tensor $\check R_{\omega^l}$ satisfies:
\begin{align}\label{eq:R-omega_exchange1}
    \check{R}_{\omega^l}(z,w)(\ldots  z_{i+1}, z_{i}\ldots,w) \check R_i(z_{i+1}/z_i)&=
    \check R_{l+i}(z_{i+1}/z_i) \check{R}_{\omega^l}(\ldots z_{i},  z_{i+1}\ldots,w) \\
    \label{eq:R-omega_exchange2}
    \check{R}_{\omega^l}(z,w)(z,\ldots  w_{j+1}, w_{j}\ldots) \check R_{k+j}(w_{j+1}/w_j)&=
    \check R_{j}(w_{j+1}/w_j) \check{R}_{\omega^l}(z,\ldots w_{j},  w_{j+1}\ldots)
\end{align}
for $i=1\ldots k-1$ and $j=1\ldots l-1$.
\begin{defn}
    For any $X_{1\ldots k}(z_1\ldots z_k)\in\CV$ we define two  maps:
\begin{align}\label{eq:Psi}
\Psi\left [ X(z)\right]&: =  \Tr_{k+1\ldots 2k}
\left[
\check{R}_{\omega^k}(q z,z)
X_{k+1\ldots 2k}(z)
\right]\\
\label{eq:Psi_prime}
\Psi'\left [ X(z)\right]&: =  \Tr_{1\ldots k}
\left[
\check{R}^\bullet_{\omega^k}(z,q z)
X_{1\ldots k}(z)
\right]
\end{align}
\end{defn}
The graphical representation of \eqref{eq:Psi} follows from \eqref{eq:A_graph} and \eqref{eq:Z_graph}, and it may be drawn in the two ways below due to the cyclic property of the trace:
