The graphical representation of $\Psi'[X(z)]$ is analogous. These two maps have several important properties which are outlined in the following Lemma.
\begin{lem}\label{lem:prop_psi}
For $X(z_1\ldots z_k)\in\CV$ we have the relations:
\begin{align}\label{eq:Psi-exchange}
    &\check R_{\sigma}^{-1}
    \Psi\left[X(z_\sigma)\right]
    \check R_\sigma=
    \Psi\left[\check R_{\sigma}^{-1}X(z_\sigma)\check R_{\sigma} \right]
    \\
    \label{eq:Psi_prime-exchange}
    &\check R_{\sigma}^{-1}
    \Psi'\left[X(z_\sigma)\right]
    \check R_\sigma=
    \Psi'\left[\check R_{\sigma}^{-1}X(z_\sigma)\check R_{\sigma} \right]
\end{align}
If $X$ is a symmetric tensor then $\Psi[X(z)]$ and $\Psi'[X(z)]$ are also symmetric tensors:
\begin{align}
    \label{eq:Psi-symmetric}
    \check R_\sigma 
\Psi[X(z)] &= 
\Psi[X(z_{\sigma})]
\check R_\sigma\\
    \label{eq:Psi_prime-symmetric}
    \check R_\sigma 
\Psi'[X(z)] &= 
\Psi'[X(z_{\sigma})]
\check R_\sigma
\end{align}
\end{lem}
\begin{proof}
It is enough to prove \eqref{eq:Psi-exchange} for all simple transpositions, i.e.:
\begin{align}\label{eq:Psi-exchange_i}
\check R_{i}(z_{i+1}/z_i)^{-1}
    \Psi\left[X(\ldots z_{i+1},z_i\ldots)\right]
    \check R_i(z_{i+1}/z_i)=
    \Psi\left[\check R_{i}(z_{i+1}/z_i)^{-1}X(\ldots z_{i+1},z_i\ldots)\check R_{i}(z_{i+1}/z_i) \right]    
\end{align}
Consider \eqref{eq:R-omega_exchange1}  and \eqref{eq:R-omega_exchange2} with $l=k$, $j=i$ and $z_a\rightarrow qz_a$ and $w_a\rightarrow  z_a$, for $a=1\ldots k$. These two equations can be combined to produce the following identity:
\begin{multline}\label{eq:R_omega_exchange_3}
\check R_i(z_{i+1}/z_i)^{-1} \check R_{\omega^k}(\ldots qz_{i+1},q z_i\ldots,\ldots z_{i+1},z_i\ldots) \check R_i(z_{i+1}/z_i)\\
=
\check R_{k+i}(z_{i+1}/z_i) \check R_{\omega^k}(qz,z) \check R_{k+i}(z_{i+1}/z_i)^{-1}
\end{multline}
Plugging the formula above in the left hand side of \eqref{eq:Psi-exchange_i} (and using the definition of $\Psi$ in \eqref{eq:Psi}, the identity \eqref{eq:R_omega_exchange_3} and the cyclicity of the trace) gives:
\begin{align*}
&\check R_{i}(z_{i+1}/z_i)^{-1}
    \Psi\left[X(\ldots z_{i+1},z_i\ldots)\right]
    \check R_i(z_{i+1}/z_i)\\
    =
&
   \Tr_{k+1\ldots 2k}
\left[
\check R_{k+i}(z_{i+1}/z_i) \check R_{\omega^k}(qz,z) \check R_{k+i}(z_{i+1}/z_i)^{-1}
X_{k+1\ldots 2k}(\ldots z_{i+1},z_i\ldots)
\right]\\
   =
&
   \Tr_{k+1\ldots 2k}
\left[ \check R_{\omega^k}(qz,z) \check R_{k+i}(z_{i+1}/z_i)^{-1}
X_{k+1\ldots 2k}(\ldots z_{i+1},z_i\ldots)
\check R_{k+i}(z_{i+1}/z_i)
\right]\\
=
    &\Psi\left[\check R_{i}(z_{i+1}/z_i)^{-1}X(\ldots z_{i+1},z_i\ldots)\check R_{i}(z_{i+1}/z_i) \right]    
\end{align*}
This proves \eqref{eq:Psi-exchange_i}, which implies \eqref{eq:Psi-exchange}. If $X(z)$ is a symmetric tensor then \eqref{eq:Psi-symmetric} holds by \eqref{eq:Psi-exchange} and \eqref{eqn:symmetric tensor}. The proofs of \eqref{eq:Psi_prime-exchange} and \eqref{eq:Psi_prime-symmetric} are analogous.
\end{proof}



\subsection{A shuffle algebras anti-isomorphism}
Here we show that $\Psi$ and $\Psi'$ are anti-isomorphisms and are inverses of each other.
\begin{prop}
For any tensors $A(z_1\ldots z_l), B(z_1\ldots z_k)\in \CV$ we have:
\begin{align}\label{eq:Gamma-Psi}
&\Gamma^+_{\Psi[A],\Psi[B]}   = \Psi[\Gamma'_{B,A}]\\
\label{eq:Gamma-Psi-prime}
&\Gamma'_{\Psi'[A],\Psi'[B]}   = \Psi'[\Gamma^+_{B,A}]
\end{align}
Additionally we have:
\begin{align}
    \label{eq:Psi-inv}
    \Psi[\Psi'[A(z)]] = \Psi'[\Psi[A(z)]] = A(z)
\end{align}
\end{prop}
