\begin{cor}\label{cor:psi iso}
There exists an anti-isomorphism of shuffle algebras $\Psi : \CA' \xrightarrow{\sim} \CA^+$ given by:
\begin{align}\label{eq:psi-iso}
     X \mapsto \Psi[X]
\end{align}
with inverse $\Psi'$.
\end{cor}
\begin{proof}
Let $A(z_1\ldots z_l), B(z_1\ldots z_k)\in \CA'$. We apply $\Psi$ to the shuffle product $*'$:
\begin{multline}\label{eq:proof-psi-iso}
        \Psi[A*'B]=\sum_{\sigma\in \mathfrak S_{k+l}/\mathfrak S_l\times \mathfrak S_k}
    \Psi[\check R_\sigma^{-1}
    \Gamma'_{A,B}(z_\sigma) \check R_\sigma]
    =\sum_{\sigma\in \mathfrak S_{k+l}/\mathfrak S_l\times \mathfrak S_k}
    \check R_\sigma^{-1}\Psi[
    \Gamma'_{A,B}(z_\sigma) ]\check R_\sigma\\
    =\sum_{\sigma\in \mathfrak S_{k+l}/\mathfrak S_l\times \mathfrak S_k}
    \check R_\sigma^{-1}
    \Gamma^+_{\Psi[B],\Psi[A]}(z_\sigma)
    \check R_\sigma
    =\Psi[B]*\Psi[A]
\end{multline}
where we used \eqref{eq:A*'B-Rcheck}, \eqref{eq:Psi-exchange}, \eqref{eq:Gamma-Psi} and \eqref{eq:A*B-Rcheck}, respectively. This implies that $\Psi$ and $\Psi'$ give mutually inverse algebra anti-homomorphisms between $\CV$ and $\CV'$. The map $\Psi$ sends elements of $\text{End}(V)(z_1^{\pm 1})$ to elements of $\text{End}(V)(z_1^{\pm 1})$ and therefore by Proposition \ref{prop:gen} this implies that $\Psi$ sends $\CA'$ to $\CA^+$.
\end{proof}


\subsection{Shuffle algebras' anti-homomorphisms}\label{sec:Psi tilde}
In this section we introduce linear maps $\widetilde \Psi$ which arise from composing $\Psi$ with projections. These linear maps become anti-homomorphisms under certain conditions.

Recall the vector space $V \cong \mathbb C^{n+m}$ and consider two vectors spaces $V'\cong \mathbb C^{n'+m'}$ and $V''\cong \mathbb C^{n''+m''}$ such that $V$ and $V'$ are two coordinate subspaces of $V''$. Let $\mathcal{I}'$ and $\mathcal{I}''$ denote the label sets of the basis vectors of $V'$ and $V''$, respectively. Fix two projections $\pi$ and $\pi'$ and embeddings $\iota$ and $\iota'$:
\begin{align}\label{eq:proj-emb}
\pi:V''\to V, 
\qquad \pi':V''\to V',
\qquad
\iota:V\to V'', 
\qquad 
\iota':V'\to V''
\end{align}
such that $\pi$ removes $n''-n$ standard basis vectors with bosonic grading and $m''-m$ standard basis vectors with fermionic grading and similarly $\pi'$ removes $n''-n'$ standard basis vectors with bosonic grading and $m''-m'$ standard basis vectors with fermionic grading. The embeddings $\iota$ and $\iota'$ act as inverses on the corresponding subspaces. The maps $\pi,\pi',\iota$ and $\iota'$ can be reused to denote the maps of the labeling sets by replacing $V$ with $\mathcal{I}$ in \eqref{eq:proj-emb}. In particular, the maps $\pi(\mathcal{I}'')$ and $\pi'(\mathcal{I}'')$ are order preserving and we have $\iota(\mathcal{I})\cup \iota'(\mathcal{I}')\subseteq\mathcal{I}''$.

Let $R^{(V')}$ and $R^{(V'')}$ be the $R$-matrices of $U_t(\dot{\fgl}_{n'|m'})$ and $U_t(\dot{\fgl}_{n''|m''})$ acting on $V'\otimes V'$ and $V''\otimes V''$, respectively. Let $\epsilon'_i$, with $i\in\mathcal{I}'$, and $\epsilon_i''$, with $i\in \mathcal{I}''$, be the gradings of the standard basis vectors of $V'$ and $V''$, respectively. We can write:
\begin{align}
    \label{eq:projections}
    (\pi\otimes \pi)R^{(V'')}(z)(\iota\otimes \iota) = R(z),
    \qquad
    (\pi'\otimes \pi')R^{(V'')}(z)(\iota'\otimes \iota') = R^{(V')}(z)
\end{align}
where we require that $\epsilon''_{\iota(i)}=\epsilon_i$ and $\epsilon''_{\iota'(i)}=\epsilon'_i$.
The same relations hold for $\check R$. Let: 
\begin{equation}
\label{eqn:big space primed}
\CV' = \bigoplus_{k=0}^{\infty} \text{End}_{\BC(q,t)}(V'^{\otimes k}) (z_1 \ldots z_k)
,
\qquad
\CV'' = \bigoplus_{k=0}^{\infty} \text{End}_{\BC(q,t)}(V''^{\otimes k}) (z_1 \ldots z_k)
\end{equation}
Consider two tensors $A = A_{1\ldots k}(z_1\ldots z_k)\in \CV''$ and $B = B_{1\ldots l}(z_1\ldots z_l)\in \CV''$ which preserve the coordinate subspaces $V^{\otimes k}$ and $V^{\otimes l}$, respectively. Using \eqref{eq:projections} one can show that:
\begin{align}
    \label{eq:proj hom}
    \pi^{\otimes (k+l)}\left( A*''B \right)\iota^{\otimes (k+l)}=
    \left(\pi^{\otimes k} A \iota^{\otimes k}\right) *\left(\pi^{\otimes l} B \iota^{\otimes l}\right)
\end{align}
where $*''$ denotes the shuffle product \eqref{eqn:shuffle product} with $R$ replaced by $R^{(V'')}$. Let us stress that the space $V''$ is used as an auxiliary space and the gradation of the standard basis vectors of $V''$ does not need to be ordered as $\{1\ldots 1,-1\ldots -1\}$. 
\begin{defn}\label{defn:tilde Psi}
For $X(z)=X_{1\ldots k}(z_1\ldots z_k)\in \CV'$ we define the map:
\begin{align}\label{eq:Psi tilde}
    \widetilde \Psi\left [ X(z)\right]=  \pi^{\otimes k}\left(
    \Tr_{k+1\ldots 2k}
\left[
\left(\check{R}^{(V'')}_{\omega^k}(q z,z)\right)
\left( \id_{V''}^{\otimes k} \otimes \left(
\iota'^{\otimes k} X(z)\pi'^{\otimes k}\right)\right)
\right]\right)\iota^{\otimes k}
\end{align}
where the traces are taken over $k$ copies of $V''$.
\end{defn}
In \eqref{eq:Psi tilde}  the non-trivial contribution from the trace only comes from the subspaces $V'$. An equivalent definition can be given by writing:
\begin{align}\label{eq:Psi tilde x}
    \widetilde \Psi\left [ X(z)\right]: =  \Tr_{k+1\ldots 2k}
\left[
\left(\pi^{\otimes k}\otimes \pi'^{\otimes k}\right)\left(\check{R}^{(V'')}_{\omega^k}(q z,z)\right)
\left(\iota^{\otimes k}\otimes \iota'^{\otimes k}\right)
X_{k+1\ldots 2k}(z)
\right]\in \CV
\end{align}
where the traces are taken over $k$ copies of  $V'$. The graphical formula of \eqref{eq:Psi tilde} is:
\begin{align}\label{eq:Psi a graphics}
