    using namespace fst;
    StdVectorFst PhiAutomatonCompose() {
      typedef PhiMatcher<Matcher<StdVectorFst>> PM;
      SymbolTable syms;
      syms.AddSymbol("<epsilon>");
      syms.AddSymbol("<phi>");
      syms.AddSymbol("a"); syms.AddSymbol("b"); syms.AddSymbol("c");

      StdVectorFst left;
      left.AddStates(2);
      left.SetStart(0);
      left.SetFinal(1);
      left.AddArc(0, StdArc(syms.Find("a"), syms.Find("a"), 1));

      StdVectorFst right;
      right.AddStates(3);
      right.SetStart(0);
      right.SetFinal(2);
