\section{Preliminaries}\label{sec:2}
\setcounter{equation}{0}
In this section, we review basic materials and previous results for the KCS model, and then we delineate main results on the uniqueness of weak solution and emergence of weak flocking whose proofs can be provided in later sections.  

\subsection{Preparatory materials} \label{sec:2.1}
In this subsection, we recall all necessary materials to be used in later sections. First, we recall the concept of weak solution to \eqref{A-1}.
\begin{definition}\label{D2.1}
\emph{(Weak solution)}
For $\tau  \in (0,\infty]$, let $f\in {\mathcal C}([0, \tau);  L^1(\mathbb{R}^{2d}))$ be a  nonnegative weak solution to  \eqref{A-1} with the initial datum $f^{\mathrm{in}} \in (L^1 \cap L_+^{\infty})(\mathbb{R}^{2d})$ if the following relations hold:
	\begin{enumerate}
		\item
		$f$ is weakly continuous in $t$:~$\forall~\psi \in {\mathcal C}_c^1(\mathbb{R}^{2d})$, 
		\[
		t \quad \mapsto \quad \int_{\mathbb{R}^{2d}}\psi f \di z \quad\text{is continuous}.
		\]
		\item	
		$f$ satisfies \eqref{A-1} in weak sense:~$ \forall~\zeta \in {\mathcal C}_c^1([0, \tau) \times\mathbb{R}^{2d}),$
\[ \int_{\mathbb{R}^{2d}}\zeta(t, z) f(t, z) \di z =  \int_{\mathbb{R}^{2d}}\zeta(0,z) f^{\mathrm{in}}(z) \di z + \int_0^{\tau} \int_{\mathbb{R}^{2d}}(\partial_s\zeta+v\cdot \nabla_x \zeta +\nabla_v\zeta \cdot L[f])f(s, z) \di z \di s.\]
	\end{enumerate}	
\end{definition}
\vspace{0.2cm}

Next, we recall the concept of $p$-Wasserstein space. Let $\mu$ and $\nu$ be probability measures on $\bbr^{d}$. Then, for  all nonnegative integrable functions $\psi_1$, $\psi_2$ defined on $\mathbb{R}^{d}$, we define a probability measure $\pi \in {\mathcal P}(\bbr^{d} \times \bbr^d)$ with marginals $\mu$ and $\nu$ as follows.
	\begin{equation*}\label{f3.1}
		\int_{\mathbb{R}^{d}\times\mathbb{R}^{d}}(\psi_1(x)+\psi_2(x_{\star}))\pi(\di x,\di x_{\star})=\int_{\mathbb{R}^{d}}\psi_1(x) \mu(x)+\int_{\mathbb{R}^{d}}\psi_2(x_{\star}) \nu(\di x_{\star}).
	\end{equation*}
	We denote $\Pi(\mu, \nu)$ by the set of probability measures on $\bbr^d \times \bbr^d$ with marginals $\mu$ and $\nu$:
	\[ \mu(\di x) = \int_{\bbr^d} \pi(\di x, \di x_\star) \di x_\star, \quad  \nu(\di x_\star) = \int_{\bbr^d} \pi(\di x, \di x_\star) \di x. \]

Next, we recall basic properties of probability measures in the following definition. 
		\begin{definition}\label{D2.2}
		\emph{($p$-Wasserstein space)}
	 For any $\mu, \nu \in \mathcal{P}(\mathbb{R}^{d})$,  the Wasserstein distance of order $p$ between $\mu$ and $\nu$ (or $p$-Wasserstein distance between $\mu$ and $\nu$) is defined by the formula:
	\begin{equation*}
		W_p(\mu, \nu):=\inf\left\{\left(\int_{\mathbb{R}^{d}\times\mathbb{R}^{d}} |x-x_{\star}|^p\pi(\di x,\di x_{\star})\right)^\frac{1}{p}:\pi\in\Pi(\mu, \nu)\right\},
	\end{equation*}
	where $\Pi(\mu,\nu)$ is the set of all probability measures on $\mathbb{R}^{d}\times\mathbb{R}^{d}$ with marginals $\mu$ and $\nu$ in ${\mathcal P}(\bbr^d)$, respectively. 	
\end{definition}
\begin{remark}
In order to avoid the difficulty that $W_p$ may take the value $+\infty$, we consider $W_m$ on $\mathcal{P}_m(\mathbb{R}^{d})$ for a suitable $m \in {\mathbb N}$.
\end{remark}
In the following lemma, we provide the characterization of the convergence in $W_p$.
\begin{lemma}{\rm \cite{k8}} \label{le2.5}
The following statements hold. 
\begin{enumerate}
\item
The metric space $(\mathcal{P}_p(\mathbb{R}^{d}), W_p)$ is complete.
\vspace{0.1cm}
\item
 Let $(\mu_k)_{k\in\mathbb{N}}$ be a sequence of probability measures in $\mathcal{P}_p(\mathbb{R}^{d})$ and let $\mu$ be another element of $\mathcal{P}_p(\mathbb{R}^{d})$.  Then, the following statements hold.
 \vspace{0.1cm}
 \begin{enumerate}
 \item
  The sequence $(\mu_k)_{k\in\mathbb{N}}$ has uniformly integrable $p$-th moments if for some $x_0\in\mathbb{R}^d$$:$
	\begin{equation*}
		\lim\limits_{r\rightarrow\infty}\int_{\mathbb{R}^d\setminus B_r(x_0)} |x-x_0|^p \mu_k(\di x)=0\quad \text{uniformly with respect to }k\in\mathbb{N},
	\end{equation*}
where $B_r(x_0)$ is the open ball with a center $x_0$ and a radius $r$. 	
\vspace{0.1cm}
\item	
The sequence $(\mu_k)$ converge weakly to $\mu$ if the following relation holds:
	\[
		\lim\limits_{k\rightarrow\infty}\int_{\mathbb{R}^d}\psi(x) \mu_k(\di x)=\int_{\mathbb{R}^d}\psi(x) \mu(\di x), \quad \forall~\psi \in {\mathcal C}_b(\mathbb{R}^d).
	\]
\item
Equivalent relation for the convergence in $W_p$:
	\begin{equation*}
	\lim\limits_{k\rightarrow\infty}W_p(\mu_k, \mu)=0  \quad \Longleftrightarrow \quad
		 \left\{\begin{aligned}
			&\mu_k \quad\mbox{converge weakly to}\quad \mu \quad \mbox{and} \\
			&(\mu_k)_{k\in\mathbb{N}} \quad \mbox{has uniformly integrable p-th moments.}
		\end{aligned}\right.
	\end{equation*}
\end{enumerate}	
\end{enumerate}	
\end{lemma}
\begin{remark}\label{D2.3}
	\emph{(Support of measure and push-forward measure)} Let $\mu$ be a Borel measure on $\mathbb{R}^{2d}$. 
	\begin{enumerate}
		\item
		The support of  $\mu$ is the closure of the set $\{(x,v)\in\mathbb{R}^{2d}:~\mu(B_r(x,v))>0, \forall\ r>0\}$, and we denote it by $\mbox{\rm spt}(\mu)$. 
		\vspace{0.2cm}
		\item
		Let $T: \mathbb{R}^{d}\rightarrow\mathbb{R}^{d}$ be a measurable map. Then, the push-forward measure of $\mu$ by $T$ is the measure $T\# \mu$ defined by $T\# \mu(B)=\mu(T^{-1}(B))$, for all Borel set $B \subset\mathbb{R}^{d}$.
	\end{enumerate}
\end{remark}

\vspace{0.2cm}

Next, we describe a particle trajectory associated with the KCS model. In literature, particle trajectory is also called "bi-characteristics or simply characteristics". For $z = (x, v) \in {\mathbb R}^d \times {\mathbb R}^d$, we define a particle trajectory 
\[ (X(t), V(t)) : = (X(t,0,z), V(t,0,z)) \]
as a unique solution to the following Cauchy problem:
\begin{equation} \label{B-1}
	\begin{cases}
		\displaystyle \dot X(t)=V(t), \quad t > 0,   \\
		\displaystyle \dot V(t)=L[f](t,X(t),V(t)), \\
		\displaystyle X(0)=x, \quad  V(0)=v,
	\end{cases}
\end{equation}
where the linear velocity alignment force along the particle trajectory is given by the following relation:
\begin{equation} \label{B-1-1}
 L[f](t,X(t),V(t))=-\kappa\int_{\mathbb{R}^{2d}} \phi( |X(t) -x_{\star}|) \left(V(t)-v_{\star}\right)  f(t, x_{\star}, v_{\star}) \di x \di v.
\end{equation}
Note that $L[f]$ in \eqref{B-1-1} is continuous in $t$ and Lipschitz continuous in state variables $(X, V)$, thus the standard Cauchy-Lipschitz theory provides a local well-posedness of  particle trajectories near $t = 0$. Moreover,
 the vector field generated by the right-hand side of \eqref{B-1} is locally bounded in $X$ and sub-linear in $V$, hence particle trajectory is globally well-defined. Thus the particle trajectory map $( X(t,0,x,v), V(t,0,x,v))$ is a well-defined homeomorphism for each fixed time $t$ and a ${\mathcal C}^1$-function of time $t$, and the weak solution $f$ to \eqref{A-1} is given by the push-forward of the initial measure $\mu^{\mathrm{in}}(\di x, \di v) = f^{\mathrm{in}}(x,v) \di x \di v$:
\[ f(t,z)=(X(t,0,z),V(t,0,z))\#f^{\mathrm{in}}, \]
or equivalently,
\begin{equation} \label{B-1-2}
	\int_{\mathbb{R}^{2d}}\psi(z) f(t, z) \di z =\int_{\mathbb{R}^{2d}}\psi(X(t,0,z),V(t,0,z))f^{\mathrm{in}}(z) \di z, \quad \forall~\psi\in {\mathcal C}_b^1(\mathbb{R}^{2d}).
\end{equation}
As a direct application of \eqref{B-1-2}, we have the following elementary estimates. 
\begin{lemma} \label{L2.2}
Let $f = f(t,z)$ be a smooth solution to \eqref{A-1} with sufficiently fast decay at infinite in phase space, and let $(X(t), V(t))$ be an associated particle trajectory defined in \eqref{B-1}. Then, the following estimates hold. 
\begin{align*}
\begin{aligned}
& (i)~  \int_{\mathbb{R}^{2d}}  f(t,z) \di z = \int_{\mathbb{R}^{2d}}  f^{\mathrm{in}}(z) \di z, \quad \int_{\mathbb{R}^{2d}}  v f(t,z) \di z = \int_{\mathbb{R}^{2d}} v f^{\mathrm{in}}(z) \di z. \\
& (ii)~  \int_{\mathbb{R}^{2d}} v f(t,z) \di z = \int_{\mathbb{R}^{2d}} V(t) f^{\mathrm{in}}(z) \di z. \\
& (iii)~  \int_{\mathbb{R}^{2d}} |v|^D f(t,z) \di z = \int_{\mathbb{R}^{2d}} |V(t)|^D f^{\mathrm{in}}(z) \di z  \quad \mbox{for}~D \geq 1. \\
& (iv)~ \int_{\mathbb{R}^{2d}} | v- v_c(t) |^2f(t,z) \di z = \int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z.
\end{aligned}
\end{align*}
\end{lemma}
\begin{proof}
\noindent (i)~The first relation follows from the direct integration of $\eqref{A-1}_1$ in phase space $\bbr^{2d}$ using the sufficient fast decay conditions. For the second estimate, we multiply $v$ to $\eqref{A-1}_1$ to see
\[
 \partial_t (v f) + \nabla_x \cdot (v \otimes v f) + \nabla_v \cdot (v \otimes L[f]f)= d L[f] f.
\]
We integrate the above relation over $\bbr^{2d}$ using the suitable decay conditions at infinity to get the desired conservation of momentum:
\begin{align*}
\begin{aligned}
\frac{\di}{\di t} \int_{\bbr^{2d}} v f \di z & =d  \int_{\bbr^{2d}}  L[f] f \di z_* \di z \\
&= -d \kappa \int_{\bbr^{4d}} \phi(|x - x_*|) (v-v_*)  f(t, z) f(t., z_*) \di z_* \di z \\
& = d \kappa \int_{\bbr^{4d}} \phi(|x - x_*|) (v-v_*)  f(t, z) f(t., z_*) \di z_* \di z \\
& = 0. 
\end{aligned}
\end{align*}
Here we use the variable exchange transformation:
\[ (x, v) \quad \Longleftrightarrow \quad (x_*, v_*). \]

\noindent (ii) - (iii):~We can take smooth cut-off functions of $v, |v|^D$ as a test function $\psi$ and use \eqref{B-1-2} to see the desired estimates (see Lemma \ref{L3.1} for the smooth cut-off fuction). In particular, 
\[  \int_{\mathbb{R}^{2d}} v f(t,z) \di z = \int_{\mathbb{R}^{2d}} V(t) f^{\mathrm{in}}(z) \di z, \quad \int_{\mathbb{R}^{2d}} |v|^2 f(t,z) \di z = \int_{\mathbb{R}^{2d}} |V(t)|^2 f^{\mathrm{in}}(z) \di z. \]
(iv) We use all the estimates in (i) - (iii) to see
\begin{align*}
\begin{aligned} 
&  \int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2 f^{\mathrm{in}}(z) \di z \\
& \hspace{1cm} =  \int_{\mathbb{R}^{2d}} |V(t)|^2  f^{\mathrm{in}}(z) \di z - 2 \Big \langle \int_{\bbr^{2d}} V(t) f^{\mathrm{in}}(z) \di z, v_c^{\mathrm{in}} \Big \rangle + |v_c^{\mathrm{in}}|^2   \int_{\bbr^{2d}}  f^{\mathrm{in}}(z) \di z \\
&  \hspace{1cm}=  \int_{\mathbb{R}^{2d}} |v|^2 f(t,z) \di z -2 \Big \langle  \int_{\mathbb{R}^{2d}} v f(t,z) \di z, v_c^{\mathrm{in}}\Big \rangle   + |v_c^{\mathrm{in}}|^2  \\
&  \hspace{1cm}= \int_{\mathbb{R}^{2d}} | v- v_c^{\mathrm{in}} |^2f(t,z) \di z  =  \int_{\mathbb{R}^{2d}} | v- v_c(t)|^2 f(t,z) \di z.
\end{aligned}
\end{align*}
\end{proof}
\begin{remark}
By the result (i) of Lemma \ref{L2.2}, we may assume that
\[ \int_{\bbr^{2d}} f(t,z) \di z = 1, \quad \forall~t \geq 0. \]
\end{remark}





\subsection{Previous results} \label{sec:2.2}
In this subsection, we summarize the previous results of  the KCS model in the following two propositions. 
\begin{proposition} 
\emph{\cite{k4,k1,w2,w6}} \label{le:2.3}
For $\tau \in (0, \infty]$, suppose that the initial data $f^{\mathrm{in}},g^{\mathrm{in}}\in (L^1 \cap L^{\infty}_+)(\mathbb{R}^{2d})$ have compact support in velocity variable, i.e., there exists a positive constant $P_\infty$ such that 
\begin{equation*}\label{eq:4.312}
	P_\infty :=\max\left\{\sup\limits_{(x,v)\in{\rm spt}(f^{\mathrm{in}})} |v|,\sup\limits_{(x,v)\in{\rm spt}(g^{\mathrm{in}})} |v|\right\}<\infty.
\end{equation*}
Then, there exists global unique nonnegative weak solutions $f,g\in L^{\infty}([0, \infty), L^1(\mathbb{R}^{2d}))$ to \eqref{A-1} with initial data $f^{\mathrm{in}}$ and $g^{\mathrm{in}}$, respectively, with the following properties:
\begin{enumerate}
	\item 
	(Propagation of compact supports in velocity variable): 
	\begin{equation}\label{eqt4.40}
		\sup\limits_{(x,v)\in{\rm spt}(f(t))} |v|\le P_\infty ,  \quad  \sup\limits_{(x,v)\in{\rm spt}(g(t))} |v|\le P_\infty, \quad t \in [0, \infty).
	\end{equation} 
	\item	
	(Conservation of total mass and its average velocity):
	\[ \frac{\di}{\di t}\int_{\mathbb{R}^{2d}}f(t, z) \di z=0, \quad  \frac{\di}{\di t}\int_{\mathbb{R}^{2d}}vf(t, z) \di z =0, \quad t \in [0, \infty). 
	\]
	\item
	(Finite-in-time stability in $W_p$):~ there exists a positive constant $C(\tau) = C(P_\infty, \beta, p, \tau)$ such that
	\begin{equation*}
		W_p(f(t),g(t))\le C(\tau) W_p(f^{\mathrm{in}},g^{\mathrm{in}}), \quad \forall~t\in[0, \tau),
	\end{equation*}
	where $\beta$ is the spatial decay of the communication weight $\phi$ (see \eqref{A-0-1}).
	\vspace{0.1cm}
\item	
(Weak mono-cluster flocking dynamics):~for $\beta\in [0,1]$, if the initial probability density function $f^{\mathrm{in}}$ of the initial measure $\mu^{\mathrm{in}}(\di x, \di v) = f^{\mathrm{in}} \di x \di v$ has an exponential decay $(\alpha > 0)$ or a polynomial decay with ($D>\frac{7}{1-\beta}$) in space variable $x$, and the coupling strength $\kappa$ is sufficiently large, then weak flocking \eqref{A-5} emerges asymptotically. 
\end{enumerate}	
\end{proposition}
\vspace{0.2cm}

\noindent Next,  we state the existence of weak solution to \eqref{A-1}.
\begin{proposition}  \label{P2.2}
	\emph{\cite{kinetic3}} \label{pro:2.4}
	Suppose that the initial probability density function \( f^{\mathrm{in}} \) satisfies
	\[
	f^{\mathrm{in}} \in (L^1 \cap L^{\infty}_+)(\mathbb{R}^{2d}), \quad (|x|^2 + |v|^2)f^{\mathrm{in}} \in L^1(\mathbb{R}^{2d}).
	\]
	Then, there exists a weak solution $f \in {\mathcal C}([0, \tau); L^1(\mathbb{R}^{2d})) \cap L_+^\infty([0, \tau) \times \mathbb{R}^{2d})$  to \eqref{A-1} such that
	\[
	( |x|^2 + |v|^2)f \in L^1(\mathbb{R}^{2d}), \quad 	\int_{\mathbb{R}^{2d}}f(t, z) \di z =\int_{\mathbb{R}^{2d}}f^{\mathrm{in}}(z) \di z, \quad t > 0.
	\]
\end{proposition}
\begin{remark} Below, we comment on the results of Proposition \ref{P2.2}. 
\begin{enumerate}
\item
Thanks to Proposition \ref{pro:2.4}, without loss of generality, we may assume 
	\[ \|f(t)\|_{1}\equiv1 \quad \forall~t \in [0, \tau). \]
\item	
By the same argument as in the proof of Proposition \ref{P2.2}, if $f^{\mathrm{in}}$ satisfies
	\[
	f^{\mathrm{in}} \in (L^1 \cap L_+^\infty)(\mathbb{R}^{2d}), \quad (|x|^D + |v|^D)f^{\mathrm{in}} \in L^1(\mathbb{R}^{2d}),
	\]
		then, there exists a weak solution $f \in {\mathcal C}([0, \tau); L^1(\mathbb{R}^{2d})) \cap L_+^\infty([0, \tau) \times \mathbb{R}^{2d})$  to \eqref{A-1} such that
	\[
	( |x|^D + |v|^D)f \in L^1(\mathbb{R}^{2d}), \quad 	\int_{\mathbb{R}^{2d}}f(t, z) \di z =\int_{\mathbb{R}^{2d}}f^{\mathrm{in}}(z) \di z, \quad t > 0.
	\]
\end{enumerate}	
\end{remark}
\subsection{Main results} \label{sec:2.3}
In this subsection, we discuss our main results on the uniqueness of weak solution and weak flocking behaviors of weak solutions. \newline

The first main result is concerned with the uniqueness property of a weak solution to \eqref{A-1} in which existence is already guaranteed in Proposition \ref{P2.2}.
\begin{theorem} \label{T2.1}
\emph{(Uniqueness of weak solution)}
Suppose that the initial datum \( f^{\mathrm{in}} \) satisfies
\[
f^{\mathrm{in}} \in (L^1 \cap L_+^{\infty})(\mathbb{R}^{2d}) \quad \mbox{and} \quad  (|x|^2 + |v|^2)f^{\mathrm{in}} \in L^1(\mathbb{R}^{2d}).
\]
Then, a weak solution to \eqref{A-1}  is unique.
\end{theorem}
\begin{proof}  Since the proof is very lengthy, we postpone the proof in Section \ref{sec:3.2}.
\end{proof}
\begin{remark}
Different from Chen and Yin \cite{k6}, who used an energy method to obtain the uniqueness of the solution when $\beta>1$, we mainly use characteristic flow estimation and uniform boundedness of second velocity moment when $\beta\le1$.
\end{remark}
Next, the second result deals with the derivation of weak flocking properties. For this, we introduce two types of probability distribution functions with decay conditions at infinity in phase space.

\begin{definition} \label{D2.4}
Let $h = h(x, v)$ be a nonnegative and integrable function on $\mathbb{R}^{2d}$. 
\begin{enumerate}
	\item
	$h$ belongs to a class of exponentially decaying distributions in phase space, if there exists  $\alpha > 0$ such that 
	\[
	\int_{\mathbb{R}^{2d}} e^{\alpha(|x|+|v|)} h(z) \di z < \infty.
	\]
	\vspace{0.2cm}
	\item
	$h$ belongs to a class of polynomially decaying distributions in phase space, if there exists $D > 0$ such that 
	\[
	\int_{\mathbb{R}^{2d}} (|x|^D+ |v|^D) h(z) \di z < \infty.
	\]
\end{enumerate}
\end{definition}
\begin{remark} It is easy to see that if $h$ belongs to  a class of exponentially decaying distributions, then it also belongs to a class of polynomially decaying distributions.
\end{remark}





\begin{theorem}\label{T2.2}
\emph{(Weak mono-cluster flocking)} 
Let $f$ be a global weak solution to \eqref{A-1} with the initial datum $f^{\mathrm{in}}$. Then, the following assertions hold. 
\begin{enumerate}
\item
If $\beta,~\kappa,~\gamma, D$ and $f^{\mathrm{in}}$ satisfy 
\begin{align}
\begin{aligned} \label{NN-1}
& 0 \leq \beta < 1, \quad \kappa> 0, \quad  \gamma > 1, \quad      D > \max \Big \{ \frac{2(3-\beta \gamma)}{\gamma -1},~4  \Big \}, \\
&  {\mathcal M}_p(f^{\mathrm{in}}, D) :=  \int_{\mathbb{R}^{2d}} (|x|^D+ |v|^D) f^{\mathrm{in}}(z) \di z < \infty, 
\end{aligned}
\end{align}
then weak mono-cluster flocking \eqref{A-5} emerges algebraically slowly:
\[
\int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \leq  {\mathcal O}(1)  (1+ t)^{1-(\frac{D}{2}(\gamma-1)+ \beta\gamma)} \quad \mbox{as $t \to \infty$}. 
\]
Here, $\gamma$ is a free parameter to be determined in the proof (see Section \ref{sec:4}).
\vspace{0.1cm}
\item
If $\beta, ~\kappa,~\alpha$ and $f^{\mathrm{in}}$ satisfy
\[    0 \leq \beta < 1, \quad \kappa >0,  \quad  \alpha > 0, \quad  {\mathcal M}_e(f^{\mathrm{in}}, \alpha) :=  \int_{\mathbb{R}^{2d}} e^{\alpha \left(| x|+| v |\right)} f^{\mathrm{in}}(z) \di z  < \infty,\]
then weak mono-cluster flocking \eqref{A-5} emerges asymptotically. 
\vspace{0.1cm}
\item
If $\beta,~\kappa$ and $f^{\mathrm{in}}$ satisfy
\[ \beta = 1, \quad \kappa >1, \quad {\mathcal M}_e(f^{\mathrm{in}}, \alpha) :=  \int_{\mathbb{R}^{2d}} e^{\alpha | x|} f^{\mathrm{in}}(z) \di z  < \infty,\quad \sup\limits_{(x,v)\in{\rm spt}(f^{\mathrm{in}})} |v|\le P_\infty, \]
then weak mono-cluster flocking \eqref{A-5} emerges asymptotically.
\end{enumerate}
\end{theorem}
\begin{proof} 
Since the proofs for the above assertions are very lengthy, we leave their proofs in Section \ref{sec:4}. However, for readers' convenience, we briefly outline a proof strategy for the first assertion in several steps. \newline

Suppose that system parameters and initial datum satisfy \eqref{NN-1}. 
\begin{itemize}
\item
Step A:~we show  that the growth of $D$-th spatial moment is at most $\mathcal{O}\left((1+t)^D\right).$ (see Lemma \ref{L3.1})
\vspace{0.1cm}
\item
Step B:~we show that the mass over the monotonically decreasing set $ \Omega(t) := (B_{R_x(t)})^c \times \bbr^d$ with $R_x(t):=  C_1(1 + t)^{\gamma}$, 
has a decay of order $\mathcal{O}(1) (1+t)^{-D(\gamma-1)}.$  See Corollary \ref{C3.1}.
\vspace{0.1cm}
\item
Step C:~we use the relation (iv) in Lemma \ref{L2.2}
to derive the Grönwall type differential inequality:
\begin{align*}
\begin{aligned}
& \dfrac{\di}{\di t} \int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z  \\
& \hspace{0.5cm} \leq - \kappa|\mathcal{O}(1)| (1+t)^{-\beta\gamma} \int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z +\mathcal{O}(1) \kappa (1+t )^{-(\frac{D}{2}(\gamma-1)+ \beta\gamma)}.
		\end{aligned}
	\end{align*}
See Section \ref{sec:4.1} for details.	
\vspace{0.1cm}
\item
Step D:~we use a variant of the Grönwall type lemma to derive velocity alignment:
\[  \int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \lesssim  {\mathcal O}(1)  (1+ t)^{1-(\frac{D}{2}(\gamma-1)+ \beta\gamma)}.     \]
\vspace{0.1cm}
\item
Step E:~ we use the relation:
\[ 	\quad\dfrac{\di}{\di t}\left(\int_{\mathbb{R}^{2d}} |X(t)-v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}\le\Big(\int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \Big)^{\frac{1}{2}}  \]
to derive the spatial cohesion:
\[
\int_{\mathbb{R}^{2d}} |X(t)-v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \leq {\mathcal O}(1).
\]
\end{itemize}
\end{proof}
\begin{remark}
We discuss several comments on the framework and the results of Theorem \ref{T2.1} and Theorem \ref{T2.2} as follows.
\begin{enumerate}
\item
Many probability distributions belong to an exponentially decaying distribution class, including well-known distributions such as Gaussian and sub-Gaussian distributions. Conversely, to fulfill the conditions for a polynomially decaying distribution, the \( D \)-th moment must be integrable.
\vspace{0.1cm}
\item
The results in Theorem \ref{T2.1} and Theorem \ref{T2.2} demonstrate that as long as initial velocity distribution is sufficiently concentrated, the solution will be unique in the weak sense of definition \ref{D2.1}, and a certain degree of concentration will persist under the evolution of the KCS flow.
\vspace{0.1cm}
\item
Compared to the previous work \cite{w6}, our results extend their findings by relaxing the assumption of compact velocity support to allow for non-compact velocity support. In particular, we do not impose any condition on coupling strength $\kappa$ and improve the critical exponent $D$. More precisely, if we take $\gamma=\frac{1}{\beta}$, then we only need to require
\[D>\max \Big \{\frac{2(3-\beta \gamma)}{\gamma -1}, 4  \Big \}=\max \Big \{\frac{4\beta}{1-\beta}, 4  \Big \}.\]
In fact, we can provide a better estimate as we stated in Remark \ref{RE:4.1},  \[D>\inf\limits_{l_1>1}\max\left\{\frac{2l_1}{l_1-1}\frac{\beta}{1-\beta},\quad 2l_1\right\}.\] This signficantly improve the exponent $D>\frac{7}{1-\beta}$ in \cite{w6}.
%assume the solution has compact velocity support, and using the same argument in the proof of theorem,
\vspace{0.1cm}
\item
If we further require the velocity support of the solution to be bounded as in \cite{w6},  we can also provide the weak mono-cluster flocking behavior of KCS model when $\beta= 1$ for an exponentially decaying initial distribution. However, for polynomial decay initial distribution, we can only deal with $\beta< 1$ even if we assume the velocity support of the solution is bounded.
\end{enumerate}
\end{remark}
\vspace{0.2cm}
In the following two sections, we provide proofs for Theorem \ref{T2.1} and Theorem \ref{T2.2}.

\section{Uniqueness of weak solution}\label{sec:3}
\setcounter{equation}{0}
In this section, we present the uniqueness of weak solutions to \eqref{A-1} using spatial and velocity moments estimates along the particle trajectories. 
\subsection{Propagation of spatial and velocity moments}\label{sec:3.1}
In this subsection, we study the propagation of spatial and velocity moments, and derive estimates on the mass of particles with sufficiently large velocities. 
\begin{lemma}\label{L3.1}
For $\tau \in (0, \infty]$, let $f \in {\mathcal C}([0, \tau); L^1(\mathbb{R}^{2d})) \cap L_+^\infty([0, \tau) \times \mathbb{R}^{2d})$ be a weak solution to \eqref{A-1} such that 
\[
{\mathcal M}_p(f^{\mathrm{in}}, D) :=  \int_{\mathbb{R}^{2d}} (|x|^D+ |v|^D) f^{\mathrm{in}}(z) \di z < \infty.
\]
Then, we have the following estimates: for $t \in [0, \tau)$, 
	\begin{align*}
	\begin{aligned} \label{C-1-101}
& (i)~\int_{\mathbb{R}^{2d}}v f(t, z) \di z =	\int_{\mathbb{R}^{2d}}vf^{\mathrm{in}}(z) \di z. \\
& (ii)~ \int_{\mathbb{R}^{2d}} xf(t, z) \di z  =	\int_{\mathbb{R}^{2d}}x f^{\mathrm{in}}(z) \di z  + t \int_{\mathbb{R}^{2d}}vf^{\mathrm{in}}(z) \di z. \\
& (iii)~ \int_{\mathbb{R}^{2d}} | v|^{D}f(t, z) \di z \le	\int_{\mathbb{R}^{2d}} | v|^{D}f^{\mathrm{in}}(z) \di z. \\
& (iv)~\int_{\mathbb{R}^{2d}} | x|^{D}f(t, z) \di z   \le	\left[ \left(\int_{\mathbb{R}^{2d}} | x|^{D}f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{D}}+ 
\left(\int_{\mathbb{R}^{2d}} | v|^{D}f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{D}}t\right ]^{D}.
	\end{aligned}
	\end{align*}

\end{lemma}
\begin{proof}
(i)~It follows from the weak formulation in Definition \ref{D2.1} that for any $\psi \in {\mathcal C}_c^1(\mathbb{R}^{2d})$, 
	\begin{equation}\label{424}
		\dfrac{\di}{\di t}\int_{\mathbb{R}^{2d}}\psi f(t, z) \di z =\int_{\mathbb{R}^{2d}} \Big( v \cdot\nabla_{ x}\psi +\nabla_{ v}\psi \cdot L[f] \Big) f(t, z) \di z.
	\end{equation}
	Since the map $ v~\mapsto~| v|^D$ is not an admissible test
	function in \eqref{424}, we introduce a smooth cut-off function \(\varphi_R\) such that  
	\[
	\varphi_R( v) = 
	\begin{cases} 
		1, & \mbox{for }~ v\in B_R, \\ 
		0, & \mbox{for }~ v\in \mathbb{R}^d \setminus B_{2R},
	\end{cases} 
	\quad \mbox{and} \quad  |\nabla \varphi_R| \leq \frac{2}{R},
	\]
	where $B_r = B_r(0)$ is the ball with a radius $r$ centered at the origin. Then, we can use the definition of a weak solution with the function to find 
		\begin{align}
		\begin{aligned} \label{C-0-110}
		 \dfrac{\di}{\di s}\int_{\mathbb{R}^{2d}}v f(s, z) \di z =-\kappa \int_{\mathbb{R}^{4d}}\phi( |x_{\star}-x|)(v-v_{\star})f(s, z_{\star})f(s, z) \di z \di z_\star =0.
	\end{aligned}
	\end{align}
	We integrate \eqref{C-0-110} from $s= 0$ to $s= t$ to find the desired total momentum.

	\vspace{0.2cm}

\noindent (ii)~We use a similar argument as in (i) and the result of (i) to get 
\begin{equation}\label{New-0}
			\dfrac{\di}{\di s}\int_{\mathbb{R}^{2d}} x f(s, z) \di z = \int_{\mathbb{R}^{4d}} v  f(s, z) \di z =  \int_{\mathbb{R}^{4d}} v  f^{\mathrm{in}}(z) \di z.
	\end{equation}	
Again, we integrate \eqref{New-0} to derive the desired estimate. 

\vspace{0.2cm}	

\noindent (iii)~Recall that 
	\begin{equation} \label{New-1}
	 \partial_t f = -\nabla_x \cdot (v f) - \nabla_v \cdot (L[f] f). 
	\end{equation}

\noindent We use the exchange map $(x, v)~~\Longleftrightarrow~~(x_\star, v_{\star})$, the symmetry of $\phi(\cdot)$ under the exchange map,  \eqref{New-1} and 
\[ \nabla_v ( | v |^D)  = D | v |^{D-2} v \]
 to find 
		\begin{align}\label{C-0-10}
		\begin{aligned}
			&\dfrac{\di}{\di t}\int_{\mathbb{R}^{2d}} | v |^D f(t, z) \di z = \int_{\mathbb{R}^{2d}} | v |^D \partial_t f(t, z) \di z \\
			&=-\kappa D\int_{\mathbb{R}^{4d}}\phi(|x_{\star}-x|) | v |^{D-2}\langle v,v-v_{\star}\rangle f(t, z_{\star})f(t, z) \di z\di z_\star \\	
			&=-\frac{\kappa D}{2}\int_{\mathbb{R}^{4d}}\phi(|x_{\star}-x|) \langle | v|^{D-2} v-| v_{\star}|^{D-2} v_{\star},v-v_{\star}\rangle f(t, z_\star)   f(t,z) \di z_{\star}  \di z  \\
					&\le-\frac{\kappa D}{2}\int_{\mathbb{R}^{4d}}\phi(|x_{\star}-x|)\left(| v|^{D}+ | v_{\star} |^{D}-| v_{\star} |^{D-1} | v|-| v|^{D-1} | v_{\star}|\right)f(t, z_{\star})f(t, z) \di z_\star  \di z  \\		
			&=-\frac{\kappa D}{2}\int_{\mathbb{R}^{4d}}\phi(|x_{\star}-x|)(| v|^{D-1}-| v_{\star}|^{D-1})\left(| v|-| v_{\star}|\right)f(t, z_{\star})f(t, z) \di z_\star  \di z \\
			&\le 0,
		\end{aligned}
	\end{align}
	where $\langle \cdot, \cdot \rangle$ is the standard inner product in $\bbr^d$. This yields the desired third estimate.

	\vspace{0.2cm}

\noindent (iv)~We can use the same technique as in (i) and the H\"{o}lder inequality to get 
		\begin{align}\label{C-0-11}
		\begin{aligned}
		& \dfrac{\di}{\di t}\int_{\mathbb{R}^{2d}} | x|^D f(t, z)  \di z \\
		& \hspace{0.5cm} =D\int_{\mathbb{R}^{2d}} | x|^{D-2}\langle x,v \rangle f(t, z) \di z \le D\int_{\mathbb{R}^{2d}} | x|^{D-1} |v |f(t, z) \di z \\
		& \hspace{0.5cm} \le D\left(\int_{\mathbb{R}^{2d}} | x|^{D}f(t, z) \di z \right)^{\frac{D-1}{D}}\left(\int_{\mathbb{R}^{2d}} |v|^{D}f(t, z) \di z \right)^{\frac{1}{D}}.
		\end{aligned}
	\end{align}
	This implies 
		\begin{equation}\label{C-0-111}
		\dfrac{\di}{\di t}\left(\int_{\mathbb{R}^{2d}} | x|^{D}f(t, z) \di z \right)^{\frac{1}{D}}
			\le \left(\int_{\mathbb{R}^{2d}} |v|^{D}f(t, z) \di z \right)^{\frac{1}{D}} 
			\le \left(\int_{\mathbb{R}^{2d}} | v|^{D}f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{D}}.
	\end{equation}
	Now, we integrate the above relation from $s= 0$ to $s= t$ to obtain
		\begin{align*}
	\int_{\mathbb{R}^{2d} } | x|^{D}f(t, z) \di z \le	\left[  \left(\int_{\mathbb{R}^{2d}} | x|^{D}f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{D}}+\left(\int_{\mathbb{R}^{2d}} | v|^{D}f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{D}}t\right]^{D }.
	\end{align*}

\end{proof}
\begin{remark} Below, we comment on the result of Lemma \ref{L3.1}.
\begin{enumerate}
\item
If we assume 
\[ x_c(0) =0, \quad v_c(0) =0, \]
then we have
\[
 x_c(t) =0, \quad v_c(t) =0, \quad t \geq 0.
\]
\item
It is easy to see that 
\[ 
\int_{\mathbb{R}^{2d}} | v|^{D}f(t, z) \di z \lesssim 1, \quad \int_{\mathbb{R}^{2d}} |x|^{D}f(t, z) \di z \lesssim (1 + t)^D.
\]
\end{enumerate}
\end{remark}



As a direct application of Lemma \ref{L3.1}, we have estimates on spatial and velocity moments for large position and velocity. 
\begin{corollary} \label{C3.1}
Let $f$ be a weak solution to \eqref{A-1} with the initial datum $f^{\mathrm{in}}$ such that
\[
{\mathcal M}_p(f^{\mathrm{in}}, D) = \int_{\mathbb{R}^{2d}}( |x|^D+ |v|^D) f^{\mathrm{in}}(z) \di z < \infty,
\]
and let $R_x(t)$ and $R_v(t)$ be nonnegative locally bounded functions. Then, we have
\begin{align}
\begin{aligned} \label{New-2}
& (i)~\int_{ \bbr_x^d \times B^c_{R_v(t)}} f(t, z) \di z \le\frac{\mathcal{M}_{p}(f^{\mathrm{in}},D)}{R_v(t)^D}. \\
& (ii)~\int_{B^c_{R_x(t)}  \times \bbr_v^d}   f(t, z) \di z \le \frac{2^{D-1} \mathcal{M}_{p}(f^{\mathrm{in}},D) (1 + t)^D}{R_x(t)^D}.
\end{aligned}
\end{align}
\end{corollary}
\begin{proof}
Let $R_x(t)$ and $R_v(t)$ be arbitrary time-dependent functions. Then, it follows from Lemma \ref{L3.1} that 
\begin{align*}
\begin{aligned}
& R_v(t)^D \int_{ \bbr_x^d \times B^c_{R_v(t)}} f(t,z) \di z   \le \int_{\mathbb{R}^{2d}} |v|^Df(t, z) \di z = \mathcal{M}_{p}(f^{\mathrm{in}}, D),\\
& R_x(t)^D   \int_{B^c_{R_x(t)}  \times \bbr_v^d}   f(t, z) \di z \leq     \int_{B^c_{R_x(t)}  \times \bbr_v^d}  |x|^D  f(t, z) \di z  \\
& \hspace{0.5cm}  \leq \int_{\bbr^{2d}} |x|^D f(t, z) \di z  \le \left[  \left(\int_{\mathbb{R}^{2d}} | x|^{D}f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{D}}+ \left(\int_{\mathbb{R}^{2d}} | v|^{D}f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{D}}t \right]^{D}  \\
& \hspace{0.5cm}  \le  2^{D-1} \Big[ \left(\int_{\mathbb{R}^{2d}} | x|^{D}f^{\mathrm{in}}(z) \di z \right) + \left(\int_{\mathbb{R}^{2d}} | v|^{D}f^{\mathrm{in}}(z) \di z \right) t^D \Big ] \\
& \hspace{0.5cm} \leq 2^{D-1} {\mathcal M}_p(f^{\mathrm{in}}, D) (1 + t)^D,
\end{aligned}
\end{align*}
where we used the inequality:
\[ (|a| + |b|)^{D} \leq 2^{D-1} (|a|^D + |b|^D),~~D \geq 1. \]
The above estimates yield the desired estimates. 
\end{proof}
\begin{remark} 
	If we choose a super-linearly growing function $R_x(t)$ such that 
\[ R_x(t) \geq C (1 + t)^{1+ \varepsilon} \quad \mbox{for some $\varepsilon > 0$}, \]
then the masses over the regions $\bbr_x^d \times B^c_{R_v(t)}$ and  $B^c_{R_x(t)}  \times \bbr_v^d$ in phase space:
\[ \int_{ \bbr_x^d \times B^c_{R_v(t)}} f(t, z) \di z  \quad \mbox{and} \quad \int_{B^c_{R_x(t)}  \times \bbr_v^d}   f(t, z) \di z  \]	
 decay to zero as $t \to \infty$. 
\end{remark}
