Note that in Lemma \ref{L3.1}, we deal with the propagation of spatial-velocity moments along the kinetic flow. Next, we study estimates on the integrals of $f$ with exponential spatial and velocity weights.
\begin{lemma}\label{L3.2}
	For $\tau \in (0, \infty]$, let $f \in {\mathcal C}([0, \tau); L^1(\mathbb{R}^{2d})) \cap L_+^\infty([0, \tau) \times \mathbb{R}^{2d})$ be a weak solution to \eqref{A-1} such that 
	\[
	{\mathcal M}_{e}(f^{\mathrm{in}}, \alpha) :=  \int_{\mathbb{R}^{2d}} e^{\alpha(|x|+ |v|)} f^{\mathrm{in}}(z) \di z < \infty.
	\]
	Then, the following assertions hold.
\begin{enumerate}
\item
Propagation of exponentially weighted mass:	
\begin{equation} \label{NN-3}
\begin{cases}
\displaystyle \int_{\mathbb{R}^{2d}}e^{\alpha | v|}f(t, z) \di z \le	\int_{\mathbb{R}^{2d}} e^{\alpha | v|}f^{\mathrm{in}}(z) \di z, \vspace{6pt}\\
\displaystyle \frac{\di }{\di t}\int_{\mathbb{R}^{2d}} e^{\alpha | x|}f(t, z) \di z   \leq	\alpha \int_{\mathbb{R}^{2d}} e^{\alpha | x|} |v| f(t, z) \di z.
\end{cases}
\end{equation}
\item
If the projected velocity support of $f$ is uniformly bounded:
	\begin{equation}\label{eqt4.401}
		\sup\limits_{(x,v)\in{\rm spt}(f(t))} |v|\le P_\infty,
	\end{equation} 
then we have
\[
		\int_{\mathbb{R}^{2d}} e^{\alpha | x|}f(t, z) \di z\le e^{\alpha P_\infty t}\int_{\mathbb{R}^{2d}} e^{\alpha | x|}f^{\mathrm{in}}( z) \di z. \]
\end{enumerate}		
\end{lemma}
\begin{proof}
(i) The derivations for the estimates in \eqref{NN-3} are similar to Lemma \ref{L3.1},  hence we omit them here.\newline

\noindent (ii) We use the second estimate in \eqref{NN-3} to see that 
\[
\frac{\di }{\di t}\int_{\mathbb{R}^{2d}} e^{\alpha | x|}f(t, z) \di z   \leq	\alpha \int_{\mathbb{R}^{2d}} e^{\alpha | x|} |v| f(t, z) \di z \leq \alpha P_{\infty} \int_{\mathbb{R}^{2d}} e^{\alpha | x|} f(t, z) \di z.
\]
This yields the desired estimate.
\end{proof}
As a direct application of Lemma \ref{L3.2}, we can estimate the mass outside of the effective domain when weak solution $f$ has a compact velocity support.
\begin{corollary}\label{C3.2}
	Suppose that the initial datum $f^{\mathrm{in}} \in L^1(\mathbb{R}^{2d})$ satisfy 
	\begin{equation*}
		P_\infty :=\sup\limits_{(x,v)\in{\rm spt}(f^{\mathrm{in}})} |v|<\infty, \qquad  \int_{\mathbb{R}^{2d}} e^{\alpha|x|} f^{\mathrm{in}}(z) \di z \leq{\mathcal M}_{e}(f^{\mathrm{in}},\alpha) < \infty,
	\end{equation*}
and  let $f$ be a global weak solution to \eqref{A-1}. Then we have
	\begin{equation} \label{New-2-1}
	 \int_{B_{R_x(t)}^c  \times \bbr^d}   f(t, z) \di z \le \mathcal{M}_{e}(f^{\mathrm{in}}, \alpha) e^{\alpha P_\infty t-\alpha R_x(t)}.
	 \end{equation}
\end{corollary}
\begin{proof} 
Note that 
\begin{align}
\begin{aligned} \label{New-2-2} 
&  e^{\alpha R_x(t)} \int_{B_{R_x(t)}^c \times \bbr^d} f(t, z) \di z   \leq 	\int_{B_{R_x(t)}^c \times \bbr^d} e^{\alpha | x|}f(t, z) \di z \\
& \hspace{2cm} \leq  \int_{\mathbb{R}^{2d}} e^{\alpha | x|}f(t, z) \di z  \leq e^{\alpha P_\infty t}\int_{\mathbb{R}^{2d}} e^{\alpha | x|}f^{\mathrm{in}}( z) \di z, \\
\end{aligned}
\end{align}
where we used (2) of Lemma \ref{L3.2} in the last inequality.  \newline

On the other hand, we have
\begin{equation} \label{New-2-3}
\int_{\mathbb{R}^{2d}} e^{\alpha | x|}f^{\mathrm{in}}( z) \di z \leq \int_{\mathbb{R}^{2d}} e^{\alpha (| x| + |v|) }f^{\mathrm{in}}( z) \di z = M_e(f^{\mathrm{in}}, \alpha) < \infty.
\end{equation}
Now, we combine \eqref{New-2-2} and \eqref{New-2-3} to get 
\[
 e^{\alpha R_x(t)} \int_{B_{R_x(t)}^c \times \bbr^d} f(t, z) \di z  \leq e^{\alpha P_\infty t}\int_{\mathbb{R}^{2d}} e^{\alpha | x|}f^{\mathrm{in}}( z) \di z \leq  e^{\alpha P_\infty t} M_e(f^{\mathrm{in}}, \alpha). 
 \]
This yields the desired estimates.
\end{proof}
In the following lemma, we provide time derivative of the second velocity moment around the average velocity.
\begin{lemma}\label{L3.3}
	For $\tau \in (0, \infty]$, let $f \in {\mathcal C}([0, \tau); L^1(\mathbb{R}^{2d})) \cap L_+^\infty([0, \tau) \times \mathbb{R}^{2d})$ be a weak solution to \eqref{A-1} with initial datum $f^{\mathrm{in}}$ satisfying 
	\[
	\int_{\bbr^{2d}} (|x|^2 + |v|^2) f^{\mathrm{in}}(z) \di z < \infty. 
	\]
	Then the kinetic energy is non-increasing:
	\[
	\frac{\di}{\di t} \int_{{\mathbb R}^{2d}} |v - v_c(t)|^2 f(t, z) \di z =-\kappa \int_{{\mathbb R}^{4d}} \phi(|x-x_\star|) |v-v_\star|^2  f(t, z_\star) f(t, z) \di z_\star  \di z\le0.
	\]
\end{lemma}
\begin{proof} It follows from Lemma \ref{L3.1} that 
	\[ v_c(t) = v_c^{\mathrm{in}}, \quad t \geq 0. \]
	We use the above relation and $ \partial_t f = -\nabla_x \cdot (v f) - \nabla_v \cdot (L[f] f)$ to find 
	\begin{align*}
		\begin{aligned}
			&\frac{\di}{\di t} \int_{{\mathbb R}^{2d}} |v - v_c(t)|^2 f(t, z) \di z  =\frac{\di}{\di t} \int_{{\mathbb R}^{2d}} |v - v_c^{\mathrm{in}}|^2 f(t, z) \di z  \\
			& \hspace{0.5cm} = \int_{{\mathbb R}^{2d}}  |v - v_c^{\mathrm{in}}|^2 \partial_t f(t, z) \di z   =  -  \int_{{\mathbb R}^{2d}}   |v - v_c^{\mathrm{in}}|^2  \nabla_v \cdot (L[f] f) \di z  \\
			& \hspace{0.5cm}  = -2 \kappa \int_{{\mathbb R}^{4d}} \phi(|x-x_*|) \langle v - v_c^{\mathrm{in}}, v-v_* \rangle  f(t,  z_\star) f(t, z) \di z_\star \di z   \\
			& \hspace{0.5cm}   =2 \kappa \int_{{\mathbb R}^{4d}} \phi(|x-x_*|) \langle v_* - v_c^{\mathrm{in}}, v-v_* \rangle  f(t,  z_\star) f(t, z) \di z_\star \di z   \\
			& \hspace{0.5cm}  =- \kappa \int_{{\mathbb R}^{4d}} \phi(|x-x_*|) |v-v_*|^2  f(t,  x_\star, v_\star) f(t, z) \di z_\star \di z.
		\end{aligned}
	\end{align*}
\end{proof}		
With the above preparations, we can show the exponential emergence of weak mono-cluster flocking under special case $\beta=0$.
\begin{proposition} \label{P3.1}
Suppose that decay of communication weight and initial datum satisfy 
			\[ \beta = 0, \quad \kappa > 0, \quad  (|x|^2 + |v|^2)  f^{\mathrm{in}} \in L^1(\mathbb{R}^{2d}), \quad v_c(0) = 0, \]
			and let $f$ be a global weak solution to \eqref{A-1}.  Then we have 
			\begin{align*}\label{eq:300}
				\int_{\mathbb{R}^{2d}} |v|^2f(t, z) \di z \le e^{-2 \kappa t}	\int_{\mathbb{R}^{2d}} |v|^2f^{\mathrm{in}}(z) \di z,  \quad  \forall t\ge0.
			\end{align*}
		\end{proposition}
		\begin{proof} By the assumptions, we have
		\[ \phi \equiv 1 \quad v_c(t) = v_c(0) = 0, \quad t > 0. \]
		Then, we use Lemma \ref{L3.2} to find 
\[ \frac{\di}{\di t} \int_{{\mathbb R}^{2d}} |v|^2 f(t, z) \di z = -\kappa \int_{{\mathbb R}^{4d}} |v - v_*|^2 f(t, z_\star) f(t, z)  \di z_\star  \di z = -2 \kappa \int_{{\mathbb R}^{2d}} |v |^2 f(t, z) \di z. \]
			This yields an exponential decay estimate. 
		\end{proof}
\subsection{Proof of Theorem \ref{T2.1}}\label{sec:3.2}
Suppose the initial datum $f^{\mathrm{in}}$ satisfies positivity, boundedness and suitable decay conditions:
\[
f^{\mathrm{in}} \in (L^1 \cap L_+^\infty)(\mathbb{R}^{2d}), \quad (|x|^2 + |v|^2)f^{\mathrm{in}} \in L^1(\mathbb{R}^{2d}), 
\]
and let $f$ be a global weak solution to \eqref{A-1} whose existence is guaranteed by Proposition \ref{P2.2}. Then, we use Lemma \ref{L3.1} to see 
				\begin{align}\label{vD}
				\int_{\mathbb{R}^{2d}} | v|^{D}f(t, z) \di z \le \int_{\mathbb{R}^{2d}} | v|^{D}f^{\mathrm{in}}(z) \di z.
			\end{align}
Suppose that $g$ is another weak solution to \eqref{A-1} with the same initial datum $g^{\mathrm{in}} = f^{\mathrm{in}}$. We want to show that for $t \in [0, \tau)$, 
\[ f(t) \equiv g(t) \quad \mbox{a.e.~~in $\bbr^{2d}$}.  \]
To see this, we set  $(X_{f}(t),V_{f}(t))$ and $(X_{g}(t),V_{g}(t))$ to be the particle trajectories generated by $f$ and $g$, respectively:
\begin{equation} \label{New-D-1}
	\begin{cases}
		\displaystyle {\dot X}_f(t)=V_f (t), \quad t > 0,   \\
		\displaystyle {\dot V}_f (t)= L[f](t, X_f(t), V_f(t)], \\
		\displaystyle X_f(0)=x, \quad  V_f(0)=v, \\
		\displaystyle f(t) =(X_{f}(t),V_{f}(t) )\# f^{\mathrm{in}},
	\end{cases}
\quad \mbox{and} \qquad  
	\begin{cases}
		\displaystyle {\dot X}_g(t)=V_g (t), \quad t > 0,   \\
		\displaystyle {\dot V}_g (t)= L[g](t, X_g(t), V_g(t)], \\
		\displaystyle X_g(0)=x, \quad  V_g(0)=v, \\
		\displaystyle g(t) =(X_{g}(t),V_{g}(t) )\# f^{\mathrm{in}}.
	\end{cases}
\end{equation}
Next, we introduce a deviation functional $\Delta[f, g]$ between two particle trajectories which was first introduced in \cite{k6}:
\begin{equation*}
	\Delta[f,g](t):=\int_{\mathbb{R}^{2d}} \Big ( |X_{f}(t)-X_{g}(t)|+ |V_{f}(t)-V_{g}(t)| \Big )f^{\mathrm{in}}(z) \di z, \quad \forall~t\in[0,\tau].
\end{equation*}
Then, we claim that 
\begin{equation} \label{New-D-3}
\Delta[f,g](t) \equiv 0, \quad t \in [0, \tau).
\end{equation}
Once the claim \eqref{New-D-3} is verified, then we derive the uniqueness:
\[ f \equiv g. \]
Since 
\[ X_f(0)= X_g(0) \quad \mbox{and} \quad  V_f(0) = V_g(0), \]
it is easy to see 
\begin{equation} \label{New-D-4}
 \Delta[f,g](0) = 0.
 \end{equation}
{\it Proof of \eqref{New-D-3}}: It suffices to derive an integral form of  Grönwall's inequality for $\Delta[f, g]$. For this, we split the derivation into two steps. \newline

\noindent $\bullet$~Step A.1: We use $\eqref{New-D-1}_1$ and $\eqref{New-D-1}_2$ to get 
\begin{align}\label{4:23}
	\begin{aligned}
		|X_{f}(t)-X_{g}(t) | \le \int_0^t |V_{f}(s)-V_{g}(s) |\di s.
	\end{aligned}
\end{align}
This and Fubini's theorem yield
\begin{equation} \label{New-D-4-0}
\int_{\mathbb{R}^{2d}} |X_{f}(t)-X_{g}(t)| f^{\mathrm{in}}(z) \di z \leq  \int_0^t\int_{\mathbb{R}^{2d}} |V_{f}(s)-V_{g}(s)|  f^{\mathrm{in}}(z) \di z \di s.
\end{equation}

\vspace{0.2cm}

\noindent $\bullet$~Step A.2:  Recall that 
\begin{equation} \label{New-D-4-1}
L[f](t,x,v)=-\kappa \int_{\mathbb{R}^{2d}} \phi( |x-x_{\star}|) \left(v-v_{\star}\right)  f(t, z_{\star}) \di z_\star.
 \end{equation}
Again, we use $\eqref{New-D-1}_1$ and $\eqref{New-D-1}_2$ to obtain
\begin{equation} \label{New-D-5}
\frac{\di}{\di t} |V_f(t) - V_g(t)| \leq  \Big| L[f](t, X_f(t), V_f(t)) -  L[g](t, X_g(t), V_g(t))  \Big|.
 \end{equation}
We integrate \eqref{New-D-5} from $0$ to $t$, and then use $ (V_f - V_g)(0) = 0$, $\eqref{New-D-1}_4$,  to get
\begin{equation} \label{New-D-6}
| V_f(t) - V_g(t)| \leq \int_0^t \Big| L[f](s, X_f(s), V_f(s)) -  L[g](s, X_g(s), V_g(s)) \Big| \di s.
\end{equation}
For $s \leq t$, we set 
\begin{align}
\begin{aligned} \label{New-D-6}
& (x_{f,\star}(s),v_{f,\star}(s)) :=(X_{f}(s,0, x_{\star}, v_{\star}),V_{f}(s,0, x_{\star}, v_{\star})), \\
& (x_{g,\star}(s),v_{g,\star}(s)) :=(X_{g}(s,0, x_{\star}, v_{\star}),V_{g}(s,0, x_{\star}, v_{\star})).
\end{aligned}
\end{align}
Next, we use the Lipschitz continuity of $\phi$, \eqref{New-D-6} and 
\[ \| f^{\mathrm{in}} \|_1 = 1, \qquad   \frac{1}{(1+|X_{f}(s)-x_{f,\star}(s)|^2)^{\frac{\beta}{2}}} \leq 1 \]
 to find that for any $( x, v)\in{\rm spt}f^{\mathrm{in}}$
\begin{align} 
\begin{aligned} \label{423}
        & \Big| L[f](s, X_f(s), V_f(s)) -  L[g](s, X_g(s), V_g(s)) \Big|  \\
        & \hspace{0.2cm} = \kappa  \Big|  \int_{\mathbb{R}^{2d}} \phi( |X_f(s)-x_{\star}|) (V_f(s)-v_{\star} )  f(s, z_{\star}) \di z_\star \\
        & \hspace{1cm} - \int_{\mathbb{R}^{2d}} \phi( |X_g(s) -x_{\star}|) (V_g(s) - v_{\star})  f(s, z_{\star}) \di z_\star  \Big| \\	
	& \hspace{0.2cm}  \leq  \kappa \int_{\mathbb{R}^{2d}}\left |\frac{V_{f}(s)-v_{f,\star}(s)}{(1+|X_{f}(s)-x_{f,\star}(s)|^2)^{\frac{\beta}{2}}}-\frac{V_{g}(s)-v_{g,\star}(s)}{(1+|X_g(s)-x_{g,\star}(s)|^2)^{\frac{\beta}{2}}}\right |f^{\mathrm{in}}(z_{\star}) \di z_\star \\
	& \hspace{0.2cm}  \le  \kappa \int_{\mathbb{R}^{2d}}\left |\frac{V_{f}(s)-v_{f,\star}(s)}{(1+|X_{f}(s)-x_{f,\star}(s)|^2)^{\frac{\beta}{2}}}-\frac{V_{g}(s)-v_{g,\star}(s)}{(1+|X_{f}(s)-x_{f,\star}(s)|^2)^{\frac{\beta}{2}}}\right |f^{\mathrm{in}}(z_{\star}) \di z_\star  \\
	& \hspace{0.4cm} +  \kappa \int_{\mathbb{R}^{2d}}\left |\frac{V_{g}(s)-v_{g,\star}(s)}{(1+|X_{f}(s)-x_{f,\star}(s)|^2)^{\frac{\beta}{2}}}-\frac{V_{g}(s)-v_{g,\star}(s)}{(1+|X_{g}(s)-x_{g,\star}(s)|^2)^{\frac{\beta}{2}}}\right |f^{\mathrm{in}}(z_{\star}) \di z_\star  \\
	 & \hspace{0.2cm}   \le  \kappa \int_{\mathbb{R}^{2d}}  \left |\frac{V_{f}(s)-V_g(s)}{(1+|X_{f}(s)-x_{f,\star}(s)|^2)^{\frac{\beta}{2}}} \right |  +  \left |\frac{v_{f,\star}(s)-v_{g,\star}(s)}{(1+|X_{f}(s)-x_{f,\star}(s)|^2)^{\frac{\beta}{2}}} \right | f^{\mathrm{in}}(z_{\star}) \di z_\star  \\
	  & \hspace{0.4cm} +  \kappa \int_{\mathbb{R}^{2d}}\left |\frac{V_{g}(s)-v_{g,\star}(s)}{(1+|X_{f}(s)-x_{f,\star}(s)|^2)^{\frac{\beta}{2}}}-\frac{V_{g}(s)-v_{g,\star}(s)}{(1+|X_{g}(s)-x_{g,\star}(s)|^2)^{\frac{\beta}{2}}}\right |f^{\mathrm{in}}(z_{\star}) \di z_\star  \\
	  & \hspace{0.2cm}  \le  \kappa |V_{f}(s)-V_{g}(s) |+  \kappa \int_{\mathbb{R}^{2d}} |v_{f,\star}(s)-v_{g,\star}(s) |f^{\mathrm{in}}(z_{\star}) \di z_\star \\
	  & \hspace{0.4cm} +  \kappa C_{\beta} 
	\int_{\mathbb{R}^{2d}}\left( |v_{g,\star}(s)|+ |V_{g}(s) |\right) \left(|x_{f,\star}(s)-x_{g,\star}(s)|+ |X_{f}(s)-X_{g}(s) |\right)  |f^{\mathrm{in}}(z_{\star}) \di z_\star,
\end{aligned}
\end{align}
where $C_\beta$ is a Lipschitz constant of the communication weight function $\phi$. \newline

Now, we combine \eqref{New-D-5} and \eqref{423} to get 
\begin{align}
\begin{aligned} \label{New-D-7}
& \int_{\mathbb{R}^{2d}} | V_f(t) - V_g(t)|  f^{\mathrm{in}}(z) \di z   \\
& \hspace{0.5cm} \leq \int_0^t  \int_{\mathbb{R}^{2d}}   \Big| L[f](s, X_f(s), V_f(s)) -  L[g](s, X_g(s), V_g(s)) \Big|  f^{\mathrm{in}}(z) \di z  \di s \\
& \hspace{0.5cm} \leq  \kappa  \int_0^t   \int_{\mathbb{R}^{2d}}   |V_{f}(s)-V_{g}(s) | f^{\mathrm{in}}(z) \di z \di s \\
& \hspace{0.7cm}  + \kappa \int_0^t \int_{\mathbb{R}^{4d}} |v_{f,\star}(s)-v_{g,\star}(s) |f^{\mathrm{in}}(z_{\star})   f^{\mathrm{in}}(z) \di z_\star \di z  \di s \\
& \hspace{0.5cm} +  \kappa C_{\beta}
	\int_0^t \int_{\mathbb{R}^{4d}} \Big( |v_{g,\star}(s)|+ |V_{g}(s) | \Big) \\
	& \hspace{0.7cm}  \times  \Big(|x_{f,\star}(s)-x_{g,\star}(s)|+ |X_{f}(s)-X_{g}(s) | \Big) f^{\mathrm{in}}(z_{\star}) f^{\mathrm{in}}(z)   \di z \di z \di s.
\end{aligned}
\end{align}
Finally, we combine \eqref{New-D-4} and \eqref{New-D-7} to see
\begin{align}
\begin{aligned} \label{New-D-8}
	\Delta[f,g](t) &= \int_{\mathbb{R}^{2d}} \Big( |X_{f}(t)-X_{g}(t)|+ |V_{f}(t)-V_{g}(t) | \Big) f^{\mathrm{in}}(z) \di  z \\
	&\leq 2  \kappa \int_0^t   \Delta(f,g)(s) \di s +   \kappa \int_0^t \int_{\mathbb{R}^{4d}} |v_{f,\star}(s)-v_{g,\star}(s) |f^{\mathrm{in}}(z_{\star})   f^{\mathrm{in}}(z) \di z  \di s \\
&+  \kappa C_{\beta}
	\int_0^t \int_{\mathbb{R}^{4d}} |v_{g,\star}(s)| |x_{f,\star}(s)-x_{g,\star}(s)|  f^{\mathrm{in}}(z_{\star})   f^{\mathrm{in}}(z) \di z_\star \di z \di s \\
	&+  \kappa C_{\beta}
	\int_0^t \int_{\mathbb{R}^{4d}}  |V_{g}(s)| |x_{f,\star}(s)-x_{g,\star}(s)| f^{\mathrm{in}}(z_{\star}) f^{\mathrm{in}}(z) \di z_\star \di z \di s \\
	& +   \kappa  C_{\beta}\int_0^t \int_{\mathbb{R}^{4d}}  |v_{g,\star}(s)| |X_{f}(s)-X_{g}(s) |  f^{\mathrm{in}}(z_{\star}) f^{\mathrm{in}}(z) \di z_\star \di z \di s \\ 
	& +  \kappa  C_{\beta}\int_0^t \int_{\mathbb{R}^{4d}}  |V_{g}(s) | |X_{f}(s)-X_{g}(s) |  f^{\mathrm{in}}(z_{\star}) f^{\mathrm{in}}(z) \di z_\star \di z \di s \\ 
	& =: 2  \kappa \int_0^t \Delta[f,g](s) \di s + \sum_{i=1}^{5} {\mathcal I}_{1i}.
\end{aligned}
\end{align}
Below, we estimate the term ${\mathcal I}_{1i}$ one by one. \newline

\noindent $\bullet$~Case A.1 (Estimate of ${\mathcal I}_{11}$): We use the Fubini theorem and $\| f^{\mathrm{in}} \|_1 = 1$ to get 
\begin{align}
\begin{aligned} \label{New-D-9}
 {\mathcal I}_{11} &=    \kappa \int_0^t \int_{\mathbb{R}^{4d}} |v_{f,\star}(s)-v_{g,\star}(s) |f^{\mathrm{in}}(z_{\star})   f^{\mathrm{in}}(z) \di z_\star \di z  \di s \\
 & =  \kappa  \int_0^t  \Big( \int_{\mathbb{R}^{2d}}  |v_{f,\star}(s)-v_{g,\star}(s) |f^{\mathrm{in}}(z_{\star})  \di z_\star \Big) \Big( \int_{\bbr^{2d}}  f^{\mathrm{in}}(z) \di z \Big) 
 \di s \\
 &=  \kappa \int_0^t \Delta[f,g](s) \di s.
\end{aligned}
\end{align}

\noindent $\bullet$~Case A.2 (Estimate of ${\mathcal I}_{12}$): We use the Cauchy-Schwarz inequality to find 
\begin{align}
\begin{aligned} \label{New-D-10}
{\mathcal I}_{12} &=  \kappa C_{\beta}
	\int_0^t \int_{\mathbb{R}^{2d}}  |v_{g,\star}(s)| |x_{f,\star}(s)-x_{g,\star}(s)| f^{\mathrm{in}}(z_{\star}) \di z_\star  \di s \\
	&\leq  \kappa C_{\beta}
	\int_0^t \Big( \int_{\mathbb{R}^{2d}}  |v_{g,\star}(s)|^2 f^{\mathrm{in}}(z_{\star}) \di z_\star \Big)^{\frac{1}{2}} \Big( \int_{\mathbb{R}^{2d}}  |x_{f,\star}(s)-x_{g,\star}(s)|^2 f^{\mathrm{in}}(z_{\star}) \di z_\star \Big)^{\frac{1}{2}}  \di s. \\
\end{aligned}
\end{align}

\noindent $\bullet$~Case A.3 (Estimate of ${\mathcal I}_{13}$): By direct estimate, we have
\begin{align}
\begin{aligned} \label{New-D-11}
{\mathcal I}_{13} &=  \kappa C_{\beta} \int_0^t \int_{\mathbb{R}^{4d}}  |V_{g}(s)| |x_{f,\star}(s)-x_{g,\star}(s)| f^{\mathrm{in}}(z_{\star}) f^{\mathrm{in}}(z) \di z_\star \di z \di s \\
& = \kappa C_{\beta} \int_0^t \Big( \int_{\mathbb{R}^{2d}} |x_{f,\star}(s)-x_{g,\star}(s)| f^{\mathrm{in}}(z_{\star}) \di z_\star \Big) \Big( \int_{\mathbb{R}^{2d}}  |V_{g}(s)| f^{\mathrm{in}}(z)    \di z  \Big) \di s.\\
\end{aligned}
\end{align}	
\noindent $\bullet$~Case A.4 (Estimate of ${\mathcal I}_{14}$): By direct estimate, we have
\begin{align}
\begin{aligned} \label{New-D-12}
{\mathcal I}_{14} &=   \kappa C_{\beta}\int_0^t \int_{\mathbb{R}^{4d}}  |v_{g,\star}(s)| |X_{f}(s)-X_{g}(s) |  f^{\mathrm{in}}(z_{\star}) f^{\mathrm{in}}(z) \di z_\star \di z \di s \\ 
&=  \kappa C_{\beta}\int_0^t \Big( \int_{\mathbb{R}^{2d}}   |v_{g,\star}(s)|  f^{\mathrm{in}}(z_{\star})  \di z_\star  \Big) \Big(  \int_{\mathbb{R}^{2d}}   |X_{f}(s)-X_{g}(s) | f^{\mathrm{in}}(z) \di z \Big) \di s.
\end{aligned}
\end{align}
\noindent $\bullet$~Case A.5 (Estimate of ${\mathcal I}_{15}$): By direct estimate, we have
\begin{align}
\begin{aligned} \label{New-D-13}
{\mathcal I}_{15} &= \kappa  C_{\beta}\int_0^t \int_{\mathbb{R}^{4d}}  |V_{g}(s) | |X_{f}(s)-X_{g}(s) |  f^{\mathrm{in}}(z_{\star}) f^{\mathrm{in}}(z) \di z_\star \di z \di s \\ 
&=  \kappa C_{\beta}\int_0^t \Big( \int_{\mathbb{R}^{2d}}  |V_{g}(s) | |X_{f}(s)-X_{g}(s)|  f^{\mathrm{in}}(z) \di z      \Big) \di s \\
&\leq \kappa  C_{\beta}\int_0^t \Big( \int_{\mathbb{R}^{2d}}  |V_{g}(s) |^2 f^{\mathrm{in}}(z) \di z      \Big)^{\frac{1}{2}} \Big(\int_{\mathbb{R}^{2d}}  
|X_{f}(s)-X_{g}(s)|^2  f^{\mathrm{in}}(z) \di z \Big)^{\frac{1}{2}} \di s.
\end{aligned}
\end{align}

Then, we collect all estimates to derive 
\begin{align*}
\begin{aligned} \label{New-D-14}		
		\Delta[f,g](t) &= \int_{\mathbb{R}^{2d}} \Big( |X_{f}(t)-X_{g}(t)|+ |V_{f}(t)-V_{g}(t) | \Big) f^{\mathrm{in}}(z) \di  z \\
		&\le C  \kappa \int_0^t\left(\int_{\mathbb{R}^{2d}} |V_{g}(s)|^{2}f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}\left(\int_{\mathbb{R}^{2d}} |X_{f}(s)-X_{g}(s)|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}\di s\\
		&\quad+C  \kappa \int_0^t \Delta[f, g](s)\di s\\
	&\le C  \kappa \left(\int_{\mathbb{R}^{2d}} |v|^{2}f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}\int_0^t\left(\int_{\mathbb{R}^{2d}} |X_{f}(s)-X_{g}(s)|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}\di s\\
	&\quad+C  \kappa \int_0^t \Delta[f,g](s)\di s\\
	&\le C  \kappa \int_0^t\left(\int_{\mathbb{R}^{2d}} |X_{f}(s)-X_{g}(s)|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}\di s+C  \kappa \int_0^t \Delta[f,g](s)\di s,
\end{aligned}
\end{align*}
i.e., we have
\begin{equation} \label{New-D-1411}
\Delta[f,g](t) \leq  C \kappa \int_0^t  \Delta[f,g](s)\di s + C  \kappa \int_0^t\left(\int_{\mathbb{R}^{2d}} |X_{f}(s)-X_{g}(s)|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}\di s.
\end{equation}
This equivalent to 
\begin{equation} \label{New-D-1511}
	\frac{\di}{\di t}\Delta[f,g](t) \leq C  \kappa  \Delta[f,g](t)+ C  \kappa \left(\int_{\mathbb{R}^{2d}} |X_{f}(t)-X_{g}(t)|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}.
\end{equation}
%In Lemma \ref{L2.3}, we set 
%\[  (u, u^{\mathrm{in}}, a, b) \quad \Longleftrightarrow \quad \Big (\Delta(f,g),  0, C,  \Big(\int_{\mathbb{R}^{2d}} |X_{f}(s)-X_{g}(s)|^2f^{\mathrm{in}}(z) \di z \Big)^{\frac{1}{2}} \Big) \]
%to find 
%
%\begin{equation} \label{New-D-14-1}
%\Delta(f,g)(t) \leq \int_0^t  e^{C(t-s)}\Big(\int_{\mathbb{R}^{2d}} |X_{f}(s)-X_{g}(s)|^2f^{\mathrm{in}}(z) \di z \Big)^{\frac{1}{2}} ds.
%\end{equation}
On the other hand, note that 
 \begin{align*}
 \begin{aligned}
& \Delta(f,g)(t) \equiv 0 \quad \Longrightarrow \quad  \int_{\mathbb{R}^{2d}} |X_{f}(t)-X_{g}(t)|f^{\mathrm{in}}(z) \di z=0 \\
& \hspace{1cm} \iff \quad |X_{f}(t)-X_{g}(t)|f^{\mathrm{in}}(z) = 0 \quad \mbox{a.e. $z \in {\mathbb R}^{2d}$} \\
& \hspace{1cm} \iff \quad |X_{f}(t)-X_{g}(t)|^2 f^{\mathrm{in}}(z) = 0 \quad \mbox{a.e. $z \in {\mathbb R}^{2d}$} \\
&  \hspace{1cm} \iff \quad  \int_{\mathbb{R}^{2d}} |X_{f}(t)-X_{g}(t)|^2 f^{\mathrm{in}}(z) \di z=0.
\end{aligned}
\end{align*}
Therefore, we have the following implication:
\begin{equation} \label{New-D-15}
 \Delta(f,g)(t) \equiv 0 \quad \Longrightarrow \quad   \int_{\mathbb{R}^{2d}} |X_{f}(t)-X_{g}(t)|^2 f^{\mathrm{in}}(z) \di z=0.
\end{equation}
Then, we use \eqref{New-D-1511} to see
	\[ \Delta[f, g](0)=0 \quad \Longrightarrow \quad 	\frac{\di}{\di t}\Delta[f,g](t)\le 0 , \quad \forall~t > 0.\]
We use the above relation and continuity argument to get 
		\[ \Delta[f, g](0)=0 \quad \Longrightarrow \quad  \Delta[f, g](t) = 0, \quad \forall~t > 0.\]
%\textcolor{blue}{Xinyu !!! please give a more direct proof for the red part}		
%		
This completes the proof. 
