\section{Emergence of weak mono-cluster flocking}\label{sec:4}
\setcounter{equation}{0}
In this section, we provide the weak mono-cluster flocking estimate of weak solutions with decaying properties in phase space.  		
\subsection{Polynomially decaying distribution class}\label{sec:4.1} 
Suppose that $\beta, D$ and $f^{\mathrm{in}}$ satisfy 

\begin{align*}
\begin{aligned}
& 0 \leq \beta < 1, \quad \kappa > 0, \quad   \gamma > 1, \quad      D > \max \Big \{ \frac{2(3-\beta \gamma)}{\gamma -1},~4  \Big \}, \\
&  {\mathcal M}_p(f^{\mathrm{in}}, D) :=  \int_{\mathbb{R}^{2d}} (|x|^D+ |v|^D) f^{\mathrm{in}}(z) \di z < \infty, 
\end{aligned}
\end{align*}
and let $f$ be a global weak solution to \eqref{A-1}. Then, we claim that
\begin{align}
\begin{aligned} \label{D-1}
& (i)~\lim_{t \to \infty} \int_{\mathbb{R}^{2d}} |v-  v^{\mathrm{in}}_c|^2 f(t, z) \di z  = 0: \quad & \mbox{weak velocity alignment}. \\
& (ii)~\sup\limits_{0\le t< \infty} \int_{\mathbb{R}^{2d}} | x - v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c|^2 f(t, z) \di z <\infty: \quad & \mbox{weak spatial cohesion}.
\end{aligned}
\end{align}			
In what follows, we derive \eqref{D-1} one by one.  Let $z=( x, v),~z_\star = ( x_{\star}, v_{\star})$ be two phase points, and we define particle trajectories $(X(t), V(t)$ ad $(X_*(t), V_*(t))$ as solutions to the following system:
	\begin{align}
		\left\{\begin{aligned} \label{D-1-1}
			&\dot X(t)=V(t),\quad  &X(0)= x, \\
			&\dot V(t)=L[f](t,X(t),V(t)),\quad & V(0)= v,
		\end{aligned}\right.
	\end{align}
	and
	\begin{align}
		\left\{\begin{aligned} \label{D-1-2}
			&\dot X_{\star}(t)= V_{\star}(t),\quad  & X_{\star}(0)= x_{\star}, \\
			&\dot V_{\star}(t)=L[f](t,X_{\star}(t),V_{\star}(t)),\quad & V_{\star}(0)= v_{\star}.
		\end{aligned}\right.
	\end{align}

\subsubsection{Weak velocity alignment} \label{sec:4.1.1} Since the derivation is very lengthy, we split its proof into several steps. \newline

\noindent $\bullet$~{\bf Step B.1 (Identification of an effective region)}: Recall that the kinetic density $f(t)$ can have a full phase space $\bbr^{2d}$ as its support, hence particles can spread out in phase space. However, thanks to the decaying properties of $f$ in phase space, most of mass will be concentrated around some time-varying region and the rest of mass can be controlled to be small outside this time-varying region. In the sequel, we call this concentration region as an effective region. The motivation for this time-varying region follows from estimates of Corollary \ref{C3.1}:
\[
\int_{B^c_{R_x(t)}  \times \bbr_v^d}   f(t, z) \di z \le \frac{2^{D-1} \mathcal{M}_{p}(f^{\mathrm{in}}, D) (1 + t)^D}{R_x(t)^D}.
\]
To get the time-decay of $ \int_{B^c_{R_x(t)}  \times \bbr_v^d}   f(t, z) \di z $, we need to choose $R_x(t)$ grows super-linearly so that 
\[  \frac{(1 + t)^D}{R_x(t)^D} \to 0 \quad \mbox{as $t \to \infty$}. \]
Hence, as long as we choose a super-linearly growing function $R_x(t)$, the mass of $f$ on the region $B^c_{R_x(t)}  \times \bbr_v^d$ decays to zero as $t \to \infty$. \newline

\noindent For a positive constant $C_1$, we define increasing time-dependent radius $R_x$:
	\[ R_x(t) = C_1(1+ t)^\gamma, \qquad \mbox{for some $\gamma > 1$}. \]
Thus, we define effective time-varying cylindrical regions for one and two-particle phase spaces, respectively:
\[ \Omega_{\mbox{eff}}:= B_{R_x(t)} \times \bbr^d, \qquad  \Omega^2_{\mbox{eff}} := \Big( B_{R_x(t)} \times \bbr^d \Big) \times  \Big( B_{R_x(t)} \times \bbr^d  \Big).
\]
Note that the total mass outside the effective region decays to zero algebraically as $t \to \infty$:
\begin{equation} \label{D-1-2-1}
\int_{|x|\ge R_x(t)} f(t, z) \di z \le   \frac{\mathcal{M}_{p}(f^{\mathrm{in}}, D) (1 + t)^D}{\left(R_x(t)\right)^D} \lesssim \left(1+t\right)^{-D(\gamma-1)}.
\end{equation}

\vspace{0.5cm}

\noindent $\bullet$~{\bf Step B.2 (Velocity alignment functional over an effective region)}: Recall a velocity alignment functional introduced in \cite{k1} and Lemma \ref{L2.2} (iv):
\[  \int_{\mathbb{R}^{2d}} | v- v_c(t) |^2f(t,z) \di z = \int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z. \]
Thus, in order to see the time-decay of the term in L.H.S. of the above relation, it suffices to see the temporal decay of the term in the R.H.S..  By Lemma \ref{L3.2}, one can see that 
	\begin{align}
	\begin{aligned} \label{D-1-3}
	&  \dfrac{\di}{\di t} \int_{\mathbb{R}^{2d}} | v- v_c^{\mathrm{in}}|^2f(t,z) \di z   \\
	& \hspace{1cm} = \frac{\di}{\di t}  \int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \\
	 & \hspace{1cm} =-\kappa\int_{\mathbb{R}^{4d}} |V(t)- V_{\star}(t)|^2 \phi(|X(t)-X_{\star}(t)|) f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z. \\
	\end{aligned}
	\end{align}
Note that to relate the R.H.S. of \eqref{D-1-3} with the velocity alignment functional, we need to take out the factor $ \phi(|X(t)-X_{\star}(t)|)$ by its minimum which is zero. Hence, we need to split the two-phase space into the union of effective regions and the rest of it so that on the effective region, we can take out $ \phi(|X(t)-X_{\star}(t)|)$ by its minimum over the effective region. 

\vspace{0.5cm}

\noindent $\bullet$~{\bf Step B.3 (Estimate of  $ \phi(|X(t)-X_{\star}(t)|)$ over an effective region)}: For a given $t > 0$, consider two arbitrary particle trajectories $X(t)$ and $X_\star(t)$ in the effective region: 
	\[ |X(t)|\le R_x(t), \quad |X_{\star}(t)|\le R_x(t).\]
	We set 
	\[
	 \underline{\phi}_{R_x}(t) :=  \inf\limits_{ x, x_{\star}\in B_{R_x(t)}}\phi(|x-x_{\star}|).
	\]
Then, we use the non-increasing property of $\phi$  to see 	
	\begin{equation} \label{D-2}
	 |X(t)-X_{\star}(t)|\le 2R_x(t) \quad \mbox{and} \quad \underline{\phi}_{R_x}(t)  \ge \phi(2R_x(t))  = \mathcal{O}(1) (1+t)^{-\beta\gamma}.
	\end{equation}

	\vspace{0.5cm}

\noindent $\bullet$~{\bf Step B.4 (Estimate of the derivative over an effective region)}: We return to \eqref{D-1-3} and rewrite the R.H.S. of \eqref{D-1-3}  into the integral over the effective region and the rest of it. More precisely, we have
	\begin{align}\label{V1}
		\begin{aligned}
			&-\int_{\mathbb{R}^{4d}} |V(t)- V_{\star}(t)|^2 \phi(|X(t)-X_{\star}(t)|) f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z \\
			& \hspace{1cm} \leq - \int_{ \Omega^2_{\mbox{eff}}} |V(t)- V_{\star}(t)|^2 \phi(|X(t)-X_{\star}(t)|) f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z \\
			& \hspace{1cm} \leq-  \underline{\phi}_{R_x}(t) \int_{\Omega^2_{\mbox{eff}}} |V(t)- V_{\star}(t)|^2 f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z \\
			& \hspace{1cm} = - \underline{\phi}_{R_x}(t) \int_{\mathbb{R}^{4d}} |V(t)- V_{\star}(t)|^2 f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z  \\
			&  \hspace{1cm} + \underline{\phi}_{R_x}(t) \int_{\mathbb{R}^{2d}} \int_{|X_{\star}(t)|> R_x(t)} |V(t)- V_{\star}(t)|^2 f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z  \\
			&  \hspace{1cm} + \underline{\phi}_{R_x}(t)  \int_{|X(t)|> R_x(t)}  \int_{\mathbb{R}^{2d}} 	 |V(t)- V_{\star}(t)|^2 f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z \\
			&  \hspace{1cm} =: {\mathcal I}_{21} + {\mathcal I}_{22} + {\mathcal I}_{23},
		\end{aligned}
	\end{align}
	where we used the relation:
\[
\Omega^2_{\mbox{eff}} = (B_{R_x(t)} \times \bbr^d) \times (B_{R_x(t)} \times \bbr^d) = \bbr^{4d}  - \bbr^{2d} \times  (B^c_{R_x(t)} \times \bbr^d) -  (B^c_{R_x(t)} \times \bbr^d) \times \bbr^{2d}.    
\]
In the following lemma, we estimate the terms ${\mathcal I}_{2i}$ in \eqref{V1} one by one. 
\begin{lemma} \label{L4.1}
The terms ${\mathcal I}_{2i}$ in \eqref{V1} satisfy the following estimates:
\begin{align*}
\begin{aligned}
& (i)~ {\mathcal I}_{21} = -2 \underline{\phi}_{R_x(t)} \int_{\mathbb{R}^{2d}} |V(t)-v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z. \\
& (ii)~{\mathcal I}_{22} = {\mathcal I}_{23} \leq  \mathcal{O}(1) \left(1+t\right)^{-\frac{D}{2}(\gamma-1)-\beta\gamma}.
\end{aligned}
\end{align*}
\end{lemma}
\begin{proof} 
\noindent (i)~We use $\| f \|_{1} = 1$ and Lemma \ref{L2.2} to find 
\[  \int_{\mathbb{R}^{2d}} (V(t)-v^{\mathrm{in}}_c) f^{\mathrm{in}}(z) \di z  = 0.    \]
Furthermore, we have
\begin{align}\label{I11}
	\begin{aligned}
		{\mathcal I}_{21} &= - \underline{\phi}_{R_x}(t) \int_{\mathbb{R}^{4d}} |V(t)- V_{\star}(t)|^2   f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z \\
		&=-  \underline{\phi}_{R_x}(t)  \int_{\mathbb{R}^{4d}} |V(t)-v^{\mathrm{in}}_c+v^{\mathrm{in}}_c- V_{\star}(t)|^2 f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z   \\
		&=-2  \underline{\phi}_{R_x}(t)  \int_{\mathbb{R}^{2d}} |V(t)-v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z.
	\end{aligned}
\end{align}
\noindent (ii)~Note that 
	\begin{align}\label{I2}
		\begin{aligned}
			{\mathcal I}_{22} &=  \underline{\phi}_{R_x}(t)  \int_{\mathbb{R}^{2d}}\int_{|X_{\star}(t)|> R_x(t)} |V(t)- V_{\star}(t)|^2 f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z	\\
			&\le 2   \underline{\phi}_{R_x}(t)  \int_{\mathbb{R}^{2d}}\int_{|X_{\star}(t)|> R_x(t)}\Big ( |V_{\star}(t)|^2+ |V(t) |^2 \Big) f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z \\
			& =: {\mathcal I}_{221} + {\mathcal I}_{222}.
	\end{aligned}
	\end{align}
Next, we estimate the term ${\mathcal I}_{22i}$ one by one. \newline

\noindent $\bullet$~Case B.1:~We use the Cauchy-Schwarz inequality and Lemma \ref{L3.1} to derive 
	\begin{align}
	\begin{aligned} \label{D-3}
	{\mathcal I}_{221}& = 2   \underline{\phi}_{R_x}(t)  \int_{\mathbb{R}^{2d}}\int_{|X_{\star}(t)|> R_x(t)} |V_{\star}(t)|^2 f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z \\
	& = 2   \underline{\phi}_{R_x}(t)   \int_{|X_{\star}(t)|> R_x(t)} | V_{\star}(t)|^2 f^{\mathrm{in}}(z_{\star}) \di z_\star \\
	&\le 2  \underline{\phi}_{R_x}(t)   \left(\int_{\mathbb{R}^{2d}} |V_*(t)|^4 f^{\mathrm{in}}(z_\star) \di z_\star \right)^{\frac{1}{2}}\left(\int_{|X_{\star}(t)|> R_x(t)}f^{\mathrm{in}}(z_\star) \di z_\star \right)^{\frac{1}{2}}\\
		&\le 2  \underline{\phi}_{R_x}(t)  \left(\mathcal{M}_p(f^{\mathrm{in}}, 4)\right)^{\frac{1}{2}}\left(\int_{|X_{\star}(t)|> R_x(t)}f^{\mathrm{in}}(z_\star) \di z_\star \right)^{\frac{1}{2}}.
	\end{aligned}
	\end{align}
%	Corollary \ref{C3.1}
\noindent $\bullet$~Case B.2:~We use the Fubini theorem and Lemma \ref{L3.1} to find 	
\begin{align}
	\begin{aligned} \label{D-4}
{\mathcal I}_{222} &=2   \underline{\phi}_{R_x}(t)   \int_{\mathbb{R}^{2d}}\int_{|X_{\star}(t)|> R_x(t)} | V(t)|^2  f^{\mathrm{in}}(z) f^{\mathrm{in}}(z_{\star}) \di z_\star \di z     \\
	&=2  \underline{\phi}_{R_x}(t)  \Big( \int_{|X_{\star}(t)|> R_x(t)}f^{\mathrm{in}}(z_{\star}) \di z_\star \Big) \cdot \Big( \int_{\mathbb{R}^{2d}} |V(t)|^2 f^{\mathrm{in}}(z) \di z \Big) \\
	&\leq 2  \underline{\phi}_{R_x}(t)  {\mathcal M}_p(f^{\mathrm{in}}, 2) \Big( \int_{|X_{\star}(t)|> R_x(t)}f^{\mathrm{in}}(z_{\star}) \di z_\star \Big).
	\end{aligned}
	\end{align}
In \eqref{I2}, we combine  \eqref{D-2}, \eqref{D-3}, \eqref{D-4} and Corollary \ref{C3.1} to find the desired estimate:
	\begin{align}\label{nwe-I2}
		\begin{aligned}
			{\mathcal I}_{22} & \le2  \underline{\phi}_{R_x}(t)  \Big[ \left(\mathcal{M}_p(f^{\mathrm{in}},4) \right)^{\frac{1}{2}}\left(\int_{|X_{\star}(t)|> R_x(t)}f^{\mathrm{in}}(z_\star) \di z_\star \right)^{\frac{1}{2}}+ \mathcal{M}_p(f^{\mathrm{in}},2) \int_{|X_{\star}(t)|> R_x(t)} f^{\mathrm{in}}(z_\star) \di z_\star \Big] \\
		 &\le2  \underline{\phi}_{R_x}(t)  \Big[ \left(\mathcal{M}_p(f^{\mathrm{in}}, 4) \right)^{\frac{1}{2}}\left(\frac{2^{D-1} {\mathcal M}_p(f^{\mathrm{in}}, D) (1 + t)^D}{R_x(t)^D}\right)^{\frac{1}{2}}+\mathcal{M}_p(2) \frac{2^{D-1} \mathcal{M}_{p}(f^{\mathrm{in}}, D) (1 + t)^D}{R_x(t)^D} \Big] \\
			&\leq  \mathcal{O}\left(\left(1+t\right)^{-\frac{D}{2}(\gamma-1)-\beta\gamma}\right) \quad \mbox{for any $D>0$.} 
		\end{aligned}
	\end{align}			
\end{proof}
In \eqref{V1}, we combine the estimates in Lemma \ref{L4.1} to find 
	\begin{align}\label{V11}
		\begin{aligned}
			&\dfrac{\di}{\di t} \int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z\\ 
			&\hspace{1cm} \le-2\kappa  \underline{\phi}_{R_x}(t) \int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z +\mathcal{O}(1) \kappa (1+t )^{-(\frac{D}{2}(\gamma-1)+ \beta\gamma)}.\\
		\end{aligned}
	\end{align}
	By Grönwall's lemma, we have 
	\begin{align}\label{V3}
		\begin{aligned}
			&\int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \\ 
			&  \le e^{-2\kappa\int_0^t  \underline{\phi}_{R_x}(s)   \di s}\int_{\mathbb{R}^{2d}} | v- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z + {\mathcal O}(1)  \int_0^te^{-2 \kappa\int_s^t  \underline{\phi}_{R_x}(\tau) \di \tau} \left(1+s\right)^{-(\frac{D}{2}(\gamma-1)+ \beta\gamma)} \di s.\\
			&= e^{ -2 \kappa \int_0^t  \underline{\phi}_{R_x}(s)  \di s}\int_{\mathbb{R}^{2d}} | v- v_c|^2f^{\mathrm{in}}(z) \di z + {\mathcal O}(1)  \int_0^{\frac{t}{2}}e^{-2\kappa \int_s^t  \underline{\phi}_{R_x}(\tau) \di \tau} \left(1+s\right)^{-(\frac{D}{2}(\gamma-1)+ \beta\gamma)} \di s\\
			& \hspace{0.2cm}+ {\mathcal O}(1)  \int_{\frac{t}{2}}^{t}e^{-2 \kappa\int_s^t  \underline{\phi}_{R_x(\tau)} \di \tau} \left(1+s\right)^{-(\frac{D}{2}(\gamma-1)+ \beta\gamma)} \di s\\
			&\le e^{-2\kappa\int_0^t  \underline{\phi}_{R_x}(s) \di s}\int_{\mathbb{R}^{2d}} | v- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z + {\mathcal O}(1) e^{-2\kappa \int_{\frac{t}{2}}^t  \underline{\phi}_{R_x}(\tau) \di \tau} \int_0^{\frac{t}{2}} \left(1+s\right)^{-(\frac{D}{2}(\gamma-1)+ \beta\gamma)} \di s\\
			& \hspace{0.2cm} +\mathcal{O}(1)  \left(\left(1+\frac{t}{2}\right)^{-(\frac{D}{2}(\gamma-1)+ \beta\gamma)}\right)\int_{\frac{t}{2}}^{t}e^{\int_s^t-2 \kappa \underline{\phi}_{R_x}(\tau) \di \tau}\di s.
		\end{aligned}
	\end{align}
On the other hand, we use the relations:	
	\[  \underline{\phi}_{R_x}(s)= \mathcal{O}(1) (1+s)^{-\beta\gamma} \quad \mbox{and} \quad R_x(t) = C_1 (1 + t)^{\gamma} \]
	to find 
	\begin{align}
	\begin{aligned} \label{D-6}
	&(i)~ e^{-2\kappa\int_0^t  \underline{\phi}_{R_x(s)}  \di s}\le e^{-|\mathcal{O}(1)|  (1+t)^{1-\beta\gamma}}, \quad  e^{-2\kappa \int_{\frac{t}{2}}^t  \underline{\phi}_{R_x}(\tau) \di \tau}\le  {\mathcal O}(1) e^{-|\mathcal{O}(1)|  (1+t )^{1-\beta\gamma}}, \\
	&(ii)~\int_0^{\frac{t}{2}} \left(1+s\right)^{-(\frac{D}{2}(\gamma-1)+ \beta\gamma)} \di s  \\
	& \hspace{1cm} =  \begin{cases}
	   \ln (1 + \frac{t}{2}), \quad & \mbox{if}~\frac{D}{2}(\gamma-1)+ \beta\gamma = 1, \\
	  \frac{1}{\frac{D}{2}(\gamma-1)+ \beta\gamma -1} \Big(  1 -  (1 + \frac{t}{2})^{1-(\frac{D}{2}(\gamma-1)+ \beta\gamma)} \Big), \quad & \mbox{if}~ \frac{D}{2}(\gamma-1)+ \beta\gamma \neq 1,
	 \end{cases} \\
	&(iii) \int_s^t  \underline{\phi}_{R_x}(\tau)  \di \tau =  {\mathcal O}(1)  \int_s^t (1 + \tau)^{-(\beta +1) \gamma} \di \tau \\
	& \hspace{3cm} = \frac{{\mathcal O}(1)}{(\beta +1) \gamma -1} 
	\Big((1 + s)^{-(\beta +1) \gamma} - (1 + t)^{-(\beta +1) \gamma}    \Big), \\
	&(iv) \int_{\frac{t}{2}}^{t}e^{\int_s^t-2 \kappa \underline{\phi}_{R_x}(\tau) \di \tau} \di s \leq {\mathcal O}(1).
	 \end{aligned}
	 \end{align}
%	 \widetilde{R_x}(\tau)\widetilde{R_v}(\tau)
Finally, we combine \eqref{V3} and \eqref{D-6} to derive 
\begin{equation} \label{D-7}
\int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \leq {\mathcal O}(1) e^{-|\mathcal{O}(1)|  (1+t)^{1-\beta\gamma}} + {\mathcal O}(1)  (1+ t)^{1-(\frac{D}{2}(\gamma-1)+ \beta\gamma)}. 
\end{equation}
Note that if system parameters $\beta, \gamma$ and $D$ satisfy the following relations:
\[ 
0 <  1- \beta \gamma < \frac{D}{2}(\gamma-1).
\]
The following relation holds:
\[ 
 e^{-|\mathcal{O}(1)|  (1+t)^{1-\beta\gamma}} \ll (1+ t)^{1-(\frac{D}{2}(\gamma-1)+ \beta\gamma)}, \quad \mbox{for}~~t \gg 1, 
\]
and we have the asymptotic velocity alignment:
\begin{equation} \label{D-8}
\int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \lesssim  {\mathcal O}(1)  (1+ t)^{1-(\frac{D}{2}(\gamma-1)+ \beta\gamma)}.
\end{equation}
\subsubsection{Weak spatial cohesion} \label{sec:4.1.2}
In this part, we provide the spatial cohesion estimate  $\eqref{D-1}_2$ of a weak solution. First, we use the Cauchy-Schwarz inequality to see
	\begin{align}\label{X1}
		\begin{aligned}
			&\dfrac{\di}{\di t}\int_{\mathbb{R}^{2d}} |X(t)-v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c |^2f^{\mathrm{in}}(z) \di z \\ 
			& \hspace{0.5cm} =\int_{\mathbb{R}^{2d}}2 \Big \langle X(t)-v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c,  V(t)-v^{\mathrm{in}}_c \Big \rangle f^{\mathrm{in}}(z) \di z \\ 
			& \hspace{0.5cm} \le2\left(\int_{\mathbb{R}^{2d}} |X(t)-v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}\left(\int_{\mathbb{R}^{2d}} |V(t)-v^{\mathrm{in}}_c |^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}\\
			& \hspace{0.5cm} \le2\left(\int_{\mathbb{R}^{2d}} |X(t)-v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}\left(\int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}.
		\end{aligned}
	\end{align}
	This yields
\begin{align*} 
	\dfrac{\di}{\di t} \Big( \int_{\mathbb{R}^{2d}} |X(t)-v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \Big)^{\frac{1}{2}} &\le  \Big( \int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \Big)^{\frac{1}{2}} \\
	&=  {\mathcal O}(1)  (1+ t)^{\frac{1}{2} - \frac{1}{2} \Big(\frac{D}{2}(\gamma-1)+ \beta\gamma \Big)}.
\end{align*}
We integrate the above relation over $t$ to get 
\begin{align}
\begin{aligned} \label{D-9}
&  \left(\int_{\mathbb{R}^{2d}} |X(t)-v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}} \\
& \hspace{1cm} \leq  \left(\int_{\mathbb{R}^{2d}} |X^{\mathrm{in}}- x^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}} + {\mathcal O}(1) \int_0^t (1+ s)^{\frac{1}{2} - \frac{1}{2} \Big(\frac{D}{2}(\gamma-1)+ \beta\gamma \Big)} \di s.
\end{aligned}
\end{align}
If we choose a large $D$ such that 
\[ \frac{1}{2} - \frac{1}{2} \Big (\frac{D}{2}(\gamma-1)+ \beta\gamma \Big) < -1, \quad \mbox{i.e.,} \quad D > \frac{2(3-\beta \gamma)}{\gamma -1}, \]
then, the second term in the right-hand side of \eqref{D-9} is integrable, hence we have
\[
  \left(\int_{\mathbb{R}^{2d}} |X(t)-v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}} \leq \left(\int_{\mathbb{R}^{2d}} |X^{\mathrm{in}}- x^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \right)^{\frac{1}{2}}  + C
\]
for some positive constant $C$. Then, this yields
\[
\int_{\mathbb{R}^{2d}} |X(t)-v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z \leq {\mathcal O}(1) \Big( \int_{\mathbb{R}^{2d}} |X^{\mathrm{in}}- x^{\mathrm{in}}_c|^2f^{\mathrm{in}}(z) \di z + 1 \Big ).
\]
Now, we take a supremum of the above relation over all $t$ to get the spatial cohesion:
\[ \sup\limits_{0\le t< \infty} \int_{\mathbb{R}^{2d}} | x - v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c |^2 f(t, z) \di z <\infty.\]
\begin{remark}\label{RE:4.1}
Below, we provide two comments on the first assertion of Theorem \ref{T2.2}. 
\begin{enumerate}
\item
	If  we take $\gamma=\frac{1}{\beta}$, then we only need $D> \max\left\{\frac{4\beta}{1-\beta},4\right\}$. The above conclusion encompasses the result that velocity has compact support \cite{w2,w6} and relaxes the range of values for the exponent $D$. Note that if $\beta\to1$, we need $D\to\infty$.
\item
	We require the exponent $D\ge4$ since we use the Cauchy-Shwartz inequality 
	\[\sum a_ib_i\le \left(\sum a_i^2\right)^{\frac{1}{2}}\left(\sum b_i^2\right)^{\frac{1}{2}} \]
	in \eqref{D-3} of Lemma \ref{L4.1}. If we use the Hölder inequality 
	\[\sum a_ib_i\le \left(\sum a_i^{l_1}\right)^{\frac{1}{l_1}}\left(\sum b_i^{l_2}\right)^{\frac{1}{l_2}}\]
in \eqref{D-3} of Lemma \ref{L4.1}, the lower bound of $D$ can be improved as 
	\[D> \inf\limits_{l_1>1}\max\left\{\frac{2l_1}{l_1-1}\frac{\beta}{1-\beta},\quad 2l_1\right\}.\]
This shows that as long as the parameter $\beta$ is smaller ($\beta\to0$), we have a lower requirement for the exponent $D$ of the velocity moment ($D\to 2$).
\end{enumerate}
\end{remark}
\subsection{Exponentially decaying distribution class}\label{sec:4.2}
In this subsection, we study the weak mono-cluster flocking estimates of weak solution with exponentially decaying initial distributions:
\[  {\mathcal M}_e(f^{\mathrm{in}},\alpha) =  \int_{\bbr^{2d}} e^{\alpha(|x| + |v|)} f^{\mathrm{in}}(z) < \infty. \]
Then, for $\alpha > 0$, the following estimate holds
\[ \int_{\bbr^{2d}} (|x|^D + |v|^D) f^{\mathrm{in}}(z) \di z \leq C  \int_{\bbr^{2d}} e^{\alpha(|x| + |v|)} f^{\mathrm{in}}(z) \di z, \]
for any $D > 0$. Therefore, $f^{\mathrm{in}}$ itself belongs to a polynomially decaying distribution class. Hence, the analysis in the previous subsection can be applied to derive weak mono-cluster flocking estimates when $\beta<1$.  Now, we return to the third assertion in Theorem \ref{T2.2}. \newline

Suppose that system parameters and  initial datum satisfy
\begin{align*}
\begin{aligned}
& \kappa>1, \quad \alpha > 0, \quad  \beta =1, \quad \quad P_\infty :=\sup\limits_{(x,v)\in{\rm spt}(f^{\mathrm{in}})} |v|<\infty,  \\
&  \int_{\mathbb{R}^{2d}} e^{\alpha | x|} f^{\mathrm{in}}(z) \di z \leq {\mathcal M}_e(f^{\mathrm{in}}, \alpha)  < \infty,
\end{aligned}
\end{align*}
and let $f$ be a weak solution to \eqref{A-1}. Then, we consider the weak velocity alignment and spatial cohesion in the sequel. 

\subsubsection{Weak velocity alignment} \label{sec:4.2.1}
For an exponentially decaying distribution class, we set
	\[	R_x(t):=\left(\frac{1}{\alpha}+1\right)P_\infty +\frac{1}{\alpha} t.\]
Note that the relation \eqref{New-2-1} gives
	\begin{align}\label{C-3-4}
		\int_{|x_{\star}|\ge R_x(t)} f(t,\di  x_{\star},\di  v_{\star})&\le{\mathcal M}_e(f^{\mathrm{in}}, \alpha)e^{\alpha(P_\infty t-R_x(t))}={\mathcal M}_e(f^{\mathrm{in}}, \alpha)e^{- (P_\infty+1) t}.
	\end{align}
	Then, we use the same argument in Section \ref{sec:4.1.1} to find  
\begin{align}\label{V111}
	\begin{aligned}
		&\quad\dfrac{\di}{\di t}\int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(\di  x,\di  v)\\ 
		& \hspace{1cm} \le-2\kappa \underline{\phi}_{R_x}(t) \int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(\di  x,\di  v)+\mathcal{O}(1) e^{- (P_\infty+1) t}.\\
	\end{aligned}
\end{align}
By Grönwall's lemma, we have 
\begin{align}\label{V311}
	\begin{aligned}
		&\int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(\di  x,\di  v)\\ 
		& \hspace{0.5cm} \le e^{-2\kappa \int_0^t  \underline{\phi}_{R_x}(s)  \di s}\int_{\mathbb{R}^{2d}} | v- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(\di  x,\di  v)+ \mathcal{O} (1)  \int_0^{t}e^{-2 \kappa\int_s^t  \underline{\phi}_{R_x}(\tau) \di \tau}e^{- (P_\infty+1) s}  \di s\\
		& \hspace{0.5cm} \le e^{-2\kappa \int_0^t  \underline{\phi}_{R_x}(s) \di s}\left\{\int_{\mathbb{R}^{2d}} | v- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(\di  x,\di  v)+ \mathcal{O} (1)  \int_0^{t}e^{2 \kappa\int_0^s  \underline{\phi}_{R_x}(\tau) \di \tau}e^{- (P_\infty +1) s} \di s\right\}\\
		& \hspace{0.5cm} \le\mathcal{O} (1)  e^{-2\kappa \int_0^t  \underline{\phi}_{R_x}(s) \di s}\\
		& \hspace{0.5cm}\le \mathcal{O}\left((1+t)^{-2\kappa}\right).
	\end{aligned}
\end{align}
Here, we used 
\[e^{2 \kappa\int_0^s  \underline{\phi}_{R_x}(\tau) \di \tau}\le  \mathcal{O}\left((1+s)^{2\kappa}\right)\]
in the third inequality.

