	\vspace{0.2cm}

\subsubsection{Weak spatial cohesion} \label{sec:4.2.2}	
Similar to Section \ref{sec:4.1.2}, we have 
	\begin{align}\label{X22}
		\begin{aligned}
			\quad\dfrac{\di}{\di t}\left(\int_{\mathbb{R}^{2d}} |X(t)-v^{\mathrm{in}}_ct- x^{\mathrm{in}}_c |^2f^{\mathrm{in}}(\di  x,\di  v)\right)^{\frac{1}{2}}\le\left(\int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c |^2f^{\mathrm{in}}(\di  x,\di  v)\right)^{\frac{1}{2}}.
		\end{aligned}
	\end{align}
Then, we can use $\kappa >1$ and \eqref{V311} to derive the desired estimates.

\begin{remark}
	If $\beta < 1$, we can get an exponentially weak flocking behavior when the velocity has compact support and the spatial has exponential decay. This can be seen in \eqref{V311}: 
\begin{align}\label{V312}
	\begin{aligned}
		\int_{\mathbb{R}^{2d}} |V(t)- v^{\mathrm{in}}_c|^2f^{\mathrm{in}}(\di  x,\di  v)&\le\mathcal{O} (1)  e^{-2\kappa \int_0^t  \underline{\phi}_{R_x}(s) \di s} \le \mathcal{O}\left(e^{-2\kappa\mathcal{O}((1+t)^{1-\beta})}\right).
	\end{aligned}
\end{align}
\end{remark}
