\section{Preliminaries} \label{sec: preliminaries}

\subsection{Operator-valued free probability} \label{subsec: operator valued prelim}

We adopt the terminology \emph{tracial von Neumann algebra} to mean a pair $(M,\tau)$ consisting of a von Neumann algebra $M$ and a faithful normal tracial state $\tau\colon M\to \C$. Recall that if $B$ is a von Neumann subalgebra of $M$ then there is a unique faithful normal $\tau$-preserving conditional expectation from $E_{B}: M \to B$. In this case, von Neumann subalgebras $B\subset M_i\subset M$, $i\in I$, are \emph{freely independent over $B$} with respect to $E_B$ if whenever $k \in \N$ and $i_1 \neq i_2 \neq \cdots \neq i_k$ and $x_j \in M_{i_j}$ with $E_{B}[x_j] = 0$, then $E_{B}[x_1 \cdots x_k] = 0$. By precomposing with $E_B$, we may extend any (faithful) normal linear map on $B$ to a (faithful) normal linear map on $M$. We will do this implicitly with any trace on $B$ and operator-valued covariance matrix on $B$ (see Definition~\ref{def: operator valued covariance} below).

We next recall non-crossing partitions and $B$-valued cumulants, combinatorial tools that aid moment computations in $B$-valued free probability. For each $k\in \N$ we denote $[k]:=\{1,\ldots, k\}$, and we let $\mathcal{P}(k)$ and  $\mathcal{NC}(k)$  (resp. $\mathcal{P}_2(k)$ and $\mathcal{NC}_2(k)$) denote the set of partitions and non-crossing partitions (resp. pair partitions and non-crossing pair partitions) on $[k]$; for background, see \cite{Speicher1994}.  
A non-crossing partition can be viewed as a diagram for the composition of some multilinear maps as follows \cite{Speicher1998}.  For $k \in \N$, let $\Lambda_k: M^k \to B$ be a $k$-linear map.  Then for each non-crossing partition $\pi \in \mathcal{NC}(k)$, there is a corresponding $k$-linear map $\Lambda_\pi$ defined recursively as follows:
\begin{itemize}
    \item If $\pi$ has a single block $[k]$, then $\Lambda_\pi = \Lambda_k$.
    \item Suppose that $\pi \in \mathcal{NC}(k)$ and $\{s+1,\dots,s+\ell\}$ is a block of $\pi$, and let $\pi'$ be the partition of $[k - \ell]$ obtained by removing this block and relabeling the remaining indices in increasing order.  Then
    \[
    \Lambda_\pi[x_1,\dots,x_k] = \begin{cases} \Lambda_{\pi'}[x_1,\dots,x_s, \Lambda_\ell[x_{s+1},\dots,x_\ell] x_{\ell+1}, x_{\ell+2},\dots,x_k], & s + \ell < k, \\
    \Lambda_{\pi'}[x_1,\dots,x_s] \Lambda_\ell[x_{s+1},\dots,x_k], & s + \ell = k.
    \end{cases}
    \]
\end{itemize}
Given $B \subseteq M$ tracial von Neumann algebras, the \emph{$B$-valued cumulants} are the unique multilinear maps $K_k: M^k \to B$ satisfying
\begin{equation} \label{eq: moment-cumulant formula}
E_{B}[x_1 \cdots x_k] = \sum_{\pi \in \mathcal{NC}(k)} K_\pi[x_1,\dots,x_k] \text{ for } x_1, \dots, x_k \in M.
\end{equation}
These also can be defined by M{\"o}bius inversion (see \cite{Speicher1998}).  Moreover, the cumulants satisfy
\[
b_0 K_k[x_1 b_1, \dots, x_k b_k] = K_k[b_0 x_1, \dots, b_{k-1} x_k] b_k
\]
for $x_1$, \dots, $x_k \in M$ and $b_0$, \dots, $b_{k+1} \in B$.

Operator-valued semicircular families (see \cite[\S 4.2-4.3]{Speicher1998}, \cite{shlyakhtenko1999valued}) are an analog of multivariate Gaussians for the setting of operator-valued free probability, which are specified in terms of operator-valued covariance matrices. The following definition should be compared with {\cite[Definition 2.1]{shlyakhtenko1999valued} and \cite[Theorem 4.3.1]{Speicher1998}.

\begin{defi} \label{def: operator valued covariance}
Let $(B,\tau)$ be a tracial von Neumann algebra and let $\eta_{i,j}:B\to B$ be normal linear maps for $i,j\in I$. We say that $\eta:=(\eta_{i,j})_{i,j\in I}$ is an \textbf{operator-valued covariance matrix} on $B$ (or a \textbf{$B$-valued covariance matrix}) if for every finite $F \subseteq I$, the map
    \begin{align*}
        \eta_F: B &\to B(\ell^2 I) \otimes B\\
            x &\mapsto \sum_{i,j \in F} e_{i,j} \otimes \eta_{i,j}(x)
    \end{align*}
is completely positive, where $\{e_{i,j}\in B(\ell^2 I)\colon i,j\in I\}$ are the standard matrix units.  We say that $\eta$ is \textbf{$\tau$-symmetric} if
    \[
        \tau(\eta_{i,j}(x) y) = \tau(x \eta_{j,i}(y)) \qquad x,y \in B.
    \]
\end{defi}

Note that in the case of an infinite index set $I$, our definition is more general than that of \cite[Definition 2.1]{shlyakhtenko1999valued}, which essentially demands one also take $F=I$ in the above definition. This more general definition is better suited to our main theorems, since they concern limits that only involve finitely many indices from $I$ at a time.

\begin{defi} \label{def: operator-valued semicirculars}
Let $(M,\tau)$ be a tracial von Neumann algebra with von Neumann subalgebra $B$.
Given a $\tau$-symmetric operator-valued covariance matrix $\eta = (\eta_{i,j})_{i,j \in I}$ on $B$, a tuple $(X_i)_{i\in I} \subset M$ is called a \textbf{$(B,\eta)$-semicircular family}  if
    \begin{align*}
        K_2[X_i, bX_j] &= \eta_{i,j}(b) & \text{for } i,j \in I, b \in B, & \\
        K_k[X_{i_1} b_1,\dots,X_{i_k} b_k] &= 0, & \text{for } i_1, \dots, i_k \in I, b_1, \dots, b_k \in B, & \text{ for } k \neq 2,
    \end{align*}
where $K_k$ are the cumulants associated to $E_B\colon M\to B$.
\end{defi}

Note that by \eqref{eq: moment-cumulant formula}, the joint $B$-valued moments of a $(B,\eta)$-semicircular family are uniquely determined by the cumulant conditions in Definition~\ref{def: operator-valued semicirculars}. A moment characterization of $(B,\eta)$-semicircular family can be found in Lemma~\ref{lem: semicircular partition formula} below. 

The existence of operator-valued semicircular families can be shown as follows.  The case where the index set $I$ is finite fits into Shlyakhtenko's framework.  The $\mathrm{C}^*$-correspondence construction in \cite[Lemma 2.2]{shlyakhtenko1999valued} yields a $(B,\eta)$-semicircular family in a von Neumann algebra $\Phi(B,\eta)$.  In particular, \cite[Lemma 2.10]{shlyakhtenko1999valued} shows that there exists a normal conditional expectation $E_B:\Phi(B,\eta)\to B$, and \cite[Proposition 2.20]{shlyakhtenko1999valued} shows that $\tau \circ E_{B}$ is tracial when $\eta$ is $\tau$-symmetric, and in this case $E_{B}$ is faithful by \cite[Proposition 5.2]{shlyakhtenko1999valued}. Moreover, \cite[Definition 4.2.3]{Speicher1998} implies this family satisfies the cumulant conditions in Definition~\ref{def: operator-valued semicirculars} (see also \cite[Example 2.5]{Lee24}).  Now suppose that $I$ is infinite, and for $F \subseteq I$ finite, let $M_F$ be a tracial von Neumann algebra generated by a $(B,\eta|_F)$-semicircular family $(X_{F,i})_{i \in F}$.  For $F \subseteq F'$, the joint distribution of $(B,(X_{F',i})_{i \in F})$ is the same as that of $(B,(X_{F,i})_{i \in F})$, so we obtain a trace-preserving inclusion $M_F \to M_{F'}$.  Let $M$ be the inductive limit of the $M_F$'s over finite $F \subseteq I$, and let $X_i$ be the common image of $X_{F,i}$ in $M$.  Then $(X_i)_{i \in I}$ is a $(B,\eta)$-semicircular family.

\subsection{{$\eta$}-Gaussian random matrix ensembles} \label{subsec: eta Gaussian ensemble}

In order to give a matrix model for operator-valued semicirculars, it is natural to define Gaussian random matrix models associated to operator-valued covariance matrices where the base algebra $B$ is the $n \times n$ matrix algebra $\mathbb{M}_n$.

\begin{prop} \label{eta-GUE exists}
Let $\eta = (\eta_{i,j})_{i,j \in I}$ be a $\tr_n$-symmetric operator-valued covariance matrix on $\mb{M}_n$.  Then there is a jointly Gaussian family $\{X_i\colon i\in I\}$ of random $n \times n$ self-adjoint matrices with mean zero that satisfy
\begin{equation} \label{eq: matrix covariance}
\E[X_i a X_j] = \eta_{i,j}(a) \qquad a\in \mb{M}_n.
\end{equation}
The distribution of the family $\{X_i\colon i\in I\}$ is uniquely determined by $\eta$.
\end{prop}

\begin{proof}
By the Kolmogorov extension theorem, it suffices to the prove the claim when the index set $I$ is finite.  In general, to obtain existence of a jointly Gaussian family of real random variables, one only has to specify a positive semi-definite covariance matrix (here ``covariance matrix'' is meant in the usual sense in probability theory as opposed to ``operator-valued covariance matrix'').  Since $X:=(X_i)_{i\in I}$ should be a random variable in the real vector space $(\mathbb{M}_n)_{\sa}^{\oplus I}$, using the Hilbert--Schmidt inner product with respect to $\Tr_n$, the covariance matrix should be a positive semi-definite operator $T$ on  $(\mathbb{M}_n)_{\sa}^{\oplus I}$.  To translate \eqref{eq: matrix covariance} into a covariance matrix, recall that for a completely positive map $\eta: \mathbb{M}_n \to B(\ell^2 I) \otimes \mathbb{M}_n$, the \emph{Choi matrix} is the element
\[
T = \sum_{i,j \in I} \sum_{k,\ell=1}^n E_{i,j} \otimes \eta_{i,j}(E_{k,\ell}) \otimes E_{k,\ell} \in B(\ell^2 I) \otimes \mathbb{M}_n \otimes \mathbb{M}_n.
\]
Choi's theorem \cite[Theorem 2]{Choi1975} shows that $\eta$ is completely positive if and only if $T \geq 0$.  To view $T$ as a linear transformation of $\mathbb{M}_n^{\oplus I}$, recall that $B(\C^I \otimes \mathbb{M}_n)$ is naturally identified with $B(\ell^2 I) \otimes \mathbb{M}_n \otimes \mathbb{M}_n^{\op}$, where the $B(\ell^2 I)$ acts on $\C^I$, the first $\mathbb{M}_n$ acts on $\mathbb{M}_n$ by left multiplication, and the opposite algebra $\mathbb{M}_n^{\op}$ acts on $\mathbb{M}_n$ by right multiplication.  Moreover, $\mathbb{M}_n$ is isomorphic to $\mathbb{M}_n^{\op}$ by sending $E_{k,\ell}$ to $E_{\ell,k}^{\op}$, so we can write $T$ as
\begin{equation} \label{eq: T definition}
T = \sum_{i,j \in I} \sum_{k,\ell=1}^n E_{i,j} \otimes \eta_{i,j}(E_{k,\ell}) \otimes E_{\ell,k}^{\op} \in B(\ell^2 I) \otimes \mathbb{M}_n \otimes \mathbb{M}_n^{\op}.
\end{equation}
Thus, $T$ is now a nonnegative $\mathbb{C}$-linear transformation of $\C^I \otimes_{\C} \mathbb{M}_n$.  Since we actually want random variables in the real subspace $\R^I \otimes_{\R} (\mathbb{M}_n)_{\sa}$, it remains to show that $T$ leaves this real subspace invariant, or equivalently that $T[A^*] = (T[A])^*$ for $A \in \C^I \otimes_{\C} \mathbb{M}_n$.  Letting $T_{i,j} = \sum_{k,\ell} \eta_{i,j}(E_{k,\ell}) \otimes E_{\ell,k}^{\op}$, it suffices to check that $\Tr_n(T_{i,j}[A^*]B) = \Tr_n(A^* T_{j,i}[B])$, and by linearity it suffices to consider basis elements $E_{s,t}$, $E_{s',t'}$ for $s, t, s', t' \in [n]$.  Using the $\tr_n$-symmetry condition for $\eta$,
\begin{align*}
\Tr_n(T_{i,j}[E_{s,t}^*] E_{s',t'}) &= \sum_{k,\ell \in [n]} \Tr_n(\eta_{i,j}(E_{k,\ell}) E_{t,s} E_{\ell,k} E_{s',t'})\\
&= \Tr_n(\eta_{i,j}(E_{s',s}) E_{t,t'}) \\
&= \Tr_n(E_{s',s} \eta_{j,i}(E_{t,t'})) = \Tr_n(E_{s,s'}^* \eta_{j,i}(E_{t,t'})),
\end{align*}
which evaluates to $\Tr_n(E_{s,t}^* T_{j,i}[E_{s',t'}])$ by a symmetric sequence of manipulations.

Finally, uniqueness holds because the joint distribution of a Gaussian family is determined by its covariance.
\end{proof}

\begin{defi} \label{def: eta-Gaussian}
Let $\eta = (\eta_{i,j})_{i,j \in I}$ be a $\tr_n$-symmetric operator-valued covariance matrix.
An \textbf{$\eta$-Gaussian family} is a tuple $(X_i)_{i\in I}$ of random $n \times n$ self-adjoint matrices whose entries are mean-zero Gaussian random variables satisfying \eqref{eq: matrix covariance}.
We define the \textbf{associated Choi matrix of $\eta$} to be the matrix $T$ as defined in \eqref{eq: T definition}.
\end{defi}

Note that the Choi matrix is the same as the \emph{covariance matrix} of the entries in the usual sense, which is denoted $\Cov(X)$ in \cite{BBvH2023}.  Indeed, considering the case where $|I| = 1$ for simplicity,
\[
\Cov(X)_{s,t;s',t'} = \mathbb{E}[X_{s,t} \overline{X}_{s',t'}] = \mathbb{E}[\Tr_n(E_{s,t}^*X) \Tr_n(X E_{s',t'})] = \Tr_n[E_{s,t}^* T[E_{s',t'}]].
\]



\begin{rem}
The $\eta$-Gaussian family also has the following invariance property:  Suppose that $B \subseteq \mb{M}_n$ is a unital $*$-subalgebra such that $\eta = \eta \circ E_{B} = E_{B} \circ \eta$.  Given a unitary matrix $u\in B' \cap \mb{M}_n$, for all $a\in \mb{M}_n$ one has
    \[
        \E[ (uX_i u^*)a(u X_j u^*)] = u \eta_{ij}(E_{B}[u^*a u]) u^*= \eta_{ij}(E_B[a]) = \eta_{i,j}(a),
    \]
where we have used $E_B[u^* a u]= E_B[a]$. Hence, the $\eta$-Gaussian distribution is invariant under conjugation by unitaries which commute with $B$. 
\end{rem}

Besides the description of Gaussian matrix tuples in terms of the operator-valued covariance $\eta$ and its Choi matrix $T$, Gaussian matrices are often described as a matrix linear combination of classical Gaussians:
\begin{equation} \label{eqn: Gaussian matrix setup BBvH}
    X_i = \sum_{k=1}^m g_k a_{k,i},
\end{equation}
where the $g_k$'s are independent standard normals (see \cite{BBvH2023}).  Taking $|I| = 1$ for simplicity, so $X= \sum_k g_k a_k$, then the operator-valued covariance can be expressed as
\[
\eta(b) = \mathbb{E}[XbX] = \sum_{k=1}^m a_k b a_k,
\]
which means precisely that the $a_{k,i}$'s are a family of Kraus operators for the completely positive map $\eta$.  Choi \cite[Theorem 1]{Choi1975} showed that every completely positive map between matrix algebras admits Kraus operators (which are not unique in general).  The ability to choose self-adjoint Kraus operators corresponds to the property that $\eta$ is $\tr_n$-symmetric (in fact, it is easy to verify this based on the fact that every jointly Gaussian variable in $(\mathbb{M}_n)_{\sa}$ can be expressed in the form \eqref{eqn: Gaussian matrix setup BBvH}).

Hence, overall, we have three equivalent ways to specify a Gaussian random matrix model:
\begin{itemize}
    \item By giving an operator-valued covariance matrix $\eta=(\eta_{i,j})_{i,j\in I}$ that should satisfy $\eta_{i,j}[a] = \mathbb{E}[X_iaX_j]$. 
    \item By giving an operator $T$ on $(\mathbb{M}_n)_{\sa}^{\oplus I}$ specifying covariances of the entries $\Cov((X_i)_{r,s}, (X_j)_{t,u})$ (which is the Choi matrix of $\eta$).
    \item By expressing the matrix model as $X_i = \sum_{k=1}^m g_k a_{k,i}$ where the $g_k$'s are independent normal random variables and the $a_{k,i}$'s are deterministic matrices (which are Kraus operators for $\eta$).
\end{itemize}
The translation between these different viewpoints on a Gaussian matrix also leads to a natural interpretation of random matrix results such as those of \cite{BBvH2023} in terms of operator-valued semicirculars.  Indeed, it is a common technique to compare a Gaussian random matrix $X = \sum_{t=1}^m g_t a_t$ as above with its free counterpart $X_{\operatorname{free}} = \sum_{t=1}^m a_t \otimes s_t \in \mathbb{M}_n \otimes M$ where the $s_t$'s are freely independent semicirculars in a tracial von Neumann algebra $M$.  The matrix $X_{\operatorname{free}}$ can in fact be reformulated as an $\mathbb{M}_n$-valued semicircular operator, and the same holds for several matrix models.

\begin{prop} \label{prop: identifying X free}
Let $X = (X_i)_{i \in I}$ be Gaussian random matrices expressed as
\[
X_i = \sum_{k=1}^m g_k a_{k,i}
\]
for self-adjoint matrices $a_{k,i}$ and independent standard normal random variables $g_k$, and let $\eta=(\eta_{i,j})_{i,j\in I}$ be the corresponding operator-valued covariance matrix $\eta_{i,j}[a] = \mathbb{E}[X_i a X_j]$.  Let $(S_k)_{k=1}^m$ be a free semicircular family in a tracial von Neumann algebra $(M,\tau)$, and let
\[
X_{\operatorname{free},i} = \sum_{k=1}^m a_{k,i} \otimes S_k \in \mathbb{M}_n \otimes M.
\]
Then $X_{\operatorname{free}}=\{X_{\operatorname{free},i}\colon i\in I\}$ is an $(\mathbb{M}_n,\eta)$-semicircular family.
\end{prop}

\begin{proof}
Noting that the expectation from $\mb{M}_n\otimes M$ onto $\mathbb{M}_n$ is given by $\id \otimes \tau$, the free independence and vanishing first moments of $(S_k)_{k=1}^m$ imply all $\mathbb{M}_n$-valued cumulants vanish except those of order two (see \cite[Proposition 9.3.13]{MingoSpeicher} and \cite[Theorem 6.2]{NSS02}). For the order two cumulants we have:
    \[
        K_2[X_{\operatorname{free},i} b, X_{\operatorname{free},j}] = E_{\mathbb{M}_n}[X_{\operatorname{free},i} b X_{\operatorname{free},j}]= \sum_{k=1}^m a_{k,i} b a_{k,j} = \mathbb{E}[X_i b X_j].
    \]
Thus $X_{\operatorname{free}}$ is an $(\mathbb{M}_n,\eta)$-semicircular family.
\end{proof}

\section{Covariance polynomials and laws} \label{sec: covariance laws}

Suppose $(B,\tau)$ is a tracial von Neumann algebra  generated by a tuple ${b}=(b_\omega)_{\omega\in \Omega}$ and equipped with an operator-valued covariance matrix $\eta=(\eta_{i,j})_{i,j\in I}$. In order to conveniently encode $\eta$, we will consider the smallest $*$-subalgebra of $B$ that is invariant under the $\eta_{i,j}$'s and contains each $b_\omega$. Formally, this $*$-subalgebra is spanned by monomials in ${b}$ that are interspersed with (potentially iterated) applications of the $\eta_{i,j}$ (e.g. $b_{\omega_1}\eta_{i_1,j_1}(b_{\omega_2} \eta_{i_2,j_2}(b_{\omega_3}) b_{\omega_4})  b_{\omega_5}$). We call the elements of this $*$-subalgebra \emph{covariance polynomials} due to the relation $E_B(X_i b X_j) = \eta_{i,j}(b)$ when $\{X_i : i \in I \}$ is an $(B,\eta)$-semicircular family. We formalize this notion in Section~\ref{subsec:covariance_polynomials} below.  Covariance polynomials were previously used in \cite[\S 2.2]{DGS2021} in the case when there is only a single map $\eta$ which is a conditional expectation onto a subalgebra $D$, and they can be viewed as an operator-valued extension of the trace polynomials that often arise in free probability and random matrices \cite{Cebron2013,DHK2013}. 

Like non-commutative polynomials, covariance polynomials admit a natural abstraction that can be evaluated in any concrete setting $(B,\eta)$ as above. We define a \emph{covariance law} to be a positive state on the abstract space of covariance polynomials, and the space of such laws is studied in Section~\ref{subsec:covariance_laws}. It is shown that, up to a boundedness condition, all such laws arise from a tracial von Neumann algebra equipped with an operator-valued covariance matrix (see Proposition~\ref{prop:concrete_covariance_laws}). This implies, for instance, that $B$, $\tau$, and $\eta$ from Theorem~\ref{introthm: weak convergence} are all guaranteed to exist by the assumptions on the finite-dimensional data (see Proposition~\ref{prop: base algebra}). We also note that pointwise convergence in the space of covariance laws provides a convenient formalism for the weak convergence of covariance polynomials.



\subsection{Covariance polynomials}\label{subsec:covariance_polynomials}


In order to define covariance polynomials, we adapt the formalism of \cite[Section 9.1]{MingoSpeicher}. 

\begin{defi} \label{def: cov monomial}
Let $A$ be a unital algebra equipped with a family of linear maps $\eta_{i,j}\colon A\to A$, $i,j\in I$. Fix $k \geq 1$. 
    We define $\eta_{\pi, \vec{\imath}}[a_1,\ldots,a_{2k-1}]$ for a partition $\pi \in \mathcal{NC}_2(2k)$ and a tuple of indices $\vec{\imath} = (i_1, \ldots, i_{2k})\in I^{2k}$ recursively as follows:
\begin{itemize}
    % \item For $k = 2$, and $\pi = \{ \{1\}, \{2\} \}$, we have $\Lambda(\eta,\pi,\vec{\imath})[b] = b$.
    \item For $k = 1$ and $\pi = \{\{1,2\}\}$, we have $\eta_{\pi, i}[a_1] = \eta_{i_1,i_2}(a_1)$.
    % \item For $k > 2$, if $\{j \} \in \pi$, then $\Lambda(\eta,\pi,\vec{\imath})[b]$ is simply the multiplication of the two halves of $\pi$ separated by $j$:
    % \[
        % \Lambda(\eta, \, \pi \restriction_{[j-1]}, \, \vec{\imath} \restriction_{[j-1]} )[b_1,\dots,b_{j-2},b_{j-1}] \cdot b_j \cdot \Lambda(\eta, \, \pi \restriction_{\{j+1, \ldots, k\}}, \, \vec{\imath} \restriction_{\{j+1, \ldots, k\}} )[b_{j+1},\dots,b_{k}].
    % \]
    \item For $k > 1$, if $\{j,j+1\} \in \pi$, then $\eta_{\pi, i}[a_1,\ldots, a_{2k-1}]$ is 
    \[
    \eta_{\pi \setminus \{j,j+1\}, \vec{\imath}\setminus\{i_j, i_{j+1}\}}[a_1,\dots,a_{j-2},a_{j-1}\eta_{i_j,i_{j+1}}(a_j)a_{j+1},a_{j+2},\dots,a_{2k-1}],
    \]
    where $\pi \setminus \{j,j+1\}$ and $\vec{\imath}\setminus\{i_j, i_{j+1}\}$ are given by restricting $\pi$ and $\vec{\imath}$ to $[2k]\setminus\{ j,j+1\}$ and reindexing the latter to identify it with $[2(k-1)]$.
\end{itemize}
We also take the convention for $k=0$ that $\eta_{\pi,\vi}=1$ where $\pi$ and $\vi$ are the empty partition and tuple, respectively.
\end{defi}



The above is best illustrated via an example with pictures.

