\begin{defi}\label{defi:covariance_polynomial}
Let $B$ be a von Neumann algebra equipped with an operator-valued covariance matrix $\eta=(\eta_{i,j})_{i,j\in I}$. Given a unital $*$-subalgebra $A\subset B$, a \textbf{covariance polynomial} over $(A,\eta)$ is an element of
    \[
        \text{span}\left\{ a_0 \eta_{\pi,\vec{\imath}}[a_1,\ldots, a_{2k-1}] a_{2k}\ \colon\ k\in \N,\ a_0,\ldots, a_{2k}\in A,\ \pi\in \mathcal{NC}_2(2k),\ \vec{\imath}\in I^{2k} \right\}.
    \]
Given a tuple $b=(b_\omega)_{\omega\in \Omega}\subset B$, a \textbf{covariance polynomial} over $(b,\eta)$ is a covariance polynomial over $(\C\<b\>,\eta)$, and we denote the set of such elements by $\C_\eta\<b\>$. A \textbf{covariance monomial} over $(b,\eta)$ will mean an element of the form
    \[
        m_0(b)\eta_{\pi,\vec{\imath}}[m_1(b),\ldots, m_{2k-1}(b)] m_{2k}(b),
    \]
where $m_0(b),\ldots, m_{2k}(b)$ are monic $*$-monomials over $b$ (possibly of degree zero).
\end{defi}

Note that a covariance monomial $m_0(b)\eta_{\pi,\vec{\imath}}[m_1(b),\ldots, m_{2k-1}(b)] m_{2k}(b)$ can be visualized as in Example~\ref{ex:visualizing_cov_poly}, where $m_0(b)$ and $m_{2k}(b)$ are placed outside of the diagram on the left and right, respectively. Also note that $\C\<b\>\subset \C_\eta \<b\>$, since by convention we can consider empty partitions and tuples.

One can also consider formal covariance polynomials over a tuple of indeterminates $t=(t_\omega)_{\omega\in \Omega}$ and a family of formal linear maps $\Lambda=(\Lambda_{i,j})_{i,j\in I}$ in much the same way that one considers non-commutative $*$-polynomials. For $\pi\in \mathcal{NC}_2(2k)$, $\vec{\imath}\in I^{2k}$, and $p_1(t),\ldots, p_{2k-1}(t)\in \C\<t\>$ the formal expression
    \[
        \Lambda_{\pi,\vi}[p_0(t),\ldots, p_{2k-1}(t)]
    \]
is expanded recursively as in Definition~\ref{def: cov monomial}, and formal covariance polynomials (resp. monomials) and then defined as in Definition~\ref{defi:covariance_polynomial} over $(t,\Lambda)$.


\begin{defi} \label{defi: formal covariance polynomials}
Given index sets $\Omega$ and $I$, we denote by $\C_I\<\Omega\>$ the set of formal covariance polynomials over indeterminates $t=(t_\omega)_{\omega\in \Omega}$ and formal linear maps $\Lambda=(\Lambda_{i,j})_{i,j\in I}$. For a formal covariance polynomial
    \[
        f= \sum_{j=1}^N m_0^{(j)}(t) \Lambda_{\pi_j,\vi_j}[m_1^{(j)}(t),\ldots, m_{2k_j-1}^{(j)}(t)] m_{2k_j}^{(j)}(t),
    \]
the \textbf{depth} of $f$ is the largest number of nested occurences of $\Lambda$, while the \textbf{degree} of $f$ is the largest degree of the $*$-monomials $m_0^{(j)}(t) m_1^{(j)}(t)\cdots m_{2k_j}^{(j)}(t)$, $1\leq j\leq N$. 
\end{defi}

If we visualize a covariance monomial as in Example~\ref{ex:visualizing_cov_poly}, then its depth is simply the largest number of nested intervals. For instance, with $\pi=\pi_1,\pi_2$ as in that example, the depth of $m_0(t)\Lambda_{\pi,\vi}[m_1(t),m_2(t),m_3(t)]m_4(t)$ would be $2$ and $1$, respectively.

Given a tuple $b=(b_\omega)_{\omega\in \Omega}$ in a von Neumann algebra $B$ equipped with an operator-valued covariance matrix $\eta=(\eta_{i,j})_{i,j\in I}$, there is a natural evaluation map 
    \begin{align*}
        \text{ev}_{(b,\eta)}\colon C_I\<\Omega\>&\to C_\eta\<b\>\\
        m_0(t) \Lambda_{\pi,\vi}[m_1(t),\ldots, m_{2k-1}(t)]m_{2k}(t) & \mapsto m_0(b) \eta_{\pi,\vi}[m_1(b),\ldots, m_{2k-1}(b)]m_{2k}(b).
    \end{align*}
Note that this map is well-defined since any formal covariance polynomial only uses finitely many variables $t_\omega$ and maps $\Lambda_{i,j}$ (even when $\Omega$ or $I$ are infinite). We will typically denote $f(b,\eta):=\text{ev}_{(b,\eta)}(f)$ for $f\in \C_I\<\Omega\>$.

We also observe that the set of formal covariance polynomials $C_I\<\Omega\>$ forms a unital $*$-algebra under formal sums and the following operations. For covariance polynomials
    \[
        f_j:=p_0^{(j)}(t)\Lambda_{\pi_j,\vi_j}[p_1^{(j)}(t),\ldots, p_{2k_j-1}^{(j)}(t)] p_{2k_j}^{(j)}(t) \qquad j=1,2,
    \]
define a product by
    \[
        f_1\cdot f_2:= p_0^{(1)}(t)\Lambda_{\pi_1\sqcup \pi_2, \vi_1\sqcup \vi_2}[p_1^{(1)}(t),\ldots, p_{2k_1-1}^{(1)}(t), p_{2k_1}^{(1)}(t)p_0^{(2)}(t),p_1^{(2)}(t),\ldots, p_{2k_2-1}^{(2)}(t)] p_{2k_2}^{(2)}(t),
    \]
where $\pi_1\sqcup \pi_2\in \mathcal{NC}_2(2(k_1+k_2))$ is the partition where the blocks of $\pi_2$ have been translated by $2k_1$, and $\vi_1\sqcup \vi_2\in I^{2(k_1+k_2)}$ is the concatenation of $\vi_1$ and $\vi_2$. The above then can be extended linearly via the distributive law. The involution is defined by
    \[
        \left(p_0(t)\Lambda_{\pi,\vi}[p_1(t),\ldots, p_{2k-1}(t)] p_{2k}(t) \right)^*:= p_{2k}(t)^* \Lambda_{\hat{\pi},\hat{\vi}}[p_{2k-1}(t)^*,\ldots, p_1(t)^*] p_0(t)^*,
    \]
where $\hat{\pi}\in \mathcal{NC}_2(2k)$ is the partition obtained by vertically reflecting $\pi$, and $\hat{\vi}=(i_{2k}, i_{2k-1},\ldots, i_1)$. Under these operations, the evaluation map above becomes a $*$-homomorphism.

Finally, each $\Lambda_{i,j}$ defines a linear map on $\C_I\<\Omega\>$ by
    \[
        \Lambda_{i,j}\left(p_0(t)\Lambda_{\pi,\vi}[p_1(t),\ldots, p_{2k-1}(t)] p_{2k}(t) \right) := \Lambda_{\tilde{\pi},(i)\sqcup\vi \sqcup (j)}[p_0(t), p_1(t),\ldots, p_{2k-1}(t), p_{2k}(t)],
    \]
where $\tilde{\pi}\in \mathcal{NC}_2(2(k+1))$ is the pairing obtained by nesting $\pi$ inside a pairing between the first and last elements, and  $(i)\sqcup\vi \sqcup (j)\in I^{2(k+1)}$ is once again the concatenation. Using this, we also define for each finite subset $F\Subset I$ a linear map $\Lambda_F\colon \C_I\<\Omega\>\to \C_I\<\Omega\>\otimes \mathbb{M}_{|F|}$ by
    \[
        \Lambda_F(f) = (\Lambda_{i,j}(f) )_{i,j\in F} \qquad f\in \C_I\<\Omega\>.
    \]
For $F=\emptyset$, we take the convention that $\Lambda_\emptyset$ is the identity map on $\C_I\<\Omega\>$.





\subsection{The space of covariance laws}\label{subsec:covariance_laws}

We consider here an abstraction of our examples that will be useful later for expressing notions of weak convergence. 


\begin{defi}
For index sets $\Omega$ and $I$, a \textbf{covariance law} over $\C_I\<\Omega\>$ is a linear functional $\mu\colon \C_I\<\Omega\>\to \C$ satisfying the following conditions:
    \begin{itemize}
        \item $\mu(1)=1$; \hfill (\textbf{unital})

        % \item $\mu(f^\sharp_.f)\geq 0$ for all $f\in \C_\bullet\<x_\omega\colon \omega\in \Omega\>$;

        \item $\mu(fg)=\mu(gf)$ for all $f,g\in \C_I\<\Omega\>$; \hfill (\textbf{tracial})

        \item $\mu(\Lambda_{i,j}(f) g) = \mu(f \Lambda_{j,i}(g))$ for all $i,j\in I$ and $f,g\in \C_I\<\Omega\>$; \hfill (\textbf{symmetric})

        \item for each finite subset $F\Subset I$ and $n\in \N$ \hfill (\textbf{completely positive})
            \[
                \mu\otimes \tr_{|F|}\otimes \tr_n( (\Lambda_F\otimes I_n)(f^*f) g^*g)\geq 0 
            \]
        for $f\in \C_I\<\Omega\> \otimes \mb{M}_n$ and $g\in \C_I\<\Omega\>\otimes \mb{M}_{|F|}\otimes \mb{M}_n$ .
    \end{itemize}
Consider tuples of positive numbers
    \[
        R:=(R_\omega)_{\omega\in \Omega} \subset (0,\infty) \qquad \text{ and } \qquad S:=(S_{i,j})_{i,j\in I} \subset (0,\infty).
    \]
For a monic $*$-monomial $m(t) = t_{\omega_1}^{\epsilon_1}\cdots t_{\omega_d}^{\epsilon_d}$ with $\epsilon_1,\ldots, \epsilon_d\in \{1,*\}$, denote $R[m(t)] = R_{\omega_1}\cdots R_{\omega_d}$, and set $R[1]=1$.  
We say $\mu$ is \textbf{$(R,S)$-exponentially bounded} if for all covariance monomials one has
    \[
        |\mu( m_0(t) \Lambda_{\pi,\vi}[m_1(t),\ldots, m_{2k-1}(t)] m_{2k}(t))| \leq \prod_{\{j,k\}\in \pi} S_{i_j, i_k} \prod_{j=0}^{2k} R[m_j(t)].
    \]
% for $f=m_0(t)\Lambda_{\pi,\vi}[m_1(t),\ldots, m_{2k-1}(t)] m_{2k}(t)$ with $m_0(t),\ldots, m_{2k}(t)$ $*$-monomials, $F\Subset I$ a finite subset, and $B\in \C_I\<\Omega\>\otimes \mathbb{M}_{|F|}$ one has
%     \[
%         \mu\otimes \tr_{|F|}( B^* \Lambda_F( f^* f) B) \leq S^{2p+1} R[m_0(t)\cdots m_{2k}(t)]^2 \mu\otimes \tr_{|F|}(B^*B),
%     \]
% where $p$ is the number of pairs in $\pi$. 
We denote by $\mathbb{L}^\infty(\Omega,I)$ the set of covariance laws over $\C_I\<\Omega\>$ that are $(R,S)$-exponentially bounded for some functions $(R,S)$.
\end{defi}

Let $B$ be a von Neumann algebra equipped with a faithful normal tracial state $\tau$ and a $\tau$-symmetric operator-valued covariance matrix $\eta=(\eta_{i,j})_{i,j\in I}$.  For any tuple $b=(b_\omega)_{\omega\in \Omega} \subset B$, consider the map $\tau_{(b,\eta)}\colon \C_I\<\Omega\>\to \C$ defined by
    \[
        \tau_{(b,\eta)}(f):= \tau( f(b,\eta)) \qquad f\in \C_I\<\Omega\>,
    \]
where we recall that $f(b,\eta) = \text{ev}_{(b,\eta)}(f)$ from the previous section. It is straightforward to verify that $\tau_{(b,\eta)}$ is a covariance law over $\C_I\<\Omega\>$. Moreover, if we set
    \[
        R_\omega:= \|b_\omega\|,\ \omega\in \Omega \qquad \text{ and } \qquad S_{i,j}:= \|\eta_{i,j}\|,\ i,j\in I,
    \]
then $\tau_{(b,\eta)}$ is $\left( (R_\omega)_{\omega\in \Omega}, (S_{i,j})_{i,j\in I} \right)$-exponentially bounded. Thus $\tau_{(b,\eta)}\in \mathbb{L}^\infty(\Omega,I)$. The following proposition tells us that, in fact, every element of $\mathbb{L}^\infty(\Omega,I)$ arises in this way.


\begin{prop}\label{prop:concrete_covariance_laws}
Let $\Omega$ and $I$ be index sets. For every $\mu\in \mathbb{L}^\infty(\Omega,I)$ there exists a von Neumann algebra $B$, a faithful normal tracial state $\tau$ on $B$, a $\tau$-symmetric operator-valued covariance matrix $\eta= (\eta_{i,j})_{i,j\in I}$ on $B$, and a generating tuple $b=(b_\omega)_{\omega\in \Omega}\subset B$ so that $\tau_{(b,\eta)}= \mu$. Moreover, if $\mu$ is $(R,S)$-exponentially bounded, then $\|b_\omega\|\leq R_\omega$ for all $\omega\in \Omega$ and
    \[
        \|\eta_{i,j}\| \leq \left(S_{i,i}^2 + S_{i,j}^2 + S_{j,i}^2 + S_{j,j}^2 \right)^{\frac12},
    \]
for all $i,j\in I$.
\end{prop}
\begin{proof}
Assume that $\mu$ is $(R,S)$-exponentially bounded. Observe that $\C_I\<\Omega\>$ is the free $*$-algebra generated by indeterminates $t_\omega$ for $\omega\in \Omega$ and $\Lambda_{i,j}(f)$ for $i,j\in I$ and covariance monomials $f$, and by definition $\mu$ defines an exponentially bounded law on this free $*$-algebra. (Recall that $\Lambda_\emptyset$ is the identity map by convention so that the positivity of $\mu$ follows from its complete positivity.) Thus if we let $J$ denote the indexing set for these generating indeterminates, then there exists a von Neumann algebra $B$ generated by a tuple $x=(x_j)_{j\in J}$ and admitting a faithful normal tracial state $\tau$ so that $\mu$ equals the law of $x$ with respect to $\tau$ (see \cite[Proposition 5.2.14, Theorem 5.2.24, Corollary 5.2.27]{AGZ2009}). The evaluation map $\text{ev}_x$ composed with the isomorphism $\C_I\<\Omega\>\cong \C\<J\>$ yields a unital $*$-homomorphism
    \[
        \pi\colon \C_I\<\Omega\> \to B
    \]
satisfying
    \begin{align}\label{eqn:expo_bound_to_actual_bound}
        \| \pi\left( m_0(t) \Lambda_{\pi,\vi}[m_1(t),\ldots, m_{2k-1}(t)] m_{2k}(t)\right)\| \leq \prod_{\{j,k\}\in \pi} S_{i_j, i_k} \prod_{j=0}^{2k} R[m_j(t)].
    \end{align}
Let us denote $b_\omega:=\pi(t_\omega)=x_\omega$ for each $\omega\in \Omega \subset J$.

Now, for each $i,j\in I$ and $f\in \C_I\<\Omega\>$, define a linear map on the $*$-algebra $\pi(\C_I\<\Omega\>) = \C\<x\>$ by
    \[
        \eta_{i,j}(\pi(f)):=\pi( \Lambda_{i,j}(f)).
    \]
This is well-defined since if $\pi(f)=0$, then using the symmetry of $\mu$ we have
    \[
        \| \eta_{i,j}(f)\|_\tau^2 = \mu( \Lambda_{i,j}(f)^* \Lambda_{i,j}(f)) = \mu( \Lambda_{j,i}(\Lambda_{i,j}(f)^*) f) = \tau( \pi( \Lambda_{j,i}( \Lambda_{i,j}(f)^*)) \pi(f)  ) =0,
    \]
and hence $\eta_{i,j}(\pi(f))=0$ by the faithfulness of $\tau$. We also define for each finite subset $F\Subset I$ the map
    \[
        \eta_F( \pi(f)) :=( \eta_{i,j}( \pi(f) ) )_{i,j\in F}.
    \]
Using the fact that $L^2(B\otimes \mathbb{M}_{|F|}\otimes \mathbb{M}_n)_+$ is a self-dual cone for all $n\in \N$ with dense subset
    \[
        \{H^* H\colon H\in \pi(\C_I\<\Omega\>)\otimes \mathbb{M}_{|F|}\otimes \mathbb{M}_n\},
    \]
it follows from the complete positivity of $\mu$ that $\eta_F\otimes I_n(\pi(f)^*\pi(f)) \geq 0$ for all $f\in \C_I\<\Omega\>\otimes \mathbb{M}_n$. In particular, $\eta_F(1)$ is a positive element of $B\otimes \mathbb{M}_{|F|}$.

We next show $\|\eta_F( \pi(f) ) \|\leq \| \eta_F(1)\| \| \pi(f)\|$ for all $F\Subset I$ and $f\in \C_I\<\Omega\>$. Indeed, the $2$-positivity of $\eta_F$ on $\mathcal{A}$ implies
    \[
        0 \leq (\eta_F\otimes I_2)\left(\begin{array}{cc} 1 & \pi(f) \\ 0 & 0 \end{array} \right)^* \left(\begin{array}{cc} 1 & \pi(f) \\ 0 & 0 \end{array} \right) = \left(\begin{array}{cc} \eta_F(1) & \eta_F(\pi(f)) \\ \eta_F(\pi(f))^* & \eta_F(\pi(f)^*\pi(f)) \end{array} \right),
    \]
from which it follows that $\eta_F(\pi(f))^*\eta_F(\pi(f)) \leq \|\eta_F(1)\|\eta_F\left(\pi(f)^*\pi(f)\right)$ (see, for example, \cite[Exercise 3.2]{Paulsen2002}). Let  $(g_n)_{n\in \N}\subset \C_I\<\Omega\>$ be a sequence so that $\pi(g_n)$ approximates $(\|\pi(f)\|^2 - \pi(f)^*\pi(f))^{1/2}$ in norm. For $H=( \pi(h_{i,j}) )_{i,j\in F}\in \pi(\C_I\<\Omega\>) \otimes \mb{M}_{|F|}$, the symmetry condition on $\mu$ gives
    \begin{align*}
        \< \eta_F( \|\pi(f)\|^2 - \pi(f)^* \pi(f)) H, H\>_{\tau\otimes \tr_{|F|}} &= \frac{1}{|F|} \sum_{i,j,k\in F} \tau\left( \pi(h_{j,i})^* \eta_{j,k}[\|\pi(f)\|^2 - \pi(f)^* \pi(f)] \pi(h_{k,i}) \right)\\
        &=\frac{1}{|F|} \sum_{i,j,k\in F} \tau\left(  [\|\pi(f)\|^2 - \pi(f)^* \pi(f)] \eta_{k,j}( \pi(h_{k,i} h_{j,i}^*) ) \right)\\
        &= \lim_{n\to\infty} \frac{1}{|F|} \sum_{i,j,k\in F} \tau\left(  \pi( g_n^*g_n ) \eta_{k,j}(\pi( h_{k,i} h_{j,i}^*)) \right)\\
        &= \lim_{n\to\infty} \< \eta_F( \pi( g_n^* g_n) ) H, H\>_{\tau\otimes \tr_{|F|}} \geq 0.
    \end{align*}
Thus $\eta_F( \|\pi(f)\|^2 - \pi(f)^* \pi(f))\geq 0$, and combined with the previous inequality we have
    \[
        \eta_F(\pi(f))^* \eta_F(\pi(f)) \leq \|\eta_F(1)\| \eta_F( \|\pi(f)\|^2) = \|\eta_F(1)\| \eta_F(1) \|\pi(f)\|^2.
    \]
Taking operator norms then gives the claimed inequality.

The above implies that each $\eta_F$, and hence each $\eta_{i,j}$, admits a unique bounded extension to the norm closure of $\pi(\C_I\<\Omega\>)$. In order to show that the $\eta_{i,j}$ can be further extended to normal maps on $B$, we first show they admit $2$-norm bounded extensions to $L^2(B,\tau)$. Fix $i,j\in I$ and observe that $\eta_{i,j}(\pi(f))^* = \pi_{j,i}( \pi(f) ^*)$ for all $f\in \C_I\<\Omega\>$ since $\eta_{\{i,j\}}$ extends to a (completely) positive map on the norm closure of $\pi(\C_I\<\Omega\>)$. This along with the symmetry of $\mu$ gives
    \[
        \| \eta_{i,j}(\pi(f)) \|_\tau^2 = \tau\left( \eta_{j,i}(\pi(f)^*) \eta_{i,j}(\pi(f)) \right) = \tau\left( \pi(f)^* \eta_{i,j}^2( \pi(f) ) \right) \leq \| \pi(f)\|_\tau \| \eta_{i,j}^2( \pi(f) ) \|_\tau.
    \]
Iterating this $d+1$ times we obtain
    \[
        \| \eta_{i,j}( \pi(f))\|_\tau^2 \leq \|\pi(f)\|_\tau^{1+\frac12 + \cdots + \frac{1}{2^d}} \| \eta_{i,j}^{2^{d+1}}( \pi(f) ) \|_\tau^{\frac{1}{2^{d}}}.
    \]
Since $\| \eta_{i,j}^{2^{d+1}}( \pi(f) ) \|_\tau \leq \| \eta_{i,j}^{2^{d+1}}( \pi(f))\| \leq \|\eta_{i,j}\|^{2^{d+1}} \|\pi(f)\|$, it follows that
    \[
        \| \eta_{i,j}(\pi(f))\|_\tau^2 \leq \limsup_{d\to\infty} \|\pi(f)\|_\tau^2 \|\eta_{i,j}\|^{2} \|\pi(f)\|^{\frac{1}{2^d}} = \|\pi(f)\|_\tau^2 \|\eta_{i,j}\|^2.
    \]
Consequently, each $\eta_{ij}$ extends to a bounded map on $L^2(M,\tau)$. For $a\in B$, we claim that $\eta_{i,j}(a)\in B$. Indeed, let $(f_n)_{n\in \N} \subset \C_I\<\Omega\>$ be a sequence satisfying $\|\pi(f_n)\| \leq \|a\|$ and $\| \pi(f_n) - a \|_\tau \to 0$. Then $( \eta_{i,j}( \pi(f_n) ) )_{n\in \N}$ converges to $\eta_{i,j}(a)$ in $2$-norm, but since $\| \eta_{i,j}( \pi(f_n) ) \| \leq \| \eta_{i,j}(1)\| \| a\|$ for all $n\in \N$ it must be that $\eta_{i,j}(a)\in B$ (see \cite[Proposition III.5.3]{TakesakiI}). To see that $\eta_{i,j}$ is normal, it suffices to show that it is weak operator topology continuous on the unit ball of $B$. Restricting to this norm ball further reduces the task to showing $a\mapsto \< \eta_{i,j}(a) \xi, \eta\>_\tau$ is weak operator topology continuous for $\xi,\eta$ varying the dense subspace $\pi(\C_I\<\Omega\>)$. But this is a consequence of the symmetry of $\mu$ since
    \[
        \< \eta_{i,j}(a) \pi(f), \pi(g)\>_\tau = \tau( \pi(g)^* \eta_{i, j}(a) \pi(f) ) = \tau( \eta_{j,i}( \pi(f)\pi(g)^*) a)
    \]
is normal as a map on $a$ for all $f,g\in \C_I\<\Omega\>$. 

Hence each $\eta_{i,j}\colon B\to B$ is normal and therefore $\eta:=(\eta_{i,j})_{i,j}$ forms a $\tau$-symmetric operator-valued covariance matrix on $B$ by inheriting the remaining properties from $\mu$. The equality $\pi(f) = \text{ev}_{(b,\eta)}(f)$ for $f\in \C_I\<\Omega\>$ can be verified by inducting on the depth of $f$, where the base case and induction step use our definitions of $b_\omega$ and $\eta_{i,j}$, respectively. Thus $\tau_{(b,\eta)} = \tau\circ \text{ev}_{(b,\eta)} = \tau\circ \pi = \mu$ by our initial construction of $(B,\tau)$.

Finally, the bound $\|b_\omega\|\leq R_\omega$ follows from (\ref{eqn:expo_bound_to_actual_bound}) applied to the covariance monomial $t_\omega$ for each $\omega\in \Omega$. To see the bound for $\|\eta_{i,j}\|$, $i,j\in I$,  we note that
    \[
        \| \eta_{i,j}\| \leq \| \eta_{\{i,j\}}\| = \| \eta_{\{i,j\}}(1)\| \leq \left( \sum_{k,\ell\in \{i,j\}} \| \eta_{k,\ell}(1)\|^2 \right)^{\frac12} \leq \left( \sum_{k,\ell\in \{i,j\}} S_{k,\ell}^2 \right)^{\frac12},
    \]
where the last inequality follows from (\ref{eqn:expo_bound_to_actual_bound}) applied to the covariance monomials $\Lambda_{k,\ell}(1)$.
\end{proof}

As an application of the previous proposition, we show that $B$, $\tau$, and $\eta$ in Theorem~\ref{introthm: weak convergence} are guaranteed to exist by the assumptions on the finite-dimensional data. We remark that the analogue of this result in the scalar-valued case is that the $n(k)\times n(k)$ identity matrices converge in distribution to the identity of the limiting von Neumann algebra.

\begin{prop} \label{prop: base algebra}
Fix index sets $\Omega, I$ and a sequence of positive integers $(n(k))_{k\in \N}\subset \N$. Further fix for each $k\in \N$ a tuple $b^{(k)}:=(b^{(k)}_\omega)_{\omega\in \Omega}\subset \mb{M}_{n(k)}$ and a $\tr_{n(k)}$-symmetric covariance matrix $\eta^{(k)}=(\eta^{(k)}_{i,j})_{i,j\in I}$ on $\mb{M}_{n(k)}$. Assume $\sup_k \|b_\omega^{(k)}\| <\infty$ for all $\omega\in \Omega$, $\sup_{k} \|\eta_{i,j}^{(k)}\| <\infty$ for all $i,j\in I$, and that
    \[
        \lim_{k\to\infty} \tr_{n(k)}\left[ f(b^{(k)},\eta^{(k)})\right]
    \]
exists for all covariance polynomials $f\in \C_I\<\Omega\>$. Then exists a von Neumann algebra $B$, a faithful normal tracial state $\tau$ on $B$, a $\tau$-symmetric operator-valued covariance matrix $\eta= (\eta_{i,j})_{i,j\in I}$ on $B$, and a generating tuple $b=(b_\omega)_{\omega\in \Omega}\subset B$ so that the above limit is given by $\tau(f(b,\eta))$ for all covariance polynomials $f$.
\end{prop}
\begin{proof}
Define a linear functional $\mu$ on covariance polynomials by
    \[
        \mu(f):= \lim_{k\to\infty} \tr_{n(k)}\left[ f( b^{(k)},\eta^{(k)})\right].
    \]
That $\mu$ is a covariance law follows immediately from the properties of the covariance matrices $\eta^{(k)}$. Moreover, the covariance law determined by $\tr_{n(k)}$ and $\eta^{(k)}$ is $( (\|b_\omega^{(k)}\|)_{\omega\in \Omega}, (\|\eta_{i,j}^{(k)}\|)_{i,j\in I})$-exponentially bounded. So letting
    \[
        R:=\left( \sup_{k\in \N}  \|b_\omega^{(k)}\| \right)_{\omega\in \Omega} \qquad \text{ and } \qquad S:= \left(\sup_{k\in \N} \| \eta_{i,j}^{(k)}(1)\| \right)_{i,j\in I},
    \]
it follows that $\mu$ is $(R,S)$-exponentially bounded. Appealing to Proposition~\ref{prop:concrete_covariance_laws} then completes the proof.
\end{proof}











\section{Proof of weak convergence} \label{sec: weak convergence}

The following notation will be used throughout this section. Let $\eta=(\eta_{i,j})_{i,j\in I}$ be a $\tr_n$-symmetric $\mb{M}_n$-valued covariance matrix and let $X = (X_i)_{i \in I}$ be an $\eta$-Gaussian family.  For each pair partition $\pi \in \mathcal{P}_2(\ell)$ and each $\vec{\imath} = (i_1,\dots,i_\ell)\in I^\ell$, define the $\ell$-tuple $X_{\pi, \vec{\imath}} = \left(X_{\pi,\vec{\imath};r}\right)_{r \in [\ell]}$ as follows.  Let $Y_{\{r,s\}} = \left(Y_{\{r,s\},i}\right)_{i \in I}$ be independent copies of $X$ indexed by the blocks $\{r,s\}\in \pi$.  For each block $\{r,s\}$, set $X_{\pi,\vec{\imath};r} = Y_{\{r,s\},i_r}$ and $X_{\pi,\vec{\imath};s} = Y_{\{r,s\},i_s}$. When $\eta$, $X$, and $X_{\pi,\vec{\imath}}$ are needed over varying matrix algebras $(\mb{M}_{n(k)})_{k\in \N}$, we will decorate them (and their entries) with a superscript: $\eta^{(k)}$, $X^{(k)}$, and $X^{(k)}_{\pi,\vec{\imath}}$.

\subsection{Wick expansion} \label{subsec: Wick expansion}

As usual in random matrix theory, we want to expand moments as a sum over pair partitions using the Wick formula. The following lemma is an immediate consequence of the Wick formula, and is an adaptation of \cite[Corollary 7.4]{BBvH2023} with deterministic matrices $B_j$ inserted between the $X$'s.

\begin{lem} \label{lem: matrix Wick formula}
Let $X$ and $X_{\pi,\vec{\imath}}$ be as above.  Let $b_1$, \dots, $b_{\ell-1}\in \mathbb{M}_n$ be deterministic matrices.  Then
\[
\mathbb{E} [X_{i_1} b_1 X_{i_2} \cdots b_{\ell-1} X_{i_\ell}] = \sum_{\pi \in \mathcal{P}_2(\ell)} \mathbb{E}[X_{\pi,\vec{\imath};1} b_1 X_{\pi,\vec{\imath};2} \cdots b_{\ell-1} X_{\pi,\vec{\imath};\ell}].
\]
\end{lem}

\begin{proof}
It suffices to prove that the left-hand side and right-hand side agree after we apply $\tr_n(\ \cdot\ b_\ell)$ to both sides for an arbitrary deterministic matrix $b_\ell$.  Since $X$ is jointly Gaussian, it can be written as $X_i = \sum_{s=1}^m g_s a_{i,s}$ where $a_{i,s}$ are deterministic matrices and $g_i$ are independent standard normal random variables.  Then by the Wick formula,
    \begin{align*}
        \mathbb{E} \circ \tr_n[X_{i_1} b_1 \cdots b_{\ell-1} X_{i_\ell} b_\ell] &= \sum_{s_1, \dots, s_\ell \in [m]} \mathbb{E}[g_{s_1} \cdots g_{s_\ell}] \tr_n[a_{i_1,s_1} b_1 \cdots a_{i_\ell,s_\ell} b_\ell] \\
        &= \sum_{\pi \in \mathcal{P}_2(\ell)} \sum_{s_1, \dots, s_\ell \in [m]} \prod_{\{u,v\} \in \pi} \Cov(g_{s_u} g_{s_v}) \tr_n[a_{i_1,s_1} b_1 \cdots a_{i_\ell,s_\ell} b_\ell].
    \end{align*}
As for the right-hand side, we can expand $\mathbb{E}[X_{\pi,\vec{\imath};1} b_1 X_{\pi,\vec{\imath},2} \cdots b_{\ell-1} X_{\pi,\vec{\imath},\ell}]$ in the same manner as a sum over partitions $\pi' \in \mathcal{P}_2(\ell)$, and in this case only the partition $\pi' = \pi$ will contribute.  Hence, summing this expression over $\pi$ yields $\mathbb{E} \circ \tr_n[X_{i_1} b_1 \cdots b_{\ell-1} X_{i_\ell} b_\ell]$, as desired.
\end{proof}

The next lemma evaluates the terms corresponding to non-crossing partitions in terms of $\eta$, obtaining the expression analogous to the moments of an operator-valued semicircular operator (see Lemma~\ref{lem: semicircular partition formula}).

\begin{lem} \label{lem: evaluation of NC terms}
Let $X$ and $X_{\pi,\vec{\imath}}$ be as above.  Suppose that $\pi$ is a non-crossing pair partition.  Then for $b_1,\dots,b_{\ell-1} \in \mathbb{M}_{n}$, we have
\[
\mathbb{E}[X_{\pi,\vec{\imath};1} b_1 X_{\pi,\vec{\imath};2} \cdots b_{\ell-1} X_{\pi,\vec{\imath};\ell}] = \eta_{\pi,\vec{\imath}}[b_1,\dots,b_{\ell-1}]. 
\]
\end{lem}
\begin{proof}
We proceed by induction on the number of blocks in the partition.  The case where $\pi$ has one block is immediate from the defining equation (\ref{eq: matrix covariance}) in the definition of an $\eta$-Gaussian family.  Consider a non-crossing pair partition $\pi$ with more than one block.  Recall that an \emph{outer block} is a block that is not nested inside any other block.  Since $\pi$ is non-crossing, if it has more than one outer block, then we can write $\pi$ as the concatenation of two partitions $\pi_1 \in \mathcal{NC}_2(\ell_1)$ and $\pi_2 \in \mathcal{NC}_2(\ell_2)$ with $\ell_1 + \ell_2 = \ell$.  Correspondingly, let $\vec{\imath}_1$ and $\vec{\imath}_2$ be the restrictions of $\vec{\imath}$ to $\{1,\dots,\ell_1\}$ and $\{\ell_1+1,\dots,\ell\}$.  Then the variables $(X_{\pi,\vec{\imath};r})_{r \in \{1,\dots,\ell_1\}}$ and $(X_{\pi,\vec{\imath};r})_{r \in \{\ell_1+1,\dots,\ell\}}$ are independent.  Thus,
    \begin{align*}
        \mathbb{E}[X_{\pi,\vec{\imath};1} & b_1 X_{\pi,\vec{\imath};2} \cdots b_{\ell-1} X_{\pi,\vec{\imath};\ell}] \\
            &= \mathbb{E}[X_{\pi,\vec{\imath};1} b_1 X_{\pi,\vec{\imath};2} \cdots b_{\ell_1-1} X_{\pi,\vec{\imath};\ell_1}] b_{\ell_1} \mathbb{E}[X_{\pi,\vec{\imath};\ell_1+1} b_{\ell_1+1} X_{\pi,\vec{\imath};\ell_1+2} \cdots b_{\ell-1} X_{\pi,\vec{\imath};\ell}] \\
            &= \mathbb{E}[X_{\pi_1,\vec{\imath}_1;1} b_1 X_{\pi_1,\vec{\imath}_1;2} \cdots b_{\ell_1-1} X_{\pi_1,\vec{\imath}_1;\ell_1}] b_{\ell_1} \mathbb{E}[X_{\pi_2,\vec{\imath}_2;1} b_{\ell_1+1} X_{\pi_2,\vec{\imath}_2;\ell_1+2} \cdots b_{\ell-1} X_{\pi_2,\vec{\imath}_2;\ell}] \\
            &= \eta_{\pi_1,\vec{\imath}_1}[b_1,\dots,b_{\ell_1-1}] b_{\ell_1} \eta_{\pi_2,\vec{\imath}_2}[b_{\ell_1+1},\dots,b_\ell] \\
            &= \eta_{\pi,\vec{\imath}}[b_1,\dots,b_\ell],
    \end{align*}
where we have applied the inductive hypothesis to $\pi_1$ and $\pi_2$ and the recursive definition of $\eta_{\pi,\vec{\imath}}$.

On the other hand, if $\pi$ has only one outer block, then $\{1,\ell\} \in \pi$.  Let $\pi' = \{\{r,s\} \subseteq [\ell-2]: \{r+1,s+1\} \in \pi \}$ be the partition on $[\ell-2]$ obtained from the remaining blocks.  Correspondingly, let $\vec{\imath}'$ be the string of indices obtained by restricting to $\{2,\dots,\ell-1\}$.  Recall that $X_{\pi,\vec{\imath};1}$ and $X_{\pi,\vec{\imath};\ell}$ are independent of the other variables.  Let $\mathcal{F}$ be the $\sigma$-algebra generated by $X_{\pi,\vec{\imath};1}$ and $X_{\pi,\vec{\imath};\ell}$.  Hence,
\begin{align*}
\mathbb{E}[X_{\pi,\vec{\imath};1} b_1 X_{\pi,\vec{\imath};2} \cdots b_{\ell-1} X_{\pi,\vec{\imath};\ell}] &= \mathbb{E} [\mathbb{E}[X_{\pi,\vec{\imath};1} b_1 X_{\pi,\vec{\imath};2} \cdots b_{\ell-1} X_{\pi,\vec{\imath};\ell} \mid \mathcal{F}] ] \\
&= \mathbb{E} [X_{\pi,\vec{\imath};1} b_1 \, \mathbb{E}[ X_{\pi,\vec{\imath};2} b_2 \cdots b_{\ell-2} X_{\pi,\vec{\imath};\ell-1} \mid \mathcal{F}] \, b_{\ell-1} X_{\pi,\vec{\imath};\ell} ] \\
&= \mathbb{E} [X_{\pi,\vec{\imath};1} b_1 \, \mathbb{E}[ X_{\pi,\vec{\imath};2} b_2 \cdots b_{\ell-2} X_{\pi,\vec{\imath};\ell-1}] \, b_{\ell-1} X_{\pi,\vec{\imath};\ell} ] \\
&= \eta_{i_1,i_\ell}[b_1 \, \eta_{\pi',\vec{\imath}}[b_2,\dots,b_{\ell-2}] \, b_{\ell-1}] \\
&= \eta_{\pi,\vec{\imath}}[b_1,\dots,b_\ell].\qedhere
\end{align*}
\end{proof}

Thus, the main task to obtain convergence is to bound the terms coming from partitions with crossings.  In the next subsection, we recall the ingredients from \cite{BBvH2023} to estimate this.

\subsection{Bounds for crossing terms} \label{subsec: bounds for crossing}

A key ingredient in the analysis of \cite{BBvH2023} is the \emph{matrix alignment parameter} first introduced by Tropp \cite[\S 3.2]{Tropp2018}.  When $X$ and $X'$ are Gaussian random matrices of mean zero, one defines
\[
w(X,X')^4 = \sup_{U,V,W \in \mathbb{U}_n} \norm{\mathbb{E}[XU\tilde{X}'VXW\tilde{X}'] },
\]
where $\tilde{X}'$ is a copy of $X'$ independent of $X$.  Note that we can just as well replace unitary matrices with any matrices of norm $\leq 1$ since these are the convex hull of the unitary group (see \cite[Proof of Lemma 4.5]{BBvH2023}).  The importance of $w(X,X')$ for is that it can be used to control the contributions of crossings in the expansion of moments of the Gaussian matrix \cite{Tropp2018}.

The alignment parameter $w(X,X')$ is difficult to compute, so \cite{BBvH2023} give practical bounds in terms of more natural parameters.  The first parameter $\sigma(X)$ is given by $\sigma(X)^2 = \norm{\mathbb{E}X^2}$, and in our terminology:
\[
\sigma(X) = \norm*{\sum_{j=1}^m A_j^2 }^{1/2} = \norm*{\mathbb{E} X^2}^{1/2} = \norm*{\eta(1)}^{1/2}.
\]
The second main parameter of \cite{BBvH2023} is defined as $v(X) = \norm{\Cov(X)}^{1/2}$, where $\Cov(X) \in \mathbb{M}_{n^2}$ is the covariance matrix.  In the discussion following Definition~\ref{def: eta-Gaussian} we showed that the covariance matrix is simply the Choi matrix $T$ associated to the completely positive map, and so
\[
v(X) = \norm{\Cov(X)}^{1/2} = \norm{T}^{1/2}.
\]

\begin{prop}[{\cite[Proposition 4.6]{BBvH2023}}]\label{prop: matrix alignment estimate}
For Gaussian matrices $X$ and $X'$ with mean zero, one has
\[
w(X,X')^4 \leq v(X) \sigma(X) v(X') \sigma(X').
\]
\end{prop}

We adapt the matrix alignment parameter to several matrices as follows.

\begin{defi}
Let $\eta = (\eta_{i,j})_{i,j \in I}$ be a $\tr_n$-symmetric $\mb{M}_n$-valued covariance matrix.  Let $X = (X_i)_{i \in I}$ and $X' = (X_i)_{i \in I}$ be independent $\eta$-Gaussian families.  Let $(\mathbb{M}_n)_1$ denote the unit ball in operator norm in $\mathbb{M}_n$.  For $i, j, i', j'$, define
\[
w(\eta,i,j,i',j') = \sup_{U,V,W \in (\mathbb{M}_n)_1} \norm{ \mathbb{E}[X_iUX_{i'}'VX_jWX_{j'}']}^{1/4}
\]
\end{defi}

\begin{lem} \label{lem: matrix alignment estimate 2}
Let $\eta = (\eta_{i,j})_{i,j \in I}$ be a $\tr_n$-symmetric $\mb{M}_n$-valued covariance matrix, and for each finite $F\subseteq I$ let $T_F$ be the Choi matrix associated to $\eta_F=(\eta_{i,j})_{i,j\in F}$.  Then for all $i,j,i',j'\in F$ we have
\[
w(\eta,i,j,i',j')^4 \leq 2 \norm{T_F} \norm{\eta_F(1)}.
\]
\end{lem}

\begin{proof}
Consider the random matrices $Y = X_i \oplus X_j$ and $Y' = X_{i'}' \oplus X_{j'}'$ in $\mathbb{M}_{2n} = \mathbb{M}_2 \otimes \mathbb{M}_n$.  For $U, V, W \in (\mathbb{M}_n)_1$, observe that
\[
\begin{bmatrix} X_iUX_{i'}'VX_jWX_{j'}' & 0 \\ 0 & 0 \end{bmatrix}
=
\begin{bmatrix} X_i & 0 \\ 0 & X_j \end{bmatrix}
\begin{bmatrix} U & 0 \\ 0 & 0 \end{bmatrix}
\begin{bmatrix} X_{i'}' & 0 \\ 0 & X_{j'}' \end{bmatrix}
\begin{bmatrix} 0 & V \\ 0 & 0 \end{bmatrix}
\begin{bmatrix} X_i & 0 \\ 0 & X_j \end{bmatrix}
\begin{bmatrix} 0 & 0 \\ 0 & W \end{bmatrix}
\begin{bmatrix} X_{i'}' & 0 \\ 0 & X_{j'}' \end{bmatrix}
\begin{bmatrix} 0 & 0 \\ I & 0 \end{bmatrix},
\]
and therefore
\[
w(\eta,i,j,i',j')^4 \leq w(Y,Y')^4.
\]
By Proposition~\ref{prop: matrix alignment estimate}, this is bounded by $v(Y) \sigma(Y) v(Y') \sigma(Y')$.  We note that
\[
\sigma(Y)^2 = \norm*{ \mathbb{E}[(X_i \oplus X_j)^2] } = \norm*{\eta_{i,i}(1) \oplus \eta_{j,j}(1)} \leq \norm{\eta_F(1)},
\]
and similarly for $\sigma(Y')$, so that $\sigma(Y) \sigma(Y') \leq \norm{\eta_F(1)}$.  To estimate $v(Y)$,  using the decomposition of $\mathbb{M}_{2n}$ into $2 \times 2$ blocks, we see that
\begin{align*}
\Cov(Y) &= \sum_{s,t \in [2n]} \mathbb{E}[Y E_{s,t} Y] \otimes E_{t,s}^{\op} \in (\mathbb{M}_2 \otimes \mathbb{M}_n) \otimes (\mathbb{M}_2 \otimes \mathbb{M}_n)^{\op} \\
&= \sum_{s,t \in [n]} (E_{1,1} \otimes \eta_{i,i}(E_{s,t})) \otimes (E_{1,1} \otimes E_{t,s})^{\op} \\
& \quad +\sum_{s,t \in [n]} (E_{1,2} \otimes \eta_{i,j}(E_{s,t})) \otimes (E_{2,1} \otimes E_{t,s})^{\op} \\
& \quad +\sum_{s,t \in [n]} (E_{2,1} \otimes \eta_{j,i}(E_{s,t})) \otimes (E_{1,2} \otimes E_{t,s})^{\op} \\
& \quad +\sum_{s,t \in [n]} (E_{2,2} \otimes \eta_{j,j}(E_{s,t})) \otimes (E_{2,2} \otimes E_{t,s})^{\op} 
\end{align*}
Since the $2 \times 2$ matrix $E_{p,q}$ is always paired with $E_{q,p}^{\op}$, the norm of this is the same if we remove the second copy of $E_{q,p}^{\op}$.  This yields the operator $T_0$ corresponding to the completely positive map
\[
\begin{pmatrix}
\eta_{\{i,j\}} =\eta_{i,i} & \eta_{i,j} \\ \eta_{j,i} & \eta_{j,j}
\end{pmatrix}.
\]
In the case that $i \neq j$, $T_0$ is a corner of the operator $T_F$ given by compressing onto the coordinates $i$ and $j$ in $\mb{M}_{|F|}$, and hence $\norm{\Cov(Y)} \leq \norm{T}$.  In the case that $i = j$, $T_0$ is the $2 \times 2$ matrix of all ones tensored with the corner of $T_F$ corresponding to $\eta_{i,i}$, so that $\norm{\Cov(Y)} \leq 2 \norm{T_F}$.  Similarly, $\norm{\Cov(Y')} \leq 2\norm{T_F}$, so overall
\[
v(Y) v(Y') = \norm{\Cov(Y)}^{1/2} \norm{\Cov(Y')}^{1/2} \leq 2 \norm{T_F}.\qedhere
\]
\end{proof}

Next we have the following bound for the terms corresponding to partitions $\pi$ with crossings, which is a direct adaptation of \cite[Lemma 7.5]{BBvH2023} incorporating the deterministic matrices.

\begin{lem}[{Cf. \cite[Lemma 7.5]{BBvH2023}}] \label{lem: estimate for crossing terms}
Let $X$ and $X_{\pi,\vec{\imath}}$ be as above and set $F:=\{i_1,\ldots, i_\ell\}$.  Suppose that the partition $\pi$ has a crossing.  Then for $b_1,\ldots, b_\ell \in \mathbb{M}_{n}$, we have
\[
\left| \mathbb{E} \circ \tr_n[X_{\pi,\vec{\imath};1} b_1 X_{\pi,\vec{\imath};2} \cdots b_{\ell-1} X_{\pi,\vec{\imath};\ell} b_\ell] \right| \leq 2 \norm{T_F} \norm{\eta_F(1)} \norm{b_1} \cdots  \norm{b_\ell} \max_{i\in F} \mathbb{E} \tr_n(|X_i|^{\ell-4}).
\]
%Furthermore, assuming that $(\log n(k))^3 \norm{T} \to 0$, there is a constant
\end{lem}

\begin{proof}
First, we observe the following estimate for a monomial, which follows from the non-commutative H{\"o}lder's inequality applied to $L^\infty(\Omega) \otimes \mathbb{M}_{n}$:
    \begin{equation} \label{eq: NC Holder estimate}
        (\mathbb{E} \tr_{n} |X_{i_1} b_1 \cdots X_{i_\ell} b_\ell|^p)^{1/p} \leq \prod_{t=1}^\ell \norm{b_t}  (\mathbb{E} \tr_n |X_{i_t}|^{\ell p})^{1/\ell p} \leq \prod_{t=1}^\ell \norm{b_t} \max_{i\in F} (\mathbb{E} \tr_n |X_{i}|^{\ell p})^{1/p}.
    \end{equation}
 Now suppose that we have a crossing $r_1 < r_2 < s_1 < s_2$ with $\{r_1,s_1\} \in \pi$ and $\{r_2,s_2\} \in \pi$.  By cyclic symmetry of the trace and of partitions, assume without loss of generality that $r_1 = 1$.  Thus, we have
    \[
        X_{\pi,\vec{\imath};1} b_1 X_{\pi,\vec{\imath};2} \cdots b_{\ell-1} X_{\pi,\vec{\imath};\ell} b_\ell = X_{\pi,\vec{\imath},r_1} Y_1 X_{\pi,\vec{\imath},r_2} Y_2 X_{\pi,\vec{\imath};s_1} Y_3 X_{\pi,\vec{\imath};s_2} Y_4,
    \]
where $Y_1$, \dots, $Y_4$ are the products of the intervening terms.  Let $\ell_j$ be the degree of $Y_j$ in the $X_{\pi,\vec{\imath}}$'s, so that $\ell_1 + \cdots + \ell_4 = \ell - 4$.  Let $p_j = (\ell - 4) / \ell_j$, so that $1/p_1 + \cdots + 1/p_4 = 1$. 
 Note that the $Y_j$'s are independent of $X_{\pi,\vec{\imath},r_1}$, $X_{\pi,\vec{\imath},r_2}$, $X_{\pi,\vec{\imath};s_1}$, $X_{\pi,\vec{\imath};s_2}$, and so by adapting \cite[Lemma 4.5]{BBvH2023} to this setting, we obtain
 \[
|\mathbb{E} \tr_n[X_{\pi,\vec{\imath},r_1} Y_1 X_{\pi,\vec{\imath},r_2} Y_2 X_{\pi,\vec{\imath};s_1} Y_3 X_{\pi,\vec{\imath};s_2} Y_4] | \leq w(\eta,i_{r_1},i_{s_1},i_{r_2},i_{s_2})^4 \prod_{t=1}^4 (\mathbb{E} \tr_n |Y_t|^{p_t} )^{1/p_t}.
 \]
Applying Lemma \ref{lem: matrix alignment estimate 2} to the $w$ term and applying \eqref{eq: NC Holder estimate} to the $Y_t$'s, we can bound this by
\begin{align*}
 2 \norm{T_F} \norm{\eta_F(1)} \norm{b_1} \cdots \norm{b_\ell} \prod_{t=1}^4 \max_{i\in F} (\mathbb{E} \tr_n |X_{i}|^{\ell_t p_t})^{1/p_t} &= 2 \norm{T_F} \norm{\eta_F(1)} \norm{b_1} \cdots \norm{b_\ell} \prod_{t=1}^4 \max_{i\in I} (\mathbb{E} \tr_n |X_{i}|^{\ell-4})^{1/p_t} \\
&= 2 \norm{T_F} \norm{\eta_F(1)} \norm{b_1} \cdots \norm{b_\ell} \max_{i\in F} (\mathbb{E} \tr_n |X_{i}|^{\ell-4}). \qedhere
\end{align*}
\end{proof}

\subsection{Convergence in expectation} \label{subsec: weak convergence in expectation}

With the estimates for the crossing terms in hand, we are now ready to prove convergence in expectation.  To bound the right-hand side from Lemma~\ref{lem: estimate for crossing terms}, we only need some a priori bound on $\max_{i\in F} \mathbb{E} \tr_n(|X_i^{(k)}|^{\ell-4})$.  Hence, we recall the following moment bound from \cite{BBvH2023}, translated into our notation.

\begin{thm}[{\cite[Theorem 2.7]{BBvH2023}}] \label{thm: BBvH moment bound}
Let $\eta: \mathbb{M}_n \to \mathbb{M}_n$ be completely positive, let $X$ be an $\eta$-Gaussian random matrix, and let $T$ be the Choi matrix of $\eta$.  Let $X_{\operatorname{free}}$ be an $(\mathbb{M}_n,\eta)$-semicircular.  Let $p \in \N$.  Then
\[
|(\mathbb{E} \tr_n(X^{2p}))^{1/2p} - \tau(X_{\operatorname{free}}^{2p})^{1/2p}| \leq 2 p^{3/4} (v(X) \sigma(X))^{1/2} = 2 p^{3/4} \norm{\eta(1)}^{1/4} \norm{T}^{1/4}.
\]
\end{thm}

\begin{cor} \label{cor: moment bound}
Let $\eta: \mathbb{M}_n \to \mathbb{M}_n$ be completely positive, let $X$ be an $\eta$-Gaussian random matrix, and let $T$ be the Choi matrix of $\eta$.  Then for $p \in \N$,
\[
(\mathbb{E} \tr_n(X^{2p}))^{1/2p} \leq 2 \norm{\eta(1)}^{1/2} + 2 p^{3/4} \norm{\eta(1)}^{1/4} \norm{T}^{1/4}. 
\]
\end{cor}

\begin{proof}
Since $X_{\operatorname{free}}$ is an $(\mathbb{M}_n,\eta)$-semicircular family by Proposition~\ref{prop: identifying X free}, it follows that $\norm{X_{\operatorname{free}}} \leq 2 \norm{\eta(1)}^{1/2}$ (see \cite[Equation (2.8)]{shlyakhtenko1999valued}).  Therefore,
\[
\tau(X_{\operatorname{free}}^{2p})^{1/2p} \leq \norm{X_{\operatorname{free}}} \leq 2 \norm{\eta(1)}^{1/2}.
\]
The asserted bound thus follows from Theorem \ref{thm: BBvH moment bound} and the triangle inequality.
\end{proof}

As an intermediate step to showing convergence in expectation for covariance polynomials, we first show show convergence for \emph{non-commutative polynomials} but in \emph{random} approximations for $B$.


\begin{lem} \label{lem: weak convergence part 1}
Let $X$ be a $(B,\eta)$-semicircular family for a tracial von Neumann algebra $(B,\tau)$ generated by $b=(b_\omega)_{\omega\in \Omega}$ and a $B$-valued covariance matrix $\eta=(\eta_{i,j})_{i,j\in I}$. For a sequence of integers $(n(k))_{k\in \N}$, let $\eta^{(k)}=(\eta_{i,j}^{(k)})_{i,j\in I}$ be a $\tr_{n(k)}$-symmetric $\mb{M}_{n(k)}$-valued covariance matrix satisfyng $\sup_k \|\eta_{i,j}^{(k)}\| <\infty$ for each $i,j\in I$. For each finite $F\subseteq I$, and let $T^{(k)}_F$ be the Choi matrix associated to $\eta_F=(\eta_{i,j})_{i,j\in F}$, and assume
\[
    \lim_{k \to \infty} \norm{T^{(k)}}_F = 0.
\]
Let $B^{(k)}=(B_\omega^{(k)})_{\omega \in \Omega}$ be random matrices in $\mathbb{M}_{n(k)}$ such that $\sup_k \mathbb{E} \norm{B_\omega^{(k)}}^m < \infty$ for each $\omega\in \Omega$ and $m \in \N$ and assume that
\[
    \lim_{k\to\infty} \mathbb{E} \tr_{n(k)}[f(\eta^{(k)},B^{(k)})] = \tau(f(\eta,b))
\]
for all covariance polynomials $f\in \C_I\<\Omega\>$. If $X^{(k)}$ is an $\eta^{(k)}$-Gaussian family independent of $B^{(k)}$ and $X$ is a $(B,\eta)$-semicircular family, then for every non-commutative polynomial $p\in \C\<\Omega\sqcup I\>$, we have
\[
\lim_{k \to \infty} \mathbb{E} \tr_{n(k)}[p(B^{(k)}, X^{(k)})] = \tau(p(b,X)).
\]
\end{lem}

\begin{proof}
It suffices to consider a monomial of the form
\[
g_0(B^{(k)}) X_{i_1}^{(k)} g_1(B^{(k)}) \cdots X_{i_\ell}^{(k)} g_\ell(B^{(k)}),
\]
where the $g_t$'s are non-commutative polynomials.   By cyclic symmetry of the trace, we may combine $g_0(B^{(k)})$ with $g_\ell(B^{(k)})$. Set $\vec{\imath}:=(i_1,\ldots, i_\ell)$ and $F:=\{i_1,\ldots, i_\ell\}$.  By conditioning on the value of $B^{(k)}$ and applying Lemma~\ref{lem: matrix Wick formula},
\[
\mathbb{E} \tr_{n(k)}[X_{i_1}^{(k)} g_1(B^{(k)}) \cdots  X_{i_\ell}^{(k)} g_\ell(B^{(k)})] = \sum_{\pi \in \mathcal{P}_2(\ell)} \mathbb{E} \tr_n[X_{\pi,\vec{\imath};1}^{(k)} g_1(B^{(k)}) \cdots X_{\pi,\vec{\imath};\ell}^{(k)} g_\ell(B^{(k)})].
\]
By conditioning on the value of $B^{(k)}$ and applying Lemma \ref{lem: estimate for crossing terms}, if $\pi$ has a crossing, then
\begin{multline*}
|\mathbb{E} \tr_n[X_{\pi,\vec{\imath};1}^{(k)} g_1(B^{(k)}) \cdots X_{\pi,\vec{\imath};\ell}^{(k)} g_\ell(B^{(k)})]| \\
\leq 2 \norm{T_F^{(k)}} \norm{\eta_F^{(k)}(1)} \mathbb{E}\left[ \norm{g_1(B^{(k)})} \cdots \norm{g_\ell(B^{(k)})} \right] \max_{i\in F} \mathbb{E} \tr_{n(k)}(|X_i^{(k)}|^{\ell-4}).
\end{multline*}
By Corollary \ref{cor: moment bound} and H{\"o}lder's inequality, $\max_i \mathbb{E} \tr_n(|X_i^{(k)}|^{\ell-4})$ is bounded as $k \to \infty$. Our norm assumptions then imply the overall contribution from each partition $\pi$ with a crossing vanishes.  Hence, we are left with the contributions from non-crossing partitions, which in turn can be evaluated using Lemma \ref{lem: evaluation of NC terms} to give
    \[
        \lim_{k \to \infty} \left| \mathbb{E} \tr_{n(k)}[X_{i_1}^{(k)} g_1(B^{(k)}) \cdots  X_{i_\ell}^{(k)} g_\ell(B^{(k)})] - \sum_{\pi \in \mathcal{NC}_2(\ell)} \tr_{n(k)}\left[\eta^{(k)}_{\pi,\vec{\imath}}[g_1(B^{(k)}),\dots,g_{\ell-1}(B^{(k)})] g_\ell(B^{(k)})\right] \right| = 0.
    \]
By our assumption of convergence for covariance polynomials then gives
    \begin{align*}
        \lim_{k \to \infty} \tr_{n(k)}\left[\eta^{(k)}_{\pi,\vec{\imath}}[g_1(B^{(k)}),\dots,g_{\ell-1}(B^{(k)})] g_\ell(B^{(k)})\right] &= \tau(\eta_{\pi,\vec{\imath}}[g_1(b),\dots,g_{\ell-1}(b)] g_\ell(b))\\
        &= \tau(X_{i_1} g_1(b) \cdots X_{i_\ell} g_\ell(b)),
    \end{align*}
where the last equality comes from Lemma~\ref{lem: semicircular partition formula}.  Hence, the desired conclusion follows from the triangle inequality.
\end{proof}


\begin{lem} \label{lem: weak convergence part 2}
Consider the same setup and hypotheses as Lemma~\ref{lem: weak convergence part 1}.  Then for every covariance polynomial $f\in \C_I\<\Omega\sqcup I\>$, we have
\[
\lim_{k \to \infty} \mathbb{E} \tr_{n(k)}[f(\eta^{(k)}, B^{(k)}, X^{(k)})] = \tau[f(\eta,b,X)].
\]
\end{lem}

\begin{proof}
It suffices to consider the case where $f$ is a covariance monomial.  In particular, suppose
\[
f(\eta^{(k)}, B^{(k)}, X^{(k)}) = g_0(B^{(k)},X^{(k)}) \eta^{(k)}_{\pi,\vec{\imath}}[g_1(B^{(k)},X^{(k)}), \dots, g_{\ell-1}(B^{(k)},X^{(k)})] g_\ell(B^{(k)},X^{(k)}).
\]
By cyclic symmetry of the trace, absorb $g_0$ into $g_\ell$. Set $\vec{\imath}:=(i_1,\ldots, i_\ell)$ and let $X_{\pi,\vec{\imath}}^{(k)}$ be as defined as at the beginning of this section, and assume that $X_{\pi,\vec{\imath}}^{(k)}$ is independent of $(B^{(k)},X^{(k)})$.  By conditioning and Lemma~\ref{lem: evaluation of NC terms}, we get
    \begin{align*}
\mathbb{E} \tr_{n(k)} &\left[\eta^{(k)}_{\pi,\vec{\imath}}[g_1(B^{(k)},X^{(k)}), \dots, g_{\ell-1}(B^{(k)},X^{(k)})] g_\ell(B^{(k)},X^{(k)})\right] \\
&= \mathbb{E} \tr_{n(k)} [X_{\pi,\vec{\imath};1}^{(k)} g_1(B^{(k)},X^{(k)}) \cdots  X_{\pi,\vec{\imath};\ell}^{(k)} g_\ell(B^{(k)},X^{(k)})].
    \end{align*}
Note that $(X^{(k)},X_{\pi,\vec{\imath}}^{(k)})$ can be viewed as a single Gaussian family indexed by $I \sqcup [\ell]$.  Analogously, let $(X_{\pi,\vec{\imath},t})_{t=1}^\ell$ be given by copies of the appropriate $X_i$'s which are freely independent over $B$ for the distinct blocks of $\pi$, and jointly freely independent over $B$ from $X^{(k)}$.  By \cite[Example 2.6]{shlyakhtenko1999valued}, this is also a $(B,\eta)$-semicircular family indexed by $I \sqcup [\ell]$.  By \cite[Proposition 3.8]{shlyakhtenko2000cpentropy}, $X_{\pi,\vec{\imath}}$ is further an $( W^*(B,X), \eta)$-valued semicircular family.  So using Lemma~\ref{lem: semicircular partition formula} we have
\[
\tau(X_{\pi,\vec{\imath};1} g_1(b,X) \cdots  X_{\pi,\vec{\imath};\ell} g_\ell(b,X)) = \tau( \eta_{\pi,\vec{\imath}}[g_1(b,X),\dots,g_{\ell-1}(b,X)]g_\ell(b,X)).
\]
By Lemma \ref{lem: weak convergence part 1}, we have
\[
\lim_{k \to \infty} \mathbb{E} \tr_{n(k)} [X_{\pi,\vec{\imath};1}^{(k)} g_1(B^{(k)},X^{(k)}) \cdots  X_{\pi,\vec{\imath};\ell}^{(k)} g_\ell(B^{(k)},X^{(k)})] = \tau(X_{\pi,\vec{\imath};1} g_1(b,X) \cdots  X_{\pi,\vec{\imath};\ell} g_\ell(b,X)),
\]
so the proof is complete.
\end{proof}

\subsection{Almost sure convergence} \label{subsec: weak almost sure convergence}

Next, we upgrade from convergence in expectation to almost sure convergence using standard concentration of measure arguments together with non-commutative H{\"o}lder inequalities.

\begin{lem} \label{lem: Herbst}
For a finite set $F$, let $\eta=(\eta_{i,j})_{i,j\in F}$ be a $\tr_n$-symmetric $\mb{M}_n$-valued covariance matrix and let $T$ the associated Choi matrix. Then an $\eta$-Gaussian family $X$ satisfies Herbst's concentration inequality: for all $\delta>0$
%\[
%P( \re f(\mathbf{X}^{(k)}) - \mathbb{E} \re f(\mathbf{X}^{(k)}) \geq \delta) \leq e^{-n(k) \delta^2 / 2 \norm{T^{(k)}} \norm{f}_{\operatorname{Lip}}^2},
%\]
%and
\[
\mathbb{P}\left( \left|f(X) - \mathbb{E}[f(X)]\right| \geq \delta \right) \leq 4 \exp\left(\frac{ -n \delta^2}{2 \norm{T} \norm{f}_{\operatorname{Lip}}^2}\right),
\]
where $\norm{f}_{\operatorname{Lip}}$ is the Lipschitz norm of $f: L^2(\mb{M}_n, \tr_n)^F\to \C$.
\end{lem}

\begin{proof}
We can write $X = T^{1/2} Y$, where $Y$ is a Gaussian random variable in $\mb{M}_{n}^I$ with covariance matrix $I$, the identity in $B(\ell^2(I)) \otimes \mb{M}_{n} \otimes \mb{M}_{n}^{\op}$.  Recall that ${Y}$ satisfies the concentration inequality
    \begin{equation} \label{eq: standard Gaussian concentration}
        \mathbb{P}\left( |g(Y) - \mathbb{E}[g(Y)]| \geq \delta \right) \leq 4 \exp\left(\frac{-\delta^2}{ 2 \norm{g}_{\operatorname{Lip},\Tr_{n}}^2}\right),
    \end{equation}
where $g:  L^2(\mb{M}_n, \Tr_n)^I \to \C$ is Lipschitz with norm $\norm{g}_{\Lip,\Tr_{n}}$ (see, for example, \cite[Corollary 4.1]{BL2000}, \cite[\S 2.3.2]{AGZ2009}).  Now suppose that $f: L^2(\mb{M}_n,\tr_n)^I \to \C$ is Lipschitz with $\norm{f}_{\Lip}$ defined with respect to the Hilbert-Schmidt norm for the \emph{normalized} trace.  Then $f(X) = f \circ T^{1/2} (Y)$ and
\[
\norm{f \circ T^{1/2}}_{\Lip,\Tr_{n}} \leq \norm{f}_{\Lip,\Tr_{n}} \norm{T}^{1/2} = n^{-1/2} \norm{T}^{1/2} \norm{f}_{\Lip,\tr_{n}}.
\]
Hence, taking $g = f \circ T^{1/2}$ in \eqref{eq: standard Gaussian concentration}, we get the asserted estimate.
\end{proof}

Since covariance polynomials under consideration are not globally Lipschitz functions, we need to make an additional cut-off argument, as is also quite standard in random matrix theory.  Although one often does the cut-off by projecting onto the unit ball in operator norm, we will project instead onto the unit ball in some non-commutative $L^p$ norm, since in Theorem~\ref{introthm: weak convergence} we do not assume bounds on $\norm{T_F^{(k)}}$ strong enough to control the operator norms the corresponding $\eta^{(k)}$-Gaussian family.  Hence, we first show the following auxiliary lemma.

\begin{lem} \label{lem: as convergence of p norm}
Consider the same setup as in Theorem~\ref{introthm: weak convergence}, so in particular ${X}^{(k)}$ is an $\eta^{(k)}$-Gaussian family and ${X}$ is a $(B,\eta)$-valued semicircular. For $p \in \N$ and $i\in I$, we have
\[
\lim_{k \to \infty} \tr_n( (X_i^{(k)})^{2p} ) = \tau((X_i)^{2p}) \text{ almost surely.}
\]
\end{lem}

\begin{proof}
Let $f(a) := \norm{a}_{2p} = \tr_n( (a)^{2p} )^{1/2p}$.  Recall that $\norm{a}_{2p} \leq n(k)^{\frac12-\frac{1}{2p}} \norm{a}_2$, so that $f$ is $n(k)^{\frac12-\frac{1}{2p}}$-Lipschitz as a map on $L^2(\mb{M}_{n(k)}, \tr_{n(k)})$. Letting $T_i^{(k)}$ be the Choi matrix associated to $\eta_{i,i}$, Lemma~\ref{lem: Herbst} then implies for $\delta > 0$ that
\[
\mathbb{P}\left( |f(X_i^{(k)}) - \mathbb{E} f(X_i^{(k)})| \geq \delta \right) \leq 4 e^{-n(k)^{1/p} \delta^2 / 2\norm{T_i^{(k)}}}.
\]
We first take $\delta = \norm{T_i^{(k)}}^{1/2}$.  Since $e^{-n(k)^{1/p}/2}$ is summable, the Borel--Cantelli lemma implies that almost surely for sufficiently large $k$, we have
\[
|f(X_i^{(k)}) - \mathbb{E} f(X_i^{(k)})| \leq \norm{T_i^{(k)}}^{1/2},
\]
and hence
\[
\lim_{k \to \infty} [f(X_i^{(k)}) - \mathbb{E} f(X_i^{(k)})] = 0 \quad\text{ almost surely.}
\]
Hence, it suffices to show that
\[
\lim_{k \to \infty} \mathbb{E} \norm{X_i^{(k)}}_{2p} = \norm{X_i}_{2p}.
\]
For the upper bound, note by H{\"o}lder's inequality,
\[
\limsup_{k \to \infty} (\mathbb{E} \norm{X_i^{(k)}}_{2p})^{2p} \leq \lim_{k \to \infty} \mathbb{E} \left( \norm{X_i^{(k)}}_{2p}^{2p} \right) = \tau[(X_i)^{2p}].
\]
For the lower bound, let $M_k = \mathbb{E}\norm{X_i^{(k)}}_{2p}$, and note that
\begin{align*}
\mathbb{E} \norm{X_i^{(k)}}_{2p}^{2p} &= \int_0^\infty 2p t^{2p-1} \mathbb{P}( \norm{X_i^{(k)}}_{2p} \geq t)\,dt \\
&= \int_0^{M_k} 2p t^{2p-1} \mathbb{P}( \norm{X_i^{(k)}}_{2p} \geq t)\,dt +  \int_0^\infty 2p (M_k + \delta)^{2p-1} \mathbb{P}( \norm{X_i^{(k)}}_{2p} \geq M_k + \delta)\,d\delta \\
&\leq M_k^{2p} + \int_0^\infty 2^{2p} p (M_k^{2p-1} + \delta^{2p-1}) e^{-n(k)^{1/p} \delta^2 / 2\norm{T^{(k)}}}\,d\delta \\
&= M_k^{2p} + 2^{2p} M_k^{2p-1} \sqrt{2\pi} \norm{T^{(k)}}^{1/2} n(k)^{-1/2p} + 2^{2p} [(2p-2)(2p-4) \cdots 2] \norm{T^{(k)}}^{p-1} n(k)^{-(p-1)/p}.
\end{align*}
The terms other than $M_k^{2p}$ vanish as $k \to \infty$. 
 Hence,
\[
\norm{X_i}_{2p} = \lim_{k \to \infty} (\mathbb{E} \norm{X_i^{(k)}}_{2p}^{2p}) \leq \liminf_{k \to \infty} M_k = \liminf_{k \to \infty} \mathbb{E} \norm{X_i^{(k)}}_{2p},
\]
which completes the proof.
\end{proof}

Next, we show that the trace of any covariance polynomial is $\norm{\,\cdot\,}_2$-Lipschitz on the product of non-commutative $L^p$-balls for sufficiently large $p$.  As in the case of ordinary trace polynomials, this will follow from the non-commutative H{\"o}lder's inequality.  We first recall the $L^p$ boundedness of $\eta$.

\begin{lem} \label{lem: Lp boundedness}
Let $(B,\tau)$ be a tracial von Neumann algebra equipped with a $\tau$-symmetric operator-valued covariance matrix $(\eta_{i,j})_{i,j\in I}$.  Then for all $x \in B$, $i,j\in I$, and $p \in [1,\infty]$ we have
\[
\norm{\eta_{i,j}(x)}_p \leq \norm{\eta_F(1)} \norm{x}_p
\]
for any finite subset $F\subseteq I$ containing $i,j$.
\end{lem}

\begin{proof}
By non-commutative $L^p$ interpolation \cite{PX2003}, it suffices to prove the bound for $p = 1$ and $p = \infty$.  For $p = \infty$, note that $\norm{\eta_{i,j}(x)} \leq \norm{\eta_F(x)} \leq \norm{\eta_F(1)} \norm{x}$ by complete positivity.  For $p = 1$, let $x, y \in B$.  Using $\tau$-symmetry,
\[
|\tau(\eta_{i,j}(x) y)| = |\tau(x \eta_{j,i}(y))| \leq \norm{x}_1 \norm{\eta_{i,j}(y)} \leq \norm{\eta_F(1)} \norm{x}_1 \norm{y}_\infty.
\]
Thus,
\[
\norm{\eta_{i,j}(x)}_1 = \sup_{\norm{y}_\infty \leq 1} |\tau(\eta_{i,j}(x) y)| \leq \norm{\eta_F(1)} \norm{x}_1,
\]
which completes the $L^1$ case and hence the proof.
\end{proof}

\begin{lem} \label{lem: covariance polynomial Lipschitz}
For a covariance monomial $f\in \C_I\<\Omega\sqcup I\>$, let $p \geq 2(\deg(f) - 1)$ and let $F\subseteq I$ and $G\subseteq \Omega$ be the finite subsets on which $f$ depends.  For $R > 0$ there is some constant $C$ depending only on $f$ and $R$, such that for any tuples $b=(b_\omega)_{\omega\in \Omega}$, $ x = (x_i)_{i\in I}$, and $x'=(x_i')_{i\in I}$ in a tracial von Neumann algebra $(M,\tau)$ equipped with an operator-valued covariance matrix $(\eta_{i,j})_{i,j\in I}$, whenever  
    \[
        \norm{\eta_F(1)} \leq R, \quad \max_{\omega\in G}\norm{b_\omega} \leq R, \quad \max_{i\in F}\norm{x_i}_p \leq R, \quad \text{ and } \quad \max_{i\in F}\norm{x_i'}_p \leq R,
    \]
we have
\[
|\tau(f(\eta,b,x)) - \tau(f(\eta,b,x'))| \leq C \norm{{x} - {x}'}_2.
\]
\end{lem}

\begin{proof}
First, consider the case where
\[
f(b,x) = b_0 x_{i_1} b_1 \cdots x_{i_\ell} b_\ell.
\]
Suppose $p \geq 2(\ell - 1)$ and let $q$ be given by $1/q = 1/2 + (\ell-1) / p$, or $q = 2p / (p + 2(\ell-1))$.  Then
\begin{align*}
\norm{f(b,x') - f(b,x)}_q &\leq \sum_{t=1}^\ell \norm{ b_0 x_{i_1} b_1  \cdots x_{i_{t-1}} b_{t-1} (x_{i_t}' - x_{i_t})  b_t x_{i_{t+1}}' b_{t+1} \cdots x_{i_\ell}' b_\ell}_q \\
&\leq \sum_{t=1}^\ell \norm{b_0} \norm{x_{i_1}}_p \norm{b_1}  \cdots \norm{x_{i_{t-1}}}_p \norm{b_{t-1}} \norm{x_{i_t}' - x_{i_t}}_2  \norm{b_t} \norm{x_{i_{t+1}}'}_p \norm{b_{t+1}} \cdots \norm{x_{i_\ell}'}_p \norm{b_\ell} \\
&\leq \ell R^{2\ell-1} \norm{{x}' - {x}}_2.
\end{align*}
Now suppose that $f$ is a covariance monomial, so that
\[
f =  f_0\eta_{\pi,\vec{\imath}}[f_1,\dots,f_{2k-1}] f_{2k}
\]
where $f_j$ has degree $\ell_j$.  Let $1 / q_j = 1/2 + (\ell_j-1)/p$ and let $1 / r_j = \ell_j / p$.  Let
\[
1/q = 1/2 + (\ell_0+\ell_1 + \cdots + \ell_{2k} - 1)/p = 1/q_j + \sum_{i \neq j} 1/r_i.
\]
Note that $q_j$, $r_j$, and $q \geq 1$.  By switching out the terms $f_j(b,x)$ for $f_j(b,x')$ one by one as above, and by iteratively applying the non-commutative H{\"o}lder's inequality and Lemma~\ref{lem: Lp boundedness}, we have
\begin{multline*}
\norm{f(\eta,b,x') - f(\eta,b,x)}_q \\
\leq \sum_{j=0}^{2k} C_j \norm{f_0(b,x)}_{r_0} \cdots \norm{f_{j-1}(b,x)}_{r_{j-1}} \norm{f_j(b,x') - f_j(b,x)}_{q_j} \norm{f_{j+1}(b,x')}_{r_{j+1}} \cdots \norm{f_{2k}(b,x')}_{r_{2k}} 
\end{multline*}
Then by applying H{\"o}lder's inequality to each of the monomials, $\norm{f_j(b,x)}_{r_j}$ is bounded by a constant.  Also, $\norm{f_j(b,x') - f_j(b,x)}_{q_j}$ is bounded by a constant times $\norm{{x} - {x}'}_2$.  Finally, note
\[
|\tau(f(\eta,b,x')) - \tau(f(\eta,b,x))| \leq \norm{f(\eta,b,x') - f(\eta,b,x)}_q.  \qedhere
\]
\end{proof}

Finally, we complete the proof of almost sure convergence in Theorem~\ref{introthm: weak convergence}.

\begin{thm}[{Theorem~\ref{introthm: weak convergence}}]\label{thm: weak convergence with proof}
Let $(M,\tau)$ be a tracial von Neumann algebra generated by a subalgebra $B\subset M$ and a $(B,\eta)$-semicircular family $x=(x_i)_{i\in I}$, where $\eta=(\eta_{i,j})_{i,j\in I}$ is a $\tau$-symmetric $B$-valued covariance matrix, and let $b=(b_\omega)_{\omega\in \Omega}$ be a generating tuple for $B$. For a sequence of integers $(n(k))_{k\in \N}\subset \N$, let $\eta^{(k)}=(\eta_{i,j}^{(k)})_{i,j\in I}$ be a $\tr_{n(k)}$-symmetric $\mb{M}_{n(k)}$-valued covariance matrix, let $X^{(k)}=(X_i^{(k)})_{i\in I}$ be an $\eta^{(k)}$-Gaussian family, and let $b^{(k)}=(b^{(k)}_\omega)_{\omega\in \Omega}\subset \mb{M}_{n(k)}$. Assume that:
    \begin{itemize}
        \item $\displaystyle\sup_k \|\eta_{i,j}^{(k)}\|<\infty$ for each $i,j\in I$;
        \item $\displaystyle\sup_k \|b_\omega^{(k)}\| <\infty$ for each $\omega\in \Omega$;
        \item $\displaystyle\lim_{k\to\infty} \|T_F^{(k)}\|=0$ for each finite $F\subseteq I$, where $T_F^{(k)}$ is the Choi matrix associated to $\eta_F=(\eta_{i,j})_{i,j\in F}$;
        \item $(\eta^{(k)}, b^{(k)})$ converges weakly in covariance law to $(\eta,b)$.
    \end{itemize}
Then $(\eta^{(k)}, b^{(k)}, X^{(k)})$ converges weakly in covariance law to $(\eta,b,x)$, both almost surely and in expectation.
\end{thm}
\begin{proof}
Convergence in expectation follows by applying Lemma~\ref{lem: weak convergence part 2} to the deterministic matrices $b^{(k)}$, so it remains to prove almost sure convergence.  By linearity, it suffices to show for every covariance monomial $f\in \C_I\<\Omega\sqcup I\>$ that
\[
\lim_{k \to \infty} \tr_{n(k)}[f(\eta^{(k)},{b}^{(k)},{X}^{(k)})] = \tau[f(\eta,{b},x)].
\]
Let $F\subseteq I$ and $G\subseteq \Omega$ be the finite subsets that $f$ depends on.  Choose $p \in \N$ such that $2p \geq 2(\deg(f) - 1)$, and choose $R$ sufficiently large that
\[
\max_{i\in F} \norm{x_i}_{2p} < R, \qquad \sup_k \norm{\eta_F^{(k)}(1)} \leq R, \quad \text{ and } \quad \max_{\omega\in G} \sup_k  \norm{b_\omega^{(k)}} \leq R.
\]
For $a \in \mathbb{M}_{n(k)}$, let
\[
\Pi(a) = \operatorname{argmin}_{a' \in \mathbb{M}_{n(k)}: \norm{a'}_{2p} \leq R} \norm{a - a'}_2.
\]
This is well-defined because $\{a': \norm{a'}_{2p} \leq R\}$ is a closed convex set in the Hilbert space $L^2(\mathbb{M}_{n(k)}, \tr_{n(k)})$ and thus there is a unique closest point to $a$.  Moreover, as a general property of projections onto closed convex sets, we have $\norm{\Pi(a) - \Pi(a')}_2 \leq \norm{a - a'}_2$. 
We will use the same notation $\Pi$ for the coordinate-wise application $\Pi$ to tuples of matrices such as ${X}_i^{(k)}$, so that $\Pi({X}_i^{(k)}) = (\Pi({X}_i^{(k)}))_{i \in I}$.  Let $C$ be a Lipschitz constant for $f$ given by Lemma~\ref{lem: covariance polynomial Lipschitz}.  Then because $\norm{\Pi(a)}_{2p} \leq R$ by construction and $\norm{\Pi(a) - \Pi(a')}_2 \leq \norm{a - a'}_2$, we have that for ${Y}, {Y}' \in (\mathbb{M}_{n(k)})_{\sa}^I$,
\begin{equation} \label{eq: convergence Lipschitz estimate}
|\tr_{n(k)}[f(\eta^{(k)},\Pi({Y}),b^{(k)})] - \tr_{n(k)}[f(\eta^{(k)},\Pi({Y}'),b^{(k)})]| \leq C \norm{{Y} - {Y}'}_2.
\end{equation}
Hence, the composition of $f$ with $\Pi$ in the middle variables is a globally $\norm{\,\cdot\,}_2$-Lipschitz function to which can apply the Herbst concentration inequality.

Now we estimate
\begin{align}
 \tr_{n(k)}[f(\eta^{(k)}, {X}^{(k)},b^{(k)})]& - \tau[f(\eta,x,{b})] \nonumber\\
=& \tr_{n(k)}[f(\eta^{(k)}, {X}^{(k)},b^{(k)})] - \tr_{n(k)}[f(\eta^{(k)}, \Pi({X}^{(k)}),b^{(k)})] 
\label{eq: convergence term 1} \\
&+ \tr_{n(k)}[f(\eta^{(k)}, \Pi({X}^{(k)}),b^{(k)})] - \mathbb{E} \tr_{n(k)}[f(\eta^{(k)}, \Pi({X}^{(k)}),b^{(k)})]
\label{eq: convergence term 2} \\
&+ \mathbb{E} \tr_{n(k)}[f(\eta^{(k)}, \Pi({X}^{(k)}),b^{(k)})] - \mathbb{E} \tr_{n(k)}[f(\eta^{(k)},{X}^{(k)},b^{(k)})] \label{eq: convergence term 3} \\
&+ \mathbb{E} \tr_{n(k)}[f(\eta^{(k)},{X}^{(k)},b^{(k)})] - \tau[f(\eta,{X},{b})].
\label{eq: convergence term 4}
\end{align}
We show that each of the four terms on the right-hand side vanishes almost surely as $k \to \infty$.

By Lemma \ref{lem: as convergence of p norm} and our choice of $R$, we have almost surely for sufficiently large $k$, $\norm{{X}_i^{(k)}}_p < R$ and hence $\Pi({X}_i^{(k)}) = {X}_i^{(k)}$.  Thus, \eqref{eq: convergence term 1} vanishes for sufficiently large $k$.

In light of \eqref{eq: convergence Lipschitz estimate}, \eqref{eq: convergence term 2} is the difference of a Lipschitz function and its expectation.  By the Herbst inequality (Lemma \ref{lem: Herbst}), we have
\[
\mathbb{P}\left(|\tr_{n(k)}[f(\eta^{(k)}, \Pi({X}^{(k)}),b^{(k)})] - \mathbb{E} \tr_{n(k)}[f(\eta^{(k)}, \Pi({X}^{(k)}),b^{(k)})]| \geq C\norm{T^{(k)}}^{1/2} \right) \leq 4 e^{-n(k)/2}.
\]
Since this is summable, the Borel--Cantelli lemma implies that almost surely for sufficiently large $k$,
\[
|\tr_{n(k)}[f(\eta^{(k)}, \Pi({X}^{(k)}),b^{(k)})] - \mathbb{E} \tr_{n(k)}[f(\eta^{(k)}, \Pi({X}^{(k)}),b^{(k)})]| \leq C\norm{T^{(k)}}^{1/2},
\]
and hence \eqref{eq: convergence term 2} vanishes as $k \to \infty$ almost surely.

The third term \eqref{eq: convergence term 3} is minus the expectation of the first term \eqref{eq: convergence term 1}, so we want to apply the dominated convergence theorem to \eqref{eq: convergence term 1}.  Let $\ell = \deg(f)$.  By H{\"o}lder-type estimates as in the proof of Lemma \ref{lem: covariance polynomial Lipschitz}, we can see that for some constant $C'$,
\begin{align*}
|\tr_{n(k)}[f(\eta^{(k)}, {X}^{(k)},b^{(k)})]| &\leq C' (\max_i \norm{X_i^{(k)}}_{2p})^\ell \\
&\leq C' \max_i \max(1, \norm{X_i^{(k)}}_{2p}) \\
&\leq C' \left( 1 + \sum_{i \in I} \tr_{n(k)}[(X_i^{(k)})^{2p}] \right).
\end{align*}
Meanwhile, $\tr_{n(k)}[f(\eta^{(k)}, \Pi({X}^{(k)}),b^{(k)})]$ is bounded, and so after modifying $C'$ if necessary,
\[
\left| \tr_{n(k)}[f(\eta^{(k)}, {X}^{(k)},b^{(k)})] - \tr_{n(k)}[f(\eta^{(k)}, \Pi({X}^{(k)}),b^{(k)})] 
 \right| \leq C' \left( 1 + \sum_{i \in I} \tr_{n(k)}[(X_i^{(k)})^{2p}] \right).
\]
The function on the right-hand side converges almost surely to $C'(1 + \sum_{i \in I} \tau(X_i^{2p})$ by Lemma \ref{lem: as convergence of p norm}, and the expectations also converge to the same limit by Lemma \ref{lem: weak convergence part 2}.  Hence, the hypotheses of the generalized dominated convergence theorem are satisfied, and so
\[
\lim_{k \to \infty} \mathbb{E} \left| \tr_{n(k)}[f(\eta^{(k)}, {X}^{(k)},b^{(k)})] - \tr_{n(k)}[f(\eta^{(k)}, \Pi({X}^{(k)}),b^{(k)})] 
 \right| = 0.
\]
Hence, \eqref{eq: convergence term 3} vanishes as $k \to \infty$.

Finally, \eqref{eq: convergence term 4} is deterministic and vanishes as $k \to \infty$ by Lemma \ref{lem: weak convergence part 2}.
\end{proof}

\section{Proof of strong convergence} \label{sec: strong convergence}

In this section, we prove the general strong convergence result, formally stated in Theorem \ref{thm: strong convergence general}. 

The proof proceeds in several steps:
\begin{itemize}
    \item We use the results of \cite{BBvH2023} to show convergence of the norms of ordinary non-commutative polynomials in ${X}^{(k)}$ and ${b}^{(k)}$.
    \item We show that a covariance polynomial in ${X}$ and ${b}$ can be approximated in operator norm by a non-commutative polynomial in ${X}$, ${b}$, and $B$-freely independent copies of ${X}$, using an averaging trick based on the free LLN.
    \item We then conclude by applying the first step to these polynomials in independent copies of the matrix models and respectively the semicirculars.
\end{itemize}


\subsection{Convergence of operator norms for polynomials} \label{subsec: norms of polynomials}

As sketched above, we first deduce convergence of the operator norms of non-commutative polynomials in ${X}^{(k)}$ and ${b}^{(k)}$ from the results of \cite{BBvH2023}.  We remark that, as usual, the asymptotic lower bounds on $\norm{p(b^{(k)},X^{(k)})}$ are automatic from weak convergence.  The following lemma is well known.

\begin{lem} \label{lem: strong convergence general lower bound}
Let $X^{(k)} = (X_i^{(k)})_{i \in I}$ for $k \in \N$ and $(X_i)_{i \in I}$ be self-adjoint operators in tracial von Neumann algebras $(M^{(k)},\tau^{(k)})$ and $(M,\tau)$ respectively.  Suppose that the law of $X^{(k)}$ converges weakly to the law of $X$.  Then for every non-commutative polynomial, we have $\liminf_{k \to \infty} \norm{p(X^{(k)})} \geq \norm{p(X)}$.
\end{lem}

\begin{proof}
Note that
\begin{align*}
    \norm{p(X)} &= \lim_{m \to \infty} \tau([p(X)^*p(X)]^m)^{1/2m} \\
    &= \sup_{m \in \N} \tau([p(X)^*p(X)]^m)^{1/2m} \\
    &= \sup_{m \in \N} \lim_{k \to \infty} \tau^{(k)}([p(X^{(k)})^*p(X^{(k)})]^m)^{1/2m} \\
    &\leq \sup_{m \in \N} \liminf_{k \to \infty} \norm{[p(X^{(k)})^*p(X^{(k)})]^m}^{1/2m} \\
    &= \liminf_{k \to \infty} \norm{p(X^{(k)})}.  \qedhere
\end{align*}
\end{proof}

Hence, our results on weak convergence (Theorem \ref{introthm: weak convergence}) will allow us to deduce the lower bounds on the operator norms of the random matrices automatically.  We therefore focus our attention on the upper bounds, and show the following.

\begin{prop} \label{prop: strong convergence plain}
Let ${X}^{(k)} = (X_i^{(k)})_{i \in I}$ be Gaussian random matrices with operator-valued covariance $\eta^{(k)}$ and associated Choi matrix $T^{(k)}$.  Assume that
\[
\sup_k \norm{\eta^{(k)}(1)} < \infty, \qquad \lim_{k \to \infty} (\log n(k))^3 \norm{T^{(k)}} = 0.
\]
Let $b^{(k)} = (b_\omega^{(k)})_{\omega \in \Omega}$ be a tuple of deterministic matrices with $\sup_k \norm{b_\omega^{(k)}} < \infty$.

Let $X$ be a $(B,\eta)$-semicircular family, and let $b = (b_\omega)_{\omega \in \Omega}$.

Let $X_{\free}^{(k)}$ be an $(\mathbb{M}_{n(k)},\eta^{(k)})$-semicircular family and let $M^{(k)}$ be the corresponding von Neumann algebra.  Assume that for every non-commutative polynomial, we have
\[
\limsup_{k \to \infty} \norm{p(b^{(k)},X_{\free}^{(k)})} \leq \norm{p(b,X)}.
\]
Then for every non-commutative polynomial $p$, we have almost surely
\[
\limsup_{k \to \infty} \norm{p(b^{(k)},X^{(k)})} \leq \norm{p(b,X)}.
\]
\end{prop}


As in \cite[\S 7.2]{BBvH2023}, we use Haagerup and Thorbj{\o}rnsen's linearization trick \cite[Lemma 1 and p.\ 758-760]{HT2005}, \cite[Theorem 7.7]{BBvH2023}.  We remark that to obtain more quantitative estimates for convergence one would want to proceed using a more explicit linearization such as \cite[Algorithm 4.3 and Theorem 4.9]{HMS2018}.  However, this would take us too far afield as the hypotheses we have assumed on $\eta^{(k)}$ are not quantitative anyway.

\begin{thm}[\cite{HT2005}] \label{thm: HT linearization}
Let $X^{(n)} = (X_i^{(n)})_{i \in [m]}$ and $X = (X_i)_{i \in [m]}$ be tuples of self-adjoint operators in a $\mathrm{C}^*$-algebra.  Then the following are equivalent:
\begin{enumerate}
    \item For every non-commutative polynomial $p$, we have
    \[
    \limsup_{n \to \infty} \norm{p(X^{(n)})} \leq \norm{p(X)}.
    \]
    \item For every $d \in \N$ and $a_0$, \dots, $a_m \in (\mathbb{M}_d)_{\sa}$ and $\varepsilon > 0$, we have for sufficiently large $n$
    \[
    \Spec\left(a_0 \otimes 1 + \sum_{i=1}^m a_j \otimes X_j^{(n)}\right) \subseteq N_{\varepsilon}\left(\Spec\left(a_0 \otimes 1 + \sum_{i=1}^m a_j \otimes X_j\right)\right),
    \]
    where $N_{\varepsilon}$ denotes the $\varepsilon$-neighborhood of a set.
\end{enumerate}
\end{thm}

We next recall the key spectral estimate of Bandeira, Boedihardjo, and van Handel for showing strong convergence.  Here note that we have used the bound $\sigma_*(X) \leq v(X)$ to remove the $\sigma_*(X)$ from the statement.

\begin{thm}[{\cite[Theorem 2.1]{BBvH2023}}] \label{thm: BBvH spectrum bound}
Let $a_0$, \dots, $a_m$ be self-adjoint matrices in $\mathbb{M}_n$.  Let $g_1$, \dots, $g_m$ be independent standard normal random variables, and let $S_1$, \dots, $S_m$ be a free semicircular family.  Let
\[
X = a_0 + \sum_{j=1}^m g_j a_j, \qquad X_{\operatorname{free}} = b_0 \otimes 1 + \sum_{j=1}^m a_j \otimes S_j.
\]
Then
\[
\mathbb{P} \left[ \Spec(X) \subseteq \Spec(X_{\operatorname{free}}) + C \{v(X)^{1/2} \sigma(X)^{1/2} (\log n)^{3/4} + v(X)t\}[-1,1]  \right] \geq 1 - e^{-t^2},
\]
where $C$ is universal constant.
\end{thm}

\begin{proof}[Proof of Proposition \ref{prop: strong convergence plain}]
Since each non-commutative polynomial $p$ in $(b,X)$, only depends on finitely many of the $b_\omega$'s, it suffices to prove strong convergence over every finite $F \subseteq I$ and finitely many coordinates of $b$, say $b_1$, \dots, $b_m$.  To apply Theorem \ref{thm: HT linearization}, fix $d$ and $a_0$, \dots, $a_m$,  and $(A_i)_{i \in I}$ in $(\mathbb{M}_d)_{\sa}$, and consider
\[
Y^{(k)} = a_0 \otimes 1 + \sum_{j=1}^m a_j \otimes b_j^{(k)} + \sum_{i \in F} a_i \otimes X_i^{(k)}.
\]
Note that $a_0 \otimes 1 + \sum_{j=1}^m a_j \otimes b_j^{(k)}$ is deterministic.  Moreover, $\sum_{i \in F} a_i \otimes X_i^{(k)}$ is a Gaussian random matrix, and since it is a matrix linear combination of $X_i^{(k)}$, we have
\begin{align*}
\sigma(Y^{(k)}) &= \norm{\mathbb{E} (Y^{(k)})^2} \leq K_1 \norm{\eta^{(k)}}^{1/2} \\
v(Y^{(k)}) &= \norm{\Cov(Y^{(k)})}^{1/2} \leq K_2 \norm{T^{(k)}}^{1/2},
\end{align*}
where $K_j$ is a constant depending only on $d$ and $(a_i)_{i \in I}$.  By our assumptions on $\norm{\eta^{(k)}(1)}$ and $\norm{T^{(k)}}$, we have 
\[
\varepsilon^{(k)} := v(Y^{(k)})^{1/2} \sigma(Y^{(k)})^{1/2} (\log n(k)d)^{3/4} + v(Y^{(k)}) (\log n(k)d)^{3/2} \to 0.
\]
By Theorem \ref{thm: BBvH spectrum bound}, we have
\[
\mathbb{P} \left[ \Spec(Y^{(k)}) \subseteq \Spec(Y_{\operatorname{free}}^{(k)}) + C \varepsilon^{(k)} \right] \geq 1 - e^{-(\log n(k)d)^3},
\]
where $Y_{\operatorname{free}}^{(k)}$ is obtained by replacing the classical Gaussians by $(\mathbb{M}_{n(k)},\eta^{(k)})$-semicirculars.  Note that $\sum_k e^{-(\log n(k)d)^3} \leq \sum_n e^{-(\log nd)^3} < \infty$, so by the Borel--Cantelli lemma, the containment of the spectra stated above holds for sufficiently large $k$ almost surely.

Now let
\[
Y = a_0 \otimes 1 + \sum_{j=1}^m a_j \otimes b_j + \sum_{i \in F} a_i \otimes X_i \in \mathbb{M}_d \otimes M.
\]
By Theorem \ref{thm: HT linearization}, there is some sequence $\delta^{(k)}$ tending to zero such that
\[
\Spec(Y_{\free}^{(k)}) \subseteq \Spec(Y) + \delta^{(k)}[-1,1],
\]
hence, almost surely for sufficiently large $k$,
\[
\Spec(Y^{(k)}) \subseteq \Spec(Y) + (\delta^{(k)} + C \varepsilon^{(k)}) [-1,1].
\]
The desired conclusion now follows from Theorem \ref{thm: HT linearization}.
\end{proof}

\subsection{Approximation of covariance polynomials by polynomials in free copies} \label{subsec: averaging argument}

We need to upgrade the convergence of norms from ordinary polynomials to covariance polynomials.  To this end, we want to approximate any covariance polynomial in free semicirculars by an ordinary polynomial.  We accomplish this through an averaging trick using infinitely many freely independent copies of ${X}$.

\begin{prop} \label{prop: approximating covariance polynomial}
Let $f$ be a covariance polynomial in variables $\eta = (\eta_{i,j})_{i,j \in I}$ and $(X_i)_{i \in I}$ and $(b_\omega)_{\omega \in \Omega}$.  Then for every $\varepsilon > 0$ and $R > 0$, there exists a polynomial $g$ only depending on $f$, $\varepsilon$, and $R$ such that the following hold:
\begin{enumerate}[(1)]
    \item Let $B$ be a tracial von Neumann algebra and $\eta: B \to B(\ell^2 I) \otimes B$ an operator-valued covariance matrix with $\norm{\eta(1)} \leq R$.  Let $(b_\omega)_{\omega \in \Omega}$ with $\norm{b_\omega} \leq R$.  Let $M$ be the von Neumann algebra generated by a $(B,\eta)$-semicircular family ${X} = (X_i)_{i \in I}$.  Let $N$ be the free product over $B$ of copies of $M$ indexed by $\N_0$ and let $\iota_t: M \to N$ be the inclusion of $t$-th copy.  Then
    \begin{equation} \label{eq: approximation difference}
    \norm{g(b,(\iota_t({X}))_{t \in \N_0}) - \iota_0 \circ f(\eta,b,X)} \leq \varepsilon.
    \end{equation}
    and
    \begin{equation} \label{eq: approximation expectation}
    E_{\iota_0(M)}[g(b,(\iota_t({X}))_{t \in \N_0})] = \iota_0 \circ f(\eta,b,X).
    \end{equation}
    \item Let $\eta^{(k)}$ be a $\tr_{n(k)}$-symmetric $\mathbb{M}_{n(k)}$-valued covariance matrix, and let $X^{(k)}$ be an $\eta^{(k)}$-Gaussian matrix.  For $t \in \N_0$, let ${X}^{(k,t)}$ be independent copies of ${X}^{(k)}$. Then for deterministic matrices $(b^{(k)}_\omega)_{\omega \in \Omega}$, we have
    \begin{equation} \label{eq: approximation expectation matrix version}
    \mathbb{E} \left[ g(b^{(k)},({X}^{(k,t)})_{t \in \N_0}) \mid {X}^{(k,0)} \right] = f(\eta^{(k)},b^{(k)},{X}^{(k,0)}).
    \end{equation}
\end{enumerate}
\end{prop}

\begin{nota}
For a tracial von Neumann algebra $M$ and self-adjoint $X = (X_i)_{i \in I}$ in $M$, define the map $\Ad_{X}: M \to B(\ell^2 I) \otimes M$ by
\[
(\Ad_{X})_{i,j}(Y) = X_i Y X_j.
\]
\end{nota}

Note that $\Ad_{X}$ is an operator-valued covariance matrix over $M$.  Our goal is to show that we can simulate the application of $\eta$ by $(1/m) \sum_{t=1}^m \Ad_{\iota_t(X)}$ where $\iota_t({X})$ are freely independent copies of ${X}$.

\begin{lem}
Consider the same setup as Proposition \ref{prop: approximating covariance polynomial} (1).  Let $(Y_t)_{t=1}^{m}$ be elements of $M$, let $i(t)$, $j(t) \in I$, and let
\[
Z_t = (\Ad_{\iota_t({X})})_{i(t),j(t)}(\iota_0(Y_t)).
\]
Then $(Z_t)_{t=1}^m$ are freely independent over $B$.
\end{lem}

\begin{proof}
Let $\tilde{Z}_t = (\Ad_{\iota_t({X})})_{i(t),j(t)}(\iota_{m+t}(Y_t))$.  Since the index sets $\{t,m+t\}$ are disjoint for $t = 1$, \dots, $m$, the variables $\tilde{Z}_t$ are freely independent over $B$.  Hence, it suffices to show that the $B$-valued moments of $(Z_t)_{t=1}^m$ agree with those of $(\tilde{Z}_t)_{t=1}^m$.

Consider a $B$-valued monomial $Z_{t(1)} b_1 \cdots Z_{t(\ell)} b_\ell$.  By the moment-cumulant formula \eqref{eq: moment-cumulant formula}, 
\begin{align*}
E_{B}[Z_{t(1)} b_1 \cdots Z_{t(\ell)} b_\ell] &= E_{B}[\iota_{t(1)}(X_{i(1)}) \iota_0(Y_{t(1)}) \iota_{j(1)}(X_{j(1)})b_1 \cdots \iota_{t(\ell)}(X_{i(\ell)}) \iota_0(Y_{t(\ell)}) \iota_{j(\ell)}(X_{j(\ell)})b_\ell] \\
&= \sum_{\pi \in \mathcal{NC}(3\ell)} K_\pi(\iota_{t(1)}(X_{i(1)}), \iota_0(Y_{t(1)}), \iota_{j(1)}(X_{j(1)})b_1, \dots, \iota_{t(\ell)}(X_{i(\ell)}), \iota_0(Y_{t(\ell)}), \iota_{j(\ell)}(X_{j(\ell)})b_\ell).
\end{align*}
Since the images of $\iota_t$ are freely independent, the only partitions $\pi$ that contribute are those where the index $t$ is constant on each block.  In other words, every block either connects variables $\iota_t(X_i)$ with the same value of $t$, and or it connects variables $\iota_0(Y_i)$.  Furthermore, as $(\iota_t(X_i))_{i \in I}$ are jointly semicircular, the partition $\pi$ must connect the variables $\iota_t(X_i)$ in pairs.

We claim that $\iota_0(Y_{t(r_1)})$ and $\iota_0(Y_{t(r_2)})$ cannot be connected by $\pi$ unless $t(r_1) = t(r_2)$.  Indeed, suppose that $\iota_0(Y_{t(r_1)})$ and $\iota_0(Y_{t(r_2)})$ are connected.  If $t(r_1) \neq t(r_2)$, then there is an odd number of semicircular variables from $\iota_{t(r_1)}(M)$ in between $\iota_0(Y_{t(r_2)})$ and $\iota_0(Y_{t(m)})$ in the monomial.  Since $\pi$ is non-crossing, these semicircular variables must be matched among themselves by the partition $\pi$; but they cannot be arranged into pairs since there is an odd number.

Given that $\iota_0(Y_{t(r_1)})$ and $\iota_0(Y_{t(r_2)})$ cannot be connected by $\pi$ unless $t(r_1) = t(r_2)$, the resulting contributions will be unchanged if we substitute $\iota_{m+t}(Y_t)$ instead of $\iota_0(Y_t)$.  Hence, $(Z_t)_{t=1}^m$ have the same joint moments as $(\tilde{Z}_t)_{t=1}^m$ as desired.
\end{proof}

% \begin{lem}[{See \cite[Lemma 3.2]{Voiculescu1986}}] \label{lem: norm of free sum}
% Let $B \subseteq M$ be tracial von Neumann algebras, and $Z_1$, \dots, $Z_m \in M$ be freely independent over $B$ with $E_{B}[Z_t] = 0$. Then for any $t_0 \in \N$,
% \[
% \norm*{\sum_{t=1}^m Z_t } \leq \norm*{ \sum_{t=1}^m Z_{t_0} Z_t }^{1/2} + \norm*{ \sum_{t=1}^m Z_t Z_{t_0} }^{1/2} + \max_{t=1,\dots,m} \norm{Z_t}.
% \]
% \end{lem}


\begin{lem} \label{lem: averaging trick}
Consider the same setup as Proposition \ref{prop: approximating covariance polynomial} (1).  Let $m \in \N$ and $i, j \in I$.  Let $Y \in M$.  Then
\begin{equation} \label{eq: averaging expectation}
E_{\iota_0(M)} \left[ \frac{1}{m} \sum_{t=1}^m (\Ad_{\iota_t({X})})_{i,j}[\iota_0(Y)] \right] = \iota_0 \circ \eta_{i,j}(Y),
\end{equation}
and
\begin{equation} \label{eq: averaging difference}
\norm*{\frac{1}{m} \sum_{t=1}^m (\Ad_{\iota_t({X})})_{i,j}[\iota_0(Y)] - \iota_0 \circ \eta_{i,j}(Y)} \leq \frac{24R \norm{Y}}{\sqrt{m}}
\end{equation}
\end{lem}

\begin{proof}
Let
\[
Z_t = (\Ad_{\iota_t({X})})_{i,j}[\iota_0(Y)] - \iota_0 \circ \eta_{i,j}(Y).
\]
For $Y' \in M$, using free independence of $\iota_t({X})$ and $M$ and the free moment-cumulant formula,
\[
E_{B}[\iota_t(X_i) \iota_0(Y) \iota_t(X_j) Y'] = \iota_0 \circ \eta_{i,j} \circ E_{B}(Y) E_{B}[Y'] = E_{B}[\eta_{i,j} \circ E_{B}(Y) Y']
\]
Since this holds for all $Y'$, we have $E_{\iota_0(M)}[\iota_t(X_i) \iota_0(Y) \iota_t(X_j)] = \iota_0 \circ \eta_{i,j} \circ E_{B}(Y)$, and averaging this over $t$ yields \eqref{eq: averaging expectation}.

The above computation also implies that $E_{B}[Z_t] = 0$. 
 Furthermore, note that $\norm{X_i} \leq 2 \sqrt{\eta_{i,i}(1)} \leq 2R^{1/2}$.  Thus, $\norm{\iota_t(X_i) \iota_0(Y) \iota_t(X_j)} \leq 4R \norm{Y}$, and hence $\norm{Z_t} \leq 8R \norm{Y}$.  Thus, by \cite[Lemma 3.2]{Voiculescu1986}, we have
\[
\norm*{\sum_{t=1}^{m} (\Ad_{\iota_t({X})})_{i,j}[\iota_0(Y)] - m \iota_0 \circ \eta_{i,j}(Y)} \leq \sqrt{m(8R \norm{Y})^2} + \sqrt{m(8R \norm{Y})^2} + 8R \norm{Y} = (2\sqrt{m} + 1) 8R \norm{Y}.
\]
We bound this (crudely) by $24 \sqrt{m} R \norm{Y}$ and then divide both sides by $m$ to obtain \eqref{eq: averaging difference}.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop: approximating covariance polynomial}]
We proceed by induction on the number of occurrences of $\eta$ in $f$. (Recall here we write $\eta$ for any formal linear map as in Definition \ref{defi: formal covariance polynomials}). The base case is when there are zero occurrences of $\eta$ and we take $g = f$.  For the induction step, consider an arbitrary covariance polynomial $f$.  By linearity, it suffices to consider the case where $f$ is a monomial, i.e.\ it is $\eta_{\pi,\vec{\imath}}$ applied to some $*$-polynomials.  Pick some innermost block in the pair partition $\pi$, and suppose it is associated to an occurrence of $\Lambda_{i,j}$ and that the term inside $\eta_{i,j}$ is $p(b,X)$ for some non-commutative polynomial $p$.  Thus, there is a covariance monomial $\widehat{f}$ with fewer occurrences of $\eta$, such that
\[
f(\eta,b,X) = \widehat{f}(\eta,b,X,\eta_{i,j}(p(b,X)),b),
\]
where $\widehat{f}$ has only one occurrence of the variable corresponding to $\eta_{i,j}(p(b,X))$.  Note that $\eta_{i,j}(p(b,X)) \in B$ is bounded by a constant only depending on $R$ and $p$.  By the induction hypothesis, there is a polynomial $\widehat{g}$ only depending on $\widehat{f}$, $\varepsilon$, and $R$ such that
\[
\norm*{ \iota_0 \circ \widehat{f}(\eta,b,X,\eta_{i,j}(p(b,X))) - \widehat{g}(b, \iota_t({X})_{t=1}^{t_0},\eta_{i,j}(p(b,\iota_0({X})))) } \leq \frac{\varepsilon}{2},
\]
and the relations \eqref{eq: approximation expectation} and \eqref{eq: approximation expectation matrix version} are satisfied, where we have used indices $t = 1$, \dots, $t_0$ rather than all $\N_0$ because the polynomial only depends on finitely many variables.  Let $m \in \N$ to be chosen later, and let
\[
g(b,\iota_t({X})_{t=1}^{t_0 + m})
= \widehat{g}\left(b, \iota_t({X})_{t=1}^{t_0}, \frac{1}{m} \sum_{t=1}^{m} \iota_{t_0 +t}(X_i) p(b,\iota_0({X})) \iota_{t_0 +t}(X_j) \right).
\]
Since $\widehat{g}$ is linear in the variable corresponding to $\eta_{i,j}(p(b,X))$, there is a constant $C$ depending only on $\widehat{g}$ and $R$ such that
\begin{multline*}
\norm*{\widehat{g}(b,\iota_t({X})_{t=1}^{t_0},\eta_{i,j}(p(b,\iota_0({X})))) - 
\widehat{g}\left(b, \iota_t({X})_{t=1}^{t_0}, \frac{1}{m} \sum_{t=1}^m \iota_{t_0 +t}(X_i) p(b,X) \iota_{t_0 +t}(X_j)\right) } \\
\leq C \norm*{\frac{1}{m} \sum_{t=1}^m \iota_{t_0 +t}(X_i) p(b,\iota_0({X})) \iota_{t_0 +t}(X_j) - \eta_{i,j}(p(b,\iota_0({X})))}
\end{multline*}
By Lemma \ref{lem: averaging trick}, we have
\[
\norm*{\eta_{i,j}(p(b,\iota_0({X}))) - \frac{1}{m} \sum_{t=1}^m \iota_{t_0 +t}(X_i) p({X},{b}) \iota_{t_0 +t}(X_j) } \leq \frac{24R}{\sqrt{m}} \norm{p(b,X)},
\]
which is bounded by $1/\sqrt{m}$ times a constant that only depends on $p$ and $R$.  By choosing $m$ large enough (only depending on $\widehat{g}$, $p$, $R$ and $\varepsilon$), we can guarantee that
\[
\norm*{\widehat{g}(b,\iota_t({X})_{t=1}^{t_0},\eta_{i,j}(p(b,X))) - 
\widehat{g}\left(b,\iota_t({X})_{t=1}^{t_0}, \frac{1}{m} \sum_{t=1}^m \iota_{t_0+t}(X_i) p(b,\iota_0({X})) \iota_{t_0+t}(X_j)\right) } \leq \frac{\varepsilon}{2},
\]
and therefore,
\[
\norm*{g(b,(\iota_t({X}))_{t=1}^{t_0+m}) - f(\eta,b,(\iota_t({X}))_{t=1}^{t_0})} \leq \varepsilon.
\]
Thus, \eqref{eq: approximation difference} is satisfied.

To verify \eqref{eq: approximation expectation}, first observe that by Lemma \ref{lem: averaging trick}
\[
E_{\iota_0(M)} \left[ \frac{1}{m} \sum_{t=1}^m \iota_{t_0+t}(X_i) p(b,\iota_0({X})) \iota_{t_0+t}(X_j) \right] = \eta_{i,j}(p(b,X)).
\]
Since the $\iota_t(M)$'s are freely independent over $B$, we also have that
\[
E_{\iota_0(M) \vee \dots \vee \iota_{t_0}(M)} \left[ \frac{1}{m} \sum_{t=1}^m \iota_{t_0+t}(X_i) p(b,\iota_0({X})) \iota_{t_0+t}(X_j) \right] = \eta_{i,j}(p(b,X)).
\]
Now if the term $\eta_{i,j}(p(b,X))$ is not nested inside any other occurrence of $\eta$, we get immediately from the bimodule property of $E_{\iota_0(M) \vee \dots \vee \iota_{t_0}(M)}$ that
\begin{multline} \label{eq: conditional expectation manipulation}
E_{\iota_0(M) \vee \dots \vee \iota_{t_0}(M)} \left[ \widehat{g}\left(b, \iota_t({X})_{t=1}^{t_0}, \frac{1}{m} \sum_{t=1}^m \iota_{t_0+t}(X_i) p(b,\iota_0(X)) \iota_{t_0+t}(X_j) \right) \right] \\
= \widehat{g}\left(b, \iota_t({X})_{t=1}^{t_0}, E_{\iota_0(M) \vee \dots \vee \iota_{t_0}(M)} \left[ \frac{1}{m} \sum_{t=1}^m \iota_{t_0+t}(X_i) p(b,\iota_0({X})) \iota_{t_0+t}(X_j) \right] \right),
\end{multline}
and therefore,
\begin{equation} \label{eq: conditional expectation manipulation 2}
E_{\iota_0(M) \vee \dots \vee \iota_{t_0}(M)}[g(b,\iota_t({X})_{t=1}^{t_0+m})] = \widehat{g}(b,\iota_t({X})_{t=1}^{t_0},\eta_{i,j}(p(b,X))).
\end{equation}
This equation also holds if $\eta_{i,j}(p(b,X))$ is nested inside some other occurrence of $\eta$, since \eqref{eq: conditional expectation manipulation} can be applied to the part of the polynomial inside the occurrence of $\eta$ that $\eta_{i,j}(p({X},{b}))$ is immediately nested inside.  By applying $E_{\iota_0(M)}$ to \eqref{eq: conditional expectation manipulation 2} and using the induction hypothesis \eqref{eq: approximation expectation} for $\widehat{f}$ and $\widehat{g}$, we obtain \eqref{eq: approximation expectation} for $f$ and $g$.  This completes the proof of (1).

It remains to show \eqref{eq: approximation expectation matrix version} holds.  Let $\eta^{(k)}$ and ${X}^{(k,t)}$ be as in (2).  Using the independence of the ${X}^{(k,t)}$'s and the definition of the Gaussian matrix associated to $\eta^{(k)}$, we have
\[
\mathbb{E}\left[ \frac{1}{m} \sum_{t=1}^m X_i^{(k,t_0+t)} p(b^{(k)},X^{(k,0)}) X_j^{(k,t_0+t)} \Big \mid ({X}^{(k,t)})_{t=1}^{t_0} \right] = \eta_{i,j}^{(k)}(p(b^{(k)},X^{(k,0)}).
\]
Now since $\widehat{g}$ is linear in the variable corresponding to $\eta_{i,j}^{(k)}(p(b^{(k)},X^{(k,0)}))$ and since all the other terms in $\widehat{g}$ depend only on $({X}^{(k,t)})_{t=1}^{t_0}$, we have
\[
\mathbb{E} \left[g(b^{(k)},({X}^{(k,t)})_{t=1}^{t_0+m}) \Big\mid ({X}^{(k,t)})_{t=0}^{t_0}  \right] = \widehat{g}(b^{(k)},({X}^{(k,t)})_{t=1}^{t_0},\eta_{i,j}^{(n)}(p(b^{(k)},{X}^{(k,0)})).
\]
Now taking the conditional expectation given ${X}^{(k,0)}$ on both sides and applying the induction hypothesis \eqref{eq: approximation expectation matrix version} to $\widehat{g}$ and $\widehat{f}$, we obtain \eqref{eq: approximation expectation matrix version} for $g$ and $f$ as desired, which completes the proof of (2).
\end{proof}

\subsection{Convergence of operator norms for covariance polynomials}

We are almost ready to complete the proof of Theorem \ref{introthm: strong convergence}.  As the proof requires an argument to exchange limit and expectation, similar to the one in the proof of weak convergence, we first record the following lemma.

\begin{lem} \label{lem: dominated convergence argument}
Let $X^{(k)}$ be an $\eta^{(k)}$-Gaussian family of random matrices and assume that $\sup_k \norm{\eta^{(k)}(1)} < \infty$ and $\sup_k (\log n(k))^3 \norm{T^{(k)}} < \infty$.  Let $f^{(k)}$ be a real-valued function and $L$ a constant such that
\[
\limsup_{k \to \infty} f^{(k)}({X}^{(k)}) \leq L \text{ almost surely,}
\]
and suppose $M$ and $r$ are constants such that
$|f^{(k)}({X}^{(k)})| \leq M(1 + \max_i \norm{X_i^{(k)}}^r)$.
Then
\[
\limsup_{k \to \infty} \mathbb{E} f^{(k)}({X^{(k)}}) \leq L.
\]
\end{lem}

\begin{proof}
From Theorem \ref{thm: BBvH spectrum bound}, we have
\[
\mathbb{P}\left[\norm{X^{(k)}} \leq \norm{X_{\operatorname{free}}^{(k)}} + C \{v(X^{(k)})^{1/2} \sigma(X^{(k)})^{1/2} (\log n(k))^{3/4} + v(X^{(k)})t\}  \right] \geq 1 - e^{-t^2}.
\]
Since $\norm{X_{\operatorname{free}}^{(k)}} \leq 2 \norm{\eta^{(k)}(1)}^{1/2}$ is bounded as $k \to \infty$, and similarly $(\log n(k))^3 v(X^{(k)})^2 = (\log n(k))^3 \norm{T^{(k)}}$ and $\sigma(X^{(k)}) = \norm{\eta^{(k)}(1)}^{1/2}$ are bounded, there is a constants $C_1$ and $C_2$ such that
\[
\mathbb{P}\left[\norm{X^{(k)}} \leq C_1 + C_2 t \right] \geq 1 - e^{-t^2}.
\]
Now let $Z^{(k)} = f^{(k)}({X}^{(k)})$.  Thus,
\[
\mathbb{P}\left[|Z^{(k)}| \geq M(1 + (C_1 + C_2 t)^r)\right] \leq e^{-t^2}.
\]
Thus also for $\ell \in \N$,
    \begin{align*}
        \mathbb{E} [|Z^{(k)}| \mathbf{1}_{|Z^{(k)}| \geq M(1 + (C_1 + C_2 2^\ell)^r}] &= \sum_{j=\ell}^\infty \mathbb{E} [Z^{(k)} \mathbf{1}_{M(1 + (C_1 + C_2 2^j)^r \leq |Z^{(k)}| \leq M(1 + (C_1 + C_2 2^{j+1})^r}] \\
            &\leq \sum_{j=\ell}^\infty M(1 + (C_1 + C_2 2^j))^r e^{-(2^j)^2}\\
            &\leq \sum_{j=\ell}^\infty (C_3 2^j)^r e^{-2^{j+1}}.
    \end{align*}
Denote $K_\ell = M(1 + (C_1 + C_2 2^\ell)^r$ and $\varepsilon_\ell = \sum_{j=\ell}^\infty (C_3 2^j)^r e^{-2^{j+1}}$.  Because the series converges, we have $\varepsilon_\ell \to 0$, and the above equation says that
    \[
        \mathbb{E} [|Z^{(k)}| \mathbf{1}_{|Z^{(k)}| \geq K_\ell}] \leq \varepsilon_\ell.
    \]
Now we observe that
    \[
        \limsup_{k \to \infty} Z^{(k)} \mathbf{1}_{|Z^{(k)}| < K_\ell} \leq L \text{ almost surely.}
    \]
Moreover, $Z^{(k)} \mathbf{1}_{|Z^{(k)}|< K_\ell}$ is bounded by $K_\ell$ and so by applying Fatou's lemma to $K_\ell - Z^{(k)} \mathbf{1}_{|Z^{(k)}|< K_\ell}$ we have
    \[
        \limsup_{k \to \infty} \mathbb{E}[Z^{(k)} \mathbf{1}_{|Z^{(k)}| < K_\ell}] \leq L.
    \]
Therefore,
    \[
        \limsup_{k \to \infty} \mathbb{E}[Z^{(k)}] \leq \limsup_{k \to \infty} \mathbb{E} [|Z^{(k)}| \mathbf{1}_{|Z^{(k)}| < K_\ell}]  + \limsup_{k \to \infty}  \mathbb{E} [|Z^{(k)}| \mathbf{1}_{|Z^{(k)}| \geq K_\ell}] \leq L + \varepsilon_\ell.
    \]
Since $\varepsilon_\ell \to 0$ as $\ell \to \infty$, we have $\limsup_{k \to \infty} \mathbb{E}[Z^{(k)}] \leq L$ as desired.
\end{proof}

\begin{thm}[Theorem \ref{introthm: strong convergence}] \label{thm: strong convergence general}
Let $(M,\tau)$ be a tracial von Neumann algebra generated by a subalgebra $B\subset M$ and a $(B,\eta)$-semicircular family $x=(x_i)_{i\in I}$, where $\eta=(\eta_{i,j})_{i,j\in I}$ is a $\tau$-symmetric $B$-valued covariance matrix, and let $b=(b_\omega)_{\omega\in \Omega}$ be a generating tuple for $B$. For a sequence of integers $(n(k))_{k\in \N}\subset \N$, let $\eta^{(k)}=(\eta_{i,j}^{(k)})_{i,j\in I}$ be a $\tr_{n(k)}$-symmetric $\mb{M}_{n(k)}$-valued covariance matrix, let $X^{(k)}=(X_i^{(k)})_{i\in I}$ be an $\eta^{(k)}$-Gaussian family, and let $b^{(k)}=(b^{(k)}_\omega)_{\omega\in \Omega}\subset \mb{M}_{n(k)}$. Assume that $\displaystyle\sup_k \|\eta_{i,j}^{(k)}\|<\infty$ for each $i,j\in I$, and $\displaystyle\sup_k \|b_\omega^{(k)}\| <\infty$ for each $\omega\in \Omega$.
Assume also that $\displaystyle \lim_{k \to \infty} (\log n(k))^3 \norm{T_F^{(k)}} = 0$ for each finite $F\subseteq I$, where $T_F^{(k)}$ is the Choi matrix associated to $\eta_F=(\eta_{i,j})_{i,j\in F}$.
Let ${X}_{\free}^{(k)}$ be an $(\mathbb{M}_{n(k)},\eta^{(k)})$-semicircular family and let $M^{(k)}$ be the corresponding von Neumann algebra.  Let $N^{(k)}$ be the free product over $\mathbb{M}_{n(k)}$ of copies of $M^{(k)}$ indexed by $\N_0$ and let $\iota_t^{(k)}: M^{(k)} \to N^{(k)}$ be the $t$-th copy.  Similarly, let $N$ be the free product over $B$ of copies of $M$ and let $\iota_t: M \to N$ be the $t$-th inclusion.  Assume that for all non-commutative polynomials, we have
\[
\lim_{k \to \infty} \norm*{p((\iota_t({X}_{\free}^{(k)})_{t \in \N_0},{B}^{(k)})} = \norm*{p((\iota_t({X}))_{t \in \N_0},{b})}.
\]
Then for every covariance polynomial $f$, we have
\[
\lim_{k \to \infty} \norm*{f(\eta^{(k)},{X}^{(k)},{B}^{(k)})} = \norm{f(\eta,{X},{b})}
\]
almost surely.
\end{thm}

\begin{proof}
First, we verify that weak convergence holds.  To apply Theorem \ref{introthm: weak convergence}, it suffices to check that $(\eta^{(k)},b^{(k)})$ converges weakly in covariance law to $(\eta,b)$ as $k \to \infty$.  To this end, fix a covariance polynomial $f$ in $(\eta,b)$.  Viewing this as a covariance polynomial in $(\eta,b,X)$, let $g$ be as in Proposition \ref{prop: approximating covariance polynomial}.  We rename $\iota_t(X)$ from Proposition \ref{prop: approximating covariance polynomial} to $S_t$ from the semicircular family $S$ in the statement of Theorem \ref{introthm: strong convergence}.  By \eqref{eq: approximation expectation}, we have
\begin{align*}
f(\eta,b) &= E_B[g(b,S)] \\
f(\eta^{(k)},b^{(k)}) &= E_{\mathbb{M}_{n(k)}}[g(b^{(k)},S^{(k)})],
\end{align*}
where $S^{(k)}$ is a countably infinite family of freely independent copies of a $(\mathbb{M}_{n(k)},\eta^{(k)})$-semicircular family with amalgamation over $\mathbb{M}_{n(k)}$.  As a consequence,
\begin{align*}
\tau^{(k)}(f(\eta^{(k)},b^{(k)})) &= \tau^{(k)}(g(b^{(k)},S^{(k)}), \\
    \tau(f(\eta,b)) &= \tau(g(b,S)). 
\end{align*}
We have assumed strong convergence, which includes weak convergence, of the laws of the free copies $(b^{(k)},S^{(k)})$ to that of $(b,S)$.  This implies that $\tau^{(k)}(f(\eta^{(k)},b^{(k)})) \to \tau(f(\eta,b))$ as desired.  So by Theorem \ref{introthm: weak convergence}, we obtain the convergence of the trace of each covariance polynomial in $(\eta^{(k)},b^{(k)},X^{(k)})$ almost surely and in expectation.  Hence, weak convergence holds.

Next, we prove the easier direction of strong convergence, the asymptotic lower bounds on the operator norms of the matrix models, both almost surely and in expectation.  Weak convergence implies in particular that for each covariance polynomial $f$, we have that $Z^{(k)} = f(\eta^{(k)},b^{(k)},X^{(k)})^* f(\eta^{(k)},b^{(k)},X^{(k)})$ converges in non-commutative law to $Z = f(\eta,b,X)^* f(\eta,b,X)$ almost surely, since each monomial in $Z^{(k)}$ is a covariance polynomial in $(\eta^{(k)},b^{(k)},X^{(k)})$, and there are only countably many such monomials.  Therefore, by Lemma \ref{lem: strong convergence general lower bound}, we have almost surely
\[
\liminf_{k \to \infty} \norm{Z^{(k)}} \geq \norm{Z}
\]
or
\[
\liminf_{k \to \infty} \norm{f(\eta^{(k)},b^{(k)},X^{(k)})} \geq \norm{f(\eta,b,X)},
\]
which is the desired almost sure lower bound.  For the lower bound in expectation, note that by Fatou's lemma,
\[
\liminf_{k \to \infty} \mathbb{E} \norm{f(\eta^{(k)},b^{(k)},X^{(k)})} \geq \mathbb{E} \liminf_{k \to \infty} \norm{f(\eta^{(k)},b^{(k)},X^{(k)})} \geq \norm{f(\eta,b,X)}. 
\]

Finally, we prove the harder direction of strong convergence, giving upper bounds on the operator norms for the matrix models.  Since we only need to deal with one covariance polynomial at a time, we can assume without loss of generality that $I$ is finite.  Let $M$ be the von Neumann algebra generated by $B$ and $X$.  Let $N$ be the free product over $B$ of $\N_0$-many copies of $M$, let $\iota_t: M \to N$ be the corresponding inclusion of the $t$-th copy, and let $S = (\iota_t(X))_{t \in \N_0}$.  Similarly, let $M^{(k)}$ be the von Neumann algebra associated to ${X}_{\free}^{(k)}$, let $N^{(k)}$ be the free product of $\N_0$-many copies over $\mathbb{M}_{n(k)}$, let $\iota_t^{(k)}$ the associated inclusion, and let $S^{(k)} = (\iota_t(X_{\free}^{(k)}))_{t \in \N_0}$.  Let $({X}^{(k,t)})_{t \in \N_0}$ be independent copies of the random matrix tuple ${X}^{(k)}$.  We assume these copies are realized on a probability space which is the product of copies of the given probability space on which the $X^{(k)}$'s live.

Let $f(\eta,b,X)$ be a covariance polynomial.  It only depends on finitely many coordinates $b_1$, \dots, $b_h$, so there is some $R > 0$ with
\[
\sup_k \norm{\eta^{(k)}(1)} \leq R, \qquad \sup_k \norm{b_j^{(k)}} \leq R \, \text{ for all } 1 \leq j \leq h.
\]
Fix $\varepsilon > 0$, and let
\[
g(b,(\iota_t({X}))_{t \in \mathbb{N}_0})
\]
be the associated polynomial given by Proposition \ref{prop: approximating covariance polynomial}.  Again $g$ only depends on finitely many values of $t$, say $t = 1$, \dots, $t_0$.  Since the covariance map $\tilde{\eta}^{(k)}$ associated to $({X}^{(k,t)})_{t=1}^{t_0}$ is a direct sum of copies of $\eta^{(k)}$, the Choi matrices $\tilde{T}^{(k)}$ also satisfy $(\log n(k))^3 \norm{\tilde{T}^{(k)}} \to 0$.  As $\tilde{\eta}^{(k)}$ is given by a direct sum, the associated $\mathbb{M}_{n(k)}$-valued semicircular families are given by freely independent copies of ${X}_{\free}^{(k)}$, that is, they can be identified with $({X}_{\free}^{(k,t)})_{t=1}^{t_0}$.  Because we assumed convergence of operator norms of polynomials in these independent operator-valued semicirculars, we can apply Proposition \ref{prop: strong convergence plain} to the independent copies.

Therefore, we have
\[
\limsup_{k \to \infty} \norm{g(b^{(k)},(X^{(k,t)})_{t=1}^{t_0})} \leq \norm{g(b,S)} \text{ almost surely.}
\]
By Proposition \ref{prop: approximating covariance polynomial}, equation \eqref{eq: approximation expectation matrix version},
\[
f(\eta^{(k)},b^{(k)},X^{(k,0)}) = \mathbb{E} \left[ g(b^{(k)},(X^{(k,t)})_{t=1}^{t_0}) \Big \mid X^{(k,0)} \right],
\]
and hence
\[
\norm{ f(\eta^{(k)},b^{(k)},X^{(k,0)}) } \leq \mathbb{E} \left[ \norm{g(b^{(k)},(X^{(k,t)})_{t=1}^{t_0})} \Big \mid X^{(k,0)} \right].
\]
We need to show that the conditional expectation on the right-hand side is bounded asymptotically by $\norm{g(b,(\iota_t(X))_{t \in \mathbb{N}_0})}$, or in other words, we must take the limit inside the conditional expectation.  By our assumption, the probability space decomposes as a product $(\Omega_1,P_1) \times (\Omega_2,P_2)$, where $X^{(k,0)}$ depends on $\omega_1 \in \Omega_1$ and $X^{(k,t)}$ depends on $\omega_2 \in \Omega_2$.  By the Fubini-Tonelli theorem, we have
\[
\text{for a.e. } \omega_1, \text{ for a.e. } \omega_2, \quad \limsup_{k \to \infty} \norm{g(b^{(k)}(X^{(k,t)})_{t=1}^{t_0})} \leq \norm{g(b,S)}.
\]
Moreover, by applying the submultiplicativity of the operator norm and the uniform boundedness of $\eta^{(k)}$, we can see that there are some constants $M$ and $\ell$ such that
\[
\norm{g(b^{(k)},(X^{(k,t)})_{t=1}^{t_0})} \leq M \left( 1 + \max_i \norm{X_i^{(k,0)}}^\ell + \max_{i \in I, t =1,\dots,t_0} \norm{X_i^{(k,t)}} \right).
\]
Therefore, for almost every $\omega_1$, the hypotheses are satisfied for applying Lemma \ref{lem: dominated convergence argument} to the random variables $(X^{(k,t)})_{t=1}^{t_0}$ on $\Omega_2$ and the function $\norm{g(b^{(k)},({X}^{(k,t)})_{t=1}^{t_0})}$.  Therefore,
    \[
        \text{for a.e. } \omega_1,\quad \limsup_{k \to \infty} \norm*{f(\eta^{(k)},b^{(k)},X^{(k,0)})} \leq \norm{g(b,S)}.
    \]
Then by Proposition \ref{prop: approximating covariance polynomial}, equation \eqref{eq: approximation difference},
\[
\norm{g(b,S)} \leq \norm{f(\eta,b,X)} + \varepsilon.
\]
Since $\varepsilon$ was arbitrary, we have the desired almost sure upper bound for strong convergence.  For the upper bound in expectation, note from the preceding argument that
\[
\mathbb{E} \norm{ f(\eta^{(k)},b^{(k)},X^{(k,0)}) } \leq \mathbb{E} \norm{g(b^{(k)},({X}^{(k,t)})_{t=0}^{t_0})}.
\]
Moreover, the hypotheses are satisfied for applying Lemma \ref{lem: dominated convergence argument} to the random variables $(X^{(k,t)})_{t=0}^{t_0}$ and the function $\norm{g(b^{(k)},(X^{(k,t)})_{t=0}^{t_0})}$, this time viewed as a random variables on the entire probability space $\Omega_1 \times \Omega_2$ rather than on $\Omega_2$.  Lemma \ref{lem: dominated convergence argument} then yields
\[
\limsup_{k \to \infty} \mathbb{E} \norm{ f(\eta^{(k)},b^{(k)},X^{(k,0)}) } \leq \limsup_{k \to \infty} \mathbb{E} \norm{g(b^{(k)}({X}^{(k,t)})_{t=0}^{t_0})} \leq \norm{f(\eta,b,X)} + \varepsilon.
\]
Since $\varepsilon$ was arbitrary, the upper bound for strong convergence holds in expectation.
\end{proof}

\section{Application to continuously weighted Gaussian Wigner ensembles} \label{sec: weighted GUE}

In this section we apply Theorems~\ref{introthm: weak convergence} and \ref{introthm: strong convergence} to prove Theorem~\ref{introthm: strong convergence weighted}. As examples, we consider Gaussian band matrices and random matrix ensembles whose asymptotic limits generate an interpolated free group factor. 

\begin{thm}[{Theorem~\ref{introthm: strong convergence weighted}}]\label{thm: strong convergence weighted proof}
Equip $L^\infty[0,1]$ with the trace $\tau=\int_{[0,1]}$ and let $b=(b_\omega)_{\omega\in \Omega}\subset C[0,1]$ be a generating tuple for $L^\infty[0,1]$. Fix a family $(h_{i,j})_{i,j \in I}\subset C[0,1]^2$ such that for all $(s,t)\in [0,1]^2$:
\begin{itemize}
    \item $h_{i,j}(s,t) = h_{j,i}(t,s)$;

    \item $(h_{i,j}(s,t))_{i,j F}\geq 0$ in $\mb{M}_{|F|}$ for all finite $F\subseteq I$.
\end{itemize}
Define a $\tau$-symmetric operator-valued covariance matrix $\eta = (\eta_{i,j})_{i,j\in I}$ over $L^\infty[0,1]$  by
    \[
        \eta_{i,j}(f)(s) = \int_{[0,1]} h_{i,j}(s,t)f(t)\,dt,
    \]
and let $X=(X_i))_{i\in I}$ be a $(L^\infty[0,1],\eta)$-semicircular family. 

For each $n\in \N$, let $E_n\colon \mb{M}_n\to \mb{D}_n$ be the $\tr_n$-preserving conditional expectation onto the subalgebra of diagonal matrices, and let us also identify $\mb{D}_n$ as a subalgebra of $L^\infty[0,1]$ so that
    \[
        E^{(n)}(f):= \diag\left(n \int_0^{1/n} f,\ldots , n\int_{(n-1)/n}^1 f\right) 
    \]
gives the unique $\tau$-preserving conditional expectation onto $\mb{D}_n$. Define a $\mb{D}_n$-valued covariance matrix over $\mb{M}_n$ by $\eta^{(n)}:=(E^{(n)}\circ \eta_{i,j}\circ E_n)_{i,j\in I}$, let ${X}^{(n)}$ be an $\eta^{(n)}$-Gaussian family, and let $b^{(n)}= (E^{(n)}(b_\omega))_{\omega\in \Omega}$. 

Then $(\eta^{(n)}, b^{(n)}, X^{(n)})$ converges weakly and strongly in covariance law to $(\eta,b,X)$, both almost surely and in expectation.
\end{thm}
\begin{proof}
We will reduce the proof to applications of Theorems~\ref{introthm: weak convergence} and \ref{introthm: strong convergence}, so we begin by establishing a bound for the Choi matrices. Fixing a finite $F\subseteq I$, observe that Choi matrix $T_F^{(n)}$ associated to $\eta_F^{(n)}$ is given by
    \begin{align*}
        T_F^{(n)} &= \sum_{i,j \in F} \sum_{k,\ell=1}^n E_{i,j} \otimes \eta_{i,j}^{(n)} (E_{k,\ell}) \otimes E_{\ell,k}^{\op}\\
            &= \sum_{i,j \in F} \sum_{k=1}^n E_{i,j} \otimes \eta_{i,j}^{(n)} (E_{k,k}) \otimes E_{k,k}^{\op}\\
            &= \sum_{i,j \in F} E_{i,j} \otimes \left[ \sum_{k=1}^n \diag \left( n \int_{0}^{1/n} \int_{(k-1)/n}^k h_{i,j}, \ldots, n \int_{(n-1)/n}^{1} \int_{(k-1)/n}^k h_{i,j} \right) \otimes E_{k,k}^{\op} \right].
    \end{align*}
As the bracketed terms in the last expression are  diagonal matrices for each $i,j\in F$, we obtain
    \begin{align}\label{eqn: weighted GUE covariance norm}
        \|T_F^{(n)} \| \leq \sum_{i,j\in F} \frac{1}{n} \|h_{i,j}\|_\infty.
    \end{align}
In particular, $(\log{n})^3\| T_F^{(n)}\|\to 0$ as $n\to\infty$ for all finite $F\subseteq I$.\\

\noindent(\textbf{Weak Convergence}): In light of (\ref{eqn: weighted GUE covariance norm}), to apply Theorem~\ref{introthm: weak convergence} it remains to show $(\eta^{(n)},b^{(n)})$ converges in covariance law to $(\eta,b)$. We will establish the following stronger claim: for all covariance monomials $f=m_0(t) \Lambda_{\pi,\vec{\imath}}[m_1(t),\ldots, m_{2k-1}(t)]m_{2k}(t)$ one has
    \[
        \lim_{n\to\infty} \| f(\eta^{(n)},b^{(n)}) - f(\eta,b)\| =0.
    \]
To prove this claim, we will proceed by induction on $|\pi|=k$. The base case $k=0$ corresponds to when $f=t_{\omega_1}\cdots t_{\omega_d}$ is a non-commutative monomial, and follows since $b_{\omega_j}^{(n)}=E^{(n)}(b_{\omega_j})\to b_{\omega_j}$ in operator norm by the continuity of $b_{\omega_j}$ for each $j=1,\ldots, d$. Suppose now the the claim has been verified for non-crossing pair partitions with at most $k-1$ blocks, and let $f$, $\pi$, and $\vec{\imath}$ be as above. If $\pi$ does not have the outer block $\{1,2k\}$, then $f=f_1 f_2$ where $f_1,f_2$ are covariance monomials corresponding corresponding to partitions $\pi_1,\pi_2$ with most $k-1$ blocks. Hence
    \[
        \| f(\eta^{(n)}, b^{(n)}) - f(\eta, b)\| \leq \| f_1(\eta^{(n)},b^{(n)}) - f_1(\eta, b)\| \|f_2(\eta^{(n)}, b^{(n)})\| + \| f_1(\eta,b)\| \| f_2(\eta^{(n)}, b^{(n)}) - f(\eta, b)\| \to 0
    \]
as $n\to\infty$ by the induction hypothesis. Otherwise $\pi$ has the outer block $\{1,2k\}$, and so $f = m_0(t) \Lambda_{i,j}(f_0) m_{2k}(t)$ for some $i,j\in I$ and $f_0$ a covariance monomial corresponding to a partition $\pi_0$ with $k-1$ blocks. Hence
    \begin{align*}
        f(\eta^{(n}, b^{(n)}) &= m_0(b^{(n)}) \eta_{i,j}^{(n)}[f_0(\eta^{(n}, b^{(n}))] m_{2k}(b^{(n)})\\
            &=  m_0(b^{(n)}) E^{(n)}\circ\eta_{i,j}[f_0(\eta^{(n}, b^{(n)}))] m_{2k}(b^{(n)}).
    \end{align*}
The base case ensures the first and last factors converge to $m_0(b)$ and $m_{2k}(b)$, respectively. For the middle factor observe that
    \begin{align*}
        \| E^{(n)}\circ\eta_{i,j}[f_0(\eta^{(n}, b^{(n)}))]& - \eta_{i,j}(f_0(\eta,b))\| \\
            &\leq \| E^{(n)}\circ \eta_{i,j} \left[f_0(\eta^{(n}, b^{(n)})) - f_0(\eta,b) \right] \| + \| (E^{(n)} -1)[\eta_{i,j}(f_0(\eta,b))] \|\\
            &\leq \|f_0(\eta^{(n}, b^{(n)})) - f_0(\eta,b)\| + \| (E^{(n)} -1)[\eta_{i,j}(f_0(\eta,b))] \|.
    \end{align*}
As $n\to\infty$, the first term in the last expression tends to zero by the induction hypothesis, and the second term tends to zero by the continuity of $\eta_{i,j}(f_0(\eta,b))$ as a function on $[0,1]$. Hence $f(\eta^{(n)},b^{(n)})\to f(\eta,b)$ in operator norm, completing the proof of the claim.\\

\noindent(\textbf{Strong Convergence}): We must show the hypotheses of Theorem~\ref{introthm: strong convergence} are satisfied, but we have already seen $(\log{n})^3 \|T_F^{(n)}\| \to 0 $ as $n\to\infty$ for all finite $F\subseteq I$ by (\ref{eqn: weighted GUE covariance norm}). 
The remaining hypotheses involve the strong convergence of polynomials in $b^{(n)}$ and independent copies of an $(\mb{M}_n, \eta^{(n)})$-semicircular family, but it actually suffices to consider a $(\mathbb{D}_n, \eta^{(n)})$-semicircular family. Indeed, $b^{(n)}\subset \mb{D}_n$, and since $\eta^{(n)}$ is $\mb{D}_n$-valued it follows from Lemma~\ref{lem: semicircular partition formula} that an $(\mb{M}_n, \eta^{(n)})$-semicircular family is also a $(\mb{D}_n, \eta^{(n)})$-semicircular family. Additionally, since any given polynomial only depends on finitely many indices in $I$, it suffices consider $(\mb{D}_n, \eta^{(n)}_F)$-semicircular families for a fixed finite $F\subseteq I$. Toward showing this refined strong convergence, we will first show that an $(L^\infty[0,1],\eta_F)$-semicircular family and a $(\mb{D}_n,\eta^{(n)}_F)$-semicircular family can be represented on a common Hilbert space.

For each $i,j\in F$ and $n\in \N$ set
    \[
        h_{i,j}^{(n)} := (E^{(n)}\otimes E^{(n)})(h_{i,j}),
    \]
and let $(g_{i,j})_{i,j\in F},(g_{i,j}^{(n)})_{i,j\in F} \in \mb{M}_{|F|}\otimes C[0,1]^2$ be the respective (positive) square roots of $(h_{i,j})_{i,j\in F}, (h_{i,j}^{(n)})_{i,j\in F}\in \mb{M}_{|F|} \otimes C[0,1]^2$. Then for each $i\in F$ and $n\in \N$ define vectors in $L^2[0,1]^2\otimes \C^F$ by
    \[
        \zeta_i :=\sum_{j\in F} g_{i,j} \otimes e_j \qquad \text{ and } \qquad \zeta_i^{(n)}:= \sum_{j\in F} g_{i,j}^{(n)}\otimes e_j.
    \]
On the free Fock space over the $L^\infty[0,1]$-$L^\infty[0,1]$ correspondence $L^2[0,2]^2 \otimes \C^F$, consider the tuples
    \[
        X_i:= \ell(\zeta_i)+ \ell(\zeta_i)^* \qquad \text{ and } \qquad X_{\operatorname{free},i}^{(n)}:= \ell(\zeta_i^{(n)}) + \ell(\zeta_i^{(n)})^* \qquad i\in F.
    \]
Then
    \begin{align*}
        E_{L^\infty[0,1]}(X_i f X_j) &= \sum_{k\in F}  \int_{[0,1]} \overline{g_{i,k}(s,t)} f(s) g_{j,k}(s,t)\ ds\\
            &= \sum_{k\in F} \int_{[0,1]} g_{k,i}(s,t) f(s) g_{j,k}(s,t)\ ds \\
            &= \int_{[0,1]} f(s) h_{j,i}(s,t)\ ds = \int_{[0,1]} h_{i,j}(t,s) f(s) \ ds = \eta_{i,j}(f)(t),
    \end{align*}
where the second equality used that $(g_{i,j})_{i,j\in F}$ is self-adjoint and the fourth equality used the first assumption on $h_{i,j}$. Similarly for the $X_{\operatorname{free},i}^{(n)}$. So, by the definition given in \cite{shlyakhtenko1999valued}, $X=(X_i)_{\in F}$ is an $(L^\infty[0,1],\eta_F)$-semicircular family and $X_{\operatorname{free}}^{(n)}=(X_{\operatorname{free},i}^{(n)})_{i\in F}$ is a $(\mb{D}_n, \eta_F^{(n)})$-semicircular family. Moreover, by \cite[Equation (2.8)]{shlyakhtenko1999valued}, for each $i\in F$ and $n\in \N$ we have 
    \begin{align}\label{eqn:common rep norm difference}
        \| X_i - X_{\operatorname{free},i}^{(n)}\| \leq 2 \| &\< \zeta_i - \zeta_i^{(n)} | \zeta_i  - \zeta_i^{(n)}\>_{L^\infty[0,1]}\|^{\frac12}\\
            &= 2\left\| \sum_{j\in F} \int_{[0,1]} |g_{i,j}(s,t) - g_{i,j}^{(n)}(s,t)|^2\ ds \right\|^{\frac12} \leq 2\left(\sum_{j\in F} \|g_{i,j} - g_{i,j}^{(n)}\|_\infty^2 \right)^{\frac12}.\nonumber
    \end{align}
Similarly,
    \begin{align}\label{eqn:uniform bound on approximations}
        \max_{i\in F}\| X_{\operatorname{free},i}^{(n)} \| \leq \max_{i\in F} 2 \left( \sum_{j\in F} \| g_{i,j}^{(n)}\|_\infty^2\right)^{\frac12} \leq 2 |F|^{1/2} \| (h_{i,j}^{(n)})_{i,j\in F}\|^{\frac12} \leq 2 |F|^{1/2} \| (h_{i,j})_{i,j\in F}\|^{\frac12}
    \end{align}
for all $n\in \N$.

Now, as in Theorem~\ref{thm: strong convergence general}, let $S=( \iota_t( X) )_{t\in \N_0}$ be copies of $X$ that are free with amalgamation over $L^\infty[0,1]$, and for each $n\in \N$ let $S^{(n)}=( \iota_t(X_{\operatorname{free}}^{(n)}))_{t\in \N_0}$ be copies of $X_{\operatorname{free}}^{(n)}$ that are free with amalgamation over $\mb{D}_n$. We view all of these tuples as represented on a common Hilbert space, such as the free Fock space over the $L^\infty[0,1]$-$L^\infty[0,1]$ correspondence $L^2[0,1]^2\otimes \C^F \otimes \ell^2(\N_0)$. Fix a non-commutative polynomial $p$ depending only on the finite subsets $F\subseteq I$, $G\subseteq \Omega$, and $H\subset \N_0$. Then (\ref{eqn:uniform bound on approximations}) and $\|b_\omega^{(n)}\| \leq \|b_\omega\|$ implies there exists a constant $C>0$ so that
    \[
        \| p(b,S) - p( b^{(n)}, S^{(n)}) \| \leq C \prod_{\omega\in G} \| b_\omega - b^{(n)}_\omega\| \prod_{\substack{t\in H\\ i\in F}} \| \iota_t( X_i) - \iota_t( X_{\operatorname{free},i}^{(n)})\|.
    \]
Combining this with (\ref{eqn:common rep norm difference}) and using that $E^{(n)}(a) \to a$ uniformly for all $a\in C[0,1]$, it follows that
    \[
        \lim_{n\to\infty} \| p(b^{(n)}, S^{(n)})\| = \|p(b,S)\|.
    \]
Theorem~\ref{introthm: strong convergence} then applies to give the strong convergence of $(\eta^{(n)},b^{(n)}, X^{(n)})$ to $(\eta, b, X)$ in covariance law.
\end{proof}

\begin{rem}
For $a\in L^\infty[0,1]$, note that the sequence $(E^{(n)}(a) )_{n\in\N}$ is uniformly bounded in operator norm and converges to $a$ in the strong operator topology. Using this observation, one can extend the weak convergence result in Theorem~\ref{thm: strong convergence weighted proof} to the case when $(h_{i,j})_{i,j\in I} \subset L^\infty[0,1]^2$ by a similar argument. However, to obtain the strong convergence result in this case would require a novel argument, if it is even true.
\end{rem}



\begin{ex}[Gaussian band matrices]\label{ex: Guassian_band_matrices}
    One can recover strong convergence for generalized Gaussian band random matrices (implicit in \cite{BBvH2023}, see also \cite{Au2021band}) using Theorem~\ref{introthm: strong convergence weighted}.
    Fix $\epsilon >0$, and consider the case where $I$ is a singleton. Specify a single continuous function $h \in C[0,1]^2$ such that $h(s,t)=h(t,s)\geq 0$ and
    \[
        \operatorname{supp}(h) \subseteq \left\{(s,t)\in [0,1]^2 : \exists r \text{ such that } |s-r|^2 + |t -r|^2 < \epsilon^2 \right\}.
    \]
    (In particular, one can do this with $h(s,t) = f(s-t)$ for an appropriately chosen $f \in C[0,1]$.)
    The covariance of the associated $\eta^{(n)}$-Gaussian $X^{(n)}$ is given by
    \[
        \Cov(X^{(n)}_{i,j}, X^{(n)}_{k,\ell}) = \mathbf{1}_{(i,j) = (k,\ell)} n^2 \int_{(i-1)/n}^{i/n} \int_{(j-1)/n}^{j/n} h(s,t)\ dsdt.
    \]
    Thus $X^{(n)}_{i,j} = 0$ whenever $\left[\frac{i-1}{n}, \frac{i}{n}\right]\times \left[ \frac{j-1}{n}, \frac{j}{n}\right]$ is disjoint from $\operatorname{supp}(h)$. In particular, $X^{(n)}$ has zeroes outside of a band of size $\lceil \epsilon n \rceil$ around the diagonal, and joint covariances of entries otherwise specified by $h$ as above.
\end{ex}

\begin{ex}[Random matrix models for interpolated free group factors]\label{ex: interpolated_fgf}
    Theorem~\ref{introthm: strong convergence weighted} can be used to produce random matrix ensembles that converge weakly and strongly in covariance law to generators of interpolated free group factors. Let $I:=J_1\sqcup J_2$ be a countable index set and let $\{S_i:i\in \{0\}\sqcup I\}$ be a free semicircular family. Set $B:=W^\ast(S_0)\cong L^\infty[0,1]$ which we equip with the trace $\tau= \int_{[0,1]}$, and for each $i\in I$ let $f_i, g_i\in C[0,1]\subset B$ satisfy either
        \[
         \begin{cases}
            f_i = \overline{g_i}, & \text{if } i\in J_1\\
            \operatorname{supp}(f_i)\cap \operatorname{supp} (g_i)=\emptyset, & \text{if } i\in J_2
        \end{cases}.
        \]
    Assume that there exists at least one $i\in J_2$ with $m(\supp(f_i)\cup \supp(g_i))=1$ and $0 < m(\supp(f_i)) < 1$. For each $i,j\in J_1\sqcup J_2$, define $h_{i,j}\in C[0,1]^2$ by
        \[
            h_{i,j}(s,t) = \delta_{i=j} \begin{cases}
                 |f_i(s) f_i(t)|^2 & \text{if }i\in J_1\\
                 |f_i(s) g_i(t)|^2 + |g_i(s) f_i(t)|^2 & \text{if }i\in J_2
            \end{cases},
        \]
    and note that the family $(h_{i,j})_{i,j\in I}$ satisfies the symmetry and positivity conditions in the statement of Theorem~\ref{thm: strong convergence weighted proof}. Using this family of continuous functions, define a $\tau$-symmetric operator valued covariance matrix $\eta=(\eta_{i,j})_{i,j\in I}$ on $B$ as in Theorem~\ref{thm: strong convergence weighted proof}. For each $i\in I$, letting
        \[
            X_i:=\begin{cases} f_i S_i \overline{f_i}, & \text{if }i\in J_1\\
        f_iS_ig_i+\overline{g_i}S_i\overline{f_i}, & \text{if } i\in J_2
        \end{cases},
        \] 
    we claim that $X=(X_i)_{i\in I}$ is a $(B,\eta)$-semicircular family. Let $E_B\colon W^*(S_i,i\in \{0\}\sqcup I)\to B$ be the trace-preserving conditional expectation and let $K_k$ be the associated cumulant maps for $k\in \N$. Any cumulant $K_k[X_{i_1} b_1,\ldots, X_{i_k} b_k]$ can be expanded as a sum of terms of the form $K_k[ c_1 S_{i_1} d_1, \ldots, c_k S_{i_k} d_k]$ for $c_1,d_1,\ldots, c_k, d_k\in B$, and for $k\neq 2$ these terms all vanish since $(S_i)_{i\in I}$ is a $(B,\operatorname{id}_B)$-semicircular family (see, for example, \cite[Proposition 3.8]{shlyakhtenko2000cpentropy}). The second order cumulants are therefore given by the second order moments, and these can be computed by taking their trace against an element in $B$. For $i,j\in I$ and $b_1,b_2\in B$, using the free independence of $S_i, S_j$ from $B$ (and each other if $i\neq j$), it follows that
        \[
            \tau(K_2[X_i, b_1 X_j] b_2) = \tau(E_B(X_i b_1 X_j) b_2)= \int_{[0,1]}\int_{[0,1]} h_{i,j}(s,t) b_1(t) b_2(s)\ dsdt = \tau( \eta_{i,j}(b_1) b_2), 
        \]
    and therefore $K_2[X_i, b_1 X_j] = \eta_{i,j}(b_1)$. Thus $X=(X_i)_{i\in I}$ forms a $(B,\eta)$-semicircular family, as claimed. In particular, Theorem~\ref{thm: strong convergence weighted proof} indicates how to find random matrix ensembles that converge weakly and strongly to $(b,X)$ in covariance law for any tuple $b=(b_\omega)_{\omega\in \Omega} \subset C[0,1]$ generating $B$.

    Finally, we claim that $W^*(B\cup \{X_i\colon i\in I\})\cong L(\mathbb{F}_t)$, where
        \[
            t = 1 + \sum_{i\in J_1} m(\supp(f_i))^2 + 2\sum_{i\in J_2}  m(\supp(f_i)) m(\supp(g_i)).
        \]
     Indeed, if $p_i := 1_{\supp(f_i)}$ and $q_i :=1_{\supp(g_i)}$, then by assumption $0<p_i=1-q_i<1$ for at least one $i\in J_2$.  Therefore $ W^*(B\cup \{ p_i S_i q_i\colon i\in I\}) \cong L(\mathbb{F}_t)$ by \cite[Definition 4.1]{Rad94} (and the discussion following it). On the other hand, $p_i,q_i\in B$ for each $i\in I$ implies $W^*(B\cup \{X_i\colon i\in I\}) = W^*( B \cup \{ f_i S_i g_i\colon i\in I\})$, and a routine approximation argument shows the latter algebra equals $W^*(B\cup \{ p_i S_i q_i\colon i\in I\})$.
\end{ex}


