\title{Retrodicting Chaotic Systems: An Algorithmic Information Theory Approach}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\author{Kamal Dingle$^{1}$, Boumediene Hamzi$^{2,3}$, Marcus Hutter$^{4,5}$,  Houman Owhadi$^{2}$}



\affiliation{$^1$Centre for Applied Mathematics and Bioinformatics,
Department of Mathematics and Natural Sciences, 
Gulf University for Science and Technology, Kuwait\\
