\section{Preliminaries} \label{sec:preliminaries}

Throughout the paper we shall deal with several closely related notions of billiard tables.

\begin{definition}
A \emph{billiard table} $K \subset \mathbb{R}^2$ is a smooth convex body whose boundary $\partial K$ is of length $1$ and has positive curvature. A \emph{marked billiard table} is a pair $(K, S)$, where $K$ is a billiard table, and $S$ is a point on the boundary $\partial K$.
\end{definition}


\noindent
The set of all marked billiard tables will be denoted by $\mathcal{B}$. Note that the group $S^1= \mathbb{R}/Z$ acts freely on $\mathcal{B}$ by counter-clockwise rotations of the marked point along the boundary. With this language the space of (non-marked) billiard tables is $\mathcal{B}/S^1$. Additionally, the group $\SE(2)$ of orientation-preserving Euclidean isometries of the plane acts on $\mathcal{B}$. We denote $\mathcal{AB} = \mathcal{B}/\SE(2)$.

\medskip\noindent{\bf Convention:} For the sake of brevity , we call elements from $\mathcal{B}/S^1$, $\mathcal{B}$, and $\mathcal{AB}$ simply \emph{ billiard tables}; the precise meaning will be clear from the context.

\medskip

Consider a billiard table $(K,S)$ and let $\gamma \colon S^1 = \mathbb{R}/\mathbb{Z} \to \mathbb{R}^2$ be the counterclockwise arc-length parametrization of $\partial K$ with $\gamma(0) = S$.
Such a curve is uniquely determined by the billiard table, and since it uniquely determines the table itself, we shall refer to it as a billiard table as well.

\begin{definition}
	Let $\alpha,\beta$ be two billiard tables. We define the ``geometric'' distance between them as
	\[
		d_{B}(\alpha,\beta) = \inf [l_{B}(\gamma_s)],
	\]
	where the infimum is taken over all smooth homotopies $\gamma_s$ between $\alpha$ and $\beta$ such that $\gamma_s \in \mathcal{B}$ for every $s \in [0,1]$. The length of a homotopy is defined as follows
	\[
		l_{B}(\gamma_s) = \int_0^1 \max_{q \in S^1} \left\|\frac{\partial \gamma_s}{\partial s} (q)\right\| \, ds,
	\]
	where $\|\cdot\|$ is the Euclidean norm.
\end{definition}

The metric $d_B$ descends to a metric on $\mathcal{AB}$ which we denote by $d_{AB}$\footnote{The reader can check that $d_{AB}$ is non-degenerate directly, but this also follows from Remark~\ref{rem:nondegeneracy}, Theorem~\ref{thm:main} and Lemma~\ref{lem:inject}.}.

\medskip

Let $A$ be the open annulus $S^1 \times (-1,1)$ and $\bar{A}$ be the closed annulus $S^1 \times [-1,1]$.

\begin{definition}
	For every curve $\gamma \in \mathcal{B}$ define a map $\psi_\gamma \colon A \to A$,\, $\psi_\gamma(q,p)=(Q,P)$ so that
	\begin{align*}
	 p &= \left\langle \frac{\gamma(Q) - \gamma(q)}{\|\gamma(Q) - \gamma(q)\|}, \gamma'(q)\right\rangle,\\
	 P &= \left\langle \frac{\gamma(Q) - \gamma(q)}{\|\gamma(Q) - \gamma(q)\|}, \gamma'(Q)\right\rangle.
	\end{align*}
	Such a map is unique and is called the \emph{billiard ball map} of the billiard table $\gamma$ (see~\cite{tabachnikov2005geometry,siburg2004principle}).
\end{definition}

	The map $\psi_{\gamma}$ is smooth by the implicit function theorem, and it is well known that this is a symplectomorphism with respect to the standard symplectic structure $\omega = dp \wedge dq$ on~$A$~\mbox{\cite[Section 8.3]{Mcduff_salamon}}. Note that the map $\psi_\gamma$ can be continuously extended to $\bar{A}$ by setting $\psi_\gamma|_{\partial A} = \id_{\partial A}$, but this map would not be smooth near the boundary~\cite[Section 3]{Marvizi}.

\begin{definition}\label{def:ham_path}
	Let $\psi_s$ be a smooth path of symplectomorphisms of the annulus $A$ for $s \in [0,1]$ that can be continuously extended as a map $A \times [0,1] \to A$  to a map $\bar{A} \times [0,1] \to \bar{A}$ by setting $\psi_s|_{\partial A} = \id_{\partial A}$. We shall call this path \emph{Hamiltonian} if there exists a smooth family of functions $H_s \colon A \to \mathbb{R}$ such that $i_{X_s} \omega = -dH_s$ for every $s \in [0,1]$, where $X_s$ is uniquely determined by
	\[
		\frac{d\psi_{s}}{ds} = X_s \circ \psi_s,
	\]
	and $H_s$ can be continuously  extended as a function on $A \times [0,1]$ to a function on $\bar{A} \times [0,1]$ by setting $H_s|_{\partial A} = 0$. Note that the family of functions $H_s \colon A \to \mathbb{R}$ is unique due to this boundary condition.
\end{definition}


\begin{definition}

	$\Ham (A, \partial A) = \{\psi_1 :\ \psi_s\ \text{--- Hamiltonian path such that}\quad \psi_0 = \id_A\}$

\end{definition}

\begin{definition}
	Let $\psi_s \colon A \to A$ be a Hamiltonian path and $H_s \colon A \to \mathbb{R}$ be the corresponding family of functions. The \emph{Hofer's length}~\cite{hofer_1990} of this path is defined as follows
	\[
		l_H(\psi_s) = \int_0^1 \left(\max_{\bar{A}} H_s - \min_{{\bar{A}}} H_s\right) ds = \int_0^1 \left(\sup_{A} H_s - \inf_{A} H_s\right) ds .
	\]
\end{definition}

\begin{definition}
	Let $\varphi, \psi$ be smooth symplectomorphisms of $A$ that can be continuously extended to the boundary by setting $\varphi|_{\partial A} = \psi|_{\partial A} = \id_{\partial A}$. The \emph{Hofer's distance} $d_H$ between $\varphi$ and $\psi$ is defined as the infimum of the length of the Hamiltonian paths that join them.
\end{definition}

\begin{remark} \label{rem:nondegeneracy}
	To see that $d_H$ in that specific case is non-degenerate let us consider a map $\psi \in \Ham (A, \partial A)$ that is not identical. Then there exists a point $x \in A$ such that $\psi(x) \neq x$. Let $U$ be a small neighborhood of $x$ such that $\psi(U) \cap U = \varnothing$ and the closure of $U$ is a subset of $A$. Let $\widetilde{e}(U)$ be the standard displacement energy of $U$, that is
	\[
		\widetilde{e}(U) = \inf \left\{ \int_0^1 \left(\sup_{A} \widetilde{H}_s - \inf_{A} \widetilde{H}_s\right) ds \right\},
	\]
	where infimum is taken over all Hamiltonians $\widetilde{H}_s$ compactly supported in the interior of the annulus, such that the corresponding time-1 map $\phi_{\widetilde{H}}$ satisfies $\phi_{\widetilde{H}}(U) \cap U = \varnothing$. Since $U$ is non-empty open set we have $\widetilde{e}(U) > 0$ (see~\cite{lalonde1995geometry} and~\cite[Section 12.3]{Mcduff_salamon}).


	Now, let $\psi_s$ be a Hamiltonian path with the Hamiltonian function $H_s$, such that $\psi_0 = \id_{A}$ and $\psi_1 = \psi$. Let $\rho$ be a smooth bump function with a compact support in $A$ such that $\rho$ equals one in the small neighborhood of the trace of $U$ under the flow $\psi_s$. Then the Hamiltonian function $\widetilde{H}_s = \rho \cdot H_s$ generates time-1 map $\phi_{\widetilde{H}}$ such that $\phi_{\widetilde{H}}(U) = \psi(U)$, hence $\phi_{\widetilde{H}}(U) \cap U = \varnothing$. Then, by the definition of $\widetilde{e}(U)$, we have
	\[
			0 < \widetilde{e}(U) \leq \int_0^1 \left(\sup_{A} \widetilde{H}_s - \inf_{A} \widetilde{H}_s\right) ds \leq	 \int_0^1 \left(\sup_{A} H_s - \inf_{A} H_s\right) ds.
	\]
	Therefore,
	\[
		0< \widetilde{e}(U) \leq d_{H}(\id_A, \psi).
	\]
	Thus, $d_H$ is indeed non-degenerate.
\end{remark}

	In the last remark we considered the notion of the standard displacement energy. Let us introduce the notion of the displacement energy associated with the group $\Ham(A,\partial A)$.

	\begin{definition}
	 Let $X$ be a subset of $A$. Then the \emph{displacement energy} of $X$ associated with the group $\Ham(A,\partial A)$ is defined as follows
	 \[
	 		e(X) = \inf\{d_H(\id_{A},\psi)|\, \psi \in \Ham(A,\partial A), \, \psi(X) \cap X = \varnothing \}.
	 \]
	\end{definition}

	\begin{remark}\label{rem:energy_compare}
		It is easy to see that $e(X) \leq \widetilde{e}(X)$ for every set $X \subseteq A$. If the closure of $X$ is also contained in $A$, then, by the argument in Remark~\ref{rem:nondegeneracy}, one can obtain $e(X) = \widetilde{e}(X)$.   
	\end{remark}

	To sum up, we have a natural map $\Upsilon: \mathcal{B} \to \mathcal{BM}$ (the latter space is defined in \eqref{def:BM}) which associates a billiard ball map with a marked billiard table. The map $\Upsilon$ is invariant under the action of $\SE(2)$ on $\mathcal{B}$. Let us discuss the effect of changing the marked point. Observe that the actions of $\SE(2)$ and $S^1$ on $\mathcal{B}$ commute. Thus, we have a natural isometric action of $S^1$ on $\mathcal{AB}$ given by $r \cdot [\gamma(q)] = [\gamma(q+r)]$, where $r \in S^1$ and $[\gamma(q)] \in \mathcal{AB}$. There is also an $S^1$-action on the annulus $A = S^1 \times (-1,1)$ given by $\varphi_r (q,p) = (q-r,p)$. This allows us to define an isometric action of $S^1$ on $\BM$ given by $r\cdot \psi = \varphi_r^{-1} \circ \psi \circ \varphi_r$. The map $(\mathcal{AB}, d_{AB}) \to (\BM, d_{H})$ is equivariant with respect to the corresponding $S^1$-actions. This map and these $S^1$-actions can be isometrically extended to the completions $\overline{\mathcal{AB}}$ and $\overline{\BM}$. The extended map is $S^1$-equivariant.


\section{A comparison theorem} \label{sec:main_theorem}
\begin{theorem}\label{thm:main}
	Any two billiard ball maps can be joined by a Hamiltonian path, and hence they belong to the set $\BM$ defined by \eqref{def:BM}. Furthermore, for any two billiard tables $\alpha$, $\beta$ and corresponding billiard ball maps $\psi_\alpha$, $\psi_\beta$ the following inequality holds:
	\[
		d_{H}(\psi_{\alpha}, \psi_{\beta}) \leq 4\cdot d_B(\alpha,\beta).
	\]
\end{theorem}


The following lemma is needed for the proof of the theorem.

\begin{lemma}\label{lem:ham_gen_fund}
	Let $\gamma_s$ be a smooth path of billiard tables and $\psi_s$ be the corresponding path of symplectomorphisms of the annulus $A$. Consider the smooth family of functions $F_s \colon (S^1 \times S^1) \setminus {\Delta_{S^1}} \to \mathbb{R}$ defined as
	\[
		F_s(q,Q) = \|\gamma_s(q) - \gamma_s(Q) \|,
	\]
	where $\Delta_{S^1} = \{(q,q)\in S^1 \times S^1: q \in S^1\}$. Then the family of functions defined as
	\[
		H_s(Q,P) = - \frac{\partial F_s}{\partial s}(q_s(Q,P),Q)
	\]
	 is the family of Hamiltonian functions for the path $\psi_s$, where
	 \[
	 	(q_s(Q,P), p_s(Q,P)) = \psi^{-1}_s(Q,P).
	 \]
	 In particular, the path $\psi_s$ is Hamiltonian.
\end{lemma}

\begin{proof}
	Consider the lift $\widetilde{\psi}_s$ of $\psi_s$ to the universal cover $\mathbb{R} \times [-1,1]$ such that $\widetilde{\psi}_s (q,1) = (q,1)$. It is well known that the symplectomorphism $\widetilde{\psi}_s \colon \mathbb{R} \times (-1,1) \to \mathbb{R} \times (-1,1)$ is generated by the function
	\[
		\widetilde{F}_s(q,Q) = \|\gamma_s(q) - \gamma_s(Q) \|
	\]
	defined on $U \times [0,1]$, where $U = \{(q,Q) \in \mathbb{R}^2 : q < Q < q+1\}$ (see~\cite[Section 8.3]{Mcduff_salamon}). Here the word ``generated'' means that
	\begin{align*}
		\frac{\partial \widetilde{F}_s}{\partial q} (q, \widetilde{Q}_s(q,p)) &= - p, \\
		\frac{\partial \widetilde{F}_s}{\partial Q} (q, \widetilde{Q}_s(q,p)) & = \widetilde{P}_s(q,p),
	\end{align*}
	where $(\widetilde{Q}_s(q,p), \widetilde{P}_s(q,p)) = \widetilde{\psi}_s(q,p)$.


	Therefore, we have obtained a family of symplectomorphisms $\widetilde{\psi}_s$ of the open simply connected subset $\mathbb{R} \times (-1,1)$ of the plane and a smooth family of functions $\widetilde{F}_s$, such that for every $s \in [0,1]$ the function $\widetilde{F}_s$ is the generating function for the symplectomorphism $\widetilde{\psi}_s$. It is well known from classical mechanics (the Hamilton--Jacobi equation, see Lemma~\ref{lem:Ham-Jac} in Appendix~\ref{section:Appendix}) that this family is Hamiltonian (without any boundary condition) with the Hamiltonian function
	\[
		\widetilde{H}_s(Q,P) = -\frac{\partial \widetilde{F}_s}{\partial s}(\widetilde{q}_s(Q,P),Q).
	\]
	The function $\widetilde{H}_s(Q,P)$ is $1$-periodic in $Q$. Indeed, $\widetilde{q}_s(Q+1,P) = \widetilde{q}_s(Q,P) + 1$ and $\widetilde{F}_s (q+1,Q+1) = \widetilde{F}_s(q,Q)$.

	Since every billiard table $\gamma_s$ has positive curvature it follows that the family $\psi_s$ as well as the family $\psi_s^{-1}$ can be continuously extended to a map $\bar{A} \times [0,1] \to \bar{A}$ by setting $\psi_s|_{\partial A} = \id_{\partial A}$ and $\psi_s^{-1}|_{\partial A} = \id_{\partial A}$. Thus, we only need to prove that $H_s(Q,P)$ can be continuously extended on $\bar{A} \times [0,1]$ by setting $H_s|_{\partial A} = 0$.	To see that such an extension is indeed continuous, consider the inequality
	\[
		|H_s(Q,P)| = \left|\frac{\partial F_s}{\partial s}(q_s(Q,P),Q)\right| \leq \left\|\frac{\partial \gamma_s}{\partial s} (q_s(Q,P)) - \frac{\partial \gamma_s}{\partial s}(Q)\right\|.
	\]
	The right-hand side is continuous on $[0,1]\times \bar{A}$ and equals $0$ when $P = \pm 1$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:main}]
	Since any two billiard tables can be joined by a path of billiard tables, the first statement of the theorem follows from Lemma~\ref{lem:ham_gen_fund}. Next, consider an arbitrary path $\gamma_s$ of billiard tables joining billiard tables $\alpha$ and $\beta$. Let $\psi_s$ be the corresponding Hamiltonian path of symplectomorphisms of the annulus $A$, and let $H_s \colon A \to \mathbb{R}$ be the smooth family of Hamiltonian functions corresponding to $\psi_s$. By Lemma~\ref{lem:ham_gen_fund} the following inequality holds
		\begin{multline*}
			l_{H}(\psi_s) = \int_0^1 \left(\newsup_{A}H_s - \inf_{A}H_s\right)\, ds = \\
			= \int_0^1 \left(\newsup_{S^1\times S^1 \setminus \Delta_{S^1}} \frac{\partial F_s}{\partial s}  - \inf_{S^1\times S^1 \setminus \Delta_{S^1}} \frac{\partial F_s}{\partial s}\right)\, ds \leq 2 \cdot \int_0^1 \newsup_{S^1\times S^1 \setminus \Delta_{S^1}} \left|\frac{\partial F_s}{\partial s}\right| \, ds,
		\end{multline*}
		where
		\[
			 F_s (q,Q) = \|\gamma_s(q) - \gamma_s(Q)\|.
		\]
		Using the triangle inequality, we obtain
		\[
			\newsup_{S^1\times S^1 \setminus \Delta_{S^1}} \left|\frac{\partial F_s}{\partial s}\right| \leq \newsup_{S^1\times S^1 \setminus \Delta_{S^1}} \left\|\frac{\partial\gamma_s}{\partial s}(q) - \frac{\partial\gamma_s}{\partial s}(Q)\right\|  \leq 2 \cdot \max_{S^1} \left\|\frac{\partial \gamma_s}{\partial s}\right\|.
		\]
		Therefore
		\[
			l_{H}(\psi_s) \leq 4 \cdot \int_0^1 \max_{S^1} \left\|\frac{\partial \gamma_s}{\partial s}\right\| \, ds \leq 4\cdot l_{B}(\gamma_s).
		\]
		Thus
		\[
			d_H(\psi_\alpha,\psi_\beta) \leq 4\cdot d_{B} (\alpha,\beta).
		\]
\end{proof}

	Due to Theorem~\ref{thm:main}, we have the Lipschitz map $\mathcal{B} \to \BM$. However, this map is not injective. To avoid this, it is more natural to consider $\mathcal{AB}$ instead of $\mathcal{B}$.

	\begin{lemma}\label{lem:inject}
	 The map $(\mathcal{AB}, d_{AB}) \to (\BM, d_{H})$ is injective and Lipschitz.
	\end{lemma}
	\begin{proof}
		Let $\gamma_{1}$ and $\gamma_{2}$ be two billiard tables and assume that the corresponding billiard ball maps $\psi_1,\psi_2 \colon A \to A$ coincide, then the corresponding generating functions $F_i(q,Q) = \|\gamma_i(q) - \gamma_i(Q)\|$ coincide as well. Indeed, they have the same partial derivatives
		\begin{align*}
			\frac{\partial F_i}{\partial q} (q, Q_i(q,p)) &= - p,\\
			\frac{\partial F_i}{\partial Q} (q, Q_i(q,p)) & = P_i(q,p).
		\end{align*}
		and $F_i(q,Q)$ tends to $0$, when $q$ approaches $Q$.

		Note that one can recover (up to a transformation from $\SE(2)$) the billiard table $\gamma$ from the function $F(q,Q) = \|\gamma(q) - \gamma(Q)\|$. Indeed, take two point $S$ and $R$ in the plane such that the distance between them equals $F(0,1/2)$. For any $0<t<1/2$ there exists only one point $\beta(t)$  such that
		\begin{align*}
			\|S- \beta(t)\| &= F(0,t),\\
			\|R- \beta(t)\| &= F(t,1/2),
		\end{align*}
		and vectors $\beta(t)-S$ and $R-S$ form a positively oriented basis of $\mathbb{R}^2$ (see Figure~\ref{fig:constructing_of_beta} below). The same holds for $1/2<t<1$, but the corresponding vectors form negatively oriented basis. If we additionally assume that $\beta(0) =\beta(1) = S$ and $\beta(1/2) = R$ one can check that $\gamma$ and $\beta$ coincide up to the transformation from $\SE(2)$.

		\begin{figure}[ht]
  		\centering
  		\includegraphics[width=0.6\textwidth]{Figures/recovery.pdf}
			\caption{Obtaining the curve $\beta$ ($0 < t < 1/2$).}
			\label{fig:constructing_of_beta}
		\end{figure}

		Thus, the map $(\mathcal{AB}, d_{AB}) \to (\BM, d_{H})$ is injective. The fact that this map is Lipschitz follows from Theorem~\ref{thm:main}.

	\end{proof}

\medskip

We conclude this section with an application of Theorem 
\ref{thm:main}. 

\begin{corollary}\label{cor-dyn}
Let $X$ be a subset of the annulus $A$ such that the displacement energy $e(X)$ is strictly positive. Fix positive integer $n$. Consider two billiard tables $\alpha, \beta$ and the corresponding billiard ball maps $\psi_{\alpha}$ and $\psi_{\beta}$. If $d_B(\alpha,\beta) < e(X)/4n$, then there is a point $x \in X$ with $\psi_\beta^n (x) \in \psi_\alpha^n(X)$.
\end{corollary}

For instance, $X$ could be an arbitrary open subset of $A$ (cf. Remark~\ref{rem:nondegeneracy} and Remark~\ref{rem:energy_compare}).

\begin{proof} Assume on the contrary that  $\psi_{\alpha}^n(X) \cap \psi_{\beta}^n(X) = \varnothing$, i.e.,
$X \cap \psi_\beta^{-n} \circ \psi_\alpha^n(X) = \varnothing$. 
Put $\psi_\alpha = \psi_\beta \circ \varphi$, with
$\phi \in \Ham(A,\partial A)$. We have
$$\psi_\alpha^n = \psi_\beta^n \prod_{j=n-1}^{0} \psi_\beta^{-j} \circ \phi \circ \psi_\beta^{j} \;.$$
The Hofer metric is invariant under conjugations by elements from $\Symp(A,\partial A)$.
Thus, by the triangle inequality and  Theorem \ref{thm:main}  we have 
 \[
 		d_{H}(\id_A, \psi_\beta^{-n} \circ \psi_\alpha^n)  \leq n\cdot d_{H}(\psi_{\alpha}, \psi_{\beta}) \leq 4n\cdot d_{B}(\alpha,\beta).
 \]
 Therefore, by definition of the displacement energy, 
 \[
 		0 < e(X) \leq 4n \cdot d_{B}(\alpha,\beta),
 \]
 and we got a contradiction. 
 \end{proof}

This is a version of an argument  which appears in~\cite[proof of Lemma 2.1.10]{polterovich2014function}. We refer to Section \ref{sec:discussion} for further discussion of the corollary. 


\section{Approximation of polygons}\label{sec:approximation_of_polygons}
	\begin{definition}
		Let $\mathcal{P}$ be a set of pairs $(P, S)$, where $P \subset \mathbb{R}^2$ is a convex polygon whose boundary $\partial P$ is of length $1$, and $S$ is a point on the boundary $\partial P$. The set $\mathcal{AP}$ is the quotient of $\mathcal{P}$ under the action of $SE(2)$.
	\end{definition}

	\begin{theorem} \label{thm:approx}
		There is a ``natural'' map $\mathcal{AP} \to \overline{\mathcal{AB}}$. More precisely, for every element of $\mathcal{AP}$ there is a $d_{AB}$-Cauchy sequence $\alpha_n$ of smooth billiard tables with positive curvature that tends in the $C^0$-norm to that element of $\mathcal{AP}$ (see the construction below). In addition, all such sequences are $d_{AB}$-equivalent.
	\end{theorem}

	In the remaining part of this section we prove this theorem.

	\medskip

	For technical purposes we introduce the set of (marked) smooth convex bodies that are not strictly convex.

	\begin{definition}
		Let $\mathcal{C}$ be the set of pairs $(K,S)$, where $K \subset \mathbb{R}^2$ is a smooth convex body (not necessarily strictly convex) whose boundary $\partial K$ is of length $1$, and $S$ is a point on the boundary $\partial K$.  We endow the set $\mathcal{C}$ with the metric $d_{C}$ defined in the same way as $d_{B}$, but instead of considering paths in $\mathcal{B}$ we consider paths in $\mathcal{C}$. Let $\mathcal{AC}$ be the quotient of $\mathcal{C}$ under the action of $SE(2)$ with the induced metric $d_{AC}$.
	\end{definition}

	Note that $\mathcal{AB} \subset \mathcal{AC}$. The reader can check that the restriction of $d_{AC}$ to $\mathcal{AB}$ coincides with $d_{AB}$ and $\mathcal{AB}$ is dense in $\mathcal{AC}$. Therefore, $\overline{\mathcal{AC}} = \overline{\mathcal{AB}}$.

	Now we are ready to describe the process of embedding $\mathcal{AP} \to \overline{\mathcal{AB}}$. Let $\eta \in \mathcal{P}$ and $K$ be the corresponding polygon. We assume that $S = \eta(0)$ is not a corner of the polygon (the case when $\eta(0)$ is a corner will be explained later). Enumerate the corners  of $K$ counterclockwise  and denote them by $D_1, \ldots, D_n$. Assume that $S \in [D_n,D_1]$. For each $D_i$ consider the orthonormal coordinate system with the origin at $D_i$ such that $\partial K$ locally looks like a graph of the function $a_i |x|$ for some $a_i > 0$. Take some  smooth convex function $f_i(x)$ such that $f_i(x)$ coincides with $a_i |x|$ outside a small neighborhood of $0$. Using this family of functions $(f_1, \ldots ,f_n)$ we can construct the corresponding smooth family of positively oriented convex Jordan curves $\gamma_s \colon S^1 = \mathbb{R}/\mathbb{Z} \to \mathbb{R}^2$ for $s \in (0,1]$ such that
	\begin{itemize}
		\item $\gamma_{s}$ coincides with the $\graph(s \cdot f_i(x/s))$ in a small neighborhood of $D_i$ (in the corresponding coordinate system)
		\item Outside all these neighborhoods $\gamma_{s}$ coincides with $\partial K$
		\item $\gamma_s(0) = S$
		\item $\left\|\partial\gamma_{s}/\partial q\right\| = \length(\gamma_{s})$.
	\end{itemize}

	\begin{figure}[ht]
		\begin{subfigure}{.42\textwidth}
