		\end{subfigure}%
		\begin{subfigure}{.56\textwidth}
  		\centering
  		\includegraphics[width=0.97\linewidth]{Figures/Figure_corner_approximation.pdf}
		\end{subfigure}
		\caption{Approximation of a polygon.}
		\label{fig:approximation}
	\end{figure}


	Denote $L(s) = \length(\gamma_{s})$ and $\lambda(s) = 1/L(s)$. Take an arbitrary point $O$ in $\mathbb{R}^2$ and consider the family of curves $\widetilde{\gamma}_s = \lambda(s)\cdot\gamma_s$, where $O$ is the center of homothety; $\widetilde{\gamma}_{s}$ is a smooth path in $\mathcal{C}$ for $s \in (0,1]$.

	\begin{theorem} \label{thm:approx_es_ind}
		There exists a limit of $[\widetilde{\gamma}_s]$ in $\overline{\mathcal{AC}} = \overline{\mathcal{AB}}$ when $s \to 0$ and this limit is independent of the choice of the functions $f_1, \ldots, f_n$ and the origin point $O$.
	\end{theorem}
	\begin{proof}
		\emph{(a) Existence of the limit}. To prove that there exists a limit of $[\widetilde{\gamma}_s]$ in $\overline{\mathcal{AC}}$ when $s \to 0$ we will show that
		\begin{equation}\label{main_int:fin}
			\int_0^1 \max_{q \in S^1} \left\| \frac{\partial \widetilde{\gamma}_s}{\partial s}(q) \right\| ds < +\infty.
		\end{equation}
		To prove this, it is enough to demonstrate that
		\begin{equation}\label{second_int:fin}
			\int_0^1 \max_{q \in S^1} \left\| \frac{\partial \gamma_s}{\partial s}(q) \right\| ds < +\infty.
		\end{equation}
		Indeed, note that
		\begin{equation}\label{Leibniz:fin}
			 \frac{\partial \widetilde{\gamma}_s}{\partial s} = \frac{\partial \lambda}{\partial s} (s)\cdot \gamma_s + \lambda(s) \cdot\frac{\partial \gamma_s}{\partial s}.
		\end{equation}
		Since $\lambda(s)$ is monotone, we have
		\begin{equation}\label{Lambda:monotone}
			\int_0^1 \left|\frac{\partial \lambda}{\partial s}(s)\right| ds = \lambda(1) - \lim_{s \to 0} \lambda(s) \leq \lambda(1).
		\end{equation}

		Now~\eqref{main_int:fin} can be inferred from equations~\eqref{second_int:fin},~\eqref{Leibniz:fin},~\eqref{Lambda:monotone} and the fact that $|\lambda(s)|$ and $\|\gamma_s(q)\|$ are bounded. Therefore, we only have to show~\eqref{second_int:fin}.

		\begin{figure}[ht]
  		\centering
  		\includegraphics[width=0.5\textwidth]{Figures/Figure_point_on_an_edge.pdf}
			\caption{Local picture on an edge.}
			\label{fig:ponit_on_an_edge}
		\end{figure}

		Let $B$ be an interior point of some edge of $\partial K$. Let $(q_0,s_0)$ be a point such that $\gamma_{s_0}(q_0) = B$ and $\gamma_{s_0}$ coincides with $\partial K$ in a small neighborhood of $B$. We want to compute $\partial \gamma_s/\partial s$ at the point $(q_0,s_0)$. Denote by $\beta(q)$ the arc-length counterclockwise parametrization of $\partial K$ in some neighborhood of the point $B$ satisfying $\beta(0) = B$. In this case for $(q,s)$ close enough to $(q_0,s_0)$ one has
		\begin{equation}\label{gamma_on_an_edge}
		\gamma_s(q) = \beta((q-Q_B(s)) \cdot L(s)),
		\end{equation}
		 where $Q_B (s)$ is uniquely defined by the equation $\gamma_s(Q_B(s)) = B$. Indeed, for a fixed $s$ both curves have the same initial conditions $\gamma_s(Q_B(s)) = \beta (0) = B$ and the same speed $L(s)$.

		 We can describe $Q_B(s)$ in a slightly different way. Let $l_{SB}(s)$ be the distance between $S$ and $B$ along $\gamma_s$ in the counterclockwise direction, then
		 \begin{equation}\label{eq:Q_B}
		 Q_B(s) = \frac{l_{SB}(s)}{L(s)}
		 \end{equation}
		 For our computations we need the explicit forms of $l_{SB}(s)$ and $L(s)$. Let $\delta_i$ be the difference between the lengths of $\partial K$ and $\gamma_1$ near the corner $D_i$. Then
		\begin{equation}\label{eq:l_SB}
			l_{SB}(s) = l_{SB,\partial K} - s \cdot \sum_{i=1}^k \delta_i,
		\end{equation}
		and
		\begin{equation}\label{eq:Ls}
			L(s) = L_{\partial K} - s \cdot \sum_{i=1}^n \delta_i,
		\end{equation}
		where $L_{\partial K}$ is the length of $\partial K$ and $l_{SB,\partial K}$ is the distance between $S$ and $B$ along $\partial K$ in the counterclockwise direction and $k$ is the number of corners between $S$ and $B$ in the counterclockwise direction. From~\eqref{gamma_on_an_edge}
		\[
			\frac{\partial \gamma_s}{\partial s}(q) = \frac{\partial \beta}{\partial q} (\ldots) \cdot \left[-\frac{\partial Q_B}{\partial s}(s) \cdot L(s) + \frac{\partial L}{\partial s} (s) \cdot (q- Q_B(s))\right].
		\]
		Note that $\beta$ is arc-length parametrized and $Q_B(s_0) = q_0$, therefore,
		\begin{equation}\label{eq:partgamma}
			\left\| \frac{\partial \gamma_s}{\partial s} \right\|_{(q_0,s_0)} = \left|L(s_0) \cdot \frac{\partial Q_B}{\partial s}(s_0)  \right| =  \frac{\left|\frac{\partial l_{SB}}{\partial s}(s_0)\cdot L(s_0) - \frac{\partial L}{\partial s}(s_0)\cdot l_{SB}(s_0)\right|}{L(s_0)},
		\end{equation}
		where the last inequality follows from~\eqref{eq:Q_B}.

		Combining~\eqref{eq:l_SB}, \eqref{eq:Ls}, and~\eqref{eq:partgamma}, one can obtain
		\[
			 \left\| \frac{\partial \gamma_s}{\partial s} \right\|_{(q_0,s_0)} \leq \frac{\bigg|L(s_0) \cdot \sum_{i=1}^k \delta_i\bigg|+\bigg|l_{SB}(s_0)\cdot \sum_{i=1}^n \delta_i \bigg|}{L(s_0)} \leq \frac{2L_{\partial K} \cdot \sum_{i=1}^n \delta_i}{L_{\partial K} - \sum_{i=1}^n \delta_i}.
		\]
		Note that the right-hand side is independent of the choice of $(q_0,s_0)$ provided $\gamma_{s_0}(q) \in \partial K$ in a small neighborhood of $q_0$.

		\begin{figure}[ht]
  		\centering
  		\includegraphics[width=0.5\textwidth]{Figures/Figure_corner_computations.pdf}
			\caption{Local picture near a corner.}
			\label{fig:corner_computations}
		\end{figure}

		Our next goal is to analyze the behavior of $\partial \gamma_s/\partial s$ near any corner. Fix a corner $D_k$ and for every $s\in (0,1]$ consider the pair of points $M_{k} (s)$ and $N_{k} (s)$, where $M_{k}(s)$ is the closest point to $D_k$ on $[D_{k-1},D_k] \cap \gamma_{s}$ and $N_{k}(s)$ is the closest point to $D_k$ on $[D_{k},D_{k+1}] \cap \gamma_{s}$ (see Figure~\ref{fig:corner_computations}). Moreover, let $h_k$ be the length of $\gamma_1$ between $M_{k}(1)$ and $N_{k}(1)$. Let $\alpha (q)$ be the arc-length reparametrization of $\gamma_1$ such that $\alpha(0) = M_{k}(1)$, and consider a coordinate system where $D_k$ is the origin. Then locally we have
		\[
			\gamma_s (q) = s \cdot \alpha\left((q-Q_k(s))\cdot\frac{L(s)}{s} \right),
		\]
		where $Q_k(s)$ is uniquely defined by the equation $\gamma_s (Q_k (s)) = M_{k}(s)$. Therefore,
		\[
			Q_k (s) =  \frac{l_{SD_k,\partial K} - s\cdot \left(\sum_{i=1}^{k-1} \delta_i + \|M_{k}(1) - D_k\|\right)}{L_{\partial K} - s \cdot \sum_{i=1}^n \delta_i}.
		\]
		Our goal is to estimate $\left\|\frac{\partial \gamma_s}{\partial s} (q)\right\|$ for $q \in \left[Q_k(s), Q_k(s) + \frac{h_k \cdot s}{L(s)} \right]$. First of all, for such a $q$ holds
		\[
			\frac{\partial \gamma_s}{\partial s} (q) = \alpha(\ldots) + \frac{\partial \alpha}{\partial q} (\ldots) \cdot \left[s \cdot \frac{\partial}{\partial s} \left((q-Q_k(s))\cdot\frac{L(s)}{s} \right)\right].
		\]
		Then
		\[
			\left\|\frac{\partial \gamma_s}{\partial s} (q)\right\| \leq \max(\|M_{k}(1) - D_k\|, \|N_{k}(1) - D_k\|) + \left|s \cdot \frac{\partial}{\partial s} \left((q-Q_k(s))\cdot\frac{L(s)}{s} \right) \right|.
		\]
		Note that
		\[
			\max_{q \in \left[Q_k(s), Q_k(s) + \frac{h_k \cdot s}{L(s)} \right]}\left|s \cdot \frac{\partial}{\partial s} \left((q-Q_k(s))\cdot\frac{L(s)}{s} \right) \right| \leq L(s)\cdot \left|\frac{\partial Q_k}{\partial s} (s)\right| + \frac{h_k \cdot s^2}{L(s)} \cdot  \left|\frac{\partial}{\partial s} \frac{L(s)}{s} \right|.
		\]
		For the first summand holds
		\[
			L(s)\cdot \left|\frac{\partial Q_k}{\partial s} (s)\right| \leq \frac{2L_{\partial K} \cdot \left(\sum_{i=1}^n \delta_i + L_{\partial K}\right)}{L_{\partial K} - \sum_{i=1}^n \delta_i}.
		\]
		For the second summand holds
		\[
			\frac{h_k \cdot s^2}{L(s)} \cdot  \left|\frac{\partial}{\partial s} \frac{L(s)}{s} \right| \leq \frac{L_{\partial K}^2}{L_{\partial K} - \sum_{i=1}^n \delta_i}.
		\]
		Therefore, from the above estimates it follows that
		\[
			\max_{q \in S^1} \left\|\frac{\partial \gamma_s}{\partial s} (q)\right\| \leq C,
		\]
		where $C$ is independent of $s \in (0,1]$. This implies~\eqref{second_int:fin}.

		\emph{(b) Choice independence}. First of all, note that the approximation procedure is independent of the homothety center $O$, because if we scale a curve by the same factor with respect to different points, then the resulting curves differ by a shift and belong to the same class in $\mathcal{AC}$.

		Assume that $\gamma_{1,s}$ is generated by the family $(f_1, \ldots, f_n)$ and $\gamma_{0,s}$ is generated by the family $(g_1, \ldots, g_n)$. Without loss of generality we assume that $g_i \leq f_i$ for every $i$. Our goal is to prove that for the corresponding families of curves $\widetilde{\gamma}_{1,s}$ and $\widetilde{\gamma}_{0,s}$ holds
		\begin{equation}\label{eq:independ}
			d_{C}(\widetilde{\gamma}_{1,s},\widetilde{\gamma}_{0,s}) = O(s),
		\end{equation}
		when $s \to 0$.

		First of all, take smooth families $(\psi_{1,t},\ldots, \psi_{n,t})$ of convex functions for $t \in [0,1]$ such that $\psi_{i,0} = g_i$, $\psi_{i,1} = f_i$ and $\psi_{i,t}$ is monotone in $t$. Then for each $t \in [0,1]$ we can construct the corresponding smooth family $\gamma_{t,s} \colon S^1 \to \mathbb{R}^2$ for $s \in (0,1]$. Let $\delta_k(t)$ be the difference between the lengths of $\partial K$ and $\gamma_{t,1}$ near the corner $D_k$. Note that every $\delta_k(t)$ is smooth on $[0,1]$ and monotonically increasing in $t$. Let $L(t,s) = \length(\gamma_{t,s})$, then
		\[
			L(t,s) = L_{\partial K} - s\cdot\sum_{i=1}^n\delta_{i}(t).
		\]
		In order to show~\eqref{eq:independ}, it is enough to prove
		\begin{equation}\label{second_eq:independ}
			\int_{0}^1 \max_{q \in S^1} \left\|\frac{\partial \gamma_{t,s}}{\partial t}(q) \right\| dt = O(s).
		\end{equation}
	 Indeed, introduce $\lambda(t,s) = 1/L(t,s)$ and $\widetilde{\gamma}_{t,s} = \lambda(t,s) \cdot \gamma_{t,s}$, then
		\[
			d_{C}(\widetilde{\gamma}_{1,s},\widetilde{\gamma}_{0,s}) \leq \int_{0}^1 \max_{q \in S^1} \left\|\frac{\partial \widetilde{\gamma}_{t,s}}{\partial t}(q) \right\| dt \leq O(s) + O(1)\cdot |\lambda(1,s) - \lambda(0,s)| = O(s).
		\]

		Let $B$ be an interior point of some edge of $\partial K$. Let $(q_0,t_0,s_0)$ be a point such that $\gamma_{t_0,s_0}(q_0) = B$ and $\gamma_{t_0,s_0}$ coincides with $\partial K$ in a small neighborhood of $B$. Denote by $\beta(q)$ the arc-length counterclockwise parametrization of $\partial K$ in some neighborhood of the point $B$ satisfying $\beta(0) = B$. Then for $(q,t,s)$ close enough to $(q_0,t_0,s_0)$ we have
		\begin{equation}\label{eq:gamma_ts}
			\gamma_{t,s}(q) = \beta((q-Q_B(t,s)) \cdot L(t,s)),
		\end{equation}
		where $Q_B (t,s)$ is uniquely defined by the equation $\gamma_{t,s}(Q_B(t,s)) = B$. Note that $Q_B(t,s)$ can also be expressed in the form
		\begin{equation}\label{eq:Q_Bts}
			Q_B(t,s) = \frac{l_{SB,\partial K} - s \cdot \sum_{i=1}^k\delta_{i}(t)}{L_{\partial K} - s\cdot\sum_{i=1}^n\delta_{i}(t)},
		\end{equation}
		where $k$ is the number of corners between $S$ and $B$ in counterclockwise direction. From~\eqref{eq:gamma_ts}
		\[
			\frac{\partial \gamma_{t,s}}{\partial t} = \frac{\partial \beta}{\partial q}(\ldots) \cdot \left[ -\frac{\partial Q_B}{\partial t} (t,s) \cdot L(t,s) + \frac{\partial L}{\partial t}(t,s) \cdot (q- Q_B(t,s)) \right].
		\]
		Note that $\beta$ is arc-length parametrized and $Q_B(t_0,s_0) = q_0$, therefore,

		\begin{equation}\label{eq:partgammateq}
			\left\|\frac{\partial \gamma_{t,s}}{\partial t}\right\|_{(q_0,t_0,s_0)} = L(t_0,s_0) \cdot \left|\frac{\partial Q_B}{\partial t} (t_0,s_0)\right|.
		\end{equation}
		Let us rewrite formula~\eqref{eq:Q_Bts} in the form
		\[
				Q_B(t,s) = \frac{l_{SB,\partial K} - s \cdot f(t)}{L_{\partial K} - s\cdot g(t)},
		\]
		where $f(t) = \sum_{i=1}^k\delta_{i}(t)$ and $g(t) = \sum_{i=1}^n\delta_{i}(t)$. Then
		\[
				\frac{\partial Q_B}{\partial t}(t,s) = \frac{s \cdot g'(t)\cdot [l_{SB,\partial K} - s \cdot f(t)] - s\cdot f'(t)\cdot [L_{\partial K} - s\cdot g(t)]}{[L_{\partial K} - s\cdot g(t)]^2}.
		\]
		Therefore,
		\begin{equation}\label{eq:Q_Bts_ineq}
			\left|\frac{\partial Q_B}{\partial t}(t_0,s_0)\right| \leq \frac{|g'(t_0)\cdot L_{\partial K}| + |f'(t_0)\cdot L_{\partial K}|}{[L(t_0,s_0)]^2} \cdot s_0 \leq \frac{2 \left[\sum\limits_{i=1}^n \delta_{i}'(t_0) \right] \cdot L_{\partial K}}{[L(t_0,s_0)]^2} \cdot s_0.
		\end{equation}
		In the last inequality we used the fact that every function $\delta_i (t)$ is monotonically increasing. Thus, by formula~\eqref{eq:partgammateq} and formula~\eqref{eq:Q_Bts_ineq} one can obtain
		\[
			 \left\|\frac{\partial \gamma_{t,s}}{\partial t}\right\|_{(q_0,t_0,s_0)} \leq  \frac{2 \left[\sum\limits_{i=1}^n \delta_{i}'(t_0) \right] \cdot L_{\partial K}}{L(t_0,s_0)} \cdot s_0 \leq \frac{2 \left[\sum\limits_{i=1}^n \delta_{i}'(t_0) \right] \cdot L_{\partial K}}{L_{\partial K} - \sum\limits_{i=1}^n \delta_{i}(1)} \cdot s_0 \leq C \cdot s_0,
		\]
		for some constant $C$ independent of the choice of such a $(q_0,t_0,s_0)$ since every function $\delta_i$ is smooth on $[0,1]$.

		Fix a corner $D_k$ and for every $s \in (0,1]$ consider the pair of points $M_{k}(s)$ and $N_{k}(s)$ where $M_{k}(s)$ is the closest point to $D_k$ on $[D_{k-1},D_k] \cap \gamma_{1,s}$ and $N_{k}(s)$ is the closest point to $D_k$ on $[D_{k},D_{k+1}] \cap \gamma_{1,s}$. Moreover, let $h_k(t) \in C^\infty([0,1])$ be the length of $\gamma_{t,1}$ between $M_{k}(1)$ and $N_{k}(1)$. Let $\alpha_t (q)$ be the arc-length reparametrization of $\gamma_{t,1}$ such that $\alpha_t(0) = M_{k}(1)$. Consider the coordinate system where $D_k$ is the origin. Then locally holds
		\[
			\gamma_{t,s} (q) = s \cdot \alpha_t \left((q-Q_k(t,s))\cdot\frac{L(t,s)}{s} \right),
		\]
		where
		\[
			Q_k (t,s) = \frac{l_{SD_k,\partial K} - s\cdot \left(\sum_{i=1}^{k-1} \delta_i(t) + \|M_{k}(1) - D_k\|\right)}{L_{\partial K} - s \cdot \sum_{i=1}^n \delta_i(t)}.
		\]
		Our goal is to estimate $\left\|\frac{\partial \gamma_{t,s}}{\partial t} (q)\right\|$ for $q \in \left[Q_k(t,s), Q_k(t,s) + \frac{h_k(t) \cdot s}{L(t,s)} \right]$. First of all, for such a $q$ holds
		\[
			\frac{\partial \gamma_{t,s}}{\partial t} (q) = s \cdot \frac{\partial\alpha_t}{\partial t}(\ldots) + \frac{\partial \alpha_t}{\partial q} (\ldots) \cdot \frac{\partial}{\partial t} \left[(q-Q_k(t,s))\cdot L(t,s)\right].
		\]
		For the first summand holds
		\[
			s \cdot \left\|\frac{\partial\alpha_t}{\partial t}(\ldots)\right\| \leq s \cdot \max_{q \in [0,h_k(t)]} \left\|\frac{\partial\alpha_t}{\partial t}(q)\right\| \leq C\cdot s.
		\]
		For the second summand holds
		\begin{align*}
			&\left\|\frac{\partial \alpha_t}{\partial q} (\ldots) \cdot \frac{\partial}{\partial t} \left[(q-Q_k(t,s))\cdot L(t,s)\right]\right\| = \left|\frac{\partial}{\partial t} \left[(q-Q_k(t,s))\cdot L(t,s)\right]\right| \leq \\
			&\leq \frac{h_k(t) \cdot s}{L(t,s)} \cdot\left|\frac{\partial L}{\partial t}(t,s)\right| + L(t,s) \cdot \left|\frac{\partial Q_k}{\partial t}(t,s)\right| \leq C \cdot s.
		\end{align*}
		Thus,
		\[
			\max_{\substack{q \in S^1\\ t \in [0,1]}} \left\|\frac{\partial \gamma_{t,s}}{\partial t}(q)\right\| = O(s).
		\]
		This completes the proof of Theorem~\ref{thm:approx_es_ind}.
	\end{proof}

	Therefore, we have defined an element $\Psi([\eta(q)]) \in \overline{\mathcal{AC}}$ for every $[\eta(q)] \in \mathcal{AP}$ such that $\eta(0)$ is not a corner. If $\eta(0)$ is a corner, we can define $\Psi([\eta(q)])$ as $\lim_{\tau \to 0} \Psi([\eta(q + \tau)]) \in \overline{\mathcal{AC}}$. Thus, we have a map $\Psi \colon \mathcal{AP} \to \overline{\mathcal{AC}}$.  As the result we have an $S^1$-equivariant map $\mathcal{AP} \to \overline{\BM}$, which completes the proof of Theorem~\ref{thm:approx}.



	\section{Comparison of the metric \texorpdfstring{$d_{B}$}{TEXT} with other geometric distances}	\label{sec:comparison}

	In this section, we discuss two estimates for the geometric distance $d_B$. First, note that $d_B$ is greater or equal than the standard $C^0$ distance.

	\begin{lemma}\label{lem:compare_bil_c0}
		Let $\alpha$ and $\beta$ be two billiard tables, then
		\[
  		d_B(\alpha,\beta) \geq \max_{q \in S^1} \|\alpha(q) - \beta(q) \|
		\]
	\end{lemma}
	\begin{proof}
		Consider a path $\gamma_s$ of billiard tables between $\alpha$ and $\beta$. Then
		\[
 			\int_{0}^1 \max_{q \in S^1} \left\|\frac{\partial \gamma_s}{\partial s} (q)\right\| ds \geq \max_{q \in S^1} \int_{0}^1 \left\|\frac{\partial \gamma_s}{\partial s} (q)\right\|ds \geq \max_{q \in S^1} \|\alpha(q) -\beta(q)\|.
		\]
\end{proof}


	Now, let $\alpha \colon S^1 \to \mathbb{R}^2$ be a billiard table and $n(q)$ be the normal outward vector field on $\alpha$. Let $f \colon S^1 \to \mathbb{R}$ be a smooth function. If $f$ is $C^2$-small enough, then every curve of the form
	\[
		\gamma_s(q) = \alpha (q) + s\cdot f(q)\cdot n(q)
	\]
	has positive curvature for every $s \in [0,1]$. In addition, assume that $\gamma_1$ has length one. Then after arc-length reparametrization, with the fixed starting point $\gamma_1(0)$, we obtain a billiard table~$\beta$. Our goal is to prove an inequality of the form
	\[
		d_{B} (\alpha,\beta) \leq C \cdot \left( \max_{q \in S^1} |f(q)| + \max_{q \in S^1}\left|\frac{\partial f}{\partial q} (q)\right| \right),
	\]
	where $C$ depends only on $\alpha$. Let $L(s)$ be the length of $\gamma_s(q)$, then	
	\[
  	L(s) = \int_0^1 \left\|\frac{\partial \gamma_s}{\partial q}\right\| dq = \int_0^1\left\|\frac{\partial \alpha}{\partial q} + s \frac{\partial f}{\partial q} n + sf\frac{\partial n}{\partial q}\right\|dq =\int_0^1 \sqrt{(1 + s f\cdot k)^2 + \left(s\cdot\partial f/\partial q\right)^2}dq,
	\]
	where $k$ is the curvature of $\alpha$. Now consider the following family
	\[
  	\widetilde{\gamma}_s(q) = \frac{\gamma_s(q)}{L(s)},
	\]
	then every curve in this family has length one. Consider an arc-length reparametrization $\hat{\gamma}_s$ of every curve $\widetilde{\gamma}_s$ such that $\hat{\gamma}_s(0) = \widetilde{\gamma}_s(0)$, for every $s$. Let us introduce the function
	\[
  	l(s,q) = \int_0^q \left\|\frac{\partial \widetilde{\gamma}_s}{\partial q}\right\|dq = \frac{\int_0^q \sqrt{(1 + s f\cdot k)^2 + \left(s\cdot\partial f/\partial q\right)^2}dq}{\int_0^1 \sqrt{(1 + s f\cdot k)^2 + \left(s\cdot\partial f/\partial q\right)^2}dq},
	\]
	then $\hat{\gamma}_s(l(s,q)) = \widetilde{\gamma}_s(q)$ and one can show that
	\[
		\max_{q \in S^1} \left\|\frac{\partial \hat{\gamma}_s}{\partial s}(q)\right\| \leq \max_{q \in S^1}\left\|\frac{\partial \widetilde{\gamma}_s}{\partial s}(q)\right\| + \max_{q \in S^1}\left|\frac{\partial l}{\partial s}(s,q)\right|.
	\]
	Using above equations one can show
	\[
		d_{B} (\alpha,\beta) \leq l_B(\hat{\gamma}_s) \leq C \cdot \left( \max_{q \in S^1} |f(q)| + \max_{q \in S^1}\left|\frac{\partial f}{\partial q} (q)\right| \right),
	\]
	where the constant $C$ and a $C^2$-neighbourhood (that $f$ belongs to) depend on $\alpha$, more precisely on its curvature $k$.

\section{Discussion and open problems}\label{sec:discussion}

Theorem~\ref{thm:approx} provides an embedding of the space $\mathcal{AP}$ of marked polygons (up to affine isometries) into the completion of the set $\BM$ of symplectic diffeomorphisms with respect to the Hofer metric.

\begin{question}
	Is the pullback of the Hofer metric to $\mathcal{A}\mathcal{P}$ given by semi-algebraic functions of the vertices? If not, does there exist an algorithm calculating this pull back with arbitrary precision?
\end{question}

Let $P$ be a marked polygon, and $\alpha_i$ be an approximating sequence from Theorem~\ref{thm:approx}. Consider the corresponding billiard ball maps $\psi_P$ (which is defined on a proper full-measure subset of the annulus) and $\psi_i := \psi_{\alpha_i}$.

\begin{question}\label{q-dyn}
	What is the relation between the dynamics of $\psi_P$ and the one of $\psi_i$ for $i \to \infty$?
\end{question}

Let us note that since $\psi_P$ is discontinuous, we cannot hope that $\psi_i$ converges to $\psi_P$ in the uniform norm. However,  the limit of $\graph(\psi_i)$ in the Hausdorff metric likely contains the graph of $\psi_P$.

A potential approach to Question \ref{q-dyn} could be as follows. It sounds likely
that one can associate a version of filtered Floer or generating function homology
with a billiard ball map $\psi$ or its iteration $\psi^k$, $k \in \mathbb{N}$,   cf. \cite{Cotton-Clay,Felshtyn}. This gives rise to
a persistence module along the lines of
\cite{PS, PSRZ}. Write $\Barc(\psi^k)$ for the corresponding barcode.
Since the sequence $\psi_i^k$ is Cauchy with respect to the Hofer distance,
the corresponding sequence of barcodes $\Barc(\psi_i^k)$ should be Cauchy with respect to
the bottleneck distance (cf. \cite{PS,PSRZ}).
Hence it defines an element, say $\mathcal{C}_k$, in the completion of the space of barcodes. Now we are ready to formulate a more precise version of Question \ref{q-dyn}.

\begin{question}
\label{q-bar}
Which dynamical properties of the billiard in $P$ (length of periodic orbits, if any, their multiplicities, etc.) can be read from the sequence of barcodes $\mathcal{C}_k$?
\end{question}

Development of the Floer theory becomes more natural if one relates the group $\Symp(A, \partial A)$ to
the group $\Symp_c(A,\omega)$ of symplectic diffeomorphisms supported in the interior of $A$.

\begin{question}
		Can we isometrically embed  $\Symp(A, \partial A)$
into the completion of  $\Symp_c(A,\omega)$ with respect to the corresponding Hofer metric?
	\end{question}

Finally, Theorem~\ref{thm:approx} likely extends to more general convex (not necessarily
strictly convex) piece-wise smooth curves other than polygons. That being said, the level of
generality in which the theorem holds is unclear to us.

\begin{question} Let $C$ be a continuous simple closed plane counterclockwise arc-length parametrized curve of length $1$ bounding
a convex set in $\mathbb{R}^2$. Does there exist a sequence of billiard tables $\alpha_i$ which is Cauchy in $d_B$-distance and which $C^0$-converges to $C$.
\end{question}

Let $\alpha$ be a billiard table. Fix $n$, and consider the {\it generating function} $F_{\alpha} \colon S^n \to \mathbb{R}$ defined as
\[
		F_{\alpha}(q_1,\ldots, q_n) = \sum_{i=1}^n \|\alpha(q_{i+1}) - \alpha(q_i)\|,
\]
where $q_{n+1} = q_1$. It is well known (for example, see~\cite{katok1995introduction}) that every closed billiard trajectory of period $n$ is a critical point of the function $F_{\alpha}$. 
Now, consider a billiard table $\beta$ which is $C^0$-close to $\alpha$.
Let $F_{\beta} \colon S^n \to \mathbb{R}$ be the corresponding generating function.  Then $F_{\beta}$ is $C^0$-close to $F_{\alpha}$. Indeed,
\begin{align*}
\sup |F_{\alpha}-F_{\beta}| &\leq \sum_{i=1}^n \bigg|\|\alpha(q_{i+1}) - \alpha(q_i)\| - \|\beta(q_{i+1}) - \beta(q_i)\|  \bigg| \leq\\
&\leq \sum_{i=1}^n \|(\alpha(q_{i+1}) - \alpha(q_i)) - (\beta(q_{i+1}) - \beta(q_i)) \| \leq \\
&\leq  \sum_{i=1}^n \bigg[  \|\alpha(q_{i+1}) - \beta(q_{i+1})\|+ \|\alpha(q_{i}) - \beta(q_i) \|\bigg] \leq 2n \cdot \sup \|\alpha - \beta\|.
\end{align*}
An important source of the Morse-theoretic information about $F_{\alpha}$
(including the actions of $n$-periodic orbits and their indices) is its barcode. By the stability theorem (see, e.g., \cite{PSRZ}), the barcodes of $F_\alpha$ and $F_\beta$ are close in the bottleneck distance. This consideration together with Lemma~\ref{lem:compare_bil_c0} does not leave much hope to obtain a new information about actions and indices of periodic orbits with the help of our technique.

In contrast to this, Corollary \ref{cor-dyn} above yields a dynamical phenomenon which apparently
cannot be obtained via generating functions, at least in a naive way. Let $y$ be an $n$-periodic point of the billiard ball map $\psi_{\alpha}$.  Consider any set $X \subseteq A$ with $e(X)>0$, such that $X$ and $\psi_\alpha^n(X)$ lie sufficiently close to $y$ with respect to the Euclidean metric on $A$. 
Let $\beta$ be another billiard table with $d_{B}(\alpha,\beta) < e(X)/4n$. By  Corollary \ref{cor-dyn}, there exists $x \in X$ with $\psi_\beta^n (x) \in \psi_\alpha^n(X)$. In other words, the trajectory of $x$ for time $n$ with respect to $\beta$ is ``almost" periodic:  the terminal point is close to the initial one. 

\begin{remark}
We conclude with a remark about the comparison of the two approaches. 
If we consider a billiard table $\alpha$ with a periodic orbit of period $n$ and action $E$, then from the stability theorem for barcodes one should be able to deduce 
that every sufficiently  $C^0$-close billiard table $\beta$ also has a periodic orbit of period $n$ and action close to $E$\footnote{It would be interesting to complete details of this argument}.
However, we do not get any insight on the location of this orbit. At the same time, the displacement energy argument shows that if we consider any sufficiently $d_B$-close billiard table $\beta$, then near this periodic point of $\psi_\alpha$ there exists an ``almost" periodic point of $\psi_\beta$.
\end{remark} 


	\section{Appendix} \label{section:Appendix}
	\begin{lemma}[The Hamilton--Jacobi equation] \label{lem:Ham-Jac}
		Let $\widetilde{\psi}_s$ be a smooth family of symplectomorphisms of $\mathbb{R} \times (-1,1)$ and $\widetilde{F}_s \colon U \to \mathbb{R}$ be a smooth family of functions, where $U = \{(q,Q) \in \mathbb{R}^2 : q < Q < q+1\}$ and $s \in [0,1]$. Assume that
		\begin{align}
			\frac{\partial \widetilde{F}_s}{\partial q} (q, Q_s(q,p)) &= - p, \label{eq:gen_small}\\
			\frac{\partial \widetilde{F}_s}{\partial Q} (q, Q_s(q,p)) & = P_s(q,p), \label{eq:gen_big}
		\end{align}
		for every $(q,p) \in \mathbb{R} \times (-1,1)$ and $s \in [0,1]$, where
		\[
			(Q_s(q,p),P_s(q,p)) = \widetilde{\psi}_s(q,p).
		\]
		Then the family $\widetilde{\psi}_s$ is Hamiltonian (without any boundary conditions) with the Hamiltonian function
		\[
			\widetilde{H}_s(Q,P) = -\frac{\partial \widetilde{F}_s}{\partial s}(q_s(Q,P), Q),
		\]
		where
		\[
			(q_s(Q,P),p_s(Q,P)) = \widetilde{\psi}_s^{-1}(Q,P).
		\]
	\end{lemma}

	\begin{proof}
		Since $\mathbb{R}\times(-1,1)$ is simply connected the family of symplectomorphisms $\widetilde{\psi}_s$ is Hamiltonian with some Hamiltonian function $\widetilde{H}_s(Q,P)$. Therefore
		\begin{align}
			\frac{\partial Q_s}{\partial s}(q,p) &= \frac{\partial \widetilde{H}_s}{\partial P}(Q_s(q,p),P_s(q,p)), \label{eq:ham_coordinate}\\
			\frac{\partial P_s}{\partial s}(q,p) &= -\frac{\partial \widetilde{H}_s}{\partial Q}(Q_s(q,p),P_s(q,p)). \label{eq:ham_momentum}
		\end{align}
		Differentiating equation~\eqref{eq:gen_small} by $s$ and equation~\eqref{eq:gen_big} by $q$ we have
		\begin{align*}
			\frac{\partial^2 \widetilde{F}_s}{\partial s\, \partial q} + \frac{\partial^2 \widetilde{F}_s}{\partial Q\, \partial q} \cdot \frac{\partial Q_s}{\partial s} &= 0,\\
			\frac{\partial^2 \widetilde{F}_s}{\partial q\, \partial Q} + \frac{\partial^2 \widetilde{F}_s}{\partial Q^2} \cdot \frac{\partial Q_s}{\partial q} &= \frac{\partial P_s}{\partial q}.
		\end{align*}
		Hence
		\[
			\frac{\partial^2 \widetilde{F}_s}{\partial s\, \partial q} = \frac{\partial Q_s}{\partial s} \cdot \left(\frac{\partial^2 \widetilde{F}_s}{\partial Q^2} \cdot \frac{\partial Q_s}{\partial q} -  \frac{\partial P_s}{\partial q}\right).
		\]
		Differentiating equation~\eqref{eq:gen_big} by $s$ we get
		\[
			\frac{\partial^2 \widetilde{F}_s}{\partial Q^2} \cdot \frac{\partial Q_s}{\partial s} = \frac{\partial P_s}{\partial s} - \frac{\partial^2 \widetilde{F}_s}{\partial s\, \partial Q},
		\]
		substituting this in the previous equation and using equations~\eqref{eq:ham_coordinate},~\eqref{eq:ham_momentum} we have
		\[
			- \left[\frac{\partial^2 \widetilde{F}_s}{\partial s\, \partial q} + \frac{\partial^2 \widetilde{F}_s}{\partial s\, \partial Q} \cdot \frac{\partial Q_s}{\partial q}\right] = \frac{\partial \widetilde{H}_s}{\partial P} \cdot \frac{\partial P_s}{\partial q} + \frac{\partial \widetilde{H}_s}{\partial Q} \cdot \frac{\partial Q_s}{\partial q}.
		\]
		Introducing functions
		\begin{align*}
			f_s(q,p) &= -\frac{\partial \widetilde{F}_s}{\partial s}(q, Q_s(q,p)),\\
			g_s(q,p) &= \widetilde{H}_s(Q_s(q,p),P_s(q,p)),
		\end{align*}
		we can rewrite equation above as
		\[
			\frac{\partial f_s}{\partial q} (q,p) = \frac{\partial g_s}{\partial q}(q,p).
		\]
		Differentiating equality~\eqref{eq:gen_big} by $s$ and multiplying it by $\partial Q_s/\partial p$ and differentiating the same equality by $p$ we have
		\begin{align*}
			\frac{\partial^2 \widetilde{F}_s}{\partial s\, \partial Q} \cdot \frac{\partial Q_s}{\partial p} + \frac{\partial^2 \widetilde{F}_s}{\partial Q^2} \cdot \frac{\partial Q_s}{\partial s} \cdot \frac{\partial Q_s}{\partial p} &= \frac{\partial P_s}{\partial s} \cdot \frac{\partial Q_s}{\partial p},\\
			\frac{\partial^2 \widetilde{F}_s}{\partial Q^2} \cdot \frac{\partial Q_s}{\partial p} &= \frac{\partial P_s}{\partial p}.
		\end{align*}
		Together with equations~\eqref{eq:ham_coordinate},~\eqref{eq:ham_momentum} we have
		\[
			- \frac{\partial^2 \widetilde{F}_s}{\partial s\, \partial Q} \cdot \frac{\partial Q_s}{\partial p} = \frac{\partial \widetilde{H}_s}{\partial P} \cdot \frac{\partial P_s}{\partial p} + \frac{\partial \widetilde{H}_s}{\partial Q} \cdot \frac{\partial Q_s}{\partial p},
		\]
		which is equivalent to
		\[
			\frac{\partial f_s}{\partial p} (q,p) = \frac{\partial g_s}{\partial p} (q,p).
		\]
		Thus,
		\[
			-\frac{\partial \widetilde{F}_s}{\partial s}(q_s(Q,P), Q) = \widetilde{H}_s(Q,P) + \varphi(s),
		\]
		for some smooth function $\varphi(s)$, but this function does not affect on the motion.
	\end{proof}



