\subsection{SCA-based Resource Allocation for Sub-problem $\mathbf{\mathcal{P}1}$}

We first focus on dealing with the resource allocation sub-problem. With the given AeBS deployment $\mathbf{L}$ and user association $\boldsymbol{\alpha}$ between AeBSs and GUs, $\mathcal{P}0$ is rewritten as
\begin{subequations}\label{subproblem_1}
	\begin{align}
  \mathcal{P}1: 
  \mathop{\mathrm{max}}\limits_{\mathbf{P}, \mathbf{C}} \ 
		 & \kappa R_{\mathrm{sum}} \qquad \qquad \label{P1_objective}
		\\
		\mathrm{s.t.} \ 
		&\mathrm{C5}\sim \mathrm{C8},
	\end{align}
\end{subequations}
where $\kappa = \lambda_2 / R_N$ is a constant.
Owing to the non-convex rate expressions, the objective function (\ref{P1_objective}) and constraints (\ref{generative_data_stream_can_be_decoded}), (\ref{minimum_achievable_sum_rate}) and (\ref{nonnegativity_of_common_rate}) in $\mathcal{P}1$ are non-convex. To address this resource allocation sub-problem, we adopt the SCA algorithm to jointly optimize beamforming matrix $\mathbf{P}$ and common rate $\mathbf{C}$.

We begin by introducing the slack variable sets $\boldsymbol{\varphi} = \left\{\varphi_{k,n}^{p} | k \in \mathcal{K}, n \in \mathcal{N}_k \right\}$, $\boldsymbol{\nu}_c = \left\{\nu_{k,n}^{c} | k \in \mathcal{K}, n \in \mathcal{N}_k\right\}$, $\boldsymbol{\nu}_p = \left\{\nu_{k,n}^{p} | k \in \mathcal{K}, n \in \mathcal{N}_k\right\}$, $\boldsymbol{\chi}_c = \left\{\chi_{k,n}^{c} | k \in \mathcal{K}, n \in \mathcal{N}_k\right\}$, $\boldsymbol{\chi}_p = \left\{\chi_{k,n}^{p} | k \in \mathcal{K}, n \in \mathcal{N}_k\right\}$, 
% $\boldsymbol{\pi}_c = [\pi_{1,1}^{c},\dots,\pi_{1,\left | \mathcal{N}_1 \right |}^{c},\dots, \pi_{K,1}^{c},\dots,\pi_{K,\left | \mathcal{N}_K \right |}^{c}]$, and $\boldsymbol{\pi}_p = [\pi_{1,1}^{p},\dots,\pi_{1,\left | \mathcal{N}_1 \right |}^{p},\dots, \pi_{K,1}^{p},\dots,\pi_{K,\left | \mathcal{N}_K \right |}^{p}]$, 
where $\varphi_{k,n}^{p}$ denotes the minimum threshold for the private rate $r_{k,n}^{c}$. $\nu_{k,n}^{c}$ and $\nu_{k,n}^{p}$ represent the minimum required SINRs for the common and private streams, respectively. The parameters $\chi_{w,k}^{c}$ and $\chi_{w,k}^{p}$ correspond to the upper bounds on the interference-plus-noise terms associated with $\nu_{k,n}^{c}$ and $\nu_{k,n}^{p}$, respectively. Similarly, $\pi_{k,n}^{c}$ and $\pi_{k,n}^{p}$ specify the lower limits for the power of useful signals corresponding to $\nu_{k,n}^{c}$ and $\nu_{k,n}^{p}$, respectively. For a fixed DEP and blocklength, $Y =  \frac{Q^{-1}\left(\epsilon \right)} {\sqrt{l}} \log_{2}{e}$ is a constant. Moreover, we define $y_{k,n}^{i}=1-\left(1+\nu_{k,n}^{i}\right)^{-2}, \forall i \in \left \{ c,p \right \} $. Based on these introduced variables, sub-problem (\ref{subproblem_1}) is rewritten as
\begin{subequations} \label{subproblem_1-2}
\begin{align}
 \mathcal{P}1\textit{-}1: &\ \max _{\mathbf{P}, \mathbf{C}, \boldsymbol{\varphi}, \boldsymbol{\nu}_{c}, \atop \boldsymbol{\nu}_p, \boldsymbol{\chi_{c}}, \boldsymbol{\chi}_p} { \sum_{k\in\mathcal{K}} \sum_{n\in \mathcal{N}_k} \left(r_{k,n}^{c}+\varphi_{k,n}^{p}\right)} \\
    \text { s.t.} \ & \log_{2}\left(1+\nu_{k,n}^{c}\right) - Y\sqrt{y_{k,n}^{c}} \ge \sum_{n\in \mathcal{N}_k} r_{k,n}^{c}, \forall k, n \label{SCA_constraint_common_rate} \\
    &\log_{2}\left(1+\nu_{k,n}^{p}\right) - Y\sqrt{y_{k,n}^{p}} \ge  \varphi_{k,n}^{p}, \forall k, n, \label{SCA_constraint_private_rate} \\
    &\frac{ |\mathbf{h}_{k,n}^H \mathbf{p}_{k,0} |^2}{\chi_{k,n}^{c}} \ge \nu_{k,n}^{c}, \quad \forall k,n, \label{common_SINR_constraint} \\    
    &\frac{ |\mathbf{h}_{k,n}^H \mathbf{p}_{k,n} |^2}{\chi_{k,n}^{p}} \ge \nu_{k,n}^{p}, \quad \forall k,n, \label{private_SINR_constraint} \\ 
    % & \tilde{\mathbf{h}}_{w, k}^{H} \mathbf{W}_{w,c} \tilde{\mathbf{h}}_{w,k} \ge \left(\pi_{w,k,c}\right)^2, \quad \forall w, k, \label{SCA_power_of_useful_signal_common_stream} \\
    % & \tilde{\mathbf{h}}_{w, k}^{H} \mathbf{W}_{w,k} \tilde{\mathbf{h}}_{w,k} \ge \left(\pi_{w,k,p}\right)^2, \quad \forall w, k, \label{SCA_power_of_useful_signal_private_stream} \\
    & \chi_{k,n}^{c} \ge \sum_{j \in \mathcal{N}_k} |\mathbf{h}_{k,n}^H \mathbf{p}_{k,j} |^2+ \Psi_{k,n} + \sigma^{2}, \forall k,n, \label{SINR_approximate_common_rate} \\
    & \chi_{w,k}^{p} \ge \sum_{j \in \mathcal{N}_k \setminus n } |\mathbf{h}_{k,n}^H \mathbf{p}_{k,j} |^2+ \Psi_{k,n} + \sigma^{2}, \forall k,n, \label{SINR_approximate_private_rate} \\
    & r_{k,n}^{c} + \varphi_{k,n}^{p} \ge R_{\mathrm{min}}, \quad \forall k,n, \label{minimum_achievable_sum_rate_approximate} \\
    & (\textup{\ref{nonnegativity_of_common_rate}}), (\textup{\ref{constraint_sum_of_transmit_power}}), \notag
\end{align}
\end{subequations}
where $\Psi_{k,n} = \sum_{i \in \mathcal{K}\setminus \left\{k\right\}^{}} \left(|\mathbf{h}_{i,0}^{H} \mathbf{p}_{i,0}|^2 + \sum_{n \in \mathcal{N}_{i}^{}} |\mathbf{h}_{i,n}^{H} \mathbf{p}_{i,n}|^2\right)$. Problem (\ref{subproblem_1-2}) remains non-convex owing to the non-convexity of constraints (\ref{SCA_constraint_common_rate})-(\ref{private_SINR_constraint}). Applying the Taylor series expansion, constraints (\ref{SCA_constraint_common_rate}) and (\ref{SCA_constraint_private_rate}) at $\nu_{k,n}^{c\left[\ell\right]}$ and $\nu_{k,n}^{p\left[\ell\right]}$ at iteration $\ell$ are approximated as 
\begin{subequations} \label{SCA_Taylor_rate_1}
\begin{align}
& \log _{2}\left(1+\nu_{k,n}^{c}\right) - 
Y\Bigg\{\Bigg[ 1 - \left( 1 + \nu _ {k,c} ^ {c [ \ell ] } \right) ^ { - 2 } \Bigg] ^ { - \frac { 1 } { 2 } } 
\Bigg[\left(1+\nu_{k,n}^{c [\ell]}\right)^{-3} \notag \\
& \ \times \left(\nu_{k,n}^{c}-\nu_{k,n}^{c [\ell]}\right) - \left(1+\nu_{k,n}^{c [\ell]}\right)^{-2} + 1\Bigg]\Bigg\} \geq \sum_{j \in \mathcal{N}_k} r_{k,n}^{c}, \label{SCA_constraint_common_rate_1} \\
& \log _{2}\left(1+\nu_{k,n}^{p}\right) - 
Y\Bigg\{\Bigg[ 1 - \left( 1 + \nu _ {k,n} ^ {p [ \ell ] } \right) ^ { - 2 } \Bigg] ^ { - \frac { 1 } { 2 } } 
\Bigg[\left(1+\nu_{k,n}^{p [\ell]}\right)^{-3} \notag \\
& \ \times \left(\nu_{k,n}^{p}-\nu_{k,n}^{p [\ell]}\right) - \left(1+\nu_{k,n}^{p [\ell]}\right)^{-2} + 1\Bigg]\Bigg\} \geq \varphi_{k,n}^{p}. \label{SCA_constraint_private_rate_1}
\end{align}
\end{subequations}
Also, we separately approximate constraints (\ref{common_SINR_constraint}) and (\ref{private_SINR_constraint}) at the respective points $\left(\mathbf{p}_{k,0}^{\left[\ell\right]}, \chi_{k,n}^{c \left[\ell\right]}\right)$ and $\left(\mathbf{p}_{k,n}^{\left[\ell\right]}, \chi_{k,n}^{p \left[\ell\right]}\right)$, as detailed follows:
\begin{subequations} \label{SCA_Taylor_rate_2}
\begin{align}
& \ \frac{2\Re\left\{\left(\mathbf{p}_{k,0}^{[\ell]}\right)^H\mathbf{h}_{k,n}\mathbf{h}_{k,n}^H\mathbf{p}_{k,0}\right\}}{\chi_{k,n}^{c[\ell]}}-\frac{\left|\mathbf{h}_{k,n}^H\mathbf{p}_{k,0}^{\left[\ell \right]}\right|^2\chi_{k,n}^{c}}{\left(\chi_{k,n}^{c[\ell]}\right)^2}\geq\nu_{k,n}^{c}, \\
& \ \frac{2\Re\left\{\left(\mathbf{p}_{k,n}^{[\ell]}\right)^H\mathbf{h}_{k,n}\mathbf{h}_{k,n}^H\mathbf{p}_{k,n}\right\}}{\chi_{k,n}^{p[\ell]}}-\frac{\left|\mathbf{h}_{k,n}^H\mathbf{p}_{k,n}^{\left[\ell \right]}\right|^2\chi_{k,n}^{p}}{\left(\chi_{k,n}^{p[\ell]}\right)^2}\geq\nu_{k,n}^{p}.
\end{align}
\end{subequations}

By following the aforementioned processing steps, the original non-convex formulation is converted into a convex optimization problem, allowing it to be efficiently solved using the SCA algorithm. 
The core idea of the SCA method is to iteratively approximate the initial non-convex problem by a sequence of convex subproblems, each of which can be successively tackled using standard optimization techniques.
Based on the optimal result~$(\mathbf{P}^{\left[\ell\right]}, \boldsymbol{\nu}_{c}^{\left[\ell\right]}, \boldsymbol{\nu}_p^{\left[\ell\right]}, \boldsymbol{\chi}_c^{\left[\ell\right]}, \boldsymbol{\chi}_p^{\left[\ell\right]})$ obtained in the previous iteration $\ell-1$, the sub-problem at iteration $\ell$ can be solved as
\begin{subequations} \label{subproblem_1-3}
\begin{align}
    \mathcal{P}1\textit{-}2: \ \max _{\mathbf{P}, \mathbf{C}, \boldsymbol{\varphi}, \boldsymbol{\nu}_{c}, \atop \boldsymbol{\nu}_p, \boldsymbol{\chi_{c}}, \boldsymbol{\chi}_p} &{ \sum_{k\in\mathcal{K}} \sum_{n\in \mathcal{N}_k} \left(r_{k,n}^{c}+\varphi_{k,n}^{p}\right)} \qquad \quad \\
    \text { s.t.} \quad & (\textup{\ref{nonnegativity_of_common_rate}}), (\textup{\ref{constraint_sum_of_transmit_power}}), (\textup{\ref{SINR_approximate_common_rate}}), \notag \\ 
    & (\textup{\ref{SINR_approximate_private_rate}}),(\textup{\ref{minimum_achievable_sum_rate_approximate}}), (\textup{\ref{SCA_Taylor_rate_1}}), (\textup{\ref{SCA_Taylor_rate_2}}). \notag
\end{align}
\end{subequations}
For ease of notation, let $\rho = \sum_{k\in\mathcal{K}} \sum_{n\in \mathcal{N}_k} \left(r_{k,n}^{c}+\varphi_{k,n}^{p}\right)$, and $\rho^{\left[\ell\right]} = \sum_{k\in\mathcal{K}} \sum_{n\in \mathcal{N}_k} \left(r_{k,n}^{c \left[\ell\right]}+\varphi_{k,n}^{p \left[\ell\right]}\right)$. The detailed procedure for beamforming and common rate design is summarized in Algorithm \ref{SCA_algorithm}, where $\tau$ denotes the convergence tolerance. Since the solution in iteration $\ell-1$ remains feasible for iteration $\ell$, Algorithm \ref{SCA_algorithm} is guaranteed to converge. The convergence of the SCA method has been rigorously established in prior studies, such as \cite{palacios1982nonlinear}, and thus the proof in our paper is omitted here for brevity.

\begin{algorithm}[!t]
%	\normalem %	去除下划线
    \caption{Beamforming and Common Rate Control for RSMA-enabled LAE networks}
    \label{SCA_algorithm}
    \SetKwData{Left}{left}\SetKwData{This}{this}\SetKwData{Up}{up}
	% \SetKwData{Initialize}{Initialize}
 \SetKwFunction{FindCompress}{FindCompress}
	\SetKwInOut{Input}{Input}\SetKwInOut{Output}{Output}
        % \SetKwData{KwData}{Initialize}

	\Input{the convergence tolerance $\tau$, the iteration index $\ell\gets 0$, $\rho^{\left[\ell\right]} \gets 0$, $\mathbf{P}^{\left[\ell\right]}$, $\boldsymbol{\nu}_{c}^{\left[\ell\right]}$, $\boldsymbol{\nu}_p^{\left[\ell\right]}$,$\boldsymbol{\chi}_c^{\left[\ell\right]}$, $\boldsymbol{\chi}_p^{\left[\ell\right]}$.}

    \Repeat{$\left | \rho^{\left[\ell\right]}-\rho^{\left[\ell-1\right]} \right | < \tau$}{
